function makeRng(seed: number): Rng {
  let state = seed >>> 0;
  return {
    next: () => {
      state = (1664525 * state + 1013904223) >>> 0;
      return state / 0x100000000;
    },
    getState: () => state >>> 0,
    setState: (nextState: number) => {
      state = nextState >>> 0;
    }
  };
}

function round(value: number, decimals = 6): number {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function normalizeAngle(angle: number): number {
  return Math.atan2(Math.sin(angle), Math.cos(angle));
}

function yawForSegment(from: { x: number; z: number }, to: { x: number; z: number }): number {
  return normalizeAngle(-Math.atan2(to.z - from.z, to.x - from.x));
}

function interpolateYaw(startYaw: number, endYaw: number, alpha: number): number {
  return normalizeAngle(startYaw + normalizeAngle(endYaw - startYaw) * Math.min(1, Math.max(0, alpha)));
}

type FootprintPose = Pick<VehicleState, 'x' | 'z' | 'yaw'>;

type Axis2 = { x: number; z: number };

function footprintAxes(_yaw: number): [Axis2, Axis2] {
  // The real shuttle rotates visually at turns, but its clearance envelope is a
  // conservative square. Yaw must not change the physical collision footprint.
  const yaw = 0;
  const cos = Math.cos(yaw);
  const sin = Math.sin(yaw);
  return [
    { x: cos, z: sin },
    { x: -sin, z: cos }
  ];
}

function footprintCorners(
  vehicle: FootprintPose,
  config: ShuttleScenario['vehicles'],
  paddingM = 0
): Array<{ x: number; z: number }> {
  const [forward, lateral] = footprintAxes(vehicle.yaw);
  const halfSideM = Math.max(config.lengthM, config.widthM) / 2 + paddingM;
  return [
    { x: vehicle.x + forward.x * halfSideM + lateral.x * halfSideM, z: vehicle.z + forward.z * halfSideM + lateral.z * halfSideM },
    { x: vehicle.x + forward.x * halfSideM - lateral.x * halfSideM, z: vehicle.z + forward.z * halfSideM - lateral.z * halfSideM },
    { x: vehicle.x - forward.x * halfSideM + lateral.x * halfSideM, z: vehicle.z - forward.z * halfSideM + lateral.z * halfSideM },
    { x: vehicle.x - forward.x * halfSideM - lateral.x * halfSideM, z: vehicle.z - forward.z * halfSideM - lateral.z * halfSideM }
  ];
}

function projectionRange(corners: Array<{ x: number; z: number }>, axis: Axis2): { min: number; max: number } {
  const values = corners.map((corner) => corner.x * axis.x + corner.z * axis.z);
  return { min: Math.min(...values), max: Math.max(...values) };
}

function vehicleFootprintsOverlap(
  left: FootprintPose,
  right: FootprintPose,
  config: ShuttleScenario['vehicles']
): boolean {
  const leftCorners = footprintCorners(left, config);
  const rightCorners = footprintCorners(right, config);
  const axes = [...footprintAxes(left.yaw), ...footprintAxes(right.yaw)];
  return axes.every((axis) => {
    const leftRange = projectionRange(leftCorners, axis);
    const rightRange = projectionRange(rightCorners, axis);
    return leftRange.max + 1e-6 >= rightRange.min && rightRange.max + 1e-6 >= leftRange.min;
  });
}

function vehicleFootprintClearanceM(
  left: FootprintPose,
  right: FootprintPose,
  config: ShuttleScenario['vehicles']
): number {
  const leftCorners = footprintCorners(left, config, 0);
  const rightCorners = footprintCorners(right, config, 0);
  const axes = [...footprintAxes(left.yaw), ...footprintAxes(right.yaw)];
  let separationM = 0;
  for (const axis of axes) {
    const leftRange = projectionRange(leftCorners, axis);
    const rightRange = projectionRange(rightCorners, axis);
    const axisSeparationM = Math.max(rightRange.min - leftRange.max, leftRange.min - rightRange.max);
    if (axisSeparationM > 0) {
      separationM = Math.max(separationM, axisSeparationM);
    }
  }
  return separationM;
}

function stableJson(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map(stableJson).join(',')}]`;
  }

  return `{${Object.entries(value as Record<string, unknown>)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, child]) => `${JSON.stringify(key)}:${stableJson(child)}`)
    .join(',')}}`;
}

export function hashEventLog(events: EventLogEntry[]): string {
  const projected = events.map((event) => ({
    sequence: event.sequence,
    timeSec: round(event.timeSec, 3),
    eventType: event.eventType,
    vehicleId: event.vehicleId,
    taskId: event.taskId,
    loadId: event.loadId,
    fromNodeId: event.fromNodeId,
    toNodeId: event.toNodeId,
    reason: event.reason,
    details: event.details
  }));
  return createHash('sha256').update(stableJson(projected)).digest('hex');
}

export function hashScenario(scenario: ShuttleScenario): string {
  return createHash('sha256').update(stableJson(scenario)).digest('hex');
}

export function hashEngineSnapshot(snapshot: Omit<ShuttleEngineSnapshotV1, 'stateHash'> | ShuttleEngineSnapshotV1): string {
  const { stateHash: _stateHash, ...projected } = snapshot as ShuttleEngineSnapshotV1;
  return createHash('sha256').update(stableJson(projected)).digest('hex');
}

export function hashDeterministicReplayState(snapshot: ShuttleEngineSnapshotV1): string {
  return hashEngineSnapshot({
    ...snapshot,
    sessionId: 'deterministic-replay-session'
  });
}

function percentile(values: number[], p: number): number {
  if (values.length === 0) {
    return 0;
  }

  const sorted = [...values].sort((left, right) => left - right);
  const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return sorted[index] ?? 0;
}

const nodePositionCacheByScenario = new WeakMap<ShuttleScenario, Map<string, { x: number; y: number; z: number }>>();

function nodePosition(scenario: ShuttleScenario, nodeId: string): { x: number; y: number; z: number } {
  let cache = nodePositionCacheByScenario.get(scenario);
  if (!cache) {
    cache = new Map(scenario.layout.nodes.map((node) => [node.id, { x: node.x, y: node.y, z: node.z }]));
    nodePositionCacheByScenario.set(scenario, cache);
  }
  const node = cache.get(nodeId);
  if (!node) {
    throw new Error(`Unknown node ${nodeId}`);
  }
  return node;
}

function liftKindForNode(node: LayoutNode): LiftKind | null {
  if (node.type !== 'lift-blackbox') {
    return null;
  }
  return node.liftKind ?? null;
}

function buildEdgeKey(from: string, to: string): string {
  return `${from}->${to}`;
}

function reverseEdgeKey(from: string, to: string): string {
  return `${to}->${from}`;
}

export function calculateTravelTimeSec(distanceM: number, maxSpeedMps: number, accelerationMps2: number): number {
  const acceleration = Math.max(0.001, accelerationMps2);
  const speed = Math.max(0.001, maxSpeedMps);
  const accelerateDistanceM = (speed * speed) / (2 * acceleration);
  if (distanceM <= accelerateDistanceM * 2) {
    return 2 * Math.sqrt(distanceM / acceleration);
  }
  return (2 * speed) / acceleration + (distanceM - accelerateDistanceM * 2) / speed;
}

export function motionProfileAt(
  elapsedSec: number,
  distanceM: number,
  maxSpeedMps: number,
  accelerationMps2: number
): { distanceM: number; speedMps: number } {
  const acceleration = Math.max(0.001, accelerationMps2);
  const speed = Math.max(0.001, maxSpeedMps);
  const accelerateDistanceM = (speed * speed) / (2 * acceleration);
  if (distanceM <= accelerateDistanceM * 2) {
    const peakSpeedMps = Math.sqrt(distanceM * acceleration);
    const accelerateTimeSec = peakSpeedMps / acceleration;
    const totalTimeSec = accelerateTimeSec * 2;
    const elapsed = Math.min(totalTimeSec, Math.max(0, elapsedSec));
    if (elapsed <= accelerateTimeSec) {
      return {
        distanceM: 0.5 * acceleration * elapsed * elapsed,
        speedMps: acceleration * elapsed
      };
    }
    const decelElapsedSec = elapsed - accelerateTimeSec;
    return {
      distanceM: distanceM - 0.5 * acceleration * Math.max(0, totalTimeSec - elapsed) ** 2,
      speedMps: Math.max(0, peakSpeedMps - acceleration * decelElapsedSec)
    };
  }

  const accelerateTimeSec = speed / acceleration;
  const cruiseDistanceM = distanceM - accelerateDistanceM * 2;
  const cruiseTimeSec = cruiseDistanceM / speed;
  const totalTimeSec = accelerateTimeSec * 2 + cruiseTimeSec;
  const elapsed = Math.min(totalTimeSec, Math.max(0, elapsedSec));
  if (elapsed <= accelerateTimeSec) {
    return {
      distanceM: 0.5 * acceleration * elapsed * elapsed,
      speedMps: acceleration * elapsed
    };
  }
  if (elapsed <= accelerateTimeSec + cruiseTimeSec) {
    return {
      distanceM: accelerateDistanceM + (elapsed - accelerateTimeSec) * speed,
      speedMps: speed
    };
  }
  const remainingSec = totalTimeSec - elapsed;
  return {
    distanceM: distanceM - 0.5 * acceleration * remainingSec * remainingSec,
    speedMps: Math.max(0, acceleration * remainingSec)
  };
}

type LayoutNode = ShuttleScenario['layout']['nodes'][number];
type LiftKind = NonNullable<LayoutNode['liftKind']>;
type LayoutEdge = ShuttleScenario['layout']['edges'][number];
type LayoutZone = ShuttleScenario['layout']['zones'][number];
type DefaultLiftMode = 'balanced' | 'all-inbound';
type TopLiftColumnFlowMode = 'inbound' | 'outbound';

function storageNodeId(rowIndex: number, columnIndex: number): string {
  return `storage-r${String(rowIndex + 1).padStart(2, '0')}-c${String(columnIndex + 1).padStart(2, '0')}`;
}

function defaultStorageRowZs(profile: ShuttleLayoutGeometryProfile): number[] {
  const topRows = Array.from({ length: profile.storageRowsPerBank }, (_, rowIndex) =>
    round(-(profile.storageInnerRowZM + (profile.storageRowsPerBank - rowIndex - 1) * profile.storageCellPitchZM), 3)
  );
  const bottomRows = Array.from({ length: profile.storageRowsPerBank }, (_, rowIndex) =>
    round(profile.storageInnerRowZM + rowIndex * profile.storageCellPitchZM, 3)
  );
  return [...topRows, ...bottomRows];
}

function defaultStorageColumnXs(profile: ShuttleLayoutGeometryProfile): number[] {
  const storageColumns = profile.storageColumnsPerBay * profile.storageColumnBays;
  return Array.from({ length: storageColumns }, (_, columnIndex) =>
    round(
      profile.firstStorageXM +
        columnIndex * profile.storageCellPitchXM +
        Math.floor(columnIndex / profile.storageColumnsPerBay) * profile.storageBayGapXM,
      3
    )
  );
}

function defaultLiftPortalXs(columnXs: number[], rightSpineX: number, profile: ShuttleLayoutGeometryProfile): number[] {
  const portalXs: number[] = [];
  for (let bayIndex = 0; bayIndex < profile.storageColumnBays - 1; bayIndex += 1) {
    const leftColumnIndex = (bayIndex + 1) * profile.storageColumnsPerBay - 1;
    const rightColumnIndex = leftColumnIndex + 1;
    portalXs.push(round((columnXs[leftColumnIndex]! + columnXs[rightColumnIndex]!) / 2, 3));
  }
  portalXs.push(round((columnXs[columnXs.length - 1]! + rightSpineX) / 2, 3));
  return portalXs;
}

function mainLaneNodeId(lane: 'north' | 'south', index: number): string {
  return `main-${lane}-${String(index).padStart(2, '0')}`;
}

function columnAccessNodeId(level: 'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b', columnIndex: number): string {
  return `column-${level}-c${String(columnIndex + 1).padStart(2, '0')}`;
}

function moduleSpineNodeId(moduleIndex: number, level: 'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b'): string {
  return `module-${String(moduleIndex + 1).padStart(2, '0')}-spine-${level}`;
}

function moduleBoundarySpineNodeId(boundaryIndex: number, level: 'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b'): string {
  return `module-boundary-${String(boundaryIndex + 1).padStart(2, '0')}-spine-${level}`;
}

type TopLiftAisleLevel = 'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b';
const TOP_LIFT_AISLE_LEVELS: readonly TopLiftAisleLevel[] = ['top-a', 'top-b', 'middle', 'bottom-a', 'bottom-b'];
const topLiftAisleLevelCache = new Map<string, TopLiftAisleLevel | null>();

function isNonEmptyAsciiDigits(value: string): boolean {
  if (value.length === 0) {
    return false;
  }
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) {
      return false;
    }
  }
  return true;
}

function hasNumberedPrefix(value: string, prefix: string): boolean {
  return value.startsWith(prefix) && isNonEmptyAsciiDigits(value.slice(prefix.length));
}

function isTopLiftColumnAccessNodeId(nodeId: string): boolean {
  return topLiftAisleLevel(nodeId) !== null;
}

function topLiftAisleLevel(nodeId: string): TopLiftAisleLevel | null {
  if (topLiftAisleLevelCache.has(nodeId)) {
    return topLiftAisleLevelCache.get(nodeId) ?? null;
  }
  let level: TopLiftAisleLevel | null = null;
  if (nodeId.startsWith('column-')) {
    const columnSuffix = nodeId.slice('column-'.length);
    for (const level of TOP_LIFT_AISLE_LEVELS) {
      const columnPrefix = `${level}-c`;
      if (hasNumberedPrefix(columnSuffix, columnPrefix)) {
        topLiftAisleLevelCache.set(nodeId, level);
        return level;
      }
    }
    topLiftAisleLevelCache.set(nodeId, null);
    return null;
  }
  const spineMarker = '-spine-';
  const spineIndex = nodeId.lastIndexOf(spineMarker);
  if (spineIndex < 0) {
    topLiftAisleLevelCache.set(nodeId, null);
    return null;
  }
  const spinePrefix = nodeId.slice(0, spineIndex);
  if (!hasNumberedPrefix(spinePrefix, 'module-') && !hasNumberedPrefix(spinePrefix, 'module-boundary-')) {
    topLiftAisleLevelCache.set(nodeId, null);
    return null;
  }
  const candidateLevel = nodeId.slice(spineIndex + spineMarker.length);
  level = TOP_LIFT_AISLE_LEVELS.includes(candidateLevel as TopLiftAisleLevel) ? candidateLevel as TopLiftAisleLevel : null;
  topLiftAisleLevelCache.set(nodeId, level);
  return level;
}

function isTopLiftAisleLevelNodeId(nodeId: string, level: TopLiftAisleLevel): boolean {
  return topLiftAisleLevel(nodeId) === level;
}

function isTopLiftSpineLevelNodeId(nodeId: string, level: TopLiftAisleLevel): boolean {
  return topLiftAisleLevel(nodeId) === level && topLiftSpineKey(nodeId) !== null;
}

function topLiftSpineKey(nodeId: string): string | null {
  return /^(module-\d+|module-boundary-\d+)-spine-(?:top-a|top-b|middle|bottom-a|bottom-b)$/.exec(nodeId)?.[1] ?? null;
}

function liftBufferNodeId(liftNodeId: string, slotIndex: number): string {
  return `${liftNodeId}-buffer-${String(slotIndex).padStart(2, '0')}`;
}

function liftBufferAccessNodeId(liftNodeId: string): string {
  return `${liftNodeId}-buffer-access`;
}

function liftQueueAccessNodeId(liftNodeId: string): string {
  return `${liftNodeId}-queue-access`;
}

function liftQueueTailAccessNodeId(liftNodeId: string, slotIndex = 1): string {
  return `${liftNodeId}-queue-${String(slotIndex).padStart(2, '0')}-access`;
}

function liftQueueServiceExitNodeId(liftNodeId: string, slotIndex = 1): string {
  return `${liftNodeId}-queue-${String(slotIndex).padStart(2, '0')}-service-exit`;
}

function liftQueueTailEntryNodeId(liftNodeId: string, slotIndex = 1): string {
  return `${liftNodeId}-queue-${String(slotIndex).padStart(2, '0')}-entry-access`;
}

function liftQueueNodeId(liftNodeId: string, slotIndex = 1): string {
  return slotIndex <= 1
    ? `parking-${liftNodeId}-queue`
    : `parking-${liftNodeId}-queue-${String(slotIndex).padStart(2, '0')}`;
}

const topLiftQueueParkingSlotCache = new Map<string, { liftNodeId: string; slotIndex: number } | null>();

function liftBufferParentNodeId(nodeId: string): { liftNodeId: string; kind: LiftKind; slotIndex: number } | null {
  const match = /^(lift-\d{2}-(inbound|outbound))-buffer-(\d{2})$/.exec(nodeId);
  if (!match) {
    return null;
  }
  return {
    liftNodeId: match[1]!,
    kind: match[2]! as LiftKind,
    slotIndex: Number(match[3]!)
  };
}

function isTopLiftQueueParkingNodeId(nodeId: string): boolean {
  return /^parking-lift-\d{2}-(?:inbound|outbound)-queue(?:-\d{2})?$/.test(nodeId);
}

function topLiftQueueParkingSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
  if (topLiftQueueParkingSlotCache.has(nodeId)) {
    return topLiftQueueParkingSlotCache.get(nodeId) ?? null;
  }
  const match = /^parking-(lift-\d{2}-(?:inbound|outbound))-queue(?:-(\d{2}))?$/.exec(nodeId);
  if (!match) {
    topLiftQueueParkingSlotCache.set(nodeId, null);
    return null;
  }
  const slot = {
    liftNodeId: match[1]!,
    slotIndex: match[2] ? Number(match[2]) : 1
  };
  topLiftQueueParkingSlotCache.set(nodeId, slot);
  return slot;
}

function topLiftQueueAisleAccess(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
  const match = /^(lift-\d{2}-(?:inbound|outbound))-queue(?:-(\d{2}))?-access$/.exec(nodeId);
  if (!match) {
    return null;
  }
  return {
    liftNodeId: match[1]!,
    slotIndex: match[2] ? Number(match[2]) : 0
  };
}

function topLiftQueueEntrySlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
  const match = /^(lift-\d{2}-(?:inbound|outbound))-queue-(\d{2})-entry-access$/.exec(nodeId);
  return match ? { liftNodeId: match[1]!, slotIndex: Number(match[2]!) } : null;
}

function topLiftQueueServiceSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
  const match = /^(lift-\d{2}-(?:inbound|outbound))-queue-(\d{2})-service-exit$/.exec(nodeId);
  return match ? { liftNodeId: match[1]!, slotIndex: Number(match[2]!) } : null;
}

export type LiftWorkcellRouteFlow =
  | 'inbound-empty-approach'
  | 'inbound-loaded-departure'
  | 'outbound-loaded-approach'
  | 'outbound-clear-through';

export type LiftWorkcellRouteContractViolation = {
  code:
    | 'mixed-lift-workcell'
    | 'wrong-lift-workcell'
    | 'wrong-flow-kind'
    | 'inbound-empty-entered-conveyor'
    | 'inbound-empty-service-not-terminal'
    | 'inbound-empty-service-without-entry'
    | 'inbound-loaded-reentered-queue'
    | 'inbound-loaded-left-service-without-entry'
    | 'inbound-loaded-service-reversal'
    | 'outbound-loaded-entered-conveyor'
    | 'outbound-loaded-service-not-terminal'
    | 'outbound-loaded-service-without-entry'
    | 'outbound-clear-start'
    | 'outbound-clear-entered-conveyor'
    | 'outbound-clear-service-order'
    | 'outbound-clear-left-without-entry';
  nodeId: string;
  index: number;
  message: string;
};

type TopLiftWorkcellNodeRole =
  | 'lift'
  | 'throat'
  | 'buffer-access'
  | 'buffer'
  | 'queue-access'
  | 'queue-pocket'
  | 'service'
  | 'entry';

type TopLiftWorkcellNodeInfo = {
  nodeId: string;
  liftNodeId: string;
  kind: LiftKind;
  role: TopLiftWorkcellNodeRole;
  slotIndex: number | null;
};

function topLiftKindFromLiftNodeId(liftNodeId: string): LiftKind | null {
  return /^lift-\d{2}-(inbound|outbound)$/.exec(liftNodeId)?.[1] as LiftKind | null;
}

function topLiftWorkcellNodeInfo(nodeId: string): TopLiftWorkcellNodeInfo | null {
  const queueParking = topLiftQueueParkingSlot(nodeId);
  if (queueParking) {
    const kind = topLiftKindFromLiftNodeId(queueParking.liftNodeId);
    return kind ? { nodeId, liftNodeId: queueParking.liftNodeId, kind, role: 'queue-pocket', slotIndex: queueParking.slotIndex } : null;
  }
  const queueAccess = topLiftQueueAisleAccess(nodeId);
  if (queueAccess) {
    const kind = topLiftKindFromLiftNodeId(queueAccess.liftNodeId);
    return kind ? { nodeId, liftNodeId: queueAccess.liftNodeId, kind, role: 'queue-access', slotIndex: queueAccess.slotIndex } : null;
  }
  const queueEntry = topLiftQueueEntrySlot(nodeId);
  if (queueEntry) {
    const kind = topLiftKindFromLiftNodeId(queueEntry.liftNodeId);
    return kind ? { nodeId, liftNodeId: queueEntry.liftNodeId, kind, role: 'entry', slotIndex: queueEntry.slotIndex } : null;
  }
  const queueService = topLiftQueueServiceSlot(nodeId);
  if (queueService) {
    const kind = topLiftKindFromLiftNodeId(queueService.liftNodeId);
    return kind ? { nodeId, liftNodeId: queueService.liftNodeId, kind, role: 'service', slotIndex: queueService.slotIndex } : null;
  }
  const buffer = liftBufferParentNodeId(nodeId);
  if (buffer) {
    return { nodeId, liftNodeId: buffer.liftNodeId, kind: buffer.kind, role: 'buffer', slotIndex: buffer.slotIndex };
  }
  const direct = /^(lift-\d{2}-(inbound|outbound))(?:-(throat|buffer-access|queue-access))?$/.exec(nodeId);
  if (!direct) {
    return null;
  }
  const suffix = direct[3] ?? '';
  const role: TopLiftWorkcellNodeRole =
    suffix === 'throat' ? 'throat' :
    suffix === 'buffer-access' ? 'buffer-access' :
    suffix === 'queue-access' ? 'queue-access' :
    'lift';
  return {
    nodeId,
    liftNodeId: direct[1]!,
    kind: direct[2]! as LiftKind,
    role,
    slotIndex: null
  };
}

export function topLiftWorkcellRouteContractViolations(
  routeNodeIds: string[],
  options: {
    flow: LiftWorkcellRouteFlow;
    expectedLiftNodeId?: string | null;
    expectedKind?: LiftKind | null;
  }
): LiftWorkcellRouteContractViolation[] {
  const workcellEntries = routeNodeIds
    .map((nodeId, index) => {
      const info = topLiftWorkcellNodeInfo(nodeId);
      return info ? { ...info, index } : null;
    })
    .filter((entry): entry is TopLiftWorkcellNodeInfo & { index: number } => entry !== null);
  if (workcellEntries.length === 0) {
    return [];
  }

  const violations: LiftWorkcellRouteContractViolation[] = [];
  const addViolation = (
    code: LiftWorkcellRouteContractViolation['code'],
    entry: TopLiftWorkcellNodeInfo & { index: number },
    message: string
  ): void => {
    violations.push({ code, nodeId: entry.nodeId, index: entry.index, message });
  };

  const liftNodeIds = new Set(workcellEntries.map((entry) => entry.liftNodeId));
  if (liftNodeIds.size > 1) {
    addViolation('mixed-lift-workcell', workcellEntries[0]!, 'Route touches more than one lift workcell.');
  }
  for (const entry of workcellEntries) {
    if (options.expectedLiftNodeId && entry.liftNodeId !== options.expectedLiftNodeId) {
      addViolation('wrong-lift-workcell', entry, `Route touches ${entry.liftNodeId}, but task owns ${options.expectedLiftNodeId}.`);
    }
    if (options.expectedKind && entry.kind !== options.expectedKind) {
      addViolation('wrong-flow-kind', entry, `Route touches ${entry.kind} workcell during ${options.expectedKind} flow.`);
    }
  }

  const conveyorRoles = new Set<TopLiftWorkcellNodeRole>(['lift', 'throat', 'buffer-access', 'buffer']);
  const queueRoles = new Set<TopLiftWorkcellNodeRole>(['queue-access', 'queue-pocket', 'buffer-access', 'buffer', 'lift', 'throat']);
  const serviceEntries = workcellEntries.filter((entry) => entry.role === 'service');
  const firstService = serviceEntries[0] ?? null;
  const lastService = serviceEntries.at(-1) ?? null;
  const entryBeforeService = (service: TopLiftWorkcellNodeInfo & { index: number }): boolean => {
    if (service.index === 0) {
      return true;
    }
    const previous = topLiftWorkcellNodeInfo(routeNodeIds[service.index - 1]!);
    return previous?.liftNodeId === service.liftNodeId && previous.role === 'entry';
  };
  const hasEntryAfterServiceBeforeExit = (service: TopLiftWorkcellNodeInfo & { index: number }): boolean => {
    const laterWorkcellEntries = workcellEntries.filter((entry) => entry.index > service.index);
    const firstNonService = laterWorkcellEntries.find((entry) => entry.role !== 'service');
    return firstNonService?.role === 'entry';
  };

  if (options.flow === 'inbound-empty-approach') {
    for (const entry of workcellEntries) {
      if (conveyorRoles.has(entry.role)) {
        addViolation('inbound-empty-entered-conveyor', entry, 'Empty inbound approach may not enter lift/conveyor equipment.');
      }
    }
    if (lastService && lastService.index !== routeNodeIds.length - 1) {
      addViolation('inbound-empty-service-not-terminal', lastService, 'Empty inbound approach must stop at pickup service point.');
    }
    if (firstService && !entryBeforeService(firstService)) {
      addViolation('inbound-empty-service-without-entry', firstService, 'Empty inbound approach must enter pickup service point from its entry pad.');
    }
  }

  if (options.flow === 'inbound-loaded-departure' && firstService) {
    const servicesAfterFirst = serviceEntries.filter((entry) => entry.index > firstService.index);
    let previousSlotIndex = firstService.slotIndex ?? 0;
    for (const service of servicesAfterFirst) {
      if ((service.slotIndex ?? 0) <= previousSlotIndex) {
        addViolation('inbound-loaded-service-reversal', service, 'Inbound loaded departure may only clear forward through service slots.');
      }
      previousSlotIndex = service.slotIndex ?? previousSlotIndex;
    }
    for (const entry of workcellEntries.filter((candidate) => candidate.index > firstService.index)) {
      if (queueRoles.has(entry.role)) {
        addViolation('inbound-loaded-reentered-queue', entry, 'Inbound loaded departure may not reverse into queue or conveyor space after pickup.');
      }
    }
    if (!hasEntryAfterServiceBeforeExit(firstService)) {
      addViolation('inbound-loaded-left-service-without-entry', firstService, 'Inbound loaded departure must leave service through an entry/clearance pad.');
    }
  }

  if (options.flow === 'outbound-loaded-approach') {
    const firstWorkcellEntry = workcellEntries[0] ?? null;
    const queuePreludeAllowed = Boolean(
      firstWorkcellEntry &&
      firstWorkcellEntry.index === 0 &&
      (firstWorkcellEntry.role === 'queue-pocket' || firstWorkcellEntry.role === 'queue-access')
    );
    for (const entry of workcellEntries) {
      if (conveyorRoles.has(entry.role)) {
        addViolation('outbound-loaded-entered-conveyor', entry, 'Loaded outbound approach may not enter conveyor or queue pocket space.');
      }
      if (entry.role === 'queue-access' || entry.role === 'queue-pocket') {
        const beforeService = !firstService || entry.index < firstService.index;
        if (!queuePreludeAllowed || !beforeService) {
          addViolation('outbound-loaded-entered-conveyor', entry, 'Loaded outbound approach may not enter conveyor or queue pocket space.');
        }
      }
    }
    if (lastService && lastService.index !== routeNodeIds.length - 1) {
      addViolation('outbound-loaded-service-not-terminal', lastService, 'Loaded outbound approach must terminate at the dropoff service point.');
    }
    if (firstService && !entryBeforeService(firstService)) {
      addViolation('outbound-loaded-service-without-entry', firstService, 'Loaded outbound approach must enter dropoff service point from its entry pad.');
    }
  }

  if (options.flow === 'outbound-clear-through') {
    const first = workcellEntries[0]!;
    if (first.index !== 0 || first.role !== 'service') {
      addViolation('outbound-clear-start', first, 'Outbound clear-through route must start at the dropoff service point.');
    }
    for (const entry of workcellEntries) {
      if (conveyorRoles.has(entry.role) || entry.role === 'queue-access' || entry.role === 'queue-pocket') {
        addViolation('outbound-clear-entered-conveyor', entry, 'Outbound clear-through may not enter conveyor or queue pocket space.');
      }
    }
    let previousSlotIndex = serviceEntries[0]?.slotIndex ?? 0;
    for (const service of serviceEntries.slice(1)) {
      if ((service.slotIndex ?? 0) <= previousSlotIndex) {
        addViolation('outbound-clear-service-order', service, 'Outbound clear-through must move forward through service slots.');
      }
      previousSlotIndex = service.slotIndex ?? previousSlotIndex;
    }
    if (firstService && !hasEntryAfterServiceBeforeExit(firstService)) {
      addViolation('outbound-clear-left-without-entry', firstService, 'Outbound clear-through must exit service through a clearance entry pad.');
    }
  }

  return violations;
}

function createTopLiftColumnLayout(
  profile: ShuttleLayoutGeometryProfile,
  _liftMode: DefaultLiftMode = 'balanced'
): ShuttleScenario['layout'] {
  const rowsPerZone = profile.storageRowsPerZone;
  const columnsPerZone = profile.storageColumnsPerZone;
  const liftPairCount = profile.liftPairCount;
  const rowsPerModule = rowsPerZone * 2;
  const columnsPerModule = columnsPerZone * 2;
  const totalRows = rowsPerModule;
  const totalColumns = columnsPerModule * liftPairCount;
  const topAisleZM = 0;
  const topLaneSpacingZM = Math.abs(profile.mainLaneSouthZM - profile.mainLaneNorthZM);
  const topLaneAZM = round(topAisleZM - topLaneSpacingZM / 2, 3);
  const topLaneBZM = round(topAisleZM + topLaneSpacingZM / 2, 3);
  const upperFirstRowZ = round(topLaneBZM + profile.storageCellPitchZM, 3);
  const upperLastRowZ = round(upperFirstRowZ + (rowsPerZone - 1) * profile.storageCellPitchZM, 3);
  const middleAisleZ = round(upperLastRowZ + profile.storageCellPitchZM, 3);
  const lowerFirstRowZ = round(middleAisleZ + profile.storageCellPitchZM, 3);
  const lowerLastRowZ = round(lowerFirstRowZ + (rowsPerZone - 1) * profile.storageCellPitchZM, 3);
  const bottomLaneAZM = round(lowerLastRowZ + profile.storageCellPitchZM, 3);
  const bottomLaneBZM = round(bottomLaneAZM + topLaneSpacingZM, 3);
  const liftServiceOffsetZM = Math.max(profile.storageCellPitchZM, topLaneSpacingZM * 0.75);
  const topLiftZ = round(topLaneAZM - profile.liftStandoffZM, 3);
  const topLiftServiceLaneZM = round(topLaneAZM - liftServiceOffsetZM, 3);
  const bottomLiftZ = round(bottomLaneBZM + profile.liftStandoffZM, 3);
  const bottomLiftServiceLaneZM = round(bottomLaneBZM + liftServiceOffsetZM, 3);
  const liftWorkcellSlotPitchZM = round(Math.max(profile.storageCellPitchZM, topLaneSpacingZM), 3);
  const columnXs = Array.from({ length: totalColumns }, (_, columnIndex) => {
    return round(
      profile.firstStorageXM +
        columnIndex * profile.storageCellPitchXM +
        Math.floor(columnIndex / columnsPerZone) * profile.storageBayGapXM,
      3
    );
  });
  const rowZ = (rowIndex: number): number => rowIndex < rowsPerZone
    ? round(upperFirstRowZ + rowIndex * profile.storageCellPitchZM, 3)
    : round(lowerFirstRowZ + (rowIndex - rowsPerZone) * profile.storageCellPitchZM, 3);

  const nodes: LayoutNode[] = [];
  const addNode = (node: LayoutNode): void => {
    nodes.push(node);
  };

  for (let columnIndex = 0; columnIndex < totalColumns; columnIndex += 1) {
    const x = columnXs[columnIndex]!;
    addNode({ id: columnAccessNodeId('top-a', columnIndex), type: 'intersection', x, y: 0, z: topLaneAZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    addNode({ id: columnAccessNodeId('top-b', columnIndex), type: 'intersection', x, y: 0, z: topLaneBZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    addNode({ id: columnAccessNodeId('middle', columnIndex), type: 'intersection', x, y: 0, z: middleAisleZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    addNode({ id: columnAccessNodeId('bottom-a', columnIndex), type: 'intersection', x, y: 0, z: bottomLaneAZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    addNode({ id: columnAccessNodeId('bottom-b', columnIndex), type: 'intersection', x, y: 0, z: bottomLaneBZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
  }

  for (let rowIndex = 0; rowIndex < totalRows; rowIndex += 1) {
    const rowLabel = String(rowIndex + 1).padStart(2, '0');
    const z = rowZ(rowIndex);
    addNode({ id: `left-row-${rowLabel}`, type: 'intersection', x: round(columnXs[0]! - profile.sideClearanceXM, 3), y: 0, z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    addNode({ id: `right-row-${rowLabel}`, type: 'intersection', x: round(columnXs[totalColumns - 1]! + profile.sideClearanceXM, 3), y: 0, z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
    for (let columnIndex = 0; columnIndex < totalColumns; columnIndex += 1) {
      addNode({
        id: storageNodeId(rowIndex, columnIndex),
        type: 'storage',
        x: columnXs[columnIndex]!,
        y: 0,
        z,
        noStop: false,
        noParking: false,
        capacity: 1,
        allowedDirections: []
      });
    }
  }

  const liftNodes: Array<{
    id: string;
    x: number;
    z: number;
    kind: LiftKind;
    throatId: string;
    bufferAccessId: string;
    bufferNodeIds: string[];
    queueAccessId: string | null;
    queueAccessNodeIds: string[];
    queueServiceExitNodeIds: string[];
    queueEntryNodeIds: string[];
    queuePickupAccessId: string | null;
    queueNodeId: string | null;
    queueNodeIds: string[];
  }> = [];
  const moduleSpineNodeIds: Record<'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b', string[]> = {
    'top-a': [],
    'top-b': [],
    middle: [],
    'bottom-a': [],
    'bottom-b': []
  };
  const moduleBoundarySpineNodeIds: Record<'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b', string[]> = {
    'top-a': [],
    'top-b': [],
    middle: [],
    'bottom-a': [],
    'bottom-b': []
  };
  const spineLevels = [
    { level: 'top-a' as const, z: topLaneAZM },
    { level: 'top-b' as const, z: topLaneBZM },
    { level: 'middle' as const, z: middleAisleZ },
    { level: 'bottom-a' as const, z: bottomLaneAZM },
    { level: 'bottom-b' as const, z: bottomLaneBZM }
  ];
  for (let moduleIndex = 0; moduleIndex < liftPairCount; moduleIndex += 1) {
    const moduleFirstColumn = moduleIndex * columnsPerModule;
    const leftZoneEndX = columnXs[moduleFirstColumn + columnsPerZone - 1]!;
    const rightZoneStartX = columnXs[moduleFirstColumn + columnsPerZone]!;
    const moduleSpineX = round((leftZoneEndX + rightZoneStartX) / 2, 3);
    for (const spine of spineLevels) {
      const id = moduleSpineNodeId(moduleIndex, spine.level);
      addNode({ id, type: 'intersection', x: moduleSpineX, y: 0, z: spine.z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
      moduleSpineNodeIds[spine.level].push(id);
    }
    const liftNumber = moduleIndex + 1;
    const portDefinitions = [
      {
        suffix: 'inbound',
        kind: 'inbound' as const,
        x: round(moduleSpineX - profile.liftPortSpacingXM, 3),
        z: topLiftZ,
        serviceLaneZ: topLiftServiceLaneZM,
        workcellOuterDirectionZ: -1
      },
      {
        suffix: 'outbound',
        kind: 'outbound' as const,
        x: round(moduleSpineX + profile.liftPortSpacingXM, 3),
        z: bottomLiftZ,
        serviceLaneZ: bottomLiftServiceLaneZM,
        workcellOuterDirectionZ: 1
      }
    ];
    for (const port of portDefinitions) {
      const id = `lift-${String(liftNumber).padStart(2, '0')}-${port.suffix}`;
      const throatId = `${id}-throat`;
      const bufferAccessId = liftBufferAccessNodeId(id);
      const bufferNodeIds: string[] = [];
      const queueAccessId = liftQueueAccessNodeId(id);
      const queuePickupAccessId: string | null = null;
      const queueNodeId = liftQueueNodeId(id);
      const queueNodeIds = Array.from({ length: 3 }, (_, index) => liftQueueNodeId(id, index + 1));
      const queueAccessNodeIds = Array.from({ length: 3 }, (_, index) => liftQueueTailAccessNodeId(id, index + 1));
      const queueServiceExitNodeIds = Array.from({ length: 3 }, (_, index) => liftQueueServiceExitNodeId(id, index + 1));
      const queueEntryNodeIds = Array.from({ length: 3 }, (_, index) => liftQueueTailEntryNodeId(id, index + 1));
      addNode({ id, type: 'lift-blackbox', liftKind: port.kind, x: port.x, y: 0, z: port.z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
      addNode({ id: throatId, type: 'intersection', x: port.x, y: 0, z: port.serviceLaneZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
      const conveyorSideX = round(port.x + (port.kind === 'inbound' ? profile.liftPortSpacingXM : -profile.liftPortSpacingXM), 3);
      const conveyorStepZM = round((port.serviceLaneZ - port.z) / Math.max(1, profile.liftBufferCapacity), 3);
      addNode({ id: bufferAccessId, type: 'intersection', x: conveyorSideX, y: 0, z: port.serviceLaneZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
      if (queueAccessId && queueNodeId) {
        const queueSlotPitchXM = Math.max(profile.storageCellPitchXM, profile.liftPortSpacingXM);
        const queueDirection = port.kind === 'inbound' ? 1 : -1;
        const queueAccessX = round(conveyorSideX + queueSlotPitchXM * queueDirection, 3);
        const queuePocketOffsetZM = round(Math.max(profile.storageCellPitchZM * 0.5, topLaneSpacingZM * 0.375), 3);
        addNode({ id: queueAccessId, type: 'intersection', x: queueAccessX, y: 0, z: port.serviceLaneZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
        for (let queueIndex = 0; queueIndex < queueNodeIds.length; queueIndex += 1) {
          const queueSlotZ = round(port.serviceLaneZ + port.workcellOuterDirectionZ * liftWorkcellSlotPitchZM * queueIndex, 3);
          const queueEntryTargetX = round(queueAccessX + queueSlotPitchXM * queueDirection, 3);
          const queueEntryX = columnXs
            .map((x, columnIndex) => ({ x, columnIndex }))
            .sort((left, right) =>
              Math.abs(left.x - queueEntryTargetX) - Math.abs(right.x - queueEntryTargetX) ||
              left.columnIndex - right.columnIndex
            )[0]!.x;
          const queuePocketZ = round(queueSlotZ + port.workcellOuterDirectionZ * queuePocketOffsetZM, 3);
          const queueParkingX = round(queueEntryX + queueSlotPitchXM * queueDirection, 3);
          addNode({
            id: queueAccessNodeIds[queueIndex]!,
            type: 'intersection',
            x: queueEntryX,
            y: 0,
            z: queuePocketZ,
            noStop: true,
            noParking: true,
            capacity: 1,
            allowedDirections: []
          });
          addNode({
            id: queueNodeIds[queueIndex]!,
            type: 'parking',
            x: queueParkingX,
            y: 0,
            z: queuePocketZ,
            noStop: true,
            noParking: true,
            capacity: 1,
            allowedDirections: []
          });
          addNode({
            id: queueServiceExitNodeIds[queueIndex]!,
            type: 'intersection',
            x: conveyorSideX,
            y: 0,
            z: queueSlotZ,
            noStop: true,
            noParking: true,
            capacity: 1,
            allowedDirections: []
          });
          addNode({
            id: queueEntryNodeIds[queueIndex]!,
            type: 'intersection',
            x: queueEntryX,
            y: 0,
            z: queueSlotZ,
            noStop: true,
            noParking: true,
            capacity: 1,
            allowedDirections: []
          });
        }
      }
      for (let bufferIndex = 1; bufferIndex <= profile.liftBufferCapacity; bufferIndex += 1) {
        const bufferId = liftBufferNodeId(id, bufferIndex);
        bufferNodeIds.push(bufferId);
        addNode({
          id: bufferId,
          type: port.kind,
          x: conveyorSideX,
          y: 0,
          z: round(port.z + conveyorStepZM * (bufferIndex - 1), 3),
          noStop: true,
          noParking: true,
          capacity: 1,
          allowedDirections: []
        });
      }
      liftNodes.push({ id, x: port.x, z: port.z, kind: port.kind, throatId, bufferAccessId, bufferNodeIds, queueAccessId, queueAccessNodeIds, queueServiceExitNodeIds, queueEntryNodeIds, queuePickupAccessId, queueNodeId, queueNodeIds });
    }
  }
  for (let boundaryIndex = 0; boundaryIndex < liftPairCount - 1; boundaryIndex += 1) {
    const leftColumnIndex = (boundaryIndex + 1) * columnsPerModule - 1;
    const rightColumnIndex = leftColumnIndex + 1;
    const boundarySpineX = round((columnXs[leftColumnIndex]! + columnXs[rightColumnIndex]!) / 2, 3);
    for (const spine of spineLevels) {
      const id = moduleBoundarySpineNodeId(boundaryIndex, spine.level);
      addNode({ id, type: 'intersection', x: boundarySpineX, y: 0, z: spine.z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
      moduleBoundarySpineNodeIds[spine.level].push(id);
    }
  }

  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  const edges: LayoutEdge[] = [];
  const addEdge = (id: string, from: string, to: string, conflictGroup: string, directionMode: 'oneWay' | 'twoWay' = 'twoWay') => {
    const fromNode = nodesById.get(from);
    const toNode = nodesById.get(to);
    if (!fromNode || !toNode) {
      throw new Error(`Top-lift column layout edge ${id} references an unknown node.`);
    }
    let lengthM = round(Math.abs(toNode.x - fromNode.x) + Math.abs(toNode.z - fromNode.z), 3);
    if (lengthM <= 0) {
      if (!id.includes('standby-queue-entry-drop') && !conflictGroup.includes('standby-queue-entry-drop')) {
        return;
      }
      lengthM = 0.001;
    }
    edges.push({
      id,
      from,
      to,
      lengthM,
      directionMode,
      reservationType: 'edge',
      conflictGroup,
      noParking: true
    });
  };

  const connectHorizontal = (
    level: 'top-a' | 'top-b' | 'middle' | 'bottom-a' | 'bottom-b',
    extraNodeIds: string[],
    groupPrefix: string,
    laneDirection: 'twoWay' | 'leftToRight' | 'rightToLeft' = 'twoWay'
  ): void => {
    const nodeIds = [
      ...Array.from({ length: totalColumns }, (_, columnIndex) => columnAccessNodeId(level, columnIndex)),
      ...extraNodeIds
    ]
      .filter((id, index, ids) => ids.indexOf(id) === index)
      .sort((left, right) => nodesById.get(left)!.x - nodesById.get(right)!.x || left.localeCompare(right));
    const groups: string[][] = [];
    for (const nodeId of nodeIds) {
      const previousGroup = groups.at(-1);
      const previousNodeId = previousGroup?.[0];
      if (previousNodeId && Math.abs(nodesById.get(previousNodeId)!.x - nodesById.get(nodeId)!.x) <= 1e-6) {
        previousGroup.push(nodeId);
      } else {
        groups.push([nodeId]);
      }
    }
    for (let groupIndex = 1; groupIndex < groups.length; groupIndex += 1) {
      const leftGroup = groups[groupIndex - 1]!;
      const rightGroup = groups[groupIndex]!;
      for (const leftNodeId of leftGroup) {
        for (const rightNodeId of rightGroup) {
          if (laneDirection === 'rightToLeft') {
            addEdge(`${rightNodeId}-${leftNodeId}`, rightNodeId, leftNodeId, `${groupPrefix}-${String(groupIndex).padStart(2, '0')}`, 'oneWay');
          } else {
            addEdge(
              `${leftNodeId}-${rightNodeId}`,
              leftNodeId,
              rightNodeId,
              `${groupPrefix}-${String(groupIndex).padStart(2, '0')}`,
              laneDirection === 'leftToRight' ? 'oneWay' : 'twoWay'
            );
          }
        }
      }
    }
  };

  connectHorizontal('top-a', [...moduleSpineNodeIds['top-a'], ...moduleBoundarySpineNodeIds['top-a']], 'top-double-aisle-a');
  connectHorizontal('top-a', [...moduleSpineNodeIds['top-a'], ...moduleBoundarySpineNodeIds['top-a']], 'top-double-aisle-a-base');
  connectHorizontal('top-b', [...moduleSpineNodeIds['top-b'], ...moduleBoundarySpineNodeIds['top-b']], 'top-double-aisle-b');
  connectHorizontal('middle', [...moduleSpineNodeIds.middle, ...moduleBoundarySpineNodeIds.middle], 'middle-aisle');
  connectHorizontal('bottom-a', [...moduleSpineNodeIds['bottom-a'], ...moduleBoundarySpineNodeIds['bottom-a']], 'bottom-double-aisle-a');
  connectHorizontal('bottom-b', [...moduleSpineNodeIds['bottom-b'], ...moduleBoundarySpineNodeIds['bottom-b']], 'bottom-double-aisle-b');

  for (let moduleIndex = 0; moduleIndex < liftPairCount; moduleIndex += 1) {
    const topA = moduleSpineNodeId(moduleIndex, 'top-a');
    const topB = moduleSpineNodeId(moduleIndex, 'top-b');
    const middle = moduleSpineNodeId(moduleIndex, 'middle');
    const bottomA = moduleSpineNodeId(moduleIndex, 'bottom-a');
    const bottomB = moduleSpineNodeId(moduleIndex, 'bottom-b');
    const spineLabel = `module-spine-${String(moduleIndex + 1).padStart(2, '0')}`;
    addEdge(`${topA}-${topB}`, topA, topB, `${spineLabel}-top-transfer`);
    addEdge(`${topB}-${middle}`, topB, middle, `${spineLabel}-upper-vertical`);
    addEdge(`${middle}-${bottomA}`, middle, bottomA, `${spineLabel}-lower-vertical`);
    addEdge(`${bottomA}-${bottomB}`, bottomA, bottomB, `${spineLabel}-bottom-transfer`);
  }
  for (let boundaryIndex = 0; boundaryIndex < liftPairCount - 1; boundaryIndex += 1) {
    const topA = moduleBoundarySpineNodeId(boundaryIndex, 'top-a');
    const topB = moduleBoundarySpineNodeId(boundaryIndex, 'top-b');
    const middle = moduleBoundarySpineNodeId(boundaryIndex, 'middle');
    const bottomA = moduleBoundarySpineNodeId(boundaryIndex, 'bottom-a');
    const bottomB = moduleBoundarySpineNodeId(boundaryIndex, 'bottom-b');
    const spineLabel = `module-boundary-spine-${String(boundaryIndex + 1).padStart(2, '0')}`;
    addEdge(`${topA}-${topB}`, topA, topB, `${spineLabel}-top-transfer`);
    addEdge(`${topB}-${middle}`, topB, middle, `${spineLabel}-upper-vertical`);
    addEdge(`${middle}-${bottomA}`, middle, bottomA, `${spineLabel}-lower-vertical`);
    addEdge(`${bottomA}-${bottomB}`, bottomA, bottomB, `${spineLabel}-bottom-transfer`);
  }

  for (let columnIndex = 0; columnIndex < totalColumns; columnIndex += 1) {
    addEdge(`${columnAccessNodeId('top-a', columnIndex)}-${columnAccessNodeId('top-b', columnIndex)}`, columnAccessNodeId('top-a', columnIndex), columnAccessNodeId('top-b', columnIndex), `top-lane-transfer-c${String(columnIndex + 1).padStart(2, '0')}`);
    addEdge(`${columnAccessNodeId('bottom-a', columnIndex)}-${columnAccessNodeId('bottom-b', columnIndex)}`, columnAccessNodeId('bottom-a', columnIndex), columnAccessNodeId('bottom-b', columnIndex), `bottom-lane-transfer-c${String(columnIndex + 1).padStart(2, '0')}`);
    addEdge(`${columnAccessNodeId('top-b', columnIndex)}-${storageNodeId(0, columnIndex)}`, columnAccessNodeId('top-b', columnIndex), storageNodeId(0, columnIndex), `storage-column-upper-c${String(columnIndex + 1).padStart(2, '0')}`);
    addEdge(`${columnAccessNodeId('middle', columnIndex)}-${storageNodeId(rowsPerZone - 1, columnIndex)}`, columnAccessNodeId('middle', columnIndex), storageNodeId(rowsPerZone - 1, columnIndex), `storage-column-upper-c${String(columnIndex + 1).padStart(2, '0')}`);
    addEdge(`${columnAccessNodeId('middle', columnIndex)}-${storageNodeId(rowsPerZone, columnIndex)}`, columnAccessNodeId('middle', columnIndex), storageNodeId(rowsPerZone, columnIndex), `storage-column-lower-c${String(columnIndex + 1).padStart(2, '0')}`);
    addEdge(`${columnAccessNodeId('bottom-a', columnIndex)}-${storageNodeId(totalRows - 1, columnIndex)}`, columnAccessNodeId('bottom-a', columnIndex), storageNodeId(totalRows - 1, columnIndex), `storage-column-lower-c${String(columnIndex + 1).padStart(2, '0')}`);
    for (let rowIndex = 1; rowIndex < rowsPerZone; rowIndex += 1) {
      addEdge(`${storageNodeId(rowIndex - 1, columnIndex)}-${storageNodeId(rowIndex, columnIndex)}`, storageNodeId(rowIndex - 1, columnIndex), storageNodeId(rowIndex, columnIndex), `storage-column-upper-c${String(columnIndex + 1).padStart(2, '0')}`);
      addEdge(`${storageNodeId(rowsPerZone + rowIndex - 1, columnIndex)}-${storageNodeId(rowsPerZone + rowIndex, columnIndex)}`, storageNodeId(rowsPerZone + rowIndex - 1, columnIndex), storageNodeId(rowsPerZone + rowIndex, columnIndex), `storage-column-lower-c${String(columnIndex + 1).padStart(2, '0')}`);
    }
  }

  for (const lift of liftNodes) {
    addEdge(`${lift.id}-${lift.throatId}`, lift.id, lift.throatId, `${lift.id}-buffer-throat`);
    const pickupBufferNodeId = lift.bufferNodeIds.at(-1);
    if (pickupBufferNodeId) {
      addEdge(`${lift.bufferAccessId}-${pickupBufferNodeId}`, lift.bufferAccessId, pickupBufferNodeId, `${lift.id}-conveyor-pickup`);
    }
    if (lift.queueAccessId && lift.queueNodeId && pickupBufferNodeId) {
      addEdge(`${lift.bufferAccessId}-${lift.queueAccessId}`, lift.bufferAccessId, lift.queueAccessId, `${lift.id}-standby-queue-access`);
      let previousQueueAccessNodeId: string | null = null;
      let previousQueueNodeId: string | null = null;
      let previousServiceExitNodeId = lift.bufferAccessId;
      for (let queueIndex = 0; queueIndex < lift.queueNodeIds.length; queueIndex += 1) {
        const queueAccessNodeId = lift.queueAccessNodeIds[queueIndex];
        const queueServiceExitNodeId = lift.queueServiceExitNodeIds[queueIndex];
        const queueNodeId = lift.queueNodeIds[queueIndex];
        if (!queueAccessNodeId || !queueServiceExitNodeId || !queueNodeId) {
          continue;
        }
        if (previousQueueAccessNodeId) {
          addEdge(
            `${previousQueueAccessNodeId}-${queueAccessNodeId}`,
            previousQueueAccessNodeId,
            queueAccessNodeId,
            `${lift.id}-standby-queue-aisle-${String(queueIndex + 1).padStart(2, '0')}`
          );
        }
        addEdge(
          `${queueAccessNodeId}-${queueNodeId}`,
          queueAccessNodeId,
          queueNodeId,
          `${lift.id}-standby-queue-slot-${String(queueIndex + 1).padStart(2, '0')}`
        );
        if (previousQueueNodeId) {
          addEdge(
            `${previousQueueNodeId}-${queueNodeId}`,
            previousQueueNodeId,
            queueNodeId,
            `${lift.id}-standby-queue-parking-spine-${String(queueIndex + 1).padStart(2, '0')}`,
            'oneWay'
          );
        }
        const queueEntryNodeId = lift.queueEntryNodeIds[queueIndex];
        if (queueEntryNodeId) {
          const entryNode = nodesById.get(queueEntryNodeId);
          if (entryNode) {
            const entryColumnIndex = columnXs.findIndex((x) => Math.abs(x - entryNode.x) < 1e-6);
            if (entryColumnIndex >= 0) {
              const entryExitNodeId = columnAccessNodeId(lift.kind === 'outbound' ? 'bottom-b' : 'top-b', entryColumnIndex);
              addEdge(
                `${queueEntryNodeId}-${entryExitNodeId}`,
                queueEntryNodeId,
                entryExitNodeId,
                `${lift.id}-standby-queue-main-exit-${String(queueIndex + 1).padStart(2, '0')}`,
                'twoWay'
              );
            }
            if (lift.kind === 'inbound') {
              addEdge(
                `${queueEntryNodeId}-${queueAccessNodeId}`,
                queueEntryNodeId,
                queueAccessNodeId,
                `${lift.id}-standby-queue-entry-pocket-${String(queueIndex + 1).padStart(2, '0')}`,
                'twoWay'
              );
              addEdge(
                `${queueServiceExitNodeId}-${queueEntryNodeId}`,
                queueServiceExitNodeId,
                queueEntryNodeId,
                `${lift.id}-standby-queue-service-entry-${String(queueIndex + 1).padStart(2, '0')}`,
                'twoWay'
              );
            } else {
              addEdge(
                `${queueEntryNodeId}-${queueAccessNodeId}`,
                queueEntryNodeId,
                queueAccessNodeId,
                `${lift.id}-standby-queue-entry-pocket-${String(queueIndex + 1).padStart(2, '0')}`,
                'twoWay'
              );
              addEdge(
                `${queueEntryNodeId}-${queueServiceExitNodeId}`,
                queueEntryNodeId,
                queueServiceExitNodeId,
                `${lift.id}-standby-queue-service-entry-${String(queueIndex + 1).padStart(2, '0')}`,
                'oneWay'
              );
            }
          }
        }
        addEdge(
          `${queueServiceExitNodeId}-${previousServiceExitNodeId}`,
          queueServiceExitNodeId,
          previousServiceExitNodeId,
          `${lift.id}-standby-queue-service-spine-${String(queueIndex + 1).padStart(2, '0')}`,
          'twoWay'
        );
        previousQueueAccessNodeId = queueAccessNodeId;
        previousQueueNodeId = queueNodeId;
        previousServiceExitNodeId = queueServiceExitNodeId;
      }
      const firstServiceExitNodeId = lift.queueServiceExitNodeIds[0];
      if (lift.kind === 'inbound' && firstServiceExitNodeId) {
        addEdge(
          `${pickupBufferNodeId}-${firstServiceExitNodeId}`,
          pickupBufferNodeId,
          firstServiceExitNodeId,
          `${lift.id}-conveyor-service-exit`
        );
      }
      if (lift.kind === 'outbound') {
        const lastServiceExitNodeId = lift.queueServiceExitNodeIds.at(-1);
        const firstEntryNodeId = lift.queueEntryNodeIds[0];
        const lastEntryNodeId = lift.queueEntryNodeIds.at(-1);
        const firstEntryNode = firstEntryNodeId ? nodesById.get(firstEntryNodeId) : null;
        const firstEntryColumnIndex = firstEntryNode
          ? columnXs.findIndex((x) => Math.abs(x - firstEntryNode.x) < 1e-6)
          : -1;
        if (lastServiceExitNodeId && firstEntryNodeId && lastEntryNodeId && firstEntryColumnIndex >= 0) {
          if (firstServiceExitNodeId) {
            addEdge(
              `${firstServiceExitNodeId}-${firstEntryNodeId}-direct-clearance`,
              firstServiceExitNodeId,
              firstEntryNodeId,
              `${lift.id}-outbound-dropoff-clearance-direct`,
              'oneWay'
            );
          }
          const exitOuterNodeId = columnAccessNodeId('bottom-b', firstEntryColumnIndex);
          addEdge(
            `${lastServiceExitNodeId}-${lastEntryNodeId}-clearance`,
            lastServiceExitNodeId,
            lastEntryNodeId,
            `${lift.id}-outbound-dropoff-clearance-lateral`,
            'oneWay'
          );
          for (let entryIndex = lift.queueEntryNodeIds.length - 1; entryIndex >= 1; entryIndex -= 1) {
            const fromEntryNodeId = lift.queueEntryNodeIds[entryIndex];
            const toEntryNodeId = lift.queueEntryNodeIds[entryIndex - 1];
            if (!fromEntryNodeId || !toEntryNodeId) {
              continue;
            }
            addEdge(
              `${fromEntryNodeId}-${toEntryNodeId}-clearance`,
              fromEntryNodeId,
              toEntryNodeId,
              `${lift.id}-outbound-dropoff-clearance-entry-spine-${String(entryIndex).padStart(2, '0')}`,
              'twoWay'
            );
          }
          addEdge(
            `${firstEntryNodeId}-${exitOuterNodeId}-clearance`,
            firstEntryNodeId,
            exitOuterNodeId,
            `${lift.id}-outbound-dropoff-clearance-exit`,
            'oneWay'
          );
        }
      }
    }
    let previousBufferNodeId: string | null = null;
    for (const bufferNodeId of lift.bufferNodeIds) {
      if (!previousBufferNodeId) {
        addEdge(`${lift.id}-${bufferNodeId}`, lift.id, bufferNodeId, `${lift.id}-conveyor-buffer`);
      } else {
        addEdge(`${previousBufferNodeId}-${bufferNodeId}`, previousBufferNodeId, bufferNodeId, `${lift.id}-conveyor-buffer`);
      }
      previousBufferNodeId = bufferNodeId;
    }
  }

  const parkingZ = bottomLaneBZM;
  for (let index = 0; index < 8; index += 1) {
    const columnIndex = Math.min(totalColumns - 1, Math.floor(index * totalColumns / 8));
    const id = `parking-${String(index + 1).padStart(2, '0')}`;
    addNode({ id, type: 'parking', x: columnXs[columnIndex]!, y: 0, z: round(parkingZ + profile.parkingStandoffXM, 3), noStop: false, noParking: false, capacity: 1, allowedDirections: [] });
    nodesById.set(id, nodes[nodes.length - 1]!);
    addEdge(`${id}-${columnAccessNodeId('bottom-b', columnIndex)}`, id, columnAccessNodeId('bottom-b', columnIndex), `parking-bottom-c${String(columnIndex + 1).padStart(2, '0')}`);
  }

  const calibrationProfile = {
    ...profile.calibrationProfile,
    id: TOP_LIFT_COLUMN_LAYOUT_PROFILE_ID,
    label: 'Top-lift column-fill layout assumption',
    sourceDescription: `${profile.calibrationProfile.sourceDescription}; updated from user reference image and vendor direction with top-side inbound lifts, opposite lower-side outbound lifts, and column-fill 7x7 modules.`,
    dimensions: profile.calibrationProfile.dimensions.map((dimension) => dimension.key === 'storageBayGapX'
      ? {
          ...dimension,
          note: 'Top-lift column layouts use one storage pitch as the pass-through gap between adjacent 7x7 storage zones.'
        }
      : dimension),
    notes: [
      ...profile.calibrationProfile.notes,
      'Top-lift column layout: every region has an upper inbound lift above the middle aisle and an opposite lower outbound lift.',
      'Each inbound and outbound lift port has three explicit compact conveyor buffer positions stacked along the lift side; inbound buffers sit to the right of the port and outbound buffers sit to the left.',
      'Each lift workcell has side standby queue pockets spaced at least one shuttle footprint apart so waiting shuttles do not occupy the main aisle.',
      'Each pair of physical lifts owns four 7x7 storage zones; inbound target allocation fills each physical storage column bottom-to-top.',
      'Adjacent 7x7 storage zones leave a one-lane pass-through gap; empty shuttles may use storage cells as conditional aisle space while loaded routes avoid stored-load crossings.',
      'Inbound source backlog models three port buffer positions plus one lift position per inbound port.'
    ]
  };

  return { units: 'meter', calibrationProfile, nodes, edges, zones: [] };
}

function createDefaultLayout(
  profile: ShuttleLayoutGeometryProfile = DEFAULT_SHUTTLE_LAYOUT_PROFILE,
  liftMode: DefaultLiftMode = 'balanced'
): ShuttleScenario['layout'] {
  if (profile.layoutKind === 'top-lift-column') {
    return createTopLiftColumnLayout(profile, liftMode);
  }

  const leftSpineX = profile.leftSpineXM;
  const rowZs = defaultStorageRowZs(profile);
  const columnXs = defaultStorageColumnXs(profile);
  const storageColumns = columnXs.length;
  const rightSpineX = round(columnXs[columnXs.length - 1]! + profile.sideClearanceXM, 3);
  const topZ = round(rowZs[0]! - profile.storageCellPitchZM * 1.5, 3);
  const bottomZ = round(rowZs[rowZs.length - 1]! + profile.storageCellPitchZM * 1.5, 3);
  const topLiftZ = round(topZ - profile.liftStandoffZM, 3);
  const bottomLiftZ = round(bottomZ + profile.liftStandoffZM, 3);
  const liftPortalXs = defaultLiftPortalXs(columnXs, rightSpineX, profile);
  const mainXs = [leftSpineX, ...liftPortalXs, rightSpineX];

  const rightParkingX = round(rightSpineX + profile.parkingStandoffXM, 3);
  const rightStagingX = round(rightSpineX + profile.parkingStandoffXM * 2, 3);
  const leftParkingX = round(leftSpineX - profile.parkingStandoffXM, 3);
  const leftStagingX = round(leftSpineX - profile.parkingStandoffXM * 2, 3);

  const nodes: LayoutNode[] = [
    { id: 'left-top', type: 'aisle', x: leftSpineX, y: 0, z: topZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] },
    { id: 'left-bottom', type: 'aisle', x: leftSpineX, y: 0, z: bottomZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] },
    { id: 'right-top', type: 'aisle', x: rightSpineX, y: 0, z: topZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] },
    { id: 'right-bottom', type: 'aisle', x: rightSpineX, y: 0, z: bottomZ, noStop: true, noParking: true, capacity: 1, allowedDirections: [] },
    { id: 'parking-a', type: 'parking', x: rightParkingX, y: 0, z: profile.mainLaneNorthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-b', type: 'parking', x: rightParkingX, y: 0, z: profile.mainLaneSouthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-c', type: 'parking', x: leftParkingX, y: 0, z: profile.mainLaneNorthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-d', type: 'parking', x: leftParkingX, y: 0, z: profile.mainLaneSouthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-e', type: 'parking', x: rightStagingX, y: 0, z: profile.mainLaneNorthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-f', type: 'parking', x: rightStagingX, y: 0, z: profile.mainLaneSouthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-g', type: 'parking', x: leftStagingX, y: 0, z: profile.mainLaneNorthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] },
    { id: 'parking-h', type: 'parking', x: leftStagingX, y: 0, z: profile.mainLaneSouthZM, noStop: false, noParking: false, capacity: 1, allowedDirections: [] }
  ];

  mainXs.forEach((x, index) => {
    nodes.push(
      { id: mainLaneNodeId('north', index), type: 'intersection', x, y: 0, z: profile.mainLaneNorthZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] },
      { id: mainLaneNodeId('south', index), type: 'intersection', x, y: 0, z: profile.mainLaneSouthZM, noStop: true, noParking: true, capacity: 1, allowedDirections: [] }
    );
  });

  const liftKind = (balancedKind: LiftKind): LiftKind => liftMode === 'all-inbound' ? 'inbound' : balancedKind;
  const liftDefinitions: Array<{ id: string; liftKind: LiftKind; portalIndex: number; x: number; z: number }> = [
    { id: 'inbound-lift-top-01', liftKind: liftKind('inbound'), portalIndex: 0, x: liftPortalXs[0]!, z: topLiftZ },
    { id: 'outbound-lift-top-01', liftKind: liftKind('outbound'), portalIndex: 1, x: liftPortalXs[1]!, z: topLiftZ },
    { id: 'inbound-lift-top-02', liftKind: liftKind('inbound'), portalIndex: 2, x: liftPortalXs[2]!, z: topLiftZ },
    { id: 'outbound-lift-top-02', liftKind: liftKind('outbound'), portalIndex: 3, x: liftPortalXs[3]!, z: topLiftZ },
    { id: 'outbound-lift-bottom-01', liftKind: liftKind('outbound'), portalIndex: 0, x: liftPortalXs[0]!, z: bottomLiftZ },
    { id: 'inbound-lift-bottom-01', liftKind: liftKind('inbound'), portalIndex: 1, x: liftPortalXs[1]!, z: bottomLiftZ },
    { id: 'outbound-lift-bottom-02', liftKind: liftKind('outbound'), portalIndex: 2, x: liftPortalXs[2]!, z: bottomLiftZ },
    { id: 'inbound-lift-bottom-02', liftKind: liftKind('inbound'), portalIndex: 3, x: liftPortalXs[3]!, z: bottomLiftZ }
  ];
  liftDefinitions.forEach((lift) => {
    nodes.push({ id: lift.id, type: 'lift-blackbox', liftKind: lift.liftKind, x: lift.x, y: 0, z: lift.z, noStop: true, noParking: true, capacity: 1, allowedDirections: [] });
  });
  for (let rowIndex = 0; rowIndex < rowZs.length; rowIndex += 1) {
    const z = rowZs[rowIndex]!;
    const rowLabel = String(rowIndex + 1).padStart(2, '0');
    nodes.push(
      { id: `left-row-${rowLabel}`, type: 'intersection', x: leftSpineX, y: 0, z, noStop: false, noParking: true, capacity: 1, allowedDirections: [] },
      { id: `right-row-${rowLabel}`, type: 'intersection', x: rightSpineX, y: 0, z, noStop: false, noParking: true, capacity: 1, allowedDirections: [] }
    );
    for (let columnIndex = 0; columnIndex < columnXs.length; columnIndex += 1) {
      nodes.push({
        id: storageNodeId(rowIndex, columnIndex),
        type: 'storage',
        x: columnXs[columnIndex]!,
        y: 0,
        z,
        noStop: false,
        noParking: false,
        capacity: 1,
        allowedDirections: []
      });
    }
  }

  const liftStorageTransferNodes: Array<{
    id: string;
    liftId: string;
    rowLabel: string;
    rowIndex: number;
    storageIds: string[];
  }> = [];
  for (const lift of liftDefinitions) {
    for (let rowIndex = 0; rowIndex < rowZs.length; rowIndex += 1) {
      const z = rowZs[rowIndex]!;
      const rowLabel = String(rowIndex + 1).padStart(2, '0');
      const leftColumnIndex = columnXs.findIndex((x, index) =>
        index < columnXs.length - 1 &&
        x < lift.x &&
        lift.x < columnXs[index + 1]!
      );
      const storageIds = leftColumnIndex >= 0
        ? [
            storageNodeId(rowIndex, leftColumnIndex),
            storageNodeId(rowIndex, leftColumnIndex + 1)
          ]
        : lift.x <= columnXs[0]!
          ? [storageNodeId(rowIndex, 0)]
          : lift.x >= columnXs[columnXs.length - 1]!
            ? [storageNodeId(rowIndex, columnXs.length - 1)]
            : [];
      if (storageIds.length === 0) {
        continue;
      }
      const id = `${lift.id}-row-${rowLabel}-transfer`;
      nodes.push({
        id,
        type: 'intersection',
        x: lift.x,
        y: 0,
        z,
        noStop: true,
        noParking: true,
        capacity: 1,
        allowedDirections: []
      });
      liftStorageTransferNodes.push({ id, liftId: lift.id, rowLabel, rowIndex, storageIds });
    }
  }

  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  const edges: LayoutEdge[] = [];
  const addEdge = (id: string, from: string, to: string, conflictGroup: string, directionMode: 'oneWay' | 'twoWay' = 'twoWay') => {
    const fromNode = nodesById.get(from);
    const toNode = nodesById.get(to);
    if (!fromNode || !toNode) {
      throw new Error(`Default layout edge ${id} references an unknown node.`);
    }
    edges.push({
      id,
      from,
      to,
      lengthM: round(Math.abs(toNode.x - fromNode.x) + Math.abs(toNode.z - fromNode.z), 3),
      directionMode,
      reservationType: 'edge',
      conflictGroup,
      noParking: true
    });
  };

  addEdge('left-top-right-top', 'left-top', 'right-top', 'north-cross-aisle');
  addEdge('left-bottom-right-bottom', 'left-bottom', 'right-bottom', 'south-cross-aisle');

  for (let index = 1; index < mainXs.length; index += 1) {
    addEdge(
      `${mainLaneNodeId('north', index - 1)}-${mainLaneNodeId('north', index)}`,
      mainLaneNodeId('north', index - 1),
      mainLaneNodeId('north', index),
      `main-lane-north-${String(index).padStart(2, '0')}`
    );
    addEdge(
      `${mainLaneNodeId('south', index - 1)}-${mainLaneNodeId('south', index)}`,
      mainLaneNodeId('south', index - 1),
      mainLaneNodeId('south', index),
      `main-lane-south-${String(index).padStart(2, '0')}`
    );
  }
  for (let index = 1; index < mainXs.length - 1; index += 1) {
    addEdge(
      `${mainLaneNodeId('north', index)}-${mainLaneNodeId('south', index)}`,
      mainLaneNodeId('north', index),
      mainLaneNodeId('south', index),
      `main-lane-transfer-${String(index).padStart(2, '0')}`
    );
  }

  const lastMainIndex = mainXs.length - 1;
  addEdge('parking-a-main-north-right', 'parking-a', mainLaneNodeId('north', lastMainIndex), 'parking-approach-right-north');
  addEdge('parking-b-main-south-right', 'parking-b', mainLaneNodeId('south', lastMainIndex), 'parking-approach-right-south');
  addEdge('parking-c-main-north-left', 'parking-c', mainLaneNodeId('north', 0), 'parking-approach-left-north');
  addEdge('parking-d-main-south-left', 'parking-d', mainLaneNodeId('south', 0), 'parking-approach-left-south');
  addEdge('parking-e-parking-a', 'parking-e', 'parking-a', 'parking-staging-right-north');
  addEdge('parking-f-parking-b', 'parking-f', 'parking-b', 'parking-staging-right-south');
  addEdge('parking-g-parking-c', 'parking-g', 'parking-c', 'parking-staging-left-north');
  addEdge('parking-h-parking-d', 'parking-h', 'parking-d', 'parking-staging-left-south');

  const liftConnectorDefinitions = [
    { id: 'inbound-lift-top-01', targets: [mainLaneNodeId('north', 1), mainLaneNodeId('south', 1)] },
    { id: 'outbound-lift-top-01', targets: [mainLaneNodeId('north', 2), mainLaneNodeId('south', 2)] },
    { id: 'inbound-lift-top-02', targets: [mainLaneNodeId('north', 3), mainLaneNodeId('south', 3)] },
    { id: 'outbound-lift-top-02', targets: [mainLaneNodeId('north', 4), mainLaneNodeId('south', 4)] },
    { id: 'outbound-lift-bottom-01', targets: [mainLaneNodeId('north', 1), mainLaneNodeId('south', 1)] },
    { id: 'inbound-lift-bottom-01', targets: [mainLaneNodeId('north', 2), mainLaneNodeId('south', 2)] },
    { id: 'outbound-lift-bottom-02', targets: [mainLaneNodeId('north', 3), mainLaneNodeId('south', 3)] },
    { id: 'inbound-lift-bottom-02', targets: [mainLaneNodeId('north', 4), mainLaneNodeId('south', 4)] }
  ];
  liftConnectorDefinitions.forEach((connector) => {
    for (const target of connector.targets) {
      addEdge(`${connector.id}-${target}`, connector.id, target, `${connector.id}-dock`);
    }
  });
  const topRowNodeIds = rowZs.map((z, rowIndex) => ({ z, left: `left-row-${String(rowIndex + 1).padStart(2, '0')}`, right: `right-row-${String(rowIndex + 1).padStart(2, '0')}` }))
    .filter((row) => row.z < profile.mainLaneNorthZM);
  const bottomRowNodeIds = rowZs.map((z, rowIndex) => ({ z, left: `left-row-${String(rowIndex + 1).padStart(2, '0')}`, right: `right-row-${String(rowIndex + 1).padStart(2, '0')}` }))
    .filter((row) => row.z > profile.mainLaneSouthZM);
  const leftSpineNodeIds = [
    'left-top',
    ...topRowNodeIds.map((row) => row.left),
    mainLaneNodeId('north', 0),
    mainLaneNodeId('south', 0),
    ...bottomRowNodeIds.map((row) => row.left),
    'left-bottom'
  ];
  const rightSpineNodeIds = [
    'right-top',
    ...topRowNodeIds.map((row) => row.right),
    mainLaneNodeId('north', lastMainIndex),
    mainLaneNodeId('south', lastMainIndex),
    ...bottomRowNodeIds.map((row) => row.right),
    'right-bottom'
  ];
  for (let index = 1; index < leftSpineNodeIds.length; index += 1) {
    const from = leftSpineNodeIds[index - 1]!;
    const to = leftSpineNodeIds[index]!;
    addEdge(`${from}-${to}`, from, to, `left-upright-${String(index).padStart(2, '0')}`);
  }
  for (let index = 1; index < rightSpineNodeIds.length; index += 1) {
    const from = rightSpineNodeIds[index - 1]!;
    const to = rightSpineNodeIds[index]!;
    addEdge(`${from}-${to}`, from, to, `right-upright-${String(index).padStart(2, '0')}`);
  }

  for (const lift of liftDefinitions) {
    const columnNodes = [
      lift.id,
      ...liftStorageTransferNodes
        .filter((transfer) => transfer.liftId === lift.id)
        .map((transfer) => transfer.id)
    ].sort((left, right) => nodesById.get(left)!.z - nodesById.get(right)!.z || left.localeCompare(right));
    for (let index = 1; index < columnNodes.length; index += 1) {
      const from = columnNodes[index - 1]!;
      const to = columnNodes[index]!;
      addEdge(
        `lift-column-segment-${from}-${to}`,
        from,
        to,
        `${lift.id}-storage-column-${String(index).padStart(2, '0')}`
      );
    }
  }

  for (let rowIndex = 0; rowIndex < rowZs.length; rowIndex += 1) {
    const rowLabel = String(rowIndex + 1).padStart(2, '0');
    const rightRowId = `right-row-${rowLabel}`;
    const leftRowId = `left-row-${rowLabel}`;
    const rightmostStorageId = storageNodeId(rowIndex, storageColumns - 1);
    edges.push({
      id: `${rightRowId}-${rightmostStorageId}`,
      from: rightRowId,
      to: rightmostStorageId,
      lengthM: round(rightSpineX - columnXs[storageColumns - 1]!, 3),
      directionMode: 'twoWay',
      reservationType: 'edge',
      conflictGroup: `fifo-lane-${rowLabel}`,
      noParking: true
    });
    for (let columnIndex = storageColumns - 1; columnIndex > 0; columnIndex -= 1) {
      const from = storageNodeId(rowIndex, columnIndex);
      const to = storageNodeId(rowIndex, columnIndex - 1);
      edges.push({
        id: `${from}-${to}`,
        from,
        to,
        lengthM: round(columnXs[columnIndex]! - columnXs[columnIndex - 1]!, 3),
        directionMode: 'twoWay',
        reservationType: 'edge',
        conflictGroup: `fifo-lane-${rowLabel}`,
        noParking: true
      });
    }
    const leftmostStorageId = storageNodeId(rowIndex, 0);
    edges.push({
      id: `${leftmostStorageId}-${leftRowId}`,
      from: leftmostStorageId,
      to: leftRowId,
      lengthM: round(columnXs[0]! - leftSpineX, 3),
      directionMode: 'twoWay',
      reservationType: 'edge',
      conflictGroup: `fifo-lane-${rowLabel}`,
      noParking: true
    });
  }
  for (const transfer of liftStorageTransferNodes) {
    for (const storageId of transfer.storageIds) {
      addEdge(
        `${storageId}-${transfer.id}`,
        storageId,
        transfer.id,
        `fifo-lane-${transfer.rowLabel}`
      );
    }
    addEdge(
      `${transfer.id}-${transfer.liftId}`,
      transfer.id,
      transfer.liftId,
      `${transfer.liftId}-storage-transfer-${transfer.rowLabel}`
    );
  }

  const liftStorageCrossingZones: LayoutZone[] = [];
  const liftMainCrossingZones: LayoutZone[] = [];
  const liftConnectorEdges = edges.filter((edge) => {
    const fromNode = nodesById.get(edge.from);
    const toNode = nodesById.get(edge.to);
    return (
      (fromNode?.type === 'lift-blackbox' && toNode?.id.startsWith('main-')) ||
      (toNode?.type === 'lift-blackbox' && fromNode?.id.startsWith('main-'))
    );
  });
  const fifoLaneEdges = edges.filter((edge) => edge.conflictGroup?.startsWith('fifo-lane'));
  for (const connectorEdge of liftConnectorEdges) {
    const connectorFrom = nodesById.get(connectorEdge.from)!;
    const connectorTo = nodesById.get(connectorEdge.to)!;
    if (connectorFrom.x !== connectorTo.x) {
      continue;
    }
    const connectorX = connectorFrom.x;
    const connectorMinZ = Math.min(connectorFrom.z, connectorTo.z);
    const connectorMaxZ = Math.max(connectorFrom.z, connectorTo.z);
    for (const fifoEdge of fifoLaneEdges) {
      const fifoFrom = nodesById.get(fifoEdge.from)!;
      const fifoTo = nodesById.get(fifoEdge.to)!;
      if (fifoFrom.z !== fifoTo.z) {
        continue;
      }
      const fifoMinX = Math.min(fifoFrom.x, fifoTo.x);
      const fifoMaxX = Math.max(fifoFrom.x, fifoTo.x);
      const crosses = connectorX >= fifoMinX && connectorX <= fifoMaxX && fifoFrom.z >= connectorMinZ && fifoFrom.z <= connectorMaxZ;
      if (!crosses) {
        continue;
      }
      const index = liftStorageCrossingZones.length + 1;
      liftStorageCrossingZones.push({
        id: `zone-lift-storage-cross-${String(index).padStart(3, '0')}`,
        type: 'intersection' as const,
        nodeIds: [],
        edgeIds: [connectorEdge.id, fifoEdge.id].sort((left, right) => left.localeCompare(right)),
        noStop: true,
        noParking: true,
        capacity: 1,
        conflictGroup: `intersection-lift-storage-cross-${String(index).padStart(3, '0')}`
      });
    }
  }
  const mainLaneEdges = edges.filter((edge) => edge.from.startsWith('main-') && edge.to.startsWith('main-'));
  for (const connectorEdge of liftConnectorEdges) {
    const connectorFrom = nodesById.get(connectorEdge.from)!;
    const connectorTo = nodesById.get(connectorEdge.to)!;
    if (connectorFrom.x !== connectorTo.x) {
      continue;
    }
    const connectorX = connectorFrom.x;
    const connectorMinZ = Math.min(connectorFrom.z, connectorTo.z);
    const connectorMaxZ = Math.max(connectorFrom.z, connectorTo.z);
    for (const mainEdge of mainLaneEdges) {
      const mainFrom = nodesById.get(mainEdge.from)!;
      const mainTo = nodesById.get(mainEdge.to)!;
      if (mainFrom.z !== mainTo.z) {
        continue;
      }
      const mainMinX = Math.min(mainFrom.x, mainTo.x);
      const mainMaxX = Math.max(mainFrom.x, mainTo.x);
      const crosses = connectorX >= mainMinX && connectorX <= mainMaxX && mainFrom.z >= connectorMinZ && mainFrom.z <= connectorMaxZ;
      if (!crosses) {
        continue;
      }
      const index = liftMainCrossingZones.length + 1;
      liftMainCrossingZones.push({
        id: `zone-lift-main-cross-${String(index).padStart(3, '0')}`,
        type: 'intersection' as const,
        nodeIds: [],
        edgeIds: [connectorEdge.id, mainEdge.id].sort((left, right) => left.localeCompare(right)),
        noStop: true,
        noParking: true,
        capacity: 1,
        conflictGroup: `intersection-lift-main-cross-${String(index).padStart(3, '0')}`
      });
    }
  }
  const liftSideOverlapZones: LayoutZone[] = [];
  const sideUprightEdges = edges.filter((edge) =>
    edge.conflictGroup?.startsWith('left-upright') || edge.conflictGroup?.startsWith('right-upright')
  );
  for (const connectorEdge of liftConnectorEdges) {
    const connectorFrom = nodesById.get(connectorEdge.from)!;
    const connectorTo = nodesById.get(connectorEdge.to)!;
    if (connectorFrom.x !== connectorTo.x) {
      continue;
    }
    const connectorMinZ = Math.min(connectorFrom.z, connectorTo.z);
    const connectorMaxZ = Math.max(connectorFrom.z, connectorTo.z);
    for (const sideEdge of sideUprightEdges) {
      const sideFrom = nodesById.get(sideEdge.from)!;
      const sideTo = nodesById.get(sideEdge.to)!;
      if (sideFrom.x !== sideTo.x || Math.abs(sideFrom.x - connectorFrom.x) > 1e-6) {
        continue;
      }
      const sideMinZ = Math.min(sideFrom.z, sideTo.z);
      const sideMaxZ = Math.max(sideFrom.z, sideTo.z);
      const overlapM = Math.min(connectorMaxZ, sideMaxZ) - Math.max(connectorMinZ, sideMinZ);
      if (overlapM <= 1e-6) {
        continue;
      }
      const index = liftSideOverlapZones.length + 1;
      const overlapNodeIds = [
        { id: sideEdge.from, z: sideFrom.z },
        { id: sideEdge.to, z: sideTo.z }
      ]
        .filter((node) => node.z >= connectorMinZ - 1e-6 && node.z <= connectorMaxZ + 1e-6)
        .map((node) => node.id)
        .sort((left, right) => left.localeCompare(right));
      liftSideOverlapZones.push({
        id: `zone-lift-side-overlap-${String(index).padStart(3, '0')}`,
        type: 'intersection' as const,
        nodeIds: overlapNodeIds,
        edgeIds: [connectorEdge.id, sideEdge.id].sort((left, right) => left.localeCompare(right)),
        noStop: true,
        noParking: true,
        capacity: 1,
        conflictGroup: `intersection-lift-side-overlap-${String(index).padStart(3, '0')}`
      });
    }
  }

  const zones: LayoutZone[] = [
    ...liftStorageCrossingZones,
    ...liftMainCrossingZones,
    ...liftSideOverlapZones,
    ...mainXs.map((_, index) => {
      const portalNodeIds = [mainLaneNodeId('north', index), mainLaneNodeId('south', index)];
      const portalNodeIdSet = new Set(portalNodeIds);
      const portalLiftEdgeIds = edges
        .filter((edge) => portalNodeIdSet.has(edge.from) || portalNodeIdSet.has(edge.to))
        .filter((edge) => {
          const otherNodeId = portalNodeIdSet.has(edge.from) ? edge.to : edge.from;
          const otherNode = nodesById.get(otherNodeId);
          return (
            otherNode?.type === 'lift-blackbox' ||
            edge.id === `${mainLaneNodeId('north', index)}-${mainLaneNodeId('south', index)}`
          );
        })
        .map((edge) => edge.id)
        .sort((left, right) => left.localeCompare(right));
      return {
        id: `zone-main-portal-node-${String(index).padStart(2, '0')}`,
        type: 'intersection' as const,
        nodeIds: portalNodeIds,
        edgeIds: portalLiftEdgeIds,
        noStop: true,
        noParking: true,
        capacity: 1,
        conflictGroup: `intersection-main-portal-node-${String(index).padStart(2, '0')}`
      };
    })
  ];

  return { units: 'meter', calibrationProfile: profile.calibrationProfile, nodes, edges, zones };
}

export function createDefaultShuttleScenario(overrides: ShuttleScenarioOverrides = {}): ShuttleScenario {
  const layoutProfile = createShuttleLayoutProfile(overrides.layoutProfile);
  const base: ShuttleScenario = {
    schemaVersion: 'shuttle.phase0.v0',
    id: 'shuttle-phase0-balanced',
    name: 'Phase 0 Balanced Shuttle Smoke',
    seed: 20260502,
    durationSec: 7200,
    timeStepSec: 0.2,
    vehicles: {
      count: 2,
      lengthM: 1.03,
      widthM: 1.03,
      heightM: 0.16,
      emptySpeedMps: 2,
      loadedSpeedMps: 1.5,
      accelerationMps2: 1,
      switchDirectionSec: 0,
      liftTimeSec: 0.05,
      lowerTimeSec: 0.05,
      maxLoadKg: 1800,
      safetyRadiusM: 0.1,
      batteryEnabled: false,
      initialSoc: 1
    },
    layout: createDefaultLayout(layoutProfile, overrides.liftMode ?? 'balanced'),
    taskGeneration: {
      inboundRatePerHour: 18,
      outboundRatePerHour: 18,
      inboundOutboundMix: 0.5,
      arrivalDistribution: 'deterministic',
      maxTasks: 40,
      initialStorageFillPolicy: 'full-columns',
      initialOutboundFullColumns: 0
    },
    physicsParams: {
      emptySpeedMps: 2,
      loadedSpeedMps: 1.5,
      accelerationMps2: 1,
      switchDirectionSec: 0,
      liftTimeSec: 0.05,
      lowerTimeSec: 0.05,
      loadedClearanceM: 0.2,
      reservationClearanceSec: 0.4
    },
    routingPolicy: {
      algorithm: 'astar',
      allowReplan: true,
      routeTimeoutSec: 12,
      maxReplansPerTask: 3
    },
    trafficPolicy: {
      controllerMode: 'reservation-v2',
      edgeCapacity: 1,
      nodeCapacity: 1,
      zoneCapacity: 1,
      liftApproachCapacity: 4,
      sourceBufferCapacity: 4,
      collisionAvoidanceEnabled: true,
      minimumClearanceSec: 0.4,
      dynamicAvoidanceClearanceM: 0.5,
      priorityAgingSec: 20,
      deadlockDetectSec: 2,
      deadlockBreakPolicy: 'oldest-waits-wins'
    }
  };

  return ShuttleScenarioSchema.parse({
    ...base,
    ...overrides,
    vehicles: { ...base.vehicles, ...overrides.vehicles },
    layout: { ...base.layout, ...overrides.layout },
    taskGeneration: { ...base.taskGeneration, ...overrides.taskGeneration },
    physicsParams: { ...base.physicsParams, ...overrides.physicsParams },
    routingPolicy: { ...base.routingPolicy, ...overrides.routingPolicy },
    trafficPolicy: { ...base.trafficPolicy, ...overrides.trafficPolicy }
  });
}

export function createInboundMvpBaselineScenario(overrides: ShuttleScenarioOverrides = {}): ShuttleScenario {
  return createDefaultShuttleScenario({
    ...overrides,
    id: overrides.id ?? 'shuttle-all-inbound-8x-7200',
    name: overrides.name ?? 'All Inbound 8 Shuttle 7200 PPH Stress',
    layoutProfile: {
      layoutKind: 'top-lift-column',
      liftPairCount: 2,
      ...overrides.layoutProfile
    },
    durationSec: overrides.durationSec ?? 7200,
    vehicles: {
      count: 8,
      emptySpeedMps: 2,
      loadedSpeedMps: 1.5,
      accelerationMps2: 1.2,
      liftTimeSec: 0.01,
      lowerTimeSec: 0.01,
      ...overrides.vehicles
    },
    physicsParams: {
      emptySpeedMps: 2,
      loadedSpeedMps: 1.5,
      accelerationMps2: 1.2,
      liftTimeSec: 0.01,
      lowerTimeSec: 0.01,
      ...overrides.physicsParams
    },
    taskGeneration: {
      inboundRatePerHour: 7200,
      outboundRatePerHour: 0,
      inboundOutboundMix: 1,
      arrivalDistribution: 'deterministic',
      maxTasks: 32,
      ...overrides.taskGeneration
    },
    trafficPolicy: {
      controllerMode: 'agent-refresh',
      liftApproachCapacity: 4,
      sourceBufferCapacity: 4,
      minimumClearanceSec: 0.4,
      dynamicAvoidanceClearanceM: 0.5,
      deadlockDetectSec: 2,
      ...overrides.trafficPolicy
    }
  });
}

export function createInboundOutboundDemoScenario(overrides: ShuttleScenarioOverrides = {}): ShuttleScenario {
  return createInboundMvpBaselineScenario({
    ...overrides,
    id: overrides.id ?? 'shuttle-inbound-outbound-demo',
    name: overrides.name ?? 'Inbound + Outbound 8 Shuttle Column Demo',
    vehicles: {
      switchDirectionSec: 1,
      ...overrides.vehicles
    },
    physicsParams: {
      switchDirectionSec: 1,
      ...overrides.physicsParams
    },
    taskGeneration: {
      inboundRatePerHour: 3600,
      outboundRatePerHour: 3600,
      inboundOutboundMix: 0.5,
      arrivalDistribution: 'deterministic',
      maxTasks: 32,
      initialStorageFillPolicy: 'full-columns',
      initialOutboundFullColumns: 4,
      ...overrides.taskGeneration
    },
    trafficPolicy: {
      deadlockDetectSec: 10,
      ...overrides.trafficPolicy
    }
  });
}

export function summarizeScenarioStaticSceneContract(scenario: ShuttleScenario = createDefaultShuttleScenario()): ShuttleStaticSceneContract {
  return summarizeStaticSceneContract(scenario);
}

export type VerticalStorageFootprintEdgeViolation = {
  edgeId: string;
  cellId: string;
};

type FootprintRect = {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
};

export type StaticObstacleFootprintViolation = {
  resourceType: 'edge' | 'node' | 'zone';
  resourceId: string;
  blockedCellId: string;
};

function rectsOverlap(left: FootprintRect, right: FootprintRect): boolean {
  return left.minX < right.maxX && left.maxX > right.minX && left.minZ < right.maxZ && left.maxZ > right.minZ;
}

function blockedCellRect(cell: NonNullable<ShuttleScenario['layout']['calibrationProfile']>['blockedCells'][number]): FootprintRect {
  return {
    minX: cell.xM - cell.lengthXM / 2,
    maxX: cell.xM + cell.lengthXM / 2,
    minZ: cell.zM - cell.lengthZM / 2,
    maxZ: cell.zM + cell.lengthZM / 2
  };
}

function shuttleSweptSquareHalfExtentM(scenario: ShuttleScenario): number {
  return Math.max(scenario.vehicles.lengthM, scenario.vehicles.widthM) / 2 + scenario.physicsParams.loadedClearanceM;
}

function nodeSweptFootprintRect(node: LayoutNode, halfExtentM: number): FootprintRect {
  return {
    minX: node.x - halfExtentM,
    maxX: node.x + halfExtentM,
    minZ: node.z - halfExtentM,
    maxZ: node.z + halfExtentM
  };
}

function edgeSweptFootprintRect(from: LayoutNode, to: LayoutNode, halfExtentM: number): FootprintRect {
  return {
    minX: Math.min(from.x, to.x) - halfExtentM,
    maxX: Math.max(from.x, to.x) + halfExtentM,
    minZ: Math.min(from.z, to.z) - halfExtentM,
    maxZ: Math.max(from.z, to.z) + halfExtentM
  };
}

export function verticalStorageFootprintEdgeViolations(scenario: ShuttleScenario): VerticalStorageFootprintEdgeViolation[] {
  if (isTopLiftColumnLayout(scenario)) {
    return [];
  }
  const staticScene = summarizeStaticSceneContract(scenario);
  const nodesById = new Map(scenario.layout.nodes.map((node) => [node.id, node]));
  const violations: VerticalStorageFootprintEdgeViolation[] = [];

  for (const edge of scenario.layout.edges) {
    const from = nodesById.get(edge.from);
    const to = nodesById.get(edge.to);
    if (!from || !to || Math.abs(from.x - to.x) > 1e-6 || Math.abs(from.z - to.z) < 1e-6) {
      continue;
    }

    const edgeMinZ = Math.min(from.z, to.z);
    const edgeMaxZ = Math.max(from.z, to.z);
    const crossedCell = staticScene.storageCells.find((cell) => {
      const halfXM = cell.lengthXM / 2 - 1e-6;
      const halfZM = cell.lengthZM / 2 - 1e-6;
      return (
        from.x >= cell.xM - halfXM &&
        from.x <= cell.xM + halfXM &&
        edgeMinZ <= cell.zM + halfZM &&
        edgeMaxZ >= cell.zM - halfZM
      );
    });
    if (crossedCell) {
      violations.push({ edgeId: edge.id, cellId: crossedCell.id });
    }
  }

  return violations.sort((left, right) => left.edgeId.localeCompare(right.edgeId) || left.cellId.localeCompare(right.cellId));
}

export function staticObstacleFootprintViolations(scenario: ShuttleScenario): StaticObstacleFootprintViolation[] {
  const blockedCells = scenario.layout.calibrationProfile?.blockedCells ?? [];
  if (blockedCells.length === 0) {
    return [];
  }

  const blockedRects = blockedCells.map((cell) => ({ cell, rect: blockedCellRect(cell) }));
  const nodesById = new Map(scenario.layout.nodes.map((node) => [node.id, node]));
  const edgesById = new Map(scenario.layout.edges.map((edge) => [edge.id, edge]));
  const halfExtentM = shuttleSweptSquareHalfExtentM(scenario);
  const violations: StaticObstacleFootprintViolation[] = [];
  const blockedByResource = new Map<string, Set<string>>();
  const seen = new Set<string>();

  const addViolation = (resourceType: StaticObstacleFootprintViolation['resourceType'], resourceId: string, blockedCellId: string): void => {
    const key = `${resourceType}:${resourceId}:${blockedCellId}`;
    if (seen.has(key)) {
      return;
    }
    seen.add(key);
    violations.push({ resourceType, resourceId, blockedCellId });
    const resourceKey = `${resourceType}:${resourceId}`;
    const blockedIds = blockedByResource.get(resourceKey) ?? new Set<string>();
    blockedIds.add(blockedCellId);
    blockedByResource.set(resourceKey, blockedIds);
  };

  for (const node of scenario.layout.nodes) {
    if (node.type === 'lift-blackbox') {
      continue;
    }
    const rect = nodeSweptFootprintRect(node, halfExtentM);
    for (const blocked of blockedRects) {
      if (rectsOverlap(rect, blocked.rect)) {
        addViolation('node', node.id, blocked.cell.id);
      }
    }
  }

  for (const edge of scenario.layout.edges) {
    const from = nodesById.get(edge.from);
    const to = nodesById.get(edge.to);
    if (!from || !to) {
      continue;
    }
    const rect = edgeSweptFootprintRect(from, to, halfExtentM);
    for (const blocked of blockedRects) {
      if (rectsOverlap(rect, blocked.rect)) {
        addViolation('edge', edge.id, blocked.cell.id);
      }
    }
  }

  for (const zone of scenario.layout.zones) {
    const blockedCellIds = new Set<string>();
    for (const nodeId of zone.nodeIds) {
      for (const blockedCellId of blockedByResource.get(`node:${nodeId}`) ?? []) {
        blockedCellIds.add(blockedCellId);
      }
    }
    for (const edgeId of zone.edgeIds) {
      const edge = edgesById.get(edgeId);
      if (!edge) {
        continue;
      }
      for (const blockedCellId of blockedByResource.get(`edge:${edge.id}`) ?? []) {
        blockedCellIds.add(blockedCellId);
      }
    }
    for (const blockedCellId of blockedCellIds) {
      addViolation('zone', zone.id, blockedCellId);
    }
  }

  return violations.sort((left, right) =>
    left.resourceType.localeCompare(right.resourceType) ||
    left.resourceId.localeCompare(right.resourceId) ||
    left.blockedCellId.localeCompare(right.blockedCellId)
  );
}

function assertNoVerticalStorageFootprintEdges(scenario: ShuttleScenario): void {
  const violations = verticalStorageFootprintEdgeViolations(scenario);
  if (violations.length === 0) {
    return;
  }
  const first = violations[0]!;
  throw new Error(
    `Invalid storage topology: vertical edge ${first.edgeId} crosses storage-cell footprint ${first.cellId}; storage-area travel must stay horizontal.`
  );
}

function assertNoStaticObstacleFootprintViolations(scenario: ShuttleScenario): void {
  const violations = staticObstacleFootprintViolations(scenario);
  if (violations.length === 0) {
    return;
  }
  const first = violations[0]!;
  throw new Error(
    `Invalid layout topology: ${first.resourceType} ${first.resourceId} swept shuttle footprint intersects blocked cell ${first.blockedCellId}; legal routes, queues, and yield pockets must stay inside verified drivable space.`
  );
}

class TrafficControllerV2 {
  private sequence = 0;
  private readonly edgesById = new Map<string, LayoutEdge>();
  private readonly edgesByPair = new Map<string, LayoutEdge>();

  constructor(private readonly scenario: ShuttleScenario) {
    for (const edge of scenario.layout.edges) {
      this.edgesById.set(edge.id, edge);
      this.edgesByPair.set(`${edge.from}->${edge.to}`, edge);
      if (edge.directionMode === 'twoWay') {
        this.edgesByPair.set(`${edge.to}->${edge.from}`, edge);
      }
    }
  }

  reserveMove(options: {
    vehicleId: string;
    taskId: string | null;
    fromNodeId: string;
    toNodeId: string;
    startTimeSec: number;
    travelSec: number;
    priority: number;
    existing: Reservation[];
    ignoreConflicts?: boolean;
  }): ReservationAttempt {
    const edge = this.findEdge(options.fromNodeId, options.toNodeId);
    if (!edge) {
      return { ok: false, reasonCode: 'route-edge-missing', blockingReservationId: null };
    }

    const endTimeSec = options.startTimeSec + options.travelSec + this.scenario.trafficPolicy.minimumClearanceSec;
    const conflictTokenEndTimeSec = endTimeSec;
    const matchingZones = this.zonesForMovement(options.fromNodeId, options.toNodeId, edge.id);
    const targetNodeZones = matchingZones.filter((zone) => zone.nodeIds.includes(options.toNodeId));
    const candidates: Reservation[] = [
      this.createReservation({
        resourceType: 'edge',
        resourceId: edge.id,
        conflictGroup: edge.conflictGroup ?? null,
        reasonCode: 'edge-reservation',
        vehicleId: options.vehicleId,
        taskId: options.taskId,
        startTimeSec: options.startTimeSec,
        endTimeSec,
        priority: options.priority
      }),
      this.createReservation({
        resourceType: 'node',
        resourceId: options.toNodeId,
        conflictGroup: targetNodeZones[0]?.conflictGroup ?? null,
        reasonCode: 'node-reservation',
        vehicleId: options.vehicleId,
        taskId: options.taskId,
        startTimeSec: options.startTimeSec,
        endTimeSec,
        priority: options.priority
      })
    ];

    for (const zone of matchingZones) {
      candidates.push(
        this.createReservation({
          resourceType: 'zone',
          resourceId: zone.id,
          conflictGroup: zone.conflictGroup ?? null,
          reasonCode: 'zone-reservation',
          vehicleId: options.vehicleId,
          taskId: options.taskId,
          startTimeSec: options.startTimeSec,
          endTimeSec: conflictTokenEndTimeSec,
          priority: options.priority
        })
      );
    }

    if (options.ignoreConflicts !== true) {
      for (const candidate of candidates) {
        const conflict = options.existing.find((reservation) => this.conflicts(candidate, reservation));
        if (conflict) {
          return {
            ok: false,
            reasonCode: `${candidate.resourceType}-reserved`,
            blockingReservationId: conflict.id
          };
        }
      }
    }

    return { ok: true, reservations: candidates.map((reservation) => ReservationSchema.parse(reservation)) };
  }

  findEdge(fromNodeId: string, toNodeId: string): LayoutEdge | null {
    return this.edgesByPair.get(`${fromNodeId}->${toNodeId}`) ?? null;
  }

  zonesForMovement(fromNodeId: string, toNodeId: string, edgeId?: string): LayoutZone[] {
    const edge = edgeId
      ? this.edgesById.get(edgeId) ?? null
      : this.findEdge(fromNodeId, toNodeId);
    if (!edge) {
      return [];
    }

    return this.scenario.layout.zones
      .filter((zone) => {
        const crossesEdge = zone.edgeIds.includes(edge.id);
        const touchesEndpoint = zone.nodeIds.includes(fromNodeId) || zone.nodeIds.includes(toNodeId);
        const endpointAppliesToMovement = touchesEndpoint && (zone.edgeIds.length === 0 || crossesEdge);
        return crossesEdge || endpointAppliesToMovement;
      })
      .filter((zone, index, zones) => zones.findIndex((candidate) => candidate.id === zone.id) === index);
  }

  private createReservation(options: Omit<Reservation, 'id'>): Reservation {
    this.sequence += 1;
    return {
      id: `res-${String(this.sequence).padStart(6, '0')}`,
      ...options,
      startTimeSec: round(options.startTimeSec),
      endTimeSec: round(options.endTimeSec)
    };
  }

  private conflicts(candidate: Reservation, existing: Reservation): boolean {
    if (existing.vehicleId === candidate.vehicleId) {
      return false;
    }
    const sameResource = existing.resourceType === candidate.resourceType && existing.resourceId === candidate.resourceId;
    const sameConflictGroup =
      existing.conflictGroup !== null &&
      candidate.conflictGroup !== null &&
      existing.conflictGroup === candidate.conflictGroup &&
      existing.resourceType === candidate.resourceType &&
      existing.resourceType === 'zone';
    if (!sameResource && !sameConflictGroup) {
      return false;
    }

    return candidate.startTimeSec <= existing.endTimeSec + 1e-6 && existing.startTimeSec <= candidate.endTimeSec + 1e-6;
  }
}

type TheoreticalCapacitySnapshot = NonNullable<KpiSnapshot['theoreticalCapacity']>;
type TheoreticalCapacityBaseline = Omit<
  TheoreticalCapacitySnapshot,
  'achievedInboundPct' | 'achievedOutboundPct' | 'achievedTotalPct' | 'averageVehicleUtilizationPct'
>;
type TheoreticalCapacityBound = TheoreticalCapacitySnapshot['bounds'][number];

const theoreticalCapacityBaselineCache = new Map<string, TheoreticalCapacityBaseline>();

export class ShuttleSimCore {
  private scenario: ShuttleScenario;
  private sessionId: string = randomUUID();
  private traffic!: TrafficControllerV2;
  private rng!: Rng;
  private status: RuntimeStatus = 'idle';
  private simTimeSec = 0;
  private tickIndex = 0;
  private vehicles: MutableVehicle[] = [];
  private tasks: TaskStateRecord[] = [];
  private loads: LoadStateRecord[] = [];
  private tasksById = new Map<string, TaskStateRecord>();
  private loadsById = new Map<string, LoadStateRecord>();
  private activeTaskIds = new Set<string>();
  private queuedTaskIds = new Set<string>();
  private storedLoadIdByNodeId = new Map<string, string>();
  private storedNodeIdByLoadId = new Map<string, string>();
  private layoutNodesById = new Map<string, LayoutNode>();
  private layoutNodeIds = new Set<string>();
  private storageNodeIds: string[] = [];
  private storageNodeIdSet = new Set<string>();
  private storageGridPositionCache = new Map<string, { row: number; column: number } | null>();
  private inboundSourceSlotNodeIdsCache = new Map<string, string[]>();
  private topLiftInboundApproachQueueNodeIdsCache = new Map<string, string[]>();
  private topLiftQueueEntryAccessNodeIdCache = new Map<string, string | null>();
  private topLiftServiceStopLiftNodeIdCache = new Map<string, string | null>();
  private topLiftColumnNodesByLevelCache = new Map<TopLiftAisleLevel, ShuttleNode[]>();
  private topLiftRailNodeNearestToLiftCache = new Map<string, string | null>();
  private topLiftRailNodeNearestToLiftEdgeCache = new Map<string, string | null>();
  private liftPortKindForNodeIdCache = new Map<string, LiftKind | null>();
  private blockedStorageTransitBaseCache = new Map<string, Set<string>>();
  private reservations: Reservation[] = [];
  private currentNodeOccupancy = new Map<string, string>();
  private eventLog: EventLogEntry[] = [];
  private recentEvents: EventLogEntry[] = [];
  private eventSequence = 0;
  private taskSequence = 0;
  private sourceLoadSequence = 0;
  private nextInboundSec = 0;
  private nextOutboundSec = 0;
  private completedTaskCycleTimes: number[] = [];
  private completedTaskWaitTimes: number[] = [];
  private completedInbound = 0;
  private completedOutbound = 0;
  private completedByLiftPort = new Map<string, { kind: LiftKind; completed: number }>();
  private reservationConflictCount = 0;
  private replanCount = 0;
  private deadlockCount = 0;
  private livelockCount = 0;
  private movementContinuationDepth = 0;
  private deadlockCandidateSignature: string | null = null;
  private deadlockCandidateSinceSec: number | null = null;
  private blockedTimeByReasonSec = new Map<string, number>();
  private deferredTaskReasons: Record<'inbound' | 'outbound', string | null> = { inbound: null, outbound: null };
  private liftPortBusyTimeSec = new Map<string, number>();
  private neighborByNodeId = new Map<string, Array<{ nodeId: string; lengthM: number }>>();
  private theoreticalCapacityBaseline: TheoreticalCapacityBaseline | null = null;
  private diagnosticReadOnlyDepth = 0;
  private topLiftColumnRowsPerZoneCache: number | null = null;
  private topLiftStorageColumnNumbersCache: number[] | null = null;
  private topLiftStorageColumnNodeIdsCache = new Map<number, string[]>();
  private topLiftColumnFlowModes = new Map<number, TopLiftColumnFlowMode>();
  private conflictSessions: ConflictSessionV1[] = [];
  private error: string | null = null;

  constructor(scenario: ShuttleScenario = createDefaultShuttleScenario()) {
    this.scenario = ShuttleScenarioSchema.parse(scenario);
    assertNoVerticalStorageFootprintEdges(this.scenario);
    assertNoStaticObstacleFootprintViolations(this.scenario);
    this.reset(this.scenario.seed);
  }

  getScenario(): ShuttleScenario {
    return structuredClone(this.scenario);
  }

  setDurationSec(durationSec: number): ShuttleSimState {
    const nextDurationSec = Math.max(round(this.simTimeSec), round(durationSec));
    this.scenario = ShuttleScenarioSchema.parse({
      ...this.scenario,
      durationSec: nextDurationSec
    });
    if (this.status === 'completed' && this.simTimeSec < nextDurationSec - 1e-9) {
      this.status = 'paused';
    }
    return this.getState();
  }

  loadScenario(scenario: ShuttleScenario): ShuttleSimState {
    this.scenario = ShuttleScenarioSchema.parse(scenario);
    assertNoVerticalStorageFootprintEdges(this.scenario);
    assertNoStaticObstacleFootprintViolations(this.scenario);
    this.theoreticalCapacityBaseline = null;
    this.topLiftColumnRowsPerZoneCache = null;
    this.topLiftStorageColumnNumbersCache = null;
    this.topLiftStorageColumnNodeIdsCache = new Map();
    this.reset(this.scenario.seed);
    this.logEvent('scenario-loaded', null, null, null, null, null, 'loadScenario', null, { scenarioId: this.scenario.id });
    return this.getState();
  }

  reset(seed = this.scenario.seed): ShuttleSimState {
    this.status = 'idle';
    this.simTimeSec = 0;
    this.tickIndex = 0;
    this.tasks = [];
    this.loads = [];
    this.tasksById = new Map();
    this.loadsById = new Map();
    this.activeTaskIds = new Set();
    this.queuedTaskIds = new Set();
    this.storedLoadIdByNodeId = new Map();
    this.storedNodeIdByLoadId = new Map();
    this.reservations = [];
    this.currentNodeOccupancy = new Map();
    this.eventLog = [];
    this.recentEvents = [];
    this.eventSequence = 0;
    this.taskSequence = 0;
    this.sourceLoadSequence = 0;
    this.completedTaskCycleTimes = [];
    this.completedTaskWaitTimes = [];
    this.completedInbound = 0;
    this.completedOutbound = 0;
    this.completedByLiftPort = new Map();
    this.reservationConflictCount = 0;
    this.replanCount = 0;
    this.deadlockCount = 0;
    this.livelockCount = 0;
    this.deadlockCandidateSignature = null;
    this.deadlockCandidateSinceSec = null;
    this.blockedTimeByReasonSec = new Map();
    this.deferredTaskReasons = { inbound: null, outbound: null };
    this.liftPortBusyTimeSec = new Map();
    this.topLiftColumnFlowModes = new Map();
    this.conflictSessions = [];
    this.error = null;
    this.rng = makeRng(seed);
    this.scenario = { ...this.scenario, seed };
    this.rebuildLayoutIndexes();
    this.traffic = new TrafficControllerV2(this.scenario);
    this.rebuildGraphNeighbors();
    this.nextInboundSec = this.scenario.taskGeneration.inboundRatePerHour > 0 ? 0 : Infinity;
    this.nextOutboundSec = this.intervalForRate(this.scenario.taskGeneration.outboundRatePerHour) / 2;

    const parkingNodes = this.parkableNodeCandidates();
    this.vehicles = Array.from({ length: this.scenario.vehicles.count }, (_, index) => {
      const parking = parkingNodes[index] ?? this.scenario.layout.nodes[0]!;
      return {
        id: `SH-${String(index + 1).padStart(2, '0')}`,
        state: 'idle',
        x: parking.x,
        y: SHUTTLE_Y_M,
        z: parking.z,
        yaw: 0,
        speedMps: 0,
        loaded: false,
        taskId: null,
        targetNodeId: null,
        currentNodeId: parking.id,
        currentEdgeId: null,
        routeNodeIds: [],
        plannedGoalNodeId: null,
        plannedRouteNodeIds: [],
        localRouteNodeIds: [],
        localRouteReason: null,
        routeIndex: 0,
        legRemainingM: 0,
        legElapsedSec: 0,
        legTravelSec: 0,
        phaseRemainingSec: 0,
        waitReason: null,
        blockingReservationId: null,
        blockingVehicleId: null,
        blockedTimeSec: 0,
        idleTimeSec: 0,
        busyTimeSec: 0,
        targetSpeedMps: 0,
        waitingSinceSec: null,
        lastMovementAxis: null,
        directionSwitchReadyNodeId: null,
        legStartYaw: 0,
        legMotionMode: 'profile',
        movingTimeSec: 0,
        handlingTimeSec: 0,
        tasklessTravelTimeSec: 0,
        queueReserveTravelTimeSec: 0,
        yieldHoldUntilSec: null,
        yieldHoldNodeId: null,
        assignmentHoldUntilSec: null,
        inboundDropoffStandbyHoldUntilSec: null,
        recentOutboundClearanceRouteNodeIds: []
      };
    });
    if (this.mixedTopLiftFlowEnabled()) {
      for (const vehicle of this.vehicles) {
        if (this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId)) {
          vehicle.routeNodeIds = [vehicle.currentNodeId];
          vehicle.plannedGoalNodeId = vehicle.currentNodeId;
          vehicle.plannedRouteNodeIds = [vehicle.currentNodeId];
          vehicle.localRouteNodeIds = [];
          vehicle.localRouteReason = 'inbound-queue-standby';
        }
      }
    }
    for (const vehicle of this.vehicles) {
      if (!this.currentNodeOccupancy.has(vehicle.currentNodeId)) {
        this.currentNodeOccupancy.set(vehicle.currentNodeId, vehicle.id);
      }
    }

    this.logEvent('sim-reset', null, null, null, null, null, 'reset', null, { seed });
    this.primeTopLiftOutboundFullColumns();
    this.refreshTopLiftColumnFlowModes();
    this.primeInboundSourceBacklog();
    return this.getState();
  }

  start(): ShuttleSimState {
    if (this.status !== 'completed') {
      this.status = 'running';
      this.logEvent('sim-started', null, null, null, null, null, 'startRun', null, {});
    }
    return this.getState();
  }

  pause(): ShuttleSimState {
    if (this.status === 'running') {
      this.status = 'paused';
      this.logEvent('sim-paused', null, null, null, null, null, 'pause', null, {});
    }
    return this.getState();
  }

  resume(): ShuttleSimState {
    if (this.status === 'paused' || this.status === 'idle') {
      this.status = 'running';
      this.logEvent('sim-resumed', null, null, null, null, null, 'resume', null, {});
    }
    return this.getState();
  }

  setParam(path: string, value: unknown): SetParamResult {
    const previousScenario = this.scenario;
    const previousValue = getByPointer(previousScenario as unknown as Record<string, unknown>, path);
    if (
      path === COLLISION_AVOIDANCE_PARAM &&
      this.simTimeSec > 0 &&
      previousValue !== value
    ) {
      return {
        accepted: false,
        path,
        previousValue,
        value,
        reason: 'reset-required'
      };
    }
    const nextScenario = structuredClone(this.scenario) as ShuttleScenario;
    const result = setByPointer(nextScenario as unknown as Record<string, unknown>, path, value);
    if (!result.accepted) {
      return { accepted: false, path, previousValue: result.previousValue, value, reason: result.reason };
    }

    const parsed = ShuttleScenarioSchema.safeParse(nextScenario);
    if (!parsed.success) {
      return {
        accepted: false,
        path,
        previousValue: result.previousValue,
        value,
        reason: parsed.error.issues[0]?.message ?? 'Invalid scenario update'
      };
    }

    this.scenario = parsed.data;
    this.theoreticalCapacityBaseline = null;
    this.topLiftColumnRowsPerZoneCache = null;
    this.topLiftStorageColumnNumbersCache = null;
    this.topLiftStorageColumnNodeIdsCache = new Map();
    if (path.startsWith('/layout')) {
      this.rebuildLayoutIndexes();
      this.rebuildGraphNeighbors();
    }
    this.logEvent('param-updated', null, null, null, null, null, 'setParam', null, { path, value: String(value) });

    if (path === '/vehicles/count') {
      this.reset(this.scenario.seed);
    }

    return {
      accepted: true,
      path,
      previousValue: result.previousValue ?? previousValue,
      value
    };
  }

  getStatus(): ShuttleSimState['status'] {
    return this.status;
  }

  getClock(): { simTimeSec: number; tickIndex: number; status: ShuttleSimState['status'] } {
    return {
      simTimeSec: round(this.simTimeSec),
      tickIndex: this.tickIndex,
      status: this.status
    };
  }

  private stepInPlace(dtSec = this.scenario.timeStepSec): void {
    if (this.status === 'idle') {
      this.status = 'running';
    }

    if (this.status !== 'running') {
      return;
    }

    if (this.simTimeSec >= this.scenario.durationSec) {
      this.status = 'completed';
      this.logEvent('sim-completed', null, null, null, null, null, 'duration-reached', null, {});
      return;
    }

    const stepSec = Math.min(dtSec, this.scenario.durationSec - this.simTimeSec);
    this.simTimeSec = round(this.simTimeSec + stepSec);
    this.tickIndex += 1;
    this.reservations = this.reservations.filter((reservation) => reservation.endTimeSec >= this.simTimeSec - 1);

    this.replenishInboundSourceBuffers();
    this.generateDueTasks(stepSec);
    this.assignQueuedTasks(stepSec);
    this.advanceVehicles(stepSec);
    this.updateConflictSessions();
    this.clearInactiveLocalRouteClaims();
    // Keep this post-advance refill: vehicles can consume inbound source slots during the tick,
    // and moving it changes deterministic event/state hashes.
    this.replenishInboundSourceBuffers();
    this.updateLiftPortUtilization(stepSec);
    this.updateDeadlockSmokeCounters();

    if (this.simTimeSec >= this.scenario.durationSec) {
      this.status = 'completed';
      this.logEvent('sim-completed', null, null, null, null, null, 'duration-reached', null, {});
    }
  }

  step(dtSec = this.scenario.timeStepSec): ShuttleSimState {
    this.stepInPlace(dtSec);
    return this.getState();
  }

  advanceByInPlace(dtSec: number): void {
    const maxStepSec = Math.max(0.001, this.scenario.timeStepSec);
    let remainingSec = dtSec;
    while (remainingSec > 1e-9 && this.status === 'running') {
      const stepSec = Math.min(maxStepSec, remainingSec);
      this.stepInPlace(stepSec);
      remainingSec -= stepSec;
    }
  }

  advanceBy(dtSec: number): ShuttleSimState {
    this.advanceByInPlace(dtSec);
    return this.getState();
  }

  runToEnd(durationSec = this.scenario.durationSec): ShuttleSimState {
    if (durationSec !== this.scenario.durationSec) {
      this.scenario = { ...this.scenario, durationSec };
    }
    this.start();
    while (this.status === 'running') {
      this.stepInPlace(this.scenario.timeStepSec);
    }
    return this.getState();
  }

  getState(): ShuttleSimState {
    this.diagnosticReadOnlyDepth += 1;
    try {
      return {
        schemaVersion: 'shuttle.phase0.state.v0',
        scenarioId: this.scenario.id,
        sessionId: this.sessionId,
        status: this.status,
        simTimeSec: round(this.simTimeSec),
        durationSec: this.scenario.durationSec,
        seed: this.scenario.seed,
        vehicles: this.vehicles.map((vehicle) => this.publicVehicle(vehicle)),
        tasks: structuredClone(this.tasks),
        loads: structuredClone(this.loads),
        reservations: structuredClone(this.reservations),
        traffic: this.calculateTrafficDiagnostics(),
        kpis: this.calculateKpis(),
        recentEvents: structuredClone(this.recentEvents),
        error: this.error
      };
    } finally {
      this.diagnosticReadOnlyDepth -= 1;
    }
  }

  getEventLog(): EventLogEntry[] {
    return structuredClone(this.eventLog);
  }

  retainRecentEventLog(maxEvents: number): void {
    const retainedEvents = Math.max(0, Math.floor(maxEvents));
    if (retainedEvents === 0) {
      this.eventLog = [];
      return;
    }
    if (this.eventLog.length > retainedEvents) {
      this.eventLog = this.eventLog.slice(-retainedEvents);
    }
  }

  getDebugState(): ShuttleSimDebugState {
    return {
      currentNodeOccupancy: [...this.currentNodeOccupancy.entries()]
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([nodeId, vehicleId]) => ({ nodeId, vehicleId })),
      storageNodeOccupancy: [...this.storageNodeLoadOccupancy(true).entries()]
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([nodeId, loadId]) => ({ nodeId, loadId }))
    };
  }

  createSnapshot(): ShuttleEngineSnapshotV1 {
    const debugState = this.getDebugState();
    const snapshotWithoutHash: Omit<ShuttleEngineSnapshotV1, 'stateHash'> = {
      schemaVersion: 'shuttle.engineSnapshot.v1',
      simTimeSec: round(this.simTimeSec),
      tickIndex: this.tickIndex,
      status: this.status,
      sessionId: this.sessionId,
      rngState: this.rng.getState(),
      eventSequence: this.eventSequence,
      taskSequence: this.taskSequence,
      sourceLoadSequence: this.sourceLoadSequence,
      nextInboundSec: Number.isFinite(this.nextInboundSec) ? this.nextInboundSec : null,
      nextOutboundSec: Number.isFinite(this.nextOutboundSec) ? this.nextOutboundSec : null,
      vehicles: structuredClone(this.vehicles),
      tasks: structuredClone(this.tasks),
      loads: structuredClone(this.loads),
      reservations: structuredClone(this.reservations),
      completedTaskCycleTimes: [...this.completedTaskCycleTimes],
      completedTaskWaitTimes: [...this.completedTaskWaitTimes],
      completedInbound: this.completedInbound,
      completedOutbound: this.completedOutbound,
      completedByLiftPort: [...this.completedByLiftPort.entries()].sort(([left], [right]) => left.localeCompare(right)),
      reservationConflictCount: this.reservationConflictCount,
      replanCount: this.replanCount,
      deadlockCount: this.deadlockCount,
      livelockCount: this.livelockCount,
      deadlockCandidateSignature: this.deadlockCandidateSignature,
      deadlockCandidateSinceSec: this.deadlockCandidateSinceSec,
      blockedTimeByReasonSec: [...this.blockedTimeByReasonSec.entries()].sort(([left], [right]) => left.localeCompare(right)),
      deferredTaskReasons: { ...this.deferredTaskReasons },
      liftPortBusyTimeSec: [...this.liftPortBusyTimeSec.entries()].sort(([left], [right]) => left.localeCompare(right)),
      currentNodeOccupancy: debugState.currentNodeOccupancy,
      storageNodeOccupancy: debugState.storageNodeOccupancy,
      conflictSessions: structuredClone(this.conflictSessions),
      recentEvents: structuredClone(this.recentEvents),
      eventLog: structuredClone(this.eventLog),
      error: this.error,
      eventLogHash: hashEventLog(this.eventLog)
    };
    return {
      ...snapshotWithoutHash,
      stateHash: hashEngineSnapshot(snapshotWithoutHash)
    };
  }

  restoreSnapshot(snapshot: ShuttleEngineSnapshotV1): ShuttleSimState {
    if (snapshot.schemaVersion !== 'shuttle.engineSnapshot.v1') {
      throw new Error(`Unsupported engine snapshot schema ${String((snapshot as { schemaVersion?: unknown }).schemaVersion)}`);
    }
    const expectedHash = hashEngineSnapshot(snapshot);
    if (snapshot.stateHash && expectedHash !== snapshot.stateHash) {
      throw new Error(`Snapshot state hash mismatch: expected ${snapshot.stateHash}, got ${expectedHash}`);
    }

    this.status = snapshot.status;
    this.simTimeSec = snapshot.simTimeSec;
    this.tickIndex = snapshot.tickIndex;
    this.sessionId = snapshot.sessionId;
    this.rng.setState(snapshot.rngState);
    this.eventSequence = snapshot.eventSequence;
    this.taskSequence = snapshot.taskSequence;
    this.sourceLoadSequence = snapshot.sourceLoadSequence;
    this.nextInboundSec = snapshot.nextInboundSec ?? Infinity;
    this.nextOutboundSec = snapshot.nextOutboundSec ?? Infinity;
    this.vehicles = structuredClone(snapshot.vehicles).map((vehicle) => ({
      ...vehicle,
      legStartYaw: Number.isFinite(vehicle.legStartYaw) ? vehicle.legStartYaw : vehicle.yaw,
      queueReserveTravelTimeSec: vehicle.queueReserveTravelTimeSec ?? 0,
      assignmentHoldUntilSec: vehicle.assignmentHoldUntilSec ?? null,
      inboundDropoffStandbyHoldUntilSec: vehicle.inboundDropoffStandbyHoldUntilSec ?? null,
      recentOutboundClearanceRouteNodeIds: vehicle.recentOutboundClearanceRouteNodeIds ?? []
    }));
    this.tasks = structuredClone(snapshot.tasks);
    this.loads = structuredClone(snapshot.loads);
    this.rebuildLayoutIndexes();
    this.rebuildTaskLoadIndexes();
    this.reservations = structuredClone(snapshot.reservations);
    this.completedTaskCycleTimes = [...snapshot.completedTaskCycleTimes];
    this.completedTaskWaitTimes = [...snapshot.completedTaskWaitTimes];
    this.completedInbound = snapshot.completedInbound;
    this.completedOutbound = snapshot.completedOutbound;
    this.completedByLiftPort = new Map(snapshot.completedByLiftPort ?? []);
    this.reservationConflictCount = snapshot.reservationConflictCount;
    this.replanCount = snapshot.replanCount;
    this.deadlockCount = snapshot.deadlockCount;
    this.livelockCount = snapshot.livelockCount;
    this.deadlockCandidateSignature = snapshot.deadlockCandidateSignature;
    this.deadlockCandidateSinceSec = snapshot.deadlockCandidateSinceSec;
    this.blockedTimeByReasonSec = new Map(snapshot.blockedTimeByReasonSec);
    this.deferredTaskReasons = { ...snapshot.deferredTaskReasons };
    this.liftPortBusyTimeSec = new Map(snapshot.liftPortBusyTimeSec);
    this.currentNodeOccupancy = new Map(snapshot.currentNodeOccupancy.map((entry) => [entry.nodeId, entry.vehicleId]));
    this.rebuildTopLiftColumnFlowModesFromState();
    this.conflictSessions = structuredClone(snapshot.conflictSessions ?? []);
    this.recentEvents = structuredClone(snapshot.recentEvents);
    this.eventLog = structuredClone(snapshot.eventLog);
    this.error = snapshot.error;
    this.traffic = new TrafficControllerV2(this.scenario);
    this.rebuildGraphNeighbors();
    return this.getState();
  }

  private rebuildLayoutIndexes(): void {
    this.layoutNodesById = new Map(this.scenario.layout.nodes.map((node) => [node.id, node]));
    this.layoutNodeIds = new Set(this.layoutNodesById.keys());
    this.storageNodeIds = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .map((node) => node.id);
    this.storageNodeIdSet = new Set(this.storageNodeIds);
    this.storageGridPositionCache = new Map();
    this.inboundSourceSlotNodeIdsCache = new Map();
    this.topLiftInboundApproachQueueNodeIdsCache = new Map();
    this.topLiftQueueEntryAccessNodeIdCache = new Map();
    this.topLiftServiceStopLiftNodeIdCache = new Map();
    this.topLiftColumnNodesByLevelCache = new Map();
    this.topLiftRailNodeNearestToLiftCache = new Map();
    this.topLiftRailNodeNearestToLiftEdgeCache = new Map();
    this.liftPortKindForNodeIdCache = new Map();
    this.blockedStorageTransitBaseCache = new Map();
  }

  private rebuildTaskLoadIndexes(): void {
    this.tasksById = new Map(this.tasks.map((task) => [task.id, task]));
    this.loadsById = new Map(this.loads.map((load) => [load.id, load]));
    this.storedLoadIdByNodeId = new Map();
    this.storedNodeIdByLoadId = new Map();
    this.activeTaskIds = new Set();
    this.queuedTaskIds = new Set();
    for (const task of this.tasks) {
      this.trackTaskIndexes(task);
    }
    for (const load of this.loads) {
      this.trackLoadIndexes(load);
    }
  }

  private pushTask(task: TaskStateRecord): TaskStateRecord {
    this.tasks.push(task);
    this.tasksById.set(task.id, task);
    this.trackTaskIndexes(task);
    return task;
  }

  private taskIsActive(task: TaskStateRecord): boolean {
    return task.state !== 'completed' && task.state !== 'failed';
  }

  private trackTaskIndexes(task: TaskStateRecord): void {
    if (this.taskIsActive(task)) {
      this.activeTaskIds.add(task.id);
    } else {
      this.activeTaskIds.delete(task.id);
    }

    if (task.state === 'queued') {
      this.queuedTaskIds.add(task.id);
    } else {
      this.queuedTaskIds.delete(task.id);
    }
  }

  private setTaskState(task: TaskStateRecord, state: TaskStateRecord['state']): void {
    task.state = state;
    this.trackTaskIndexes(task);
  }

  private activeTasks(): TaskStateRecord[] {
    const tasks: TaskStateRecord[] = [];
    for (const taskId of this.activeTaskIds) {
      const task = this.tasksById.get(taskId);
      if (!task || !this.taskIsActive(task)) {
        this.activeTaskIds.delete(taskId);
        this.queuedTaskIds.delete(taskId);
        continue;
      }
      tasks.push(task);
    }
    return tasks;
  }

  private queuedTasks(): TaskStateRecord[] {
    const tasks: TaskStateRecord[] = [];
    for (const taskId of this.queuedTaskIds) {
      const task = this.tasksById.get(taskId);
      if (!task || task.state !== 'queued') {
        this.queuedTaskIds.delete(taskId);
        if (task && !this.taskIsActive(task)) {
          this.activeTaskIds.delete(taskId);
        }
        continue;
      }
      tasks.push(task);
    }
    return tasks;
  }

  private pushLoad(load: LoadStateRecord): LoadStateRecord {
    this.loads.push(load);
    this.loadsById.set(load.id, load);
    this.trackLoadIndexes(load);
    return load;
  }

  private trackLoadIndexes(load: LoadStateRecord): void {
    const previousStoredNodeId = this.storedNodeIdByLoadId.get(load.id);
    if (previousStoredNodeId && (previousStoredNodeId !== load.nodeId || load.state !== 'stored')) {
      if (this.storedLoadIdByNodeId.get(previousStoredNodeId) === load.id) {
        this.storedLoadIdByNodeId.delete(previousStoredNodeId);
      }
      this.storedNodeIdByLoadId.delete(load.id);
    }
    if (load.state === 'stored' && load.nodeId && this.isStorageNode(load.nodeId)) {
      this.storedLoadIdByNodeId.set(load.nodeId, load.id);
      this.storedNodeIdByLoadId.set(load.id, load.nodeId);
    }
  }

  private setLoadPlacement(
    load: LoadStateRecord,
    state: LoadStateRecord['state'],
    nodeId: string | null,
    vehicleId: string | null
  ): void {
    load.state = state;
    load.nodeId = nodeId;
    load.vehicleId = vehicleId;
    this.trackLoadIndexes(load);
  }

  private taskById(taskId: string | null | undefined): TaskStateRecord | null {
    return taskId ? this.tasksById.get(taskId) ?? null : null;
  }

  private loadById(loadId: string | null | undefined): LoadStateRecord | null {
    return loadId ? this.loadsById.get(loadId) ?? null : null;
  }

  setVehicleRouteForTest(vehicleId: string, routeNodeIds: string[]): ShuttleSimState {
    const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId);
    if (!vehicle) {
      throw new Error(`Unknown vehicle ${vehicleId}`);
    }
    if (routeNodeIds.length < 1) {
      throw new Error('Test route must include at least one node');
    }
    for (const nodeId of routeNodeIds) {
      nodePosition(this.scenario, nodeId);
    }
    for (const [nodeId, occupantId] of [...this.currentNodeOccupancy.entries()]) {
      if (occupantId === vehicle.id) {
        this.currentNodeOccupancy.delete(nodeId);
        this.releaseZoneHoldReservations(vehicle);
      }
    }
    const startPosition = nodePosition(this.scenario, routeNodeIds[0]!);
    vehicle.x = startPosition.x;
    vehicle.y = SHUTTLE_Y_M;
    vehicle.z = startPosition.z;
    vehicle.yaw = 0;
    vehicle.speedMps = 0;
    vehicle.loaded = false;
    vehicle.taskId = null;
    vehicle.currentNodeId = routeNodeIds[0]!;
    vehicle.currentEdgeId = null;
    vehicle.routeNodeIds = [...routeNodeIds];
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.phaseRemainingSec = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.targetSpeedMps = 0;
    vehicle.lastMovementAxis = null;
    vehicle.directionSwitchReadyNodeId = null;
    vehicle.legStartYaw = vehicle.yaw;
    vehicle.legMotionMode = 'profile';
    vehicle.movingTimeSec = 0;
    vehicle.handlingTimeSec = 0;
    vehicle.tasklessTravelTimeSec = 0;
    vehicle.queueReserveTravelTimeSec = 0;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.assignmentHoldUntilSec = null;
    vehicle.recentOutboundClearanceRouteNodeIds = [];
    vehicle.plannedGoalNodeId = null;
    vehicle.plannedRouteNodeIds = [];
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
    vehicle.state = routeNodeIds.length > 1 ? 'assigned' : 'idle';
    this.currentNodeOccupancy.set(vehicle.currentNodeId, vehicle.id);
    this.ensureZoneHoldReservation(vehicle, vehicle.currentNodeId);
    return this.getState();
  }

  addReservationForTest(reservation: Omit<Reservation, 'id'> & { id?: string }): ShuttleSimState {
    const id = reservation.id ?? `test-res-${String(this.reservations.length + 1).padStart(4, '0')}`;
    this.reservations.push(ReservationSchema.parse({ ...reservation, id }));
    return this.getState();
  }

  installMoveReservationsForTest(vehicleId: string, reservations: Reservation[]): MoveReservationInstall {
    const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId);
    if (!vehicle) {
      throw new Error(`Unknown vehicle ${vehicleId}`);
    }
    const install = this.installMoveReservationsReplacingSelfOverlap(vehicle, reservations);
    return structuredClone(install);
  }

  rollbackMoveReservationsForTest(install: MoveReservationInstall): ShuttleSimState {
    this.rollbackMoveReservationInstall(install.installed, install.removed);
    return this.getState();
  }

  setVehicleWaitingForTest(vehicleId: string, options: {
    targetNodeId: string | null;
    waitReason: string;
    blockingVehicleId?: string | null;
    blockingReservationId?: string | null;
    waitingSinceSec?: number;
  }): ShuttleSimState {
    const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId);
    if (!vehicle) {
      throw new Error(`Unknown vehicle ${vehicleId}`);
    }
    vehicle.state = 'waiting-blocked';
    vehicle.targetNodeId = options.targetNodeId;
    vehicle.waitReason = options.waitReason;
    vehicle.blockingVehicleId = options.blockingVehicleId ?? null;
    vehicle.blockingReservationId = options.blockingReservationId ?? null;
    vehicle.waitingSinceSec = options.waitingSinceSec ?? this.simTimeSec;
    return this.getState();
  }

  addLoadForTest(load: LoadStateRecord): ShuttleSimState {
    this.pushLoad(LoadStateRecordSchema.parse(load));
    return this.getState();
  }

  addTaskForTest(task: TaskStateRecord): ShuttleSimState {
    this.pushTask(TaskStateRecordSchema.parse(task));
    return this.getState();
  }

  setVehicleTaskForTest(vehicleId: string, taskId: string | null, loaded: boolean): ShuttleSimState {
    const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId);
    if (!vehicle) {
      throw new Error(`Unknown vehicle ${vehicleId}`);
    }
    vehicle.taskId = taskId;
    vehicle.loaded = loaded;
    vehicle.state = taskId ? 'assigned' : vehicle.routeNodeIds.length > 1 ? 'assigned' : 'idle';
    return this.getState();
  }

  private intervalForRate(ratePerHour: number): number {
    if (ratePerHour <= 0) {
      return Number.POSITIVE_INFINITY;
    }
    return 3600 / ratePerHour;
  }

  private generateDueTasks(dtSec: number): void {
    if (this.activeTaskCount() >= this.scenario.taskGeneration.maxTasks) {
      return;
    }

    while (this.simTimeSec >= this.nextInboundSec && this.activeTaskCount() < this.scenario.taskGeneration.maxTasks) {
      const result = this.createTask('inbound');
      if (!result.created) {
        this.deferTask('inbound', result.reason, dtSec);
        this.nextInboundSec = this.simTimeSec + this.scenario.timeStepSec;
        break;
      }
      this.deferredTaskReasons.inbound = null;
      this.nextInboundSec += this.nextArrivalInterval('inbound');
    }

    while (this.simTimeSec >= this.nextOutboundSec && this.activeTaskCount() < this.scenario.taskGeneration.maxTasks) {
      const result = this.createTask('outbound');
      if (!result.created) {
        this.deferTask('outbound', result.reason, dtSec);
        this.nextOutboundSec = this.simTimeSec + this.scenario.timeStepSec;
        break;
      }
      this.deferredTaskReasons.outbound = null;
      this.nextOutboundSec += this.nextArrivalInterval('outbound');
    }
  }

  private activeTaskCount(): number {
    return this.activeTasks().length;
  }

  private nextArrivalInterval(kind: 'inbound' | 'outbound'): number {
    const rate = kind === 'inbound' ? this.scenario.taskGeneration.inboundRatePerHour : this.scenario.taskGeneration.outboundRatePerHour;
    const deterministic = this.intervalForRate(rate);
    if (this.scenario.taskGeneration.arrivalDistribution === 'deterministic') {
      return deterministic;
    }
    const u = Math.max(1e-9, 1 - this.rng.next());
    return -Math.log(u) * deterministic;
  }

  private createTask(kind: 'inbound' | 'outbound'): { created: true } | { created: false; reason: string } {
    this.refreshTopLiftColumnFlowModes();
    const topLiftInboundSelection = kind === 'inbound' && this.topLiftColumnLayoutEnabled()
      ? this.selectTopLiftInboundTaskSelection()
      : null;
    const topLiftOutboundSelection = kind === 'outbound' && this.topLiftColumnLayoutEnabled()
      ? this.selectTopLiftOutboundTaskSelection()
      : null;
    if (topLiftInboundSelection && 'reason' in topLiftInboundSelection) {
      return { created: false, reason: topLiftInboundSelection.reason };
    }
    if (topLiftOutboundSelection && 'reason' in topLiftOutboundSelection) {
      return { created: false, reason: topLiftOutboundSelection.reason };
    }
    const storageSelection = topLiftInboundSelection ?? topLiftOutboundSelection ?? (kind === 'inbound' ? this.selectInboundStorageNode() : this.selectOutboundLoad());
    if (!storageSelection) {
      return { created: false, reason: kind === 'inbound' ? 'storage-full' : 'storage-empty' };
    }

    const inboundSourceSelection = kind === 'inbound'
      ? topLiftInboundSelection
        ? { liftNodeId: topLiftInboundSelection.liftNodeId, loadId: topLiftInboundSelection.loadId }
        : this.selectInboundSourceLoadForTask(storageSelection.nodeId)
      : null;
    const liftNodeId = kind === 'inbound'
      ? inboundSourceSelection?.liftNodeId ?? null
      : topLiftOutboundSelection && 'liftNodeId' in topLiftOutboundSelection
        ? topLiftOutboundSelection.liftNodeId
        : this.selectLiftPortNodeId(kind, storageSelection.nodeId);
    if (!liftNodeId) {
      return { created: false, reason: kind === 'inbound' ? this.inboundSourceUnavailableReason() : 'outbound-lift-unavailable' };
    }

    this.taskSequence += 1;
    const taskId = `task-${String(this.taskSequence).padStart(4, '0')}`;
    const loadId = kind === 'inbound' ? inboundSourceSelection!.loadId : storageSelection.loadId;
    const pickupNodeId = kind === 'inbound' ? this.inboundSourcePickupNodeId(liftNodeId) : storageSelection.nodeId;
    const dropoffNodeId = kind === 'inbound' ? storageSelection.nodeId : this.outboundSinkDropoffNodeId(liftNodeId);
    const task: TaskStateRecord = {
      id: taskId,
      kind,
      state: 'queued',
      createdAtSec: this.simTimeSec,
      assignedAtSec: null,
      startedAtSec: null,
      completedAtSec: null,
      pickupNodeId,
      dropoffNodeId,
      loadId,
      vehicleId: null,
      replanCount: 0,
      waitReason: null
    };
    this.pushTask(task);
    this.logEvent('task-created', null, task.id, loadId, null, pickupNodeId, 'task-generation', nodePosition(this.scenario, pickupNodeId), {
      kind,
      fifoNodeId: storageSelection.nodeId
    });
    return { created: true };
  }

  private selectTopLiftInboundTaskSelection(): { nodeId: string; liftNodeId: string; loadId: string } | { reason: string } {
    for (const liftNode of this.inboundLiftNodes()) {
      this.compactInboundSourceBuffer(liftNode.id);
    }

    const assignedLoadIds = this.activeInboundSourceLoadIds();
    const sourceCandidates = this.inboundLiftNodes()
      .filter((liftNode) =>
        this.liftPortPlannedLoad('inbound', liftNode.id) < this.topLiftPortStagedTaskCapacity('inbound', liftNode.id)
      )
      .flatMap((liftNode) => {
        return this.inboundLiftWaitingSourceLoads(liftNode.id)
          .filter((sourceLoad) => !assignedLoadIds.has(sourceLoad.id))
          .sort((left, right) => this.inboundSourceSlotRank(liftNode.id, right.nodeId) - this.inboundSourceSlotRank(liftNode.id, left.nodeId))
          .map((sourceLoad, sourceIndex) => ({
            liftNodeId: liftNode.id,
            loadId: sourceLoad.id,
            plannedLoad: this.liftPortPlannedLoad('inbound', liftNode.id),
            sourceIndex
          }));
      })
      .sort((left, right) =>
        left.plannedLoad - right.plannedLoad ||
        left.sourceIndex - right.sourceIndex ||
        left.liftNodeId.localeCompare(right.liftNodeId)
      );

    if (sourceCandidates.length === 0) {
      return { reason: this.inboundSourceUnavailableReason() };
    }

    for (const source of sourceCandidates) {
      const nodeId = this.selectTopLiftInboundStorageNodeForLift(source.liftNodeId);
      if (nodeId) {
        return { nodeId, liftNodeId: source.liftNodeId, loadId: source.loadId };
      }
    }

    return { reason: 'storage-full' };
  }

  private selectLiftPortNodeId(kind: 'inbound' | 'outbound', relatedNodeId: string): string | null {
    const fallbackNodeId = this.scenario.layout.nodes.find((node) => node.type === kind)?.id ?? relatedNodeId;
    const relatedNode = this.scenario.layout.nodes.find((node) => node.id === relatedNodeId);
    const liftNodes = this.scenario.layout.nodes
      .filter((node) => liftKindForNode(node) === kind)
      .filter((node) => kind !== 'inbound' || !this.inboundLiftHasWaitingSourceLoad(node.id))
      .filter((node) => !this.topLiftColumnLayoutEnabled() || this.liftPortPlannedLoad(kind, node.id) < this.topLiftPortStagedTaskCapacity(kind, node.id))
      .sort((left, right) => {
        const leftPlannedLoad = this.liftPortPlannedLoad(kind, left.id);
        const rightPlannedLoad = this.liftPortPlannedLoad(kind, right.id);
        if (leftPlannedLoad !== rightPlannedLoad) {
          return leftPlannedLoad - rightPlannedLoad;
        }
        const leftDistance = relatedNode ? Math.abs(left.z - relatedNode.z) + Math.abs(left.x - relatedNode.x) : 0;
        const rightDistance = relatedNode ? Math.abs(right.z - relatedNode.z) + Math.abs(right.x - relatedNode.x) : 0;
        return leftDistance - rightDistance || left.id.localeCompare(right.id);
      });
    if (liftNodes.length > 0) {
      return liftNodes[0]!.id;
    }
    return kind === 'inbound' ? null : fallbackNodeId;
  }

  private replenishInboundSourceBuffers(): void {
    if (this.scenario.taskGeneration.inboundRatePerHour <= 0) {
      return;
    }

    for (const liftNode of this.inboundLiftNodes()) {
      this.compactInboundSourceBuffer(liftNode.id);
      const capacity = this.inboundSourceBufferCapacity(liftNode.id);
      while (this.inboundLiftWaitingSourceLoads(liftNode.id).length < capacity) {
        const slotNodeId = this.nextInboundSourceSlotNodeId(liftNode.id);
        this.sourceLoadSequence += 1;
        const load: LoadStateRecord = {
          id: `source-load-${String(this.sourceLoadSequence).padStart(5, '0')}`,
          state: 'waiting',
          nodeId: slotNodeId,
          vehicleId: null,
          weightKg: 450 + Math.round(this.rng.next() * 350)
        };
        this.pushLoad(load);
        this.logEvent('source-load-replenished', null, null, load.id, null, liftNode.id, 'inbound-source-buffer-refill', nodePosition(this.scenario, slotNodeId), {
          sourceSlotNodeId: slotNodeId,
          sourceBufferOccupancy: this.inboundLiftWaitingSourceLoads(liftNode.id).length,
          sourceBufferCapacity: capacity
        });
        this.compactInboundSourceBuffer(liftNode.id);
      }
    }
  }

  private selectInboundSourceLoadForTask(relatedNodeId: string): { liftNodeId: string; loadId: string } | null {
    for (const liftNode of this.inboundLiftNodes()) {
      this.compactInboundSourceBuffer(liftNode.id);
    }
    const assignedLoadIds = this.activeInboundSourceLoadIds();
    const relatedNode = this.scenario.layout.nodes.find((node) => node.id === relatedNodeId);
    const candidates = this.inboundLiftNodes()
      .flatMap((liftNode) => {
        const pickupNodeId = this.inboundSourceFrontBufferNodeId(liftNode.id);
        const sourceLoads = this.inboundLiftWaitingSourceLoads(liftNode.id)
          .filter((sourceLoad) => sourceLoad.nodeId === pickupNodeId && !assignedLoadIds.has(sourceLoad.id));
        return sourceLoads.map((sourceLoad, sourceIndex) => ({
              liftNodeId: liftNode.id,
              loadId: sourceLoad.id,
              plannedLoad: this.liftPortPlannedLoad('inbound', liftNode.id),
              sourceIndex,
              distanceM: relatedNode ? Math.abs(liftNode.z - relatedNode.z) + Math.abs(liftNode.x - relatedNode.x) : 0
            }));
      })
      .sort((left, right) =>
        left.plannedLoad - right.plannedLoad ||
        left.sourceIndex - right.sourceIndex ||
        left.distanceM - right.distanceM ||
        left.liftNodeId.localeCompare(right.liftNodeId)
      );
    return candidates[0] ? { liftNodeId: candidates[0].liftNodeId, loadId: candidates[0].loadId } : null;
  }

  private activeInboundSourceLoadIds(): Set<string> {
    return new Set(
      this.activeTasks()
        .filter((task) => task.kind === 'inbound')
        .map((task) => task.loadId)
    );
  }

  private compactInboundSourceBuffer(liftNodeId: string): void {
    if (this.diagnosticReadOnlyDepth > 0 || !this.topLiftColumnLayoutEnabled()) {
      return;
    }
    const slotNodeIds = this.inboundSourceSlotNodeIds(liftNodeId);
    if (slotNodeIds.length < 2) {
      return;
    }
    const slotOrder = new Map(slotNodeIds.map((nodeId, index) => [nodeId, index]));
    const targetSlotsFrontFirst = [...slotNodeIds].reverse();
    const waitingLoadsFrontFirst = this.loads
      .filter((load) =>
        load.state === 'waiting' &&
        load.nodeId !== null &&
        slotOrder.has(load.nodeId) &&
        load.vehicleId === null
      )
      .sort((left, right) =>
        (slotOrder.get(right.nodeId!) ?? Number.MIN_SAFE_INTEGER) - (slotOrder.get(left.nodeId!) ?? Number.MIN_SAFE_INTEGER) ||
        left.id.localeCompare(right.id)
      );
    for (let index = 0; index < waitingLoadsFrontFirst.length && index < targetSlotsFrontFirst.length; index += 1) {
      waitingLoadsFrontFirst[index]!.nodeId = targetSlotsFrontFirst[index]!;
    }
  }

  private inboundSourceSlotRank(liftNodeId: string, nodeId: string | null): number {
    if (!nodeId) {
      return -1;
    }
    return this.inboundSourceSlotNodeIds(liftNodeId).indexOf(nodeId);
  }

  private inboundLiftWaitingSourceLoads(liftNodeId: string): LoadStateRecord[] {
    const slotNodeIds = this.inboundSourceSlotNodeIds(liftNodeId);
    const slotOrder = new Map(slotNodeIds.map((nodeId, index) => [nodeId, index]));
    return this.loads
      .filter((load) => load.state === 'waiting' && load.nodeId !== null && slotOrder.has(load.nodeId) && load.vehicleId === null)
      .sort((left, right) =>
        (slotOrder.get(left.nodeId!) ?? Number.MAX_SAFE_INTEGER) - (slotOrder.get(right.nodeId!) ?? Number.MAX_SAFE_INTEGER) ||
        left.id.localeCompare(right.id)
      );
  }

  private inboundLiftWaitingSourceLoad(liftNodeId: string): LoadStateRecord | null {
    return this.inboundLiftWaitingSourceLoads(liftNodeId)[0] ?? null;
  }

  private inboundSourceSlotNodeIds(liftNodeId: string): string[] {
    if (!this.topLiftColumnLayoutEnabled()) {
      return [liftNodeId];
    }
    const cached = this.inboundSourceSlotNodeIdsCache.get(liftNodeId);
    if (cached) {
      return cached;
    }
    const bufferNodeIds = Array.from({ length: Math.max(0, this.scenario.trafficPolicy.sourceBufferCapacity - 1) }, (_, index) =>
      liftBufferNodeId(liftNodeId, index + 1)
    ).filter((nodeId) => this.layoutNodeIds.has(nodeId));
    const slotNodeIds = [liftNodeId, ...bufferNodeIds];
    this.inboundSourceSlotNodeIdsCache.set(liftNodeId, slotNodeIds);
    return slotNodeIds;
  }

  private inboundSourcePickupNodeId(liftNodeId: string): string {
    if (!this.topLiftColumnLayoutEnabled()) {
      return liftNodeId;
    }
    return this.topLiftInboundPickupStopNodeId(liftNodeId) ?? this.inboundSourceFrontBufferNodeId(liftNodeId);
  }

  private inboundSourceFrontBufferNodeId(liftNodeId: string): string {
    if (!this.topLiftColumnLayoutEnabled()) {
      return liftNodeId;
    }
    return this.inboundSourceSlotNodeIds(liftNodeId).at(-1) ?? liftNodeId;
  }

  private liftBufferNodeIds(liftNodeId: string): string[] {
    return this.scenario.layout.nodes
      .map((node) => ({ nodeId: node.id, parent: liftBufferParentNodeId(node.id) }))
      .filter((entry): entry is { nodeId: string; parent: { liftNodeId: string; kind: LiftKind; slotIndex: number } } =>
        entry.parent?.liftNodeId === liftNodeId
      )
      .sort((left, right) => left.parent.slotIndex - right.parent.slotIndex)
      .map((entry) => entry.nodeId);
  }

  private outboundSinkDropoffNodeId(liftNodeId: string): string {
    if (!this.topLiftColumnLayoutEnabled()) {
      return liftNodeId;
    }
    const dropoffStopNodeId = this.topLiftOutboundDropoffStopNodeId(liftNodeId);
    if (dropoffStopNodeId) {
      return dropoffStopNodeId;
    }
    return this.liftBufferNodeIds(liftNodeId).at(-1) ?? liftNodeId;
  }

  private topLiftInboundPickupStopNodeId(liftNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled() || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return null;
    }
    return this.topLiftRailNodeNearestToLiftEdge(liftNodeId, 'top-a') ?? this.topLiftDockRailNodeId(liftNodeId);
  }

  private topLiftOutboundDropoffStopNodeId(liftNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled() || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
      return null;
    }
    return this.topLiftDockRailNodeId(liftNodeId);
  }

  private topLiftDockRailNodeId(liftNodeId: string): string | null {
    const kind = this.liftPortKindForNodeId(liftNodeId);
    if (kind !== 'inbound' && kind !== 'outbound') {
      return null;
    }
    const level: TopLiftAisleLevel = kind === 'inbound' ? 'top-b' : 'bottom-b';
    return this.topLiftRailNodeNearestToLift(liftNodeId, level);
  }

  private topLiftLiftEdgeAnchorNode(liftNodeId: string): ShuttleNode | null {
    const kind = this.liftPortKindForNodeId(liftNodeId);
    const candidateIds = kind === 'inbound'
      ? [
          liftQueueAccessNodeId(liftNodeId),
          liftQueueServiceExitNodeId(liftNodeId, 1),
          liftBufferAccessNodeId(liftNodeId),
          liftQueueTailAccessNodeId(liftNodeId, 1),
          liftNodeId,
        ]
      : [
          liftNodeId,
          liftQueueServiceExitNodeId(liftNodeId, 1),
          liftBufferAccessNodeId(liftNodeId),
          liftQueueTailEntryNodeId(liftNodeId, 1),
          liftQueueAccessNodeId(liftNodeId)
        ];
    for (const candidateId of candidateIds) {
      const node = this.layoutNode(candidateId);
      if (node) {
        return node;
      }
    }
    return null;
  }

  private topLiftColumnNodesByLevel(level: TopLiftAisleLevel): ShuttleNode[] {
    const cached = this.topLiftColumnNodesByLevelCache.get(level);
    if (cached) {
      return cached;
    }
    const columnPrefix = `column-${level}-c`;
    const nodes = this.scenario.layout.nodes.filter((node) => node.id.startsWith(columnPrefix));
    this.topLiftColumnNodesByLevelCache.set(level, nodes);
    return nodes;
  }

  private topLiftRailNodeNearestToLiftEdge(liftNodeId: string, level: TopLiftAisleLevel): string | null {
    const cacheKey = `${liftNodeId}:${level}`;
    if (this.topLiftRailNodeNearestToLiftEdgeCache.has(cacheKey)) {
      return this.topLiftRailNodeNearestToLiftEdgeCache.get(cacheKey) ?? null;
    }
    const anchorNode = this.topLiftLiftEdgeAnchorNode(liftNodeId) ?? this.layoutNode(liftNodeId);
    if (!anchorNode) {
      this.topLiftRailNodeNearestToLiftEdgeCache.set(cacheKey, null);
      return null;
    }
    let nearest: ShuttleNode | null = null;
    let nearestDistance = Number.POSITIVE_INFINITY;
    for (const node of this.topLiftColumnNodesByLevel(level)) {
      const distance = Math.hypot(node.x - anchorNode.x, node.z - anchorNode.z);
      if (distance < nearestDistance) {
        nearest = node;
        nearestDistance = distance;
      }
    }
    const nearestNodeId = nearest?.id ?? null;
    this.topLiftRailNodeNearestToLiftEdgeCache.set(cacheKey, nearestNodeId);
    return nearestNodeId;
  }

  private topLiftRailNodeNearestToLift(liftNodeId: string, level: TopLiftAisleLevel): string | null {
    const cacheKey = `${liftNodeId}:${level}`;
    if (this.topLiftRailNodeNearestToLiftCache.has(cacheKey)) {
      return this.topLiftRailNodeNearestToLiftCache.get(cacheKey) ?? null;
    }
    const liftNode = this.layoutNode(liftNodeId);
    if (!liftNode) {
      this.topLiftRailNodeNearestToLiftCache.set(cacheKey, null);
      return null;
    }
    let nearest: ShuttleNode | null = null;
    let nearestDistance = Number.POSITIVE_INFINITY;
    for (const node of this.topLiftColumnNodesByLevel(level)) {
      const distance = Math.hypot(node.x - liftNode.x, node.z - liftNode.z);
      if (distance < nearestDistance) {
        nearest = node;
        nearestDistance = distance;
      }
    }
    const nearestNodeId = nearest?.id ?? null;
    this.topLiftRailNodeNearestToLiftCache.set(cacheKey, nearestNodeId);
    return nearestNodeId;
  }

  private topLiftServiceStopLiftNodeId(kind: LiftKind, nodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const cacheKey = `${kind}:${nodeId}`;
    if (this.topLiftServiceStopLiftNodeIdCache.has(cacheKey)) {
      return this.topLiftServiceStopLiftNodeIdCache.get(cacheKey) ?? null;
    }
    const liftNodes = kind === 'inbound' ? this.inboundLiftNodes() : this.outboundLiftNodes();
    const liftNodeId = liftNodes.find((liftNode) =>
      (kind === 'inbound'
        ? this.topLiftInboundPickupStopNodeId(liftNode.id)
        : this.topLiftOutboundDropoffStopNodeId(liftNode.id)) === nodeId
    )?.id ?? null;
    this.topLiftServiceStopLiftNodeIdCache.set(cacheKey, liftNodeId);
    return liftNodeId;
  }

  private topLiftInboundApproachQueueNodeIds(liftNodeId: string): string[] {
    if (!this.topLiftColumnLayoutEnabled() || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return [];
    }
    const cached = this.topLiftInboundApproachQueueNodeIdsCache.get(liftNodeId);
    if (cached) {
      return cached;
    }
    const dockNodeId = this.topLiftInboundPickupStopNodeId(liftNodeId);
    const dockNode = dockNodeId ? this.layoutNode(dockNodeId) : null;
    const queueDirection = this.topLiftQueueDisplayDirection(liftNodeId);
    const nodeIds = dockNode
      ? Array.from({ length: 3 }, (_, index) =>
          this.topLiftColumnRailNodeAtOffset('top-a', dockNode, queueDirection, index + 1)?.id ?? null
        ).filter((nodeId): nodeId is string => nodeId !== null)
      : [];
    this.topLiftInboundApproachQueueNodeIdsCache.set(liftNodeId, nodeIds);
    return nodeIds;
  }

  private topLiftInboundApproachQueueSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const parkingSlot = topLiftQueueParkingSlot(nodeId);
    if (parkingSlot && this.liftPortKindForNodeId(parkingSlot.liftNodeId) === 'inbound') {
      return parkingSlot;
    }
    const accessSlot = topLiftQueueAisleAccess(nodeId);
    if (accessSlot && accessSlot.slotIndex > 0 && this.liftPortKindForNodeId(accessSlot.liftNodeId) === 'inbound') {
      return accessSlot;
    }
    if (!isTopLiftAisleLevelNodeId(nodeId, 'top-a')) {
      return null;
    }
    for (const liftNode of this.inboundLiftNodes()) {
      const slotIndex = this.topLiftInboundApproachQueueNodeIds(liftNode.id).indexOf(nodeId);
      if (slotIndex >= 0) {
        return { liftNodeId: liftNode.id, slotIndex: slotIndex + 1 };
      }
    }
    return null;
  }

  private topLiftInboundReserveQueueSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
    const slot = this.topLiftInboundApproachQueueSlot(nodeId);
    if (!slot || !this.topLiftInboundApproachQueueNodeIds(slot.liftNodeId).includes(nodeId)) {
      return null;
    }
    return slot;
  }

  private topLiftInboundStationQueueSlotLeases(liftNodeId: string): StationQueueSlotLease[] {
    if (!this.topLiftColumnLayoutEnabled() || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return [];
    }
    const leases: StationQueueSlotLease[] = [];
    const addLease = (
      vehicle: MutableVehicle,
      nodeId: string | null | undefined,
      phase: StationQueueSlotLease['phase'],
      soft = false
    ): void => {
      if (!nodeId) {
        return;
      }
      const slot = this.topLiftInboundApproachQueueSlot(nodeId);
      if (slot?.liftNodeId !== liftNodeId) {
        return;
      }
      leases.push({
        liftNodeId,
        vehicleId: vehicle.id,
        nodeId,
        slotIndex: slot.slotIndex,
        phase,
        soft
      });
    };

    for (const vehicle of this.vehicles) {
      addLease(vehicle, vehicle.currentNodeId, 'occupied');
      addLease(vehicle, vehicle.targetNodeId, 'targeted');
      addLease(
        vehicle,
        vehicle.plannedGoalNodeId,
        'planned',
        this.tasklessInboundQueueStandbySoftClaim(vehicle, vehicle.plannedGoalNodeId ?? '')
      );
    }

    return leases.sort((left, right) =>
      left.slotIndex - right.slotIndex ||
      left.phase.localeCompare(right.phase) ||
      left.vehicleId.localeCompare(right.vehicleId)
    );
  }

  private topLiftInboundStationQueueSlotClaim(
    slot: { liftNodeId: string; slotIndex: number },
    vehicleId: string,
    ignoredVehicleId: string | null = null,
    options: { includeSoftPlannedLeases?: boolean } = {}
  ): StationQueueSlotLease | null {
    return this.topLiftInboundStationQueueSlotLeases(slot.liftNodeId).find((lease) =>
      lease.slotIndex === slot.slotIndex &&
      lease.vehicleId !== vehicleId &&
      lease.vehicleId !== ignoredVehicleId &&
      (!lease.soft || options.includeSoftPlannedLeases)
    ) ?? null;
  }

  private inboundSourceLoadBelongsToLift(load: LoadStateRecord | null | undefined, liftNodeId: string): boolean {
    return Boolean(
      load &&
      load.state === 'waiting' &&
      load.nodeId !== null &&
      this.inboundSourceSlotNodeIds(liftNodeId).includes(load.nodeId)
    );
  }

  private inboundTaskLoadReadyAtPickup(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    const canCompact = this.diagnosticReadOnlyDepth === 0;
    const pickupStopLiftNodeId = this.topLiftServiceStopLiftNodeId('inbound', task.pickupNodeId);
    if (pickupStopLiftNodeId) {
      if (canCompact) {
        this.compactInboundSourceBuffer(pickupStopLiftNodeId);
      }
      const load = this.loadById(task.loadId);
      return Boolean(
        load &&
        load.state === 'waiting' &&
        load.nodeId === this.inboundSourceFrontBufferNodeId(pickupStopLiftNodeId) &&
        load.vehicleId === null
      );
    }
    const pickupServiceSlot = topLiftQueueServiceSlot(task.pickupNodeId);
    if (pickupServiceSlot && this.liftPortKindForNodeId(pickupServiceSlot.liftNodeId) === 'inbound') {
      if (canCompact) {
        this.compactInboundSourceBuffer(pickupServiceSlot.liftNodeId);
      }
      const load = this.loadById(task.loadId);
      return Boolean(
        load &&
        load.state === 'waiting' &&
        load.nodeId === this.inboundSourceFrontBufferNodeId(pickupServiceSlot.liftNodeId) &&
        load.vehicleId === null
      );
    }
    const bufferParent = liftBufferParentNodeId(task.pickupNodeId);
    if (!bufferParent || bufferParent.kind !== 'inbound') {
      const projectedLiftNodeId = this.topLiftProjectedInboundLiftNodeId(task.pickupNodeId);
      if (!projectedLiftNodeId) {
        return true;
      }
      if (canCompact) {
        this.compactInboundSourceBuffer(projectedLiftNodeId);
      }
      const load = this.loadById(task.loadId);
      return Boolean(
        load &&
        load.state === 'waiting' &&
        load.nodeId === this.inboundSourceFrontBufferNodeId(projectedLiftNodeId) &&
        load.vehicleId === null
      );
    }
    if (canCompact) {
      this.compactInboundSourceBuffer(bufferParent.liftNodeId);
    }
    const load = this.loadById(task.loadId);
    return Boolean(load && load.state === 'waiting' && load.nodeId === task.pickupNodeId && load.vehicleId === null);
  }

  private promoteInboundTaskSourceLoadToFront(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    const frontNodeId = this.inboundSourceFrontBufferNodeId(liftNodeId);
    const slotNodeIds = new Set(this.inboundSourceSlotNodeIds(liftNodeId));
    const taskLoad = this.loadById(task.loadId);
    if (
      !taskLoad ||
      taskLoad.state !== 'waiting' ||
      taskLoad.nodeId === null ||
      taskLoad.vehicleId !== null ||
      !slotNodeIds.has(taskLoad.nodeId)
    ) {
      return false;
    }
    if (taskLoad.nodeId === frontNodeId) {
      return true;
    }
    if (this.diagnosticReadOnlyDepth > 0) {
      return false;
    }

    const displacedLoad = this.loads.find((load) =>
      load.id !== taskLoad.id &&
      load.state === 'waiting' &&
      load.nodeId === frontNodeId &&
      load.vehicleId === null
    );
    const previousNodeId = taskLoad.nodeId;
    taskLoad.nodeId = frontNodeId;
    if (displacedLoad) {
      displacedLoad.nodeId = previousNodeId;
    }
    this.logEvent('source-load-promoted', null, task.id, task.loadId, previousNodeId, frontNodeId, 'inbound-task-source-load-promoted', nodePosition(this.scenario, frontNodeId), {
      liftNodeId,
      displacedLoadId: displacedLoad?.id ?? null,
      displacedNodeId: previousNodeId
    });
    return true;
  }

  private topLiftInboundVehicleStagedForPickup(
    task: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled() || !vehicle || vehicle.loaded) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    return vehicle.currentNodeId === task.pickupNodeId ||
      this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId)?.liftNodeId === liftNodeId;
  }

  private prepareInboundSourceLoadForStagedPickup(
    task: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): boolean {
    if (!this.topLiftInboundVehicleStagedForPickup(task, vehicle)) {
      return false;
    }
    if (this.inboundTaskShouldWaitBeforePickup(task) && vehicle?.currentNodeId !== task.pickupNodeId) {
      return false;
    }
    if (
      vehicle &&
      vehicle.currentNodeId !== task.pickupNodeId &&
      this.topLiftInboundPickupOccupiedByOtherTask(task, vehicle)
    ) {
      return false;
    }
    return this.promoteInboundTaskSourceLoadToFront(task);
  }

  private topLiftInboundPickupOccupiedByOtherTask(
    task: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    return this.vehicles.some((candidate) => {
      if (candidate.id === vehicle?.id || candidate.loaded || candidate.currentNodeId !== task.pickupNodeId) {
        return false;
      }
      const candidateTask = this.taskForVehicle(candidate);
      return candidateTask?.kind === 'inbound' &&
        candidateTask.id !== task.id &&
        candidateTask.pickupNodeId === task.pickupNodeId &&
        this.taskLiftPortNodeId(candidateTask) === liftNodeId &&
        candidateTask.state !== 'completed' &&
        candidateTask.state !== 'failed';
    });
  }

  private topLiftInboundQueueNodeIdForTask(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string | null {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return null;
    }
    const earlierUnreleasedCount = this.activeTasks()
      .filter((candidate) => this.inboundTaskBlocksLiftPickupOrder(candidate, task))
      .length;
    const queueNodeIds = this.topLiftInboundQueueCandidateNodeIds(task, liftNodeId)
      .filter((nodeId) => nodeId !== task.pickupNodeId);
    if (queueNodeIds.length === 0) {
      return null;
    }
    const preferredIndex = Math.min(queueNodeIds.length - 1, Math.max(0, earlierUnreleasedCount - 1));
    for (let index = preferredIndex; index < queueNodeIds.length; index += 1) {
      const nodeId = queueNodeIds[index]!;
      if (this.inboundQueueNodeAvailableForTask(task, nodeId, vehicle)) {
        return nodeId;
      }
    }
    return null;
  }

  private topLiftInboundQueueCandidateNodeIds(task: TaskStateRecord, liftNodeId: string): string[] {
    if (this.topLiftInboundUsesProjectedQueue(task)) {
      return this.topLiftInboundApproachQueueNodeIds(liftNodeId);
    }
    return Array.from(
      { length: this.topLiftPortQueueCapacity(liftNodeId) },
      (_, index) => liftQueueNodeId(liftNodeId, index + 1)
    ).filter((nodeId) => this.layoutNode(nodeId) !== null);
  }

  private topLiftInboundUsesProjectedQueue(task: TaskStateRecord): boolean {
    return this.topLiftProjectedInboundLiftNodeId(task.pickupNodeId) !== null ||
      (this.topLiftColumnLayoutEnabled() && this.scenario.taskGeneration.inboundOutboundMix < 1);
  }

  private inboundQueueNodeAvailableForTask(
    task: TaskStateRecord,
    nodeId: string,
    vehicle?: MutableVehicle | VehicleState | null
  ): boolean {
    const exitingPredecessorVehicleId = this.inboundQueueExitingPredecessorVehicleId(task, nodeId, vehicle);
    const liftNodeId = this.taskLiftPortNodeId(task);
    const candidateSlot = liftNodeId ? this.topLiftInboundApproachQueueSlot(nodeId) : null;
    if (liftNodeId && candidateSlot?.liftNodeId === liftNodeId) {
      if (this.topLiftInboundQueueNodeHardClaimedByOtherVehicle(nodeId, vehicle?.id ?? '', exitingPredecessorVehicleId)) {
        return false;
      }
    } else if (!this.outboundQueueNodeAvailableForVehicle(nodeId, vehicle) && !exitingPredecessorVehicleId) {
      return false;
    }
    if (!liftNodeId || !candidateSlot || candidateSlot.liftNodeId !== liftNodeId) {
      return true;
    }
    if (this.inboundQueueSlotClaimedByOtherVehicle(candidateSlot, vehicle, exitingPredecessorVehicleId)) {
      return false;
    }

    for (const earlierTask of this.activeTasks()) {
      const columnPredecessor = this.inboundTaskIsColumnPredecessor(earlierTask, task);
      if (!columnPredecessor && !this.inboundTaskBlocksLiftPickupOrder(earlierTask, task)) {
        continue;
      }

      const earlierVehicle = earlierTask.vehicleId
        ? this.vehicles.find((candidate) => candidate.id === earlierTask.vehicleId) ?? null
        : null;
      if (!earlierVehicle || earlierVehicle.id === vehicle?.id) {
        continue;
      }
      if (earlierVehicle.id === exitingPredecessorVehicleId) {
        continue;
      }
      const columnPredecessorReservedSlotIndex = columnPredecessor
        ? this.inboundColumnPredecessorReservedQueueSlotIndex(earlierTask, earlierVehicle, liftNodeId)
        : null;
      if (
        columnPredecessorReservedSlotIndex !== null &&
        candidateSlot.slotIndex <= columnPredecessorReservedSlotIndex
      ) {
        return false;
      }

      const earlierRouteNodeIds = this.topLiftInboundQueueClaimNodeIds(earlierVehicle);
      if (earlierRouteNodeIds.includes(nodeId)) {
        return false;
      }

      if (this.inboundQueueNodeOverlapsEarlierLoadedExitPath(task, nodeId, earlierTask)) {
        return false;
      }

      if (this.inboundQueueRouteOverlapsEarlierQueueOccupant(task, nodeId, earlierTask, vehicle)) {
        return false;
      }

      const earliestBlockingSlotIndex = Math.max(
        0,
        ...earlierRouteNodeIds
          .map((candidate) => this.topLiftInboundApproachQueueSlot(candidate))
          .filter((slot): slot is { liftNodeId: string; slotIndex: number } =>
            Boolean(slot) && slot!.liftNodeId === liftNodeId
          )
          .map((slot) => slot.slotIndex)
      );
      const effectiveBlockingSlotIndex = columnPredecessorReservedSlotIndex !== null
        ? Math.min(columnPredecessorReservedSlotIndex, earliestBlockingSlotIndex || columnPredecessorReservedSlotIndex)
        : earliestBlockingSlotIndex;
      if (effectiveBlockingSlotIndex > 0 && candidateSlot.slotIndex <= effectiveBlockingSlotIndex) {
        return false;
      }
    }

    return true;
  }

  private inboundQueueSlotClaimedByOtherVehicle(
    candidateSlot: { liftNodeId: string; slotIndex: number },
    vehicle?: MutableVehicle | VehicleState | null,
    ignoredVehicleId: string | null = null
  ): boolean {
    return this.topLiftInboundStationQueueSlotClaim(
      candidateSlot,
      vehicle?.id ?? '',
      ignoredVehicleId
    ) !== null;
  }

  private topLiftInboundQueueNodeHardClaimedByOtherVehicle(
    nodeId: string,
    vehicleId: string,
    ignoredVehicleId: string | null = null,
    options: { includeTasklessStandbyPlannedGoal?: boolean } = {}
  ): string | null {
    if (!this.topLiftInboundApproachQueueSlot(nodeId)) {
      return this.nodeClaimedByOtherVehicle(nodeId, vehicleId);
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicleId && occupantId !== ignoredVehicleId) {
      return occupantId;
    }
    const claimant = this.vehicles.find((vehicle) =>
      vehicle.id !== vehicleId &&
      vehicle.id !== ignoredVehicleId &&
      (
        vehicle.currentNodeId === nodeId ||
        vehicle.targetNodeId === nodeId ||
        (
          vehicle.plannedGoalNodeId === nodeId &&
          (
            options.includeTasklessStandbyPlannedGoal ||
            !this.tasklessInboundQueueStandbySoftClaim(vehicle, nodeId)
          )
        )
      )
    );
    return claimant?.id ?? null;
  }

  private tasklessInboundQueueStandbySoftClaim(vehicle: MutableVehicle | VehicleState, nodeId: string): boolean {
    return Boolean(
      nodeId &&
      vehicle.plannedGoalNodeId === nodeId &&
      !vehicle.loaded &&
      vehicle.taskId === null &&
      vehicle.currentNodeId !== nodeId &&
      vehicle.targetNodeId !== nodeId &&
      vehicle.localRouteReason === 'inbound-queue-standby'
    );
  }

  private topLiftInboundQueueClaimNodeIds(vehicle: MutableVehicle): string[] {
    const nodeIds = [
      vehicle.currentNodeId,
      vehicle.targetNodeId,
      vehicle.plannedGoalNodeId
    ];
    if (!this.topLiftInboundQueueRouteTailIsDetachedDetour(vehicle)) {
      nodeIds.push(
        ...this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
        ...this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
        ...this.vehicleRouteTail(vehicle, vehicle.localRouteNodeIds)
      );
    }
    return nodeIds
      .filter((nodeId): nodeId is string => Boolean(nodeId))
      .filter((nodeId, index, all) => all.indexOf(nodeId) === index);
  }

  private topLiftInboundQueueRouteTailIsDetachedDetour(vehicle: MutableVehicle): boolean {
    if (vehicle.loaded) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    const plannedSlot = vehicle.plannedGoalNodeId
      ? this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId)
      : null;
    if (task?.kind !== 'inbound' || !plannedSlot || !vehicle.targetNodeId) {
      return false;
    }
    const targetSlot = this.topLiftInboundApproachQueueSlot(vehicle.targetNodeId);
    if (targetSlot?.liftNodeId === plannedSlot.liftNodeId) {
      return false;
    }
    const targetNode = this.layoutNode(vehicle.targetNodeId);
    const temporaryQueueDetour =
      vehicle.localRouteReason === 'temporary-yield' ||
      vehicle.localRouteReason === 'inbound-unready-queue-leader-yield' ||
      vehicle.localRouteReason === 'top-lift-queue-swap-yield' ||
      vehicle.localRouteReason === 'column-access-storage-swap-clearance';
    return targetNode?.type === 'storage' || temporaryQueueDetour;
  }

  private inboundQueueExitingPredecessorVehicleId(
    task: TaskStateRecord,
    nodeId: string,
    vehicle?: MutableVehicle | VehicleState | null
  ): string | null {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const candidateSlot = this.topLiftInboundApproachQueueSlot(nodeId);
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!candidateSlot || !liftNodeId || candidateSlot.liftNodeId !== liftNodeId) {
      return null;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    const occupant = this.vehicles.find((candidate) =>
      candidate.id !== vehicle?.id &&
      (candidate.id === occupantId || candidate.currentNodeId === nodeId)
    ) ?? null;
    if (!occupant) {
      return null;
    }
    const occupantTask = occupant ? this.taskForVehicle(occupant) : null;
    if (
      !occupant ||
      !occupantTask ||
      occupant.loaded ||
      occupantTask.kind !== 'inbound' ||
      this.taskLiftPortNodeId(occupantTask) !== liftNodeId ||
      !this.inboundTaskBlocksLiftPickupOrder(occupantTask, task) ||
      occupant.plannedGoalNodeId !== occupantTask.pickupNodeId
    ) {
      return null;
    }
    const targetLevel = occupant.targetNodeId ? topLiftAisleLevel(occupant.targetNodeId) : null;
    const targetSlot = occupant.targetNodeId ? this.topLiftInboundApproachQueueSlot(occupant.targetNodeId) : null;
    return targetLevel === 'top-b' && !targetSlot ? occupant.id : null;
  }

  private inboundQueueRouteOverlapsEarlierQueueOccupant(
    task: TaskStateRecord,
    queueNodeId: string,
    earlierTask: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): boolean {
    if (
      !vehicle ||
      task.kind !== 'inbound' ||
      earlierTask.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      this.taskLiftPortNodeId(task) !== this.taskLiftPortNodeId(earlierTask)
    ) {
      return false;
    }

    const liftNodeId = this.taskLiftPortNodeId(task);
    const candidateSlot = this.topLiftInboundApproachQueueSlot(queueNodeId);
    const earlierVehicle = earlierTask.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === earlierTask.vehicleId) ?? null
      : null;
    if (!liftNodeId || !candidateSlot || !earlierVehicle || earlierVehicle.id === vehicle.id) {
      return false;
    }

    let routeNodeIds: string[];
    try {
      routeNodeIds = this.shortestPath(vehicle.currentNodeId, queueNodeId);
    } catch {
      return false;
    }

    const routePoses = routeNodeIds
      .slice(1, -1)
      .map((nodeId) => this.topLiftProjectedDisplayPoseAtNode(nodeId))
      .filter((pose): pose is { x: number; z: number } => pose !== null);
    if (routePoses.length === 0) {
      return false;
    }

    const earlierNodeIds = this.topLiftInboundQueueClaimNodeIds(earlierVehicle);

    return earlierNodeIds.some((earlierNodeId) => {
      const earlierSlot = this.topLiftInboundApproachQueueSlot(earlierNodeId);
      if (
        !earlierSlot ||
        earlierSlot.liftNodeId !== liftNodeId ||
        earlierSlot.slotIndex >= candidateSlot.slotIndex
      ) {
        return false;
      }
      const earlierPose = this.topLiftProjectedDisplayPoseAtNode(earlierNodeId);
      return earlierPose
        ? routePoses.some((routePose) => this.topLiftProjectedDisplayPosesOverlap(routePose, earlierPose))
        : false;
    });
  }

  private inboundQueueNodeOverlapsEarlierLoadedExitPath(
    task: TaskStateRecord,
    queueNodeId: string,
    earlierTask: TaskStateRecord
  ): boolean {
    if (
      task.kind !== 'inbound' ||
      earlierTask.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      this.taskLiftPortNodeId(task) !== this.taskLiftPortNodeId(earlierTask)
    ) {
      return false;
    }
    const queuePose = this.topLiftProjectedDisplayPoseAtNode(queueNodeId);
    if (!queuePose) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(earlierTask);
    const dropoffColumn = this.storageGridPosition(earlierTask.dropoffNodeId)?.column ?? null;
    const pickupColumn = this.topLiftColumnAccessColumn(earlierTask.pickupNodeId);
    if (!liftNodeId || dropoffColumn === null || pickupColumn === null) {
      return false;
    }

    const direction = Math.sign(dropoffColumn - pickupColumn) || 1;
    const corridorNodeIds: string[] = [];
    for (let column = pickupColumn; column !== dropoffColumn + direction; column += direction) {
      corridorNodeIds.push(columnAccessNodeId('top-b', column - 1));
    }
    return corridorNodeIds.some((nodeId) => {
      const corridorPose = this.topLiftProjectedDisplayPoseAtNode(nodeId);
      return corridorPose ? this.topLiftProjectedDisplayPosesOverlap(queuePose, corridorPose) : false;
    });
  }

  private inboundTaskPickupReleased(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || task.state === 'completed' || task.state === 'failed') {
      return true;
    }
    if (task.startedAtSec !== null || task.state === 'in-progress') {
      return true;
    }
    const vehicle = task.vehicleId ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) : null;
    if (vehicle?.loaded) {
      return true;
    }
    const load = this.loadById(task.loadId);
    return Boolean(load && load.state !== 'waiting');
  }

  private taskPrecedes(left: TaskStateRecord, right: TaskStateRecord): boolean {
    return left.createdAtSec < right.createdAtSec ||
      (left.createdAtSec === right.createdAtSec && left.id.localeCompare(right.id) < 0);
  }

  private inboundTaskPrecedes(left: TaskStateRecord, right: TaskStateRecord): boolean {
    return this.taskPrecedes(left, right);
  }

  private inboundTaskHasEarlierPickupTask(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled() || task.startedAtSec !== null) {
      return false;
    }
    return this.activeTasks().some((candidate) => this.inboundTaskBlocksLiftPickupOrder(candidate, task));
  }

  private inboundTaskBlocksLiftPickupOrder(candidate: TaskStateRecord, task: TaskStateRecord): boolean {
    if (
      candidate.id === task.id ||
      candidate.kind !== 'inbound' ||
      task.kind !== 'inbound' ||
      this.taskLiftPortNodeId(candidate) !== this.taskLiftPortNodeId(task) ||
      !this.inboundTaskPrecedes(candidate, task) ||
      this.inboundTaskPickupReleased(candidate)
    ) {
      return false;
    }
    if (candidate.state === 'queued' && this.topLiftInboundColumnPredecessorPending(candidate)) {
      return false;
    }
    if (!this.inboundTaskLoadReadyAtPickup(candidate) && this.inboundTaskLoadReadyAtPickup(task)) {
      return false;
    }
    if (this.inboundQueuedTaskBlockedAwayFromLift(candidate)) {
      return false;
    }
    if (this.inboundEarlierPickupVehiclePhysicallyBehind(candidate, task)) {
      return false;
    }
    return true;
  }

  private inboundQueuedTaskBlockedAwayFromLift(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || task.state !== 'queued' || task.vehicleId !== null || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const dropoffLoadId = this.storedLoadIdAtNode(task.dropoffNodeId);
    if (dropoffLoadId && dropoffLoadId !== task.loadId) {
      return true;
    }
    if (!this.isStorageNode(task.dropoffNodeId)) {
      return false;
    }
    const dropoffColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
    if (
      dropoffColumn !== null &&
      this.topLiftTasklessStorageVehicleBlocksInboundAllocation(dropoffColumn) &&
      !this.topLiftQueuedInboundTaskHasAssignableVehicleInColumn(task)
    ) {
      return true;
    }
    return !this.topLiftInboundStorageNodeReachableInColumn(
      task.dropoffNodeId,
      this.storageNodeLoadOccupancyForInFlightInboundReachability(task)
    );
  }

  private inboundTaskIsColumnPredecessor(candidate: TaskStateRecord, task: TaskStateRecord): boolean {
    if (
      candidate.id === task.id ||
      candidate.kind !== 'inbound' ||
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      this.taskLiftPortNodeId(candidate) !== this.taskLiftPortNodeId(task) ||
      !this.isStorageNode(candidate.dropoffNodeId) ||
      !this.isStorageNode(task.dropoffNodeId)
    ) {
      return false;
    }
    const candidatePosition = this.storageGridPosition(candidate.dropoffNodeId);
    const taskPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!candidatePosition || !taskPosition || candidatePosition.column !== taskPosition.column) {
      return false;
    }
    const columnNodeIds = this.topLiftStorageColumnNodeIds(taskPosition.column);
    const candidateIndex = columnNodeIds.indexOf(candidate.dropoffNodeId);
    const taskIndex = columnNodeIds.indexOf(task.dropoffNodeId);
    return candidateIndex >= 0 && taskIndex >= 0 && candidateIndex < taskIndex;
  }

  private inboundColumnPredecessorReservedQueueSlotIndex(
    predecessorTask: TaskStateRecord,
    predecessorVehicle: MutableVehicle | null,
    liftNodeId: string
  ): number | null {
    if (
      !predecessorVehicle ||
      predecessorVehicle.loaded ||
      predecessorVehicle.currentNodeId === predecessorTask.pickupNodeId
    ) {
      return null;
    }

    const activeSlot =
      this.topLiftInboundApproachQueueSlot(predecessorVehicle.currentNodeId) ??
      this.topLiftInboundApproachQueueSlot(predecessorVehicle.targetNodeId ?? '');
    if (activeSlot?.liftNodeId === liftNodeId) {
      return activeSlot.slotIndex;
    }

    return 1;
  }

  private inboundEarlierPickupVehiclePhysicallyBehind(candidate: TaskStateRecord, task: TaskStateRecord): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      candidate.pickupNodeId !== task.pickupNodeId ||
      candidate.vehicleId === null ||
      task.vehicleId === null
    ) {
      return false;
    }
    const candidateVehicle = this.vehicles.find((vehicle) => vehicle.id === candidate.vehicleId) ?? null;
    const taskVehicle = this.vehicles.find((vehicle) => vehicle.id === task.vehicleId) ?? null;
    if (!candidateVehicle || !taskVehicle || candidateVehicle.loaded || taskVehicle.loaded) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.taskLiftPortNodeId(candidate) !== liftNodeId) {
      return false;
    }
    const pickupSlot = this.topLiftInboundApproachQueueSlot(task.pickupNodeId);
    const pickupIsTopLiftStop =
      this.topLiftServiceStopLiftNodeId('inbound', task.pickupNodeId) === liftNodeId &&
      isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-a');
    if (!pickupIsTopLiftStop && (!pickupSlot || pickupSlot.liftNodeId !== liftNodeId)) {
      return false;
    }
    const candidateRank = this.topLiftInboundPickupApproachRank(candidateVehicle.currentNodeId, task.pickupNodeId, liftNodeId);
    const taskRank = this.topLiftInboundPickupApproachRank(taskVehicle.currentNodeId, task.pickupNodeId, liftNodeId);
    if (taskRank !== null && candidateRank === null) {
      const candidateTargetRank = candidateVehicle.targetNodeId
        ? this.topLiftInboundPickupApproachRank(candidateVehicle.targetNodeId, task.pickupNodeId, liftNodeId)
        : null;
      return candidateTargetRank === null && candidateVehicle.currentNodeId !== task.pickupNodeId;
    }
    return candidateRank !== null && taskRank !== null && candidateRank > taskRank;
  }

  private topLiftInboundPickupApproachRank(
    nodeId: string,
    pickupNodeId: string,
    liftNodeId: string
  ): number | null {
    const queueSlot = this.topLiftInboundApproachQueueSlot(nodeId);
    if (queueSlot?.liftNodeId === liftNodeId) {
      return -100 + queueSlot.slotIndex;
    }
    if (!isTopLiftAisleLevelNodeId(nodeId, 'top-a') && !isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
      return null;
    }
    const pickupColumn = this.topLiftColumnAccessColumn(pickupNodeId);
    const nodeColumn = this.topLiftColumnAccessColumn(nodeId);
    if (pickupColumn === null || nodeColumn === null || nodeColumn < pickupColumn) {
      return null;
    }
    return nodeColumn - pickupColumn;
  }

  private inboundTaskShouldWaitBeforePickup(task: TaskStateRecord): boolean {
    return this.inboundTaskHasEarlierPickupTask(task) || this.topLiftInboundColumnPredecessorBlocksPickup(task);
  }

  private topLiftInboundColumnPredecessorBlocksPickup(task: TaskStateRecord): boolean {
    if (!this.topLiftInboundColumnPredecessorPending(task)) {
      return false;
    }
    return !this.topLiftInboundColumnPredecessorPickupPipelineAllowed(task);
  }

  private topLiftInboundColumnPredecessorPickupPipelineAllowed(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (
      !liftNodeId ||
      this.liftPortKindForNodeId(liftNodeId) !== 'inbound' ||
      task.state !== 'assigned' ||
      task.startedAtSec !== null ||
      !task.vehicleId ||
      !this.inboundTaskLoadReadyAtPickup(task)
    ) {
      return false;
    }
    const vehicle = this.vehicles.find((candidate) => candidate.id === task.vehicleId) ?? null;
    const queueSlot = vehicle ? this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId) : null;
    if (
      !vehicle ||
      vehicle.loaded ||
      vehicle.phaseRemainingSec > 0 ||
      queueSlot?.liftNodeId !== liftNodeId ||
      queueSlot.slotIndex !== 1 ||
      this.topLiftLoadedInboundWipCountForLift(liftNodeId) >= 2
    ) {
      return false;
    }
    const waitingAtFrontQueue =
      vehicle.currentEdgeId === null &&
      vehicle.legRemainingM <= 0 &&
      vehicle.targetNodeId === null;
    const releasedFromFrontQueueToPickup =
      vehicle.currentEdgeId !== null &&
      vehicle.legRemainingM > 0 &&
      vehicle.targetNodeId === task.pickupNodeId &&
      vehicle.routeNodeIds.includes(task.pickupNodeId);
    if (!waitingAtFrontQueue && !releasedFromFrontQueueToPickup) {
      return false;
    }
    const predecessors = this.topLiftInboundColumnPredecessorTasks(task);
    const predecessor = predecessors.length === 1
      ? this.topLiftInboundImmediateColumnPredecessorTask(task)
      : null;
    if (!predecessor || predecessor.id !== predecessors[0]!.id) {
      return false;
    }
    const predecessorVehicle = predecessor.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === predecessor.vehicleId) ?? null
      : null;
    return Boolean(
      predecessorVehicle?.loaded &&
      predecessorVehicle.waitReason === null &&
      this.topLiftInboundColumnPredecessorInsideStorageColumn(predecessor, task)
    );
  }

  private topLiftLoadedInboundWipCountForLift(liftNodeId: string): number {
    return this.topLiftLoadedInboundWipVehiclesForLift(liftNodeId).length;
  }

  private topLiftLoadedInboundWipVehiclesForLift(liftNodeId: string): MutableVehicle[] {
    return this.vehicles.filter((vehicle) => {
      if (!vehicle.loaded || !vehicle.taskId) {
        return false;
      }
      const task = this.taskById(vehicle.taskId);
      return task?.kind === 'inbound' &&
        this.taskLiftPortNodeId(task) === liftNodeId &&
        task.state !== 'completed' &&
        task.state !== 'failed';
    });
  }

  private topLiftInboundPickupPipelineWipLimit(liftNodeId: string): number {
    return Math.max(
      3,
      Math.min(this.topLiftPortStagedTaskCapacity('inbound', liftNodeId), this.inboundSourceBufferCapacity(liftNodeId))
    );
  }

  private topLiftInboundColumnPredecessorInsideStorageColumn(
    predecessor: TaskStateRecord,
    task: TaskStateRecord
  ): boolean {
    if (!this.inboundTaskPickupReleased(predecessor)) {
      return false;
    }
    const vehicle = predecessor.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === predecessor.vehicleId) ?? null
      : null;
    if (!vehicle?.loaded || !this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    const predecessorColumn = this.storageGridPosition(predecessor.dropoffNodeId)?.column ?? null;
    const vehicleColumn = this.storageGridPosition(vehicle.currentNodeId)?.column ?? null;
    const taskColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
    return predecessorColumn !== null &&
      predecessorColumn === vehicleColumn &&
      predecessorColumn === taskColumn;
  }

  private topLiftInboundColumnPredecessorReleasedTowardStorageColumn(
    predecessor: TaskStateRecord,
    task: TaskStateRecord
  ): boolean {
    if (!this.inboundTaskPickupReleased(predecessor)) {
      return false;
    }
    const vehicle = predecessor.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === predecessor.vehicleId) ?? null
      : null;
    if (!vehicle?.loaded) {
      return false;
    }
    const predecessorColumn = this.storageGridPosition(predecessor.dropoffNodeId)?.column ?? null;
    const taskColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
    if (predecessorColumn === null || predecessorColumn !== taskColumn) {
      return false;
    }
    const predecessorColumnNodeIds = new Set(this.topLiftStorageColumnNodeIds(predecessorColumn));
    const claimedNodeIds = [
      vehicle.currentNodeId,
      vehicle.targetNodeId,
      vehicle.plannedGoalNodeId,
      ...this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      ...this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
      ...this.vehicleRouteTail(vehicle, vehicle.localRouteNodeIds)
    ].filter((nodeId): nodeId is string => Boolean(nodeId));
    return claimedNodeIds.includes(predecessor.dropoffNodeId) ||
      claimedNodeIds.some((nodeId) => predecessorColumnNodeIds.has(nodeId));
  }

  private topLiftInboundColumnPredecessorTasks(task: TaskStateRecord): TaskStateRecord[] {
    const position = this.topLiftInboundColumnPredecessorPosition(task);
    if (!position) {
      return [];
    }
    const columnNodeIds = this.topLiftStorageColumnNodeIds(position.column);
    const targetIndex = columnNodeIds.indexOf(task.dropoffNodeId);
    if (targetIndex <= 0) {
      return [];
    }
    const deeperNodeIds = new Set(columnNodeIds.slice(0, targetIndex));
    return this.activeTasks().filter((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'inbound' &&
      this.inboundTaskPrecedes(candidate, task) &&
      deeperNodeIds.has(candidate.dropoffNodeId) &&
      !this.inboundEarlierPickupVehiclePhysicallyBehind(candidate, task) &&
      this.topLiftInboundColumnPredecessorCanBlockSuccessor(candidate)
    );
  }

  private topLiftInboundColumnPredecessorCanBlockSuccessor(candidate: TaskStateRecord): boolean {
    if (this.inboundQueuedTaskBlockedAwayFromLift(candidate)) {
      return false;
    }
    if (candidate.state !== 'queued') {
      return true;
    }
    const dropoffLoadId = this.storedLoadIdAtNode(candidate.dropoffNodeId);
    if (dropoffLoadId && dropoffLoadId !== candidate.loadId) {
      return false;
    }
    if (candidate.waitReason === 'storage-full') {
      return false;
    }
    return true;
  }

  private topLiftInboundVehicleNearQueueArea(vehicle: MutableVehicle | VehicleState): boolean {
    return [vehicle.currentNodeId, vehicle.targetNodeId, vehicle.plannedGoalNodeId].some((nodeId) =>
      this.topLiftInboundQueueAreaNode(nodeId)
    );
  }

  private topLiftInboundQueueAreaNode(nodeId: string | null): boolean {
    if (!nodeId) {
      return false;
    }
    const approachSlot = this.topLiftInboundApproachQueueSlot(nodeId);
    if (approachSlot) {
      return true;
    }
    const serviceSlot = topLiftQueueServiceSlot(nodeId);
    if (serviceSlot && this.liftPortKindForNodeId(serviceSlot.liftNodeId) === 'inbound') {
      return true;
    }
    const parkingSlot = topLiftQueueParkingSlot(nodeId);
    if (parkingSlot && this.liftPortKindForNodeId(parkingSlot.liftNodeId) === 'inbound') {
      return true;
    }
    const entrySlot = topLiftQueueEntrySlot(nodeId);
    if (entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'inbound') {
      return true;
    }
    const aisleAccess = topLiftQueueAisleAccess(nodeId);
    return Boolean(aisleAccess && this.liftPortKindForNodeId(aisleAccess.liftNodeId) === 'inbound');
  }

  private inboundStickyQueueGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string | null {
    if (task.kind !== 'inbound' || vehicle?.loaded || !vehicle?.plannedGoalNodeId || vehicle.currentNodeId === vehicle.plannedGoalNodeId) {
      return null;
    }
    const plannedQueueSlot =
      topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) ??
      this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId);
    if (!plannedQueueSlot) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (plannedQueueSlot.liftNodeId !== liftNodeId) {
      return null;
    }
    const alreadyInsideQueue = [vehicle.currentNodeId].some((nodeId) =>
      topLiftQueueParkingSlot(nodeId)?.liftNodeId === liftNodeId ||
      topLiftQueueAisleAccess(nodeId)?.liftNodeId === liftNodeId ||
      this.topLiftInboundApproachQueueSlot(nodeId)?.liftNodeId === liftNodeId
    );
    if (alreadyInsideQueue && this.inboundTaskLoadReadyAtPickup(task) && !this.inboundTaskShouldWaitBeforePickup(task)) {
      return null;
    }
    if (alreadyInsideQueue) {
      return vehicle.plannedGoalNodeId;
    }
    return this.inboundTaskShouldWaitBeforePickup(task) || !this.inboundTaskLoadReadyAtPickup(task)
      ? vehicle.plannedGoalNodeId
      : null;
  }

  private inboundPickupDispatchGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string {
    this.prepareInboundSourceLoadForStagedPickup(task, vehicle);
    const shouldWaitBeforePickup = this.inboundTaskShouldWaitBeforePickup(task);
    if (!shouldWaitBeforePickup && !this.topLiftInboundPickupOccupiedByOtherTask(task, vehicle)) {
      this.promoteInboundTaskSourceLoadToFront(task);
    }
    const currentQueueHoldNodeId = this.inboundCurrentQueueHoldOrDeeperGoalNodeId(task, vehicle);
    if (currentQueueHoldNodeId) {
      return currentQueueHoldNodeId;
    }
    const stickyQueueGoalNodeId = this.inboundStickyQueueGoalNodeId(task, vehicle);
    if (stickyQueueGoalNodeId) {
      return stickyQueueGoalNodeId;
    }
    if (vehicle && this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task)) {
      const queueGoalNodeId =
        this.topLiftInboundQueueNodeIdForTask(task, vehicle) ??
        this.topLiftInboundActiveQueueRouteTerminalNodeId(task, vehicle);
      if (queueGoalNodeId) {
        return queueGoalNodeId;
      }
      return vehicle.currentNodeId;
    }
    if (!this.inboundTaskLoadReadyAtPickup(task)) {
      return this.topLiftInboundQueueNodeIdForTask(task, vehicle) ?? task.pickupNodeId;
    }
    if (!shouldWaitBeforePickup) {
      return task.pickupNodeId;
    }
    return this.topLiftInboundQueueNodeIdForTask(task, vehicle) ?? task.pickupNodeId;
  }

  private inboundCurrentQueueHoldOrDeeperGoalNodeId(
    task: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): string | null {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle?.loaded ||
      !vehicle?.currentNodeId
    ) {
      return null;
    }
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!currentSlot || !liftNodeId || currentSlot.liftNodeId !== liftNodeId) {
      return null;
    }

    const shouldRemainQueued = this.inboundTaskShouldWaitBeforePickup(task) || !this.inboundTaskLoadReadyAtPickup(task);
    if (!shouldRemainQueued) {
      return null;
    }

    const computedQueueNodeId = this.topLiftInboundQueueNodeIdForTask(task, vehicle);
    const computedSlot = computedQueueNodeId ? this.topLiftInboundApproachQueueSlot(computedQueueNodeId) : null;
    if (
      computedQueueNodeId &&
      computedSlot?.liftNodeId === currentSlot.liftNodeId &&
      (
        this.topLiftInboundProjectedQueueForwardCompressionAllowed(vehicle, currentSlot, computedSlot, computedQueueNodeId)
      )
    ) {
      return computedQueueNodeId;
    }
    return vehicle.currentNodeId;
  }

  private topLiftInboundProjectedQueueForwardCompressionAllowed(
    vehicle: MutableVehicle | VehicleState,
    currentSlot: { liftNodeId: string; slotIndex: number },
    computedSlot: { liftNodeId: string; slotIndex: number },
    computedQueueNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      computedSlot.liftNodeId !== currentSlot.liftNodeId ||
      computedSlot.slotIndex >= currentSlot.slotIndex ||
      !this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId) ||
      !this.topLiftInboundApproachQueueSlot(computedQueueNodeId)
    ) {
      return false;
    }
    let routeNodeIds: string[];
    try {
      routeNodeIds = this.shortestPath(vehicle.currentNodeId, computedQueueNodeId);
    } catch {
      return false;
    }
    if (
      routeNodeIds.length < 2 ||
      routeNodeIds.some((nodeId) => this.topLiftInboundApproachQueueSlot(nodeId)?.liftNodeId !== currentSlot.liftNodeId)
    ) {
      return false;
    }
    const mutableVehicle = this.vehicles.find((candidate) => candidate.id === vehicle.id) ?? null;
    if (!mutableVehicle) {
      return false;
    }
    return this.agentRefreshLocalRouteNodesClear(mutableVehicle, routeNodeIds);
  }

  private topLiftOutboundQueueNodeIdForTask(
    task: TaskStateRecord,
    vehicle?: MutableVehicle | VehicleState | null
  ): string | null {
    if (task.kind !== 'outbound' || !this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return null;
    }
    const earlierUnreleasedCount = this.activeTasks().filter((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'outbound' &&
      this.taskLiftPortNodeId(candidate) === liftNodeId &&
      this.taskPrecedes(candidate, task) &&
      this.outboundTaskPhysicallyBlocksDropoffOrder(candidate, liftNodeId)
    ).length;
    if (earlierUnreleasedCount <= 0) {
      return null;
    }
    if (this.outboundEarlierDropoffBlockedByVehicle(task, vehicle)) {
      return null;
    }
    const meterNodeIds = this.topLiftOutboundApproachMeterNodeIds(liftNodeId);
    const preferredIndex = Math.max(0, earlierUnreleasedCount - 1);
    for (let index = preferredIndex; index < meterNodeIds.length; index += 1) {
      const nodeId = meterNodeIds[index]!;
      if (this.outboundQueueNodeAvailableForVehicle(nodeId, vehicle)) {
        return nodeId;
      }
    }
    return meterNodeIds.at(-1) ?? null;
  }

  private topLiftOutboundApproachMeterNodeIds(liftNodeId: string): string[] {
    if (!this.topLiftColumnLayoutEnabled() || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
      return [];
    }
    const serviceEntryNodeId = liftQueueTailEntryNodeId(liftNodeId, 1);
    const serviceEntryTopNodeId = this.topLiftQueueEntryTopAccessNodeId(serviceEntryNodeId);
    const match = /^column-bottom-a-c(\d+)$/.exec(serviceEntryTopNodeId ?? '');
    if (!match) {
      return [];
    }
    const dropoffColumn = Number(match[1]!);
    return Array.from({ length: 3 }, (_, index) => `column-bottom-b-c${String(dropoffColumn - index - 1).padStart(2, '0')}`)
      .filter((nodeId) => this.layoutNode(nodeId) !== null);
  }

  private topLiftOutboundMeterConflictsWithSiblingInbound(outboundLiftNodeId: string, nodeId: string): boolean {
    const meterNode = this.layoutNode(nodeId);
    if (!meterNode) {
      return true;
    }
    const inboundLiftNodeId = outboundLiftNodeId.replace('-outbound', '-inbound');
    if (!this.layoutNode(inboundLiftNodeId)) {
      return false;
    }
    const minimumClearanceM = this.scenario.vehicles.lengthM + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    const siblingInboundCriticalNodes = Array.from({ length: 3 }, (_, index) => index + 1)
      .flatMap((slotIndex) => {
        const entryNodeId = liftQueueTailEntryNodeId(inboundLiftNodeId, slotIndex);
        return [
          liftQueueServiceExitNodeId(inboundLiftNodeId, slotIndex),
          entryNodeId,
          this.topLiftQueueEntryBottomAccessNodeId(entryNodeId)
        ];
      })
      .filter((candidate): candidate is string => Boolean(candidate));
    return siblingInboundCriticalNodes.some((criticalNodeId) => {
      const criticalNode = this.layoutNode(criticalNodeId);
      if (!criticalNode) {
        return false;
      }
      return Math.hypot(meterNode.x - criticalNode.x, meterNode.z - criticalNode.z) < minimumClearanceM;
    });
  }

  private topLiftOutboundServiceEntryBottomNodeId(liftNodeId: string): string | null {
    const firstEntryNodeId = liftQueueTailEntryNodeId(liftNodeId, 1);
    return this.layoutNode(firstEntryNodeId)
      ? this.topLiftQueueEntryBottomAccessNodeId(firstEntryNodeId)
      : null;
  }

  private topLiftOutboundMeterSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const outboundLiftNodeIds = this.scenario.layout.nodes
      .filter((node) => liftKindForNode(node) === 'outbound')
      .map((node) => node.id);
    for (const liftNodeId of outboundLiftNodeIds) {
      const slotIndex = this.topLiftOutboundApproachMeterNodeIds(liftNodeId).indexOf(nodeId);
      if (slotIndex >= 0) {
        return { liftNodeId, slotIndex: slotIndex + 1 };
      }
    }
    return null;
  }

  private outboundTaskDropoffReleased(task: TaskStateRecord): boolean {
    return task.kind !== 'outbound' ||
      task.state === 'completed' ||
      task.state === 'failed' ||
      !this.outboundTaskCurrentlyClaimsDropoff(task);
  }

  private outboundTaskCurrentlyClaimsDropoff(task: TaskStateRecord): boolean {
    if (task.kind !== 'outbound' || task.completedAtSec !== null) {
      return false;
    }
    const vehicle = task.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) ?? null
      : null;
    return task.state === 'in-progress' || vehicle?.loaded === true;
  }

  private topLiftMaxOccupiedEarlierQueueSlot(liftNodeId: string, task: TaskStateRecord, kind: 'inbound' | 'outbound'): number {
    let maxSlotIndex = 0;
    for (const candidate of this.activeTasks()) {
      if (
        candidate.id === task.id ||
        candidate.kind !== kind ||
        this.taskLiftPortNodeId(candidate) !== liftNodeId ||
        !this.taskPrecedes(candidate, task)
      ) {
        continue;
      }
      const vehicle = candidate.vehicleId
        ? this.vehicles.find((entry) => entry.id === candidate.vehicleId) ?? null
        : null;
      for (const nodeId of [vehicle?.currentNodeId, vehicle?.targetNodeId, vehicle?.plannedGoalNodeId]) {
        const slot = nodeId ? topLiftQueueParkingSlot(nodeId) ?? topLiftQueueEntrySlot(nodeId) : null;
        if (slot?.liftNodeId === liftNodeId) {
          maxSlotIndex = Math.max(maxSlotIndex, slot.slotIndex);
        }
      }
    }
    return maxSlotIndex;
  }

  private outboundTaskHasEarlierDropoffTask(task: TaskStateRecord): boolean {
    if (task.kind !== 'outbound' || !this.topLiftColumnLayoutEnabled() || task.completedAtSec !== null) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return false;
    }
    return this.activeTasks().some((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'outbound' &&
      this.taskLiftPortNodeId(candidate) === liftNodeId &&
      this.taskPrecedes(candidate, task) &&
      this.outboundTaskPhysicallyBlocksDropoffOrder(candidate, liftNodeId)
    );
  }

  private outboundTaskPhysicallyBlocksDropoffOrder(task: TaskStateRecord, liftNodeId: string): boolean {
    if (task.kind !== 'outbound' || this.outboundTaskDropoffReleased(task)) {
      return false;
    }
    const vehicle = task.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) ?? null
      : null;
    if (!vehicle?.loaded) {
      return false;
    }
    if (this.outboundLoadedVehicleAlreadyInServiceLane(task, vehicle)) {
      return true;
    }
    const meterNodeIds = this.topLiftOutboundApproachMeterNodeIds(liftNodeId);
    const dropoffOrderNodeIds = new Set([
      ...meterNodeIds,
      ...this.topLiftOutboundClearanceNodeIds(liftNodeId),
      ...this.topLiftOutboundClearanceSweepNodeIds(liftNodeId)
    ]);
    const physicallyClaimsDropoffOrder = (nodeId: string): boolean =>
      this.topLiftNodeBelongsToLiftQueueOrService(nodeId, liftNodeId) ||
      dropoffOrderNodeIds.has(nodeId);
    if ([vehicle.currentNodeId, vehicle.currentEdgeId ? vehicle.targetNodeId : null]
      .filter((nodeId): nodeId is string => Boolean(nodeId))
      .some(physicallyClaimsDropoffOrder)) {
      return true;
    }
    if (this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    return [
      this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.localRouteNodeIds)
    ].some((routeTail) => routeTail.slice(0, 6).some(physicallyClaimsDropoffOrder));
  }

  private outboundStickyQueueGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string | null {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle?.loaded ||
      !vehicle.plannedGoalNodeId
    ) {
      return null;
    }
    const plannedQueueSlot =
      topLiftQueueEntrySlot(vehicle.plannedGoalNodeId) ??
      topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) ??
      this.topLiftOutboundMeterSlot(vehicle.plannedGoalNodeId);
    if (!plannedQueueSlot) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (plannedQueueSlot.liftNodeId !== liftNodeId) {
      return null;
    }
    const plannedMeterSlot = this.topLiftOutboundMeterSlot(vehicle.plannedGoalNodeId);
    if (plannedMeterSlot) {
      if (this.outboundEarlierDropoffBlockedByVehicle(task, vehicle)) {
        return null;
      }
      if (!this.outboundTaskHasEarlierDropoffTask(task)) {
        return null;
      }
      return this.outboundQueueNodeAvailableForVehicle(vehicle.plannedGoalNodeId, vehicle)
        ? vehicle.plannedGoalNodeId
        : null;
    }
    const alreadyInsideQueue = [vehicle.currentNodeId].some((nodeId) =>
      topLiftQueueEntrySlot(nodeId)?.liftNodeId === liftNodeId ||
      topLiftQueueParkingSlot(nodeId)?.liftNodeId === liftNodeId ||
      topLiftQueueAisleAccess(nodeId)?.liftNodeId === liftNodeId
    );
    if (!alreadyInsideQueue && !this.outboundQueueNodeAvailableForVehicle(vehicle.plannedGoalNodeId, vehicle)) {
      return null;
    }
    if (alreadyInsideQueue && vehicle.currentNodeId !== vehicle.plannedGoalNodeId) {
      return vehicle.plannedGoalNodeId;
    }
    return this.outboundTaskHasEarlierDropoffTask(task) ? vehicle.plannedGoalNodeId : null;
  }

  private outboundDropoffDispatchGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string {
    if (this.outboundLoadedVehicleAlreadyInServiceLane(task, vehicle)) {
      return task.dropoffNodeId;
    }
    const bottomLaneMeterClearanceHoldGoalNodeId = this.bottomLaneMeterClearanceHoldGoalNodeId(task, vehicle);
    if (bottomLaneMeterClearanceHoldGoalNodeId) {
      return bottomLaneMeterClearanceHoldGoalNodeId;
    }
    const earlierDropoffBlockedByVehicle = this.outboundEarlierDropoffBlockedByVehicle(task, vehicle);
    const stickyQueueGoalNodeId = this.outboundStickyQueueGoalNodeId(task, vehicle);
    if (stickyQueueGoalNodeId) {
      return stickyQueueGoalNodeId;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!this.outboundTaskHasEarlierDropoffTask(task)) {
      if (liftNodeId && !earlierDropoffBlockedByVehicle && this.topLiftOutboundClearanceActive(liftNodeId, vehicle?.id ?? null)) {
        return this.topLiftOutboundApproachMeterNodeIds(liftNodeId).find((nodeId) =>
          this.outboundQueueNodeAvailableForVehicle(nodeId, vehicle) &&
          (!vehicle || this.routeAvailable(vehicle.currentNodeId, nodeId))
        ) ?? this.topLiftOutboundApproachMeterNodeIds(liftNodeId)[0] ?? task.dropoffNodeId;
      }
      return task.dropoffNodeId;
    }
    const queueNodeId = this.topLiftOutboundQueueNodeIdForTask(task, vehicle);
    if (!queueNodeId) {
      const plannedGoalNodeId = vehicle?.plannedGoalNodeId ?? null;
      const plannedGoalStillBelongsToLift = plannedGoalNodeId && liftNodeId && (
        this.topLiftNodeBelongsToLiftQueueOrService(plannedGoalNodeId, liftNodeId) ||
        this.topLiftOutboundApproachMeterNodeIds(liftNodeId).includes(plannedGoalNodeId)
      );
      return plannedGoalStillBelongsToLift && !earlierDropoffBlockedByVehicle ? plannedGoalNodeId : task.dropoffNodeId;
    }
    if (vehicle && !this.routeAvailable(vehicle.currentNodeId, queueNodeId)) {
      const fallbackMeterNodeId = liftNodeId
        ? this.topLiftOutboundApproachMeterNodeIds(liftNodeId).find((nodeId) =>
            this.outboundQueueNodeAvailableForVehicle(nodeId, vehicle) &&
            this.routeAvailable(vehicle.currentNodeId, nodeId)
          ) ?? null
        : null;
      if (fallbackMeterNodeId) {
        return fallbackMeterNodeId;
      }
    }
    return queueNodeId;
  }

  private bottomLaneMeterClearanceHoldGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string | null {
    const mutableVehicle = vehicle && 'localRouteReason' in vehicle && 'yieldHoldNodeId' in vehicle
      ? vehicle as MutableVehicle
      : null;
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      !mutableVehicle?.loaded ||
      mutableVehicle.localRouteReason !== 'bottom-lane-meter-clearance' ||
      mutableVehicle.currentNodeId !== mutableVehicle.yieldHoldNodeId ||
      mutableVehicle.routeNodeIds.at(-1) !== mutableVehicle.currentNodeId ||
      !this.outboundTaskHasEarlierDropoffTask(task) ||
      topLiftAisleLevel(mutableVehicle.currentNodeId) !== 'bottom-b'
    ) {
      return null;
    }
    const currentColumn = this.topLiftColumnAccessColumn(mutableVehicle.currentNodeId);
    if (!currentColumn) {
      return null;
    }
    const siblingMeterNodeId = columnAccessNodeId('bottom-a', currentColumn - 1);
    return this.topLiftOutboundMeterSlot(siblingMeterNodeId) ? mutableVehicle.currentNodeId : null;
  }

  private outboundEarlierDropoffBlockedByVehicle(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): boolean {
    if (
      task.kind !== 'outbound' ||
      !vehicle?.loaded ||
      !this.topLiftColumnLayoutEnabled()
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return false;
    }
    const currentNodeId = vehicle.currentNodeId;
    return this.activeTasks().some((candidate) => {
      if (
        candidate.id === task.id ||
        candidate.kind !== 'outbound' ||
        this.taskLiftPortNodeId(candidate) !== liftNodeId ||
        !this.taskPrecedes(candidate, task) ||
        this.outboundTaskDropoffReleased(candidate)
      ) {
        return false;
      }
      const candidateVehicle = candidate.vehicleId
        ? this.vehicles.find((other) => other.id === candidate.vehicleId) ?? null
        : null;
      if (!candidateVehicle?.loaded) {
        return false;
      }
      if (candidateVehicle.blockingVehicleId === vehicle.id && candidateVehicle.targetNodeId === currentNodeId) {
        return true;
      }
      const routeTail = this.vehicleRouteTail(candidateVehicle, candidateVehicle.routeNodeIds);
      return routeTail.slice(1, 5).includes(currentNodeId);
    });
  }

  private topLiftOutboundClearanceActive(liftNodeId: string, excludedVehicleId: string | null): boolean {
    const clearanceNodeIds = new Set(this.topLiftOutboundClearanceNodeIds(liftNodeId));
    if (clearanceNodeIds.size === 0) {
      return false;
    }
    return this.vehicles.some((vehicle) =>
      vehicle.id !== excludedVehicleId &&
      !vehicle.taskId &&
      !vehicle.loaded &&
      (clearanceNodeIds.has(vehicle.currentNodeId) || (vehicle.targetNodeId !== null && clearanceNodeIds.has(vehicle.targetNodeId)))
    );
  }

  private topLiftOutboundClearanceNodeIds(liftNodeId: string): string[] {
    const dropoffNodeId = this.topLiftOutboundDropoffStopNodeId(liftNodeId);
    const nodeIds: string[] = [];
    if (dropoffNodeId) {
      nodeIds.push(dropoffNodeId);
      const exitNodeId = this.topLiftOutboundDropoffExitNodeId(dropoffNodeId);
      if (exitNodeId) {
        nodeIds.push(exitNodeId);
      }
    }
    return nodeIds.filter((nodeId, index, ids) =>
      this.layoutNode(nodeId) !== null && ids.indexOf(nodeId) === index
    );
  }

  private topLiftOutboundClearanceSweepNodeIds(liftNodeId: string): string[] {
    const dropoffNodeId = this.topLiftOutboundDropoffStopNodeId(liftNodeId);
    const dropoffNode = dropoffNodeId ? this.layoutNode(dropoffNodeId) : null;
    if (!dropoffNodeId || !dropoffNode || !isTopLiftAisleLevelNodeId(dropoffNodeId, 'bottom-b')) {
      return dropoffNodeId ? [dropoffNodeId] : [];
    }
    const direction = this.topLiftOutboundClearanceDirections(liftNodeId, dropoffNodeId)[0] ?? 1;
    const nodeIds = [dropoffNodeId];
    for (let offset = 1; offset <= 3; offset += 1) {
      const node = this.topLiftRailNodeAtOffset('bottom-b', dropoffNode, direction, offset);
      if (node) {
        nodeIds.push(node.id);
      }
    }
    return nodeIds.filter((nodeId, index, ids) =>
      this.layoutNode(nodeId) !== null && ids.indexOf(nodeId) === index
    );
  }

  private activeTopLiftOutboundDockSweepBlockedNodeIds(requesterVehicleId: string): Set<string> {
    const blockedNodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return blockedNodeIds;
    }
    for (const vehicle of this.vehicles) {
      if (vehicle.id === requesterVehicleId) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      let liftNodeId: string | null = null;
      if (
        task?.kind === 'outbound' &&
        task.completedAtSec === null &&
        (vehicle.loaded || vehicle.state === 'lowering' || task.state === 'in-progress')
      ) {
        liftNodeId = this.taskLiftPortNodeId(task);
      } else if (
        !vehicle.taskId &&
        !vehicle.loaded &&
        (vehicle.localRouteReason === 'outbound-lift-clearance' || vehicle.localRouteReason === 'outbound-lift-clearance-hold')
      ) {
        liftNodeId = this.outboundLiftNodeIdFromClearanceRoute(vehicle.plannedRouteNodeIds) ??
          this.outboundLiftNodeIdFromClearanceRoute(vehicle.routeNodeIds) ??
          this.outboundLiftNodeIdFromDockCorridorRoute(vehicle.plannedRouteNodeIds) ??
          this.outboundLiftNodeIdFromDockCorridorRoute(vehicle.routeNodeIds);
      }
      if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
        continue;
      }
      for (const nodeId of this.topLiftOutboundClearanceSweepNodeIds(liftNodeId)) {
        blockedNodeIds.add(nodeId);
      }
    }
    return blockedNodeIds;
  }

  private outboundLiftNodeIdFromDockCorridorRoute(routeNodeIds: string[]): string | null {
    for (const nodeId of routeNodeIds) {
      const liftNodeId = this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(nodeId);
      if (liftNodeId && this.liftPortKindForNodeId(liftNodeId) === 'outbound') {
        return liftNodeId;
      }
    }
    return null;
  }

  private topLiftOutboundClearanceOrMeterNode(nodeId: string): boolean {
    return this.topLiftColumnLayoutEnabled() && this.outboundLiftNodes().some((liftNode) =>
      this.topLiftOutboundClearanceNodeIds(liftNode.id).includes(nodeId) ||
      this.topLiftOutboundApproachMeterNodeIds(liftNode.id).includes(nodeId)
    );
  }

  private routeAvailable(fromNodeId: string, toNodeId: string): boolean {
    try {
      this.shortestPath(fromNodeId, toNodeId);
      return true;
    } catch {
      return false;
    }
  }

  private outboundQueueNodeAvailableForVehicle(queueNodeId: string, vehicle?: MutableVehicle | VehicleState | null): boolean {
    const occupantId = this.currentNodeOccupancy.get(queueNodeId);
    if (occupantId && occupantId !== vehicle?.id) {
      return false;
    }
    return !this.nodeClaimedByOtherVehicle(queueNodeId, vehicle?.id ?? '');
  }

  private outboundLoadedVehicleAlreadyInServiceLane(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): boolean {
    if (task.kind !== 'outbound' || !vehicle?.loaded || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    if (vehicle.currentNodeId === task.dropoffNodeId) {
      return true;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return false;
    }
    const currentBuffer = liftBufferParentNodeId(vehicle.currentNodeId);
    if (currentBuffer?.liftNodeId === liftNodeId) {
      return true;
    }
    const currentBufferAccessLiftNodeId = /^(lift-\d{2}-outbound)-buffer-access$/.exec(vehicle.currentNodeId)?.[1] ?? null;
    if (currentBufferAccessLiftNodeId === liftNodeId) {
      return true;
    }
    const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    if (currentEntrySlot?.liftNodeId === liftNodeId) {
      return true;
    }
    const currentServiceLiftNodeId = /^(lift-\d{2}-outbound)-queue-\d{2}-service-exit$/.exec(vehicle.currentNodeId)?.[1] ?? null;
    return currentServiceLiftNodeId === liftNodeId;
  }

  private taskDispatchGoalNodeId(task: TaskStateRecord, vehicle?: MutableVehicle | VehicleState | null): string {
    if (task.kind === 'inbound' && !vehicle?.loaded) {
      return this.inboundPickupDispatchGoalNodeId(task, vehicle);
    }
    if (task.kind === 'outbound' && vehicle?.loaded) {
      return this.outboundDropoffDispatchGoalNodeId(task, vehicle);
    }
    return vehicle?.loaded ? task.dropoffNodeId : task.pickupNodeId;
  }

  private inboundPickupClearanceRouteActive(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    const liftNodeId = this.taskLiftPortNodeId(task);
    const terminalNodeId = vehicle.routeNodeIds.at(-1) ?? null;
    const terminalSlot = terminalNodeId ? this.topLiftInboundApproachQueueSlot(terminalNodeId) : null;
    const terminalTopAColumn = terminalNodeId && isTopLiftAisleLevelNodeId(terminalNodeId, 'top-a')
      ? this.topLiftColumnAccessColumn(terminalNodeId)
      : null;
    const terminalTopBColumn = terminalNodeId && isTopLiftAisleLevelNodeId(terminalNodeId, 'top-b')
      ? this.topLiftColumnAccessColumn(terminalNodeId)
      : null;
    const pickupIsProjectedTopA = isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-a');
    const pickupTopAColumn = pickupIsProjectedTopA
      ? this.topLiftColumnAccessColumn(task.pickupNodeId)
      : null;
    const pickupIsProjectedTopB = isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-b');
    const pickupTopBColumn = pickupIsProjectedTopB
      ? this.topLiftColumnAccessColumn(task.pickupNodeId)
      : null;
    const terminalClearsPickup = terminalNodeId !== null &&
      terminalNodeId !== task.pickupNodeId &&
      terminalNodeId !== vehicle.currentNodeId &&
      (
        terminalSlot?.liftNodeId === liftNodeId ||
        this.isStorageNode(terminalNodeId) ||
        (terminalTopAColumn !== null && terminalTopAColumn === pickupTopBColumn) ||
        (terminalTopBColumn !== null && terminalTopBColumn === pickupTopAColumn)
      );
    return task.kind === 'inbound' &&
      liftNodeId !== null &&
      terminalClearsPickup &&
      vehicle.routeNodeIds[vehicle.routeIndex] === vehicle.currentNodeId &&
      vehicle.routeNodeIds[vehicle.routeIndex + 1] !== undefined;
  }

  private syncActiveInboundPickupClearanceRoute(vehicle: MutableVehicle, task: TaskStateRecord): void {
    const route = this.vehicleRouteTail(vehicle, vehicle.routeNodeIds);
    if (route.length < 2 || route[0] !== vehicle.currentNodeId) {
      return;
    }
    const terminalNodeId = route.at(-1) ?? null;
    if (!terminalNodeId) {
      return;
    }
    const alreadySynced =
      vehicle.plannedGoalNodeId === terminalNodeId &&
      vehicle.plannedRouteNodeIds.join('>') === route.join('>') &&
      vehicle.localRouteNodeIds.join('>') === route.join('>');
    vehicle.plannedGoalNodeId = terminalNodeId;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'temporary-yield';
    vehicle.yieldHoldUntilSec ??= round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 1);
    vehicle.yieldHoldNodeId ??= terminalNodeId;
    if (!alreadySynced) {
      this.logAgentReroute(vehicle, task, task.pickupNodeId, route, 'inbound-pickup-clearance-route-synced', { countTaskReplan: false });
    }
  }

  private rerouteInboundPickupVehicleBehindEarlierTask(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'inbound' ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      (this.inboundTaskLoadReadyAtPickup(task) && !this.inboundTaskShouldWaitBeforePickup(task))
    ) {
      return false;
    }
    const queueNodeId = this.topLiftInboundQueueNodeIdForTask(task, vehicle);
    const queueClearanceRoute = queueNodeId && queueNodeId !== vehicle.currentNodeId
      ? this.topLiftInboundPrematurePickupQueueRoute(vehicle.currentNodeId, queueNodeId)
      : null;
    const nominalQueueRoute = queueNodeId && queueNodeId !== vehicle.currentNodeId
      ? queueClearanceRoute ?? (this.agentRefreshEnabled()
          ? this.agentRefreshShortestPath(
              vehicle.currentNodeId,
              queueNodeId,
              this.agentRefreshBlockedNodeIds(vehicle, task, queueNodeId)
            )
          : this.shortestPath(vehicle.currentNodeId, queueNodeId))
      : null;
    const candidateRoutes = [
      nominalQueueRoute,
      this.topLiftInboundPrematureProjectedPickupRetreatRoute(vehicle, task),
      this.topLiftInboundPrematurePickupTopAHoldRoute(vehicle, task),
      this.topLiftInboundPrematurePickupStoragePocketRoute(vehicle, task)
    ].filter((route): route is string[] => Boolean(route));
    const route = candidateRoutes.find((candidateRoute) =>
      this.topLiftInboundPrematurePickupClearanceRouteAllowed(vehicle, task, candidateRoute)
    );
    if (!route) {
      return false;
    }
    const nextNodeId = route[1] ?? null;
    if (!nextNodeId) {
      return false;
    }
    const block = this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
          : this.agentMoveBlocker(vehicle, nextNodeId)
      : null;
    if (block) {
      return false;
    }
    const reason = this.inboundTaskHasEarlierPickupTask(task)
      ? 'inbound-pickup-clears-earlier-load'
      : this.topLiftInboundColumnPredecessorPending(task)
        ? 'inbound-pickup-clears-column-predecessor'
        : 'inbound-pickup-clears-unready-source';
    this.installInboundPickupClearanceRoute(vehicle, task, route, reason);
    return true;
  }

  private installInboundPickupClearanceRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    route: string[],
    reason: string,
    holdUntilExtraSec = 1
  ): void {
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'temporary-yield';
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + holdUntilExtraSec);
    vehicle.yieldHoldNodeId = route.at(-1) ?? null;
    this.logAgentReroute(vehicle, task, task.pickupNodeId, route, reason, { countTaskReplan: false });
  }

  private topLiftInboundPrematurePickupClearanceRouteAllowed(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    route: string[]
  ): boolean {
    if (route.length < 2 || route[0] !== vehicle.currentNodeId || !this.routeEdgesExist(route)) {
      return false;
    }
    if (
      route.some((nodeId) => isTopLiftAisleLevelNodeId(nodeId, 'top-a')) &&
      !this.topLiftInboundPrematurePickupTopAHoldRouteAllowed(vehicle, route) &&
      !this.topLiftInboundPrematureProjectedPickupClearanceRouteAllowed(vehicle, task, route)
    ) {
      return false;
    }
    return this.agentRefreshLocalRouteNodesClear(vehicle, route);
  }

  private topLiftInboundPrematureProjectedPickupRetreatRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord
  ): string[] | null {
    const liftNodeId = this.taskLiftPortNodeId(task);
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      !liftNodeId ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      this.topLiftInboundPickupStopNodeId(liftNodeId) !== task.pickupNodeId ||
      pickupColumn === null ||
      !isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-a')
    ) {
      return null;
    }
    const retreatColumn = pickupColumn - this.topLiftQueueDisplayDirection(liftNodeId);
    const candidateRoutes = [
      [vehicle.currentNodeId, columnAccessNodeId('top-a', retreatColumn - 1)],
      [vehicle.currentNodeId, columnAccessNodeId('top-b', pickupColumn - 1)]
    ];
    return candidateRoutes.find((route) =>
      this.layoutNode(route[1]!) &&
      this.routeEdgesExist(route)
    ) ?? null;
  }

  private topLiftInboundPrematureProjectedPickupClearanceRouteAllowed(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    route: string[]
  ): boolean {
    const liftNodeId = this.taskLiftPortNodeId(task);
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    const terminalNodeId = route.at(-1) ?? null;
    const terminalColumn = terminalNodeId ? this.topLiftColumnAccessColumn(terminalNodeId) : null;
    const terminalSlot = terminalNodeId ? this.topLiftInboundApproachQueueSlot(terminalNodeId) : null;
    const terminalIsProjectedQueueSlot = terminalSlot?.liftNodeId === liftNodeId;
    const terminalIsSameColumnTopBHold =
      Boolean(terminalNodeId) &&
      isTopLiftAisleLevelNodeId(terminalNodeId!, 'top-b') &&
      terminalColumn === pickupColumn;
    if (
      !liftNodeId ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      this.topLiftInboundPickupStopNodeId(liftNodeId) !== task.pickupNodeId ||
      pickupColumn === null ||
      terminalColumn === null ||
      !route.every((nodeId) => isTopLiftAisleLevelNodeId(nodeId, 'top-a') || isTopLiftAisleLevelNodeId(nodeId, 'top-b'))
    ) {
      return false;
    }
    if (terminalIsProjectedQueueSlot || terminalIsSameColumnTopBHold) {
      return true;
    }
    return terminalColumn === pickupColumn - this.topLiftQueueDisplayDirection(liftNodeId);
  }

  private topLiftInboundPrematurePickupTopAHoldRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord
  ): string[] | null {
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      pickupColumn === null ||
      !isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-b')
    ) {
      return null;
    }
    const holdNodeId = columnAccessNodeId('top-a', pickupColumn - 1);
    const route = [vehicle.currentNodeId, holdNodeId];
    if (!this.layoutNode(holdNodeId) || !this.routeEdgesExist(route)) {
      return null;
    }
    if (!this.topLiftInboundPrematurePickupTopAHoldRouteAllowed(vehicle, route)) {
      return null;
    }
    return route;
  }

  private topLiftInboundPrematurePickupTopAHoldRouteAllowed(vehicle: MutableVehicle, route: string[]): boolean {
    if (route.length !== 2 || route[0] !== vehicle.currentNodeId) {
      return false;
    }
    const fromColumn = this.topLiftColumnAccessColumn(route[0]!);
    const toColumn = this.topLiftColumnAccessColumn(route[1]!);
    if (
      fromColumn === null ||
      toColumn === null ||
      fromColumn !== toColumn ||
      !isTopLiftAisleLevelNodeId(route[0]!, 'top-b') ||
      !isTopLiftAisleLevelNodeId(route[1]!, 'top-a')
    ) {
      return false;
    }
    const holdNodeId = route[1]!;
    const occupantId = this.currentNodeOccupancy.get(holdNodeId);
    return (!occupantId || occupantId === vehicle.id) &&
      !this.nodeClaimedByOtherVehicle(holdNodeId, vehicle.id) &&
      this.agentMinimalYieldFirstLegSafe(vehicle, route[0]!, holdNodeId);
  }

  private tryAdvanceInboundPickupTopAHoldAway(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'top-a') ||
      !isTopLiftAisleLevelNodeId(task.pickupNodeId, 'top-b') ||
      (this.inboundTaskLoadReadyAtPickup(task) && !this.inboundTaskShouldWaitBeforePickup(task))
    ) {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    if (currentColumn === null || pickupColumn === null || currentColumn !== pickupColumn) {
      return false;
    }
    const activeNextNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 1] ?? null;
    if (
      activeNextNodeId &&
      isTopLiftAisleLevelNodeId(activeNextNodeId, 'top-a') &&
      this.topLiftColumnAccessColumn(activeNextNodeId) !== currentColumn
    ) {
      return false;
    }

    const route = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'top-a'))
      .filter((neighbor) => this.topLiftColumnAccessColumn(neighbor.nodeId) !== currentColumn)
      .filter((neighbor) => {
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        return (!occupantId || occupantId === vehicle.id) &&
          !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id) &&
          this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId);
      })
      .sort((left, right) =>
        Math.abs((this.topLiftColumnAccessColumn(left.nodeId) ?? currentColumn) - currentColumn) -
          Math.abs((this.topLiftColumnAccessColumn(right.nodeId) ?? currentColumn) - currentColumn) ||
        left.nodeId.localeCompare(right.nodeId)
      )
      .map((neighbor) => [vehicle.currentNodeId, neighbor.nodeId])
      .find((candidateRoute) => this.routeEdgesExist(candidateRoute) && this.agentRefreshLocalRouteNodesClear(vehicle, candidateRoute));
    if (!route) {
      return false;
    }
    this.installInboundPickupClearanceRoute(vehicle, task, route, 'inbound-pickup-top-a-hold-advance', 2);
    return true;
  }

  private tryClearInboundTopASpineRouteUnavailable(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    const liftNodeId = this.taskLiftPortNodeId(task);
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !liftNodeId ||
      pickupColumn === null ||
      !isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-a')
    ) {
      return false;
    }

    const preferredColumn = pickupColumn - this.topLiftQueueDisplayDirection(liftNodeId);
    const candidates = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'top-a'))
      .map((neighbor) => ({
        nodeId: neighbor.nodeId,
        column: this.topLiftColumnAccessColumn(neighbor.nodeId) ?? Number.MAX_SAFE_INTEGER
      }))
      .sort((left, right) =>
        (left.column === preferredColumn ? 0 : 1) - (right.column === preferredColumn ? 0 : 1) ||
        (left.nodeId === task.pickupNodeId ? 1 : 0) - (right.nodeId === task.pickupNodeId ? 1 : 0) ||
        Math.abs(left.column - preferredColumn) - Math.abs(right.column - preferredColumn) ||
        left.nodeId.localeCompare(right.nodeId)
      );

    for (const candidate of candidates) {
      const route = [vehicle.currentNodeId, candidate.nodeId];
      if (
        this.routeEdgesExist(route) &&
        this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, candidate.nodeId) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, route) &&
        !this.agentRefreshMoveBlocker(vehicle, candidate.nodeId, route)
      ) {
        this.installInboundPickupClearanceRoute(vehicle, task, route, 'inbound-top-a-spine-clears-unavailable-queue', 1);
        return true;
      }
    }
    return false;
  }

  private topLiftReadyInboundFollowerBehindQueueSlot(
    task: TaskStateRecord,
    vehicle: MutableVehicle,
    currentSlot: { liftNodeId: string; slotIndex: number }
  ): MutableVehicle | null {
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || currentSlot.liftNodeId !== liftNodeId) {
      return null;
    }
    return this.vehicles
      .map((candidate) => {
        if (candidate.id === vehicle.id || candidate.loaded) {
          return null;
        }
        const candidateTask = this.taskForVehicle(candidate);
        if (
          candidateTask?.kind !== 'inbound' ||
          candidateTask.pickupNodeId !== task.pickupNodeId ||
          this.taskLiftPortNodeId(candidateTask) !== liftNodeId ||
          !this.inboundTaskLoadReadyAtPickup(candidateTask)
        ) {
          return null;
        }
        const candidateSlot =
          this.topLiftInboundApproachQueueSlot(candidate.currentNodeId) ??
          this.topLiftInboundApproachQueueSlot(candidate.targetNodeId ?? '') ??
          this.topLiftInboundApproachQueueSlot(candidate.plannedGoalNodeId ?? '');
        if (!candidateSlot || candidateSlot.liftNodeId !== liftNodeId || candidateSlot.slotIndex <= currentSlot.slotIndex) {
          return null;
        }
        return { vehicle: candidate, slotIndex: candidateSlot.slotIndex };
      })
      .filter((candidate): candidate is { vehicle: MutableVehicle; slotIndex: number } => candidate !== null)
      .sort((left, right) => left.slotIndex - right.slotIndex || left.vehicle.id.localeCompare(right.vehicle.id))[0]?.vehicle ?? null;
  }

  private tryYieldUnreadyInboundQueueLeader(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'top-a')
    ) {
      return false;
    }
    this.prepareInboundSourceLoadForStagedPickup(task, vehicle);
    if (this.inboundTaskLoadReadyAtPickup(task)) {
      return false;
    }
    if (
      vehicle.localRouteReason === 'inbound-unready-queue-leader-yield' &&
      vehicle.plannedGoalNodeId !== null &&
      vehicle.plannedGoalNodeId !== vehicle.currentNodeId &&
      vehicle.localRouteNodeIds[0] === vehicle.currentNodeId
    ) {
      return false;
    }
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!currentSlot || !liftNodeId || currentSlot.liftNodeId !== liftNodeId) {
      return false;
    }
    const readyFollower = this.topLiftReadyInboundFollowerBehindQueueSlot(task, vehicle, currentSlot);
    if (!readyFollower) {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    if (currentColumn === null) {
      return false;
    }
    const sideNodeId = columnAccessNodeId('top-b', currentColumn - 1);
    const route = [vehicle.currentNodeId, sideNodeId];
    const occupantId = this.currentNodeOccupancy.get(sideNodeId);
    if (
      !this.layoutNode(sideNodeId) ||
      !this.routeEdgesExist(route) ||
      (occupantId && occupantId !== vehicle.id) ||
      this.nodeClaimedByOtherVehicle(sideNodeId, vehicle.id) ||
      !this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, sideNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, route) ||
      this.agentRefreshMoveBlocker(vehicle, sideNodeId, route)
    ) {
      return false;
    }
    this.installInboundPickupClearanceRoute(vehicle, task, route, 'inbound-unready-queue-leader-yield', 2);
    vehicle.localRouteReason = 'inbound-unready-queue-leader-yield';
    this.logEvent('queue-yield', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, sideNodeId, 'inbound-unready-queue-leader-yield', this.vehiclePosition(vehicle), {
      liftNodeId,
      followerVehicleId: readyFollower.id
    });
    return true;
  }

  private tryAdvanceTopAHoldAwayFromQueueBlocker(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    blockedTopBNodeId: string,
    blockingVehicleId: string | null
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'top-a') ||
      !isTopLiftAisleLevelNodeId(blockedTopBNodeId, 'top-b')
    ) {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTopBNodeId);
    if (currentColumn === null || blockedColumn === null || currentColumn !== blockedColumn) {
      return false;
    }
    const blocker = this.inboundQueueFootprintBlockerForTopBNode(blockedTopBNodeId, vehicle.id, blockingVehicleId);
    if (!blocker) {
      return false;
    }

    const referenceColumn =
      this.topLiftColumnAccessColumn(task.pickupNodeId) ??
      this.storageGridPosition(task.pickupNodeId)?.column ??
      this.storageGridPosition(task.dropoffNodeId)?.column ??
      null;
    const preferredDirection = referenceColumn === null ? 1 : Math.sign(currentColumn - referenceColumn) || 1;
    const route = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'top-a'))
      .filter((neighbor) => this.topLiftColumnAccessColumn(neighbor.nodeId) !== currentColumn)
      .filter((neighbor) => {
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        return (!occupantId || occupantId === vehicle.id) &&
          !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id) &&
          this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId);
      })
      .sort((left, right) => {
        const leftColumn = this.topLiftColumnAccessColumn(left.nodeId) ?? currentColumn;
        const rightColumn = this.topLiftColumnAccessColumn(right.nodeId) ?? currentColumn;
        const leftDirectionScore = Math.sign(leftColumn - currentColumn) === preferredDirection ? 0 : 1;
        const rightDirectionScore = Math.sign(rightColumn - currentColumn) === preferredDirection ? 0 : 1;
        return leftDirectionScore - rightDirectionScore ||
          Math.abs(leftColumn - currentColumn) - Math.abs(rightColumn - currentColumn) ||
          left.nodeId.localeCompare(right.nodeId);
      })
      .map((neighbor) => [vehicle.currentNodeId, neighbor.nodeId])
      .find((candidateRoute) =>
        this.routeEdgesExist(candidateRoute) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, candidateRoute) &&
        !this.agentRefreshMoveBlocker(vehicle, candidateRoute[1]!, candidateRoute)
      );
    if (!route) {
      return false;
    }
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'temporary-yield';
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 2);
    vehicle.yieldHoldNodeId = route.at(-1) ?? null;
    this.logAgentReroute(vehicle, task, blockedTopBNodeId, route, 'top-a-queue-blocker-hold-advance', { countTaskReplan: false });
    return true;
  }

  private inboundQueueFootprintBlockerForTopBNode(
    topBNodeId: string,
    requesterVehicleId: string,
    preferredBlockingVehicleId: string | null = null
  ): MutableVehicle | null {
    if (!isTopLiftAisleLevelNodeId(topBNodeId, 'top-b')) {
      return null;
    }
    const topBPosition = nodePosition(this.scenario, topBNodeId);
    const requester = this.vehicles.find((candidate) => candidate.id === requesterVehicleId) ?? null;
    const projectedRequester = {
      x: topBPosition.x,
      z: topBPosition.z,
      yaw: requester?.yaw ?? 0
    };
    const preferred = preferredBlockingVehicleId
      ? this.vehicles.find((candidate) => candidate.id === preferredBlockingVehicleId) ?? null
      : null;
    const candidates = [preferred, ...this.vehicles].reduce<MutableVehicle[]>((acc, candidate) => {
      if (
        candidate &&
        candidate.id !== requesterVehicleId &&
        !acc.some((entry) => entry.id === candidate.id)
      ) {
        acc.push(candidate);
      }
      return acc;
    }, []);
    const topBColumn = this.topLiftColumnAccessColumn(topBNodeId);
    return candidates.find((candidate) => {
      if (
        candidate.loaded ||
        !this.topLiftFifoHeldVehicle(candidate) ||
        !this.topLiftInboundQueueAreaNode(candidate.currentNodeId)
      ) {
        return false;
      }
      if (candidate.id === preferredBlockingVehicleId) {
        return true;
      }
      if (vehicleFootprintsOverlap(projectedRequester, candidate, this.scenario.vehicles)) {
        return true;
      }
      const candidateSlot = this.topLiftQueueSlotForNode(candidate.currentNodeId);
      return Boolean(
        candidateSlot &&
        topBColumn !== null &&
        this.topLiftStorageColumnNumbersForLift(candidateSlot.liftNodeId).includes(topBColumn)
      );
    }) ?? null;
  }

  private topLiftInboundPrematurePickupStoragePocketRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord
  ): string[] | null {
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      !liftNodeId ||
      this.topLiftServiceStopLiftNodeId('inbound', vehicle.currentNodeId) !== liftNodeId
    ) {
      return null;
    }

    const candidate = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => this.layoutNode(neighbor.nodeId)?.type === 'storage')
      .filter((neighbor) => this.topLiftInboundPrematurePickupStorageNodeAllowed(vehicle, task, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftPosition = this.storageGridPosition(left.nodeId);
        const rightPosition = this.storageGridPosition(right.nodeId);
        return (leftPosition?.row ?? Number.MAX_SAFE_INTEGER) - (rightPosition?.row ?? Number.MAX_SAFE_INTEGER) ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0];
    return candidate ? [vehicle.currentNodeId, candidate.nodeId] : null;
  }

  private topLiftInboundPrematurePickupStorageNodeAllowed(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    nodeId: string
  ): boolean {
    if (this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId)) {
      return true;
    }
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'inbound' ||
      vehicle.currentNodeId !== task.pickupNodeId ||
      !this.isStorageNode(nodeId)
    ) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if ((occupantId && occupantId !== vehicle.id) || this.nodeClaimedByOtherVehicle(nodeId, vehicle.id) || this.storedLoadIdAtNode(nodeId)) {
      return false;
    }
    if (this.activeInboundDropoffNodeIds().has(nodeId)) {
      return false;
    }
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    const pocketPosition = this.storageGridPosition(nodeId);
    return pickupColumn !== null && pocketPosition?.column === pickupColumn && pocketPosition.row === 1;
  }

  private topLiftInboundPrematurePickupQueueRoute(currentNodeId: string, queueNodeId: string): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const serviceSlot = topLiftQueueServiceSlot(currentNodeId);
    const queueSlot = topLiftQueueParkingSlot(queueNodeId);
    if (
      !serviceSlot ||
      !queueSlot ||
      serviceSlot.liftNodeId !== queueSlot.liftNodeId ||
      this.liftPortKindForNodeId(serviceSlot.liftNodeId) !== 'inbound'
    ) {
      return null;
    }
    const currentEntryNodeId = liftQueueTailEntryNodeId(serviceSlot.liftNodeId, serviceSlot.slotIndex);
    const currentAccessNodeId = liftQueueTailAccessNodeId(serviceSlot.liftNodeId, serviceSlot.slotIndex);
    const queueAccessTail = Array.from({ length: Math.abs(queueSlot.slotIndex - serviceSlot.slotIndex) + 1 }, (_, index) => {
      const direction = Math.sign(queueSlot.slotIndex - serviceSlot.slotIndex);
      return liftQueueTailAccessNodeId(serviceSlot.liftNodeId, serviceSlot.slotIndex + direction * index);
    });
    const route = [
      currentNodeId,
      currentEntryNodeId,
      currentAccessNodeId,
      ...queueAccessTail,
      queueNodeId
    ].filter((nodeId, index, nodeIds) => index === 0 || nodeId !== nodeIds[index - 1]);
    return this.routeEdgesExist(route) ? route : null;
  }

  private waitForInboundPickupLoad(vehicle: MutableVehicle, task: TaskStateRecord, dtSec: number): void {
    if (this.holdInboundPickupBeforePredecessor(vehicle, task, dtSec)) {
      return;
    }
    if (!this.inboundTaskShouldWaitBeforePickup(task) || vehicle.currentNodeId === task.pickupNodeId) {
      this.prepareInboundSourceLoadForStagedPickup(task, vehicle);
      if (this.inboundTaskLoadReadyAtPickup(task)) {
        this.startInboundPickupLift(vehicle, task, vehicle.currentNodeId);
        return;
      }
    }
    vehicle.state = 'waiting-blocked';
    vehicle.speedMps = 0;
    vehicle.waitReason = 'inbound-source-not-at-pickup';
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec ??= this.simTimeSec;
    vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
    this.blockedTimeByReasonSec.set('inbound-source-not-at-pickup', round((this.blockedTimeByReasonSec.get('inbound-source-not-at-pickup') ?? 0) + dtSec));
    this.logEvent('vehicle-waiting', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, task.pickupNodeId, 'inbound-source-not-at-pickup', this.vehiclePosition(vehicle), {});
  }

  private holdInboundPickupBeforePredecessor(vehicle: MutableVehicle, task: TaskStateRecord, dtSec: number): boolean {
    if (task.kind !== 'inbound' || !this.inboundTaskShouldWaitBeforePickup(task)) {
      return false;
    }
    if (this.inboundPickupClearanceRouteActive(vehicle, task)) {
      this.syncActiveInboundPickupClearanceRoute(vehicle, task);
      return true;
    }
    if (this.rerouteInboundPickupVehicleBehindEarlierTask(vehicle, task)) {
      return true;
    }
    this.holdAtTopLiftQueueNode(vehicle, vehicle.currentNodeId, this.topLiftInboundQueueHoldReason(task), dtSec);
    return true;
  }

  private startInboundPickupLift(vehicle: MutableVehicle, task: TaskStateRecord, nodeId: string): void {
    this.setTaskState(task, 'in-progress');
    task.startedAtSec ??= this.simTimeSec;
    vehicle.state = 'lifting';
    vehicle.speedMps = 0;
    vehicle.phaseRemainingSec = this.scenario.physicsParams.liftTimeSec;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    this.ensureZoneHoldReservation(vehicle, nodeId);
    this.logEvent('lift-started', vehicle.id, task.id, task.loadId, nodeId, nodeId, 'pickup-aligned', this.vehiclePosition(vehicle), {});
  }

  private nextInboundSourceSlotNodeId(liftNodeId: string): string {
    const occupiedSlotNodeIds = new Set(
      this.inboundLiftWaitingSourceLoads(liftNodeId)
        .map((load) => load.nodeId)
        .filter((nodeId): nodeId is string => nodeId !== null)
    );
    return this.inboundSourceSlotNodeIds(liftNodeId).find((nodeId) => !occupiedSlotNodeIds.has(nodeId)) ?? liftNodeId;
  }

  private inboundSourceUnavailableReason(): string {
    const waitingSourceLoadCount = this.inboundLiftNodes()
      .filter((liftNode) => this.inboundLiftWaitingSourceLoad(liftNode.id))
      .length;
    return waitingSourceLoadCount > 0 ? 'inbound-lift-source-assigned' : 'inbound-lift-source-empty';
  }

  private primeInboundSourceBacklog(): void {
    if (!this.shouldPrimeInboundSourceBacklog()) {
      return;
    }

    this.replenishInboundSourceBuffers();
    const inboundLiftCount = this.scenario.layout.nodes.filter((node) => liftKindForNode(node) === 'inbound').length;
    const sourceCapacity = this.inboundSourceBacklogCapacity();
    const targetTaskCount = Math.min(
      this.topLiftColumnLayoutEnabled() ? sourceCapacity : inboundLiftCount,
      this.scenario.taskGeneration.maxTasks
    );
    while (this.activeTaskCount() < targetTaskCount) {
      const result = this.createTask('inbound');
      if (!result.created) {
        break;
      }
    }

    this.nextInboundSec = Math.max(this.nextInboundSec, this.nextArrivalInterval('inbound'));
  }

  private primeTopLiftOutboundFullColumns(): void {
    const seedColumnNumbers = this.initialTopLiftOutboundSeedColumnNumbers();
    if (
      !this.topLiftColumnLayoutEnabled() ||
      seedColumnNumbers.length === 0 ||
      this.scenario.taskGeneration.outboundRatePerHour <= 0
    ) {
      return;
    }

    const occupancy = this.storageNodeLoadOccupancy(false);
    for (const vehicle of this.vehicles) {
      occupancy.set(vehicle.currentNodeId, vehicle.id);
    }
    let seedIndex = 0;
    for (const column of seedColumnNumbers) {
      this.topLiftColumnFlowModes.set(column, 'outbound');
      for (const nodeId of this.topLiftStorageColumnNodeIds(column)) {
        if (occupancy.has(nodeId)) {
          continue;
        }
        seedIndex += 1;
        const position = this.storageGridPosition(nodeId);
        const load: LoadStateRecord = {
          id: `${OUTBOUND_SEED_LOAD_PREFIX}c${String(column).padStart(2, '0')}-r${String(position?.row ?? 0).padStart(2, '0')}-${String(seedIndex).padStart(4, '0')}`,
          state: 'stored',
          nodeId,
          vehicleId: null,
          weightKg: 450 + Math.round(this.rng.next() * 350)
        };
        this.pushLoad(load);
        occupancy.set(nodeId, load.id);
      }
    }
    if (seedIndex > 0) {
      this.logEvent('outbound-columns-seeded', null, null, null, null, null, 'initial-outbound-full-columns', null, {
        columns: seedColumnNumbers.map((column) => `c${String(column).padStart(2, '0')}`).join(','),
        policy: this.scenario.taskGeneration.initialStorageFillPolicy,
        loadCount: seedIndex
      });
    }
  }

  private initialTopLiftOutboundSeedColumnNumbers(): number[] {
    if (this.scenario.taskGeneration.initialStorageFillPolicy === 'zone-balanced-50') {
      return this.initialTopLiftZoneBalancedHalfFullColumnNumbers();
    }
    return this.initialTopLiftOutboundFullColumnNumbers(this.scenario.taskGeneration.initialOutboundFullColumns);
  }

  private initialTopLiftZoneBalancedHalfFullColumnNumbers(): number[] {
    const selected = new Set<number>();
    const inboundLiftNodes = this.inboundLiftNodes().sort((left, right) => left.x - right.x || left.id.localeCompare(right.id));
    if (inboundLiftNodes.length === 0) {
      return this.initialTopLiftOutboundFullColumnNumbers(Math.ceil(this.topLiftStorageColumnNumbers().length / 2));
    }

    for (const liftNode of inboundLiftNodes) {
      const columns = this.topLiftStorageColumnNumbersForLift(liftNode.id);
      const targetCount = Math.ceil(columns.length / 2);
      for (const column of columns.slice(0, targetCount)) {
        selected.add(column);
      }
    }

    return [...selected].sort((left, right) => left - right);
  }

  private initialTopLiftOutboundFullColumnNumbers(targetColumnCount: number): number[] {
    const columns = this.topLiftStorageColumnNumbers();
    if (columns.length === 0 || targetColumnCount <= 0) {
      return [];
    }

    const inboundLiftCount = this.inboundLiftNodes().length;
    const moduleCount = Math.max(1, inboundLiftCount);
    const columnsPerModule = Math.max(1, Math.floor(columns.length / moduleCount));
    const selected = new Set<number>();
    const columnsPerModuleTarget = Math.max(1, Math.ceil(targetColumnCount / moduleCount));

    for (let moduleIndex = 0; moduleIndex < moduleCount && selected.size < targetColumnCount; moduleIndex += 1) {
      const moduleStart = moduleIndex * columnsPerModule;
      const moduleColumns = columns.slice(moduleStart, moduleStart + columnsPerModule);
      const half = Math.max(1, Math.floor(moduleColumns.length / 2));
      const localCandidates = [
        ...moduleColumns.slice(0, half),
        ...moduleColumns.slice(half)
      ];
      for (const column of localCandidates.slice(0, columnsPerModuleTarget)) {
        selected.add(column);
        if (selected.size >= targetColumnCount) {
          break;
        }
      }
    }

    for (const column of columns) {
      if (selected.size >= targetColumnCount) {
        break;
      }
      selected.add(column);
    }

    return [...selected].sort((left, right) => left - right);
  }

  private shouldPrimeInboundSourceBacklog(): boolean {
    const inboundLiftCount = this.scenario.layout.nodes.filter((node) => liftKindForNode(node) === 'inbound').length;
    const outboundLiftCount = this.scenario.layout.nodes.filter((node) => liftKindForNode(node) === 'outbound').length;
    return (
      this.isInboundOnlyFlow() &&
      (outboundLiftCount === 0 || this.topLiftColumnLayoutEnabled()) &&
      inboundLiftCount > 1 &&
      this.scenario.taskGeneration.inboundRatePerHour >= 7200
    );
  }

  private inboundLiftHasWaitingSourceLoad(liftNodeId: string): boolean {
    return this.inboundLiftWaitingSourceLoad(liftNodeId) !== null;
  }

  private inboundSourceBacklogCapacity(): number {
    return this.inboundLiftNodes().reduce((sum, liftNode) => sum + this.inboundSourceBufferCapacity(liftNode.id), 0);
  }

  private inboundSourceBufferCapacity(_liftNodeId: string): number {
    if (!this.topLiftColumnLayoutEnabled()) {
      return 1;
    }
    return Math.max(1, Math.min(this.scenario.trafficPolicy.sourceBufferCapacity, this.inboundSourceSlotNodeIds(_liftNodeId).length));
  }

  private liftPortPlannedLoad(kind: 'inbound' | 'outbound', liftNodeId: string): number {
    return this.activeTasks().filter((task) =>
      task.kind === kind &&
      this.taskLiftPortNodeId(task) === liftNodeId
    ).length;
  }

  private taskLiftPortNodeId(task: TaskStateRecord): string | null {
    const candidateNodeId = task.kind === 'inbound' ? task.pickupNodeId : task.dropoffNodeId;
    const serviceStopLiftNodeId = this.topLiftServiceStopLiftNodeId(task.kind, candidateNodeId);
    if (serviceStopLiftNodeId) {
      return serviceStopLiftNodeId;
    }
    const bufferParent = liftBufferParentNodeId(candidateNodeId);
    if (bufferParent?.kind === task.kind) {
      return bufferParent.liftNodeId;
    }
    const serviceSlot = topLiftQueueServiceSlot(candidateNodeId);
    if (serviceSlot && this.liftPortKindForNodeId(serviceSlot.liftNodeId) === task.kind) {
      return serviceSlot.liftNodeId;
    }
    if (task.kind === 'inbound') {
      const projectedLiftNodeId = this.topLiftProjectedInboundLiftNodeId(candidateNodeId);
      if (projectedLiftNodeId) {
        return projectedLiftNodeId;
      }
    }
    return this.liftPortKindForNodeId(candidateNodeId) === task.kind ? candidateNodeId : null;
  }

  private topLiftProjectedInboundLiftNodeId(nodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const queueSlot =
      this.topLiftInboundApproachQueueSlot(nodeId) ??
      topLiftQueueParkingSlot(nodeId) ??
      topLiftQueueAisleAccess(nodeId) ??
      topLiftQueueEntrySlot(nodeId);
    if (queueSlot && this.liftPortKindForNodeId(queueSlot.liftNodeId) === 'inbound') {
      return queueSlot.liftNodeId;
    }
    if (!isTopLiftAisleLevelNodeId(nodeId, 'top-a') && !isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(nodeId);
    if (column === null) {
      return null;
    }
    return this.inboundLiftNodes().find((liftNode) => {
      const pickupStopNodeId = this.topLiftInboundPickupStopNodeId(liftNode.id);
      const pickupColumn = pickupStopNodeId ? this.topLiftColumnAccessColumn(pickupStopNodeId) : null;
      return pickupColumn === column;
    })?.id ?? null;
  }

  private liftPortKindForNodeId(nodeId: string): LiftKind | null {
    if (this.liftPortKindForNodeIdCache.has(nodeId)) {
      return this.liftPortKindForNodeIdCache.get(nodeId) ?? null;
    }
    const bufferParent = liftBufferParentNodeId(nodeId);
    if (bufferParent) {
      this.liftPortKindForNodeIdCache.set(nodeId, bufferParent.kind);
      return bufferParent.kind;
    }
    const serviceSlot = topLiftQueueServiceSlot(nodeId);
    if (serviceSlot) {
      const kind = /-inbound$/.test(serviceSlot.liftNodeId) ? 'inbound' : 'outbound';
      this.liftPortKindForNodeIdCache.set(nodeId, kind);
      return kind;
    }
    const node = this.layoutNodesById.get(nodeId);
    const kind = node ? liftKindForNode(node) : null;
    this.liftPortKindForNodeIdCache.set(nodeId, kind);
    return kind;
  }

  private isLiftPortCycleActive(kind: 'inbound' | 'outbound', liftNodeId: string): boolean {
    return this.vehicles.some((vehicle) =>
      ((kind === 'inbound' && vehicle.state === 'lifting') || (kind === 'outbound' && vehicle.state === 'lowering')) &&
      this.vehicleTaskLiftPortNodeId(vehicle) === liftNodeId
    );
  }

  private vehicleTaskLiftPortNodeId(vehicle: MutableVehicle | VehicleState): string | null {
    const task = this.taskById(vehicle.taskId);
    return task ? this.taskLiftPortNodeId(task) : null;
  }

  private nodeBelongsToLiftPort(nodeId: string, liftNodeId: string): boolean {
    if (nodeId === liftNodeId) {
      return true;
    }
    if (
      nodeId === this.topLiftInboundPickupStopNodeId(liftNodeId) ||
      nodeId === this.topLiftOutboundDropoffStopNodeId(liftNodeId)
    ) {
      return true;
    }
    if (nodeId === liftBufferAccessNodeId(liftNodeId)) {
      return true;
    }
    return liftBufferParentNodeId(nodeId)?.liftNodeId === liftNodeId ||
      topLiftQueueServiceSlot(nodeId)?.liftNodeId === liftNodeId;
  }

  private liftPortApproachCapacity(): number {
    return this.scenario.trafficPolicy.liftApproachCapacity;
  }

  private topLiftPortQueueCapacity(liftNodeId: string): number {
    if (!this.topLiftColumnLayoutEnabled()) {
      return 0;
    }
    return this.scenario.layout.nodes.filter((node) => topLiftQueueParkingSlot(node.id)?.liftNodeId === liftNodeId).length;
  }

  private topLiftPortStagedTaskCapacity(kind: 'inbound' | 'outbound', liftNodeId: string): number {
    if (!this.topLiftColumnLayoutEnabled()) {
      return this.effectiveLiftPortApproachCapacity(kind);
    }
    return Math.max(1, this.topLiftPortQueueCapacity(liftNodeId) + 1);
  }

  private effectiveLiftPortApproachCapacity(kind: 'inbound' | 'outbound'): number {
    if (this.topLiftColumnLayoutEnabled() && kind === 'outbound') {
      return 1;
    }
    return this.liftPortApproachCapacity();
  }

  private liftPortApproachCount(kind: 'inbound' | 'outbound', liftNodeId: string): number {
    return this.activeTasks().filter((task) =>
      task.kind === kind &&
      task.state !== 'queued' &&
      this.taskLiftPortNodeId(task) === liftNodeId &&
      this.taskStillConsumesLiftApproachSlot(task, kind, liftNodeId)
    ).length;
  }

  private taskStillConsumesLiftApproachSlot(task: TaskStateRecord, kind: 'inbound' | 'outbound', liftNodeId: string): boolean {
    const vehicle = task.vehicleId ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) : null;
    if (vehicle && (vehicle.currentNodeId === liftNodeId || vehicle.targetNodeId === liftNodeId)) {
      return true;
    }
    if (kind === 'inbound') {
      const load = this.loadById(task.loadId);
      return task.state === 'assigned' || this.inboundSourceLoadBelongsToLift(load, liftNodeId);
    }
    return true;
  }

  private vehicleLiftPortWindowContains(vehicle: MutableVehicle, liftNodeId: string): boolean {
    return (
      vehicle.routeNodeIds[vehicle.routeIndex + 1] === liftNodeId ||
      vehicle.routeNodeIds[vehicle.routeIndex + 2] === liftNodeId
    );
  }

  private routeLiftPortAfterTarget(vehicle: MutableVehicle, toNodeId: string): { liftNodeId: string; kind: LiftKind } | null {
    if (vehicle.routeNodeIds[vehicle.routeIndex + 1] !== toNodeId) {
      return null;
    }
    const liftNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 2];
    if (!liftNodeId) {
      return null;
    }
    const kind = this.liftPortKindForNodeId(liftNodeId);
    const parent = liftBufferParentNodeId(liftNodeId);
    return kind ? { liftNodeId: parent?.liftNodeId ?? liftNodeId, kind } : null;
  }

  private liftIngressClaimingVehicleId(liftNodeId: string, vehicleId: string): string | null {
    for (const other of [...this.vehicles].sort((left, right) => left.id.localeCompare(right.id))) {
      if (other.id === vehicleId) {
        continue;
      }
      if (this.nodeBelongsToLiftPort(other.currentNodeId, liftNodeId) || (other.targetNodeId && this.nodeBelongsToLiftPort(other.targetNodeId, liftNodeId))) {
        return other.id;
      }
      const task = this.taskById(other.taskId);
      if (!task || task.state === 'completed' || task.state === 'failed' || this.taskLiftPortNodeId(task) !== liftNodeId) {
        continue;
      }
      if (this.vehicleLiftPortWindowContains(other, liftNodeId)) {
        return other.id;
      }
    }
    return null;
  }

  private liftIngressStagingBlock(
    vehicle: MutableVehicle,
    toNodeId: string,
    task: TaskStateRecord | null
  ): { reason: string; blockingVehicleId: string | null } | null {
    const liftPort = this.routeLiftPortAfterTarget(vehicle, toNodeId);
    if (!liftPort) {
      return null;
    }

    const blockingVehicleId = this.liftIngressClaimingVehicleId(liftPort.liftNodeId, vehicle.id);
    if (blockingVehicleId) {
      return { reason: `${liftPort.kind}-lift-busy:${liftPort.liftNodeId}`, blockingVehicleId };
    }

    const approachCount = this.liftPortApproachCount(liftPort.kind, liftPort.liftNodeId);
    const consumesSelf = task ? this.taskStillConsumesLiftApproachSlot(task, liftPort.kind, liftPort.liftNodeId) : false;
    const otherApproachCount = consumesSelf ? Math.max(0, approachCount - 1) : approachCount;
    if (otherApproachCount >= this.effectiveLiftPortApproachCapacity(liftPort.kind)) {
      return { reason: `${liftPort.kind}-lift-approach-full:${liftPort.liftNodeId}`, blockingVehicleId: null };
    }

    return null;
  }

  private portalNodeHoldBlock(vehicle: MutableVehicle, toNodeId: string): Reservation | null {
    const portalZones = this.zonesForNode(toNodeId).filter((zone) => zone.noStop && zone.noParking);
    for (const zone of portalZones) {
      const entrySensitive = this.portalNodeEntryUsesZone(vehicle, toNodeId, zone);
      const reservation = this.reservations.find((candidate) =>
        candidate.reasonCode === 'zone-hold' &&
        candidate.resourceType === 'zone' &&
        candidate.resourceId === zone.id &&
        candidate.vehicleId !== vehicle.id &&
        this.reservationIsActive(candidate) &&
        (entrySensitive || this.portalHoldConflictsWithEntry(candidate, zone, toNodeId))
      );
      if (reservation) {
        return reservation;
      }
    }
    return null;
  }

  private portalNodeEntryUsesZone(vehicle: MutableVehicle, toNodeId: string, zone: LayoutZone): boolean {
    const nextNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 2];
    if (!nextNodeId) {
      return false;
    }
    const nextEdge = this.traffic.findEdge(toNodeId, nextNodeId);
    return nextEdge ? zone.edgeIds.includes(nextEdge.id) : false;
  }

  private portalHoldConflictsWithEntry(reservation: Reservation, zone: LayoutZone, toNodeId: string): boolean {
    const holder = this.vehicles.find((vehicle) => vehicle.id === reservation.vehicleId);
    if (!holder || !holder.targetNodeId) {
      return true;
    }
    if (holder.targetNodeId === toNodeId) {
      return true;
    }
    const holderEdge = this.traffic.findEdge(holder.currentNodeId, holder.targetNodeId);
    return holderEdge ? zone.edgeIds.includes(holderEdge.id) : true;
  }

  private movingVehicleTargetingNode(nodeId: string, vehicleId: string): string | null {
    const claimant = this.vehicles.find((vehicle) =>
      vehicle.id !== vehicleId &&
      vehicle.currentEdgeId !== null &&
      vehicle.targetNodeId === nodeId
    );
    return claimant?.id ?? null;
  }

  private movingVehicleClearingNode(nodeId: string, vehicle: MutableVehicle): string | null {
    if (!this.collisionAvoidanceEnabled()) {
      return null;
    }
    const node = nodePosition(this.scenario, nodeId);
    const entrantPose = { x: node.x, z: node.z, yaw: vehicle.yaw };
    const blocker = this.vehicles.find((candidate) =>
      candidate.id !== vehicle.id &&
      candidate.currentEdgeId !== null &&
      candidate.currentNodeId === nodeId &&
      candidate.targetNodeId !== null &&
      vehicleFootprintsOverlap(entrantPose, candidate, this.scenario.vehicles)
    );
    return blocker?.id ?? null;
  }

  private minimalTargetClaimBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    const target = nodePosition(this.scenario, toNodeId);
    const closeEnoughM = this.closeTargetClaimDistanceM();
    const requesterDistanceToTargetM = Math.hypot(vehicle.x - target.x, vehicle.z - target.z);
    const strictNoParkingTarget =
      this.topLiftColumnLayoutEnabled() &&
      Boolean(this.layoutNode(toNodeId)?.noParking);
    const claimant = this.vehicles.find((candidate) => {
      if (candidate.id === vehicle.id || candidate.currentEdgeId === null || candidate.targetNodeId !== toNodeId) {
        return false;
      }
      if (this.vehicleCurrentlyWaitsFor(candidate, vehicle.id)) {
        return false;
      }
      const claimantDistanceToTargetM = Math.hypot(candidate.x - target.x, candidate.z - target.z);
      return strictNoParkingTarget || claimantDistanceToTargetM <= closeEnoughM;
    });
    if (!claimant) {
      return null;
    }
    if (strictNoParkingTarget) {
      return claimant.id;
    }
    return requesterDistanceToTargetM <= closeEnoughM ? claimant.id : null;
  }

  private closeTargetClaimDistanceM(): number {
    return Math.max(
      this.scenario.vehicles.lengthM + this.scenario.vehicles.safetyRadiusM + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM / 2,
      this.scenario.vehicles.lengthM * 1.5
    );
  }

  private nodeClaimedByOtherVehicle(nodeId: string, vehicleId: string): string | null {
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicleId) {
      return occupantId;
    }
    const claimant = this.vehicles.find((vehicle) =>
      vehicle.id !== vehicleId &&
      vehicle.targetNodeId === nodeId &&
      vehicle.currentNodeId !== nodeId &&
      this.vehicleFutureClaimsEnabled(vehicle)
    );
    if (claimant) {
      return claimant.id;
    }
    return this.localRouteNodeClaimBlocker(nodeId, vehicleId);
  }

  private vehicleFutureClaimsEnabled(vehicle: MutableVehicle): boolean {
    return vehicle.state !== 'idle' && vehicle.state !== 'parking' && vehicle.state !== 'waiting-blocked';
  }

  private localRouteNodeClaimBlocker(nodeId: string, vehicleId: string): string | null {
    const claimant = this.vehicles.find((vehicle) => {
      if (
        vehicle.id === vehicleId ||
        vehicle.state === 'idle' ||
        vehicle.state === 'parking' ||
        vehicle.state === 'waiting-blocked' ||
        vehicle.localRouteNodeIds.length < 2
      ) {
        return false;
      }
      const activeLocalRouteTail = this.activeLocalRouteClaimTail(vehicle);
      if (activeLocalRouteTail.length < 2) {
        return false;
      }
      if (this.vehicleCurrentlyWaitsFor(vehicle, vehicleId)) {
        return false;
      }
      return activeLocalRouteTail.slice(1).includes(nodeId);
    });
    return claimant?.id ?? null;
  }

  private activeLocalRouteClaimTail(vehicle: MutableVehicle): string[] {
    if (!vehicle.localRouteReason || vehicle.localRouteNodeIds.length < 2) {
      return [];
    }
    const currentIndex = vehicle.localRouteNodeIds.indexOf(vehicle.currentNodeId);
    if (currentIndex < 0) {
      return [];
    }
    const localTail = vehicle.localRouteNodeIds.slice(currentIndex);
    const routeTail = this.vehicleRouteTail(vehicle, vehicle.routeNodeIds);
    const localTailMatchesActiveRoute =
      routeTail.length >= localTail.length &&
      localTail.every((nodeId, index) => routeTail[index] === nodeId);
    const activeYieldHold =
      vehicle.yieldHoldUntilSec !== null &&
      this.simTimeSec < vehicle.yieldHoldUntilSec &&
      (vehicle.yieldHoldNodeId === null || localTail.includes(vehicle.yieldHoldNodeId));
    return localTailMatchesActiveRoute || activeYieldHold ? localTail : [];
  }

  private clearInactiveLocalRouteClaims(): void {
    for (const vehicle of this.vehicles) {
      if (!vehicle.localRouteReason || vehicle.localRouteNodeIds.length < 2) {
        continue;
      }
      if (this.activeLocalRouteClaimTail(vehicle).length >= 2) {
        continue;
      }
      vehicle.localRouteNodeIds = [];
      vehicle.localRouteReason = null;
      if (
        vehicle.yieldHoldUntilSec !== null &&
        (this.simTimeSec >= vehicle.yieldHoldUntilSec || !this.activeYieldingConflictSessionForVehicle(vehicle.id))
      ) {
        vehicle.yieldHoldUntilSec = null;
        vehicle.yieldHoldNodeId = null;
      }
    }
  }

  private vehicleCurrentlyWaitsFor(vehicle: MutableVehicle, blockingVehicleId: string): boolean {
    return vehicle.state === 'waiting-blocked' &&
      (vehicle.blockingVehicleId === blockingVehicleId ||
        this.blockingVehicleForReservation(vehicle.blockingReservationId) === blockingVehicleId);
  }

  private closeOccupiedNextNode(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (!this.collisionAvoidanceEnabled()) {
      return null;
    }
    const nextNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 2];
    if (!nextNodeId) {
      return null;
    }
    const occupantId = this.currentNodeOccupancy.get(nextNodeId) ?? this.movingVehicleTargetingNode(nextNodeId, vehicle.id);
    if (!occupantId || occupantId === vehicle.id) {
      return null;
    }
    const to = nodePosition(this.scenario, toNodeId);
    const next = nodePosition(this.scenario, nextNodeId);
    const spacingM = Math.hypot(to.x - next.x, to.z - next.z);
    const requiredM = this.scenario.vehicles.lengthM + this.scenario.vehicles.safetyRadiusM + 0.1;
    return spacingM < requiredM ? occupantId : null;
  }

  private deferTask(kind: 'inbound' | 'outbound', reason: string, dtSec: number): void {
    this.blockedTimeByReasonSec.set(reason, round((this.blockedTimeByReasonSec.get(reason) ?? 0) + dtSec));
    if (this.deferredTaskReasons[kind] === reason) {
      return;
    }

    this.deferredTaskReasons[kind] = reason;
    this.logEvent('task-deferred', null, null, null, null, null, reason, null, { kind });
  }

  private isStorageNode(nodeId: string): boolean {
    return this.storageNodeIdSet.has(nodeId);
  }

  private storageLanes(): ShuttleScenario['layout']['nodes'][] {
    if (this.topLiftColumnLayoutEnabled()) {
      const laneByKey = new Map<string, ShuttleScenario['layout']['nodes']>();
      for (const node of this.scenario.layout.nodes.filter((candidate) => candidate.type === 'storage')) {
        const key = this.nodeStorageRowLabel(node.id);
        if (!key) {
          continue;
        }
        const lane = laneByKey.get(key) ?? [];
        lane.push(node);
        laneByKey.set(key, lane);
      }

      return [...laneByKey.entries()]
        .sort(([leftKey], [rightKey]) => leftKey.localeCompare(rightKey))
        .map(([, lane]) => lane.sort((left, right) => {
          const leftPosition = this.storageGridPosition(left.id);
          const rightPosition = this.storageGridPosition(right.id);
          return (
            (rightPosition?.row ?? 0) - (leftPosition?.row ?? 0) ||
            left.id.localeCompare(right.id)
          );
        }));
    }

    const laneByZ = new Map<number, ShuttleScenario['layout']['nodes']>();
    for (const node of this.scenario.layout.nodes.filter((candidate) => candidate.type === 'storage')) {
      const lane = laneByZ.get(node.z) ?? [];
      lane.push(node);
      laneByZ.set(node.z, lane);
    }

    return [...laneByZ.entries()]
      .sort(([leftZ], [rightZ]) => leftZ - rightZ)
      .map(([, lane]) => lane.sort((left, right) => left.x - right.x || left.id.localeCompare(right.id)));
  }

  private storageNodeLoadOccupancy(includePendingInbound: boolean): Map<string, string> {
    const occupancy = new Map<string, string>();
    for (const nodeId of this.storedLoadIdByNodeId.keys()) {
      const loadId = this.storedLoadIdAtNode(nodeId);
      if (loadId) {
        occupancy.set(nodeId, loadId);
      }
    }

    if (!includePendingInbound) {
      return occupancy;
    }

    for (const task of this.activeTasks()) {
      if (
        task.kind === 'inbound' &&
        this.isStorageNode(task.dropoffNodeId)
      ) {
        occupancy.set(task.dropoffNodeId, task.loadId);
      }
    }

    return occupancy;
  }

  private storageNodeLoadOccupancyForTaskReachability(task: TaskStateRecord): Map<string, string> {
    const occupancy = this.storageNodeLoadOccupancy(false);
    if (task.kind !== 'inbound') {
      return occupancy;
    }
    for (const candidate of this.activeTasks()) {
      if (
        candidate.kind !== 'inbound' ||
        !this.isStorageNode(candidate.dropoffNodeId)
      ) {
        continue;
      }
      const candidatePrecedesTask =
        candidate.createdAtSec < task.createdAtSec ||
        (candidate.createdAtSec === task.createdAtSec && candidate.id.localeCompare(task.id) <= 0);
      if (candidatePrecedesTask) {
        occupancy.set(candidate.dropoffNodeId, candidate.loadId);
      }
    }
    return occupancy;
  }

  private storageNodeLoadOccupancyForInFlightInboundReachability(task: TaskStateRecord): Map<string, string> {
    const occupancy = this.storageNodeLoadOccupancy(false);
    if (task.kind !== 'inbound') {
      return occupancy;
    }
    for (const candidate of this.activeTasks()) {
      if (
        candidate.id === task.id ||
        candidate.kind !== 'inbound' ||
        (candidate.state !== 'assigned' && candidate.state !== 'in-progress') ||
        !this.isStorageNode(candidate.dropoffNodeId)
      ) {
        continue;
      }
      occupancy.set(candidate.dropoffNodeId, candidate.loadId);
    }
    return occupancy;
  }

  private storedLoadIdAtNode(nodeId: string): string | null {
    const loadId = this.storedLoadIdByNodeId.get(nodeId);
    if (!loadId) {
      return null;
    }
    const load = this.loadById(loadId);
    if (load?.state === 'stored' && load.nodeId === nodeId) {
      return loadId;
    }
    this.storedLoadIdByNodeId.delete(nodeId);
    if (load) {
      this.storedNodeIdByLoadId.delete(load.id);
    }
    return null;
  }

  private selectInboundStorageNode(): { nodeId: string; loadId: string } | null {
    if (this.topLiftColumnLayoutEnabled()) {
      return this.selectTopLiftInboundStorageNode();
    }

    if (this.agentRefreshEnabled()) {
      return this.selectRefreshInboundStorageNode();
    }

    const lanes = this.storageLanes();
    if (lanes.length === 0) {
      return null;
    }

    const occupancy = this.storageNodeLoadOccupancy(true);
    const candidates: Array<{ nodeId: string; activeRowTaskCount: number; roundRobinDistance: number }> = [];
    for (let laneIndex = 0; laneIndex < lanes.length; laneIndex += 1) {
      const lane = lanes[laneIndex]!;
      const firstEmptyIndex = lane.findIndex((node) => !occupancy.has(node.id) && !this.currentNodeOccupancy.has(node.id));
      if (firstEmptyIndex < 0) {
        continue;
      }
      // Phase 0 storage policy is an explicit contiguous lane-fill contract:
      // each row fills from the outfeed side toward the infeed side, and the
      // allocator does not compact or skip gaps inside a partially used row.
      const occupiedTowardOutfeed = lane.slice(0, firstEmptyIndex).every((leftSideNode) => occupancy.has(leftSideNode.id));
      const emptyTowardInfeed = lane.slice(firstEmptyIndex + 1).every((rightSideNode) => !occupancy.has(rightSideNode.id));
      if (occupiedTowardOutfeed && emptyTowardInfeed) {
        const nodeId = lane[firstEmptyIndex]!.id;
        const rowLabel = this.nodeStorageRowLabel(nodeId);
        candidates.push({
          nodeId,
          activeRowTaskCount: rowLabel ? this.activeStorageRowTaskCount(rowLabel) : 0,
          roundRobinDistance: (laneIndex - (this.taskSequence % lanes.length) + lanes.length) % lanes.length
        });
      }
    }
    const bestCandidate = candidates.sort((left, right) =>
      left.activeRowTaskCount - right.activeRowTaskCount ||
      left.roundRobinDistance - right.roundRobinDistance ||
      left.nodeId.localeCompare(right.nodeId)
    )[0];
    return bestCandidate ? { nodeId: bestCandidate.nodeId, loadId: '' } : null;
  }

  private selectRefreshInboundStorageNode(): { nodeId: string; loadId: string } | null {
    const lanes = this.storageLanes();
    if (lanes.length === 0) {
      return null;
    }

    const inboundTaskOrdinal = this.tasks.filter((task) => task.kind === 'inbound').length + 1;
    const occupancy = this.storageNodeLoadOccupancy(true);
    for (let offset = 0; offset < lanes.length; offset += 1) {
      const lane = lanes[(inboundTaskOrdinal - 1 + offset) % lanes.length]!;
      const rowLabel = this.nodeStorageRowLabel(lane[0]?.id ?? '');
      if (rowLabel && this.activeInboundStorageRowTaskCount(rowLabel) > 0) {
        continue;
      }

      const firstEmptyIndex = lane.findIndex((node) => !occupancy.has(node.id) && !this.currentNodeOccupancy.has(node.id));
      if (firstEmptyIndex < 0) {
        continue;
      }

      const occupiedTowardOutfeed = lane.slice(0, firstEmptyIndex).every((leftSideNode) => occupancy.has(leftSideNode.id));
      const emptyTowardInfeed = lane.slice(firstEmptyIndex + 1).every((rightSideNode) => !occupancy.has(rightSideNode.id));
      if (!occupiedTowardOutfeed || !emptyTowardInfeed) {
        continue;
      }

      return { nodeId: lane[firstEmptyIndex]!.id, loadId: '' };
    }

    return null;
  }

  private selectTopLiftInboundStorageNode(): { nodeId: string; loadId: string } | null {
    const occupancy = this.storageNodeLoadOccupancy(true);
    const outboundLockedColumns = this.topLiftActiveOutboundTaskColumns();
    const activeColumn = this.activeTopLiftTaskColumn('inbound');
    if (activeColumn !== null) {
      if (outboundLockedColumns.has(activeColumn)) {
        return null;
      }
      if (this.topLiftTasklessStorageVehicleBlocksInboundAllocation(activeColumn)) {
        return null;
      }
      if (this.activeTopLiftTaskCountInColumn('inbound', activeColumn) >= this.topLiftSkuColumnActiveTaskLimit('inbound')) {
        return null;
      }
      const nodeId = this.firstAvailableTopLiftInboundNodeInColumn(activeColumn, occupancy);
      return nodeId ? { nodeId, loadId: '' } : null;
    }

    for (const column of this.topLiftStorageColumnNumbers()) {
      if (outboundLockedColumns.has(column)) {
        continue;
      }
      if (this.topLiftTasklessStorageVehicleBlocksInboundAllocation(column)) {
        continue;
      }
      const nodeId = this.firstAvailableTopLiftInboundNodeInColumn(column, occupancy);
      if (nodeId) {
        return { nodeId, loadId: '' };
      }
    }
    return null;
  }

  private selectTopLiftInboundStorageNodeForLift(liftNodeId: string): string | null {
    const occupancy = this.storageNodeLoadOccupancy(true);
    const outboundLockedColumns = this.topLiftActiveOutboundTaskColumns();
    const activeColumn = this.activeTopLiftTaskColumnForLift('inbound', liftNodeId);
    if (activeColumn !== null) {
      if (outboundLockedColumns.has(activeColumn)) {
        return null;
      }
      if (this.topLiftTasklessStorageVehicleBlocksInboundAllocation(activeColumn)) {
        return null;
      }
      const activeColumnTaskCount = this.activeTopLiftTaskCountInColumnForLift('inbound', activeColumn, liftNodeId);
      if (activeColumnTaskCount < this.topLiftSkuColumnActiveTaskLimit('inbound')) {
        const activeColumnNodeId = this.firstAvailableTopLiftInboundNodeInColumn(activeColumn, occupancy);
        if (activeColumnNodeId) {
          return activeColumnNodeId;
        }
      }
      return this.selectTopLiftInboundHandoffStorageNodeForLift(liftNodeId, activeColumn, occupancy, outboundLockedColumns);
    }

    for (const column of this.topLiftStorageColumnNumbersForLift(liftNodeId)) {
      if (outboundLockedColumns.has(column)) {
        continue;
      }
      if (this.topLiftTasklessStorageVehicleBlocksInboundAllocation(column)) {
        continue;
      }
      const nodeId = this.firstAvailableTopLiftInboundNodeInColumn(column, occupancy);
      if (nodeId) {
        return nodeId;
      }
    }
    return null;
  }

  private selectTopLiftInboundHandoffStorageNodeForLift(
    liftNodeId: string,
    activeColumn: number,
    occupancy: Map<string, string>,
    outboundLockedColumns: Set<number>
  ): string | null {
    if (!this.topLiftInboundColumnHandoffReady(liftNodeId, activeColumn)) {
      return null;
    }
    if (this.topLiftInboundHasDifferentColumnHandoffTask(liftNodeId, activeColumn)) {
      return null;
    }
    if (this.topLiftInboundOpenApproachQueueSlotCount(liftNodeId) === 0) {
      return null;
    }

    const liftColumns = this.topLiftStorageColumnNumbersForLift(liftNodeId);
    const activeIndex = liftColumns.indexOf(activeColumn);
    const candidateColumns = activeIndex >= 0
      ? liftColumns.slice(activeIndex + 1)
      : liftColumns;
    for (const column of candidateColumns) {
      if (outboundLockedColumns.has(column)) {
        continue;
      }
      if (this.topLiftTasklessStorageVehicleBlocksInboundAllocation(column)) {
        continue;
      }
      const nodeId = this.firstAvailableTopLiftInboundNodeInColumn(column, occupancy);
      if (nodeId) {
        return nodeId;
      }
    }
    return null;
  }

  private topLiftInboundColumnHandoffReady(liftNodeId: string, activeColumn: number): boolean {
    const activeTasks = this.activeTasks().filter((task) =>
      task.kind === 'inbound' &&
      this.taskLiftPortNodeId(task) === liftNodeId &&
      this.taskStorageColumn(task) === activeColumn
    );
    if (activeTasks.length === 0) {
      return false;
    }
    if (activeTasks.some((task) => task.state === 'queued')) {
      return false;
    }
    return activeTasks.some((task) => this.inboundTaskPickupReleased(task));
  }

  private topLiftInboundHasDifferentColumnHandoffTask(liftNodeId: string, activeColumn: number): boolean {
    return this.activeTasks().some((task) =>
      task.kind === 'inbound' &&
      this.taskLiftPortNodeId(task) === liftNodeId &&
      this.taskStorageColumn(task) !== null &&
      this.taskStorageColumn(task) !== activeColumn
    );
  }

  private topLiftInboundOpenApproachQueueSlotCount(liftNodeId: string): number {
    return this.topLiftInboundApproachQueueNodeIds(liftNodeId).filter((nodeId) =>
      !this.topLiftInboundQueueNodeHardClaimedByOtherVehicle(nodeId, '')
    ).length;
  }

  private firstAvailableTopLiftInboundNodeInColumn(column: number, occupancy: Map<string, string>): string | null {
    for (const nodeId of this.topLiftStorageColumnNodeIds(column)) {
      if (
        !occupancy.has(nodeId) &&
        !this.currentNodeOccupancy.has(nodeId) &&
        this.topLiftInboundStorageNodeReachableInColumn(nodeId, occupancy)
      ) {
        return nodeId;
      }
    }
    return null;
  }

  private topLiftInboundStorageNodeReachableInColumn(nodeId: string, occupancy: Map<string, string>): boolean {
    const position = this.storageGridPosition(nodeId);
    if (!position || !this.topLiftColumnLayoutEnabled()) {
      return true;
    }

    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const zoneFirstRow = position.row <= rowsPerZone ? 1 : rowsPerZone + 1;
    const zoneLastRow = position.row <= rowsPerZone ? rowsPerZone : rowsPerZone * 2;
    const columnIndex = position.column - 1;
    const rowClear = (row: number): boolean => {
      const transitNodeId = storageNodeId(row - 1, columnIndex);
      return !occupancy.has(transitNodeId) && !this.currentNodeOccupancy.has(transitNodeId);
    };
    const rangeClear = (firstRow: number, lastRow: number): boolean => {
      for (let row = firstRow; row <= lastRow; row += 1) {
        if (!rowClear(row)) {
          return false;
        }
      }
      return true;
    };

    return rangeClear(zoneFirstRow, position.row - 1) || rangeClear(position.row + 1, zoneLastRow);
  }

  private activeStorageRowTaskCount(rowLabel: string): number {
    return this.activeTasks().filter((task) =>
      this.taskStorageRowLabel(task) === rowLabel
    ).length;
  }

  private activeInboundStorageRowTaskCount(rowLabel: string): number {
    return this.activeTasks().filter((task) =>
      task.kind === 'inbound' &&
      this.taskStorageRowLabel(task) === rowLabel
    ).length;
  }

  private selectOutboundLoad(): { nodeId: string; loadId: string } | null {
    if (this.topLiftColumnLayoutEnabled()) {
      return this.selectTopLiftOutboundLoad();
    }

    const lanes = this.storageLanes();
    const assignedOutboundLoadIds = new Set(
      this.tasks
        .filter((task) => task.kind === 'outbound' && task.state !== 'completed' && task.state !== 'failed')
        .map((task) => task.loadId)
    );

    for (let offset = 0; offset < lanes.length; offset += 1) {
      const lane = lanes[(this.taskSequence + offset) % lanes.length]!;
      for (const node of lane) {
        const loadId = this.storedLoadIdAtNode(node.id);
        if (loadId && !assignedOutboundLoadIds.has(loadId)) {
          return { nodeId: node.id, loadId };
        }
      }
    }
    return null;
  }

  private selectTopLiftOutboundTaskSelection(): { nodeId: string; liftNodeId: string; loadId: string } | { reason: string } {
    if (this.topLiftMixedFlowOutboundReservedForInbound()) {
      return { reason: 'outbound-reserved-for-inbound' };
    }
    const outboundLockedColumns = this.topLiftOutboundLockedColumns();
    if (this.mixedTopLiftFlowEnabled() && outboundLockedColumns.size === 0) {
      return { reason: 'storage-empty' };
    }

    const assignedOutboundLoadIds = this.assignedOutboundLoadIds();
    const outboundLifts = this.outboundLiftNodes()
      .filter((node) => this.liftPortPlannedLoad('outbound', node.id) < this.topLiftPortStagedTaskCapacity('outbound', node.id))
      .sort((left, right) =>
        this.liftPortPlannedLoad('outbound', left.id) - this.liftPortPlannedLoad('outbound', right.id) ||
        left.x - right.x ||
        left.id.localeCompare(right.id)
      );

    for (const liftNode of outboundLifts) {
      for (const column of this.topLiftStorageColumnNumbersForLift(liftNode.id)) {
        if (this.mixedTopLiftFlowEnabled() && !outboundLockedColumns.has(column)) {
          continue;
        }
        if (!this.topLiftOutboundColumnCanAcceptTask(column)) {
          continue;
        }
        const selection = this.firstAvailableTopLiftOutboundLoadInColumn(column, assignedOutboundLoadIds);
        if (selection) {
          return { ...selection, liftNodeId: liftNode.id };
        }
      }
    }

    return { reason: 'storage-empty' };
  }

  private topLiftMixedFlowOutboundReservedForInbound(): boolean {
    if (!this.mixedTopLiftFlowEnabled() || !this.topLiftInboundPressureActive()) {
      return false;
    }
    const outboundActiveTaskCount = this.activeTasks().filter((task) => task.kind === 'outbound').length;
    return outboundActiveTaskCount >= this.topLiftMixedFlowOutboundActiveTaskLimit();
  }

  private topLiftMixedFlowOutboundActiveTaskLimit(): number {
    return Math.max(1, this.vehicles.length - Math.max(1, this.inboundLiftNodes().length));
  }

  private topLiftInboundPressureActive(): boolean {
    if (!this.mixedTopLiftFlowEnabled()) {
      return false;
    }
    return this.inboundLiftNodes().some((lift) => this.inboundLiftWaitingSourceLoads(lift.id).length > 0) ||
      this.activeTasks().some((task) => task.kind === 'inbound');
  }

  private selectTopLiftOutboundLoad(): { nodeId: string; loadId: string } | null {
    const assignedOutboundLoadIds = this.assignedOutboundLoadIds();
    const outboundLockedColumns = this.topLiftOutboundLockedColumns();
    const activeColumn = this.activeTopLiftTaskColumn('outbound');
    if (activeColumn !== null && !this.mixedTopLiftFlowEnabled()) {
      if (this.topLiftOutboundColumnCanAcceptTask(activeColumn)) {
        return this.firstAvailableTopLiftOutboundLoadInColumn(activeColumn, assignedOutboundLoadIds);
      }
      return null;
    }

    if (this.mixedTopLiftFlowEnabled() && outboundLockedColumns.size === 0) {
      return null;
    }

    for (const column of this.topLiftStorageColumnNumbers()) {
      if (this.mixedTopLiftFlowEnabled() && !outboundLockedColumns.has(column)) {
        continue;
      }
      if (!this.topLiftOutboundColumnCanAcceptTask(column)) {
        continue;
      }
      const selection = this.firstAvailableTopLiftOutboundLoadInColumn(column, assignedOutboundLoadIds);
      if (selection) {
        return selection;
      }
    }
    return null;
  }

  private topLiftOutboundColumnCanAcceptTask(column: number): boolean {
    return !this.topLiftColumnHasActiveOppositeWork('outbound', column) &&
      this.activeTopLiftTaskCountInColumn('outbound', column) < this.topLiftSkuColumnActiveTaskLimit('outbound');
  }

  private firstAvailableTopLiftOutboundLoadInColumn(column: number, assignedOutboundLoadIds: Set<string>): { nodeId: string; loadId: string } | null {
    for (const nodeId of this.topLiftStorageColumnNodeIds(column)) {
      const loadId = this.storedLoadIdAtNode(nodeId);
      const load = this.loadById(loadId);
      if (!load) {
        continue;
      }
      if (assignedOutboundLoadIds.has(load.id) || !this.outboundEligibleLoad(load)) {
        return null;
      }
      if (this.topLiftOutboundLoadHasStoredBlocker(load, assignedOutboundLoadIds)) {
        return null;
      }
      if (load) {
        return { nodeId, loadId: load.id };
      }
    }
    return null;
  }

  private topLiftOutboundLoadHasStoredBlocker(load: LoadStateRecord, assignedOutboundLoadIds: Set<string>): boolean {
    if (!load.nodeId || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    if (!this.storageGridPosition(load.nodeId)) {
      return false;
    }
    const exitRoute = this.topLiftLoadedOutboundStorageExitRoute(load.nodeId);
    if (!exitRoute) {
      return true;
    }
    for (const blockerNodeId of exitRoute.slice(1)) {
      const blockerLoadId = this.storedLoadIdAtNode(blockerNodeId);
      if (blockerLoadId && blockerLoadId !== load.id) {
        return true;
      }
      if (blockerLoadId && assignedOutboundLoadIds.has(blockerLoadId)) {
        return true;
      }
    }
    return false;
  }

  private topLiftOutboundLockedColumns(): Set<number> {
    const columns = new Set<number>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return columns;
    }
    if (this.scenario.taskGeneration.outboundRatePerHour <= 0) {
      return columns;
    }

    for (const task of this.activeTasks()) {
      if (task.kind !== 'outbound') {
        continue;
      }
      const column = this.taskStorageColumn(task);
      if (column !== null) {
        columns.add(column);
      }
    }

    for (const [nodeId, loadId] of this.storedLoadIdByNodeId) {
      const load = this.loadById(loadId);
      if (!load || load.state !== 'stored' || load.nodeId !== nodeId || !this.outboundEligibleLoad(load)) {
        continue;
      }
      const column = this.storageGridPosition(nodeId)?.column ?? null;
      if (column !== null) {
        columns.add(column);
      }
    }

    return columns;
  }

  private topLiftActiveOutboundTaskColumns(): Set<number> {
    const columns = new Set<number>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return columns;
    }
    for (const task of this.activeTasks()) {
      if (task.kind !== 'outbound') {
        continue;
      }
      const column = this.taskStorageColumn(task);
      if (column !== null) {
        columns.add(column);
      }
    }
    return columns;
  }

  private outboundEligibleLoad(load: LoadStateRecord): boolean {
    if (!this.mixedTopLiftFlowEnabled()) {
      return true;
    }
    if (load.id.startsWith(OUTBOUND_SEED_LOAD_PREFIX)) {
      return true;
    }
    if (!load.nodeId) {
      return false;
    }
    const column = this.storageGridPosition(load.nodeId)?.column ?? null;
    if (column === null || this.topLiftColumnHasActiveInboundWork(column)) {
      return false;
    }
    return this.topLiftColumnFlowModes.get(column) === 'outbound' || !this.topLiftColumnHasActiveInboundWork(column);
  }

  private topLiftColumnHasActiveInboundWork(column: number): boolean {
    return this.activeTopLiftTaskCountInColumn('inbound', column) > 0;
  }

  private topLiftColumnHasActiveOppositeWork(
    kind: 'inbound' | 'outbound',
    column: number,
    excludeTaskId: string | null = null
  ): boolean {
    const oppositeKind = kind === 'inbound' ? 'outbound' : 'inbound';
    return this.activeTasks().some((task) =>
      task.id !== excludeTaskId &&
      task.kind === oppositeKind &&
      this.taskStorageColumn(task) === column
    );
  }

  private topLiftColumnModeConflictReason(task: TaskStateRecord): string | null {
    if (!this.topLiftColumnLayoutEnabled() || !this.mixedTopLiftFlowEnabled()) {
      return null;
    }
    const column = this.taskStorageColumn(task);
    if (column === null || !this.topLiftColumnHasActiveOppositeWork(task.kind, column, task.id)) {
      return null;
    }
    return `column-mode-conflict:c${String(column).padStart(2, '0')}`;
  }

  private mixedTopLiftFlowEnabled(): boolean {
    return this.topLiftColumnLayoutEnabled() &&
      this.scenario.taskGeneration.inboundRatePerHour > 0 &&
      this.scenario.taskGeneration.outboundRatePerHour > 0;
  }

  private mixedTopLiftStorageResourceReuseEnabled(): boolean {
    return this.mixedTopLiftFlowEnabled() &&
      this.scenario.taskGeneration.initialStorageFillPolicy === 'zone-balanced-50';
  }

  private assignedOutboundLoadIds(): Set<string> {
    return new Set(
      this.activeTasks()
        .filter((task) => task.kind === 'outbound')
        .map((task) => task.loadId)
    );
  }

  private assignQueuedTasks(dtSec: number): void {
    this.dispatchTasklessTopLiftStorageExits();
    this.holdTasklessInboundQueueStandbys();
    this.dispatchTasklessInboundQueueStandbys(false);
    const availableVehicleIds = new Set(
      this.vehicles
        .filter((vehicle) => this.canAcceptQueuedTask(vehicle))
        .map((vehicle) => vehicle.id)
    );

    for (const { task } of this.queuedTasksForAssignment()) {
      this.tryRetargetQueuedInboundStorageFullTask(task);
      const assignmentPriority = this.queuedTaskAssignmentPriority(task);
      if (assignmentPriority > 0) {
        const priorityOverrideAssignment = this.topLiftInboundPriorityWaitAssignment(task, availableVehicleIds);
        if (priorityOverrideAssignment) {
          this.assignTaskToVehicle(priorityOverrideAssignment.vehicle, task, priorityOverrideAssignment.route);
          availableVehicleIds.delete(priorityOverrideAssignment.vehicle.id);
          continue;
        }
        this.recordQueuedTaskWait(task, assignmentPriority === 1 ? 'inbound-column-predecessor-wait' : 'inbound-lift-fifo-wait', dtSec);
        continue;
      }
      if (availableVehicleIds.size === 0) {
        this.recordQueuedTaskWait(task, 'vehicle-unavailable', dtSec);
        continue;
      }
      let reason = this.taskAssignmentBlockReason(task);
      if (reason === 'storage-full' && this.tryRetargetQueuedInboundStorageFullTask(task)) {
        reason = this.taskAssignmentBlockReason(task);
      }
      if (reason) {
        this.recordQueuedTaskWait(task, reason, dtSec);
        continue;
      }

      const assignment = this.bestAvailableVehicleForTaskAvoidingUnsafeDropoffReentry(task, availableVehicleIds);
      if (!assignment) {
        this.recordQueuedTaskWait(task, this.inboundTaskHasEarlierPickupTask(task) ? 'inbound-lift-fifo-wait' : 'route-unavailable', dtSec);
        continue;
      }
      if (task.kind === 'outbound' && this.admitVehicleToStationReserveBeforeOutboundAssignment(assignment.vehicle)) {
        availableVehicleIds.delete(assignment.vehicle.id);
        this.recordQueuedTaskWait(task, 'outbound-reserved-for-inbound', dtSec);
        continue;
      }
      if (this.stageVehicleToInboundQueueBeforeAssignment(assignment.vehicle, task, assignment.route)) {
        availableVehicleIds.delete(assignment.vehicle.id);
        this.recordQueuedTaskWait(task, 'inbound-queue-replenish-wait', dtSec);
        continue;
      }
      if (
        this.topLiftInboundAssignmentMustStageThroughQueue(assignment.vehicle, task) &&
        !this.topLiftInboundAssignmentRouteStagesThroughQueue(assignment.vehicle, task, assignment.route)
      ) {
        this.recordQueuedTaskWait(task, 'inbound-queue-replenish-wait', dtSec);
        continue;
      }

      this.assignTaskToVehicle(assignment.vehicle, task, assignment.route);
      availableVehicleIds.delete(assignment.vehicle.id);
    }
    this.dispatchTasklessInboundQueueStandbys();
  }

  private admitVehicleToStationReserveBeforeOutboundAssignment(vehicle: MutableVehicle): boolean {
    const route = this.stationOwnedReserveAdmissionRouteBeforeOutboundAssignment(vehicle);
    if (!route) {
      return false;
    }
    this.installTasklessPostDropoffRoute(
      vehicle,
      route,
      'inbound-queue-reserve-before-outbound-assignment',
      'inbound-queue-standby'
    );
    return true;
  }

  private stationOwnedReserveAdmissionRouteBeforeOutboundAssignment(vehicle: MutableVehicle): string[] | null {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      this.assignmentHoldActive(vehicle) ||
      this.inboundDropoffStandbyHoldActive(vehicle) ||
      !this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)
    ) {
      return null;
    }
    const candidates = this.inboundLiftNodes()
      .filter((lift) =>
        this.topLiftInboundStationReserveAdmissionCoverageDepth(lift.id) <
        this.topLiftInboundQueueReserveRequiredDepth(lift.id)
      )
      .map((lift) => {
        const route = this.routeToInboundQueueStandby(vehicle, vehicle.currentNodeId, { liftNodeId: lift.id });
        return route && this.stationOwnedReserveAdmissionRouteAllowed(route)
          ? { liftNodeId: lift.id, route }
          : null;
      })
      .filter((candidate): candidate is { liftNodeId: string; route: string[] } => candidate !== null)
      .sort((left, right) =>
        left.route.length - right.route.length ||
        left.liftNodeId.localeCompare(right.liftNodeId)
      );
    const candidate = candidates[0] ?? null;
    if (!candidate) {
      return null;
    }
    const nextNodeId = candidate.route[1] ?? null;
    const nextBlock = nextNodeId && this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, candidate.route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
          : this.agentMoveBlocker(vehicle, nextNodeId)
      : null;
    return nextBlock ? null : candidate.route;
  }

  private stationOwnedReserveAdmissionRouteAllowed(routeNodeIds: string[]): boolean {
    if (
      routeNodeIds.length < 2 ||
      routeNodeIds.length > TOP_LIFT_STATION_RESERVE_ADMISSION_MAX_NODE_COUNT ||
      !this.topLiftInboundReserveQueueSlot(routeNodeIds.at(-1) ?? '')
    ) {
      return false;
    }
    const rankByLevel: Record<TopLiftAisleLevel, number> = {
      'bottom-b': 0,
      'bottom-a': 1,
      middle: 2,
      'top-b': 3,
      'top-a': 4
    };
    let previousRank = -1;
    for (const nodeId of routeNodeIds) {
      if (this.isStorageNode(nodeId) || nodeId.includes('inbound') || nodeId.includes('outbound')) {
        return false;
      }
      const level = topLiftAisleLevel(nodeId);
      if (!level) {
        return false;
      }
      const rank = rankByLevel[level];
      if (rank < previousRank) {
        return false;
      }
      previousRank = rank;
    }
    return true;
  }

  private bestAvailableVehicleForTaskAvoidingUnsafeDropoffReentry(
    task: TaskStateRecord,
    availableVehicleIds: Set<string>
  ): { vehicle: MutableVehicle; route: string[]; pickupDistanceM: number; totalDistanceM: number } | null {
    const remainingVehicleIds = new Set(availableVehicleIds);
    while (remainingVehicleIds.size > 0) {
      const assignment = this.bestAvailableVehicleForTask(task, remainingVehicleIds);
      if (!assignment) {
        return null;
      }
      if (!this.topLiftOutboundDropoffAssignmentConflictsWithLoadedApproach(assignment.vehicle, task, assignment.route)) {
        return assignment;
      }
      this.logEvent(
        'task-assignment-deferred',
        assignment.vehicle.id,
        task.id,
        task.loadId,
        assignment.vehicle.currentNodeId,
        assignment.route[1] ?? null,
        'loaded-outbound-approach-conflict',
        this.vehiclePosition(assignment.vehicle),
        { route: assignment.route.join('>') }
      );
      remainingVehicleIds.delete(assignment.vehicle.id);
    }
    return null;
  }

  private tryRetargetQueuedInboundStorageFullTask(task: TaskStateRecord): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      task.kind !== 'inbound' ||
      task.state !== 'queued' ||
      task.vehicleId !== null ||
      !this.isStorageNode(task.dropoffNodeId)
    ) {
      return false;
    }

    const occupancy = this.storageNodeLoadOccupancyForQueuedInboundRetarget(task);
    const currentDropoffLoadId = this.storedLoadIdAtNode(task.dropoffNodeId);
    const currentDropoffStillUsable =
      (!currentDropoffLoadId || currentDropoffLoadId === task.loadId) &&
      this.topLiftInboundStorageNodeReachableInColumn(task.dropoffNodeId, occupancy);
    if (currentDropoffStillUsable) {
      if (task.waitReason === 'storage-full') {
        task.waitReason = null;
      }
      return false;
    }

    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }

    const outboundLockedColumns = this.topLiftActiveOutboundTaskColumns();
    for (const column of this.topLiftStorageColumnNumbersForLift(liftNodeId)) {
      if (outboundLockedColumns.has(column) || this.topLiftTasklessStorageVehicleBlocksInboundAllocation(column)) {
        continue;
      }
      if (this.activeTopLiftTaskCountInColumnForLift('inbound', column, liftNodeId) >= this.topLiftSkuColumnActiveTaskLimit('inbound')) {
        continue;
      }
      const nodeId = this.firstAvailableTopLiftInboundNodeInColumn(column, occupancy);
      if (!nodeId || nodeId === task.dropoffNodeId) {
        continue;
      }
      const previousDropoffNodeId = task.dropoffNodeId;
      task.dropoffNodeId = nodeId;
      task.waitReason = null;
      this.logEvent('task-retargeted', null, task.id, task.loadId, previousDropoffNodeId, nodeId, 'queued-inbound-retarget-reachable-dropoff', null, {
        kind: task.kind
      });
      return true;
    }

    return false;
  }

  private storageNodeLoadOccupancyForQueuedInboundRetarget(task: TaskStateRecord): Map<string, string> {
    const occupancy = this.storageNodeLoadOccupancy(false);
    for (const candidate of this.activeTasks()) {
      if (
        candidate.id === task.id ||
        candidate.kind !== 'inbound' ||
        !this.isStorageNode(candidate.dropoffNodeId)
      ) {
        continue;
      }
      const dropoffLoadId = this.storedLoadIdAtNode(candidate.dropoffNodeId);
      if (!dropoffLoadId || dropoffLoadId === candidate.loadId) {
        occupancy.set(candidate.dropoffNodeId, candidate.loadId);
      }
    }
    return occupancy;
  }

  private topLiftInboundPriorityWaitAssignment(
    task: TaskStateRecord,
    availableVehicleIds: Set<string>
  ): { vehicle: MutableVehicle; route: string[]; pickupDistanceM: number; totalDistanceM: number } | null {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      availableVehicleIds.size === 0
    ) {
      return null;
    }
    return this.bestAvailableVehicleForTask(task, availableVehicleIds);
  }

  private queuedTasksForAssignment(): Array<{ task: TaskStateRecord; priority: number }> {
    return this.queuedTasks()
      .map((task) => ({ task, priority: this.queuedTaskAssignmentPriority(task) }))
      .sort((left, right) =>
        left.priority - right.priority ||
        left.task.createdAtSec - right.task.createdAtSec ||
        left.task.id.localeCompare(right.task.id)
      );
  }

  private queuedTaskAssignmentPriority(task: TaskStateRecord): number {
    if (this.topLiftInboundQueueReplenishAssignmentBoost(task)) {
      return -2;
    }
    if (
      task.kind === 'inbound' &&
      this.topLiftColumnLayoutEnabled() &&
      this.inboundTaskHasEarlierPickupTask(task) &&
      !this.topLiftInboundQueueSlotAvailableForTask(task)
    ) {
      return 2;
    }
    if (
      task.kind === 'inbound' &&
      this.topLiftColumnLayoutEnabled() &&
      this.topLiftInboundColumnPredecessorPending(task) &&
      !this.topLiftInboundColumnPredecessorStagingAllowed(task)
    ) {
      return 1;
    }
    return 0;
  }

  private topLiftInboundQueueReplenishAssignmentBoost(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    if (this.topLiftInboundActiveEmptyQueueDepth(liftNodeId) >= this.topLiftInboundQueueReplenishTargetDepth(liftNodeId)) {
      return false;
    }
    return this.topLiftInboundQueueSlotAvailableForTask(task);
  }

  private topLiftInboundQueueReplenishTargetDepth(liftNodeId: string): number {
    const queueDepth = this.topLiftInboundApproachQueueNodeIds(liftNodeId).length;
    return Math.min(2, queueDepth);
  }

  private topLiftInboundActiveEmptyQueueDepth(liftNodeId: string): number {
    const vehicleIds = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (vehicle.loaded) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      if (
        task?.kind !== 'inbound' ||
        this.taskLiftPortNodeId(task) !== liftNodeId ||
        (task.state !== 'assigned' && task.state !== 'in-progress')
      ) {
        continue;
      }
      if (this.topLiftInboundVehicleContributesQueueCoverage(vehicle, liftNodeId)) {
        vehicleIds.add(vehicle.id);
      }
    }
    return vehicleIds.size;
  }

  private topLiftInboundVehicleContributesQueueCoverage(vehicle: MutableVehicle, liftNodeId: string): boolean {
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    if (currentSlot?.liftNodeId === liftNodeId) {
      return true;
    }
    const targetSlot = this.topLiftInboundApproachQueueSlot(vehicle.targetNodeId ?? '');
    if (targetSlot?.liftNodeId === liftNodeId) {
      return true;
    }
    const plannedSlot = this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId ?? '');
    if (plannedSlot?.liftNodeId !== liftNodeId) {
      return false;
    }
    const currentLevel = topLiftAisleLevel(vehicle.currentNodeId);
    const targetLevel = topLiftAisleLevel(vehicle.targetNodeId ?? '');
    return currentLevel === 'top-a' ||
      currentLevel === 'top-b' ||
      targetLevel === 'top-a' ||
      targetLevel === 'top-b';
  }

  private recordQueuedTaskWait(task: TaskStateRecord, reason: string, dtSec: number): void {
    task.waitReason = reason;
    this.blockedTimeByReasonSec.set(reason, round((this.blockedTimeByReasonSec.get(reason) ?? 0) + dtSec));
  }

  private canAcceptQueuedTask(vehicle: MutableVehicle): boolean {
    if (vehicle.taskId || vehicle.loaded || vehicle.currentEdgeId || vehicle.legRemainingM > 0 || vehicle.phaseRemainingSec > 0) {
      return false;
    }
    if (this.assignmentHoldActive(vehicle)) {
      return false;
    }
    if (this.inboundDropoffStandbyHoldActive(vehicle)) {
      return false;
    }
    if (this.tasklessPlannedRouteActive(vehicle) && !this.tasklessRoutePreemptibleForQueuedWork(vehicle)) {
      return false;
    }
    return vehicle.state === 'idle' ||
      vehicle.state === 'assigned' ||
      vehicle.state === 'waiting-blocked' ||
      vehicle.state === 'parking' ||
      vehicle.state === 'returning';
  }

  private tasklessPlannedRouteActive(vehicle: MutableVehicle): boolean {
    return this.topLiftColumnLayoutEnabled() &&
      !vehicle.taskId &&
      vehicle.plannedGoalNodeId !== null &&
      vehicle.plannedGoalNodeId !== vehicle.currentNodeId;
  }

  private tasklessRoutePreemptibleForQueuedWork(vehicle: MutableVehicle): boolean {
    return this.topLiftColumnLayoutEnabled() &&
      !vehicle.taskId &&
      !vehicle.loaded &&
      vehicle.currentEdgeId === null &&
      vehicle.legRemainingM <= 0 &&
      vehicle.phaseRemainingSec <= 0 &&
      !this.assignmentHoldActive(vehicle) &&
      this.queuedTasks().length > 0;
  }

  private assignmentHoldActive(vehicle: MutableVehicle): boolean {
    return vehicle.assignmentHoldUntilSec !== null && this.simTimeSec < vehicle.assignmentHoldUntilSec;
  }

  private inboundDropoffStandbyHoldActive(vehicle: MutableVehicle): boolean {
    return vehicle.inboundDropoffStandbyHoldUntilSec !== null &&
      this.simTimeSec < vehicle.inboundDropoffStandbyHoldUntilSec;
  }

  private bestAvailableVehicleForTask(task: TaskStateRecord, availableVehicleIds: Set<string>): { vehicle: MutableVehicle; route: string[]; pickupDistanceM: number; totalDistanceM: number } | null {
    const queueResources = this.topLiftInboundQueueResourcesForTask(task, availableVehicleIds);
    const candidateVehicleIds = queueResources && queueResources.available.length > 0
      ? new Set(queueResources.available.map((resource) => resource.vehicle.id))
      : availableVehicleIds;
    const queueResourceRank = queueResources && queueResources.available.length > 0
      ? new Map(queueResources.available.map((resource, index) => [resource.vehicle.id, index]))
      : null;
    let bestAssignment: { vehicle: MutableVehicle; route: string[]; pickupDistanceM: number; totalDistanceM: number; queueRank: number } | null = null;
    for (const vehicle of this.vehicles.filter((candidate) => candidateVehicleIds.has(candidate.id))) {
      if (this.tasklessInboundQueueReserveProtectedFromTask(vehicle, task)) {
        continue;
      }
      if (this.topLiftInboundCrossLiftAssignmentBlocked(vehicle, task)) {
        continue;
      }
      if (
        task.kind === 'inbound' &&
        this.topLiftColumnLayoutEnabled() &&
        this.inboundTaskShouldWaitBeforePickup(task) &&
        !this.topLiftInboundQueueNodeIdForTask(task, vehicle) &&
        !this.topLiftInboundVehicleAlreadyInCompatibleApproachQueue(vehicle, task)
      ) {
        continue;
      }
      try {
        const route = this.taskAssignmentRoute(vehicle, task);
        if (!this.topLiftOutboundPickupApproachRouteClear(vehicle, task, route)) {
          continue;
        }
        if (!this.topLiftOutboundLoadedEgressReachableAfterPickup(vehicle, task)) {
          continue;
        }
        const reverseClearancePenaltyM = this.outboundLiftClearanceReverseAssignmentPenaltyM(vehicle, route);
        const lowerLevelInboundPenaltyM = this.topLiftInboundLowerLevelAssignmentPenaltyM(vehicle, task, route);
        if (lowerLevelInboundPenaltyM > 0 && this.topLiftInboundLowerLevelAssignmentBlocked(task)) {
          continue;
        }
        const assignmentPenaltyM = reverseClearancePenaltyM + lowerLevelInboundPenaltyM;
        const pickupDistanceM = this.routePlannerCostM(route, this.taskDispatchGoalNodeId(task, vehicle), vehicle.lastMovementAxis) + assignmentPenaltyM;
        const totalDistanceM = this.routePlannerCostM(route, undefined, vehicle.lastMovementAxis) + assignmentPenaltyM;
        const queueRank = queueResourceRank?.get(vehicle.id) ?? Number.POSITIVE_INFINITY;
        if (
          !bestAssignment ||
          queueRank < bestAssignment.queueRank ||
          (queueRank === bestAssignment.queueRank && pickupDistanceM < bestAssignment.pickupDistanceM) ||
          (queueRank === bestAssignment.queueRank && pickupDistanceM === bestAssignment.pickupDistanceM && totalDistanceM < bestAssignment.totalDistanceM) ||
          (queueRank === bestAssignment.queueRank && pickupDistanceM === bestAssignment.pickupDistanceM && totalDistanceM === bestAssignment.totalDistanceM && vehicle.id.localeCompare(bestAssignment.vehicle.id) < 0)
        ) {
          bestAssignment = { vehicle, route, pickupDistanceM, totalDistanceM, queueRank };
        }
      } catch {
        continue;
      }
    }
    return bestAssignment
      ? {
          vehicle: bestAssignment.vehicle,
          route: bestAssignment.route,
          pickupDistanceM: bestAssignment.pickupDistanceM,
          totalDistanceM: bestAssignment.totalDistanceM
        }
      : null;
  }

  private topLiftOutboundLoadedEgressReachableAfterPickup(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      !this.agentRefreshEnabled() ||
      vehicle.loaded
    ) {
      return true;
    }

    const egressTask: TaskStateRecord = { ...task, vehicleId: vehicle.id };
    try {
      const route = this.agentRefreshLoadedOutboundRouteToDropoff(task.pickupNodeId, egressTask, task.dropoffNodeId);
      return Boolean(route && route.length > 1 && route.at(-1) === task.dropoffNodeId);
    } catch {
      return false;
    }
  }

  private topLiftOutboundPickupApproachRouteClear(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    route: string[]
  ): boolean {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded
    ) {
      return true;
    }

    const pickupIndex = route.indexOf(task.pickupNodeId);
    const routeToPickup = route.slice(1, pickupIndex >= 0 ? pickupIndex + 1 : undefined);
    return routeToPickup.every((nodeId) => {
      if (!this.isStorageNode(nodeId)) {
        return true;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      return !occupantId || occupantId === vehicle.id;
    });
  }

  private topLiftInboundVehicleAlreadyInCompatibleApproachQueue(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    return Boolean(liftNodeId && currentSlot?.liftNodeId === liftNodeId);
  }

  private topLiftInboundQueueResourcesForTask(
    task: TaskStateRecord,
    availableVehicleIds: Set<string>
  ): { available: Array<{ vehicle: MutableVehicle; slotIndex: number }> } | null {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return null;
    }
    const resources = this.vehicles
      .map((vehicle) => {
        const slot = this.topLiftInboundQueueResourceSlot(vehicle, liftNodeId);
        return slot ? { vehicle, slotIndex: slot.slotIndex } : null;
      })
      .filter((resource): resource is { vehicle: MutableVehicle; slotIndex: number } => resource !== null)
      .sort((left, right) =>
        left.slotIndex - right.slotIndex ||
        left.vehicle.id.localeCompare(right.vehicle.id)
      );
    if (resources.length === 0) {
      return null;
    }
    return { available: resources.filter((resource) => availableVehicleIds.has(resource.vehicle.id)) };
  }

  private topLiftInboundQueueResourceSlot(vehicle: MutableVehicle | VehicleState, liftNodeId: string): { liftNodeId: string; slotIndex: number } | null {
    if (vehicle.taskId || vehicle.loaded) {
      return null;
    }
    const activeNodeIds = [
      vehicle.currentNodeId,
      vehicle.targetNodeId
    ].filter((nodeId): nodeId is string => Boolean(nodeId));
    const activeSlots = activeNodeIds
      .map((nodeId) => this.topLiftInboundApproachQueueSlot(nodeId))
      .filter((slot): slot is { liftNodeId: string; slotIndex: number } =>
        Boolean(slot) && slot!.liftNodeId === liftNodeId
      )
      .sort((left, right) => left.slotIndex - right.slotIndex);
    if (activeSlots[0]) {
      return activeSlots[0];
    }
    return null;
  }

  private topLiftInboundLocalQueueReserveShouldHoldRemoteAssignment(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.mixedTopLiftFlowEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    return this.vehicles.some((vehicle) =>
      !vehicle.taskId &&
      !vehicle.loaded &&
      vehicle.localRouteReason === 'inbound-queue-standby' &&
      this.topLiftInboundVehicleContributesQueueCoverage(vehicle, liftNodeId)
    );
  }

  private topLiftInboundLowerLevelAssignmentBlocked(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.mixedTopLiftFlowEnabled()) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    return Boolean(liftNodeId && this.liftPortKindForNodeId(liftNodeId) === 'inbound');
  }

  private tasklessInboundQueueReserveProtectedFromTask(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' && this.topLiftTasklessVehicleShouldReserveForInboundQueue(vehicle)) {
      return true;
    }
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.localRouteReason !== 'inbound-queue-standby' ||
      vehicle.plannedGoalNodeId === null
    ) {
      return false;
    }
    const reserveSlot = this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId);
    if (!reserveSlot) {
      return false;
    }
    if (task.kind !== 'inbound') {
      return this.topLiftInboundQueueReserveShouldHoldForOutbound(vehicle, reserveSlot.liftNodeId);
    }
    const taskLiftNodeId = this.taskLiftPortNodeId(task);
    if (taskLiftNodeId !== reserveSlot.liftNodeId) {
      return true;
    }
    return !this.topLiftInboundVehicleContributesQueueCoverage(vehicle, taskLiftNodeId);
  }

  private topLiftTasklessVehicleShouldReserveForInboundQueue(vehicle: MutableVehicle): boolean {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      this.assignmentHoldActive(vehicle) ||
      !this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)
    ) {
      return false;
    }
    if (!this.inboundLiftsNeedQueueReserve()) {
      return false;
    }
    const route = this.routeToInboundQueueStandby(vehicle);
    return route !== null && this.tasklessInboundQueueStandbyRouteOriginAllowed(route);
  }

  private inboundLiftsNeedQueueReserve(): boolean {
    return this.inboundLiftNodes().some((lift) =>
      this.topLiftInboundQueueCoveredDepth(lift.id) < this.topLiftInboundQueueReserveRequiredDepth(lift.id)
    );
  }

  private topLiftInboundQueueReserveShouldHoldForOutbound(vehicle: MutableVehicle, liftNodeId: string): boolean {
    const requiredDepth = this.topLiftInboundQueueReserveRequiredDepth(liftNodeId);
    if (requiredDepth <= 0) {
      return false;
    }
    const protectedVehicleIds = this.vehicles
      .map((candidate) => {
        if (
          candidate.loaded ||
          candidate.taskId ||
          candidate.localRouteReason !== 'inbound-queue-standby' ||
          !this.topLiftInboundVehicleContributesQueueCoverage(candidate, liftNodeId)
        ) {
          return null;
        }
        const slot =
          this.topLiftInboundApproachQueueSlot(candidate.currentNodeId) ??
          this.topLiftInboundApproachQueueSlot(candidate.targetNodeId ?? '') ??
          this.topLiftInboundApproachQueueSlot(candidate.plannedGoalNodeId ?? '');
        return slot?.liftNodeId === liftNodeId ? { vehicleId: candidate.id, slotIndex: slot.slotIndex } : null;
      })
      .filter((entry): entry is { vehicleId: string; slotIndex: number } => entry !== null)
      .sort((left, right) => left.slotIndex - right.slotIndex || left.vehicleId.localeCompare(right.vehicleId))
      .slice(0, requiredDepth)
      .map((entry) => entry.vehicleId);
    return protectedVehicleIds.includes(vehicle.id);
  }

  private topLiftInboundCrossLiftAssignmentBlocked(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.loaded ||
      (vehicle.taskId !== null && vehicle.taskId !== task.id)
    ) {
      return false;
    }
    const targetLiftNodeId = this.taskLiftPortNodeId(task);
    if (!targetLiftNodeId || this.liftPortKindForNodeId(targetLiftNodeId) !== 'inbound') {
      return false;
    }
    const localLiftNodeId = this.topLiftInboundLiftContextForVehicle(vehicle);
    return Boolean(localLiftNodeId && localLiftNodeId !== targetLiftNodeId);
  }

  private topLiftInboundLiftContextForVehicle(vehicle: MutableVehicle): string | null {
    const nodeIds = [
      vehicle.currentNodeId,
      vehicle.targetNodeId,
      vehicle.plannedGoalNodeId,
      ...this.vehicleRouteTail(vehicle, vehicle.routeNodeIds).slice(0, 3),
      ...this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds).slice(0, 3)
    ].filter((nodeId): nodeId is string => Boolean(nodeId));
    for (const nodeId of nodeIds) {
      const liftNodeId = this.topLiftInboundLiftContextForNode(nodeId);
      if (liftNodeId) {
        return liftNodeId;
      }
    }
    return null;
  }

  private topLiftInboundLiftContextForNode(nodeId: string): string | null {
    const slot =
      this.topLiftInboundApproachQueueSlot(nodeId) ??
      topLiftQueueParkingSlot(nodeId) ??
      topLiftQueueAisleAccess(nodeId) ??
      topLiftQueueEntrySlot(nodeId) ??
      topLiftQueueServiceSlot(nodeId);
    if (slot && this.liftPortKindForNodeId(slot.liftNodeId) === 'inbound') {
      return slot.liftNodeId;
    }
    if (!isTopLiftAisleLevelNodeId(nodeId, 'top-a') && !isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(nodeId);
    if (column === null) {
      return null;
    }
    const nearest = this.inboundLiftNodes()
      .map((liftNode) => {
        const pickupStopNodeId = this.topLiftInboundPickupStopNodeId(liftNode.id);
        const pickupColumn = pickupStopNodeId ? this.topLiftColumnAccessColumn(pickupStopNodeId) : null;
        return pickupColumn === null ? null : { liftNodeId: liftNode.id, distance: Math.abs(column - pickupColumn) };
      })
      .filter((entry): entry is { liftNodeId: string; distance: number } => entry !== null)
      .sort((left, right) => left.distance - right.distance || left.liftNodeId.localeCompare(right.liftNodeId))[0] ?? null;
    return nearest && nearest.distance <= 4 ? nearest.liftNodeId : null;
  }

  private outboundLiftClearanceReverseAssignmentPenaltyM(vehicle: MutableVehicle, route: string[]): number {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.recentOutboundClearanceRouteNodeIds.length < 2 ||
      route.length < 2 ||
      !isTopLiftAisleLevelNodeId(route[0]!, 'bottom-b')
    ) {
      return 0;
    }

    const recent = vehicle.recentOutboundClearanceRouteNodeIds;
    const lastRecentIndex = recent.length - 1;
    if (route[0] !== recent[lastRecentIndex] || route[1] !== recent[lastRecentIndex - 1]) {
      return 0;
    }

    let reversedLegCount = 0;
    const comparableLength = Math.min(route.length, recent.length);
    for (let index = 0; index < comparableLength; index += 1) {
      if (route[index] !== recent[lastRecentIndex - index]) {
        break;
      }
      reversedLegCount += 1;
    }

    return reversedLegCount >= 2 ? OUTBOUND_LIFT_CLEARANCE_REVERSE_ASSIGNMENT_PENALTY_M : 0;
  }

  private topLiftInboundLowerLevelAssignmentPenaltyM(vehicle: MutableVehicle, task: TaskStateRecord, route: string[]): number {
    if (
      task.kind !== 'inbound' ||
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.loaded ||
      vehicle.taskId !== null
    ) {
      return 0;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return 0;
    }
    const dispatchGoalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
    const dispatchGoalIndex = route.indexOf(dispatchGoalNodeId);
    const approachRoute = dispatchGoalIndex >= 0 ? route.slice(0, dispatchGoalIndex + 1) : route;
    const usesLowerLevelApproach = approachRoute.some((nodeId) => {
      const level = topLiftAisleLevel(nodeId);
      return level === 'middle' || level === 'bottom-a' || level === 'bottom-b';
    });
    return usesLowerLevelApproach ? TOP_LIFT_INBOUND_LOWER_LEVEL_ASSIGNMENT_PENALTY_M : 0;
  }

  private taskAssignmentRoute(vehicle: MutableVehicle, task: TaskStateRecord): string[] {
    const pickupGoalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
    if (vehicle.currentNodeId === pickupGoalNodeId) {
      return [vehicle.currentNodeId];
    }
    if (this.agentRefreshEnabled()) {
      return this.agentRefreshNominalRouteToGoal(vehicle, task, pickupGoalNodeId);
    }
    if (this.agentMinimalEnabled()) {
      return this.agentNominalRouteToGoal(vehicle, task, pickupGoalNodeId);
    }
    return this.planRoute(vehicle.currentNodeId, task, this.parkingNodeFor(vehicle.id));
  }

  private assignTaskToVehicle(vehicle: MutableVehicle, task: TaskStateRecord, route: string[]): void {
    if (!vehicle.taskId) {
      this.clearTasklessRouteReservations(vehicle);
    }
    const agentMinimal = this.agentMinimalEnabled();
    const agentRefresh = this.agentRefreshEnabled();
    const agentSimple = this.agentSimpleEnabled();
    vehicle.taskId = task.id;
    const routeTerminalNodeId = route.at(-1) ?? null;
    const dispatchGoalNodeId = agentRefresh && routeTerminalNodeId
      ? routeTerminalNodeId
      : this.taskDispatchGoalNodeId(task, vehicle);
    if (agentRefresh) {
      this.installAgentRefreshPlannedRoute(vehicle, task, dispatchGoalNodeId, route);
    } else if (agentMinimal) {
      this.installAgentTaskRoute(vehicle, task, dispatchGoalNodeId);
    } else if (agentSimple) {
      this.resetNavigationAtCurrentNode(vehicle);
    } else {
      vehicle.routeNodeIds = route;
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = route[1] ?? null;
    }
    vehicle.state = 'assigned';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.directionSwitchReadyNodeId = null;
    vehicle.recentOutboundClearanceRouteNodeIds = [];
    vehicle.inboundDropoffStandbyHoldUntilSec = null;
    this.setTaskState(task, 'assigned');
    task.vehicleId = vehicle.id;
    task.assignedAtSec = this.simTimeSec;
    task.waitReason = null;
    this.logEvent(
      'task-assigned',
      vehicle.id,
      task.id,
      task.loadId,
      vehicle.currentNodeId,
      task.pickupNodeId,
      agentRefresh ? 'nearest-available-agent-refresh' : agentSimple ? 'nearest-available-agent-goal' : 'nearest-available',
      this.vehiclePosition(vehicle),
      agentSimple
        ? agentRefresh
          ? { pickupNodeId: task.pickupNodeId, dropoffNodeId: task.dropoffNodeId, dispatcherRouteInstalled: false, route: vehicle.routeNodeIds.join('>') }
          : agentMinimal
          ? { pickupNodeId: task.pickupNodeId, dropoffNodeId: task.dropoffNodeId, dispatcherRouteInstalled: false, route: vehicle.routeNodeIds.join('>') }
          : { pickupNodeId: task.pickupNodeId, dropoffNodeId: task.dropoffNodeId, dispatcherRouteInstalled: false }
        : { route: route.join('>') }
    );
  }

  private installAgentTaskRoute(vehicle: MutableVehicle, task: TaskStateRecord, goalNodeId: string): string[] {
    const route = this.simplifyImmediateTurnbackLoops(this.agentNominalRouteToGoal(vehicle, task, goalNodeId));
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    return route;
  }

  private installAgentRefreshPlannedRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    goalNodeId: string,
    plannedRoute?: string[]
  ): string[] {
    const route = this.simplifyImmediateTurnbackLoops(plannedRoute ?? this.agentRefreshNominalRouteToGoal(vehicle, task, goalNodeId));
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.plannedGoalNodeId = goalNodeId;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
    vehicle.assignmentHoldUntilSec = null;
    vehicle.recentOutboundClearanceRouteNodeIds = [];
    return route;
  }

  private restoreMissingTaskRouteAtCurrentNode(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    reason: string
  ): string[] | null {
    const goalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
    if (vehicle.currentNodeId === goalNodeId) {
      return null;
    }

    let route: string[];
    if (this.agentRefreshEnabled()) {
      route = this.installAgentRefreshPlannedRoute(vehicle, task, goalNodeId);
    } else if (this.agentMinimalEnabled()) {
      route = this.installAgentTaskRoute(vehicle, task, goalNodeId);
    } else if (this.agentSimpleEnabled()) {
      route = this.agentNominalRouteToGoal(vehicle, task, goalNodeId);
      vehicle.routeNodeIds = route;
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = route[1] ?? null;
    } else {
      route = this.planRoute(vehicle.currentNodeId, task, this.parkingNodeFor(vehicle.id));
      vehicle.routeNodeIds = route;
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = route[1] ?? null;
    }

    if (route.length < 2) {
      return null;
    }

    vehicle.state = 'assigned';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.directionSwitchReadyNodeId = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    this.logEvent('route-replanned', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, goalNodeId, reason, this.vehiclePosition(vehicle), {
      route: route.join('>')
    });
    return route;
  }

  private resetNavigationAtCurrentNode(vehicle: MutableVehicle): void {
    vehicle.routeNodeIds = [vehicle.currentNodeId];
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = null;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.targetSpeedMps = 0;
    vehicle.plannedGoalNodeId = null;
    vehicle.plannedRouteNodeIds = [];
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
  }

  private clearTasklessRouteReservations(vehicle: MutableVehicle): void {
    this.reservations = this.reservations.filter(
      (reservation) => reservation.vehicleId !== vehicle.id || reservation.reasonCode === 'zone-hold'
    );
    this.ensureZoneHoldReservation(vehicle, vehicle.currentNodeId);
  }

  private resetTasklessVehicleAtCurrentNode(vehicle: MutableVehicle): void {
    this.clearTasklessRouteReservations(vehicle);
    this.resetNavigationAtCurrentNode(vehicle);
    vehicle.state = 'idle';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.assignmentHoldUntilSec = null;
    vehicle.inboundDropoffStandbyHoldUntilSec = null;
    vehicle.directionSwitchReadyNodeId = null;
  }

  private tryAssignQueuedTaskToVehicle(vehicle: MutableVehicle): boolean {
    if (vehicle.taskId || vehicle.loaded || this.queuedTasks().length === 0) {
      return false;
    }

    this.resetTasklessVehicleAtCurrentNode(vehicle);
    if (!this.canAcceptQueuedTask(vehicle)) {
      return false;
    }

    const availableVehicleIds = new Set([vehicle.id]);
    const tryAssignMatchingTask = (matches: (task: TaskStateRecord) => boolean): boolean => {
      for (const { task } of this.queuedTasksForAssignment()) {
        if (!matches(task)) {
          continue;
        }
        if (this.queuedTaskAssignmentPriority(task) > 0 || this.taskAssignmentBlockReason(task)) {
          continue;
        }
        const assignment = this.bestAvailableVehicleForTask(task, availableVehicleIds);
        if (!assignment || assignment.vehicle.id !== vehicle.id) {
          continue;
        }
        if (this.stageVehicleToInboundQueueBeforeAssignment(vehicle, task, assignment.route)) {
          return true;
        }
        if (
          this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task) &&
          !this.topLiftInboundAssignmentRouteStagesThroughQueue(vehicle, task, assignment.route)
        ) {
          return false;
        }
        if (this.topLiftOutboundDropoffAssignmentConflictsWithLoadedApproach(vehicle, task, assignment.route)) {
          this.logEvent(
            'task-assignment-deferred',
            vehicle.id,
            task.id,
            task.loadId,
            vehicle.currentNodeId,
            assignment.route[1] ?? null,
            'loaded-outbound-approach-conflict',
            this.vehiclePosition(vehicle),
            { route: assignment.route.join('>') }
          );
          continue;
        }
        this.assignTaskToVehicle(vehicle, task, assignment.route);
        return true;
      }
      return false;
    };

    if (tryAssignMatchingTask((task) => task.kind === 'inbound')) {
      return true;
    }

    if (this.dispatchTasklessToInboundQueueStandby(vehicle, 'inbound-queue-replenish-before-outbound-assignment')) {
      return true;
    }

    return tryAssignMatchingTask((task) => task.kind !== 'inbound');
  }

  private topLiftOutboundDropoffAssignmentConflictsWithLoadedApproach(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    assignmentRoute: string[]
  ): boolean {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId ||
      assignmentRoute.length < 2 ||
      assignmentRoute[0] !== vehicle.currentNodeId ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-b')
    ) {
      return false;
    }

    const liftNodeId = this.topLiftOutboundDropoffLiftNodeId(vehicle.currentNodeId);
    if (
      !liftNodeId ||
      this.liftPortKindForNodeId(liftNodeId) !== 'outbound' ||
      this.topLiftOutboundDropoffStopNodeId(liftNodeId) !== vehicle.currentNodeId
    ) {
      return false;
    }

    const routeEntersOpposingSpine = assignmentRoute.slice(1, 5).some((nodeId) => {
      const level = topLiftAisleLevel(nodeId);
      return topLiftSpineKey(nodeId) !== null && level !== 'bottom-b';
    });
    if (!routeEntersOpposingSpine) {
      return false;
    }

    return this.vehicles.some((candidate) => {
      if (candidate.id === vehicle.id || !candidate.loaded) {
        return false;
      }
      const candidateTask = this.taskForVehicle(candidate);
      if (
        candidateTask &&
        (candidateTask.kind !== 'outbound' ||
          candidateTask.completedAtSec !== null ||
          (this.taskLiftPortNodeId(candidateTask) !== null && this.taskLiftPortNodeId(candidateTask) !== liftNodeId))
      ) {
        return false;
      }
      const candidateOwnsSameDropoff = candidateTask?.dropoffNodeId === vehicle.currentNodeId;
      const candidateActivelyTargetsSameDropoff = candidate.plannedGoalNodeId === vehicle.currentNodeId;
      if (!candidateOwnsSameDropoff && !candidateActivelyTargetsSameDropoff) {
        return false;
      }
      if (candidateOwnsSameDropoff) {
        return true;
      }
      const candidateRoutes = [
        this.vehicleRouteTail(candidate, candidate.routeNodeIds),
        this.vehicleRouteTail(candidate, candidate.plannedRouteNodeIds)
      ];
      return candidateRoutes.some((routeTail) => {
        const dropoffIndex = routeTail.indexOf(vehicle.currentNodeId);
        return dropoffIndex > 0 && dropoffIndex <= 20;
      }) || (candidate.plannedGoalNodeId === vehicle.currentNodeId && candidate.currentNodeId !== vehicle.currentNodeId);
    });
  }

  private topLiftOutboundDropoffLiftNodeId(nodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    return this.outboundLiftNodes().find((liftNode) =>
      this.topLiftOutboundDropoffStopNodeId(liftNode.id) === nodeId
    )?.id ?? null;
  }

  private stageVehicleToInboundQueueBeforeAssignment(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    assignmentRoute: string[]
  ): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.loaded ||
      (vehicle.taskId !== null && vehicle.taskId !== task.id)
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    if (!this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task)) {
      return false;
    }
    if (!this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)) {
      return false;
    }
    if (this.topLiftInboundAssignmentRouteStagesThroughQueue(vehicle, task, assignmentRoute)) {
      return false;
    }
    const route = this.routeToInboundQueueForTask(vehicle, task);
    if (!route || route.length <= 1) {
      return false;
    }
    const nextNodeId = route[1] ?? null;
    const nextBlock = nextNodeId && this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
          : this.agentMoveBlocker(vehicle, nextNodeId)
      : null;
    if (nextBlock) {
      return false;
    }
    this.installTasklessPostDropoffRoute(vehicle, route, 'inbound-queue-replenish-before-assignment', 'inbound-queue-standby');
    return true;
  }

  private topLiftInboundAssignmentMustStageThroughQueue(vehicle: MutableVehicle | VehicleState, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.loaded ||
      (vehicle.taskId !== null && vehicle.taskId !== task.id)
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    if (vehicle.currentNodeId === task.pickupNodeId) {
      return false;
    }
    return this.topLiftInboundCurrentQueueResourceSlot(vehicle, liftNodeId) === null;
  }

  private topLiftInboundCurrentQueueResourceSlot(vehicle: MutableVehicle | VehicleState, liftNodeId: string): { liftNodeId: string; slotIndex: number } | null {
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    return currentSlot?.liftNodeId === liftNodeId ? currentSlot : null;
  }

  private topLiftInboundActiveQueueRouteTerminalNodeId(task: TaskStateRecord, vehicle: MutableVehicle | VehicleState): string | null {
    if (task.kind !== 'inbound' || vehicle.loaded) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return null;
    }
    const routeTerminalNodeId = vehicle.routeNodeIds.at(-1) ?? vehicle.plannedRouteNodeIds.at(-1) ?? vehicle.plannedGoalNodeId;
    const terminalSlot = routeTerminalNodeId ? this.topLiftInboundApproachQueueSlot(routeTerminalNodeId) : null;
    return terminalSlot?.liftNodeId === liftNodeId ? routeTerminalNodeId : null;
  }

  private topLiftInboundAssignmentRouteStagesThroughQueue(
    vehicle: MutableVehicle | VehicleState,
    task: TaskStateRecord,
    route: string[]
  ): boolean {
    if (!this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task)) {
      return true;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const terminalSlot = this.topLiftInboundApproachQueueSlot(route.at(-1) ?? '');
    return Boolean(liftNodeId && terminalSlot?.liftNodeId === liftNodeId);
  }

  private routeToInboundQueueForTask(vehicle: MutableVehicle, task: TaskStateRecord): string[] | null {
    if (!this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task)) {
      return null;
    }
    const targetNodeId = this.topLiftInboundQueueNodeIdForTask(task, vehicle);
    if (!targetNodeId || targetNodeId === vehicle.currentNodeId) {
      return null;
    }
    try {
      const route = this.planStandbyRoute(
        vehicle.currentNodeId,
        targetNodeId,
        this.activeTopLiftOutboundDockBlockedNodeIds(vehicle.id)
      );
      if (
        route.length > 1 &&
        route.at(-1) === targetNodeId &&
        this.routeEdgesExist(route) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, route) &&
        this.tasklessInboundQueueStandbyRouteAllowed(vehicle, route) &&
        this.routeAvoidsActiveTopLiftOutboundDockBlocks(vehicle, route)
      ) {
        return route;
      }
    } catch {
      return null;
    }
    return null;
  }

  private tryReassignRouteUnavailableInboundPickupTask(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.vehicleId !== vehicle.id ||
      task.state !== 'assigned' ||
      task.startedAtSec !== null ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    const dispatchGoalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
    const goalLiftNodeId = this.topLiftInboundEmptyApproachLiftNodeId(task, goalNodeId);
    if (goalNodeId !== dispatchGoalNodeId && goalLiftNodeId !== liftNodeId) {
      return false;
    }

    const currentLiftContext = this.topLiftInboundLiftContextForVehicle(vehicle);
    const currentQueueSlot = this.topLiftInboundCurrentQueueResourceSlot(vehicle, liftNodeId);
    if (currentLiftContext === liftNodeId && (currentQueueSlot || vehicle.currentNodeId === task.pickupNodeId)) {
      return false;
    }

    const availableVehicleIds = new Set(
      this.vehicles
        .filter((candidate) =>
          candidate.id !== vehicle.id &&
          this.topLiftInboundRouteUnavailableReassignmentCandidate(candidate, liftNodeId)
        )
        .map((candidate) => candidate.id)
    );
    if (availableVehicleIds.size === 0) {
      return this.tryHandoffRouteUnavailableInboundPickupTaskToFifoReplacement(vehicle, task, liftNodeId);
    }

    const previousVehicleId = vehicle.id;
    const assignment = this.bestAvailableVehicleForTask(task, availableVehicleIds);
    if (!assignment || assignment.vehicle.id === previousVehicleId) {
      return this.tryHandoffRouteUnavailableInboundPickupTaskToFifoReplacement(vehicle, task, liftNodeId);
    }

    const nextVehicle = assignment.vehicle;
    task.vehicleId = null;
    task.waitReason = null;
    vehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(vehicle);
    this.assignTaskToVehicle(nextVehicle, task, assignment.route);
    this.logEvent(
      'task-reassigned',
      nextVehicle.id,
      task.id,
      task.loadId,
      vehicle.currentNodeId,
      nextVehicle.currentNodeId,
      'inbound-route-unavailable-local-resource',
      this.vehiclePosition(nextVehicle),
      {
        previousVehicleId,
        nextVehicleId: nextVehicle.id,
        liftNodeId,
        route: assignment.route.join('>')
      }
    );
    return true;
  }

  private tryHandoffRouteUnavailableInboundPickupTaskToFifoReplacement(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    liftNodeId: string
  ): boolean {
    const replacement = this.topLiftInboundRouteUnavailableFifoReplacementCandidate(vehicle, task, liftNodeId);
    if (!replacement) {
      return false;
    }

    const snapshot = this.createSnapshot();
    const previousVehicleId = vehicle.id;
    const nextVehicle = replacement.vehicle;
    const displacedTask = replacement.task;

    displacedTask.vehicleId = null;
    displacedTask.waitReason = 'inbound-lift-fifo-wait';
    this.setTaskState(displacedTask, 'queued');
    nextVehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(nextVehicle);

    task.vehicleId = null;
    task.waitReason = null;
    vehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(vehicle);
    vehicle.assignmentHoldUntilSec = round(this.simTimeSec + OUTBOUND_STORAGE_ROUTE_UNAVAILABLE_REASSIGN_HOLD_SEC);

    const assignment = this.bestAvailableVehicleForTask(task, new Set([nextVehicle.id]));
    if (!assignment || assignment.vehicle.id !== nextVehicle.id) {
      this.restoreSnapshot(snapshot);
      return false;
    }

    this.assignTaskToVehicle(nextVehicle, task, assignment.route);
    this.logEvent(
      'task-reassigned',
      nextVehicle.id,
      task.id,
      task.loadId,
      vehicle.currentNodeId,
      nextVehicle.currentNodeId,
      'inbound-route-unavailable-fifo-handoff',
      this.vehiclePosition(nextVehicle),
      {
        previousVehicleId,
        nextVehicleId: nextVehicle.id,
        displacedTaskId: displacedTask.id,
        liftNodeId,
        replacementSlotIndex: replacement.slotIndex,
        route: assignment.route.join('>')
      }
    );
    return true;
  }

  private topLiftInboundRouteUnavailableFifoReplacementCandidate(
    stuckVehicle: MutableVehicle,
    stuckTask: TaskStateRecord,
    liftNodeId: string
  ): { vehicle: MutableVehicle; task: TaskStateRecord; slotIndex: number } | null {
    const candidates = this.vehicles
      .map((candidate) => {
        if (
          candidate.id === stuckVehicle.id ||
          candidate.loaded ||
          candidate.currentEdgeId !== null ||
          candidate.legRemainingM > 0 ||
          candidate.phaseRemainingSec > 0 ||
          this.assignmentHoldActive(candidate)
        ) {
          return null;
        }
        if (
          candidate.state !== 'assigned' &&
          candidate.state !== 'waiting-blocked' &&
          candidate.state !== 'idle'
        ) {
          return null;
        }
        const candidateTask = this.taskById(candidate.taskId);
        if (
          !candidateTask ||
          candidateTask.id === stuckTask.id ||
          candidateTask.kind !== 'inbound' ||
          candidateTask.state !== 'assigned' ||
          candidateTask.startedAtSec !== null ||
          candidateTask.vehicleId !== candidate.id ||
          this.taskLiftPortNodeId(candidateTask) !== liftNodeId
        ) {
          return null;
        }
        const slot =
          this.topLiftInboundApproachQueueSlot(candidate.currentNodeId) ??
          this.topLiftInboundApproachQueueSlot(candidate.targetNodeId ?? '') ??
          this.topLiftInboundApproachQueueSlot(candidate.plannedGoalNodeId ?? '');
        if (!slot || slot.liftNodeId !== liftNodeId) {
          return null;
        }
        const waitingInSameQueue =
          candidate.waitReason === 'inbound-lift-fifo-wait' ||
          candidate.waitReason === 'inbound-column-predecessor-wait' ||
          candidate.currentNodeId === candidate.targetNodeId ||
          candidate.targetNodeId === null;
        if (!waitingInSameQueue) {
          return null;
        }
        return { vehicle: candidate, task: candidateTask, slotIndex: slot.slotIndex };
      })
      .filter((candidate): candidate is { vehicle: MutableVehicle; task: TaskStateRecord; slotIndex: number } =>
        candidate !== null
      )
      .sort((left, right) =>
        left.slotIndex - right.slotIndex ||
        left.vehicle.id.localeCompare(right.vehicle.id)
      );
    return candidates[0] ?? null;
  }

  private topLiftInboundRouteUnavailableReassignmentCandidate(vehicle: MutableVehicle, liftNodeId: string): boolean {
    if (
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      this.assignmentHoldActive(vehicle)
    ) {
      return false;
    }
    if (
      vehicle.state !== 'idle' &&
      vehicle.state !== 'assigned' &&
      vehicle.state !== 'waiting-blocked' &&
      vehicle.state !== 'parking' &&
      vehicle.state !== 'returning'
    ) {
      return false;
    }
    if (
      this.tasklessPlannedRouteActive(vehicle) &&
      vehicle.localRouteReason !== 'inbound-queue-standby'
    ) {
      return false;
    }
    return this.topLiftInboundQueueResourceSlot(vehicle, liftNodeId) !== null ||
      this.topLiftInboundLiftContextForVehicle(vehicle) === liftNodeId;
  }

  private routeDistanceM(routeNodeIds: string[], stopAtNodeId?: string): number {
    if (stopAtNodeId && routeNodeIds[0] === stopAtNodeId) {
      return 0;
    }
    let distanceM = 0;
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromNodeId = routeNodeIds[index - 1]!;
      const toNodeId = routeNodeIds[index]!;
      const edge = this.traffic.findEdge(fromNodeId, toNodeId);
      if (!edge) {
        throw new Error(`No route edge between ${fromNodeId} and ${toNodeId}`);
      }
      distanceM += edge.lengthM;
      if (toNodeId === stopAtNodeId) {
        return distanceM;
      }
    }
    return distanceM;
  }

  private routeTurnPenaltyCostM(routeNodeIds: string[], initialAxis: MovementAxis = null, stopAtNodeId?: string): number {
    let penaltyM = 0;
    let previousAxis = initialAxis;
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const axis = this.axisBetweenNodes(routeNodeIds[index - 1]!, routeNodeIds[index]!);
      penaltyM += this.turnPenaltyCostM(previousAxis, axis);
      previousAxis = axis ?? previousAxis;
      if (routeNodeIds[index] === stopAtNodeId) {
        return penaltyM;
      }
    }
    return penaltyM;
  }

  private routePlannerCostM(routeNodeIds: string[], stopAtNodeId?: string, initialAxis: MovementAxis = null): number {
    return this.routeDistanceM(routeNodeIds, stopAtNodeId) + this.routeTurnPenaltyCostM(routeNodeIds, initialAxis, stopAtNodeId);
  }

  private routeTravelEstimateSec(vehicle: MutableVehicle, routeNodeIds: string[]): number {
    return round(this.routeTravelEstimateForSpeedSec(routeNodeIds, (edge) => this.speedForEdge(vehicle, edge), vehicle.lastMovementAxis));
  }

  private routeTravelEstimateForSpeedSec(
    routeNodeIds: string[],
    speedForEdge: (edge: ShuttleScenario['layout']['edges'][number]) => number,
    initialAxis: MovementAxis = null
  ): number {
    let travelSec = 0;
    let previousAxis = initialAxis;
    let segmentAxis: MovementAxis = null;
    let segmentDistanceM = 0;
    let segmentSpeedMps = 0;
    const flushSegment = (): void => {
      if (segmentDistanceM <= 0 || segmentSpeedMps <= 0) {
        return;
      }
      travelSec += calculateTravelTimeSec(segmentDistanceM, segmentSpeedMps, this.scenario.physicsParams.accelerationMps2);
      segmentDistanceM = 0;
      segmentSpeedMps = 0;
    };

    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromNodeId = routeNodeIds[index - 1]!;
      const toNodeId = routeNodeIds[index]!;
      const edge = this.traffic.findEdge(fromNodeId, toNodeId);
      if (!edge) {
        continue;
      }
      const axis = this.axisForEdge(edge);
      const speedMps = speedForEdge(edge);
      if (segmentAxis && axis && axis === segmentAxis && Math.abs(speedMps - segmentSpeedMps) <= 1e-9) {
        segmentDistanceM += edge.lengthM;
        previousAxis = axis;
        continue;
      }
      flushSegment();
      if (previousAxis && axis && previousAxis !== axis) {
        travelSec += this.scenario.physicsParams.switchDirectionSec;
      }
      segmentAxis = axis;
      segmentDistanceM = edge.lengthM;
      segmentSpeedMps = speedMps;
      previousAxis = axis ?? previousAxis;
    }
    flushSegment();
    return travelSec;
  }

  private nearestLiftPortNodeIdByDistance(kind: LiftKind, relatedNodeId: string): string | null {
    const related = this.scenario.layout.nodes.find((node) => node.id === relatedNodeId);
    const liftNodes = this.scenario.layout.nodes
      .filter((node) => liftKindForNode(node) === kind)
      .sort((left, right) => {
        const leftDistance = related ? Math.abs(left.x - related.x) + Math.abs(left.z - related.z) : 0;
        const rightDistance = related ? Math.abs(right.x - related.x) + Math.abs(right.z - related.z) : 0;
        return leftDistance - rightDistance || left.id.localeCompare(right.id);
      });
    return liftNodes[0]?.id ?? null;
  }

  private routeThroughTargets(startNodeId: string, targets: string[]): string[] {
    const route = [startNodeId];
    for (const target of targets) {
      if (target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      const blockedStorageNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target);
      const segment = this.shortestPath(fromNodeId, target, blockedStorageNodeIds);
      route.push(...segment.slice(1));
    }
    return route;
  }

  private idealInboundCycleForStorageCell(storageNodeId: string): {
    loadedDistanceM: number;
    emptyReturnDistanceM: number;
    loadedTravelSec: number;
    emptyReturnSec: number;
    cycleSec: number;
    loadedRouteNodeIds: string[];
    emptyReturnRouteNodeIds: string[];
  } | null {
    const liftNodeId = this.nearestLiftPortNodeIdByDistance('inbound', storageNodeId);
    const storageEntryNodeId = this.storageSideNodeId(storageNodeId, 'right');
    const storageExitNodeId = this.storageSideNodeId(storageNodeId, 'left');
    if (!liftNodeId || !storageEntryNodeId || !storageExitNodeId) {
      return null;
    }

    try {
      const loadedRoute = this.routeThroughTargets(liftNodeId, [storageEntryNodeId, storageNodeId]);
      const emptyReturnRoute = this.routeThroughTargets(storageNodeId, [storageExitNodeId, liftNodeId]);
      const loadedDistanceM = this.routeDistanceM(loadedRoute);
      const emptyReturnDistanceM = this.routeDistanceM(emptyReturnRoute);
      const loadedTravelSec = this.routeTravelEstimateForSpeedSec(
        loadedRoute,
        (edge) => Math.min(edge.speedLimitLoadedMps ?? this.scenario.physicsParams.loadedSpeedMps, this.scenario.physicsParams.loadedSpeedMps)
      );
      const emptyReturnSec = this.routeTravelEstimateForSpeedSec(
        emptyReturnRoute,
        (edge) => Math.min(edge.speedLimitEmptyMps ?? this.scenario.physicsParams.emptySpeedMps, this.scenario.physicsParams.emptySpeedMps)
      );
      const cycleSec = loadedTravelSec + emptyReturnSec + this.scenario.physicsParams.liftTimeSec + this.scenario.physicsParams.lowerTimeSec;
      return { loadedDistanceM, emptyReturnDistanceM, loadedTravelSec, emptyReturnSec, cycleSec, loadedRouteNodeIds: loadedRoute, emptyReturnRouteNodeIds: emptyReturnRoute };
    } catch {
      return null;
    }
  }

  private idealTopLiftOutboundCycleForStorageCell(storageNodeId: string): {
    loadedDistanceM: number;
    emptyReturnDistanceM: number;
    loadedTravelSec: number;
    emptyReturnSec: number;
    cycleSec: number;
    loadedRouteNodeIds: string[];
    emptyReturnRouteNodeIds: string[];
  } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const liftNodeId = this.nearestLiftPortNodeIdByDistance('outbound', storageNodeId);
    const dropoffStopNodeId = liftNodeId ? this.topLiftOutboundDropoffStopNodeId(liftNodeId) : null;
    const clearThroughNodeId = liftNodeId ? this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId) : null;
    const storageExitNodeId = this.storageSideNodeId(storageNodeId, 'left');
    const storageEntryNodeId = this.storageSideNodeId(storageNodeId, 'right');
    if (!liftNodeId || !dropoffStopNodeId || !storageExitNodeId || !storageEntryNodeId) {
      return null;
    }

    try {
      const loadedTargets = [storageExitNodeId, dropoffStopNodeId, clearThroughNodeId].filter((nodeId): nodeId is string => Boolean(nodeId));
      const loadedRoute = this.routeThroughTargets(storageNodeId, loadedTargets);
      const emptyReturnRoute = this.routeThroughTargets(loadedRoute[loadedRoute.length - 1]!, [storageEntryNodeId, storageNodeId]);
      const loadedDistanceM = this.routeDistanceM(loadedRoute);
      const emptyReturnDistanceM = this.routeDistanceM(emptyReturnRoute);
      const loadedTravelSec = this.routeTravelEstimateForSpeedSec(
        loadedRoute,
        (edge) => Math.min(edge.speedLimitLoadedMps ?? this.scenario.physicsParams.loadedSpeedMps, this.scenario.physicsParams.loadedSpeedMps)
      );
      const emptyReturnSec = this.routeTravelEstimateForSpeedSec(
        emptyReturnRoute,
        (edge) => Math.min(edge.speedLimitEmptyMps ?? this.scenario.physicsParams.emptySpeedMps, this.scenario.physicsParams.emptySpeedMps)
      );
      const cycleSec = loadedTravelSec + emptyReturnSec + this.scenario.physicsParams.liftTimeSec + this.scenario.physicsParams.lowerTimeSec;
      return { loadedDistanceM, emptyReturnDistanceM, loadedTravelSec, emptyReturnSec, cycleSec, loadedRouteNodeIds: loadedRoute, emptyReturnRouteNodeIds: emptyReturnRoute };
    } catch {
      return null;
    }
  }

  private flowDemandShares(): { inboundShare: number; outboundShare: number; activeFlowCount: number } {
    const inboundDemand = this.scenario.taskGeneration.inboundRatePerHour;
    const outboundDemand = this.scenario.taskGeneration.outboundRatePerHour;
    const totalDemand = inboundDemand + outboundDemand;
    if (totalDemand <= 0) {
      return { inboundShare: 1, outboundShare: 0, activeFlowCount: 1 };
    }
    return {
      inboundShare: inboundDemand / totalDemand,
      outboundShare: outboundDemand / totalDemand,
      activeFlowCount: (inboundDemand > 0 ? 1 : 0) + (outboundDemand > 0 ? 1 : 0)
    };
  }

  private liftPortCapacityBoundPph(inboundShare: number, outboundShare: number): TheoreticalCapacityBound {
    const inboundLiftCount = Math.max(0, this.inboundLiftNodes().length);
    const outboundLiftCount = Math.max(0, this.outboundLiftNodes().length);
    const inboundServiceCycleSec = Math.max(
      0.001,
      this.scenario.physicsParams.liftTimeSec +
        this.scenario.physicsParams.switchDirectionSec +
        this.scenario.physicsParams.reservationClearanceSec
    );
    const outboundServiceCycleSec = Math.max(
      0.001,
      this.scenario.physicsParams.lowerTimeSec +
        this.scenario.physicsParams.switchDirectionSec +
        this.scenario.physicsParams.reservationClearanceSec
    );
    const inboundCapacityPph = inboundLiftCount > 0 ? inboundLiftCount * 3600 / inboundServiceCycleSec : 0;
    const outboundCapacityPph = outboundLiftCount > 0 ? outboundLiftCount * 3600 / outboundServiceCycleSec : 0;
    const mixLimitedPph = Math.min(
      inboundShare > 0 ? inboundCapacityPph / inboundShare : Infinity,
      outboundShare > 0 ? outboundCapacityPph / outboundShare : Infinity
    );
    return {
      kind: 'lift-port',
      pph: round(Number.isFinite(mixLimitedPph) ? mixLimitedPph : Math.max(inboundCapacityPph, outboundCapacityPph), 3),
      cycleSec: round(Math.max(inboundServiceCycleSec, outboundServiceCycleSec), 3),
      utilizationBasis: `${inboundLiftCount} inbound lift(s), ${outboundLiftCount} outbound lift(s)`,
      assumptions: [
        'service cycle includes lift/lower time, direction-change allowance, and reservation clearance',
        'mixed-flow total capacity is limited by the requested inbound/outbound demand split'
      ]
    };
  }

  private columnResourceCapacityBoundPph(weightedCycleSec: number): TheoreticalCapacityBound {
    const columnCount = Math.max(1, this.topLiftStorageColumnNumbers().length);
    const rowsPerColumn = Math.max(1, this.topLiftStorageColumnNodeIds(this.topLiftStorageColumnNumbers()[0] ?? 1).length);
    const activeColumnParallelism = Math.max(1, Math.min(columnCount, this.inboundLiftNodes().length + this.outboundLiftNodes().length));
    const perPositionCycleSec = Math.max(0.001, weightedCycleSec / Math.max(1, rowsPerColumn));
    return {
      kind: 'column-resource',
      pph: round(activeColumnParallelism * 3600 / perPositionCycleSec, 3),
      cycleSec: round(perPositionCycleSec, 3),
      utilizationBasis: `${activeColumnParallelism}/${columnCount} serviceable column(s), ${rowsPerColumn} positions per column`,
      assumptions: [
        'each SKU column is a mutex: a column cannot be filled and drained at the same time',
        'parallelism is capped by active lift ports until explicit column assignment policy is proven'
      ]
    };
  }

  private networkMinCutCapacityBoundPph(samples: Array<{
    loadedRouteNodeIds: string[];
    emptyReturnRouteNodeIds: string[];
  }>): TheoreticalCapacityBound {
    const groupOccupancySec = new Map<string, number>();
    const sampleWeight = 1 / Math.max(1, samples.length);
    const addRoute = (routeNodeIds: string[], loaded: boolean): void => {
      for (let index = 1; index < routeNodeIds.length; index += 1) {
        const fromNodeId = routeNodeIds[index - 1]!;
        const toNodeId = routeNodeIds[index]!;
        const edge = this.traffic.findEdge(fromNodeId, toNodeId);
        if (!edge) {
          continue;
        }
        const group = edge.conflictGroup ?? edge.id;
        const speed = loaded
          ? Math.min(edge.speedLimitLoadedMps ?? this.scenario.physicsParams.loadedSpeedMps, this.scenario.physicsParams.loadedSpeedMps)
          : Math.min(edge.speedLimitEmptyMps ?? this.scenario.physicsParams.emptySpeedMps, this.scenario.physicsParams.emptySpeedMps);
        const occupancySec = calculateTravelTimeSec(edge.lengthM, speed, this.scenario.physicsParams.accelerationMps2);
        groupOccupancySec.set(group, (groupOccupancySec.get(group) ?? 0) + occupancySec * sampleWeight);
      }
    };
    for (const sample of samples) {
      addRoute(sample.loadedRouteNodeIds, true);
      addRoute(sample.emptyReturnRouteNodeIds, false);
    }
    const [criticalGroup, criticalOccupancySec] = [...groupOccupancySec.entries()]
      .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))[0] ?? ['none', 0];
    return {
      kind: 'network-min-cut',
      pph: round(criticalOccupancySec > 0 ? 3600 / criticalOccupancySec : 0, 3),
      cycleSec: round(criticalOccupancySec, 3),
      utilizationBasis: criticalGroup,
      assumptions: [
        'network bound estimates the busiest legal route conflict-group occupancy from sampled ideal routes',
        'this is a min-cut proxy and must be replaced by CAD-calibrated swept-envelope validation before customer PPH claims'
      ]
    };
  }

  private calculateTopLiftTheoreticalCapacityBaseline(): TheoreticalCapacityBaseline {
    const inboundSamples = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .flatMap((node) => this.idealInboundCycleForStorageCell(node.id) ?? []);
    const outboundSamples = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .flatMap((node) => this.idealTopLiftOutboundCycleForStorageCell(node.id) ?? []);
    const { inboundShare, outboundShare } = this.flowDemandShares();
    const activeInboundSamples = inboundShare > 0 ? inboundSamples : [];
    const activeOutboundSamples = outboundShare > 0 ? outboundSamples : [];
    const samples = [...activeInboundSamples, ...activeOutboundSamples];
    const sampleCount = Math.max(1, samples.length);
    const weightedCycleSec =
      (inboundShare > 0 && inboundSamples.length > 0
        ? inboundShare * inboundSamples.reduce((sum, sample) => sum + sample.cycleSec, 0) / inboundSamples.length
        : 0) +
      (outboundShare > 0 && outboundSamples.length > 0
        ? outboundShare * outboundSamples.reduce((sum, sample) => sum + sample.cycleSec, 0) / outboundSamples.length
        : 0);
    const averageCycleSec = weightedCycleSec > 0
      ? weightedCycleSec
      : samples.reduce((sum, sample) => sum + sample.cycleSec, 0) / sampleCount;
    const averageLoadedDistanceM = samples.reduce((sum, sample) => sum + sample.loadedDistanceM, 0) / sampleCount;
    const averageEmptyReturnDistanceM = samples.reduce((sum, sample) => sum + sample.emptyReturnDistanceM, 0) / sampleCount;
    const averageLoadedTravelSec = samples.reduce((sum, sample) => sum + sample.loadedTravelSec, 0) / sampleCount;
    const averageEmptyReturnSec = samples.reduce((sum, sample) => sum + sample.emptyReturnSec, 0) / sampleCount;
    const shuttleCycleBound: TheoreticalCapacityBound = {
      kind: 'shuttle-cycle',
      pph: round(averageCycleSec > 0 ? this.scenario.vehicles.count * 3600 / averageCycleSec : 0, 3),
      cycleSec: round(averageCycleSec, 3),
      utilizationBasis: `${this.scenario.vehicles.count} shared shuttle(s)`,
      assumptions: [
        'weighted by configured inbound/outbound demand split',
        'uses legal top-lift service stop routes and configured speed/turn/lift timing'
      ]
    };
    const bounds = [
      this.liftPortCapacityBoundPph(inboundShare, outboundShare),
      shuttleCycleBound,
      this.columnResourceCapacityBoundPph(averageCycleSec),
      this.networkMinCutCapacityBoundPph(samples)
    ].sort((left, right) => left.pph - right.pph || left.kind.localeCompare(right.kind));
    const limitingBound = bounds[0]!;
    const fleetPph = limitingBound.pph;
    const singleShuttlePph = this.scenario.vehicles.count > 0 ? fleetPph / this.scenario.vehicles.count : 0;
    return {
      kind: 'top-lift-column',
      formulaVersion: 'top-lift-four-bound-v1',
      shuttleCount: this.scenario.vehicles.count,
      singleShuttlePph: round(singleShuttlePph, 3),
      fleetPph: round(fleetPph, 3),
      idealCycleSec: round(averageCycleSec, 3),
      loadedTravelSec: round(averageLoadedTravelSec, 3),
      emptyReturnSec: round(averageEmptyReturnSec, 3),
      liftAndLowerSec: round(this.scenario.physicsParams.liftTimeSec + this.scenario.physicsParams.lowerTimeSec, 3),
      averageLoadedDistanceM: round(averageLoadedDistanceM, 3),
      averageEmptyReturnDistanceM: round(averageEmptyReturnDistanceM, 3),
      limitingBound: limitingBound.kind,
      bounds,
      assumptions: [
        'top-lift four-bound estimate: lift-port, shuttle-cycle, column-resource, and network-min-cut',
        'not a customer PPH proof until CAD obstacle masks and lift workcell FSM gates are verified',
        'inbound/outbound route samples use legal service stop and clear-through graph nodes, not legacy row-bank lift nodes'
      ]
    };
  }

  private calculateTheoreticalCapacityBaseline(): TheoreticalCapacityBaseline {
    if (this.theoreticalCapacityBaseline) {
      return this.theoreticalCapacityBaseline;
    }
    const cacheKey = this.theoreticalCapacityBaselineCacheKey();
    const cached = theoreticalCapacityBaselineCache.get(cacheKey);
    if (cached) {
      this.theoreticalCapacityBaseline = cached;
      return cached;
    }

    if (this.topLiftColumnLayoutEnabled()) {
      this.theoreticalCapacityBaseline = this.calculateTopLiftTheoreticalCapacityBaseline();
      theoreticalCapacityBaselineCache.set(cacheKey, this.theoreticalCapacityBaseline);
      return this.theoreticalCapacityBaseline;
    }

    const samples = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .flatMap((node) => this.idealInboundCycleForStorageCell(node.id) ?? []);
    const sampleCount = Math.max(1, samples.length);
    const averageCycleSec = samples.reduce((sum, sample) => sum + sample.cycleSec, 0) / sampleCount;
    const averageLoadedDistanceM = samples.reduce((sum, sample) => sum + sample.loadedDistanceM, 0) / sampleCount;
    const averageEmptyReturnDistanceM = samples.reduce((sum, sample) => sum + sample.emptyReturnDistanceM, 0) / sampleCount;
    const averageLoadedTravelSec = samples.reduce((sum, sample) => sum + sample.loadedTravelSec, 0) / sampleCount;
    const averageEmptyReturnSec = samples.reduce((sum, sample) => sum + sample.emptyReturnSec, 0) / sampleCount;
    const singleShuttlePph = averageCycleSec > 0 ? 3600 / averageCycleSec : 0;
    const fleetPph = singleShuttlePph * this.scenario.vehicles.count;
    this.theoreticalCapacityBaseline = {
      kind: 'inbound',
      formulaVersion: 'inbound-ideal-v1',
      shuttleCount: this.scenario.vehicles.count,
      singleShuttlePph: round(singleShuttlePph, 3),
      fleetPph: round(fleetPph, 3),
      idealCycleSec: round(averageCycleSec, 3),
      loadedTravelSec: round(averageLoadedTravelSec, 3),
      emptyReturnSec: round(averageEmptyReturnSec, 3),
      liftAndLowerSec: round(this.scenario.physicsParams.liftTimeSec + this.scenario.physicsParams.lowerTimeSec, 3),
      averageLoadedDistanceM: round(averageLoadedDistanceM, 3),
      averageEmptyReturnDistanceM: round(averageEmptyReturnDistanceM, 3),
      limitingBound: 'shuttle-cycle',
      bounds: [{
        kind: 'shuttle-cycle',
        pph: round(fleetPph, 3),
        cycleSec: round(averageCycleSec, 3),
        utilizationBasis: `${this.scenario.vehicles.count} shuttle(s)`,
        assumptions: ['legacy inbound-only ideal capacity bound']
      }],
      assumptions: [
        'inbound-only ideal with unlimited lift-side demand',
        'no traffic conflicts, waiting, deadlock recovery, battery, or upstream starvation',
        'average over all storage cells using nearest inbound lift and current speed/lift/lower/90-degree-turn parameters',
        'empty return is modeled from storage cell back to the nearest inbound lift through allowed horizontal storage rows and aisles'
      ]
    };
    theoreticalCapacityBaselineCache.set(cacheKey, this.theoreticalCapacityBaseline);
    return this.theoreticalCapacityBaseline;
  }

  private theoreticalCapacityBaselineCacheKey(): string {
    const layoutHash = createHash('sha256')
      .update(stableJson({
        calibrationProfile: this.scenario.layout.calibrationProfile ?? null,
        nodes: this.scenario.layout.nodes.map((node) => ({
          id: node.id,
          type: node.type,
          liftKind: node.liftKind ?? null,
          x: node.x,
          z: node.z,
          noStop: node.noStop,
          noParking: node.noParking
        })),
        edges: this.scenario.layout.edges.map((edge) => ({
          id: edge.id,
          from: edge.from,
          to: edge.to,
          lengthM: edge.lengthM,
          directionMode: edge.directionMode
        }))
      }))
      .digest('hex');
    return stableJson({
      layoutHash,
      shuttleCount: this.scenario.vehicles.count,
      emptySpeedMps: this.scenario.physicsParams.emptySpeedMps,
      loadedSpeedMps: this.scenario.physicsParams.loadedSpeedMps,
      accelerationMps2: this.scenario.physicsParams.accelerationMps2,
      switchDirectionSec: this.scenario.physicsParams.switchDirectionSec,
      liftTimeSec: this.scenario.physicsParams.liftTimeSec,
      lowerTimeSec: this.scenario.physicsParams.lowerTimeSec
    });
  }

  private calculateTheoreticalCapacity(
    inboundPph: number,
    outboundPph: number,
    vehicleUtilization: Record<string, number>
  ): TheoreticalCapacitySnapshot {
    const baseline = this.calculateTheoreticalCapacityBaseline();
    const utilizationValues = Object.values(vehicleUtilization);
    const averageVehicleUtilizationPct =
      utilizationValues.reduce((sum, value) => sum + value, 0) / Math.max(1, utilizationValues.length) * 100;

    return {
      ...baseline,
      achievedInboundPct: round(baseline.fleetPph > 0 ? (inboundPph / baseline.fleetPph) * 100 : 0, 3),
      achievedOutboundPct: round(baseline.fleetPph > 0 ? (outboundPph / baseline.fleetPph) * 100 : 0, 3),
      achievedTotalPct: round(baseline.fleetPph > 0 ? ((inboundPph + outboundPph) / baseline.fleetPph) * 100 : 0, 3),
      averageVehicleUtilizationPct: round(averageVehicleUtilizationPct, 3)
    };
  }

  private taskAssignmentBlockReason(task: TaskStateRecord): string | null {
    if (task.kind === 'inbound') {
      if (this.inboundTaskHasEarlierPickupTask(task) && !this.topLiftInboundQueueSlotAvailableForTask(task)) {
        return 'inbound-lift-fifo-wait';
      }
      const columnPredecessorBlockReason = this.topLiftInboundColumnPredecessorBlockReason(task);
      if (columnPredecessorBlockReason && !this.topLiftInboundQueueSlotAvailableForTask(task)) {
        return columnPredecessorBlockReason;
      }
      const dropoffLoadId = this.storedLoadIdAtNode(task.dropoffNodeId);
      if (dropoffLoadId && dropoffLoadId !== task.loadId) {
        return 'storage-full';
      }
      const columnModeConflictReason = this.topLiftColumnModeConflictReason(task);
      if (columnModeConflictReason) {
        return columnModeConflictReason;
      }
      const dropoffColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
      if (
        this.topLiftColumnLayoutEnabled() &&
        dropoffColumn !== null &&
        this.topLiftTasklessStorageVehicleBlocksInboundAllocation(dropoffColumn) &&
        !this.topLiftQueuedInboundTaskHasAssignableVehicleInColumn(task)
      ) {
        return `inbound-column-clearing:c${String(dropoffColumn).padStart(2, '0')}`;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        this.isStorageNode(task.dropoffNodeId) &&
        !this.topLiftInboundStorageNodeReachableInColumn(task.dropoffNodeId, this.storageNodeLoadOccupancyForInFlightInboundReachability(task))
      ) {
        return 'storage-full';
      }
    }
    if (task.kind === 'inbound' && this.isInboundOnlyFlow()) {
      return null;
    }
    if (
      task.kind === 'outbound' &&
      this.topLiftColumnLayoutEnabled() &&
      this.outboundTaskHasEarlierDropoffTask(task) &&
      !this.topLiftOutboundQueueSlotAvailableForTask(task)
    ) {
      return 'outbound-lift-queue-full';
    }
    const columnModeConflictReason = this.topLiftColumnModeConflictReason(task);
    if (columnModeConflictReason) {
      return columnModeConflictReason;
    }
    return this.topLiftStationPairBlockReason(task) ??
      this.liftPortBlockReason(task) ??
      this.fifoLaneBlockReason(task) ??
      this.fifoNetworkBlockReason(task);
  }

  private topLiftStationPairBlockReason(task: TaskStateRecord): string | null {
    if (!this.mixedTopLiftFlowEnabled()) {
      return null;
    }
    const pairId = this.topLiftStationPairIdForTask(task);
    if (!pairId) {
      return null;
    }
    const activeCount = this.activeTasks().filter((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === task.kind &&
      (candidate.state === 'assigned' || candidate.state === 'in-progress') &&
      this.topLiftStationPairIdForTask(candidate) === pairId
    ).length;
    return activeCount >= this.topLiftStationPairActiveTaskLimit(task)
      ? `top-lift-station-pair-wip-full:${pairId}`
      : null;
  }

  private topLiftStationPairIdForTask(task: TaskStateRecord): string | null {
    const liftNodeId = this.taskLiftPortNodeId(task);
    return liftNodeId ? /^(lift-\d{2})-(?:inbound|outbound)$/.exec(liftNodeId)?.[1] ?? null : null;
  }

  private topLiftStationPairActiveTaskLimit(task: TaskStateRecord): number {
    const liftNodeId = this.taskLiftPortNodeId(task);
    return liftNodeId
      ? this.topLiftPortStagedTaskCapacity(task.kind, liftNodeId)
      : 2;
  }

  private yieldPocketRank(vehicle: MutableVehicle, nodeId: string): number {
    const node = this.layoutNode(nodeId);
    if (!node) {
      return 99;
    }
    if (this.agentMinimalEnabled()) {
      if (node.type === 'parking') {
        return 0;
      }
      if (node.type === 'storage') {
        return /^left-row-|^right-row-/.test(vehicle.currentNodeId) ? 1 : 4;
      }
      if (node.type === 'aisle') {
        return 2;
      }
      if (node.type === 'intersection') {
        return 3;
      }
      return 10;
    }
    if (node.type === 'storage') {
      return vehicle.loaded ? 50 : 0;
    }
    if (node.type === 'parking') {
      return 1;
    }
    if (node.type === 'aisle') {
      return 2;
    }
    if (node.type === 'intersection') {
      return 3;
    }
    return 10;
  }

  private tryInsertEmptySideAisleRefuge(vehicle: MutableVehicle, blockedTargetNodeId: string): boolean {
    if (vehicle.loaded) {
      return false;
    }
    const currentNode = this.layoutNode(vehicle.currentNodeId);
    if (!currentNode || currentNode.type !== 'intersection' || !/^left-row-|^right-row-/.test(currentNode.id)) {
      return false;
    }
    const previousNodeId = vehicle.routeNodeIds[vehicle.routeIndex - 1];
    if (
      previousNodeId &&
      this.layoutNode(previousNodeId)?.type === 'storage' &&
      vehicle.routeNodeIds[vehicle.routeIndex - 2] === currentNode.id
    ) {
      return false;
    }
    const currentTargetNode = this.layoutNode(blockedTargetNodeId);
    if (currentTargetNode?.type === 'storage') {
      return false;
    }
    const activeRefugeNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 1];
    if (
      activeRefugeNodeId &&
      this.layoutNode(activeRefugeNodeId)?.type === 'storage' &&
      vehicle.routeNodeIds[vehicle.routeIndex + 2] === currentNode.id
    ) {
      return false;
    }
    const refuge = this.neighbors(currentNode.id)
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id))
      .filter((neighbor) => this.layoutNode(neighbor.nodeId)?.type === 'storage')
      .sort((left, right) => left.lengthM - right.lengthM || left.nodeId.localeCompare(right.nodeId))[0];
    if (!refuge || !this.traffic.findEdge(refuge.nodeId, currentNode.id)) {
      return false;
    }
    const nextRoute = [
      ...vehicle.routeNodeIds.slice(0, vehicle.routeIndex + 1),
      refuge.nodeId,
      currentNode.id,
      ...vehicle.routeNodeIds.slice(vehicle.routeIndex + 1)
    ];
    vehicle.routeNodeIds = nextRoute;
    vehicle.targetNodeId = refuge.nodeId;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.state = 'assigned';
    this.replanCount += 1;
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, null, currentNode.id, refuge.nodeId, 'side-aisle-refuge-pocket', this.vehiclePosition(vehicle), {
      blockedTargetNodeId,
      route: nextRoute.join('>')
    });
    return true;
  }

  private storageRefugeExitBlock(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    fromNodeId: string,
    toNodeId: string,
    exitEdge: LayoutEdge
  ): { reason: string; blockingReservationId: string | null; blockingVehicleId: string | null } | null {
    if (vehicle.loaded) {
      return null;
    }
    const fromNode = this.layoutNode(fromNodeId);
    const toNode = this.layoutNode(toNodeId);
    if (fromNode?.type === 'storage' && toNode?.type === 'storage' && vehicle.routeIndex > 0) {
      let sideRowExitNodeId: string | null = null;
      let sideRowExitIndex = -1;
      for (let index = vehicle.routeIndex + 2; index < vehicle.routeNodeIds.length; index += 1) {
        const candidateNodeId = vehicle.routeNodeIds[index]!;
        const candidateNode = this.layoutNode(candidateNodeId);
        if (candidateNode?.type === 'storage') {
          continue;
        }
        if (candidateNode?.type === 'intersection' && /^left-row-|^right-row-/.test(candidateNode.id)) {
          sideRowExitNodeId = candidateNode.id;
          sideRowExitIndex = index;
        }
        break;
      }
      if (!sideRowExitNodeId) {
        return null;
      }
      const fromStoragePosition = this.storageGridPosition(fromNodeId);
      const toStoragePosition = this.storageGridPosition(toNodeId);
      if (fromStoragePosition && toStoragePosition) {
        const movingTowardSideExit = sideRowExitNodeId.startsWith('left-row-')
          ? toStoragePosition.column < fromStoragePosition.column
          : toStoragePosition.column > fromStoragePosition.column;
        if (!movingTowardSideExit) {
          return null;
        }
      }

      const sideRowClaimId = this.nodeClaimedByOtherVehicle(sideRowExitNodeId, vehicle.id);
      if (sideRowClaimId) {
        return { reason: 'refuge-exit-blocked', blockingReservationId: null, blockingVehicleId: sideRowClaimId };
      }
      const continuationNodeId = vehicle.routeNodeIds[sideRowExitIndex + 1];
      if (continuationNodeId && this.layoutNode(continuationNodeId)?.type !== 'storage') {
        const continuationClaimId = this.nodeClaimedByOtherVehicle(continuationNodeId, vehicle.id);
        if (continuationClaimId) {
          return { reason: 'refuge-exit-blocked', blockingReservationId: null, blockingVehicleId: continuationClaimId };
        }
      }
      return null;
    }

    if (
      fromNode?.type !== 'storage' ||
      toNode?.type !== 'intersection' ||
      !/^left-row-|^right-row-/.test(toNode.id) ||
      vehicle.routeNodeIds[vehicle.routeIndex - 1] !== toNodeId
    ) {
      return null;
    }

    const continuationNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 2];
    if (!continuationNodeId || this.layoutNode(continuationNodeId)?.type === 'storage') {
      return null;
    }

    const sideRowClaimId = this.nodeClaimedByOtherVehicle(toNodeId, vehicle.id);
    if (sideRowClaimId) {
      return { reason: 'node-occupied', blockingReservationId: null, blockingVehicleId: sideRowClaimId };
    }

    const continuationClaimId = this.nodeClaimedByOtherVehicle(continuationNodeId, vehicle.id);
    if (continuationClaimId) {
      return { reason: 'refuge-exit-blocked', blockingReservationId: null, blockingVehicleId: continuationClaimId };
    }

    const continuationEdge = this.traffic.findEdge(toNodeId, continuationNodeId);
    if (!continuationEdge) {
      return { reason: 'route-edge-missing', blockingReservationId: null, blockingVehicleId: null };
    }

    const exitMotionMode = this.routeLegMotionMode(vehicle, exitEdge, toNodeId, vehicle.routeIndex, task);
    const exitTravelSec = this.routeLegTravelSec(vehicle, exitEdge, toNodeId, vehicle.routeIndex, exitMotionMode);
    const continuationMotionMode = this.routeLegMotionMode(vehicle, continuationEdge, continuationNodeId, vehicle.routeIndex + 1, task);
    const continuationTravelSec = this.routeLegTravelSec(vehicle, continuationEdge, continuationNodeId, vehicle.routeIndex + 1, continuationMotionMode);
    const attempt = this.traffic.reserveMove({
      vehicleId: vehicle.id,
      taskId: vehicle.taskId,
      fromNodeId: toNodeId,
      toNodeId: continuationNodeId,
      startTimeSec: this.simTimeSec + exitTravelSec,
      travelSec: continuationTravelSec,
      priority: this.priorityFor(vehicle),
      existing: this.reservations,
      ignoreConflicts: !this.collisionAvoidanceEnabled()
    });
    if (!attempt.ok) {
      return {
        reason: attempt.reasonCode === 'route-edge-missing' ? attempt.reasonCode : 'refuge-exit-blocked',
        blockingReservationId: attempt.blockingReservationId,
        blockingVehicleId: this.blockingVehicleForReservation(attempt.blockingReservationId)
      };
    }

    return null;
  }

  private deeperStorageRefugeNodeId(vehicle: MutableVehicle, blockedTargetNodeId: string): string | null {
    if (vehicle.loaded || !this.isStorageNode(vehicle.currentNodeId)) {
      return null;
    }
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    if (!currentPosition) {
      return null;
    }

    const previousNodeId = vehicle.routeNodeIds[vehicle.routeIndex - 1];
    const enteredFromSideAisle = Boolean(previousNodeId && /^left-row-|^right-row-/.test(previousNodeId));
    const currentCellClaimedByOther = this.nodeClaimedByOtherVehicle(vehicle.currentNodeId, vehicle.id) !== null;
    const blockedPosition = this.storageGridPosition(blockedTargetNodeId);
    const blockedTargetClaimId = this.nodeClaimedByOtherVehicle(blockedTargetNodeId, vehicle.id);
    const blockedTargetClaimant = blockedTargetClaimId
      ? this.vehicles.find((candidate) => candidate.id === blockedTargetClaimId) ?? null
      : null;
    const loadedVehicleNeedsBlockedStorageCell = Boolean(
      blockedPosition &&
      blockedPosition.row === currentPosition.row &&
      blockedTargetClaimant?.loaded
    );
    const sideRowExitNodeId = this.storageRowSideExitNodeIdForRoute(vehicle);
    const sideRowExitClaimId = sideRowExitNodeId ? this.nodeClaimedByOtherVehicle(sideRowExitNodeId, vehicle.id) : null;
    const sideRowExitClaimant = sideRowExitClaimId
      ? this.vehicles.find((candidate) => candidate.id === sideRowExitClaimId) ?? null
      : null;
    const loadedVehicleBlocksSameRowExit = Boolean(
      sideRowExitNodeId &&
      this.storageSideRowMatchesStorageRow(sideRowExitNodeId, currentPosition.row) &&
      sideRowExitClaimant?.loaded
    );
    if (
      !enteredFromSideAisle &&
      !currentCellClaimedByOther &&
      !loadedVehicleNeedsBlockedStorageCell &&
      !loadedVehicleBlocksSameRowExit
    ) {
      return null;
    }

    let deeperColumn: number | null = null;
    if (blockedPosition && blockedPosition.row === currentPosition.row) {
      deeperColumn = blockedPosition.column < currentPosition.column
        ? currentPosition.column + 1
        : currentPosition.column - 1;
    } else if (blockedTargetNodeId.startsWith('left-row-')) {
      deeperColumn = currentPosition.column + 1;
    } else if (blockedTargetNodeId.startsWith('right-row-')) {
      deeperColumn = currentPosition.column - 1;
    } else {
      if (previousNodeId?.startsWith('left-row-')) {
        deeperColumn = currentPosition.column + 1;
      } else if (previousNodeId?.startsWith('right-row-')) {
        deeperColumn = currentPosition.column - 1;
      }
    }
    if (deeperColumn === null || deeperColumn < 1) {
      return null;
    }

    const candidateNodeId = storageNodeId(currentPosition.row - 1, deeperColumn - 1);
    if (!this.isStorageNode(candidateNodeId) || !this.traffic.findEdge(vehicle.currentNodeId, candidateNodeId)) {
      return null;
    }
    if (this.storedLoadIdAtNode(candidateNodeId)) {
      return null;
    }
    return this.nodeClaimedByOtherVehicle(candidateNodeId, vehicle.id) ? null : candidateNodeId;
  }

  private storageRowSideExitNodeIdForRoute(vehicle: MutableVehicle): string | null {
    for (let index = vehicle.routeIndex + 1; index < vehicle.routeNodeIds.length; index += 1) {
      const nodeId = vehicle.routeNodeIds[index]!;
      const node = this.layoutNode(nodeId);
      if (node?.type === 'storage') {
        continue;
      }
      return node?.type === 'intersection' && /^left-row-|^right-row-/.test(node.id) ? node.id : null;
    }
    return null;
  }

  private storageSideRowMatchesStorageRow(sideRowNodeId: string, storageRow: number): boolean {
    const match = /^(?:left|right)-row-(\d+)$/.exec(sideRowNodeId);
    return match ? Number(match[1]) === storageRow : false;
  }

  private tryMoveDeeperIntoStorageRefuge(vehicle: MutableVehicle, blockedTargetNodeId: string): boolean {
    const deeperNodeId = this.deeperStorageRefugeNodeId(vehicle, blockedTargetNodeId);
    if (!deeperNodeId) {
      return false;
    }

    const nextRoute = [
      ...vehicle.routeNodeIds.slice(0, vehicle.routeIndex + 1),
      deeperNodeId,
      vehicle.currentNodeId,
      ...vehicle.routeNodeIds.slice(vehicle.routeIndex + 1)
    ];
    vehicle.routeNodeIds = nextRoute;
    vehicle.targetNodeId = deeperNodeId;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.state = 'assigned';
    this.replanCount += 1;
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, null, vehicle.currentNodeId, deeperNodeId, 'storage-refuge-deeper-pocket', this.vehiclePosition(vehicle), {
      blockedTargetNodeId,
      route: nextRoute.join('>')
    });
    return true;
  }

  private liftPortBlockReason(task: TaskStateRecord): string | null {
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return null;
    }
    if (this.topLiftColumnLayoutEnabled() && this.topLiftPortQueueCapacity(liftNodeId) > 0) {
      return null;
    }
    const approachCount = this.liftPortApproachCount(task.kind, liftNodeId);
    return approachCount >= this.effectiveLiftPortApproachCapacity(task.kind) ? `${task.kind}-lift-approach-full:${liftNodeId}` : null;
  }

  private liftPortWaitReason(nodeId: string): string | null {
    const kind = this.liftPortKindForNodeId(nodeId);
    return kind ? `${kind}-lift-busy:${nodeId}` : null;
  }

  private reservationIsActive(reservation: Reservation): boolean {
    return reservation.startTimeSec <= this.simTimeSec + 1e-6 && this.simTimeSec <= reservation.endTimeSec + 1e-6;
  }

  private reservationWindowsOverlap(left: Reservation, right: Reservation): boolean {
    return left.startTimeSec <= right.endTimeSec + 1e-6 && right.startTimeSec <= left.endTimeSec + 1e-6;
  }

  private reservationsShareBlockingResource(left: Reservation, right: Reservation): boolean {
    const sameResource = left.resourceType === right.resourceType && left.resourceId === right.resourceId;
    const sameZoneConflictGroup =
      left.resourceType === 'zone' &&
      right.resourceType === 'zone' &&
      left.conflictGroup !== null &&
      right.conflictGroup !== null &&
      left.conflictGroup === right.conflictGroup;
    return sameResource || sameZoneConflictGroup;
  }

  private reservationsShareExactResource(left: Reservation, right: Reservation): boolean {
    return left.resourceType === right.resourceType && left.resourceId === right.resourceId;
  }

  private mergeSelfReservationWindows(existing: Reservation, candidate: Reservation): Reservation {
    const mergedStartTimeSec = Math.min(existing.startTimeSec, candidate.startTimeSec);
    const retainedPastSec = Math.max(
      this.scenario.timeStepSec,
      this.scenario.trafficPolicy.minimumClearanceSec
    ) + 1e-6;
    const startTimeSec = mergedStartTimeSec < this.simTimeSec - retainedPastSec
      ? Math.max(this.simTimeSec - retainedPastSec, Math.min(existing.endTimeSec, candidate.startTimeSec))
      : mergedStartTimeSec;
    return ReservationSchema.parse({
      ...existing,
      taskId: existing.taskId ?? candidate.taskId,
      startTimeSec,
      endTimeSec: Math.max(existing.endTimeSec, candidate.endTimeSec),
      priority: Math.max(existing.priority, candidate.priority)
    });
  }

  private installMoveReservationsReplacingSelfOverlap(
    vehicle: MutableVehicle,
    reservations: Reservation[]
  ): MoveReservationInstall {
    if (reservations.length === 0) {
      return { installed: [], removed: [] };
    }

    const removed: Array<{ index: number; reservation: Reservation }> = [];
    const acceptedReservations: Reservation[] = [];
    for (const reservation of reservations) {
      let mergedReservation = reservation;
      for (let index = acceptedReservations.length - 1; index >= 0; index -= 1) {
        const existing = acceptedReservations[index]!;
        if (
          this.reservationsShareExactResource(existing, mergedReservation) &&
          this.reservationWindowsOverlap(existing, mergedReservation)
        ) {
          acceptedReservations.splice(index, 1);
          mergedReservation = this.mergeSelfReservationWindows(existing, mergedReservation);
        }
      }
      this.reservations = this.reservations.filter((existing, index) => {
        const merge =
          existing.vehicleId === vehicle.id &&
          this.reservationsShareExactResource(existing, mergedReservation) &&
          this.reservationWindowsOverlap(existing, mergedReservation);
        if (merge) {
          removed.push({ index, reservation: existing });
          mergedReservation = this.mergeSelfReservationWindows(existing, mergedReservation);
        }
        return !merge;
      });
      acceptedReservations.push(mergedReservation);
    }
    this.reservations.push(...acceptedReservations);
    return { installed: acceptedReservations, removed };
  }

  private rollbackMoveReservationInstall(
    installed: Reservation[],
    removed: Array<{ index: number; reservation: Reservation }>
  ): void {
    if (installed.length === 0 && removed.length === 0) {
      return;
    }

    const addedIds = new Set(installed.map((reservation) => reservation.id));
    const restored = this.reservations.filter((reservation) => !addedIds.has(reservation.id));
    for (const { index, reservation } of removed.sort((left, right) => left.index - right.index)) {
      restored.splice(Math.min(index, restored.length), 0, reservation);
    }
    this.reservations = restored;
  }

  private hasActiveSelfMoveAuthorization(
    vehicle: MutableVehicle,
    edgeId: string,
    targetNodeId: string,
    requiredEndTimeSec: number
  ): boolean {
    return this.hasSelfMoveAuthorizationAt(vehicle, edgeId, targetNodeId, this.simTimeSec, requiredEndTimeSec);
  }

  private hasSelfMoveAuthorizationAt(
    vehicle: MutableVehicle,
    edgeId: string,
    targetNodeId: string,
    authorizationStartTimeSec: number,
    requiredEndTimeSec: number,
    endToleranceSec = 1e-6
  ): boolean {
    const hasEdgeReservation = this.reservations.some((reservation) =>
      reservation.vehicleId === vehicle.id &&
      reservation.resourceType === 'edge' &&
      reservation.resourceId === edgeId &&
      reservation.startTimeSec <= authorizationStartTimeSec + 1e-6 &&
      authorizationStartTimeSec <= reservation.endTimeSec + 1e-6 &&
      reservation.endTimeSec >= requiredEndTimeSec - endToleranceSec
    );
    const hasNodeReservation = this.reservations.some((reservation) =>
      reservation.vehicleId === vehicle.id &&
      reservation.resourceType === 'node' &&
      reservation.resourceId === targetNodeId &&
      reservation.startTimeSec <= authorizationStartTimeSec + 1e-6 &&
      authorizationStartTimeSec <= reservation.endTimeSec + 1e-6 &&
      reservation.endTimeSec >= requiredEndTimeSec - endToleranceSec
    );
    return hasEdgeReservation && hasNodeReservation;
  }

  private fifoLaneBlockReason(task: TaskStateRecord): string | null {
    const rowLabel = this.taskStorageRowLabel(task);
    if (!rowLabel) {
      return null;
    }
    const taskColumn = this.taskStorageColumn(task);
    if (taskColumn !== null) {
      const hasUnfinishedPredecessor = this.activeTasks().some((candidate) =>
        candidate.id !== task.id &&
        candidate.kind === task.kind &&
        this.taskStorageRowLabel(candidate) === rowLabel &&
        (this.taskStorageColumn(candidate) ?? Number.POSITIVE_INFINITY) < taskColumn
      );
      if (hasUnfinishedPredecessor) {
        return `fifo-predecessor-pending:${rowLabel}`;
      }
      if (this.topLiftColumnLayoutEnabled()) {
        const activeSameColumnSameKindCount = this.activeTasks().filter((candidate) =>
          candidate.id !== task.id &&
          candidate.kind === task.kind &&
          (candidate.state === 'assigned' || candidate.state === 'in-progress') &&
          this.taskStorageColumn(candidate) === taskColumn
        ).length;
        if (activeSameColumnSameKindCount < this.topLiftSkuColumnActiveTaskLimit(task.kind)) {
          return null;
        }
      }
    }
    const hasActiveSameLaneTask = this.activeTasks().some((candidate) =>
      candidate.id !== task.id &&
      (candidate.state === 'assigned' || candidate.state === 'in-progress') &&
      this.taskStorageRowLabel(candidate) === rowLabel
    );
    return hasActiveSameLaneTask ? `fifo-lane-busy:${rowLabel}` : null;
  }

  private fifoNetworkBlockReason(task: TaskStateRecord): string | null {
    if (task.kind !== 'outbound') {
      return null;
    }
    if (this.mixedTopLiftFlowEnabled()) {
      return null;
    }
    const hasActiveOutboundFifoTask = this.activeTasks().some((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'outbound' &&
      (candidate.state === 'assigned' || candidate.state === 'in-progress')
    );
    return hasActiveOutboundFifoTask ? 'fifo-left-network-busy' : null;
  }

  private topLiftInboundColumnPredecessorBlockReason(task: TaskStateRecord): string | null {
    const position = this.topLiftInboundColumnPredecessorPosition(task);
    return position && this.topLiftInboundColumnPredecessorPending(task)
      ? `inbound-column-predecessor-pending:c${String(position.column).padStart(2, '0')}`
      : null;
  }

  private topLiftInboundQueueSlotAvailableForTask(task: TaskStateRecord): boolean {
    const queueNodeId = this.topLiftInboundQueueNodeIdForTask(task);
    if (!queueNodeId) {
      return false;
    }
    const taskVehicleId = task.vehicleId ?? null;
    const exitingPredecessorVehicleId = this.inboundQueueExitingPredecessorVehicleId(task, queueNodeId, null);
    const occupantId = this.currentNodeOccupancy.get(queueNodeId);
    if (occupantId && occupantId !== taskVehicleId && occupantId !== exitingPredecessorVehicleId) {
      return false;
    }
    return !this.vehicles.some((vehicle) =>
      vehicle.id !== taskVehicleId &&
      vehicle.id !== exitingPredecessorVehicleId &&
      (
        vehicle.currentNodeId === queueNodeId ||
        vehicle.targetNodeId === queueNodeId ||
        (
          vehicle.plannedGoalNodeId === queueNodeId &&
          !this.tasklessInboundQueueStandbySoftClaim(vehicle, queueNodeId)
        )
      )
    );
  }

  private topLiftOutboundQueueSlotAvailableForTask(task: TaskStateRecord): boolean {
    const queueNodeId = this.topLiftOutboundQueueNodeIdForTask(task);
    if (!queueNodeId) {
      return false;
    }
    const taskVehicleId = task.vehicleId ?? null;
    const occupantId = this.currentNodeOccupancy.get(queueNodeId);
    if (occupantId && occupantId !== taskVehicleId) {
      return false;
    }
    return !this.vehicles.some((vehicle) =>
      vehicle.id !== taskVehicleId &&
      (vehicle.currentNodeId === queueNodeId || vehicle.targetNodeId === queueNodeId || vehicle.plannedGoalNodeId === queueNodeId)
    );
  }

  private topLiftInboundColumnPredecessorPending(task: TaskStateRecord): boolean {
    return this.topLiftInboundColumnPredecessorTasks(task).length > 0;
  }

  private topLiftInboundImmediateColumnPredecessorTask(task: TaskStateRecord): TaskStateRecord | null {
    const position = this.topLiftInboundColumnPredecessorPosition(task);
    if (!position) {
      return null;
    }
    const columnNodeIds = this.topLiftStorageColumnNodeIds(position.column);
    const targetIndex = columnNodeIds.indexOf(task.dropoffNodeId);
    if (targetIndex <= 0) {
      return null;
    }
    const predecessorNodeId = columnNodeIds[targetIndex - 1]!;
    return this.activeTasks().find((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'inbound' &&
      candidate.dropoffNodeId === predecessorNodeId
    ) ?? null;
  }

  private topLiftInboundColumnPredecessorQueueReleaseAllowed(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    if (!this.topLiftInboundQueueSlotAvailableForTask(task)) {
      return false;
    }
    const predecessor = this.topLiftInboundImmediateColumnPredecessorTask(task);
    if (!predecessor) {
      return false;
    }
    const vehicle = predecessor.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === predecessor.vehicleId) ?? null
      : null;
    if (!vehicle) {
      return false;
    }
    return this.inboundTaskPickupReleased(predecessor) ||
      !this.topLiftInboundColumnPredecessorPending(predecessor);
  }

  private topLiftInboundColumnPredecessorStagingAllowed(task: TaskStateRecord): boolean {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    if (!this.topLiftInboundQueueSlotAvailableForTask(task)) {
      return false;
    }
    if (this.topLiftInboundUsesProjectedQueue(task)) {
      return true;
    }
    return this.topLiftInboundColumnPredecessorQueueReleaseAllowed(task);
  }

  private topLiftInboundColumnPredecessorPosition(task: TaskStateRecord): { row: number; column: number } | null {
    if (task.kind !== 'inbound' || !this.topLiftColumnLayoutEnabled() || !this.isStorageNode(task.dropoffNodeId)) {
      return null;
    }
    const position = this.storageGridPosition(task.dropoffNodeId);
    if (!position) {
      return null;
    }
    return position;
  }

  private taskStorageRowLabel(task: TaskStateRecord): string | null {
    const storageNodeId = task.kind === 'inbound' ? task.dropoffNodeId : task.pickupNodeId;
    return this.nodeStorageRowLabel(storageNodeId);
  }

  private taskStorageColumn(task: TaskStateRecord): number | null {
    const storageNodeId = task.kind === 'inbound' ? task.dropoffNodeId : task.pickupNodeId;
    return this.storageGridPosition(storageNodeId)?.column ?? null;
  }

  private activeTopLiftTaskColumn(kind: 'inbound' | 'outbound'): number | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const activeTasks = this.tasks
      .filter((task) => task.kind === kind && task.state !== 'completed' && task.state !== 'failed')
      .map((task) => ({
        task,
        column: this.taskStorageColumn(task)
      }))
      .filter((entry): entry is { task: TaskStateRecord; column: number } => entry.column !== null)
      .sort((left, right) =>
        left.task.createdAtSec - right.task.createdAtSec ||
        left.task.id.localeCompare(right.task.id)
      );
    return activeTasks[0]?.column ?? null;
  }

  private activeTopLiftTaskCountInColumn(kind: 'inbound' | 'outbound', column: number): number {
    return this.activeTasks().filter((task) =>
      task.kind === kind &&
      this.taskStorageColumn(task) === column
    ).length;
  }

  private activeTopLiftTaskColumnForLift(kind: 'inbound' | 'outbound', liftNodeId: string): number | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const activeTasks = this.activeTasks()
      .filter((task) =>
        task.kind === kind &&
        this.taskLiftPortNodeId(task) === liftNodeId
      )
      .map((task) => ({
        task,
        column: this.taskStorageColumn(task)
      }))
      .filter((entry): entry is { task: TaskStateRecord; column: number } => entry.column !== null)
      .sort((left, right) =>
        left.task.createdAtSec - right.task.createdAtSec ||
        left.task.id.localeCompare(right.task.id)
      );
    return activeTasks[0]?.column ?? null;
  }

  private activeTopLiftTaskCountInColumnForLift(kind: 'inbound' | 'outbound', column: number, liftNodeId: string): number {
    return this.activeTasks().filter((task) =>
      task.kind === kind &&
      this.taskStorageColumn(task) === column &&
      this.taskLiftPortNodeId(task) === liftNodeId
    ).length;
  }

  private topLiftSkuColumnActiveTaskLimit(kind: 'inbound' | 'outbound'): number {
    if (kind === 'inbound' && this.topLiftColumnLayoutEnabled()) {
      return 3;
    }
    if (kind === 'outbound' && this.topLiftColumnLayoutEnabled()) {
      return 1;
    }
    return 2;
  }
  private refreshTopLiftColumnFlowModes(): void {
    if (!this.mixedTopLiftFlowEnabled()) {
      this.topLiftColumnFlowModes.clear();
      return;
    }

    const storedOccupancy = this.storageNodeLoadOccupancy(false);
    for (const column of this.topLiftStorageColumnNumbers()) {
      const nodeIds = this.topLiftStorageColumnNodeIds(column);
      const mode = this.topLiftColumnFlowModes.get(column);
      const hasSeedLoad = this.topLiftColumnHasSeedOutboundLoad(nodeIds, storedOccupancy);
      const hasActiveOutbound = this.activeTopLiftTaskCountInColumn('outbound', column) > 0;
      const hasActiveInbound = this.activeTopLiftTaskCountInColumn('inbound', column) > 0;
      const full = this.topLiftColumnIsPhysicallyFull(nodeIds, storedOccupancy);
      const empty = this.topLiftColumnIsPhysicallyEmpty(nodeIds, storedOccupancy);
      const hasReachableInboundSlot = this.topLiftColumnHasReachableInboundSlot(nodeIds, storedOccupancy);

      if (hasSeedLoad || hasActiveOutbound) {
        this.topLiftColumnFlowModes.set(column, 'outbound');
        continue;
      }
      if ((mode === 'outbound' || hasActiveInbound) && empty && !hasActiveOutbound) {
        this.topLiftColumnFlowModes.set(column, 'inbound');
        continue;
      }
      if ((mode === undefined || mode === 'inbound') && full && !hasActiveInbound) {
        this.topLiftColumnFlowModes.set(column, 'outbound');
        continue;
      }
      if ((mode === undefined || mode === 'inbound') && !empty && !full && !hasActiveInbound && !hasReachableInboundSlot) {
        this.topLiftColumnFlowModes.set(column, 'outbound');
        continue;
      }
      if (mode === undefined) {
        this.topLiftColumnFlowModes.set(column, 'inbound');
      }
    }
  }

  private rebuildTopLiftColumnFlowModesFromState(): void {
    this.topLiftColumnFlowModes = new Map();
    if (!this.mixedTopLiftFlowEnabled()) {
      return;
    }
    this.refreshTopLiftColumnFlowModes();
  }

  private topLiftColumnHasSeedOutboundLoad(nodeIds: string[], storedOccupancy: Map<string, string>): boolean {
    return nodeIds.some((nodeId) =>
      (storedOccupancy.get(nodeId) ?? '').startsWith(OUTBOUND_SEED_LOAD_PREFIX)
    );
  }

  private topLiftColumnIsPhysicallyFull(nodeIds: string[], storedOccupancy: Map<string, string>): boolean {
    return nodeIds.length > 0 && nodeIds.every((nodeId) => storedOccupancy.has(nodeId));
  }

  private topLiftColumnIsPhysicallyEmpty(nodeIds: string[], storedOccupancy: Map<string, string>): boolean {
    return nodeIds.every((nodeId) => !storedOccupancy.has(nodeId));
  }

  private topLiftColumnHasReachableInboundSlot(nodeIds: string[], occupancy: Map<string, string>): boolean {
    return nodeIds.some((nodeId) =>
      !occupancy.has(nodeId) &&
      !this.currentNodeOccupancy.has(nodeId) &&
      this.topLiftInboundStorageNodeReachableInColumn(nodeId, occupancy)
    );
  }

  private topLiftStorageColumnNumbers(): number[] {
    if (this.topLiftStorageColumnNumbersCache) {
      return this.topLiftStorageColumnNumbersCache;
    }
    const columns = new Set<number>();
    for (const node of this.scenario.layout.nodes) {
      if (node.type !== 'storage') {
        continue;
      }
      const position = this.storageGridPosition(node.id);
      if (position) {
        columns.add(position.column);
      }
    }
    this.topLiftStorageColumnNumbersCache = [...columns].sort((left, right) => left - right);
    return this.topLiftStorageColumnNumbersCache;
  }

  private topLiftStorageColumnNumbersForLift(liftNodeId: string): number[] {
    const columns = this.topLiftStorageColumnNumbers();
    const liftNode = this.layoutNode(liftNodeId);
    const liftKind = liftNode ? liftKindForNode(liftNode) : null;
    const liftNodes = this.scenario.layout.nodes
      .filter((node) => liftKindForNode(node) === (liftKind ?? 'inbound'))
      .sort((left, right) => left.x - right.x || left.id.localeCompare(right.id));
    const liftIndex = liftNodes.findIndex((liftNode) => liftNode.id === liftNodeId);
    if (liftIndex < 0 || liftNodes.length === 0) {
      return columns;
    }
    const startIndex = Math.floor((liftIndex * columns.length) / liftNodes.length);
    const endIndex = Math.floor(((liftIndex + 1) * columns.length) / liftNodes.length);
    return columns.slice(startIndex, endIndex);
  }

  private topLiftStorageColumnNodeIds(column: number): string[] {
    const cached = this.topLiftStorageColumnNodeIdsCache.get(column);
    if (cached) {
      return cached;
    }
    const nodeIds = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .map((node) => ({ nodeId: node.id, position: this.storageGridPosition(node.id) }))
      .filter((entry): entry is { nodeId: string; position: { row: number; column: number } } =>
        entry.position !== null && entry.position.column === column
      )
      .sort((left, right) =>
        right.position.row - left.position.row ||
        left.nodeId.localeCompare(right.nodeId)
      )
      .map((entry) => entry.nodeId);
    this.topLiftStorageColumnNodeIdsCache.set(column, nodeIds);
    return nodeIds;
  }

  private topLiftInitialSkuParkingBlockedColumns(): Set<number> {
    if (!this.topLiftColumnLayoutEnabled()) {
      return new Set();
    }
    const columns = this.topLiftStorageColumnNumbers();
    const firstColumn = columns[0];
    if (firstColumn === undefined) {
      return new Set();
    }
    return new Set(columns.filter((column) => column === firstColumn || column === firstColumn + 1));
  }

  private storageGridPosition(nodeId: string): { row: number; column: number } | null {
    if (this.storageGridPositionCache.has(nodeId)) {
      return this.storageGridPositionCache.get(nodeId) ?? null;
    }
    const match = /^storage-r(\d+)-c(\d+)$/.exec(nodeId);
    const position = match ? { row: Number(match[1]), column: Number(match[2]) } : null;
    this.storageGridPositionCache.set(nodeId, position);
    return position;
  }

  private nodeStorageRowLabel(nodeId: string): string | null {
    const storagePosition = this.storageGridPosition(nodeId);
    if (storagePosition) {
      if (this.topLiftColumnLayoutEnabled()) {
        const bank = storagePosition.row <= this.topLiftColumnRowsPerZone() ? 1 : 2;
        return `b${String(bank).padStart(2, '0')}-c${String(storagePosition.column).padStart(2, '0')}`;
      }
      return `r${String(storagePosition.row).padStart(2, '0')}`;
    }
    if (this.topLiftColumnLayoutEnabled()) {
      const accessMatch = /^column-(?:top-a|top-b|middle|bottom-a|bottom-b)-c(\d+)$/.exec(nodeId);
      if (accessMatch) {
        return `c${accessMatch[1]}`;
      }
    }
    const sideMatch = /^(?:left|right)-row-(\d+)$/.exec(nodeId);
    if (sideMatch) {
      return `r${sideMatch[1]}`;
    }
    return null;
  }

  private topLiftColumnKey(nodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const storagePosition = this.storageGridPosition(nodeId);
    if (storagePosition) {
      return `c${String(storagePosition.column).padStart(2, '0')}`;
    }
    const accessMatch = /^column-(?:top-a|top-b|middle|bottom-a|bottom-b)-c(\d+)$/.exec(nodeId);
    if (accessMatch) {
      return `c${String(Number(accessMatch[1])).padStart(2, '0')}`;
    }
    return null;
  }

  private topLiftTasklessStorageVehicleInColumn(column: number): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    return this.vehicles.some((vehicle) => {
      if (vehicle.loaded || vehicle.taskId) {
        return false;
      }
      const position = this.storageGridPosition(vehicle.currentNodeId);
      return position?.column === column;
    });
  }

  private topLiftTasklessStorageVehicleBlocksInboundAllocation(column: number): boolean {
    if (!this.topLiftTasklessStorageVehicleInColumn(column)) {
      return false;
    }
    return !this.mixedTopLiftStorageResourceReuseEnabled();
  }

  private topLiftQueuedInboundTaskHasAssignableVehicleInColumn(task: TaskStateRecord): boolean {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound') {
      return false;
    }
    const taskColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
    if (taskColumn === null) {
      return false;
    }
    return this.vehicles.some((vehicle) => {
      if (!this.canAcceptQueuedTask(vehicle)) {
        return false;
      }
      const vehicleColumn = this.storageGridPosition(vehicle.currentNodeId)?.column ?? null;
      if (vehicleColumn !== taskColumn) {
        return false;
      }
      try {
        return this.taskAssignmentRoute(vehicle, task).length > 1;
      } catch {
        return false;
      }
    });
  }

  private topLiftTasklessVehicleBlocksInboundColumn(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId || !this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    const position = this.storageGridPosition(vehicle.currentNodeId);
    if (!position) {
      return false;
    }
    return this.activeTasks().some((task) =>
      task.kind === 'inbound' &&
      this.storageGridPosition(task.dropoffNodeId)?.column === position.column
    );
  }

  private topLiftTasklessVehicleBlocksActiveRoute(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId || !this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    const blockedNodeId = vehicle.currentNodeId;
    return this.vehicles.some((other) => {
      if (other.id === vehicle.id || other.state === 'idle' || other.state === 'parking') {
        return false;
      }
      if (other.currentNodeId === blockedNodeId || other.blockingVehicleId === vehicle.id) {
        return true;
      }
      if (!this.vehicleFutureClaimsEnabled(other)) {
        return false;
      }
      if (other.targetNodeId === blockedNodeId) {
        return true;
      }
      return (
        this.vehicleRouteTail(other, other.routeNodeIds).includes(blockedNodeId) ||
        this.vehicleRouteTail(other, other.plannedRouteNodeIds).includes(blockedNodeId) ||
        this.vehicleRouteTail(other, other.localRouteNodeIds).includes(blockedNodeId)
      );
    });
  }

  private topLiftQueuedInboundTaskMatchesVehicleColumn(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId || !this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    const position = this.storageGridPosition(vehicle.currentNodeId);
    if (!position) {
      return false;
    }
    return this.queuedTasks().some((task) =>
      task.kind === 'inbound' &&
      this.storageGridPosition(task.dropoffNodeId)?.column === position.column
    );
  }

  private tryYieldEmptyBottomBDockCorridorBlockerForLoadedOutbound(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      this.taskForVehicle(requester)?.kind !== 'outbound' ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'bottom-b')
    ) {
      return false;
    }

    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind === 'inbound' && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }

    const requesterClaim = this.topLiftOutboundDockCorridorClaim(requester.currentNodeId, blockedTargetNodeId);
    const blockerClaim = this.topLiftOutboundDockCorridorClaim(
      blocker.currentNodeId,
      blocker.targetNodeId ?? blocker.plannedGoalNodeId
    );
    if (
      !requesterClaim ||
      !blockerClaim ||
      requesterClaim.liftNodeId !== blockerClaim.liftNodeId ||
      !requesterClaim.bottomCorridor ||
      !blockerClaim.bottomCorridor
    ) {
      return false;
    }

    const currentNodeId = blocker.currentNodeId;
    const forbiddenNodeIds = new Set<string>([
      blockedTargetNodeId,
      requester.currentNodeId,
      requester.targetNodeId ?? '',
      requester.plannedGoalNodeId ?? ''
    ]);
    const currentNode = this.layoutNode(currentNodeId);
    const blockedNode = this.layoutNode(blockedTargetNodeId);

    const candidate = this.neighbors(currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'bottom-b'))
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(neighbor.nodeId) !== requesterClaim.liftNodeId)
      .filter((neighbor) => {
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        return (!occupantId || occupantId === blocker.id) &&
          !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id) &&
          !this.movingVehicleTargetingNode(neighbor.nodeId, blocker.id) &&
          !this.movingVehicleClearingNode(neighbor.nodeId, blocker);
      })
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, currentNodeId, neighbor.nodeId))
      .filter((neighbor) => {
        const route = [currentNodeId, neighbor.nodeId];
        return this.agentRefreshLocalRouteNodesClear(blocker, route) &&
          !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route) &&
          !this.agentRefreshMoveBlocker(blocker, neighbor.nodeId, route);
      })
      .sort((left, right) => {
        const leftNode = this.layoutNode(left.nodeId);
        const rightNode = this.layoutNode(right.nodeId);
        const leftDockDistance = currentNode && blockedNode && leftNode
          ? Math.abs(leftNode.x - blockedNode.x) + Math.abs(leftNode.z - blockedNode.z)
          : 0;
        const rightDockDistance = currentNode && blockedNode && rightNode
          ? Math.abs(rightNode.x - blockedNode.x) + Math.abs(rightNode.z - blockedNode.z)
          : 0;
        return rightDockDistance - leftDockDistance ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0] ?? null;

    if (!candidate) {
      return false;
    }

    return this.installAgentRefreshSideYieldRoute(
      blocker,
      requester,
      blockedTargetNodeId,
      [currentNodeId, candidate.nodeId],
      this.activeConflictSessionForPair(blocker.id, requester.id)
    );
  }

  private dispatchTasklessNoParkingClearance(vehicle: MutableVehicle): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId ||
      !this.layoutNode(vehicle.currentNodeId)?.noParking ||
      this.isInboundOnlyFlow() ||
      this.topLiftOutboundClearanceHoldAllowed(vehicle)
    ) {
      return false;
    }
    const clearanceRoute = this.topLiftTasklessNoParkingClearanceRoute(vehicle);
    if (!clearanceRoute) {
      return false;
    }
    this.installTasklessNoParkingClearanceRoute(vehicle, clearanceRoute);
    return true;
  }

  private tryClearTasklessBottomBSpineBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.taskId ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      !requester.loaded ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'bottom-b') ||
      this.layoutNode(blocker.currentNodeId)?.noParking !== true
    ) {
      return false;
    }

    const storageAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      return Boolean(
        node?.type === 'storage' &&
        !this.currentNodeOccupancy.has(nodeId) &&
        !this.nodeClaimedByOtherVehicle(nodeId, blocker.id) &&
        !this.storedLoadIdAtNode(nodeId) &&
        this.agentRefreshTemporaryStorageNodeAllowed(blocker, nodeId)
      );
    };
    const passThroughAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      return Boolean(
        node &&
        isTopLiftColumnAccessNodeId(nodeId) &&
        !this.currentNodeOccupancy.has(nodeId) &&
        !this.nodeClaimedByOtherVehicle(nodeId, blocker.id)
      );
    };

    const candidates: string[][] = [];
    const queue: string[][] = [[blocker.currentNodeId]];
    const bestDepthByNodeId = new Map<string, number>([[blocker.currentNodeId, 0]]);
    while (queue.length > 0) {
      const route = queue.shift()!;
      const currentNodeId = route[route.length - 1]!;
      if (route.length > 5) {
        continue;
      }
      for (const neighbor of this.neighbors(currentNodeId)) {
        const nextNodeId = neighbor.nodeId;
        if (route.includes(nextNodeId) || nextNodeId === requester.currentNodeId) {
          continue;
        }
        const nextRoute = [...route, nextNodeId];
        if (storageAllowed(nextNodeId)) {
          candidates.push(nextRoute);
          continue;
        }
        if (!passThroughAllowed(nextNodeId)) {
          continue;
        }
        if ((bestDepthByNodeId.get(nextNodeId) ?? Number.POSITIVE_INFINITY) <= nextRoute.length) {
          continue;
        }
        bestDepthByNodeId.set(nextNodeId, nextRoute.length);
        queue.push(nextRoute);
      }
    }
    candidates.sort((left, right) =>
      this.bottomBSpineClearanceRouteRank(blocker, requester, left) -
      this.bottomBSpineClearanceRouteRank(blocker, requester, right) ||
      left.length - right.length ||
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    );
    const route = candidates[0] ?? null;
    if (route) {
      this.installTasklessNoParkingClearanceRoute(blocker, route);
      return true;
    }
    return false;
  }

  private bottomBSpineClearanceRouteRank(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    routeNodeIds: string[]
  ): number {
    const firstHopNodeId = routeNodeIds[1] ?? null;
    const blockerNode = this.layoutNode(blocker.currentNodeId);
    const firstHopNode = firstHopNodeId ? this.layoutNode(firstHopNodeId) : null;
    const requesterForwardNode =
      this.layoutNode(requester.plannedGoalNodeId ?? '') ??
      this.layoutNode(requester.routeNodeIds[requester.routeIndex + 2] ?? '') ??
      this.layoutNode(requester.targetNodeId ?? '');
    if (!blockerNode || !firstHopNode || !requesterForwardNode) {
      return 10;
    }
    const requesterDirection = Math.sign(requesterForwardNode.x - blockerNode.x);
    const firstHopDirection = Math.sign(firstHopNode.x - blockerNode.x);
    if (requesterDirection !== 0 && firstHopDirection === requesterDirection) {
      return 0;
    }
    if (firstHopDirection !== 0) {
      return 1;
    }
    return 2;
  }

  private tryClearEmptyNoParkingSpineBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      !requester.loaded ||
      this.layoutNode(blocker.currentNodeId)?.noParking !== true
    ) {
      return false;
    }

    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind === 'inbound' && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }

    const route = this.topLiftTasklessNoParkingClearanceRoute(blocker);
    if (
      !route ||
      route.length < 2 ||
      route.includes(requester.currentNodeId) ||
      route.includes(blockedTargetNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(blocker, route)
    ) {
      return false;
    }

    return this.installAgentRefreshSideYieldRoute(
      blocker,
      requester,
      blockedTargetNodeId,
      route,
      this.activeConflictSessionForPair(blocker.id, requester.id)
    );
  }

  private tryClearEmptyNoParkingServiceLaneBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      this.layoutNode(blocker.currentNodeId)?.noParking !== true
    ) {
      return false;
    }

    const requesterTask = this.taskForVehicle(requester);
    if (!requester.loaded && !requesterTask) {
      return false;
    }
    const requesterWaitSec = requester.waitingSinceSec === null
      ? 0
      : this.simTimeSec - requester.waitingSinceSec;
    if (requesterWaitSec < 60) {
      return false;
    }

    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind === 'inbound' && !blocker.loaded && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }
    if (
      blockerTask &&
      blocker.targetNodeId !== null &&
      blocker.targetNodeId !== blocker.currentNodeId &&
      blocker.plannedGoalNodeId !== blocker.currentNodeId &&
      blocker.routeNodeIds.length > 1 &&
      blocker.waitReason === null
    ) {
      return false;
    }

    const route = this.topLiftNoParkingServiceLaneClearanceRoute(blocker, requester, blockedTargetNodeId);
    if (!route) {
      return false;
    }
    this.installTasklessNoParkingClearanceRoute(blocker, route);
    this.logAgentReroute(blocker, blockerTask, blockedTargetNodeId, route, 'top-lift-no-parking-service-lane-clearance', { countTaskReplan: false });
    return true;
  }

  private installTasklessNoParkingClearanceRoute(vehicle: MutableVehicle, clearanceRoute: string[]): void {
    vehicle.state = 'assigned';
    vehicle.routeNodeIds = clearanceRoute;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = clearanceRoute[1] ?? null;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.plannedGoalNodeId = clearanceRoute.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = clearanceRoute;
    vehicle.localRouteNodeIds = this.localClaimPrefixForRoute(vehicle.id, clearanceRoute);
    vehicle.localRouteReason = 'temporary-yield';
  }

  private topLiftNoParkingServiceLaneClearanceRoute(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): string[] | null {
    const fromNodeId = vehicle.currentNodeId;
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || this.layoutNode(fromNodeId)?.noParking !== true) {
      return null;
    }

    const activeInboundColumnKeys = this.activeTopLiftInboundColumnKeys();
    const protectedNodeIds = new Set([requester.currentNodeId]);
    protectedNodeIds.delete(blockedTargetNodeId);
    protectedNodeIds.delete(fromNodeId);

    const terminalAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      if (node?.type !== 'storage') {
        return false;
      }
      return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
    };
    const passThroughAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      return Boolean(node) &&
        node?.type !== 'lift-blackbox' &&
        (isTopLiftColumnAccessNodeId(nodeId) || this.topLiftColumnSpineOrAccessNode(nodeId));
    };

    const candidates: string[][] = [];
    const queue: string[][] = [[fromNodeId]];
    const visited = new Set<string>([fromNodeId]);
    const maxRouteNodes = 10;

    while (queue.length > 0) {
      const route = queue.shift()!;
      const currentNodeId = route.at(-1)!;
      if (route.length >= maxRouteNodes) {
        continue;
      }
      for (const neighbor of this.neighbors(currentNodeId)) {
        const nextNodeId = neighbor.nodeId;
        if (route.includes(nextNodeId) || protectedNodeIds.has(nextNodeId)) {
          continue;
        }
        const node = this.layoutNode(nextNodeId);
        if (!node || node.type === 'lift-blackbox') {
          continue;
        }
        const occupantId = this.currentNodeOccupancy.get(nextNodeId);
        if (occupantId && occupantId !== vehicle.id) {
          continue;
        }
        if (this.nodeClaimedByOtherVehicle(nextNodeId, vehicle.id)) {
          continue;
        }

        const nextRoute = [...route, nextNodeId];
        if (!this.routeHasOnlyAdjacentEdges(nextRoute)) {
          continue;
        }
        if (this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, nextRoute)) {
          continue;
        }
        if (terminalAllowed(nextNodeId)) {
          candidates.push(nextRoute);
          continue;
        }
        if (!passThroughAllowed(nextNodeId) || visited.has(nextNodeId)) {
          continue;
        }
        visited.add(nextNodeId);
        queue.push(nextRoute);
      }
    }

    candidates.sort((left, right) =>
      this.topLiftNoParkingServiceLaneClearanceRouteRank(left, activeInboundColumnKeys) -
      this.topLiftNoParkingServiceLaneClearanceRouteRank(right, activeInboundColumnKeys) ||
      left.length - right.length ||
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    );
    return candidates[0] ?? null;
  }

  private topLiftNoParkingServiceLaneClearanceRouteRank(routeNodeIds: string[], activeInboundColumnKeys: Set<string>): number {
    const terminalNodeId = routeNodeIds.at(-1) ?? '';
    const terminalColumnKey = this.topLiftColumnKey(terminalNodeId);
    return terminalColumnKey && activeInboundColumnKeys.has(terminalColumnKey) ? 10 : 0;
  }

  private topLiftTasklessNoParkingClearanceRoute(vehicle: MutableVehicle): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return null;
    }
    const fromNodeId = vehicle.currentNodeId;
    const fromNode = this.layoutNode(fromNodeId);
    if (!fromNode?.noParking) {
      return null;
    }
    const activeColumnKeys = this.activeTopLiftInboundColumnKeys();

    const pocketAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      if (node?.type !== 'storage') {
        return false;
      }
      const columnKey = this.topLiftColumnKey(nodeId);
      return (!columnKey || !activeColumnKeys.has(columnKey)) &&
        !this.currentNodeOccupancy.has(nodeId) &&
        !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id) &&
        !this.storedLoadIdAtNode(nodeId) &&
        this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
    };
    const passThroughAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      return Boolean(node) &&
        isTopLiftColumnAccessNodeId(nodeId) &&
        !this.currentNodeOccupancy.has(nodeId) &&
        !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
    };
    const candidates: string[][] = [];
    for (const firstHop of this.neighbors(fromNodeId)) {
      if (!this.agentMinimalYieldFirstLegSafe(vehicle, fromNodeId, firstHop.nodeId)) {
        continue;
      }
      if (pocketAllowed(firstHop.nodeId)) {
        candidates.push([fromNodeId, firstHop.nodeId]);
        continue;
      }
      if (!passThroughAllowed(firstHop.nodeId)) {
        continue;
      }
      for (const secondHop of this.neighbors(firstHop.nodeId)) {
        if (secondHop.nodeId === fromNodeId || !pocketAllowed(secondHop.nodeId)) {
          continue;
        }
        const route = [fromNodeId, firstHop.nodeId, secondHop.nodeId];
        if (this.routeEdgesExist(route)) {
          candidates.push(route);
        }
      }
    }
    candidates.sort((left, right) => {
      const leftTarget = left.at(-1)!;
      const rightTarget = right.at(-1)!;
      return this.topLiftTasklessClearanceRank(leftTarget) - this.topLiftTasklessClearanceRank(rightTarget) ||
        left.length - right.length ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'));
    });
    return candidates[0] ?? null;
  }

  private topLiftTasklessClearanceRank(nodeId: string): number {
    const node = this.layoutNode(nodeId);
    if (!node) {
      return 99;
    }
    if (isTopLiftColumnAccessNodeId(nodeId)) {
      return 1;
    }
    if (node.type === 'storage') {
      return 0;
    }
    return 10;
  }

  private topLiftRouteTerminatesOnColumnAccess(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const terminalNodeId = routeNodeIds.at(-1);
    return terminalNodeId ? isTopLiftColumnAccessNodeId(terminalNodeId) : false;
  }

  private topLiftColumnRowsPerZone(): number {
    if (this.topLiftColumnRowsPerZoneCache !== null) {
      return this.topLiftColumnRowsPerZoneCache;
    }
    const rows = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage')
      .map((node) => this.storageGridPosition(node.id)?.row ?? 0);
    this.topLiftColumnRowsPerZoneCache = Math.max(1, Math.max(...rows) / 2);
    return this.topLiftColumnRowsPerZoneCache;
  }

  private isTopLiftStorageBankEntryRow(nodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const position = this.storageGridPosition(nodeId);
    if (!position) {
      return false;
    }
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    return position.row === 1 ||
      position.row === rowsPerZone ||
      position.row === rowsPerZone + 1 ||
      position.row === rowsPerZone * 2;
  }

  private planRoute(currentNodeId: string, task: TaskStateRecord, parkingNodeId: string): string[] {
    const route: string[] = [currentNodeId];
    const storageEntrySideNodeId = task.kind === 'inbound' ? this.storageSideNodeId(task.dropoffNodeId, 'right') : this.storageSideNodeId(task.pickupNodeId, 'left');
    const currentStorageExitNodeId = task.kind === 'inbound' && this.isStorageNode(currentNodeId)
      ? this.inboundStorageExitNodeId(currentNodeId)
      : null;
    const alreadyAtOutboundPickup = task.kind === 'outbound' && currentNodeId === task.pickupNodeId;
    const targets = task.kind === 'inbound'
      ? [currentStorageExitNodeId, task.pickupNodeId, storageEntrySideNodeId, task.dropoffNodeId]
      : alreadyAtOutboundPickup
        ? [task.dropoffNodeId, parkingNodeId]
        : [storageEntrySideNodeId, task.pickupNodeId, storageEntrySideNodeId, task.dropoffNodeId, parkingNodeId];
    for (const target of targets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      const blockStoredLoads = route.includes(task.pickupNodeId) && target !== task.pickupNodeId;
      const blockedStorageNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target, { blockStoredLoads });
      const segment = this.shortestPath(fromNodeId, target, blockedStorageNodeIds);
      route.push(...segment.slice(1));
    }
    return this.simplifyImmediateTurnbackLoops(route, new Set([task.pickupNodeId, task.dropoffNodeId]));
  }

  private planLoadedRouteToDropoff(currentNodeId: string, task: TaskStateRecord): string[] {
    const route: string[] = [currentNodeId];
    const targets = task.kind === 'inbound'
      ? [this.storageSideNodeId(task.dropoffNodeId, 'right'), task.dropoffNodeId]
      : [task.dropoffNodeId];

    for (const target of targets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      const blockedStorageNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target, { blockStoredLoads: true });
      const segment = this.shortestPath(fromNodeId, target, blockedStorageNodeIds);
      route.push(...segment.slice(1));
    }

    return this.simplifyImmediateTurnbackLoops(route, new Set([task.pickupNodeId, task.dropoffNodeId]));
  }

  private inboundStorageExitNodeId(storageNodeId: string): string | null {
    return this.inboundStorageExitNodeCandidates(storageNodeId)[0] ?? null;
  }

  private inboundStorageExitNodeCandidates(storageNodeId: string): string[] {
    if (this.topLiftColumnLayoutEnabled()) {
      return [
        this.topLiftNearestStorageColumnAccessNodeId(storageNodeId),
        this.storageSideNodeId(storageNodeId, 'right'),
        this.storageSideNodeId(storageNodeId, 'left')
      ].filter((nodeId, index, nodeIds): nodeId is string =>
        nodeId !== null && nodeIds.indexOf(nodeId) === index
      );
    }
    if (this.isInboundOnlyFlow()) {
      const nodeId = this.nearestStorageSideNodeId(storageNodeId);
      return nodeId ? [nodeId] : [];
    }
    return [
      this.storageSideNodeId(storageNodeId, 'left'),
      this.nearestStorageSideNodeId(storageNodeId)
    ].filter((nodeId, index, nodeIds): nodeId is string =>
      nodeId !== null && nodeIds.indexOf(nodeId) === index
    );
  }

  private dispatchVehicleAfterInboundDropoff(vehicle: MutableVehicle): boolean {
    if (vehicle.loaded || vehicle.taskId) {
      return false;
    }
    if (this.dispatchTasklessToInboundQueueStandby(vehicle, 'inbound-dropoff-queue-standby')) {
      return true;
    }
    if (this.dispatchTasklessTopLiftStorageExit(vehicle)) {
      return true;
    }
    if (!this.isInboundOnlyFlow()) {
      return false;
    }

    const route = this.routeToInboundStandby(vehicle);
    if (!route || route.length <= 1 || this.topLiftRouteTerminatesOnColumnAccess(route)) {
      return false;
    }
    this.installTasklessPostDropoffRoute(vehicle, route);
    return true;
  }

  private dispatchVehicleAfterOutboundDropoff(vehicle: MutableVehicle, task: TaskStateRecord): boolean {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId
    ) {
      return false;
    }

    const route = this.outboundLiftDropoffClearanceRoute(vehicle, task);
    if (!route || route.length <= 1) {
      return false;
    }
    if (this.outboundClearanceRouteAcceptedAsStationReserve(route)) {
      this.installTasklessPostDropoffRoute(
        vehicle,
        route,
        'outbound-lift-dropoff-clearance-to-inbound-reserve',
        'inbound-queue-standby'
      );
      return true;
    }
    this.installTasklessPostDropoffRoute(vehicle, route, 'outbound-lift-dropoff-clearance', 'outbound-lift-clearance');
    return true;
  }

  private outboundClearanceRouteAcceptedAsStationReserve(routeNodeIds: string[]): boolean {
    const terminalSlot = this.topLiftInboundReserveQueueSlot(routeNodeIds.at(-1) ?? '');
    if (!terminalSlot || routeNodeIds.length > TOP_LIFT_PROTECTED_STANDBY_REROUTE_MAX_NODE_COUNT) {
      return false;
    }
    return this.topLiftInboundQueueCoveredDepth(terminalSlot.liftNodeId) <
      this.topLiftInboundQueueReserveRequiredDepth(terminalSlot.liftNodeId);
  }

  private outboundLiftDropoffClearanceRoute(vehicle: MutableVehicle, task: TaskStateRecord): string[] | null {
    if (vehicle.currentNodeId !== task.dropoffNodeId) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return null;
    }
    if (task.dropoffNodeId === this.topLiftDockRailNodeId(liftNodeId)) {
      return this.extendOutboundLiftDropoffClearanceRouteToStandby(vehicle, [task.dropoffNodeId], liftNodeId);
    }
    const yellowGridExitNodeId = this.topLiftOutboundDropoffExitNodeId(task.dropoffNodeId);
    if (yellowGridExitNodeId && this.traffic.findEdge(task.dropoffNodeId, yellowGridExitNodeId)) {
      return this.extendOutboundLiftDropoffClearanceRouteToStandby(vehicle, [task.dropoffNodeId, yellowGridExitNodeId]);
    }
    const serviceSlot = topLiftQueueServiceSlot(task.dropoffNodeId);
    if (serviceSlot?.liftNodeId === liftNodeId && this.liftPortKindForNodeId(liftNodeId) === 'outbound') {
      const directEntryNodeId = liftQueueTailEntryNodeId(liftNodeId, serviceSlot.slotIndex);
      const directExitNodeId = this.topLiftQueueEntryBottomAccessNodeId(directEntryNodeId);
      const directRoute = [
        task.dropoffNodeId,
        directEntryNodeId,
        directExitNodeId
      ].filter((nodeId): nodeId is string => Boolean(nodeId));
      const checkedDirectRoute = this.enforceTopLiftWorkcellRouteContract(
        directRoute.length > 1 && this.routeEdgesExist(directRoute) ? directRoute : null,
        'outbound-clear-through',
        liftNodeId,
        'outbound'
      );
      if (checkedDirectRoute) {
        return this.extendOutboundLiftDropoffClearanceRouteToStandby(vehicle, checkedDirectRoute);
      }
      const finalServiceSlotIndex = 3;
      const serviceExitNodeIds = Array.from({ length: finalServiceSlotIndex - serviceSlot.slotIndex }, (_, index) =>
        liftQueueServiceExitNodeId(liftNodeId, serviceSlot.slotIndex + index + 1)
      );
      const finalEntryNodeId = liftQueueTailEntryNodeId(liftNodeId, finalServiceSlotIndex);
      const exitBottomNodeId = this.topLiftQueueEntryBottomAccessNodeId(finalEntryNodeId);
      const route = [
        task.dropoffNodeId,
        ...serviceExitNodeIds,
        finalEntryNodeId,
        exitBottomNodeId
      ].filter((nodeId): nodeId is string => Boolean(nodeId));
      const checkedRoute = this.enforceTopLiftWorkcellRouteContract(
        route.length > 1 && this.routeEdgesExist(route) ? route : null,
        'outbound-clear-through',
        liftNodeId,
        'outbound'
      );
      return checkedRoute
        ? this.extendOutboundLiftDropoffClearanceRouteToStandby(vehicle, checkedRoute)
        : null;
    }

    const dropoffBuffer = liftBufferParentNodeId(task.dropoffNodeId);
    if (dropoffBuffer?.kind !== 'outbound' || dropoffBuffer.liftNodeId !== liftNodeId) {
      return null;
    }

    const exitNodeId = liftBufferAccessNodeId(liftNodeId);
    if (!this.layoutNode(exitNodeId) || !this.traffic.findEdge(task.dropoffNodeId, exitNodeId)) {
      return null;
    }
    return this.extendOutboundLiftDropoffClearanceRouteToStandby(vehicle, [task.dropoffNodeId, exitNodeId]);
  }

  private extendOutboundLiftDropoffClearanceRouteToStandby(vehicle: MutableVehicle, routeNodeIds: string[], explicitLiftNodeId: string | null = null): string[] | null {
    const inboundQueueRoute = this.extendTasklessRouteToInboundQueueStandby(vehicle, routeNodeIds);
    if (
      inboundQueueRoute &&
      inboundQueueRoute.length > routeNodeIds.length &&
      (
        !this.topLiftRouteTerminatesOnColumnAccess(inboundQueueRoute) ||
        this.topLiftInboundApproachQueueSlot(inboundQueueRoute.at(-1) ?? '') !== null
      )
    ) {
      return inboundQueueRoute;
    }

    const liftNodeId = explicitLiftNodeId ?? this.outboundLiftNodeIdFromClearanceRoute(routeNodeIds);
    if (liftNodeId) {
      const clearanceDirections = this.topLiftOutboundClearanceDirections(liftNodeId, routeNodeIds.at(-1) ?? null);
      for (const direction of clearanceDirections) {
        const awayFromLiftRoute = this.extendOutboundLiftClearanceAwayFromLift(vehicle, routeNodeIds, direction);
        if (!awayFromLiftRoute || awayFromLiftRoute.length <= routeNodeIds.length) {
          continue;
        }
        return awayFromLiftRoute;
      }
    }
    const offNoStopRoute = this.extendTasklessTopLiftExitRouteOffNoStop(vehicle, routeNodeIds);
    if (
      offNoStopRoute &&
      offNoStopRoute.length > routeNodeIds.length &&
      !this.topLiftRouteTerminatesOnColumnAccess(offNoStopRoute) &&
      !this.topLiftRouteCrossesOutboundDockVerticalTransfer(offNoStopRoute)
    ) {
      return offNoStopRoute;
    }
    const standbyRoute = this.extendPostDropoffExitRouteToStandby(vehicle, routeNodeIds);
    if (
      standbyRoute &&
      standbyRoute.length > routeNodeIds.length &&
      !this.topLiftRouteTerminatesOnColumnAccess(standbyRoute) &&
      !this.topLiftRouteCrossesOutboundDockVerticalTransfer(standbyRoute)
    ) {
      return standbyRoute;
    }
    return this.topLiftRouteTerminatesOnColumnAccess(routeNodeIds) ? null : routeNodeIds;
  }

  private extendOutboundLiftClearanceToLowerStorageStandby(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    direction: -1 | 1
  ): string[] | null {
    const startNodeId = routeNodeIds.at(-1);
    if (!startNodeId || !isTopLiftAisleLevelNodeId(startNodeId, 'bottom-b')) {
      return null;
    }
    const protectedNodeIds = new Set(routeNodeIds.slice(0, -1));
    const startColumn = this.topLiftColumnAccessColumn(startNodeId);

    const storageTerminalAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      if (!node || node.type !== 'storage' || this.isTopLiftStorageBankEntryRow(nodeId)) {
        return false;
      }
      const columnKey = this.topLiftColumnKey(nodeId);
      return !this.currentNodeOccupancy.has(nodeId) &&
        !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id) &&
        !this.storedLoadIdAtNode(nodeId) &&
        !this.activeInboundDropoffNodeIds().has(nodeId) &&
        (!columnKey || !this.activeTopLiftInboundColumnKeys().has(columnKey)) &&
        (!columnKey || !this.claimedTasklessParkableColumnKeys(vehicle.id).has(columnKey)) &&
        this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
    };
    const passThroughAllowed = (nodeId: string): boolean => {
      const node = this.layoutNode(nodeId);
      if (!node || protectedNodeIds.has(nodeId)) {
        return false;
      }
      if (isTopLiftAisleLevelNodeId(nodeId, 'top-a') || isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
        return false;
      }
      if (isTopLiftColumnAccessNodeId(nodeId)) {
        return !this.currentNodeOccupancy.has(nodeId) && !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
      }
      if (node.type === 'storage' && this.isTopLiftStorageBankEntryRow(nodeId)) {
        return !this.currentNodeOccupancy.has(nodeId) &&
          !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id) &&
          !this.storedLoadIdAtNode(nodeId);
      }
      return false;
    };

    const candidates: string[][] = [];
    const queue: string[][] = [[startNodeId]];
    const bestDepthByNodeId = new Map<string, number>([[startNodeId, 0]]);
    while (queue.length > 0) {
      const route = queue.shift()!;
      const currentNodeId = route.at(-1)!;
      if (route.length > 6) {
        continue;
      }
      for (const neighbor of this.neighbors(currentNodeId)) {
        const nextNodeId = neighbor.nodeId;
        if (route.includes(nextNodeId) || protectedNodeIds.has(nextNodeId)) {
          continue;
        }
        const nextRoute = [...route, nextNodeId];
        const fullRoute = [...routeNodeIds, ...nextRoute.slice(1)];
        if (this.topLiftRouteCrossesOutboundDockVerticalTransfer(fullRoute)) {
          continue;
        }
        if (storageTerminalAllowed(nextNodeId)) {
          candidates.push(nextRoute);
          continue;
        }
        if (!passThroughAllowed(nextNodeId)) {
          continue;
        }
        if ((bestDepthByNodeId.get(nextNodeId) ?? Number.POSITIVE_INFINITY) <= nextRoute.length) {
          continue;
        }
        bestDepthByNodeId.set(nextNodeId, nextRoute.length);
        queue.push(nextRoute);
      }
    }

    candidates.sort((left, right) =>
      this.outboundLiftClearanceStorageStandbyRouteRank(left, startColumn, direction) -
      this.outboundLiftClearanceStorageStandbyRouteRank(right, startColumn, direction) ||
      left.length - right.length ||
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    );

    const standbyRoute = candidates[0] ?? null;
    return standbyRoute ? [...routeNodeIds, ...standbyRoute.slice(1)] : null;
  }

  private outboundLiftClearanceStorageStandbyRouteRank(
    routeNodeIds: string[],
    startColumn: number | null,
    direction: -1 | 1
  ): number {
    const targetNodeId = routeNodeIds.at(-1);
    const targetPosition = targetNodeId ? this.storageGridPosition(targetNodeId) : null;
    const awayPenalty = startColumn && targetPosition
      ? Math.max(0, (targetPosition.column - startColumn) * -direction) * 100
      : 0;
    const columnDistance = startColumn && targetPosition ? Math.abs(targetPosition.column - startColumn) : 0;
    const rowPreference = targetPosition ? Math.abs(targetPosition.row - (this.topLiftColumnRowsPerZone() * 2 - 1)) : 10;
    return awayPenalty + columnDistance * 10 + rowPreference;
  }

  private topLiftOutboundClearanceDirections(liftNodeId: string, fromNodeId: string | null): Array<-1 | 1> {
    const liftNode = this.layoutNode(liftNodeId);
    const fromNode = fromNodeId ? this.layoutNode(fromNodeId) : null;
    if (liftNode && fromNode && Math.abs(fromNode.x - liftNode.x) > 1e-6) {
      const awayFromLift = fromNode.x > liftNode.x ? 1 : -1;
      return [awayFromLift, awayFromLift === 1 ? -1 : 1];
    }
    const queueDirection = this.topLiftQueueDisplayDirection(liftNodeId);
    return [queueDirection, queueDirection === 1 ? -1 : 1];
  }

  private topLiftOutboundClearanceHoldAllowed(vehicle: MutableVehicle): boolean {
    const completedRecentClearance =
      vehicle.localRouteReason === null &&
      this.assignmentHoldActive(vehicle) &&
      vehicle.recentOutboundClearanceRouteNodeIds.length > 1 &&
      vehicle.recentOutboundClearanceRouteNodeIds.at(-1) === vehicle.currentNodeId;
    return this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      !vehicle.taskId &&
      (
        vehicle.localRouteReason === 'outbound-lift-clearance' ||
        vehicle.localRouteReason === 'outbound-lift-clearance-hold' ||
        completedRecentClearance
      ) &&
      vehicle.plannedGoalNodeId === vehicle.currentNodeId &&
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-b');
  }

  private topLiftRouteCrossesOutboundDockVerticalTransfer(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromNodeId = routeNodeIds[index - 1]!;
      const toNodeId = routeNodeIds[index]!;
      const fromMatch = /^(module-\d+)-spine-bottom-b$/.exec(fromNodeId);
      if (fromMatch && toNodeId === `${fromMatch[1]}-spine-bottom-a`) {
        return true;
      }
      const toMatch = /^(module-\d+)-spine-bottom-b$/.exec(toNodeId);
      if (toMatch && fromNodeId === `${toMatch[1]}-spine-bottom-a`) {
        return true;
      }
    }
    return false;
  }

  private extendOutboundLiftClearanceAwayFromLift(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    direction: -1 | 1
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    let route = [...routeNodeIds];
    let tailNodeId = route.at(-1);
    if (!tailNodeId || !isTopLiftAisleLevelNodeId(tailNodeId, 'bottom-b')) {
      return null;
    }
    const clearanceNodeCount = 3;
    for (let index = 0; index < clearanceNodeCount; index += 1) {
      const nextNodeId = this.nextTopLiftRailNodeAlongDirection(tailNodeId, 'bottom-b', direction, vehicle.id);
      if (!nextNodeId) {
        break;
      }
      route.push(nextNodeId);
      tailNodeId = nextNodeId;
    }
    return route.length > routeNodeIds.length ? route : null;
  }

  private outboundLiftNodeIdFromClearanceRoute(routeNodeIds: string[]): string | null {
    for (const nodeId of routeNodeIds) {
      const serviceSlot = topLiftQueueServiceSlot(nodeId);
      if (serviceSlot && this.liftPortKindForNodeId(serviceSlot.liftNodeId) === 'outbound') {
        return serviceSlot.liftNodeId;
      }
      const entrySlot = topLiftQueueEntrySlot(nodeId);
      if (entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'outbound') {
        return entrySlot.liftNodeId;
      }
      const accessSlot = topLiftQueueAisleAccess(nodeId);
      if (accessSlot && this.liftPortKindForNodeId(accessSlot.liftNodeId) === 'outbound') {
        return accessSlot.liftNodeId;
      }
      const buffer = liftBufferParentNodeId(nodeId);
      if (buffer?.kind === 'outbound') {
        return buffer.liftNodeId;
      }
    }
    for (const liftNode of this.outboundLiftNodes()) {
      const sweepNodeIds = this.topLiftOutboundClearanceSweepNodeIds(liftNode.id);
      if (routeNodeIds.some((nodeId) => sweepNodeIds.includes(nodeId))) {
        return liftNode.id;
      }
    }
    return null;
  }

  private nextTopLiftRailNodeAlongDirection(
    fromNodeId: string,
    level: TopLiftAisleLevel,
    direction: -1 | 1,
    vehicleId: string
  ): string | null {
    const fromNode = this.layoutNode(fromNodeId);
    if (!fromNode) {
      return null;
    }
    const candidates = this.scenario.layout.nodes
      .filter((node) => isTopLiftAisleLevelNodeId(node.id, level))
      .filter((node) => (node.x - fromNode.x) * direction > 1e-6)
      .sort((left, right) => (left.x - fromNode.x) * direction - (right.x - fromNode.x) * direction);
    for (const candidate of candidates) {
      if (!this.traffic.findEdge(fromNodeId, candidate.id)) {
        continue;
      }
      const occupantId = this.currentNodeOccupancy.get(candidate.id);
      if (occupantId && occupantId !== vehicleId) {
        continue;
      }
      if (this.nodeClaimedByOtherVehicle(candidate.id, vehicleId)) {
        continue;
      }
      return candidate.id;
    }
    return null;
  }

  private topLiftOutboundDropoffExitNodeId(dropoffNodeId: string): string | null {
    const match = /^column-bottom-a-c(\d+)$/.exec(dropoffNodeId);
    if (!match) {
      return null;
    }
    const exitNodeId = `column-bottom-b-c${match[1]}`;
    return this.layoutNode(exitNodeId) ? exitNodeId : null;
  }

  private topLiftQueueEntryTopAccessNodeId(entryNodeId: string): string | null {
    return this.topLiftQueueEntryAccessNodeId(entryNodeId, 'approach');
  }

  private topLiftQueueEntryBottomAccessNodeId(entryNodeId: string): string | null {
    return this.topLiftQueueEntryAccessNodeId(entryNodeId, 'exit');
  }

  private topLiftQueueEntryAccessNodeId(entryNodeId: string, side: 'approach' | 'exit'): string | null {
    const cacheKey = `${entryNodeId}:${side}`;
    if (this.topLiftQueueEntryAccessNodeIdCache.has(cacheKey)) {
      return this.topLiftQueueEntryAccessNodeIdCache.get(cacheKey) ?? null;
    }
    const entryNode = this.layoutNode(entryNodeId);
    if (!entryNode) {
      this.topLiftQueueEntryAccessNodeIdCache.set(cacheKey, null);
      return null;
    }
    const entrySlot = topLiftQueueEntrySlot(entryNodeId);
    if (!entrySlot) {
      this.topLiftQueueEntryAccessNodeIdCache.set(cacheKey, null);
      return null;
    }
    const kind = this.liftPortKindForNodeId(entrySlot.liftNodeId);
    const level: TopLiftAisleLevel = kind === 'outbound'
      ? (side === 'approach' ? 'bottom-a' : 'bottom-b')
      : (side === 'approach' ? 'top-a' : 'top-b');
    const accessNode = this.scenario.layout.nodes.find((node) =>
      node.id.startsWith(`column-${level}-c`) &&
      Math.abs(node.x - entryNode.x) < 1e-6
    );
    const nodeId = accessNode?.id ?? null;
    this.topLiftQueueEntryAccessNodeIdCache.set(cacheKey, nodeId);
    return nodeId;
  }

  private routeEdgesExist(route: string[]): boolean {
    for (let index = 1; index < route.length; index += 1) {
      if (!this.traffic.findEdge(route[index - 1]!, route[index]!)) {
        return false;
      }
    }
    return true;
  }

  private simplifyImmediateTurnbackLoops(routeNodeIds: string[], protectedNodeIds: Set<string> = new Set()): string[] {
    if (routeNodeIds.length < 3) {
      return routeNodeIds;
    }
    const route = [...routeNodeIds];
    let index = 0;
    while (index + 2 < route.length) {
      const anchorNodeId = route[index]!;
      const middleNodeId = route[index + 1]!;
      const returnNodeId = route[index + 2]!;
      if (anchorNodeId !== returnNodeId) {
        index += 1;
        continue;
      }
      if (protectedNodeIds.has(middleNodeId) || protectedNodeIds.has(returnNodeId)) {
        index += 1;
        continue;
      }

      const nextNodeId = route[index + 3] ?? null;
      if (nextNodeId && !this.traffic.findEdge(anchorNodeId, nextNodeId)) {
        index += 1;
        continue;
      }
      route.splice(index + 1, 2);
      index = Math.max(0, index - 1);
    }
    return route;
  }

  private dispatchTasklessTopLiftStorageExit(vehicle: MutableVehicle, force = false): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId || !this.isStorageNode(vehicle.currentNodeId)) {
      return false;
    }
    if (
      !force &&
      this.inboundDropoffStandbyHoldActive(vehicle) &&
      !this.topLiftTasklessVehicleBlocksActiveRoute(vehicle)
    ) {
      return false;
    }
    const postDropoffExitRoute = this.postDropoffColumnExitRoute(vehicle);
    const queuedWorkWaiting = this.topLiftQueuedWorkWaiting();
    const route = postDropoffExitRoute
      ? this.isInboundOnlyFlow() && !queuedWorkWaiting
        ? this.extendPostDropoffExitRouteToStandby(vehicle, postDropoffExitRoute)
        : postDropoffExitRoute
      : null;
    if (!route || route.length <= 1) {
      return false;
    }
    if (this.isInboundOnlyFlow() && !queuedWorkWaiting && this.topLiftRouteTerminatesOnColumnAccess(route)) {
      return false;
    }
    if (!force && !this.topLiftTasklessStorageExitNeeded(vehicle, route)) {
      return false;
    }
    this.installTasklessPostDropoffRoute(
      vehicle,
      route,
      force ? 'outbound-route-unavailable-storage-release-exit' : 'inbound-lift-near-storage-standby',
      force ? 'route-unavailable-storage-release-exit' : 'post-dropoff-column-exit'
    );
    return true;
  }

  private topLiftTasklessStorageExitNeeded(
    vehicle: MutableVehicle,
    route: string[]
  ): boolean {
    if (!this.topLiftRouteTerminatesOnColumnAccess(route)) {
      return true;
    }
    if (
      this.topLiftQueuedInboundTaskMatchesVehicleColumn(vehicle) ||
      this.topLiftTasklessVehicleBlocksInboundColumn(vehicle) ||
      this.topLiftTasklessVehicleBlocksActiveRoute(vehicle)
    ) {
      return true;
    }
    return this.vehicles.some((other) =>
      other.id !== vehicle.id &&
      (other.currentNodeId === vehicle.currentNodeId || this.vehicleFutureClaimsEnabled(other)) &&
      (
        other.currentNodeId === vehicle.currentNodeId ||
        other.targetNodeId === vehicle.currentNodeId ||
        other.routeNodeIds.includes(vehicle.currentNodeId) ||
        other.plannedRouteNodeIds.includes(vehicle.currentNodeId) ||
        other.localRouteNodeIds.includes(vehicle.currentNodeId)
      )
    );
  }

  private topLiftQueuedWorkWaiting(): boolean {
    return this.tasks.some((task) => task.state === 'queued');
  }

  private dispatchTasklessTopLiftStorageExits(): void {
    if (!this.topLiftColumnLayoutEnabled()) {
      return;
    }
    const queuedWorkWaiting = this.topLiftQueuedWorkWaiting();
    for (const vehicle of this.vehicles) {
      if (
        !vehicle.taskId &&
        !vehicle.loaded &&
        this.isStorageNode(vehicle.currentNodeId) &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.phaseRemainingSec <= 0 &&
        !this.tasklessPlannedRouteActive(vehicle) &&
        !this.inboundDropoffStandbyHoldActive(vehicle) &&
        (this.topLiftQueuedInboundTaskMatchesVehicleColumn(vehicle) ||
          this.topLiftTasklessVehicleBlocksInboundColumn(vehicle) ||
          this.topLiftTasklessVehicleBlocksActiveRoute(vehicle))
      ) {
        this.dispatchTasklessTopLiftStorageExit(vehicle);
      }
    }
  }

  private dispatchTasklessInboundQueueStandbys(allowQueueCompression = true): void {
    if (!this.mixedTopLiftFlowEnabled()) {
      return;
    }
    const candidates = this.vehicles
      .filter((vehicle) =>
        !vehicle.taskId &&
        !vehicle.loaded &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.phaseRemainingSec <= 0 &&
      !this.assignmentHoldActive(vehicle) &&
      !this.inboundDropoffStandbyHoldActive(vehicle) &&
      this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)
      )
      .sort((left, right) =>
        this.topLiftInboundQueueStandbyDispatchRank(left) - this.topLiftInboundQueueStandbyDispatchRank(right) ||
        this.topLiftInboundQueueStandbyNearestDistanceM(left) - this.topLiftInboundQueueStandbyNearestDistanceM(right) ||
        left.id.localeCompare(right.id)
      );
    for (const vehicle of candidates) {
      if (allowQueueCompression && this.compressTasklessInboundQueueStandby(vehicle)) {
        continue;
      }
      if (this.holdTasklessInboundQueueStandby(vehicle, vehicle.currentNodeId)) {
        continue;
      }
      this.dispatchTasklessToInboundQueueStandby(vehicle);
    }
  }

  private compressTasklessInboundQueueStandby(vehicle: MutableVehicle): boolean {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.localRouteReason !== 'inbound-queue-standby' ||
      vehicle.plannedGoalNodeId !== vehicle.currentNodeId
    ) {
      return false;
    }
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    if (!currentSlot || currentSlot.slotIndex <= 1) {
      return false;
    }

    const candidateNodeIds = this.topLiftInboundApproachQueueNodeIds(currentSlot.liftNodeId)
      .filter((nodeId) => {
        const slot = this.topLiftInboundApproachQueueSlot(nodeId);
        return Boolean(slot && slot.liftNodeId === currentSlot.liftNodeId && slot.slotIndex < currentSlot.slotIndex);
      });
    for (const nodeId of candidateNodeIds) {
      if (!this.topLiftInboundQueueStandbyNodeAvailable(vehicle, nodeId)) {
        continue;
      }
      let route: string[];
      try {
        route = this.shortestPath(vehicle.currentNodeId, nodeId);
      } catch {
        continue;
      }
      if (
        route.length < 2 ||
        !route.every((routeNodeId) => this.topLiftInboundApproachQueueSlot(routeNodeId)?.liftNodeId === currentSlot.liftNodeId) ||
        !this.agentRefreshLocalRouteNodesClear(vehicle, route)
      ) {
        continue;
      }
      const nextNodeId = route[1] ?? null;
      const block = nextNodeId && this.collisionAvoidanceEnabled()
        ? this.agentRefreshEnabled()
          ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
          : this.agentMinimalEnabled()
            ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
            : this.agentMoveBlocker(vehicle, nextNodeId)
        : null;
      if (block) {
        continue;
      }
      this.installTasklessPostDropoffRoute(vehicle, route, 'inbound-queue-standby-compress', 'inbound-queue-standby');
      return true;
    }
    return false;
  }

  private topLiftInboundQueueStandbyDispatchRank(vehicle: MutableVehicle): number {
    const level = topLiftAisleLevel(vehicle.currentNodeId);
    if (level === 'top-a' || level === 'top-b') {
      return 0;
    }
    if (this.isStorageNode(vehicle.currentNodeId)) {
      return 1;
    }
    if (level === 'middle') {
      return 2;
    }
    if (level === 'bottom-a' || level === 'bottom-b') {
      return 3;
    }
    return 2;
  }

  private topLiftInboundQueueStandbyNearestDistanceM(vehicle: MutableVehicle): number {
    const vehicleNode = this.layoutNode(vehicle.currentNodeId);
    if (!vehicleNode) {
      return Number.POSITIVE_INFINITY;
    }
    let bestDistanceM = Number.POSITIVE_INFINITY;
    for (const lift of this.inboundLiftNodes()) {
      if (this.topLiftInboundQueueCoveredDepth(lift.id) >= this.topLiftInboundQueueReserveRequiredDepth(lift.id)) {
        continue;
      }
      for (const nodeId of this.topLiftInboundApproachQueueNodeIds(lift.id)) {
        const node = this.layoutNode(nodeId);
        if (!node || !this.topLiftInboundQueueStandbyNodeAvailable(vehicle, nodeId)) {
          continue;
        }
        bestDistanceM = Math.min(bestDistanceM, Math.abs(vehicleNode.x - node.x) + Math.abs(vehicleNode.z - node.z));
      }
    }
    return bestDistanceM;
  }

  private dispatchTasklessToInboundQueueStandby(
    vehicle: MutableVehicle,
    reason = 'inbound-queue-standby-dispatched'
  ): boolean {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      this.inboundDropoffStandbyHoldActive(vehicle)
    ) {
      return false;
    }
    if (!this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)) {
      return false;
    }
    if (this.holdTasklessInboundQueueStandby(vehicle, vehicle.currentNodeId)) {
      return true;
    }
    const route = this.routeToInboundQueueStandby(vehicle);
    if (!route || route.length <= 1) {
      return false;
    }
    const nextNodeId = route[1] ?? null;
    const nextBlock = nextNodeId && this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
          : this.agentMoveBlocker(vehicle, nextNodeId)
      : null;
    if (nextBlock) {
      return false;
    }
    if (this.assignQueuedInboundTaskToQueueStandby(vehicle, route, reason)) {
      return true;
    }
    if (!this.tasklessInboundQueueStandbyRouteOriginAllowed(route)) {
      return false;
    }
    this.installTasklessPostDropoffRoute(vehicle, route, reason, 'inbound-queue-standby');
    return true;
  }

  private assignQueuedInboundTaskToQueueStandby(vehicle: MutableVehicle, route: string[], reason: string): boolean {
    const terminalNodeId = route.at(-1) ?? null;
    const terminalSlot = terminalNodeId ? this.topLiftInboundApproachQueueSlot(terminalNodeId) : null;
    if (!terminalSlot || vehicle.taskId || vehicle.loaded) {
      return false;
    }
    for (const { task } of this.queuedTasksForAssignment()) {
      if (
        task.kind !== 'inbound' ||
        task.state !== 'queued' ||
        task.vehicleId !== null ||
        this.taskLiftPortNodeId(task) !== terminalSlot.liftNodeId
      ) {
        continue;
      }
      this.tryRetargetQueuedInboundStorageFullTask(task);
      if (
        this.queuedTaskAssignmentPriority(task) > 0 ||
        this.taskAssignmentBlockReason(task) ||
        !this.topLiftInboundAssignmentMustStageThroughQueue(vehicle, task) ||
        !this.topLiftInboundAssignmentRouteStagesThroughQueue(vehicle, task, route)
      ) {
        continue;
      }
      this.assignTaskToVehicle(vehicle, task, route);
      this.logEvent(
        'task-routed-to-inbound-queue',
        vehicle.id,
        task.id,
        task.loadId,
        vehicle.currentNodeId,
        terminalNodeId,
        reason,
        this.vehiclePosition(vehicle),
        { route: route.join('>') }
      );
      return true;
    }
    return false;
  }

  private holdTasklessInboundQueueStandbys(): void {
    if (!this.mixedTopLiftFlowEnabled()) {
      return;
    }
    for (const vehicle of this.vehicles) {
      this.holdTasklessInboundQueueStandby(vehicle, vehicle.currentNodeId);
    }
  }

  private tasklessInboundQueueStandbyRerouteAllowed(vehicle: MutableVehicle): boolean {
    if (!this.tasklessPlannedRouteActive(vehicle)) {
      return true;
    }
    if (vehicle.localRouteReason === 'inbound-queue-standby') {
      return false;
    }
    return vehicle.localRouteReason === null ||
      vehicle.localRouteReason === 'post-dropoff-column-exit';
  }

  private routeToInboundQueueStandby(
    vehicle: MutableVehicle,
    fromNodeId = vehicle.currentNodeId,
    options: { allowTaskedVehicle?: boolean; liftNodeId?: string } = {}
  ): string[] | null {
    const targetNodeId = this.topLiftInboundQueueStandbyTargetNodeId(vehicle, fromNodeId, options);
    if (!targetNodeId) {
      return null;
    }
    try {
      const outboundDockBlockedNodeIds = this.activeTopLiftOutboundDockBlockedNodeIds(vehicle.id);
      const route = this.planStandbyRoute(
        fromNodeId,
        targetNodeId,
        outboundDockBlockedNodeIds
      );
      if (
        route.length > 1 &&
        route.at(-1) === targetNodeId &&
        this.routeEdgesExist(route) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, route) &&
        this.tasklessInboundQueueStandbyRouteAllowed(vehicle, route, options) &&
        this.routeAvoidsActiveTopLiftOutboundDockBlocks(vehicle, route)
      ) {
        return route;
      }
      if (!this.tasklessInboundQueueStandbyRouteAllowed(vehicle, route, options)) {
        const protectedNodeIds = this.activeTopLiftInboundMainFlowProtectedNodeIds(vehicle.id);
        const blockedNodeIds = new Set([...outboundDockBlockedNodeIds, ...protectedNodeIds]);
        const protectedRoute = this.planStandbyRoute(fromNodeId, targetNodeId, blockedNodeIds);
        if (
          protectedRoute.length > 1 &&
          protectedRoute.length <= TOP_LIFT_PROTECTED_STANDBY_REROUTE_MAX_NODE_COUNT &&
          protectedRoute.at(-1) === targetNodeId &&
          this.routeEdgesExist(protectedRoute) &&
          this.agentRefreshLocalRouteNodesClear(vehicle, protectedRoute) &&
          this.tasklessInboundQueueStandbyRouteAllowed(vehicle, protectedRoute, options) &&
          this.routeAvoidsActiveTopLiftOutboundDockBlocks(vehicle, protectedRoute)
        ) {
          return protectedRoute;
        }
      }
    } catch {
      return null;
    }
    return null;
  }

  private extendTasklessRouteToInboundQueueStandby(vehicle: MutableVehicle, routeNodeIds: string[]): string[] | null {
    if (routeNodeIds.length === 0 || !this.mixedTopLiftFlowEnabled()) {
      return null;
    }
    for (let index = routeNodeIds.length - 1; index >= 0; index -= 1) {
      const prefix = routeNodeIds.slice(0, index + 1);
      const fromNodeId = prefix.at(-1);
      if (!fromNodeId) {
        continue;
      }
      const standbyRoute = this.routeToInboundQueueStandby(vehicle, fromNodeId);
      if (!standbyRoute || standbyRoute.length <= 1) {
        continue;
      }
      const route = [...prefix, ...standbyRoute.slice(1)];
      if (
        route.length <= prefix.length ||
        new Set(route).size !== route.length ||
        !this.routeEdgesExist(route) ||
        !this.tasklessInboundQueueStandbyRouteAllowed(vehicle, route)
      ) {
        continue;
      }
      return route;
    }
    return null;
  }

  private tasklessInboundQueueStandbyRouteAllowed(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    options: { allowTaskedVehicle?: boolean } = {}
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      (!options.allowTaskedVehicle && vehicle.taskId) ||
      routeNodeIds.length <= 1
    ) {
      return true;
    }
    const protectedNodeIds = this.activeTopLiftInboundMainFlowProtectedNodeIds(vehicle.id);
    if (protectedNodeIds.size === 0) {
      return true;
    }
    return routeNodeIds.slice(1).every((nodeId) => !protectedNodeIds.has(nodeId));
  }

  private routeAvoidsActiveTopLiftOutboundDockBlocks(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || routeNodeIds.length <= 1) {
      return true;
    }
    const blockedNodeIds = this.activeTopLiftOutboundDockBlockedNodeIds(vehicle.id);
    if (blockedNodeIds.size === 0) {
      return true;
    }
    const allowedNodeIds = new Set<string>([
      vehicle.currentNodeId,
      routeNodeIds[0]!,
      routeNodeIds.at(-1)!
    ]);
    return routeNodeIds.slice(1).every((nodeId) =>
      allowedNodeIds.has(nodeId) || !blockedNodeIds.has(nodeId)
    );
  }

  private tasklessInboundQueueStandbyRouteOriginAllowed(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    return routeNodeIds.every((nodeId) => {
      const level = topLiftAisleLevel(nodeId);
      return level === 'top-a' ||
        level === 'top-b' ||
        this.topLiftInboundApproachQueueSlot(nodeId) !== null;
    });
  }

  private activeTopLiftInboundMainFlowProtectedNodeIds(requesterVehicleId: string): Set<string> {
    const protectedNodeIds = this.activeTopLiftLoadedInboundProtectedNodeIds(requesterVehicleId);
    if (!this.topLiftColumnLayoutEnabled()) {
      return protectedNodeIds;
    }

    for (const vehicle of this.vehicles) {
      if (vehicle.id === requesterVehicleId || vehicle.loaded) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      if (
        task?.kind !== 'inbound' ||
        task.completedAtSec !== null ||
        task.vehicleId !== vehicle.id ||
        !this.isStorageNode(task.dropoffNodeId)
      ) {
        continue;
      }
      for (const nodeId of this.topLiftProjectedLoadedInboundProtectedRoute(task)) {
        protectedNodeIds.add(nodeId);
      }
    }

    return protectedNodeIds;
  }

  private topLiftProjectedLoadedInboundProtectedRoute(task: TaskStateRecord): string[] {
    try {
      const route = this.agentRefreshLoadedInboundRouteToDropoff(task.pickupNodeId, task);
      return this.topLiftProtectedInboundRouteNodeIds(route, task.dropoffNodeId);
    } catch {
      return [];
    }
  }

  private topLiftInboundQueueStandbyTargetNodeId(
    vehicle: MutableVehicle,
    fromNodeId = vehicle.currentNodeId,
    options: { allowTaskedVehicle?: boolean; liftNodeId?: string } = {}
  ): string | null {
    if (!this.mixedTopLiftFlowEnabled() || vehicle.loaded || (!options.allowTaskedVehicle && vehicle.taskId)) {
      return null;
    }
    const inboundLifts = this.inboundLiftNodes();
    if (inboundLifts.length === 0) {
      return null;
    }
    const inboundDemandKnown =
      this.scenario.taskGeneration.inboundRatePerHour > 0 ||
      inboundLifts.some((lift) => this.topLiftInboundQueueReplenishDemand(lift.id) > 0);
    if (!inboundDemandKnown) {
      return null;
    }
    const vehicleOffset = (this.vehicleOrdinal(vehicle.id) - 1) % inboundLifts.length;
    const liftOrder = options.liftNodeId
      ? inboundLifts.filter((lift) => lift.id === options.liftNodeId)
      : inboundLifts
          .map((lift, index) => ({
            lift,
            depth: this.topLiftInboundQueueCoveredDepth(lift.id),
            demand: this.topLiftInboundQueueReserveDemand(lift.id),
            requiredDepth: this.topLiftInboundQueueReserveRequiredDepth(lift.id),
            offsetDistance: (index - vehicleOffset + inboundLifts.length) % inboundLifts.length
          }))
          .sort((left, right) =>
            right.demand - left.demand ||
            left.depth - right.depth ||
            left.offsetDistance - right.offsetDistance ||
            left.lift.id.localeCompare(right.lift.id)
          )
          .map(({ lift }) => lift);
    for (const lift of liftOrder) {
      if (this.topLiftInboundQueueCoveredDepth(lift.id) >= this.topLiftInboundQueueReserveRequiredDepth(lift.id)) {
        continue;
      }
      const candidateNodeIds = this.topLiftInboundApproachQueueNodeIds(lift.id);
      for (const nodeId of candidateNodeIds) {
        if (nodeId === fromNodeId || !this.topLiftInboundQueueStandbyNodeAvailable(vehicle, nodeId)) {
          continue;
        }
        return nodeId;
      }
    }
    return null;
  }

  private topLiftInboundQueueReplenishDemand(liftNodeId: string): number {
    const waitingSourceLoadCount = this.inboundLiftWaitingSourceLoads(liftNodeId).length;
    const activeInboundTaskCount = this.activeTasks().filter((task) =>
      task.kind === 'inbound' &&
      this.taskLiftPortNodeId(task) === liftNodeId &&
      !this.inboundQueuedTaskBlockedAwayFromLift(task)
    ).length;
    return waitingSourceLoadCount * 10 + activeInboundTaskCount;
  }

  private topLiftInboundQueueReserveDemand(liftNodeId: string): number {
    const actualDemand = this.topLiftInboundQueueReplenishDemand(liftNodeId);
    if (actualDemand > 0) {
      return actualDemand;
    }
    return this.topLiftInboundQueuePlannedMinimumReserveDepth(liftNodeId);
  }

  private topLiftInboundQueueReserveRequiredDepth(liftNodeId: string): number {
    return Math.min(
      this.topLiftInboundQueueReplenishTargetDepth(liftNodeId),
      this.topLiftInboundQueueReserveDemand(liftNodeId)
    );
  }

  private topLiftInboundQueuePlannedMinimumReserveDepth(liftNodeId: string): number {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      this.scenario.taskGeneration.inboundRatePerHour <= 0 ||
      this.liftPortKindForNodeId(liftNodeId) !== 'inbound' ||
      this.topLiftInboundApproachQueueNodeIds(liftNodeId).length === 0
    ) {
      return 0;
    }
    return 1;
  }

  private topLiftInboundQueueCoveredDepth(liftNodeId: string): number {
    return this.topLiftInboundQueueStandbyDepth(liftNodeId) + this.topLiftInboundActiveEmptyQueueDepth(liftNodeId);
  }

  private topLiftInboundStationReserveAdmissionCoverageDepth(liftNodeId: string): number {
    const vehicleIds = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (vehicle.loaded) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      if (
        task?.kind === 'inbound' &&
        this.taskLiftPortNodeId(task) === liftNodeId &&
        (task.state === 'assigned' || task.state === 'in-progress') &&
        this.topLiftInboundVehicleContributesQueueCoverage(vehicle, liftNodeId)
      ) {
        vehicleIds.add(vehicle.id);
        continue;
      }
      if (vehicle.taskId || vehicle.localRouteReason !== 'inbound-queue-standby') {
        continue;
      }
      const hasStationQueueLease = [
        vehicle.currentNodeId,
        vehicle.targetNodeId,
        vehicle.plannedGoalNodeId
      ].some((nodeId) =>
        this.topLiftInboundApproachQueueSlot(nodeId ?? '')?.liftNodeId === liftNodeId
      );
      if (hasStationQueueLease) {
        vehicleIds.add(vehicle.id);
      }
    }
    return vehicleIds.size;
  }

  private topLiftInboundQueueStandbyDepth(liftNodeId: string): number {
    return this.vehicles.filter((vehicle) => {
      if (vehicle.loaded || vehicle.taskId || vehicle.localRouteReason !== 'inbound-queue-standby') {
        return false;
      }
      return this.topLiftInboundVehicleContributesQueueCoverage(vehicle, liftNodeId);
    }).length;
  }

  private topLiftInboundQueueStandbyNodeAvailable(vehicle: MutableVehicle, nodeId: string): boolean {
    const slot = this.topLiftInboundApproachQueueSlot(nodeId);
    if (!slot) {
      return false;
    }
    return this.topLiftInboundQueueNodeHardClaimedByOtherVehicle(
      nodeId,
      vehicle.id,
      null,
      { includeTasklessStandbyPlannedGoal: true }
    ) === null;
  }

  private shadowStationCoordinatorCandidateReason(vehicle: MutableVehicle, liftNodeId: string): string {
    if (vehicle.taskId) {
      return 'busy-task';
    }
    if (vehicle.loaded) {
      return 'busy-loaded';
    }
    if (vehicle.currentEdgeId || vehicle.legRemainingM > 0 || vehicle.phaseRemainingSec > 0) {
      return 'busy-moving';
    }
    if (this.assignmentHoldActive(vehicle)) {
      return 'assignment-hold';
    }
    if (this.inboundDropoffStandbyHoldActive(vehicle)) {
      return 'inbound-dropoff-standby-hold';
    }
    if (!this.tasklessInboundQueueStandbyRerouteAllowed(vehicle)) {
      return 'standby-reroute-not-allowed';
    }
    const targetNodeId = this.topLiftInboundQueueStandbyTargetNodeId(vehicle, vehicle.currentNodeId, { liftNodeId });
    if (!targetNodeId) {
      return 'no-open-station-target';
    }
    const route = this.routeToInboundQueueStandby(vehicle, vehicle.currentNodeId, { liftNodeId });
    if (!route || route.length <= 1) {
      return 'no-station-route';
    }
    if (!this.tasklessInboundQueueStandbyRouteOriginAllowed(route)) {
      return 'route-origin-disallowed';
    }
    return 'dispatchable-reserve';
  }

  private shadowStationCoordinatorCandidateReasonCounts(liftNodeId: string): Record<string, number> {
    const counts: Record<string, number> = {};
    for (const vehicle of this.vehicles) {
      const reason = this.shadowStationCoordinatorCandidateReason(vehicle, liftNodeId);
      counts[reason] = (counts[reason] ?? 0) + 1;
    }
    return Object.fromEntries(Object.entries(counts).sort(([left], [right]) => left.localeCompare(right)));
  }

  private holdTasklessInboundQueueStandby(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.localRouteReason !== 'inbound-queue-standby' ||
      vehicle.plannedGoalNodeId !== nodeId ||
      !this.topLiftInboundApproachQueueSlot(nodeId)
    ) {
      return false;
    }
    this.clearTasklessRouteReservations(vehicle);
    vehicle.state = 'idle';
    vehicle.speedMps = 0;
    vehicle.routeNodeIds = [nodeId];
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = null;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.targetSpeedMps = 0;
    vehicle.plannedGoalNodeId = nodeId;
    vehicle.plannedRouteNodeIds = [nodeId];
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = 'inbound-queue-standby';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.directionSwitchReadyNodeId = null;
    return true;
  }

  private tryAdoptInboundQueueTaskAtCurrentSlot(vehicle: MutableVehicle): boolean {
    if (
      !this.mixedTopLiftFlowEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0
    ) {
      return false;
    }

    const queueSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    if (!queueSlot || this.liftPortKindForNodeId(queueSlot.liftNodeId) !== 'inbound') {
      return false;
    }

    const adoption = this.activeTasks()
      .filter((task) =>
        task.kind === 'inbound' &&
        task.state === 'assigned' &&
        task.startedAtSec === null &&
        task.vehicleId !== null &&
        task.vehicleId !== vehicle.id &&
        this.taskLiftPortNodeId(task) === queueSlot.liftNodeId
      )
      .map((task) => {
        const assignedVehicle = task.vehicleId
          ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) ?? null
          : null;
        return assignedVehicle ? { task, assignedVehicle } : null;
      })
      .filter((entry): entry is { task: TaskStateRecord; assignedVehicle: MutableVehicle } =>
        entry !== null &&
        !entry.assignedVehicle.loaded &&
        entry.assignedVehicle.currentEdgeId === null &&
        entry.assignedVehicle.legRemainingM <= 0 &&
        entry.assignedVehicle.phaseRemainingSec <= 0 &&
        this.assignedInboundVehicleClaimsQueueNode(entry.assignedVehicle, vehicle.currentNodeId, vehicle.id)
      )
      .sort((left, right) =>
        left.task.createdAtSec - right.task.createdAtSec ||
        left.task.id.localeCompare(right.task.id)
      )[0] ?? null;
    if (!adoption) {
      return false;
    }

    let route: string[];
    try {
      route = this.taskAssignmentRoute(vehicle, adoption.task);
    } catch {
      return false;
    }
    if (route.length === 0 || route[0] !== vehicle.currentNodeId) {
      return false;
    }

    const previousVehicle = adoption.assignedVehicle;
    const previousVehicleId = previousVehicle.id;
    const previousTargetNodeId = previousVehicle.targetNodeId;
    adoption.task.vehicleId = null;
    previousVehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(previousVehicle);
    const conflictSession = this.activeConflictSessionForPair(vehicle.id, previousVehicleId);
    if (conflictSession) {
      this.closeConflictSession(conflictSession, 'inbound-queue-reserve-adopted-task');
    }

    this.assignTaskToVehicle(vehicle, adoption.task, route);
    this.logEvent(
      'task-reassigned',
      vehicle.id,
      adoption.task.id,
      adoption.task.loadId,
      previousVehicle.currentNodeId,
      route.at(-1) ?? vehicle.currentNodeId,
      'inbound-queue-reserve-adopted-task',
      this.vehiclePosition(vehicle),
      {
        previousVehicleId,
        previousTargetNodeId,
        queueNodeId: vehicle.currentNodeId,
        route: route.join('>')
      }
    );

    if (!this.tryAssignQueuedTaskToVehicle(previousVehicle)) {
      this.dispatchTasklessToInboundQueueStandby(previousVehicle);
    }
    return true;
  }

  private tryAdoptOutboundStorageTaskBlockingActivePickup(vehicle: MutableVehicle): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !this.isStorageNode(vehicle.currentNodeId)
    ) {
      return false;
    }

    const adoption = this.activeTasks()
      .filter((task) =>
        task.kind === 'outbound' &&
        task.state === 'assigned' &&
        task.vehicleId !== null &&
        task.vehicleId !== vehicle.id &&
        task.completedAtSec === null &&
        this.isStorageNode(task.pickupNodeId)
      )
      .map((task) => {
        const assignedVehicle = task.vehicleId
          ? this.vehicles.find((candidate) => candidate.id === task.vehicleId) ?? null
          : null;
        if (!assignedVehicle || assignedVehicle.loaded) {
          return null;
        }
        const routeTail = this.vehicleRouteTail(assignedVehicle, assignedVehicle.routeNodeIds);
        const plannedTail = this.vehicleRouteTail(assignedVehicle, assignedVehicle.plannedRouteNodeIds);
        const route = routeTail.length >= plannedTail.length ? routeTail : plannedTail;
        const blockerIndex = route.indexOf(vehicle.currentNodeId);
        const pickupIndex = route.indexOf(task.pickupNodeId);
        if (blockerIndex < 0 || pickupIndex < 0 || blockerIndex >= pickupIndex) {
          return null;
        }
        if (
          assignedVehicle.blockingVehicleId !== vehicle.id &&
          assignedVehicle.targetNodeId !== vehicle.currentNodeId &&
          blockerIndex > 2
        ) {
          return null;
        }

        let adoptionRoute: string[];
        try {
          adoptionRoute = this.taskAssignmentRoute(vehicle, task);
        } catch {
          return null;
        }
        if (
          adoptionRoute.length === 0 ||
          adoptionRoute[0] !== vehicle.currentNodeId ||
          adoptionRoute.at(-1) !== this.taskDispatchGoalNodeId(task, vehicle) ||
          this.agentEmptyEscapeRouteCrossesStoredLoad(adoptionRoute, task.pickupNodeId)
        ) {
          return null;
        }
        let previousRemainingDistanceM: number;
        let adoptionDistanceM: number;
        try {
          previousRemainingDistanceM = this.routeDistanceM(route.slice(0, pickupIndex + 1));
          adoptionDistanceM = this.routeDistanceM(adoptionRoute);
        } catch {
          return null;
        }
        return { task, assignedVehicle, adoptionRoute, previousRemainingDistanceM, adoptionDistanceM };
      })
      .filter((entry): entry is {
        task: TaskStateRecord;
        assignedVehicle: MutableVehicle;
        adoptionRoute: string[];
        previousRemainingDistanceM: number;
        adoptionDistanceM: number;
      } => entry !== null)
      .sort((left, right) =>
        left.adoptionDistanceM - right.adoptionDistanceM ||
        left.previousRemainingDistanceM - right.previousRemainingDistanceM ||
        left.task.createdAtSec - right.task.createdAtSec ||
        left.task.id.localeCompare(right.task.id)
      )[0] ?? null;

    if (!adoption) {
      return false;
    }

    const previousVehicle = adoption.assignedVehicle;
    const previousVehicleId = previousVehicle.id;
    const previousTargetNodeId = previousVehicle.targetNodeId;
    adoption.task.vehicleId = null;
    adoption.task.waitReason = null;
    previousVehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(previousVehicle);
    const conflictSession = this.activeConflictSessionForPair(vehicle.id, previousVehicleId);
    if (conflictSession) {
      this.closeConflictSession(conflictSession, 'outbound-storage-blocker-adopted-task');
    }

    this.assignTaskToVehicle(vehicle, adoption.task, adoption.adoptionRoute);
    this.logEvent(
      'task-reassigned',
      vehicle.id,
      adoption.task.id,
      adoption.task.loadId,
      previousVehicle.currentNodeId,
      adoption.adoptionRoute.at(-1) ?? vehicle.currentNodeId,
      'outbound-storage-blocker-adopted-task',
      this.vehiclePosition(vehicle),
      {
        previousVehicleId,
        previousTargetNodeId,
        blockerNodeId: vehicle.currentNodeId,
        route: adoption.adoptionRoute.join('>')
      }
    );

    if (!this.tryAssignQueuedTaskToVehicle(previousVehicle)) {
      this.dispatchTasklessToInboundQueueStandby(previousVehicle);
    }
    return true;
  }

  private assignedInboundVehicleClaimsQueueNode(
    assignedVehicle: MutableVehicle,
    queueNodeId: string,
    queueVehicleId: string
  ): boolean {
    if (
      assignedVehicle.blockingVehicleId === queueVehicleId &&
      assignedVehicle.targetNodeId === queueNodeId
    ) {
      return true;
    }
    const claimedNodeIds = [
      assignedVehicle.targetNodeId,
      assignedVehicle.plannedGoalNodeId,
      ...this.vehicleRouteTail(assignedVehicle, assignedVehicle.routeNodeIds),
      ...this.vehicleRouteTail(assignedVehicle, assignedVehicle.plannedRouteNodeIds),
      ...this.vehicleRouteTail(assignedVehicle, assignedVehicle.localRouteNodeIds)
    ].filter((nodeId): nodeId is string => Boolean(nodeId));
    return claimedNodeIds.includes(queueNodeId);
  }

  private convertCompletedOutboundClearanceToInboundQueueStandby(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.localRouteReason !== 'outbound-lift-clearance' ||
      vehicle.plannedGoalNodeId !== nodeId ||
      !this.topLiftInboundReserveQueueSlot(nodeId)
    ) {
      return false;
    }
    vehicle.localRouteReason = 'inbound-queue-standby';
    vehicle.assignmentHoldUntilSec = null;
    vehicle.recentOutboundClearanceRouteNodeIds = [];
    return this.holdTasklessInboundQueueStandby(vehicle, nodeId);
  }

  private installTasklessPostDropoffRoute(
    vehicle: MutableVehicle,
    route: string[],
    reason = 'inbound-lift-near-storage-standby',
    localRouteReason = 'post-dropoff-column-exit'
  ): void {
    this.clearTasklessRouteReservations(vehicle);
    vehicle.state = 'assigned';
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = this.localClaimPrefixForRoute(vehicle.id, route);
    vehicle.localRouteReason = localRouteReason;
    vehicle.assignmentHoldUntilSec = localRouteReason === 'outbound-lift-clearance'
      ? round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + OUTBOUND_LIFT_CLEARANCE_ASSIGNMENT_HOLD_SEC)
      : null;
    vehicle.inboundDropoffStandbyHoldUntilSec = null;
    vehicle.recentOutboundClearanceRouteNodeIds = localRouteReason === 'outbound-lift-clearance'
      ? [...route]
      : [];
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.directionSwitchReadyNodeId = null;
    this.logEvent('vehicle-standby-dispatched', vehicle.id, null, null, vehicle.currentNodeId, route[route.length - 1] ?? null, reason, this.vehiclePosition(vehicle), {
      route: route.join('>')
    });
  }

  private extendPostDropoffExitRouteToStandby(
    vehicle: MutableVehicle,
    exitRoute: string[],
    forbiddenReturnNodeIds: Set<string> = new Set(),
    candidateRouteAllowed: (routeNodeIds: string[]) => boolean = () => true
  ): string[] | null {
    const exitNodeId = exitRoute.at(-1);
    if (!exitNodeId) {
      return this.topLiftRouteTerminatesOnColumnAccess(exitRoute) ? null : exitRoute;
    }
    for (const candidate of this.inboundStandbyNodeCandidates(vehicle.id)) {
      try {
        const standbyRoute = this.planStandbyRoute(exitNodeId, candidate.id);
        if (standbyRoute.slice(1).some((nodeId) => forbiddenReturnNodeIds.has(nodeId))) {
          continue;
        }
        if (
          standbyRoute.length > 1 &&
          this.postDropoffStandbyRouteAcceptable(standbyRoute) &&
          candidateRouteAllowed(standbyRoute)
        ) {
          return [...exitRoute, ...standbyRoute.slice(1)];
        }
      } catch {
        continue;
      }
    }
    return this.topLiftRouteTerminatesOnColumnAccess(exitRoute) ? null : exitRoute;
  }

  private postDropoffStandbyRouteAcceptable(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    const targetNodeId = routeNodeIds.at(-1);
    if (!targetNodeId || !this.isStorageNode(targetNodeId)) {
      return true;
    }

    let storageSuffixCount = 0;
    for (let index = routeNodeIds.length - 1; index >= 0; index -= 1) {
      if (!this.isStorageNode(routeNodeIds[index]!)) {
        break;
      }
      storageSuffixCount += 1;
    }
    return storageSuffixCount <= 4;
  }

  private localClaimPrefixForRoute(vehicleId: string, routeNodeIds: string[], maxNodeCount = 4): string[] {
    if (routeNodeIds.length < 2) {
      return [];
    }
    const prefix = [routeNodeIds[0]!];
    for (const nodeId of routeNodeIds.slice(1)) {
      if (prefix.length >= maxNodeCount) {
        break;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      const claimedByOtherId = this.nodeClaimedByOtherVehicle(nodeId, vehicleId);
      if ((occupantId && occupantId !== vehicleId) || claimedByOtherId) {
        break;
      }
      prefix.push(nodeId);
    }
    return prefix.length >= 2 ? prefix : [];
  }

  private postDropoffColumnExitRoute(vehicle: MutableVehicle): string[] | null {
    const fromNodeId = vehicle.currentNodeId;
    if (!this.topLiftColumnLayoutEnabled() || !this.isStorageNode(fromNodeId)) {
      return null;
    }
    const exitNodeIds = [
      this.storageSideNodeId(fromNodeId, 'left'),
      ...this.inboundStorageExitNodeCandidates(fromNodeId)
    ].filter((nodeId, index, nodeIds): nodeId is string =>
      nodeId !== null && nodeIds.indexOf(nodeId) === index
    );
    for (const exitNodeId of exitNodeIds) {
      if (exitNodeId === fromNodeId) {
        continue;
      }
      const route = this.topLiftDirectStorageColumnExitRoute(fromNodeId, exitNodeId);
      if (route && this.postDropoffColumnExitRouteClear(vehicle, route)) {
        const clearingRoute = this.extendTasklessTopLiftExitRouteOffNoStop(vehicle, route);
        if (clearingRoute && this.postDropoffColumnExitRouteClear(vehicle, clearingRoute)) {
          return clearingRoute;
        }
      }
    }
    return null;
  }

  private extendTasklessTopLiftExitRouteOffNoStop(
    vehicle: MutableVehicle,
    routeNodeIds: string[]
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || routeNodeIds.length < 2) {
      return routeNodeIds;
    }
    const terminalNodeId = routeNodeIds.at(-1)!;
    const terminalNode = this.layoutNode(terminalNodeId);
    if (terminalNode?.type === 'storage' && !this.topLiftTemporaryYieldStorageHoldAllowed(vehicle, terminalNodeId)) {
      return null;
    }
    if (!terminalNode?.noStop && !terminalNode?.noParking) {
      return routeNodeIds;
    }
    const holdRoute = this.extendTopLiftTemporaryYieldRouteToHold(vehicle, routeNodeIds);
    if (holdRoute && !this.topLiftRouteTerminatesOnColumnAccess(holdRoute)) {
      return holdRoute;
    }
    const standbyRoute = this.extendPostDropoffExitRouteToStandby(vehicle, routeNodeIds);
    return standbyRoute && !this.topLiftRouteTerminatesOnColumnAccess(standbyRoute)
      ? standbyRoute
      : null;
  }

  private postDropoffColumnExitRouteClear(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    for (const nodeId of routeNodeIds.slice(1)) {
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicle.id) {
        return false;
      }
      const claimantId = this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
      if (claimantId) {
        return false;
      }
      if (this.isStorageNode(nodeId) && nodeId !== vehicle.currentNodeId && this.storedLoadIdAtNode(nodeId)) {
        return false;
      }
    }
    return true;
  }

  private topLiftDirectStorageColumnExitRoute(fromNodeId: string, exitNodeId: string): string[] | null {
    const position = this.storageGridPosition(fromNodeId);
    const exitMatch = /^column-(top-b|middle|bottom-a)-c(\d+)$/.exec(exitNodeId);
    if (!position || !exitMatch || Number(exitMatch[2]) !== position.column) {
      return null;
    }

    const level = exitMatch[1] as 'top-b' | 'middle' | 'bottom-a';
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const totalRows = rowsPerZone * 2;
    const route = [fromNodeId];
    const addStorageRow = (row: number): void => {
      route.push(storageNodeId(row - 1, position.column - 1));
    };

    if (level === 'top-b' && position.row <= rowsPerZone) {
      for (let row = position.row - 1; row >= 1; row -= 1) {
        addStorageRow(row);
      }
    } else if (level === 'middle' && position.row <= rowsPerZone) {
      for (let row = position.row + 1; row <= rowsPerZone; row += 1) {
        addStorageRow(row);
      }
    } else if (level === 'middle' && position.row > rowsPerZone) {
      for (let row = position.row - 1; row >= rowsPerZone + 1; row -= 1) {
        addStorageRow(row);
      }
    } else if (level === 'bottom-a' && position.row > rowsPerZone) {
      for (let row = position.row + 1; row <= totalRows; row += 1) {
        addStorageRow(row);
      }
    } else {
      return null;
    }

    route.push(exitNodeId);
    if (route.some((nodeId) => !this.layoutNode(nodeId))) {
      return null;
    }
    for (let index = 1; index < route.length; index += 1) {
      if (!this.traffic.findEdge(route[index - 1]!, route[index]!)) {
        return null;
      }
    }
    return route;
  }

  private topLiftDirectStorageColumnStorageRoute(fromNodeId: string, targetNodeId: string): string[] | null {
    const fromPosition = this.storageGridPosition(fromNodeId);
    const targetPosition = this.storageGridPosition(targetNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !fromPosition ||
      !targetPosition ||
      fromPosition.column !== targetPosition.column
    ) {
      return null;
    }
    if (fromPosition.row === targetPosition.row) {
      return [fromNodeId];
    }

    const direction = Math.sign(targetPosition.row - fromPosition.row);
    const route = [fromNodeId];
    for (
      let row = fromPosition.row + direction;
      direction > 0 ? row <= targetPosition.row : row >= targetPosition.row;
      row += direction
    ) {
      route.push(storageNodeId(row - 1, fromPosition.column - 1));
    }

    if (route.some((nodeId) => !this.layoutNode(nodeId))) {
      return null;
    }
    for (let index = 1; index < route.length; index += 1) {
      if (!this.traffic.findEdge(route[index - 1]!, route[index]!)) {
        return null;
      }
      const nodeId = route[index]!;
      if (nodeId !== targetNodeId && this.storedLoadIdAtNode(nodeId)) {
        return null;
      }
    }
    return route;
  }

  private topLiftLoadedInboundDirectStorageColumnDropoffRoute(currentNodeId: string, task: TaskStateRecord): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound' || !this.isStorageNode(task.dropoffNodeId)) {
      return null;
    }
    const route = this.topLiftInboundSameColumnStorageRoute(currentNodeId, task.dropoffNodeId);
    if (!route || route.length <= 1) {
      return route;
    }
    const vehicleId = task.vehicleId ?? '';
    for (const nodeId of route.slice(1)) {
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicleId) {
        return null;
      }
      if (this.nodeClaimedByOtherVehicle(nodeId, vehicleId)) {
        return null;
      }
    }
    return route;
  }

  private topLiftInboundSameColumnStorageRoute(fromNodeId: string, targetNodeId: string): string[] | null {
    const fromPosition = this.storageGridPosition(fromNodeId);
    const targetPosition = this.storageGridPosition(targetNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !fromPosition ||
      !targetPosition ||
      fromPosition.column !== targetPosition.column
    ) {
      return null;
    }
    if (fromPosition.row === targetPosition.row) {
      return [fromNodeId];
    }

    const direction = Math.sign(targetPosition.row - fromPosition.row);
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const route = [fromNodeId];
    for (
      let row = fromPosition.row + direction;
      direction > 0 ? row <= targetPosition.row : row >= targetPosition.row;
      row += direction
    ) {
      const crossesMiddleAccess =
        (direction > 0 && row === rowsPerZone + 1) ||
        (direction < 0 && row === rowsPerZone);
      if (crossesMiddleAccess) {
        route.push(columnAccessNodeId('middle', fromPosition.column - 1));
      }
      route.push(storageNodeId(row - 1, fromPosition.column - 1));
    }

    if (route.some((nodeId) => !this.layoutNode(nodeId))) {
      return null;
    }
    for (let index = 1; index < route.length; index += 1) {
      if (!this.traffic.findEdge(route[index - 1]!, route[index]!)) {
        return null;
      }
      const nodeId = route[index]!;
      if (nodeId !== targetNodeId && this.storedLoadIdAtNode(nodeId)) {
        return null;
      }
    }
    return route;
  }

  private routeHasStoredLoadConflict(routeNodeIds: string[], allowedNodeIds = new Set<string>()): boolean {
    return routeNodeIds.some((nodeId) => !allowedNodeIds.has(nodeId) && this.storedLoadIdAtNode(nodeId) !== null);
  }

  private routeHasOtherVehicleStorageOccupancyConflict(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    allowedNodeIds = new Set<string>()
  ): boolean {
    return routeNodeIds.slice(1).some((nodeId) => {
      if (allowedNodeIds.has(nodeId) || !this.isStorageNode(nodeId)) {
        return false;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      return Boolean(occupantId && occupantId !== vehicle.id);
    });
  }

  private topLiftLoadedOutboundStorageExitNodeId(fromNodeId: string): string | null {
    return this.topLiftLoadedOutboundStorageExitRoute(fromNodeId)?.at(-1) ?? null;
  }

  private topLiftLoadedOutboundStorageExitRoute(fromNodeId: string): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || !this.isStorageNode(fromNodeId)) {
      return null;
    }
    const candidates = [
      this.storageSideNodeId(fromNodeId, 'left'),
      this.storageSideNodeId(fromNodeId, 'right')
    ].filter((nodeId, index, nodeIds): nodeId is string =>
      nodeId !== null && nodeIds.indexOf(nodeId) === index
    );

    for (const nodeId of candidates) {
        const directRoute = this.topLiftDirectStorageColumnExitRoute(fromNodeId, nodeId);
        if (directRoute && !this.routeHasStoredLoadConflict(directRoute, new Set([fromNodeId]))) {
          return directRoute;
        }
        try {
          const blockedNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, nodeId, { blockStoredLoads: true });
          blockedNodeIds.delete(fromNodeId);
          const route = this.agentRefreshShortestPath(fromNodeId, nodeId, blockedNodeIds);
          if (!this.routeHasStoredLoadConflict(route, new Set([fromNodeId]))) {
            return route;
          }
        } catch {
          continue;
        }
    }

    return null;
  }

  private routeToInboundStandby(vehicle: MutableVehicle): string[] | null {
    for (const candidate of this.inboundStandbyNodeCandidates(vehicle.id)) {
      try {
        const route = this.planStandbyRoute(vehicle.currentNodeId, candidate.id);
        if (route.length > 1) {
          return route;
        }
      } catch {
        continue;
      }
    }
    return null;
  }

  private planStandbyRoute(fromNodeId: string, targetNodeId: string, extraBlockedNodeIds = new Set<string>()): string[] {
    const route: string[] = [fromNodeId];
    const targets: Array<string | null> = this.isStorageNode(targetNodeId)
      ? this.isStorageNode(fromNodeId)
        ? [this.inboundStorageExitNodeId(fromNodeId), this.nearestStorageSideNodeId(targetNodeId), targetNodeId]
        : [this.nearestStorageSideNodeId(targetNodeId), targetNodeId]
      : this.isStorageNode(fromNodeId)
        ? [this.inboundStorageExitNodeId(fromNodeId), targetNodeId]
        : [targetNodeId];

    for (const target of targets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const current = route[route.length - 1]!;
      const blockedNodeIds = this.blockedStorageTransitNodeIds(current, target);
      for (const nodeId of extraBlockedNodeIds) {
        blockedNodeIds.add(nodeId);
      }
      blockedNodeIds.delete(current);
      blockedNodeIds.delete(target);
      const segment = this.shortestPath(current, target, blockedNodeIds);
      route.push(...segment.slice(1));
    }
    return route;
  }

  private inboundStandbyNodeCandidates(vehicleId: string): LayoutNode[] {
    const inboundLifts = this.inboundLiftNodes();
    if (inboundLifts.length === 0) {
      return [];
    }

    const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId) ?? null;
    const storageNodes = this.topLiftColumnLayoutEnabled()
      ? []
      : this.scenario.layout.nodes.filter((node): node is LayoutNode =>
          node.type === 'storage' && !node.noStop && !node.noParking && !this.isTopLiftStorageBankEntryRow(node.id)
        );
    const dedicatedParkingNodes = this.scenario.layout.nodes.filter((node): node is LayoutNode =>
      node.type === 'parking' && !node.noStop && !node.noParking
    );
    const standbyNodes = dedicatedParkingNodes.length > 0
      ? [...dedicatedParkingNodes, ...storageNodes]
      : storageNodes;
    const blockedDropoffNodeIds = this.activeInboundDropoffNodeIds();
    const blockedDropoffColumnKeys = this.activeTopLiftInboundColumnKeys();
    const storedLoadNodeIds = new Set(this.storageNodeLoadOccupancy(false).keys());
    const storedLoadColumnKeys = new Set(
      [...storedLoadNodeIds]
        .map((nodeId) => this.topLiftColumnKey(nodeId))
        .filter((columnKey): columnKey is string => columnKey !== null)
    );
    const claimedStandbyNodeIds = this.claimedTasklessParkableNodeIds(vehicleId);
    const claimedStandbyColumnKeys = this.claimedTasklessParkableColumnKeys(vehicleId);
    const vehicleOffset = (this.vehicleOrdinal(vehicleId) - 1) % inboundLifts.length;
    const liftOrder = inboundLifts.map((_, index) => inboundLifts[(index + vehicleOffset) % inboundLifts.length]!);
    const candidates: LayoutNode[] = [];
    const seenNodeIds = new Set<string>();

    for (const lift of liftOrder) {
      const rankedNodes = standbyNodes
        .filter((node) => node.id !== vehicle?.currentNodeId)
        .filter((node) => !storedLoadNodeIds.has(node.id))
        .filter((node) => !blockedDropoffNodeIds.has(node.id))
        .filter((node) => {
          const columnKey = this.topLiftColumnKey(node.id);
          return !columnKey || !blockedDropoffColumnKeys.has(columnKey);
        })
        .filter((node) => {
          const columnKey = this.topLiftColumnKey(node.id);
          return !columnKey || !storedLoadColumnKeys.has(columnKey);
        })
        .filter((node) => !claimedStandbyNodeIds.has(node.id))
        .filter((node) => {
          const columnKey = this.topLiftColumnKey(node.id);
          return !columnKey || !claimedStandbyColumnKeys.has(columnKey);
        })
        .filter((node) => {
          const occupantId = this.currentNodeOccupancy.get(node.id);
          return !occupantId || occupantId === vehicleId;
        })
        .map((node) => ({
          node,
          parkingRank: node.type === 'parking' ? 0 : 1,
          distanceM: Math.hypot(node.x - lift.x, node.z - lift.z)
        }))
        .sort((left, right) =>
          this.topLiftStandbyNodeRank(left.node) - this.topLiftStandbyNodeRank(right.node) ||
          left.parkingRank - right.parkingRank ||
          left.distanceM - right.distanceM ||
          left.node.id.localeCompare(right.node.id)
        );

      for (const ranked of rankedNodes) {
        if (seenNodeIds.has(ranked.node.id)) {
          continue;
        }
        seenNodeIds.add(ranked.node.id);
        candidates.push(ranked.node);
      }
    }

    return candidates;
  }

  private inboundLiftNodes(): LayoutNode[] {
    return this.scenario.layout.nodes
      .filter((node) => node.type === 'lift-blackbox' && node.liftKind === 'inbound')
      .sort((left, right) => left.id.localeCompare(right.id));
  }

  private outboundLiftNodes(): LayoutNode[] {
    return this.scenario.layout.nodes
      .filter((node) => node.type === 'lift-blackbox' && node.liftKind === 'outbound')
      .sort((left, right) => left.id.localeCompare(right.id));
  }

  private activeInboundDropoffNodeIds(): Set<string> {
    return new Set(
      this.activeTasks()
        .filter((task) =>
          task.kind === 'inbound' &&
          this.isStorageNode(task.dropoffNodeId)
        )
        .map((task) => task.dropoffNodeId)
    );
  }

  private activeMovingInboundDropoffNodeIds(): Set<string> {
    return new Set(
      this.activeTasks()
        .filter((task) =>
          task.kind === 'inbound' &&
          (task.state === 'assigned' || task.state === 'in-progress') &&
          this.isStorageNode(task.dropoffNodeId)
        )
        .map((task) => task.dropoffNodeId)
    );
  }

  private activeInboundDropoffColumnKeys(): Set<string> {
    const activeColumnKeys = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return activeColumnKeys;
    }
    for (const nodeId of this.activeInboundDropoffNodeIds()) {
      const columnKey = this.topLiftColumnKey(nodeId);
      if (columnKey) {
        activeColumnKeys.add(columnKey);
      }
    }
    return activeColumnKeys;
  }

  private activeTopLiftInboundColumnKeys(): Set<string> {
    const activeColumnKeys = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return activeColumnKeys;
    }

    for (const nodeId of this.activeInboundDropoffNodeIds()) {
      const columnKey = this.topLiftColumnKey(nodeId);
      if (columnKey) {
        activeColumnKeys.add(columnKey);
      }
    }

    for (const columnKey of this.clearingTopLiftColumnKeys()) {
      activeColumnKeys.add(columnKey);
    }

    for (const column of this.topLiftActiveOutboundTaskColumns()) {
      activeColumnKeys.add(`c${String(column).padStart(2, '0')}`);
    }

    return activeColumnKeys;
  }

  private activeTopLiftInboundTransitBlockedNodeIds(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    goalNodeId: string
  ): Set<string> {
    const blockedNodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return blockedNodeIds;
    }

    const activeColumnKeys = new Set<string>();
    for (const nodeId of this.activeMovingInboundDropoffNodeIds()) {
      const columnKey = this.topLiftColumnKey(nodeId);
      if (columnKey) {
        activeColumnKeys.add(columnKey);
      }
    }
    for (const columnKey of this.clearingTopLiftColumnKeys()) {
      activeColumnKeys.add(columnKey);
    }

    const protectedInboundNodeIds = this.activeTopLiftLoadedInboundProtectedNodeIds(vehicle.id);
    for (const nodeId of protectedInboundNodeIds) {
      blockedNodeIds.add(nodeId);
    }
    for (const nodeId of this.activeTopLiftInboundQueueExitProtectedNodeIds(vehicle.id)) {
      blockedNodeIds.add(nodeId);
    }

    if (activeColumnKeys.size === 0) {
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(goalNodeId);
      if (task) {
        blockedNodeIds.delete(task.pickupNodeId);
        blockedNodeIds.delete(task.dropoffNodeId);
      }
      return blockedNodeIds;
    }

    for (const node of this.scenario.layout.nodes) {
      const columnKey = this.topLiftColumnKey(node.id);
      if (
        columnKey &&
        activeColumnKeys.has(columnKey) &&
        (node.type === 'storage' || /^column-middle-c\d+$/.test(node.id))
      ) {
        blockedNodeIds.add(node.id);
      }
    }

    const currentColumnKey = this.topLiftColumnKey(vehicle.currentNodeId);
    if (currentColumnKey && activeColumnKeys.has(currentColumnKey)) {
      if (this.isStorageNode(vehicle.currentNodeId)) {
        const exitNodeId = this.topLiftNearestStorageColumnAccessNodeId(vehicle.currentNodeId);
        if (exitNodeId) {
          for (const nodeId of this.topLiftStorageColumnAccessClearanceNodeIds(vehicle.currentNodeId, exitNodeId)) {
            blockedNodeIds.delete(nodeId);
          }
        }
      }
    }

    blockedNodeIds.delete(vehicle.currentNodeId);
    blockedNodeIds.delete(goalNodeId);
    if (task) {
      blockedNodeIds.delete(task.pickupNodeId);
      blockedNodeIds.delete(task.dropoffNodeId);
    }
    return blockedNodeIds;
  }

  private activeTopLiftInboundQueueExitProtectedNodeIds(vehicleId: string): Set<string> {
    const protectedNodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return protectedNodeIds;
    }
    for (const requester of this.vehicles) {
      if (requester.id === vehicleId) {
        continue;
      }
      const task = this.taskForVehicle(requester);
      if (task?.kind !== 'inbound') {
        continue;
      }
      const protectedTargetNodeId = this.topLiftProtectedInboundQueueExitTargetNodeId(requester);
      if (!protectedTargetNodeId) {
        continue;
      }
      protectedNodeIds.add(protectedTargetNodeId);
      const displayNodeId = this.topLiftProjectedDisplayRailNodeId(requester.currentNodeId);
      if (displayNodeId) {
        protectedNodeIds.add(displayNodeId);
      }
    }
    return protectedNodeIds;
  }

  private topLiftStorageColumnAccessClearanceNodeIds(storageNodeId: string, accessNodeId: string): string[] {
    if (!this.topLiftColumnLayoutEnabled()) {
      return [];
    }
    const position = this.storageGridPosition(storageNodeId);
    const accessLevel = topLiftAisleLevel(accessNodeId);
    if (!position || !accessLevel) {
      return [];
    }

    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const maxRow = rowsPerZone * 2;
    const rowIds: number[] = [];
    if (accessLevel === 'top-a' || accessLevel === 'top-b') {
      for (let row = position.row; row >= 1; row -= 1) {
        rowIds.push(row);
      }
    } else if (accessLevel === 'middle') {
      if (position.row <= rowsPerZone) {
        for (let row = position.row; row <= rowsPerZone; row += 1) {
          rowIds.push(row);
        }
      } else {
        for (let row = position.row; row >= rowsPerZone + 1; row -= 1) {
          rowIds.push(row);
        }
      }
    } else if (accessLevel === 'bottom-a' || accessLevel === 'bottom-b') {
      for (let row = position.row; row <= maxRow; row += 1) {
        rowIds.push(row);
      }
    }

    const nodeIds = rowIds.map((row) => `storage-r${String(row).padStart(2, '0')}-c${String(position.column).padStart(2, '0')}`);
    nodeIds.push(accessNodeId);
    return nodeIds.filter((nodeId, index, ids) =>
      this.layoutNode(nodeId) !== null && ids.indexOf(nodeId) === index
    );
  }

  private activeTopLiftLoadedInboundProtectedNodeIds(requesterVehicleId: string): Set<string> {
    const protectedNodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return protectedNodeIds;
    }

    for (const vehicle of this.vehicles) {
      if (vehicle.id === requesterVehicleId || !vehicle.loaded) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      if (task?.kind !== 'inbound') {
        continue;
      }
      for (const nodeId of this.topLiftLoadedInboundProtectedRouteTail(vehicle, task)) {
        protectedNodeIds.add(nodeId);
      }
    }

    return protectedNodeIds;
  }

  private topLiftLoadedInboundProtectedRouteTail(vehicle: MutableVehicle, task: TaskStateRecord): string[] {
    const routeOptions = [
      this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
      [vehicle.currentNodeId, vehicle.targetNodeId].filter((nodeId): nodeId is string => nodeId !== null)
    ].filter((route) => route.length > 1);
    const route = routeOptions.find((candidate) => candidate.includes(task.dropoffNodeId)) ?? routeOptions[0];
    if (!route) {
      return [];
    }

    return this.topLiftProtectedInboundRouteNodeIds(route, task.dropoffNodeId);
  }

  private topLiftProtectedInboundRouteNodeIds(route: string[], dropoffNodeId: string): string[] {
    const dropoffIndex = route.indexOf(dropoffNodeId);
    const endIndex = dropoffIndex >= 1 ? dropoffIndex : Math.min(route.length - 1, 10);
    const protectedNodeIds = new Set<string>();
    const protectedRoute = route.slice(1, endIndex + 1);
    for (const nodeId of protectedRoute) {
      protectedNodeIds.add(nodeId);
    }

    const clearanceM = this.scenario.vehicles.widthM / 2 + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    for (let index = 1; index < protectedRoute.length; index += 1) {
      const fromNodeId = protectedRoute[index - 1]!;
      const toNodeId = protectedRoute[index]!;
      for (const nodeId of this.topLiftNodesNearSegment(fromNodeId, toNodeId, clearanceM)) {
        protectedNodeIds.add(nodeId);
      }
    }

    return [...protectedNodeIds];
  }

  private activeTopLiftInboundServiceProtectedNodeIds(requesterVehicleId: string): Set<string> {
    const protectedNodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return protectedNodeIds;
    }

    const clearanceM = this.scenario.vehicles.widthM / 2 + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    for (const vehicle of this.vehicles) {
      if (vehicle.id === requesterVehicleId || vehicle.loaded) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      const liftNodeId = task && task.kind === 'inbound' ? this.taskLiftPortNodeId(task) : null;
      if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
        continue;
      }
      const serviceNodeId = liftQueueServiceExitNodeId(liftNodeId, 1);
      const entryNodeId = liftQueueTailEntryNodeId(liftNodeId, 1);
      const routeTail = this.vehicleRouteTail(vehicle, vehicle.routeNodeIds);
      const activeNearService = [
        vehicle.currentNodeId,
        vehicle.targetNodeId,
        ...routeTail.slice(0, 4)
      ].some((nodeId) => nodeId === serviceNodeId);
      if (!activeNearService || !this.layoutNode(serviceNodeId) || !this.layoutNode(entryNodeId)) {
        continue;
      }
      protectedNodeIds.add(serviceNodeId);
      protectedNodeIds.add(entryNodeId);
      for (const nodeId of this.topLiftNodesNearSegment(serviceNodeId, entryNodeId, clearanceM)) {
        protectedNodeIds.add(nodeId);
      }
    }

    return protectedNodeIds;
  }

  private topLiftNodesNearSegment(fromNodeId: string, toNodeId: string, clearanceM: number): string[] {
    const fromNode = this.layoutNode(fromNodeId);
    const toNode = this.layoutNode(toNodeId);
    if (!fromNode || !toNode) {
      return [];
    }

    return this.scenario.layout.nodes
      .filter((node) =>
        node.id !== fromNodeId &&
        node.id !== toNodeId &&
        (
          this.topLiftColumnSpineOrAccessNode(node.id) ||
          this.isStorageNode(node.id) ||
          topLiftQueueEntrySlot(node.id) !== null ||
          topLiftQueueServiceSlot(node.id) !== null
        ) &&
        this.pointToSegmentDistanceM(node.x, node.z, fromNode.x, fromNode.z, toNode.x, toNode.z) <= clearanceM + 1e-6
      )
      .map((node) => node.id);
  }

  private clearingTopLiftColumnKeys(): Set<string> {
    const clearingColumnKeys = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return clearingColumnKeys;
    }

    for (const vehicle of this.vehicles) {
      if (vehicle.loaded || vehicle.taskId || vehicle.localRouteReason !== 'post-dropoff-column-exit') {
        continue;
      }
      for (const nodeId of [vehicle.currentNodeId, vehicle.targetNodeId]) {
        if (!nodeId) {
          continue;
        }
        const columnKey = this.topLiftColumnKey(nodeId);
        if (columnKey) {
          clearingColumnKeys.add(columnKey);
        }
      }
    }

    return clearingColumnKeys;
  }

  private claimedTasklessParkableNodeIds(vehicleId: string): Set<string> {
    const claimed = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (vehicle.id === vehicleId || vehicle.taskId || vehicle.loaded) {
        continue;
      }
      const routeTargetNodeId = vehicle.routeNodeIds.at(-1) ?? null;
      for (const nodeId of [vehicle.currentNodeId, vehicle.targetNodeId, routeTargetNodeId]) {
        const node = nodeId ? this.layoutNode(nodeId) : null;
        if (node && (node.type === 'storage' || node.type === 'parking')) {
          claimed.add(node.id);
        }
      }
    }
    return claimed;
  }

  private claimedTasklessParkableColumnKeys(vehicleId: string): Set<string> {
    const claimed = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return claimed;
    }
    for (const vehicle of this.vehicles) {
      if (vehicle.id === vehicleId || vehicle.taskId || vehicle.loaded) {
        continue;
      }
      const routeTargetNodeId = vehicle.routeNodeIds.at(-1) ?? null;
      for (const nodeId of [vehicle.currentNodeId, vehicle.targetNodeId, vehicle.plannedGoalNodeId, routeTargetNodeId]) {
        const node = nodeId ? this.layoutNode(nodeId) : null;
        const columnKey = node && (node.type === 'storage' || node.type === 'parking')
          ? this.topLiftColumnKey(node.id)
          : null;
        if (columnKey) {
          claimed.add(columnKey);
        }
      }
    }
    return claimed;
  }

  private isInboundOnlyFlow(): boolean {
    return this.scenario.taskGeneration.inboundRatePerHour > 0 && this.scenario.taskGeneration.outboundRatePerHour <= 0;
  }

  private topLiftColumnLayoutEnabled(): boolean {
    return isTopLiftColumnLayout(this.scenario);
  }

  private vehicleOrdinal(vehicleId: string): number {
    return Math.max(1, Number(vehicleId.replace(/\D+/g, '')) || 1);
  }

  private storageSideNodeId(storageNodeId: string, side: 'left' | 'right'): string | null {
    const match = /^storage-r(\d+)-c\d+$/.exec(storageNodeId);
    if (!match) {
      return null;
    }
    if (this.topLiftColumnLayoutEnabled()) {
      const position = this.storageGridPosition(storageNodeId);
      if (!position) {
        return null;
      }
      const rowsPerZone = this.topLiftColumnRowsPerZone();
      const upperBank = position.row <= rowsPerZone;
      const columnIndex = position.column - 1;
      const nodeId = upperBank
        ? side === 'right'
          ? columnAccessNodeId('top-b', columnIndex)
          : columnAccessNodeId('middle', columnIndex)
        : side === 'right'
          ? columnAccessNodeId('middle', columnIndex)
          : columnAccessNodeId('bottom-a', columnIndex);
      return this.layoutNodeIds.has(nodeId) ? nodeId : null;
    }
    const sideNodeId = `${side}-row-${match[1]}`;
    return this.layoutNodeIds.has(sideNodeId) ? sideNodeId : null;
  }

  private nearestStorageSideNodeId(storageNodeId: string): string | null {
    if (this.topLiftColumnLayoutEnabled()) {
      return this.storageSideNodeId(storageNodeId, 'right') ?? this.storageSideNodeId(storageNodeId, 'left');
    }
    const position = this.storageGridPosition(storageNodeId);
    if (!position) {
      return null;
    }
    const maxColumn = Math.max(
      position.column,
      ...this.scenario.layout.nodes
        .map((node) => this.storageGridPosition(node.id)?.column ?? 0)
    );
    const preferredSide = position.column <= (maxColumn + 1) / 2 ? 'left' : 'right';
    return this.storageSideNodeId(storageNodeId, preferredSide) ?? this.storageSideNodeId(storageNodeId, preferredSide === 'left' ? 'right' : 'left');
  }

  private blockedStorageTransitNodeIds(
    fromNodeId: string,
    targetNodeId: string,
    options: { blockStoredLoads?: boolean } = {}
  ): Set<string> {
    const cacheKey = `${fromNodeId}>${targetNodeId}`;
    let baseBlockedNodeIds = this.blockedStorageTransitBaseCache.get(cacheKey);
    if (!baseBlockedNodeIds) {
      const allowedNodeIds = new Set([fromNodeId, targetNodeId]);
      baseBlockedNodeIds = new Set<string>();
      const fromRowLabel = this.nodeStorageRowLabel(fromNodeId);
      const targetRowLabel = this.nodeStorageRowLabel(targetNodeId);
      const fromIsStorage = this.isStorageNode(fromNodeId);
      const targetIsStorage = this.isStorageNode(targetNodeId);
      const allowStorageTransitRows = new Set<string>();
      if (fromIsStorage && fromRowLabel) {
        allowStorageTransitRows.add(fromRowLabel);
      }
      if (targetIsStorage && targetRowLabel) {
        allowStorageTransitRows.add(targetRowLabel);
      }

      for (const nodeId of this.storageNodeIds) {
        const rowLabel = this.nodeStorageRowLabel(nodeId);
        if (!allowedNodeIds.has(nodeId) && (!rowLabel || !allowStorageTransitRows.has(rowLabel))) {
          baseBlockedNodeIds.add(nodeId);
        }
      }
      this.blockedStorageTransitBaseCache.set(cacheKey, baseBlockedNodeIds);
    }

    const blockedNodeIds = new Set(baseBlockedNodeIds);
    if (options.blockStoredLoads) {
      const allowedNodeIds = new Set([fromNodeId, targetNodeId]);
      for (const [nodeId] of this.storageNodeLoadOccupancy(false)) {
        if (!allowedNodeIds.has(nodeId)) {
          blockedNodeIds.add(nodeId);
        }
      }
    }

    return blockedNodeIds;
  }

  private shortestPath(fromNodeId: string, toNodeId: string, blockedNodeIds = new Set<string>()): string[] {
    if (fromNodeId === toNodeId) {
      return [fromNodeId];
    }

    const open = new MinPriorityQueue();
    const cameFrom = new Map<string, string>();
    const gScore = new Map<string, number>([[fromNodeId, 0]]);
    open.push({ nodeId: fromNodeId, priority: 0 });

    while (open.size > 0) {
      const next = open.pop();
      if (!next) {
        break;
      }
      const current = next.nodeId;
      if (next.priority > (gScore.get(current) ?? Infinity) + 1e-9) {
        continue;
      }
      if (current === toNodeId) {
        const path = [current];
        while (cameFrom.has(path[0]!)) {
          path.unshift(cameFrom.get(path[0]!)!);
        }
        return path;
      }

      for (const neighbor of this.neighbors(current)) {
        if (blockedNodeIds.has(neighbor.nodeId)) {
          continue;
        }
        if (this.topLiftColumnLayoutEnabled() && !this.agentEdgeDirectionAllowed(current, neighbor.nodeId, toNodeId)) {
          continue;
        }
        if (this.topLiftColumnLayoutEnabled() && !this.topLiftOperationalEdgeAllowed(current, neighbor.nodeId, toNodeId)) {
          continue;
        }
        if (neighbor.nodeId !== toNodeId && this.layoutNode(neighbor.nodeId)?.type === 'lift-blackbox') {
          continue;
        }
        const tentative = (gScore.get(current) ?? Infinity) + this.agentEdgeCostM(current, neighbor.nodeId, neighbor.lengthM, toNodeId);
        if (tentative < (gScore.get(neighbor.nodeId) ?? Infinity)) {
          cameFrom.set(neighbor.nodeId, current);
          gScore.set(neighbor.nodeId, tentative);
          open.push({ nodeId: neighbor.nodeId, priority: tentative });
        }
      }
    }

    throw new Error(`No route between ${fromNodeId} and ${toNodeId}`);
  }

  private agentShortestPath(fromNodeId: string, toNodeId: string, blockedNodeIds = new Set<string>()): string[] {
    if (fromNodeId === toNodeId) {
      return [fromNodeId];
    }

    const open = new MinPriorityQueue();
    const cameFrom = new Map<string, string>();
    const gScore = new Map<string, number>([[fromNodeId, 0]]);
    open.push({ nodeId: fromNodeId, priority: 0 });

    while (open.size > 0) {
      const next = open.pop();
      if (!next) {
        break;
      }
      const current = next.nodeId;
      if (next.priority > (gScore.get(current) ?? Infinity) + 1e-9) {
        continue;
      }
      if (current === toNodeId) {
        const path = [current];
        while (cameFrom.has(path[0]!)) {
          path.unshift(cameFrom.get(path[0]!)!);
        }
        return path;
      }

      for (const neighbor of this.agentNeighbors(current, toNodeId)) {
        if (blockedNodeIds.has(neighbor.nodeId)) {
          continue;
        }
        if (neighbor.nodeId !== toNodeId && this.layoutNode(neighbor.nodeId)?.type === 'lift-blackbox') {
          continue;
        }
        const tentative = (gScore.get(current) ?? Infinity) + this.agentEdgeCostM(current, neighbor.nodeId, neighbor.lengthM, toNodeId);
        if (tentative < (gScore.get(neighbor.nodeId) ?? Infinity)) {
          cameFrom.set(neighbor.nodeId, current);
          gScore.set(neighbor.nodeId, tentative);
          open.push({ nodeId: neighbor.nodeId, priority: tentative });
        }
      }
    }

    throw new Error(`No route between ${fromNodeId} and ${toNodeId}`);
  }

  private neighbors(nodeId: string): Array<{ nodeId: string; lengthM: number }> {
    return this.neighborByNodeId.get(nodeId) ?? [];
  }

  private agentNeighbors(nodeId: string, goalNodeId: string): Array<{ nodeId: string; lengthM: number }> {
    return this.neighbors(nodeId)
      .filter((neighbor) => this.agentLiftStorageTransferAllowed(nodeId, neighbor.nodeId, goalNodeId))
      .filter((neighbor) => this.topLiftOperationalEdgeAllowed(nodeId, neighbor.nodeId, goalNodeId))
      .filter((neighbor) => this.agentEdgeDirectionAllowed(nodeId, neighbor.nodeId, goalNodeId))
      .map((neighbor) => ({
        ...neighbor,
        lengthM: this.agentEdgeCostM(nodeId, neighbor.nodeId, neighbor.lengthM, goalNodeId)
      }));
  }

  private topLiftOperationalLiftNodeId(nodeId: string): string | null {
    const queueSlot = topLiftQueueParkingSlot(nodeId);
    if (queueSlot) {
      return queueSlot.liftNodeId;
    }
    const queueAccess = topLiftQueueAisleAccess(nodeId);
    if (queueAccess) {
      return queueAccess.liftNodeId;
    }
    const queueEntry = topLiftQueueEntrySlot(nodeId);
    if (queueEntry) {
      return queueEntry.liftNodeId;
    }
    const queueService = topLiftQueueServiceSlot(nodeId);
    if (queueService) {
      return queueService.liftNodeId;
    }
    const buffer = liftBufferParentNodeId(nodeId);
    if (buffer) {
      return buffer.liftNodeId;
    }
    const direct = /^(lift-\d{2}-(?:inbound|outbound))(?:$|-throat|-buffer-access|-queue-access)$/.exec(nodeId);
    return direct?.[1] ?? null;
  }

  private topLiftOperationalEdgeAllowed(fromNodeId: string, toNodeId: string, goalNodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    const fromLiftNodeId = this.topLiftOperationalLiftNodeId(fromNodeId);
    const toLiftNodeId = this.topLiftOperationalLiftNodeId(toNodeId);
    if (!fromLiftNodeId && !toLiftNodeId) {
      return true;
    }
    const edgeLiftNodeId = fromLiftNodeId ?? toLiftNodeId;
    if (!edgeLiftNodeId || (fromLiftNodeId && toLiftNodeId && fromLiftNodeId !== toLiftNodeId)) {
      return false;
    }
    const goalLiftNodeId = this.topLiftOperationalLiftNodeId(goalNodeId);
    if (goalLiftNodeId === edgeLiftNodeId) {
      return true;
    }
    if (fromLiftNodeId === edgeLiftNodeId) {
      return true;
    }
    return false;
  }

  private agentLiftStorageTransferAllowed(fromNodeId: string, toNodeId: string, goalNodeId: string): boolean {
    const fromTransferLiftId = this.liftStorageTransferTargetLiftId(fromNodeId);
    const toTransferLiftId = this.liftStorageTransferTargetLiftId(toNodeId);
    if (toTransferLiftId && toTransferLiftId !== goalNodeId) {
      return false;
    }
    if (fromTransferLiftId && this.layoutNode(toNodeId)?.type === 'lift-blackbox' && fromTransferLiftId !== goalNodeId) {
      return false;
    }
    return true;
  }

  private liftStorageTransferTargetLiftId(nodeId: string): string | null {
    const match = /^(.*)-row-\d{2}-transfer$/.exec(nodeId);
    return match?.[1] ?? null;
  }

  private agentEdgeCostM(fromNodeId: string, toNodeId: string, lengthM: number, goalNodeId: string): number {
    if (this.topLiftColumnLayoutEnabled()) {
      const goalNode = this.layoutNode(goalNodeId);
      if (
        goalNode?.type !== 'storage' &&
        goalNodeId !== fromNodeId &&
        goalNodeId !== toNodeId &&
        (this.isStorageNode(fromNodeId) || this.isStorageNode(toNodeId))
      ) {
        return lengthM + 8;
      }
      const liftPortTransit = (nodeId: string): boolean => /^lift-\d+-(?:inbound|outbound)(?:$|-)/.test(nodeId);
      if (
        (liftPortTransit(fromNodeId) || liftPortTransit(toNodeId)) &&
        goalNodeId !== fromNodeId &&
        goalNodeId !== toNodeId
      ) {
        return lengthM + 5;
      }
      const goalLiftNodeId = this.topLiftOperationalLiftNodeId(goalNodeId);
      if (
        goalLiftNodeId &&
        this.liftPortKindForNodeId(goalLiftNodeId) === 'outbound' &&
        topLiftAisleLevel(fromNodeId) === 'top-b' &&
        topLiftAisleLevel(toNodeId) === 'top-b'
      ) {
        return lengthM + 12;
      }
      if (
        goalLiftNodeId &&
        this.liftPortKindForNodeId(goalLiftNodeId) === 'inbound' &&
        topLiftAisleLevel(fromNodeId) === 'top-a' &&
        topLiftAisleLevel(toNodeId) === 'top-a'
      ) {
        return lengthM + 12;
      }
      if (
        goalNode?.type !== 'storage' &&
        goalNodeId !== fromNodeId &&
        goalNodeId !== toNodeId &&
        (isTopLiftAisleLevelNodeId(fromNodeId, 'middle') || isTopLiftAisleLevelNodeId(toNodeId, 'middle'))
      ) {
        return lengthM + 20;
      }
    }
    const edgeKey = [fromNodeId, toNodeId].sort().join('>');
    if (
      (edgeKey === 'left-top>right-top' || edgeKey === 'left-bottom>right-bottom') &&
      goalNodeId !== fromNodeId &&
      goalNodeId !== toNodeId
    ) {
      return lengthM + 1000;
    }
    return lengthM;
  }

  private topLiftDoubleLaneDirectionAllowed(fromNodeId: string, toNodeId: string): boolean | null {
    const fromLevel = topLiftAisleLevel(fromNodeId);
    const toLevel = topLiftAisleLevel(toNodeId);
    if (!fromLevel || fromLevel !== toLevel || fromLevel === 'middle') {
      return null;
    }
    return true;
  }

  private agentEdgeDirectionAllowed(fromNodeId: string, toNodeId: string, goalNodeId: string): boolean {
    if (this.topLiftColumnLayoutEnabled()) {
      if (toNodeId === goalNodeId) {
        return true;
      }
      return this.topLiftDoubleLaneDirectionAllowed(fromNodeId, toNodeId) ?? true;
    }
    const fromMain = /^main-(north|south)-(\d+)$/.exec(fromNodeId);
    const toMain = /^main-(north|south)-(\d+)$/.exec(toNodeId);
    if (!fromMain || !toMain || fromMain[1] !== toMain[1]) {
      return true;
    }
    const fromIndex = Number(fromMain[2]);
    const toIndex = Number(toMain[2]);
    const preferredDirection = fromMain[1] === 'north' ? toIndex >= fromIndex : toIndex <= fromIndex;
    if (preferredDirection) {
      return true;
    }
    const goalNode = this.layoutNode(goalNodeId);
    const goalIsLiftPort = goalNode?.type === 'inbound' || goalNode?.type === 'outbound' || goalNode?.type === 'lift-blackbox';
    return goalIsLiftPort && this.neighbors(toNodeId).some((neighbor) => neighbor.nodeId === goalNodeId);
  }

  private rebuildGraphNeighbors(): void {
    const nodes = new Set(this.scenario.layout.nodes.map((node) => node.id));
    const byNode = new Map<string, Array<{ nodeId: string; lengthM: number }>>();
    const addNeighbor = (from: string, to: string, lengthM: number): void => {
      if (!nodes.has(from) || !nodes.has(to)) {
        return;
      }
      const neighbors = byNode.get(from) ?? [];
      neighbors.push({ nodeId: to, lengthM });
      byNode.set(from, neighbors);
    };

    for (const edge of this.scenario.layout.edges) {
      if (!this.isAllowedStorageTraversalEdge(edge)) {
        continue;
      }
      addNeighbor(edge.from, edge.to, edge.lengthM);
      if (edge.directionMode === 'twoWay') {
        addNeighbor(edge.to, edge.from, edge.lengthM);
      }
    }

    this.neighborByNodeId = new Map(
      [...byNode.entries()].map(([id, neighbors]) => [
        id,
        neighbors.sort((left, right) => left.nodeId.localeCompare(right.nodeId))
      ])
    );
  }

  private isAllowedStorageTraversalEdge(edge: LayoutEdge): boolean {
    if (!this.isStorageNode(edge.from) || !this.isStorageNode(edge.to)) {
      return true;
    }
    return this.nodeStorageRowLabel(edge.from) === this.nodeStorageRowLabel(edge.to);
  }

  private parkingNodeFor(vehicleId: string): string {
    const parkingNodes = this.parkableNodeCandidates();
    if (parkingNodes.length === 0) {
      const fallbackNode = this.scenario.layout.nodes.find((node) => !node.noParking && !node.noStop) ?? this.scenario.layout.nodes[0];
      if (!fallbackNode) {
        throw new Error('Scenario has no nodes available for vehicle parking.');
      }
      return fallbackNode.id;
    }
    const vehicleNumber = Number(vehicleId.replace(/\D+/g, '')) || 1;
    return parkingNodes[(vehicleNumber - 1) % parkingNodes.length]!.id;
  }

  private parkableNodeCandidates(): ShuttleScenario['layout']['nodes'] {
    const isParkableStorage = (node: ShuttleScenario['layout']['nodes'][number]): boolean =>
      node.type === 'storage' && !node.noStop && !node.noParking;
    const dedicatedParking = this.scenario.layout.nodes
      .filter((node) => node.type === 'parking' && !node.noStop && !node.noParking)
      .sort((left, right) => {
        const parkingRank = (nodeId: string): number => isTopLiftQueueParkingNodeId(nodeId) ? 0 : nodeId.startsWith('parking-') ? 1 : 2;
        return parkingRank(left.id) - parkingRank(right.id) || left.id.localeCompare(right.id);
      });
    const temporaryStorageParking = this.scenario.layout.nodes
      .filter(isParkableStorage)
      .filter((node) => !this.isTopLiftStorageBankEntryRow(node.id))
      .sort((left, right) => {
        const leftPosition = this.storageGridPosition(left.id);
        const rightPosition = this.storageGridPosition(right.id);
        return (
          (leftPosition?.column ?? 0) - (rightPosition?.column ?? 0) ||
          (rightPosition?.row ?? 0) - (leftPosition?.row ?? 0) ||
          left.id.localeCompare(right.id)
        );
      });
    if (this.isInboundOnlyFlow()) {
      const inboundStandbyStorage = this.inboundInitialParkingCandidates(temporaryStorageParking);
      const standbyIds = new Set(inboundStandbyStorage.map((node) => node.id));
      const initialSkuParkingBlockedColumns = this.topLiftInitialSkuParkingBlockedColumns();
      const blocksInitialSkuColumn = (node: ShuttleScenario['layout']['nodes'][number]): boolean =>
        initialSkuParkingBlockedColumns.has(this.storageGridPosition(node.id)?.column ?? 0);
      const overflowStorage = this.spreadTopLiftStorageParkingCandidates(
        temporaryStorageParking.filter((node) => !standbyIds.has(node.id) && !blocksInitialSkuColumn(node))
      );
      const lastResortInitialSkuStorage = this.spreadTopLiftStorageParkingCandidates(
        temporaryStorageParking.filter((node) => !standbyIds.has(node.id) && blocksInitialSkuColumn(node))
      );
      return [
        ...inboundStandbyStorage,
        ...overflowStorage,
        ...dedicatedParking,
        ...lastResortInitialSkuStorage
      ];
    }
    if (this.topLiftColumnLayoutEnabled()) {
      const initialSkuParkingBlockedColumns = this.topLiftInitialSkuParkingBlockedColumns();
      const blocksInitialSkuColumn = (node: ShuttleScenario['layout']['nodes'][number]): boolean =>
        initialSkuParkingBlockedColumns.has(this.storageGridPosition(node.id)?.column ?? 0);
      const inboundApproachQueueNodes = this.mixedTopLiftFlowEnabled()
        ? this.inboundLiftNodes()
            .flatMap((liftNode) => this.topLiftInboundApproachQueueNodeIds(liftNode.id))
            .map((nodeId) => this.layoutNode(nodeId))
            .filter((node): node is ShuttleScenario['layout']['nodes'][number] => node !== null)
        : [];
      const inGridStandbyStorage = this.spreadTopLiftStorageParkingCandidates(
        temporaryStorageParking.filter((node) => !blocksInitialSkuColumn(node))
      );
      const lastResortInitialSkuStorage = this.spreadTopLiftStorageParkingCandidates(
        temporaryStorageParking.filter(blocksInitialSkuColumn)
      );
      const inboundQueueParking = dedicatedParking.filter((node) => {
        const slot = topLiftQueueParkingSlot(node.id);
        return Boolean(slot && this.liftPortKindForNodeId(slot.liftNodeId) === 'inbound');
      });
      const otherDedicatedParking = dedicatedParking.filter((node) => !inboundQueueParking.includes(node));
      if (this.mixedTopLiftFlowEnabled()) {
        return [
          ...inboundApproachQueueNodes,
          ...inboundQueueParking,
          ...inGridStandbyStorage,
          ...otherDedicatedParking,
          ...lastResortInitialSkuStorage
        ];
      }
      return [
        ...inGridStandbyStorage,
        ...dedicatedParking,
        ...lastResortInitialSkuStorage
      ];
    }
    return [...dedicatedParking, ...temporaryStorageParking];
  }

  private spreadTopLiftStorageParkingCandidates(nodes: ShuttleScenario['layout']['nodes']): ShuttleScenario['layout']['nodes'] {
    const byColumn = new Map<number, ShuttleScenario['layout']['nodes']>();
    for (const node of nodes) {
      const position = this.storageGridPosition(node.id);
      if (!position) {
        continue;
      }
      const columnNodes = byColumn.get(position.column) ?? [];
      columnNodes.push(node);
      byColumn.set(position.column, columnNodes);
    }
    for (const columnNodes of byColumn.values()) {
      columnNodes.sort((left, right) => {
        const leftPosition = this.storageGridPosition(left.id);
        const rightPosition = this.storageGridPosition(right.id);
        return (
          (rightPosition?.row ?? 0) - (leftPosition?.row ?? 0) ||
          left.id.localeCompare(right.id)
        );
      });
    }
    const columns = [...byColumn.keys()].sort((left, right) => left - right);
    const spread: ShuttleScenario['layout']['nodes'] = [];
    let depthIndex = 0;
    while (true) {
      let added = false;
      for (const column of columns) {
        const node = byColumn.get(column)?.[depthIndex];
        if (node) {
          spread.push(node);
          added = true;
        }
      }
      if (!added) {
        break;
      }
      depthIndex += 1;
    }
    return spread;
  }

  private topLiftStandbyNodeRank(node: LayoutNode): number {
    if (isTopLiftQueueParkingNodeId(node.id)) {
      return 0;
    }
    if (node.type === 'storage') {
      return 1;
    }
    if (node.type === 'parking') {
      return 2;
    }
    return 3;
  }

  private inboundInitialParkingCandidates(storageNodes: ShuttleScenario['layout']['nodes']): ShuttleScenario['layout']['nodes'] {
    const inboundLifts = this.inboundLiftNodes();
    if (inboundLifts.length === 0 || storageNodes.length === 0) {
      return [];
    }

    const initialSkuParkingBlockedColumns = this.topLiftInitialSkuParkingBlockedColumns();
    const candidateStorageNodes = initialSkuParkingBlockedColumns.size === 0
      ? storageNodes
      : storageNodes.filter((node) => !initialSkuParkingBlockedColumns.has(this.storageGridPosition(node.id)?.column ?? 0));
    const candidates: ShuttleScenario['layout']['nodes'] = [];
    const seenNodeIds = new Set<string>();
    for (const lift of inboundLifts) {
      const ranked = candidateStorageNodes
        .filter((node) => !seenNodeIds.has(node.id))
        .map((node) => ({
          node,
          distanceM: Math.abs(node.x - lift.x) + Math.abs(node.z - lift.z)
        }))
        .sort((left, right) => left.distanceM - right.distanceM || left.node.id.localeCompare(right.node.id));
      const selected = ranked[0]?.node;
      if (selected) {
        seenNodeIds.add(selected.id);
        candidates.push(selected);
      }
    }

    return candidates;
  }

  private zonesForNode(nodeId: string): ShuttleScenario['layout']['zones'] {
    return this.scenario.layout.zones.filter((zone) => zone.nodeIds.includes(nodeId));
  }

  private axisForEdge(edge: ShuttleScenario['layout']['edges'][number]): MovementAxis {
    const from = nodePosition(this.scenario, edge.from);
    const to = nodePosition(this.scenario, edge.to);
    const dx = Math.abs(to.x - from.x);
    const dz = Math.abs(to.z - from.z);
    if (dx <= 1e-9 && dz <= 1e-9) {
      return null;
    }
    return dx >= dz ? 'x' : 'z';
  }

  private axisBetweenNodes(fromNodeId: string, toNodeId: string): MovementAxis {
    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    return edge ? this.axisForEdge(edge) : null;
  }

  private routeTerminalAxis(routeNodeIds: string[], fallbackAxis: MovementAxis = null): MovementAxis {
    for (let index = routeNodeIds.length - 1; index >= 1; index -= 1) {
      const axis = this.axisBetweenNodes(routeNodeIds[index - 1]!, routeNodeIds[index]!);
      if (axis) {
        return axis;
      }
    }
    return fallbackAxis;
  }

  private turnPenaltyCostM(previousAxis: MovementAxis, nextAxis: MovementAxis): number {
    if (!previousAxis || !nextAxis || previousAxis === nextAxis) {
      return 0;
    }
    const speedEquivalentMps = Math.max(
      this.scenario.physicsParams.loadedSpeedMps,
      this.scenario.physicsParams.emptySpeedMps
    );
    return this.scenario.physicsParams.switchDirectionSec * speedEquivalentMps;
  }

  private releaseNodeOccupancy(vehicle: MutableVehicle, nodeId: string): void {
    if (this.currentNodeOccupancy.get(nodeId) === vehicle.id) {
      this.currentNodeOccupancy.delete(nodeId);
    }
    this.releaseZoneHoldReservations(vehicle);
  }

  private occupyNode(vehicle: MutableVehicle, nodeId: string): void {
    for (const [occupiedNodeId, occupantId] of [...this.currentNodeOccupancy.entries()]) {
      if (occupantId === vehicle.id && occupiedNodeId !== nodeId) {
        this.currentNodeOccupancy.delete(occupiedNodeId);
      }
    }
    this.currentNodeOccupancy.set(nodeId, vehicle.id);
    this.ensureZoneHoldReservation(vehicle, nodeId);
  }

  private ensureZoneHoldReservation(vehicle: MutableVehicle, nodeId: string): void {
    if (this.agentSimpleEnabled()) {
      return;
    }
    this.releaseZoneHoldReservations(vehicle);
    const holdZones = this.zonesForNode(nodeId).filter((zone) => zone.noStop || zone.noParking);
    if (holdZones.length === 0) {
      return;
    }
    const startTimeSec = this.simTimeSec;
    const endTimeSec = round(
      this.simTimeSec + Math.max(this.scenario.timeStepSec, this.scenario.trafficPolicy.minimumClearanceSec) + 1e-6
    );
    const priority = this.priorityFor(vehicle);
    for (const zone of holdZones) {
      this.installLocalZoneHoldReservation(ReservationSchema.parse({
        id: `local-hold-${vehicle.id}-${zone.id}-${String(Math.round(this.simTimeSec * 1000)).padStart(8, '0')}`,
        resourceType: 'zone',
        resourceId: zone.id,
        vehicleId: vehicle.id,
        taskId: vehicle.taskId,
        startTimeSec,
        endTimeSec,
        priority,
        conflictGroup: zone.conflictGroup ?? null,
        reasonCode: 'local-zone-occupancy'
      }));
    }
  }

  private installLocalZoneHoldReservation(hold: Reservation): void {
    let installedHold = hold;
    const retained: Reservation[] = [];
    for (const existing of this.reservations) {
      const conflicts =
        this.reservationWindowsOverlap(existing, installedHold) &&
        this.reservationsShareBlockingResource(existing, installedHold);
      if (!conflicts) {
        retained.push(existing);
        continue;
      }
      if (
        existing.vehicleId === installedHold.vehicleId &&
        this.reservationsShareExactResource(existing, installedHold)
      ) {
        installedHold = this.mergeSelfReservationWindows(existing, installedHold);
        continue;
      }
      if (existing.reasonCode !== 'local-zone-occupancy') {
        continue;
      }
      retained.push(existing);
    }
    this.reservations = [...retained, installedHold];
  }

  private releaseZoneHoldReservations(vehicle: MutableVehicle): void {
    this.reservations = this.reservations.filter(
      (reservation) =>
        !(
          (reservation.reasonCode === 'zone-hold' || reservation.reasonCode === 'local-zone-occupancy') &&
          reservation.vehicleId === vehicle.id &&
          reservation.resourceType === 'zone'
        )
    );
  }

  private shouldLogVehicleWait(
    vehicle: MutableVehicle,
    targetNodeId: string,
    waitReason: string,
    blockingReservationId: string | null,
    blockingVehicleId: string | null
  ): boolean {
    return (
      vehicle.state !== 'waiting-blocked' ||
      vehicle.targetNodeId !== targetNodeId ||
      vehicle.waitReason !== waitReason ||
      vehicle.blockingReservationId !== blockingReservationId ||
      vehicle.blockingVehicleId !== blockingVehicleId
    );
  }

  private predictedFootprintOverlapVehicleId(
    vehicle: MutableVehicle,
    x: number,
    z: number,
    ignoredVehicleIds = new Set<string>()
  ): string | null {
    const predictedPose = { x, z, yaw: vehicle.yaw };
    const blocker = this.vehicles.find((other) =>
      other.id !== vehicle.id &&
      !ignoredVehicleIds.has(other.id) &&
      !this.topLiftProjectedQueuePocketInternalMoveIgnoresFootprintBlocker(vehicle, other) &&
      vehicleFootprintsOverlap(predictedPose, other, this.scenario.vehicles)
    );
    return blocker?.id ?? null;
  }

  private predictedSweptFootprintOverlapVehicleId(
    vehicle: MutableVehicle,
    fromX: number,
    fromZ: number,
    toX: number,
    toZ: number,
    ignoredVehicleIds = new Set<string>()
  ): string | null {
    const distanceM = Math.hypot(toX - fromX, toZ - fromZ);
    const sampleSpacingM = Math.max(0.05, Math.min(0.2, this.scenario.vehicles.lengthM / 4));
    const steps = Math.max(1, Math.ceil(distanceM / sampleSpacingM));
    for (let step = 1; step <= steps; step += 1) {
      const ratio = step / steps;
      const x = round(fromX + (toX - fromX) * ratio);
      const z = round(fromZ + (toZ - fromZ) * ratio);
      const blockerId = this.predictedFootprintOverlapVehicleId(vehicle, x, z, ignoredVehicleIds);
      if (blockerId) {
        return blockerId;
      }
    }
    return null;
  }

  private advanceVehicles(dtSec: number): void {
    if (this.agentSimpleEnabled()) {
      this.advanceVehiclesAgentSimple(dtSec);
      return;
    }

    const sortedVehicles = [...this.vehicles].sort((left, right) => left.id.localeCompare(right.id));
    for (const vehicle of sortedVehicles) {
      if (vehicle.state === 'idle' && !vehicle.taskId && !vehicle.loaded) {
        if (this.tryAdoptOutboundStorageTaskBlockingActivePickup(vehicle)) {
          continue;
        }
        if (this.tryAdoptInboundQueueTaskAtCurrentSlot(vehicle)) {
          continue;
        }
        this.holdTasklessInboundQueueStandby(vehicle, vehicle.currentNodeId);
        vehicle.idleTimeSec = round(vehicle.idleTimeSec + dtSec);
        continue;
      }
      vehicle.busyTimeSec = round(vehicle.busyTimeSec + dtSec);
      this.accrueVehicleWorkBreakdown(vehicle, dtSec);

      if (vehicle.state === 'lifting' || vehicle.state === 'lowering' || vehicle.state === 'parking') {
        this.advanceTimedPhase(vehicle, dtSec);
        continue;
      }

      if (!vehicle.currentEdgeId && vehicle.legRemainingM <= 0 && vehicle.phaseRemainingSec > 0) {
        this.advanceDirectionSwitchPhase(vehicle, dtSec);
        continue;
      }

      if (vehicle.currentEdgeId || vehicle.legRemainingM > 0) {
        this.advanceMovement(vehicle, dtSec);
        continue;
      }

      this.startNextLeg(vehicle, dtSec);
    }
  }

  private advanceVehiclesAgentSimple(dtSec: number): void {
    const vehicles = [...this.vehicles].sort((left, right) =>
      this.agentTurnPriority(right) - this.agentTurnPriority(left) ||
      left.id.localeCompare(right.id)
    );

    for (const vehicle of vehicles) {
      if (vehicle.state === 'idle' && !vehicle.taskId && !vehicle.loaded) {
        if (this.tryAdoptOutboundStorageTaskBlockingActivePickup(vehicle)) {
          continue;
        }
        if (this.tryAdoptInboundQueueTaskAtCurrentSlot(vehicle)) {
          continue;
        }
        if (
          (this.topLiftTasklessVehicleBlocksInboundColumn(vehicle) ||
            this.topLiftTasklessVehicleBlocksActiveRoute(vehicle)) &&
          this.dispatchTasklessTopLiftStorageExit(vehicle)
        ) {
          continue;
        }
        if (this.convertCompletedOutboundClearanceToInboundQueueStandby(vehicle, vehicle.currentNodeId)) {
          vehicle.idleTimeSec = round(vehicle.idleTimeSec + dtSec);
          continue;
        }
        if (this.holdTasklessInboundQueueStandby(vehicle, vehicle.currentNodeId)) {
          vehicle.idleTimeSec = round(vehicle.idleTimeSec + dtSec);
          continue;
        }
        if (this.topLiftColumnLayoutEnabled() && this.layoutNode(vehicle.currentNodeId)?.noParking) {
          this.startNextLegAgentSimple(vehicle, dtSec);
          continue;
        }
        vehicle.idleTimeSec = round(vehicle.idleTimeSec + dtSec);
        continue;
      }

      vehicle.busyTimeSec = round(vehicle.busyTimeSec + dtSec);
      this.accrueVehicleWorkBreakdown(vehicle, dtSec);

      if (vehicle.state === 'lifting' || vehicle.state === 'lowering' || vehicle.state === 'parking') {
        this.advanceTimedPhase(vehicle, dtSec);
        continue;
      }

      if (!vehicle.currentEdgeId && vehicle.legRemainingM <= 0 && vehicle.phaseRemainingSec > 0) {
        this.advanceDirectionSwitchPhase(vehicle, dtSec);
        continue;
      }

      if (vehicle.currentEdgeId || vehicle.legRemainingM > 0) {
        this.advanceMovement(vehicle, dtSec);
        continue;
      }

      this.startNextLegAgentSimple(vehicle, dtSec);
    }
  }

  private accrueVehicleWorkBreakdown(vehicle: MutableVehicle, dtSec: number): void {
    const moving =
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.state === 'moving-to-pickup' ||
      vehicle.state === 'loaded-moving' ||
      vehicle.state === 'returning';
    if (moving) {
      vehicle.movingTimeSec = round(vehicle.movingTimeSec + dtSec);
    }
    if (vehicle.state === 'lifting' || vehicle.state === 'lowering') {
      vehicle.handlingTimeSec = round(vehicle.handlingTimeSec + dtSec);
    }
    if (!vehicle.taskId && !vehicle.loaded && (moving || vehicle.state === 'assigned' || vehicle.state === 'returning')) {
      vehicle.tasklessTravelTimeSec = round(vehicle.tasklessTravelTimeSec + dtSec);
      if (vehicle.localRouteReason === 'inbound-queue-standby') {
        vehicle.queueReserveTravelTimeSec = round(vehicle.queueReserveTravelTimeSec + dtSec);
      }
    }
  }

  private advanceTimedPhase(vehicle: MutableVehicle, dtSec: number): void {
    vehicle.phaseRemainingSec = round(Math.max(0, vehicle.phaseRemainingSec - dtSec));
    vehicle.speedMps = 0;
    if (vehicle.phaseRemainingSec > 0) {
      return;
    }

    const task = this.taskById(vehicle.taskId);
    if (vehicle.state === 'lifting' && task) {
      vehicle.loaded = true;
      const load = this.loadById(task.loadId);
      if (load) {
        this.setLoadPlacement(load, 'carried', null, vehicle.id);
      }
      vehicle.state = 'assigned';
      this.logEvent('lift-complete', vehicle.id, task.id, task.loadId, task.pickupNodeId, vehicle.currentNodeId, 'lift-time-elapsed', this.vehiclePosition(vehicle), {});
      const loadedDispatchGoalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
      if (this.agentRefreshEnabled()) {
        let route: string[];
        try {
          route = this.installAgentRefreshPlannedRoute(vehicle, task, loadedDispatchGoalNodeId);
        } catch {
          if (this.tryRetargetLoadedInboundToReachableDropoff(vehicle, task, loadedDispatchGoalNodeId)) {
            return;
          }
          this.agentSetWaiting(
            vehicle,
            loadedDispatchGoalNodeId,
            { reason: 'route-unavailable', blockingVehicleId: null },
            dtSec
          );
          return;
        }
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.directionSwitchReadyNodeId = null;
        this.logEvent('route-replanned', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, route.at(-1) ?? null, 'loaded-shortest-path', this.vehiclePosition(vehicle), {
          route: route.join('>')
        });
        return;
      }
      if (this.agentMinimalEnabled()) {
        const route = this.installAgentTaskRoute(vehicle, task, loadedDispatchGoalNodeId);
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.directionSwitchReadyNodeId = null;
        this.logEvent('route-replanned', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, route.at(-1) ?? null, 'loaded-shortest-path', this.vehiclePosition(vehicle), {
          route: route.join('>')
        });
        return;
      }
      if (this.agentSimpleEnabled()) {
        this.resetNavigationAtCurrentNode(vehicle);
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.directionSwitchReadyNodeId = null;
        return;
      }
      const directLoadedRoute = this.planLoadedRouteToDropoff(vehicle.currentNodeId, task);
      vehicle.routeNodeIds = directLoadedRoute;
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = directLoadedRoute[1] ?? null;
      vehicle.directionSwitchReadyNodeId = null;
      this.logEvent('route-replanned', vehicle.id, task.id, task.loadId, vehicle.currentNodeId, directLoadedRoute.at(-1) ?? null, 'loaded-shortest-path', this.vehiclePosition(vehicle), {
        route: directLoadedRoute.join('>')
      });
      return;
    }

    if (vehicle.state === 'lowering' && task) {
      vehicle.loaded = false;
      const load = this.loadById(task.loadId);
      if (load) {
        this.setLoadPlacement(
          load,
          task.kind === 'inbound' ? 'stored' : 'delivered',
          task.kind === 'inbound' ? task.dropoffNodeId : null,
          null
        );
      }
      this.setTaskState(task, 'completed');
      task.completedAtSec = this.simTimeSec;
      this.completedTaskCycleTimes.push(task.completedAtSec - task.createdAtSec);
      this.completedTaskWaitTimes.push((task.assignedAtSec ?? task.createdAtSec) - task.createdAtSec);
      if (task.kind === 'inbound') this.completedInbound += 1;
      if (task.kind === 'outbound') this.completedOutbound += 1;
      this.recordLiftPortCompletion(task);
      this.refreshTopLiftColumnFlowModes();
      this.logEvent('task-completed', vehicle.id, task.id, task.loadId, task.pickupNodeId, task.dropoffNodeId, 'lower-complete', this.vehiclePosition(vehicle), {
        kind: task.kind
      });
      vehicle.taskId = null;
      if (this.dispatchVehicleAfterOutboundDropoff(vehicle, task)) {
        return;
      }
      if (this.agentSimpleModeEnabled()) {
        this.clearTasklessRouteReservations(vehicle);
        vehicle.state = 'idle';
        this.resetNavigationAtCurrentNode(vehicle);
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.directionSwitchReadyNodeId = null;
        return;
      }
      if (task.kind === 'inbound' && this.isStorageNode(vehicle.currentNodeId)) {
        vehicle.inboundDropoffStandbyHoldUntilSec = round(this.simTimeSec + INBOUND_DROPOFF_STANDBY_GRACE_SEC);
        if (this.dispatchVehicleAfterInboundDropoff(vehicle)) {
          return;
        }
        vehicle.state = 'idle';
        vehicle.routeNodeIds = [vehicle.currentNodeId];
        vehicle.routeIndex = 0;
        vehicle.targetNodeId = null;
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.directionSwitchReadyNodeId = null;
        return;
      }
      if (this.tryAssignQueuedTaskToVehicle(vehicle)) {
        return;
      }
      vehicle.state = 'assigned';
      return;
    }

    if (vehicle.state === 'parking') {
      vehicle.state = 'idle';
      vehicle.routeNodeIds = [];
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = null;
      vehicle.currentEdgeId = null;
      vehicle.legRemainingM = 0;
      vehicle.legElapsedSec = 0;
      vehicle.legTravelSec = 0;
      vehicle.phaseRemainingSec = 0;
      vehicle.targetSpeedMps = 0;
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      vehicle.plannedGoalNodeId = null;
      vehicle.plannedRouteNodeIds = [];
      vehicle.localRouteNodeIds = [];
      vehicle.localRouteReason = null;
      vehicle.yieldHoldUntilSec = null;
      vehicle.yieldHoldNodeId = null;
      vehicle.directionSwitchReadyNodeId = null;
      this.logEvent('vehicle-parked', vehicle.id, null, null, vehicle.currentNodeId, null, 'idle-parking', this.vehiclePosition(vehicle), {});
    }
  }

  private advanceDirectionSwitchPhase(vehicle: MutableVehicle, dtSec: number): void {
    vehicle.phaseRemainingSec = round(Math.max(0, vehicle.phaseRemainingSec - dtSec));
    vehicle.speedMps = 0;
    if (vehicle.phaseRemainingSec > 0) {
      return;
    }

    vehicle.directionSwitchReadyNodeId = vehicle.currentNodeId;
    this.logEvent('direction-switch-complete', vehicle.id, vehicle.taskId, null, vehicle.currentNodeId, vehicle.targetNodeId, 'switch-direction-elapsed', this.vehiclePosition(vehicle), {});
  }

  private startNextLegAgentSimple(vehicle: MutableVehicle, dtSec: number): void {
    const fromNodeId = vehicle.currentNodeId;
    const task = this.taskForVehicle(vehicle);

    if (this.redirectTopLiftQueueAccessToParking(vehicle)) {
      this.startNextLegAgentSimple(vehicle, dtSec);
      return;
    }

    const activeInboundPickupClearance =
      task &&
      fromNodeId === task.pickupNodeId &&
      !vehicle.loaded &&
      this.inboundPickupClearanceRouteActive(vehicle, task) &&
      (this.inboundTaskShouldWaitBeforePickup(task) || !this.inboundTaskLoadReadyAtPickup(task));
    if (activeInboundPickupClearance) {
      this.syncActiveInboundPickupClearanceRoute(vehicle, task);
    } else if (task && fromNodeId === task.pickupNodeId && !vehicle.loaded) {
      if (this.holdInboundPickupBeforePredecessor(vehicle, task, dtSec)) {
        return;
      }
      this.promoteInboundTaskSourceLoadToFront(task);
      if (!this.inboundTaskLoadReadyAtPickup(task)) {
        if (!this.inboundPickupClearanceRouteActive(vehicle, task)) {
          this.waitForInboundPickupLoad(vehicle, task, dtSec);
          return;
        }
        this.syncActiveInboundPickupClearanceRoute(vehicle, task);
        return;
      }
      this.startInboundPickupLift(vehicle, task, fromNodeId);
      return;
    }

    if (task && fromNodeId === task.dropoffNodeId && vehicle.loaded) {
      vehicle.state = 'lowering';
      vehicle.speedMps = 0;
      vehicle.phaseRemainingSec = this.scenario.physicsParams.lowerTimeSec;
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      this.logEvent('lower-started', vehicle.id, task.id, task.loadId, fromNodeId, fromNodeId, 'dropoff-aligned', this.vehiclePosition(vehicle), {});
      return;
    }

    if (
      (this.agentMinimalEnabled() || this.agentRefreshEnabled()) &&
      vehicle.yieldHoldUntilSec !== null &&
      (vehicle.yieldHoldNodeId === null || vehicle.yieldHoldNodeId === fromNodeId)
    ) {
      const refreshHoldBlock = this.agentRefreshYieldHoldBlocker(vehicle, task);
      if (this.agentRefreshEnabled()) {
        if (refreshHoldBlock) {
          this.agentSetWaiting(
            vehicle,
            vehicle.routeNodeIds[vehicle.routeIndex + 1] ?? fromNodeId,
            refreshHoldBlock,
            dtSec
          );
          return;
        }
        vehicle.yieldHoldUntilSec = null;
        vehicle.yieldHoldNodeId = null;
      } else if (this.simTimeSec < vehicle.yieldHoldUntilSec || refreshHoldBlock) {
        this.agentSetWaiting(
          vehicle,
          vehicle.routeNodeIds[vehicle.routeIndex + 1] ?? fromNodeId,
          refreshHoldBlock ?? { reason: 'local-yield-hold', blockingVehicleId: null },
          dtSec
        );
        return;
      }
      if (!this.agentRefreshEnabled()) {
        vehicle.yieldHoldUntilSec = null;
        vehicle.yieldHoldNodeId = null;
      }
    }

    if (task && this.tryYieldUnreadyInboundQueueLeader(vehicle, task)) {
      this.startNextLegAgentSimple(vehicle, dtSec);
      return;
    }

    if (task && this.tryAdvanceInboundPickupTopAHoldAway(vehicle, task)) {
      this.startNextLegAgentSimple(vehicle, dtSec);
      return;
    }

    const goalNodeId = this.agentGoalNodeId(vehicle, task);
    const committedLocalRouteAtGoal = this.agentRefreshEnabled() && goalNodeId === fromNodeId
      ? this.agentRefreshCommittedLocalRoute(vehicle, goalNodeId)
      : null;
    if (task && goalNodeId === fromNodeId && !committedLocalRouteAtGoal && this.topLiftInboundQueueHoldActive(task, vehicle)) {
      this.holdAtTopLiftQueueNode(vehicle, fromNodeId, this.topLiftInboundQueueHoldReason(task), dtSec);
      return;
    }
    if (task && goalNodeId === fromNodeId && !committedLocalRouteAtGoal && this.topLiftOutboundMeterHoldActive(task, vehicle)) {
      this.holdAtTopLiftQueueNode(vehicle, fromNodeId, 'outbound-lift-fifo-wait', dtSec);
      return;
    }
    if (!goalNodeId || (goalNodeId === fromNodeId && !committedLocalRouteAtGoal)) {
      if (
        !task &&
        (this.topLiftTasklessVehicleBlocksInboundColumn(vehicle) ||
          this.topLiftTasklessVehicleBlocksActiveRoute(vehicle)) &&
        this.dispatchTasklessTopLiftStorageExit(vehicle)
      ) {
        return;
      }
      if (!task && this.topLiftColumnLayoutEnabled() && this.layoutNode(fromNodeId)?.noParking) {
        if (this.convertCompletedOutboundClearanceToInboundQueueStandby(vehicle, fromNodeId)) {
          return;
        }
        if (this.holdTasklessInboundQueueStandby(vehicle, fromNodeId)) {
          return;
        }
        if (this.topLiftOutboundClearanceHoldAllowed(vehicle)) {
          this.clearTasklessRouteReservations(vehicle);
          vehicle.state = 'idle';
          vehicle.routeNodeIds = [vehicle.currentNodeId];
          vehicle.routeIndex = 0;
          vehicle.targetNodeId = null;
          vehicle.currentEdgeId = null;
          vehicle.legRemainingM = 0;
          vehicle.legElapsedSec = 0;
          vehicle.legTravelSec = 0;
          vehicle.targetSpeedMps = 0;
          vehicle.plannedGoalNodeId = vehicle.currentNodeId;
          vehicle.plannedRouteNodeIds = [vehicle.currentNodeId];
          vehicle.localRouteNodeIds = [];
          vehicle.localRouteReason = 'outbound-lift-clearance-hold';
          vehicle.waitReason = null;
          vehicle.blockingReservationId = null;
          vehicle.blockingVehicleId = null;
          vehicle.directionSwitchReadyNodeId = null;
          return;
        }
        if (!this.isInboundOnlyFlow()) {
          if (this.dispatchTasklessNoParkingClearance(vehicle)) {
            return;
          }
        }
        const standbyRoute = this.routeToInboundStandby(vehicle);
        if (standbyRoute && standbyRoute.length > 1 && !this.topLiftRouteTerminatesOnColumnAccess(standbyRoute)) {
          const nextStandbyNodeId = standbyRoute[1] ?? null;
          const standbyBlock = nextStandbyNodeId && this.collisionAvoidanceEnabled()
            ? this.agentRefreshMoveBlocker(vehicle, nextStandbyNodeId, standbyRoute)
            : null;
          if (nextStandbyNodeId && standbyBlock) {
            this.agentSetWaiting(vehicle, nextStandbyNodeId, standbyBlock, dtSec);
            return;
          }
          vehicle.state = 'assigned';
          vehicle.routeNodeIds = standbyRoute;
          vehicle.routeIndex = 0;
          vehicle.targetNodeId = nextStandbyNodeId;
          vehicle.currentEdgeId = null;
          vehicle.legRemainingM = 0;
          vehicle.waitReason = null;
          vehicle.blockingReservationId = null;
          vehicle.blockingVehicleId = null;
          vehicle.plannedGoalNodeId = null;
          vehicle.plannedRouteNodeIds = [];
          vehicle.localRouteNodeIds = [];
          vehicle.localRouteReason = null;
          return;
        }
        this.clearTasklessRouteReservations(vehicle);
        vehicle.state = 'waiting-blocked';
        vehicle.speedMps = 0;
        vehicle.routeNodeIds = [];
        vehicle.routeIndex = 0;
        vehicle.targetNodeId = null;
        vehicle.currentEdgeId = null;
        vehicle.legRemainingM = 0;
        vehicle.waitReason = 'standby-unavailable';
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        vehicle.waitingSinceSec ??= this.simTimeSec;
        vehicle.plannedGoalNodeId = null;
        vehicle.plannedRouteNodeIds = [];
        vehicle.localRouteNodeIds = [];
        vehicle.localRouteReason = null;
        this.blockedTimeByReasonSec.set('standby-unavailable', round((this.blockedTimeByReasonSec.get('standby-unavailable') ?? 0) + dtSec));
        return;
      }
      vehicle.state = vehicle.taskId ? 'assigned' : 'idle';
      vehicle.routeNodeIds = [fromNodeId];
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = null;
      vehicle.currentEdgeId = null;
      vehicle.legRemainingM = 0;
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      vehicle.plannedGoalNodeId = null;
      vehicle.plannedRouteNodeIds = [];
      vehicle.localRouteNodeIds = [];
      vehicle.localRouteReason = null;
      return;
    }

    let route: string[];
    try {
      route = committedLocalRouteAtGoal ?? this.agentRouteToGoal(vehicle, task, goalNodeId);
    } catch {
      const flushedStorageBlocker = task
        ? this.tryFlushEmptyStorageBlockerOnLoadedInboundColumnRoute(vehicle, task)
        : null;
      if (flushedStorageBlocker) {
        this.agentSetWaiting(
          vehicle,
          flushedStorageBlocker.nodeId,
          { reason: 'node-occupied', blockingVehicleId: flushedStorageBlocker.blockerId },
          dtSec
        );
        return;
      }
      if (task && this.tryRetargetLoadedInboundToReachableDropoff(vehicle, task, goalNodeId)) {
        return;
      }
      if (task && this.tryClearInboundTopASpineRouteUnavailable(vehicle, task)) {
        return;
      }
      if (task && this.tryRecoverRouteUnavailableOutboundStoragePickup(vehicle, task, goalNodeId)) {
        return;
      }
      if (task && this.tryReleaseRouteUnavailableOutboundPickupTaskInStorage(vehicle, task, goalNodeId)) {
        return;
      }
      if (task && this.tryReleaseRouteUnavailableOutboundPickupTaskAtAisle(vehicle, task, goalNodeId)) {
        return;
      }
      if (task && this.tryReassignRouteUnavailableInboundPickupTask(vehicle, task, goalNodeId)) {
        return;
      }
      if (!task && this.topLiftColumnLayoutEnabled() && !vehicle.loaded && this.isStorageNode(vehicle.currentNodeId)) {
        this.resetNavigationAtCurrentNode(vehicle);
        vehicle.state = 'idle';
        this.dispatchTasklessTopLiftStorageExit(vehicle);
        return;
      }
      this.agentSetWaiting(
        vehicle,
        this.routeUnavailableWaitTargetNodeId(vehicle, task, goalNodeId),
        { reason: 'route-unavailable', blockingVehicleId: null },
        dtSec
      );
      return;
    }

    let toNodeId = route[1];
    if (!toNodeId) {
      if (task) {
        const recoveredRoute = this.restoreMissingTaskRouteAtCurrentNode(vehicle, task, 'agent-task-route-missing-recovered');
        if (recoveredRoute?.[1]) {
          route = recoveredRoute;
          toNodeId = recoveredRoute[1];
        } else if (this.tryRetargetLoadedInboundToReachableDropoff(vehicle, task, goalNodeId)) {
          return;
        } else if (this.tryClearInboundTopASpineRouteUnavailable(vehicle, task)) {
          return;
        } else if (this.tryRecoverRouteUnavailableOutboundStoragePickup(vehicle, task, goalNodeId)) {
          return;
        } else if (this.tryReleaseRouteUnavailableOutboundPickupTaskInStorage(vehicle, task, goalNodeId)) {
          return;
        } else if (this.tryReleaseRouteUnavailableOutboundPickupTaskAtAisle(vehicle, task, goalNodeId)) {
          return;
        } else if (this.tryReassignRouteUnavailableInboundPickupTask(vehicle, task, goalNodeId)) {
          return;
        }
      }
    }
    if (!toNodeId) {
      if (task) {
        this.agentSetWaiting(
          vehicle,
          this.routeUnavailableWaitTargetNodeId(vehicle, task, goalNodeId),
          { reason: 'route-unavailable', blockingVehicleId: null },
          dtSec
        );
        return;
      }
      vehicle.state = vehicle.taskId ? 'assigned' : 'idle';
      vehicle.routeNodeIds = [fromNodeId];
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = null;
      vehicle.plannedGoalNodeId = null;
      vehicle.plannedRouteNodeIds = [];
      vehicle.localRouteNodeIds = [];
      vehicle.localRouteReason = null;
      return;
    }

    let storageLoadBlock = this.loadedStorageLoadBlock(vehicle, toNodeId);
    if (
      storageLoadBlock &&
      this.agentRefreshEnabled() &&
      vehicle.loaded &&
      task?.kind === 'outbound'
    ) {
      try {
        route = this.installAgentRefreshPlannedRoute(vehicle, task, goalNodeId);
        toNodeId = route[1];
        storageLoadBlock = toNodeId ? this.loadedStorageLoadBlock(vehicle, toNodeId) : storageLoadBlock;
      } catch {
        // Keep the original wait reason below.
      }
    }
    if (storageLoadBlock) {
      this.agentSetWaiting(vehicle, toNodeId, storageLoadBlock, dtSec);
      return;
    }
    if (!toNodeId) {
      this.agentSetWaiting(
        vehicle,
        vehicle.routeNodeIds[1] ?? vehicle.targetNodeId ?? goalNodeId,
        { reason: 'route-unavailable', blockingVehicleId: null },
        dtSec
      );
      return;
    }

    const storageExitBlock = this.agentMinimalStorageExitLookaheadBlocker(vehicle, route);
    if (storageExitBlock) {
      this.agentSetWaiting(vehicle, toNodeId, storageExitBlock, dtSec);
      return;
    }

    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = toNodeId;

    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (!edge) {
      vehicle.state = 'faulted';
      vehicle.waitReason = 'route-edge-missing';
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      this.error = `Missing route edge ${fromNodeId} -> ${toNodeId}`;
      this.logEvent('vehicle-faulted', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, 'route-edge-missing', this.vehiclePosition(vehicle), {});
      return;
    }

    const block = this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, toNodeId)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, toNodeId)
          : this.agentMoveBlocker(vehicle, toNodeId)
      : null;
    if (block) {
      if (task && this.tryRetargetLoadedInboundAroundTasklessDropoffBlocker(vehicle, task, block)) {
        return;
      }
      if (!task && this.rerouteTasklessStandbyAroundBlockedTarget(vehicle, toNodeId)) {
        return;
      }
      if (block.reason === 'no-stop-continuation-blocked' && this.tryExtendAgentRefreshNoStopContinuation(vehicle, toNodeId)) {
        return;
      }
      if (
        task &&
        this.agentRefreshEnabled() &&
        this.tryAdvanceTopAHoldAwayFromQueueBlocker(vehicle, task, toNodeId, block.blockingVehicleId)
      ) {
        this.startNextLegAgentSimple(vehicle, dtSec);
        return;
      }
      if (this.agentRefreshEnabled() && this.agentRefreshHandleMoveBlock(vehicle, toNodeId, block)) {
        this.agentRefreshMarkStationaryHandledBlockAsWaiting(vehicle, fromNodeId, toNodeId, block, dtSec);
        return;
      }
      if (vehicle.loaded && block.blockingVehicleId) {
        this.agentTryDisplaceEmptyBlocker(block.blockingVehicleId, vehicle, toNodeId);
      } else if (task && block.blockingVehicleId) {
        const blockingVehicle = this.vehicles.find((candidate) => candidate.id === block.blockingVehicleId) ?? null;
        if (blockingVehicle && !blockingVehicle.loaded && !blockingVehicle.taskId) {
          this.agentTryDisplaceEmptyBlocker(block.blockingVehicleId, vehicle, toNodeId);
        }
      }
      this.agentSetWaiting(vehicle, toNodeId, block, dtSec);
      return;
    }

    this.beginAgentSimpleLeg(vehicle, edge, toNodeId, task, dtSec);
  }

  private agentRefreshMarkStationaryHandledBlockAsWaiting(
    vehicle: MutableVehicle,
    fromNodeId: string,
    toNodeId: string,
    block: { reason: string; blockingVehicleId: string | null },
    dtSec: number
  ): void {
    if (
      !this.agentRefreshEnabled() ||
      (!vehicle.loaded && !vehicle.taskId) ||
      vehicle.currentNodeId !== fromNodeId ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.waitReason !== null ||
      vehicle.targetNodeId !== toNodeId
    ) {
      return;
    }
    this.agentSetWaiting(vehicle, toNodeId, block, dtSec);
  }

  private rerouteTasklessStandbyAroundBlockedTarget(vehicle: MutableVehicle, blockedTargetNodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.taskId ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0
    ) {
      return false;
    }
    const blockedNode = this.layoutNode(blockedTargetNodeId);
    if (!blockedNode || (blockedNode.type !== 'parking' && blockedNode.type !== 'storage')) {
      return false;
    }
    const route = this.routeToInboundStandby(vehicle);
    const nextNodeId = route?.[1] ?? null;
    if (!route || !nextNodeId || nextNodeId === blockedTargetNodeId || this.topLiftRouteTerminatesOnColumnAccess(route)) {
      return false;
    }
    const nextBlock = this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(vehicle, nextNodeId)
          : this.agentMoveBlocker(vehicle, nextNodeId)
      : null;
    if (nextBlock) {
      return false;
    }

    this.clearTasklessRouteReservations(vehicle);
    vehicle.state = 'assigned';
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = nextNodeId;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    this.logAgentReroute(vehicle, null, blockedTargetNodeId, route, 'standby-target-occupied-reroute', { countTaskReplan: false });
    return true;
  }

  private tryRetargetLoadedInboundAroundTasklessDropoffBlocker(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    block: { reason: string; blockingVehicleId: string | null }
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      task.kind !== 'inbound' ||
      !this.isStorageNode(task.dropoffNodeId) ||
      !block.blockingVehicleId
    ) {
      return false;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === block.blockingVehicleId) ?? null;
    if (
      !blocker ||
      blocker.loaded ||
      blocker.taskId !== null ||
      blocker.currentNodeId !== task.dropoffNodeId
    ) {
      return false;
    }
    return this.tryRetargetLoadedInboundToReachableDropoff(vehicle, task, task.dropoffNodeId);
  }

  private tryRetargetLoadedInboundToReachableDropoff(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    failedGoalNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      task.kind !== 'inbound' ||
      failedGoalNodeId !== task.dropoffNodeId ||
      !this.isStorageNode(task.dropoffNodeId)
    ) {
      return false;
    }

    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return false;
    }

    const occupancy = this.storageNodeLoadOccupancy(true);
    occupancy.delete(task.dropoffNodeId);
    const outboundLockedColumns = this.topLiftActiveOutboundTaskColumns();
    const candidateRoutes: Array<{ nodeId: string; routeNodeIds: string[] }> = [];

    for (const column of this.topLiftStorageColumnNumbersForLift(liftNodeId)) {
      if (outboundLockedColumns.has(column)) {
        continue;
      }
      for (const nodeId of this.topLiftStorageColumnNodeIds(column)) {
        if (
          nodeId === task.dropoffNodeId ||
          occupancy.has(nodeId) ||
          this.currentNodeOccupancy.has(nodeId) ||
          !this.topLiftInboundStorageNodeReachableInColumn(nodeId, occupancy)
        ) {
          continue;
        }

        const candidateTask: TaskStateRecord = { ...task, dropoffNodeId: nodeId };
        try {
          const routeNodeIds = this.agentRefreshLoadedInboundRouteToDropoff(vehicle.currentNodeId, candidateTask);
          const nextNodeId = routeNodeIds[1] ?? null;
          if (
            !nextNodeId ||
            !this.routeEdgesExist(routeNodeIds) ||
            this.routeHasStoredLoadConflict(routeNodeIds, new Set([nodeId])) ||
            this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeNodeIds)
          ) {
            continue;
          }
          candidateRoutes.push({ nodeId, routeNodeIds });
        } catch {
          continue;
        }
      }
    }

    const selected = candidateRoutes.sort((left, right) =>
      this.routePlannerCostM(left.routeNodeIds, left.nodeId, vehicle.lastMovementAxis) -
        this.routePlannerCostM(right.routeNodeIds, right.nodeId, vehicle.lastMovementAxis) ||
      this.routeDistanceM(left.routeNodeIds) - this.routeDistanceM(right.routeNodeIds) ||
      left.nodeId.localeCompare(right.nodeId)
    )[0] ?? null;
    if (!selected) {
      return false;
    }

    const previousDropoffNodeId = task.dropoffNodeId;
    task.dropoffNodeId = selected.nodeId;
    task.waitReason = null;
    vehicle.routeNodeIds = selected.routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = selected.routeNodeIds[1] ?? null;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = selected.nodeId;
    vehicle.plannedRouteNodeIds = selected.routeNodeIds;
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
    this.logAgentReroute(vehicle, task, previousDropoffNodeId, selected.routeNodeIds, 'loaded-inbound-retarget-reachable-dropoff', {
      countTaskReplan: true
    });
    return true;
  }

  private tryFlushEmptyStorageBlockerOnLoadedInboundColumnRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord
  ): { blockerId: string; nodeId: string } | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      task.kind !== 'inbound' ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !this.isStorageNode(task.dropoffNodeId)
    ) {
      return null;
    }
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!currentPosition || !dropoffPosition || currentPosition.column !== dropoffPosition.column) {
      return null;
    }
    const direction = Math.sign(dropoffPosition.row - currentPosition.row);
    if (direction !== -1 && direction !== 1) {
      return null;
    }
    const nextNodeId = `storage-r${String(currentPosition.row + direction).padStart(2, '0')}-c${String(currentPosition.column).padStart(2, '0')}`;
    const blockerId = this.currentNodeOccupancy.get(nextNodeId);
    if (!blockerId || blockerId === vehicle.id) {
      return null;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockerId) ?? null;
    if (!blocker || blocker.loaded || blocker.currentNodeId !== nextNodeId) {
      return null;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return null;
    }
    return this.tryFlushTasklessStorageBlockerAhead(blocker, vehicle, nextNodeId)
      ? { blockerId, nodeId: nextNodeId }
      : null;
  }

  private agentRefreshMoveBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null = null
  ): { reason: string; blockingVehicleId: string | null } | null {
    const middleExitLookaheadBlockerId = this.topLiftStorageMiddleExitLookaheadBlocker(vehicle, toNodeId, candidateRouteNodeIds);
    if (middleExitLookaheadBlockerId) {
      return { reason: 'middle-exit-precedence', blockingVehicleId: middleExitLookaheadBlockerId };
    }
    const middleAisleBlockerId = this.topLiftMiddleAisleOpposingClaimBlocker(vehicle, toNodeId, candidateRouteNodeIds);
    if (middleAisleBlockerId) {
      return { reason: 'middle-aisle-opposing-claim', blockingVehicleId: middleAisleBlockerId };
    }
    const spineBlockerId = this.topLiftVerticalSpineOpposingClaimBlocker(vehicle, toNodeId);
    if (spineBlockerId) {
      return { reason: 'top-lift-spine-opposing-claim', blockingVehicleId: spineBlockerId };
    }
    const inboundColumnEntryBlockerId = this.topLiftLoadedInboundColumnEntryBlocker(vehicle, toNodeId, candidateRouteNodeIds);
    if (inboundColumnEntryBlockerId) {
      return { reason: 'inbound-column-entry-occupied', blockingVehicleId: inboundColumnEntryBlockerId };
    }
    const outboundDockCorridorBlockerId = this.topLiftOutboundDockCorridorBlocker(vehicle, toNodeId);
    if (outboundDockCorridorBlockerId) {
      return { reason: 'outbound-lift-dock-corridor', blockingVehicleId: outboundDockCorridorBlockerId };
    }

    const immediateBlock = this.agentMinimalMoveBlocker(vehicle, toNodeId);
    if (immediateBlock && this.agentRefreshImmediateNodeBlockTakesPrecedence(immediateBlock.reason)) {
      const immediateBlockingVehicle = immediateBlock.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === immediateBlock.blockingVehicleId) ?? null
        : null;
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'node-target-near' || immediateBlock.reason === 'node-clearing') &&
        this.topLiftSameDirectionMovingFollowerAllowed(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      return immediateBlock;
    }

    const queueAisleBlocker = this.topLiftQueueAisleClearThroughBlocker(vehicle, toNodeId, candidateRouteNodeIds);
    if (queueAisleBlocker) {
      return { reason: 'lift-queue-aisle-clear-through', blockingVehicleId: queueAisleBlocker };
    }

    const noStopContinuationBlock = this.agentRefreshNoStopContinuationBlock(vehicle, toNodeId, candidateRouteNodeIds);
    if (noStopContinuationBlock) {
      const noStopBlockingVehicle = noStopContinuationBlock.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === noStopContinuationBlock.blockingVehicleId) ?? null
        : null;
      if (
        noStopBlockingVehicle &&
        (
          this.agentRefreshBlockerIsTrailingCurrentNode(vehicle, noStopBlockingVehicle) ||
          this.agentRefreshBlockerIsBehindCurrentMove(vehicle, toNodeId, noStopBlockingVehicle)
        )
      ) {
        return null;
      }
      return noStopContinuationBlock;
    }

    const queueFifoBlocker = this.topLiftQueueFifoBlocker(vehicle, toNodeId);
    if (queueFifoBlocker) {
      return { reason: 'lift-queue-fifo', blockingVehicleId: queueFifoBlocker };
    }

    if (immediateBlock) {
      const immediateBlockingVehicle = immediateBlock.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === immediateBlock.blockingVehicleId) ?? null
        : null;
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.topLiftQueueDeeperClearanceOverlapAllowed(vehicle, toNodeId, immediateBlockingVehicle.id)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.agentRefreshStoragePocketBlockerIsOffAisleYield(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.topLiftServiceExitOverlapAllowed(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.topLiftOutboundExitLaneClearanceMoveAllowed(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.clearanceMoveEndpointFootprintsClear(vehicle, toNodeId, immediateBlockingVehicle) &&
        this.emptyMoveIncreasesClearanceFromLoadedBlocker(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.clearanceMoveEndpointFootprintsClear(vehicle, toNodeId, immediateBlockingVehicle) &&
        this.loadedMoveIncreasesClearanceFromLoadedBlocker(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.clearanceMoveEndpointFootprintsClear(vehicle, toNodeId, immediateBlockingVehicle) &&
        this.topLiftMoveIncreasesClearanceFromBlocker(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.topLiftSeparatingMoveFromFootprintBlockerAllowed(vehicle, toNodeId, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlockingVehicle &&
        (immediateBlock.reason === 'min-separation' || immediateBlock.reason === 'avoidance-clearance') &&
        this.agentRefreshBlockerIsTrailingCurrentNode(vehicle, immediateBlockingVehicle)
      ) {
        return null;
      }
      if (
        immediateBlock.reason === 'no-stop-continuation-blocked' &&
        !immediateBlock.blockingVehicleId &&
        this.agentRefreshRouteNodeAfter(vehicle, toNodeId, candidateRouteNodeIds) !== null
      ) {
        return null;
      }
      return immediateBlock;
    }
    if (this.isStorageNode(vehicle.currentNodeId)) {
      return null;
    }
    return this.agentRefreshColumnEdgeBlocker(vehicle, toNodeId);
  }

  private agentRefreshStoragePocketBlockerIsOffAisleYield(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      !this.isStorageNode(blocker.currentNodeId) ||
      !isTopLiftColumnAccessNodeId(toNodeId) ||
      this.topLiftColumnKey(blocker.currentNodeId) !== this.topLiftColumnKey(toNodeId)
    ) {
      return false;
    }
    if (
      blocker.waitReason !== 'local-yield-hold' &&
      blocker.waitReason !== 'middle-aisle-opposing-claim'
    ) {
      return false;
    }
    return blocker.blockingVehicleId === vehicle.id ||
      this.activeConflictSessionForPair(vehicle.id, blocker.id)?.yielderVehicleId === blocker.id;
  }

  private topLiftLoadedInboundColumnEntryBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null
  ): string | null {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded || !isTopLiftColumnAccessNodeId(toNodeId)) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return null;
    }
    const routeNodeIds = candidateRouteNodeIds ?? this.vehicleRouteTailForMove(vehicle, toNodeId);
    const toIndex = routeNodeIds.indexOf(toNodeId);
    const nextNodeId = toIndex >= 0 ? routeNodeIds[toIndex + 1] ?? null : null;
    if (!nextNodeId || !this.isStorageNode(nextNodeId)) {
      return null;
    }
    const nextPosition = this.storageGridPosition(nextNodeId);
    const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!nextPosition || !dropoffPosition || nextPosition.column !== dropoffPosition.column) {
      return null;
    }
    for (let index = toIndex + 1; index < routeNodeIds.length; index += 1) {
      const nodeId = routeNodeIds[index]!;
      if (!this.isStorageNode(nodeId)) {
        break;
      }
      const nodePosition = this.storageGridPosition(nodeId);
      if (!nodePosition || nodePosition.column !== dropoffPosition.column) {
        break;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicle.id) {
        const occupant = this.vehicles.find((candidate) => candidate.id === occupantId) ?? null;
        if (!occupant || occupant.loaded) {
          return occupantId;
        }
        const occupantTarget = occupant.targetNodeId ?? occupant.routeNodeIds[occupant.routeIndex + 1] ?? null;
        const occupantRoute = new Set([
          ...this.vehicleRouteTail(occupant, occupant.routeNodeIds),
          ...this.vehicleRouteTail(occupant, occupant.plannedRouteNodeIds)
        ]);
        if (occupantTarget === toNodeId || occupantRoute.has(toNodeId)) {
          return occupantId;
        }
      }
      if (nodeId === task.dropoffNodeId) {
        break;
      }
    }
    return null;
  }

  private topLiftOutboundDockCorridorBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const moveClaim = this.topLiftOutboundDockCorridorClaim(vehicle.currentNodeId, toNodeId);
    if (!moveClaim || (!moveClaim.workcell && !moveClaim.bottomCorridor)) {
      return null;
    }
    const serviceEntryCompletion = this.topLiftOutboundLoadedServiceEntryCompletion(vehicle, toNodeId);
    const serviceExitClearThrough = this.topLiftOutboundEmptyServiceExitClearThrough(vehicle, toNodeId);

    for (const candidate of this.vehicles) {
      if (candidate.id === vehicle.id) {
        continue;
      }
      const candidateClaim = this.topLiftOutboundDockCorridorClaimForVehicle(candidate);
      if (!candidateClaim || candidateClaim.liftNodeId !== moveClaim.liftNodeId) {
        continue;
      }
      const candidateActivelyCrossingBottomCorridor = candidateClaim.bottomCorridor && (
        candidate.currentEdgeId !== null ||
        candidate.state === 'moving-to-pickup' ||
        candidate.state === 'returning' ||
        candidate.state === 'loaded-moving'
      );
      if (this.topLiftOutboundDockJunctionExitPrecedenceAllows(vehicle, toNodeId, candidate)) {
        continue;
      }
      if (
        candidateClaim.workcell &&
        this.topLiftOutboundTasklessWorkcellExitPrecedenceAllows(vehicle, toNodeId, candidate)
      ) {
        continue;
      }
      if (serviceEntryCompletion && candidateClaim.bottomCorridor && !candidateClaim.workcell) {
        continue;
      }
      if (serviceExitClearThrough && candidateClaim.bottomCorridor && !candidateClaim.workcell) {
        continue;
      }
      if (this.topLiftOutboundEmptyQueueExitPrecedenceAllows(vehicle, toNodeId, candidate)) {
        continue;
      }
      if (this.topLiftOutboundLoadedApproachPrecedenceAllows(vehicle, toNodeId, candidate)) {
        continue;
      }
      if (this.topLiftOutboundLoadedApproachRetreatAllows(vehicle, toNodeId, candidate)) {
        continue;
      }
      if (
        (
          moveClaim.bottomCorridor &&
          candidateClaim.workcell &&
          this.topLiftOutboundDockProjectedRouteOverlap(vehicle, toNodeId, candidate)
        ) ||
        (
          moveClaim.workcell &&
          candidateActivelyCrossingBottomCorridor &&
          this.topLiftOutboundDockProjectedRouteOverlap(vehicle, toNodeId, candidate)
        )
      ) {
        return candidate.id;
      }
    }

    return null;
  }

  private topLiftOutboundDockCorridorActiveBottomMoveBlocker(
    vehicle: MutableVehicle,
    nextX: number,
    nextZ: number
  ): string | null {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.targetNodeId) {
      return null;
    }
    const moveClaim = this.topLiftOutboundDockCorridorClaim(vehicle.currentNodeId, vehicle.targetNodeId);
    if (!moveClaim || (!moveClaim.bottomCorridor && !moveClaim.workcell)) {
      return null;
    }
    const serviceEntryCompletion = this.topLiftOutboundLoadedServiceEntryCompletion(vehicle, vehicle.targetNodeId);
    const serviceExitClearThrough = this.topLiftOutboundEmptyServiceExitClearThrough(vehicle, vehicle.targetNodeId);

    for (const candidate of this.vehicles) {
      if (candidate.id === vehicle.id) {
        continue;
      }
      const candidateClaim = this.topLiftOutboundDockCorridorClaimForVehicle(candidate);
      if (serviceEntryCompletion && candidateClaim?.bottomCorridor && !candidateClaim.workcell) {
        continue;
      }
      if (serviceExitClearThrough && candidateClaim?.bottomCorridor && !candidateClaim.workcell) {
        continue;
      }
      if (this.topLiftOutboundEmptyQueueExitPrecedenceAllows(vehicle, vehicle.targetNodeId, candidate)) {
        continue;
      }
      if (this.topLiftOutboundLoadedApproachPrecedenceAllows(vehicle, vehicle.targetNodeId, candidate)) {
        continue;
      }
      if (this.topLiftOutboundLoadedApproachRetreatAllows(vehicle, vehicle.targetNodeId, candidate)) {
        continue;
      }
      if (!candidateClaim?.workcell || candidateClaim.liftNodeId !== moveClaim.liftNodeId) {
        if (
          moveClaim.workcell &&
          candidateClaim?.bottomCorridor &&
          candidate.currentEdgeId === null &&
          /^module-\d+-spine-bottom-b$/.test(candidate.currentNodeId) &&
          this.topLiftOutboundDockProjectedFootprintsOverlap(vehicle, nextX, nextZ, candidate)
        ) {
          return candidate.id;
        }
        continue;
      }
      if (this.topLiftOutboundDockJunctionExitPrecedenceAllows(vehicle, vehicle.targetNodeId, candidate)) {
        continue;
      }
      if (this.topLiftOutboundTasklessWorkcellExitPrecedenceAllows(vehicle, vehicle.targetNodeId, candidate)) {
        continue;
      }
      if (
        moveClaim.bottomCorridor &&
        this.topLiftOutboundDockProjectedFootprintsOverlap(vehicle, nextX, nextZ, candidate)
      ) {
        return candidate.id;
      }
    }

    return null;
  }

  private topLiftOutboundDockCorridorClaimForVehicle(
    vehicle: MutableVehicle
  ): { liftNodeId: string; workcell: boolean; bottomCorridor: boolean } | null {
    if (
      this.isStorageNode(vehicle.currentNodeId) &&
      (!vehicle.targetNodeId || this.traffic.findEdge(vehicle.currentNodeId, vehicle.targetNodeId) === null)
    ) {
      return this.topLiftOutboundDockCorridorClaim(vehicle.currentNodeId, null);
    }
    return this.topLiftOutboundDockCorridorClaim(
      vehicle.currentNodeId,
      vehicle.targetNodeId ?? vehicle.plannedGoalNodeId
    );
  }

  private topLiftOutboundLoadedServiceEntryCompletion(
    vehicle: MutableVehicle,
    toNodeId: string | null
  ): { liftNodeId: string; slotIndex: number } | null {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded || !toNodeId) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'outbound') {
      return null;
    }
    const entrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    const serviceSlot = topLiftQueueServiceSlot(toNodeId);
    if (
      !entrySlot ||
      !serviceSlot ||
      entrySlot.liftNodeId !== serviceSlot.liftNodeId ||
      entrySlot.slotIndex !== serviceSlot.slotIndex ||
      this.liftPortKindForNodeId(entrySlot.liftNodeId) !== 'outbound'
    ) {
      return null;
    }
    const taskLiftNodeId = this.taskLiftPortNodeId(task);
    if (taskLiftNodeId && taskLiftNodeId !== entrySlot.liftNodeId) {
      return null;
    }
    return entrySlot;
  }

  private topLiftOutboundEmptyServiceExitClearThrough(
    vehicle: MutableVehicle,
    toNodeId: string | null
  ): { liftNodeId: string; slotIndex: number } | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId !== null || !toNodeId) {
      return null;
    }
    const serviceSlot = topLiftQueueServiceSlot(vehicle.currentNodeId);
    const entrySlot = topLiftQueueEntrySlot(toNodeId);
    if (
      !serviceSlot ||
      !entrySlot ||
      serviceSlot.liftNodeId !== entrySlot.liftNodeId ||
      serviceSlot.slotIndex !== entrySlot.slotIndex ||
      this.liftPortKindForNodeId(serviceSlot.liftNodeId) !== 'outbound'
    ) {
      return null;
    }
    return serviceSlot;
  }

  private topLiftOutboundEmptyQueueExitPrecedenceAllows(
    vehicle: MutableVehicle,
    toNodeId: string | null,
    candidate: MutableVehicle
  ): boolean {
    const vehicleSlot = this.topLiftOutboundEmptyQueueExitSlot(vehicle, toNodeId);
    const candidateSlot = this.topLiftOutboundEmptyQueueExitSlot(candidate, candidate.targetNodeId);
    return Boolean(
      vehicleSlot &&
      candidateSlot &&
      vehicleSlot.liftNodeId === candidateSlot.liftNodeId &&
      vehicleSlot.slotIndex < candidateSlot.slotIndex
    );
  }

  private topLiftOutboundLoadedApproachPrecedenceAllows(
    vehicle: MutableVehicle,
    toNodeId: string | null,
    candidate: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded || !toNodeId) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'outbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
      return false;
    }
    const candidateSlot = this.topLiftOutboundEmptyQueueExitSlot(candidate, candidate.targetNodeId);
    if (!candidateSlot || candidateSlot.liftNodeId !== liftNodeId || candidateSlot.slotIndex <= 1) {
      return false;
    }
    const bottomAccessNodeId = this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId);
    return toNodeId === bottomAccessNodeId ||
      vehicle.currentNodeId === bottomAccessNodeId ||
      topLiftQueueEntrySlot(toNodeId)?.liftNodeId === liftNodeId;
  }

  private topLiftOutboundLoadedApproachRetreatAllows(
    vehicle: MutableVehicle,
    toNodeId: string | null,
    candidate: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded || !toNodeId || candidate.loaded) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'outbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
      return false;
    }
    const bottomAccessNodeId = this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId);
    const candidateEntrySlot = topLiftQueueEntrySlot(candidate.currentNodeId);
    if (
      !bottomAccessNodeId ||
      vehicle.currentNodeId !== bottomAccessNodeId ||
      toNodeId === bottomAccessNodeId ||
      topLiftAisleLevel(toNodeId) !== 'bottom-b' ||
      candidateEntrySlot?.liftNodeId !== liftNodeId ||
      candidate.targetNodeId !== bottomAccessNodeId
    ) {
      return false;
    }
    return Boolean(this.traffic.findEdge(vehicle.currentNodeId, toNodeId));
  }

  private topLiftOutboundEmptyQueueExitSlot(
    vehicle: MutableVehicle,
    toNodeId: string | null
  ): { liftNodeId: string; slotIndex: number } | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || !toNodeId) {
      return null;
    }
    const entrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    if (!entrySlot || this.liftPortKindForNodeId(entrySlot.liftNodeId) !== 'outbound') {
      return null;
    }
    const bottomAccessNodeId = this.topLiftQueueEntryBottomAccessNodeId(vehicle.currentNodeId);
    return bottomAccessNodeId === toNodeId ? entrySlot : null;
  }

  private topLiftOutboundTasklessWorkcellExitPrecedenceAllows(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidate: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      candidate.loaded
    ) {
      return false;
    }
    const vehicleSlot = this.topLiftOutboundWorkcellQueueSlot(vehicle.currentNodeId);
    const candidateSlot = this.topLiftOutboundWorkcellQueueSlot(candidate.currentNodeId);
    const vehicleCorridorLiftNodeId =
      this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(vehicle.currentNodeId) ??
      this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(toNodeId);
    const vehicleTargetLiftNodeId = this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(toNodeId);
    const candidateTargetLiftNodeId = this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(candidate.targetNodeId);
    if (
      !vehicleSlot &&
      candidateSlot &&
      vehicleCorridorLiftNodeId === candidateSlot.liftNodeId &&
      vehicleTargetLiftNodeId === candidateSlot.liftNodeId &&
      candidateTargetLiftNodeId === candidateSlot.liftNodeId
    ) {
      return true;
    }
    if (
      !vehicleSlot ||
      !candidateSlot ||
      vehicleSlot.liftNodeId !== candidateSlot.liftNodeId ||
      vehicleSlot.slotIndex >= candidateSlot.slotIndex
    ) {
      return false;
    }
    return vehicleTargetLiftNodeId === vehicleSlot.liftNodeId &&
      candidateTargetLiftNodeId === candidateSlot.liftNodeId;
  }

  private topLiftOutboundDockJunctionExitPrecedenceAllows(
    vehicle: MutableVehicle,
    toNodeId: string | null,
    candidate: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      candidate.loaded ||
      !toNodeId ||
      !candidate.targetNodeId ||
      candidate.currentEdgeId !== null ||
      candidate.legRemainingM > 0 ||
      candidate.phaseRemainingSec > 0 ||
      candidate.targetNodeId !== vehicle.currentNodeId ||
      toNodeId === candidate.currentNodeId ||
      !/^module-\d+-spine-bottom-b$/.test(vehicle.currentNodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, toNodeId)
    ) {
      return false;
    }

    const vehicleClaim = this.topLiftOutboundDockCorridorClaim(vehicle.currentNodeId, toNodeId);
    const candidateClaim = this.topLiftOutboundDockCorridorClaim(candidate.currentNodeId, candidate.targetNodeId);
    if (
      !vehicleClaim ||
      !candidateClaim ||
      vehicleClaim.liftNodeId !== candidateClaim.liftNodeId ||
      !vehicleClaim.bottomCorridor ||
      (!candidateClaim.workcell && !candidateClaim.bottomCorridor)
    ) {
      return false;
    }

    const targetOccupantId = this.currentNodeOccupancy.get(toNodeId);
    if (targetOccupantId && targetOccupantId !== vehicle.id) {
      return false;
    }
    const targetClaimantId = this.nodeClaimedByOtherVehicle(toNodeId, vehicle.id);
    return targetClaimantId === null || targetClaimantId === candidate.id;
  }

  private topLiftOutboundWorkcellQueueSlot(nodeId: string | null): { liftNodeId: string; slotIndex: number } | null {
    if (!nodeId) {
      return null;
    }
    const entrySlot = topLiftQueueEntrySlot(nodeId);
    if (entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'outbound') {
      return entrySlot;
    }
    const serviceSlot = topLiftQueueServiceSlot(nodeId);
    if (serviceSlot && this.liftPortKindForNodeId(serviceSlot.liftNodeId) === 'outbound') {
      return serviceSlot;
    }
    return null;
  }

  private topLiftOutboundDockProjectedFootprintsOverlap(
    vehicle: MutableVehicle,
    nextX: number,
    nextZ: number,
    blocker: MutableVehicle
  ): boolean {
    const vehiclePose = this.topLiftProjectedDisplayPose(vehicle, nextX, nextZ);
    const blockerPose = this.topLiftProjectedDisplayPose(blocker, blocker.x, blocker.z);
    const visualSideM = Math.max(this.scenario.vehicles.lengthM, this.scenario.vehicles.widthM) * 0.78;
    return Math.abs(vehiclePose.x - blockerPose.x) < visualSideM * 0.96 &&
      Math.abs(vehiclePose.z - blockerPose.z) < visualSideM * 0.96;
  }

  private topLiftOutboundDockProjectedRouteOverlap(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const vehiclePoses = [
      this.topLiftProjectedDisplayPoseAtNode(vehicle.currentNodeId),
      this.topLiftProjectedDisplayPoseAtNode(toNodeId)
    ].filter((pose): pose is { x: number; z: number } => pose !== null);
    const blockerPoses = [
      this.topLiftProjectedDisplayPoseAtNode(blocker.currentNodeId),
      blocker.targetNodeId ? this.topLiftProjectedDisplayPoseAtNode(blocker.targetNodeId) : null
    ].filter((pose): pose is { x: number; z: number } => pose !== null);

    for (const vehiclePose of vehiclePoses) {
      for (const blockerPose of blockerPoses) {
        if (this.topLiftProjectedDisplayPosesOverlap(vehiclePose, blockerPose)) {
          return true;
        }
      }
    }
    return false;
  }

  private topLiftProjectedDisplayPosesOverlap(
    left: { x: number; z: number },
    right: { x: number; z: number }
  ): boolean {
    const visualSideM = Math.max(this.scenario.vehicles.lengthM, this.scenario.vehicles.widthM) * 0.78;
    return Math.abs(left.x - right.x) < visualSideM * 0.96 &&
      Math.abs(left.z - right.z) < visualSideM * 0.96;
  }

  private topLiftProjectedDisplayPoseAtNode(nodeId: string): { x: number; z: number } | null {
    const node = this.layoutNode(nodeId);
    return node ? this.topLiftDisplayPointForNode(nodeId, node) : null;
  }

  private topLiftProjectedDisplayRailNodeId(nodeId: string): string | null {
    const pose = this.topLiftProjectedDisplayPoseAtNode(nodeId);
    if (!pose) {
      return null;
    }
    const railNode = this.scenario.layout.nodes.find((candidate) =>
      topLiftAisleLevel(candidate.id) !== null &&
      Math.abs(candidate.x - pose.x) <= 1e-6 &&
      Math.abs(candidate.z - pose.z) <= 1e-6
    );
    return railNode?.id ?? null;
  }

  private topLiftProjectedDisplayMoveBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      (
        !this.topLiftDisplayProjectedNode(vehicle.currentNodeId) &&
        !this.topLiftDisplayProjectedNode(toNodeId)
      )
    ) {
      return null;
    }
    const movePose = this.topLiftProjectedDisplayPoseAtNode(toNodeId);
    if (!movePose) {
      return null;
    }
    if (this.topLiftSameDisplayQueuePocketMove(vehicle, toNodeId)) {
      return null;
    }
    for (const other of this.vehicles) {
      if (other.id === vehicle.id) {
        continue;
      }
      const otherCurrentPose = this.topLiftProjectedDisplayPoseAtNode(other.currentNodeId);
      if (otherCurrentPose && this.topLiftProjectedDisplayPosesOverlap(movePose, otherCurrentPose)) {
        return other.id;
      }
      if (other.targetNodeId) {
        const otherTargetPose = this.topLiftProjectedDisplayPoseAtNode(other.targetNodeId);
        if (otherTargetPose && this.topLiftProjectedDisplayPosesOverlap(movePose, otherTargetPose)) {
          if (this.topLiftInboundQueueClearerMayOverrideTargetClaim(vehicle, toNodeId, other)) {
            continue;
          }
          return other.id;
        }
      }
    }
    return null;
  }

  private topLiftProjectedQueuePocketInternalMoveIgnoresFootprintBlocker(
    vehicle: MutableVehicle,
    blocker: MutableVehicle
  ): boolean {
    if (!vehicle.targetNodeId) {
      return false;
    }
    return this.topLiftSameDisplayQueuePocketMove(vehicle, vehicle.targetNodeId) &&
      this.topLiftQueuePocketNode(blocker.currentNodeId);
  }

  private topLiftSameDisplayQueuePocketMove(vehicle: MutableVehicle, toNodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    if (!this.topLiftQueuePocketNode(vehicle.currentNodeId) || !this.topLiftQueuePocketNode(toNodeId)) {
      return false;
    }
    const currentSlot = this.topLiftQueueSlotForNode(vehicle.currentNodeId);
    const targetSlot = this.topLiftQueueSlotForNode(toNodeId);
    if (!currentSlot || !targetSlot || currentSlot.liftNodeId !== targetSlot.liftNodeId) {
      return false;
    }
    const currentPose = this.topLiftProjectedDisplayPoseAtNode(vehicle.currentNodeId);
    const targetPose = this.topLiftProjectedDisplayPoseAtNode(toNodeId);
    return Boolean(
      currentPose &&
      targetPose &&
      Math.abs(currentPose.x - targetPose.x) <= 1e-6 &&
      Math.abs(currentPose.z - targetPose.z) <= 1e-6
    );
  }

  private topLiftQueuePocketNode(nodeId: string): boolean {
    return topLiftQueueEntrySlot(nodeId) !== null ||
      topLiftQueueAisleAccess(nodeId) !== null ||
      topLiftQueueParkingSlot(nodeId) !== null ||
      topLiftQueueServiceSlot(nodeId) !== null;
  }

  private topLiftInboundQueueClearerMayOverrideTargetClaim(
    vehicle: MutableVehicle,
    toNodeId: string,
    other: MutableVehicle
  ): boolean {
    if (this.topLiftInboundQueueTailYieldVehicle(vehicle) && !this.topLiftInboundQueueTailYieldVehicle(other)) {
      return true;
    }
    if (!this.topLiftInboundQueueClearingVehicle(vehicle) || this.topLiftInboundQueueClearingVehicle(other)) {
      return false;
    }
    const targetSlot = this.topLiftQueueSlotForNode(toNodeId);
    const currentSlot = this.topLiftQueueSlotForNode(vehicle.currentNodeId);
    return Boolean(
      currentSlot &&
      targetSlot &&
      currentSlot.liftNodeId === targetSlot.liftNodeId &&
      this.liftPortKindForNodeId(currentSlot.liftNodeId) === 'inbound'
    );
  }

  private topLiftInboundQueueTailYieldVehicle(vehicle: MutableVehicle): boolean {
    if (
      vehicle.loaded ||
      !vehicle.targetNodeId ||
      !this.topLiftColumnLayoutEnabled() ||
      (
        this.topLiftFifoHeldVehicle(vehicle) &&
        isTopLiftQueueParkingNodeId(vehicle.currentNodeId) &&
        !this.topLiftInboundQueueCompressingVehicle(vehicle)
      )
    ) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return false;
    }
    const currentSlot = this.topLiftQueueSlotForNode(vehicle.currentNodeId);
    const targetSlot = this.topLiftQueueSlotForNode(vehicle.targetNodeId);
    const finalSlot = this.topLiftQueueSlotForNode(vehicle.routeNodeIds.at(-1) ?? '');
    if (!currentSlot || !targetSlot || !finalSlot) {
      return false;
    }
    const advancesToDeeperSlot = targetSlot.slotIndex > currentSlot.slotIndex || finalSlot.slotIndex > currentSlot.slotIndex;
    const settlesCurrentDeepSlot =
      currentSlot.slotIndex > 1 &&
      targetSlot.slotIndex === currentSlot.slotIndex &&
      finalSlot.slotIndex === currentSlot.slotIndex &&
      isTopLiftQueueParkingNodeId(vehicle.targetNodeId);
    const clearsFrontAccessToParking =
      currentSlot.slotIndex === 1 &&
      targetSlot.slotIndex === currentSlot.slotIndex &&
      finalSlot.slotIndex === currentSlot.slotIndex &&
      isTopLiftQueueParkingNodeId(vehicle.targetNodeId);
    return Boolean(
      currentSlot.liftNodeId === targetSlot.liftNodeId &&
      targetSlot.liftNodeId === finalSlot.liftNodeId &&
      this.liftPortKindForNodeId(currentSlot.liftNodeId) === 'inbound' &&
      (advancesToDeeperSlot || settlesCurrentDeepSlot || clearsFrontAccessToParking)
    );
  }

  private topLiftProjectedDisplayPose(vehicle: MutableVehicle, x: number, z: number): { x: number; z: number } {
    const currentNode = this.layoutNode(vehicle.currentNodeId);
    const targetNode = vehicle.targetNodeId ? this.layoutNode(vehicle.targetNodeId) : null;
    if (
      vehicle.currentEdgeId &&
      currentNode &&
      targetNode &&
      (
        this.topLiftDisplayProjectedNode(currentNode.id) ||
        this.topLiftDisplayProjectedNode(targetNode.id)
      )
    ) {
      const dx = targetNode.x - currentNode.x;
      const dz = targetNode.z - currentNode.z;
      const lengthSq = dx * dx + dz * dz;
      const progress = lengthSq <= 1e-9
        ? 0
        : Math.max(0, Math.min(1, ((x - currentNode.x) * dx + (z - currentNode.z) * dz) / lengthSq));
      const from = this.topLiftDisplayPointForNode(currentNode.id, currentNode);
      const to = this.topLiftDisplayPointForNode(targetNode.id, targetNode);
      return this.topLiftPointOnOrthogonalDisplayPath(from, to, progress, Math.abs(dx) >= Math.abs(dz) ? 'x' : 'z');
    }
    if (vehicle.currentEdgeId && currentNode && targetNode) {
      return Math.abs(currentNode.x - targetNode.x) <= Math.abs(currentNode.z - targetNode.z)
        ? { x: currentNode.x, z: Math.max(Math.min(currentNode.z, targetNode.z), Math.min(Math.max(currentNode.z, targetNode.z), z)) }
        : { x: Math.max(Math.min(currentNode.x, targetNode.x), Math.min(Math.max(currentNode.x, targetNode.x), x)), z: currentNode.z };
    }
    return currentNode ? { x: currentNode.x, z: currentNode.z } : { x, z };
  }

  private topLiftDisplayProjectedNode(nodeId: string): boolean {
    return /^(?:lift|parking-lift)-\d{2}-(?:inbound|outbound)(?:$|-throat|-buffer-access|-buffer-\d{2}|-queue(?:-\d{2})?|-queue-access|-queue-\d{2}-(?:access|entry-access|service-exit))$/.test(nodeId);
  }

  private topLiftDisplayPointForNode(nodeId: string, fallback: { x: number; z: number }): { x: number; z: number } {
    const serviceSlot = topLiftQueueServiceSlot(nodeId);
    const entrySlot = topLiftQueueEntrySlot(nodeId);
    const parkingSlot = topLiftQueueParkingSlot(nodeId);
    const aisleAccess = topLiftQueueAisleAccess(nodeId);
    const liftNodeId =
      serviceSlot?.liftNodeId ??
      entrySlot?.liftNodeId ??
      parkingSlot?.liftNodeId ??
      aisleAccess?.liftNodeId ??
      liftBufferParentNodeId(nodeId)?.liftNodeId ??
      (/^lift-\d{2}-(?:inbound|outbound)$/.test(nodeId) ? nodeId : null);
    if (!liftNodeId) {
      return fallback;
    }
    const kind = this.liftPortKindForNodeId(liftNodeId);
    if (kind !== 'inbound' && kind !== 'outbound') {
      return fallback;
    }
    const displayLevel: TopLiftAisleLevel = kind === 'inbound' ? 'top-b' : 'bottom-b';
    const displaysAtDock =
      serviceSlot !== null ||
      liftBufferParentNodeId(nodeId) !== null ||
      /^lift-\d{2}-(?:inbound|outbound)(?:$|-throat|-buffer-access|-buffer-\d{2})$/.test(nodeId);
    if (displaysAtDock) {
      const dockNodeId = this.topLiftDockRailNodeId(liftNodeId);
      const dockNode = dockNodeId ? this.layoutNode(dockNodeId) : null;
      if (dockNode) {
        return { x: dockNode.x, z: dockNode.z };
      }
    }
    const queueNode = this.topLiftQueueDisplayRailNode(liftNodeId, nodeId, displayLevel);
    if (queueNode) {
      return { x: queueNode.x, z: queueNode.z };
    }
    const nearest = this.topLiftNearestRailNodeToPoint(displayLevel, fallback);
    return nearest ? { x: nearest.x, z: nearest.z } : fallback;
  }

  private topLiftQueueDisplayRailNode(
    liftNodeId: string,
    nodeId: string,
    level: TopLiftAisleLevel
  ): ShuttleNode | null {
    const dockNodeId = this.topLiftDockRailNodeId(liftNodeId);
    const dockNode = dockNodeId ? this.layoutNode(dockNodeId) : null;
    if (!dockNode) {
      return null;
    }
    const parkingSlot = topLiftQueueParkingSlot(nodeId);
    const aisleAccess = topLiftQueueAisleAccess(nodeId);
    const entrySlot = topLiftQueueEntrySlot(nodeId);
    let offset: number | null = null;
    if (entrySlot?.liftNodeId === liftNodeId) {
      offset = entrySlot.slotIndex;
    } else if (aisleAccess?.liftNodeId === liftNodeId) {
      offset = Math.max(1, aisleAccess.slotIndex);
    } else if (parkingSlot?.liftNodeId === liftNodeId) {
      offset = parkingSlot.slotIndex + 1;
    } else if (nodeId === liftQueueAccessNodeId(liftNodeId)) {
      offset = 1;
    }
    if (offset === null) {
      return null;
    }
    return this.topLiftColumnRailNodeAtOffset(level, dockNode, this.topLiftQueueDisplayDirection(liftNodeId), offset);
  }

  private topLiftColumnRailNodeAtOffset(
    level: TopLiftAisleLevel,
    anchor: { x: number; z: number },
    direction: -1 | 1,
    offset: number
  ): ShuttleNode | null {
    const candidates = this.scenario.layout.nodes
      .filter((node) => new RegExp(`^column-${level}-c\\d+$`).test(node.id))
      .filter((node) => (node.x - anchor.x) * direction > 1e-6)
      .sort((left, right) => (left.x - anchor.x) * direction - (right.x - anchor.x) * direction);
    return candidates[offset - 1] ?? null;
  }

  private topLiftWorkcellQueueIndex(nodeId: string): number | null {
    const match = /-queue-(\d{2})(?:-|$)/.exec(nodeId);
    return match ? Number(match[1]) : null;
  }

  private topLiftQueueDisplayDirection(liftNodeId: string): -1 | 1 {
    const serviceNode = this.layoutNode(`${liftNodeId}-queue-01-service-exit`);
    const entryNode = this.layoutNode(`${liftNodeId}-queue-01-entry-access`) ?? this.layoutNode(`${liftNodeId}-queue-access`);
    if (serviceNode && entryNode && Math.abs(entryNode.x - serviceNode.x) > 1e-6) {
      return entryNode.x > serviceNode.x ? 1 : -1;
    }
    return 1;
  }

  private topLiftNearestRailNodeToPoint(level: TopLiftAisleLevel, point: { x: number; z: number }): ShuttleNode | null {
    let nearest: ShuttleNode | null = null;
    let nearestDistance = Number.POSITIVE_INFINITY;
    for (const node of this.scenario.layout.nodes) {
      if (!isTopLiftAisleLevelNodeId(node.id, level) && !new RegExp(`^module-\\d+-spine-${level}$`).test(node.id)) {
        continue;
      }
      const distance = Math.hypot(node.x - point.x, node.z - point.z);
      if (distance < nearestDistance) {
        nearest = node;
        nearestDistance = distance;
      }
    }
    return nearest;
  }

  private topLiftRailNodeAtOffset(
    level: TopLiftAisleLevel,
    anchor: { x: number; z: number },
    direction: -1 | 1,
    offset: number
  ): ShuttleNode | null {
    if (offset <= 0) {
      return null;
    }
    const candidates = this.scenario.layout.nodes
      .filter((node) => isTopLiftAisleLevelNodeId(node.id, level))
      .filter((node) => (node.x - anchor.x) * direction > 1e-6)
      .sort((left, right) => (left.x - anchor.x) * direction - (right.x - anchor.x) * direction);
    return candidates[offset - 1] ?? candidates.at(-1) ?? null;
  }

  private topLiftPointOnOrthogonalDisplayPath(
    from: { x: number; z: number },
    to: { x: number; z: number },
    progress: number,
    preferredAxis: 'x' | 'z'
  ): { x: number; z: number } {
    const midpoint = preferredAxis === 'x' ? { x: to.x, z: from.z } : { x: from.x, z: to.z };
    const segments = Math.abs(from.x - to.x) <= 1e-6 || Math.abs(from.z - to.z) <= 1e-6
      ? [{ from, to }]
      : [{ from, to: midpoint }, { from: midpoint, to }];
    const nonZeroSegments = segments.filter((segment) =>
      Math.hypot(segment.to.x - segment.from.x, segment.to.z - segment.from.z) > 1e-6
    );
    const totalLength = nonZeroSegments.reduce((sum, segment) =>
      sum + Math.hypot(segment.to.x - segment.from.x, segment.to.z - segment.from.z), 0
    );
    let remaining = Math.max(0, Math.min(1, progress)) * totalLength;
    for (const segment of nonZeroSegments) {
      const length = Math.hypot(segment.to.x - segment.from.x, segment.to.z - segment.from.z);
      if (remaining <= length || segment === nonZeroSegments[nonZeroSegments.length - 1]) {
        const ratio = length <= 1e-9 ? 0 : Math.max(0, Math.min(1, remaining / length));
        return {
          x: segment.from.x + (segment.to.x - segment.from.x) * ratio,
          z: segment.from.z + (segment.to.z - segment.from.z) * ratio
        };
      }
      remaining -= length;
    }
    return to;
  }

  private topLiftOutboundDockCorridorClaim(
    fromNodeId: string,
    toNodeId: string | null
  ): { liftNodeId: string; workcell: boolean; bottomCorridor: boolean } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const liftNodeIds = new Set<string>();
    let workcell = false;
    let bottomCorridor = false;

    for (const nodeId of [fromNodeId, toNodeId]) {
      if (!nodeId) {
        continue;
      }
      const workcellLiftNodeId = this.topLiftOutboundDockWorkcellNodeLiftNodeId(nodeId);
      if (workcellLiftNodeId) {
        liftNodeIds.add(workcellLiftNodeId);
        workcell = true;
      }
      const bottomLiftNodeId = this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(nodeId);
      if (bottomLiftNodeId) {
        liftNodeIds.add(bottomLiftNodeId);
        bottomCorridor = true;
      }
    }

    if (liftNodeIds.size !== 1) {
      return null;
    }
    return { liftNodeId: [...liftNodeIds][0]!, workcell, bottomCorridor };
  }

  private topLiftOutboundDockWorkcellNodeLiftNodeId(nodeId: string | null): string | null {
    if (!nodeId) {
      return null;
    }
    for (const liftNode of this.outboundLiftNodes()) {
      if (nodeId === this.topLiftDockRailNodeId(liftNode.id)) {
        return liftNode.id;
      }
    }
    const serviceSlot = topLiftQueueServiceSlot(nodeId);
    if (serviceSlot && this.liftPortKindForNodeId(serviceSlot.liftNodeId) === 'outbound') {
      return serviceSlot.liftNodeId;
    }
    const entrySlot = topLiftQueueEntrySlot(nodeId);
    if (entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'outbound') {
      return entrySlot.liftNodeId;
    }
    const bufferParent = liftBufferParentNodeId(nodeId);
    if (bufferParent?.kind === 'outbound') {
      return bufferParent.liftNodeId;
    }
    return null;
  }

  private topLiftOutboundDockBottomCorridorNodeLiftNodeId(nodeId: string | null): string | null {
    if (!nodeId) {
      return null;
    }
    const node = this.layoutNode(nodeId);
    if (!node) {
      return null;
    }
    if (
      !isTopLiftAisleLevelNodeId(nodeId, 'bottom-a') &&
      !isTopLiftAisleLevelNodeId(nodeId, 'bottom-b') &&
      !/^module-\d+-spine-bottom-b$/.test(nodeId)
    ) {
      return null;
    }

    for (const liftNode of this.outboundLiftNodes()) {
      const firstEntryNodeId = liftQueueTailEntryNodeId(liftNode.id, 1);
      const entryApproachNodeId = this.topLiftQueueEntryTopAccessNodeId(firstEntryNodeId);
      const entryExitNodeId = this.topLiftQueueEntryBottomAccessNodeId(firstEntryNodeId);
      const serviceNodeId = liftQueueServiceExitNodeId(liftNode.id, 1);
      const entryNode = entryApproachNodeId ? this.layoutNode(entryApproachNodeId) : null;
      const exitNode = entryExitNodeId ? this.layoutNode(entryExitNodeId) : null;
      const serviceNode = this.layoutNode(serviceNodeId);
      if (!entryNode || !exitNode || !serviceNode) {
        continue;
      }
      const displayDirection = this.topLiftQueueDisplayDirection(liftNode.id);
      const tailBottomBNode = this.topLiftRailNodeAtOffset('bottom-b', exitNode, displayDirection, 4) ?? exitNode;
      let minX = Math.min(tailBottomBNode.x, serviceNode.x) - this.scenario.vehicles.widthM * 0.35;
      let maxX = Math.max(tailBottomBNode.x, serviceNode.x) + this.scenario.vehicles.widthM * 0.35;
      if (isTopLiftAisleLevelNodeId(nodeId, 'bottom-a')) {
        const upstreamBottomAX = this.topLiftPreviousColumnAccessX('bottom-a', entryNode.x) ?? entryNode.x;
        if (node.x < upstreamBottomAX - 1e-6 || node.x > entryNode.x + 1e-6) {
          continue;
        }
        minX = upstreamBottomAX;
        maxX = entryNode.x;
      }
      const onDockX = node.x >= minX - 1e-6 && node.x <= maxX + 1e-6;
      const onDockLane =
        Math.abs(node.z - entryNode.z) <= 1e-6 ||
        Math.abs(node.z - exitNode.z) <= 1e-6;
      if (onDockX && onDockLane) {
        return liftNode.id;
      }
    }

    return null;
  }

  private topLiftPreviousColumnAccessX(level: TopLiftAisleLevel, x: number): number | null {
    let previousX: number | null = null;
    for (const node of this.scenario.layout.nodes) {
      if (
        isTopLiftAisleLevelNodeId(node.id, level) &&
        node.x < x - 1e-6 &&
        (previousX === null || node.x > previousX)
      ) {
        previousX = node.x;
      }
    }
    return previousX;
  }

  private topLiftServiceExitOverlapAllowed(vehicle: MutableVehicle, toNodeId: string, blocker: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded || blocker.loaded) {
      return false;
    }
    if (this.topLiftLoadedMainLaneBypassesInboundServiceLane(vehicle, toNodeId, blocker)) {
      return true;
    }
    const vehicleTask = this.taskForVehicle(vehicle);
    const vehicleLiftNodeId = vehicleTask ? this.taskLiftPortNodeId(vehicleTask) : null;
    const blockerLiftNodeId =
      topLiftQueueEntrySlot(blocker.currentNodeId)?.liftNodeId ??
      topLiftQueueAisleAccess(blocker.currentNodeId)?.liftNodeId ??
      topLiftQueueParkingSlot(blocker.currentNodeId)?.liftNodeId ??
      topLiftQueueEntrySlot(blocker.targetNodeId ?? '')?.liftNodeId ??
      topLiftQueueAisleAccess(blocker.targetNodeId ?? '')?.liftNodeId ??
      topLiftQueueParkingSlot(blocker.plannedGoalNodeId ?? '')?.liftNodeId ??
      null;
    if (
      vehicleLiftNodeId &&
      blockerLiftNodeId === vehicleLiftNodeId &&
      /^column-top-b-c\d+$/.test(vehicle.currentNodeId) &&
      /^column-top-b-c\d+$/.test(toNodeId)
    ) {
      return true;
    }
    const entrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    if (!entrySlot) {
      return false;
    }
    const exitNodeId = this.topLiftQueueEntryBottomAccessNodeId(vehicle.currentNodeId);
    if (exitNodeId !== toNodeId) {
      return false;
    }
    if (vehicleLiftNodeId && vehicleLiftNodeId !== entrySlot.liftNodeId) {
      return false;
    }
    if (blockerLiftNodeId && blockerLiftNodeId !== entrySlot.liftNodeId) {
      return false;
    }
    const blockerNode = this.layoutNode(blocker.currentNodeId);
    const entryNode = this.layoutNode(vehicle.currentNodeId);
    if (!blockerNode || !entryNode || Math.abs(blockerNode.x - entryNode.x) > 1e-6) {
      return false;
    }
    return /^column-top-a-c\d+$/.test(blocker.currentNodeId) ||
      topLiftQueueEntrySlot(blocker.targetNodeId ?? '')?.liftNodeId === entrySlot.liftNodeId ||
      topLiftQueueParkingSlot(blocker.plannedGoalNodeId ?? '')?.liftNodeId === entrySlot.liftNodeId;
  }

  private topLiftOutboundExitLaneClearanceMoveAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      blocker.loaded ||
      vehicle.taskId !== null ||
      blocker.taskId !== null ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b' ||
      topLiftAisleLevel(toNodeId) !== 'top-b'
    ) {
      return false;
    }

    const liftNodeId = this.topLiftOutboundClearanceLiftNodeId(blocker);
    if (!liftNodeId) {
      return false;
    }
    const exitBottomNodeId = this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId);
    if (
      !exitBottomNodeId ||
      vehicle.currentNodeId !== exitBottomNodeId ||
      toNodeId === exitBottomNodeId ||
      !this.traffic.findEdge(vehicle.currentNodeId, toNodeId)
    ) {
      return false;
    }

    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    const currentDistanceM = Math.hypot(vehicle.x - blocker.x, vehicle.z - blocker.z);
    const targetDistanceM = Math.hypot(target.x - blocker.x, target.z - blocker.z);
    return targetDistanceM > currentDistanceM + 0.1;
  }

  private topLiftInboundServiceAccessAisleClearanceMoveAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    serviceVehicle: MutableVehicle
  ): boolean {
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(serviceVehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !serviceVehicle.loaded ||
      !clearanceSegment ||
      this.liftPortKindForNodeId(clearanceSegment.liftNodeId) !== 'inbound' ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b'
    ) {
      return false;
    }
    const task = this.taskForVehicle(serviceVehicle);
    if (task !== null && task.kind !== 'inbound') {
      return false;
    }
    if (
      topLiftAisleLevel(toNodeId) !== 'top-a' &&
      topLiftAisleLevel(toNodeId) !== 'top-b' &&
      !isTopLiftSpineLevelNodeId(toNodeId, 'top-b')
    ) {
      return false;
    }

    const accessNodeId = this.topLiftLoadedInboundServiceAccessConflictNodeIds(serviceVehicle)
      .find((nodeId) => isTopLiftAisleLevelNodeId(nodeId, 'top-b')) ?? null;
    const accessNode = accessNodeId ? this.layoutNode(accessNodeId) : null;
    const currentNode = this.layoutNode(vehicle.currentNodeId);
    const targetNode = this.layoutNode(toNodeId);
    if (!accessNode || !currentNode || !targetNode) {
      return false;
    }

    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const accessColumn = this.topLiftColumnAccessColumn(accessNodeId!);
    if (currentColumn === null || accessColumn === null || Math.abs(currentColumn - accessColumn) > 1) {
      return false;
    }

    const currentAwayM = Math.abs(currentNode.x - accessNode.x);
    const targetAwayM = Math.abs(targetNode.x - accessNode.x);
    if (targetAwayM + 1e-6 < currentAwayM) {
      return false;
    }

    const protectedNodeIds = new Set([
      ...this.vehicleRouteTail(serviceVehicle, serviceVehicle.routeNodeIds).slice(1, 6),
      ...this.vehicleRouteTail(serviceVehicle, serviceVehicle.plannedRouteNodeIds).slice(1, 6),
      ...this.topLiftLoadedInboundServiceAccessConflictNodeIds(serviceVehicle)
    ]);
    return !protectedNodeIds.has(toNodeId);
  }

  private topLiftOutboundClearanceLiftNodeId(vehicle: MutableVehicle): string | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || vehicle.taskId !== null) {
      return null;
    }

    const currentServiceSlot = topLiftQueueServiceSlot(vehicle.currentNodeId);
    const targetEntrySlot = topLiftQueueEntrySlot(vehicle.targetNodeId ?? '');
    if (
      currentServiceSlot &&
      targetEntrySlot &&
      currentServiceSlot.liftNodeId === targetEntrySlot.liftNodeId &&
      this.liftPortKindForNodeId(currentServiceSlot.liftNodeId) === 'outbound'
    ) {
      return currentServiceSlot.liftNodeId;
    }

    const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    if (
      currentEntrySlot &&
      this.liftPortKindForNodeId(currentEntrySlot.liftNodeId) === 'outbound' &&
      this.topLiftQueueEntryBottomAccessNodeId(vehicle.currentNodeId) === vehicle.targetNodeId
    ) {
      return currentEntrySlot.liftNodeId;
    }

    const routeNodeIds = vehicle.routeNodeIds.length > 0 ? vehicle.routeNodeIds : vehicle.plannedRouteNodeIds;
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromServiceSlot = topLiftQueueServiceSlot(routeNodeIds[index - 1]!);
      const toEntrySlot = topLiftQueueEntrySlot(routeNodeIds[index]!);
      if (
        fromServiceSlot &&
        toEntrySlot &&
        fromServiceSlot.liftNodeId === toEntrySlot.liftNodeId &&
        this.liftPortKindForNodeId(fromServiceSlot.liftNodeId) === 'outbound'
      ) {
        return fromServiceSlot.liftNodeId;
      }
    }

    return null;
  }

  private agentRefreshYieldPocketCompatibleWithRequester(
    _vehicle: MutableVehicle,
    nodeId: string,
    requester: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    if (this.topLiftLoadedInboundServiceAccessConflictNodeIds(requester).includes(nodeId)) {
      return false;
    }
    if (this.agentRefreshRequesterProtectedRouteNodeIds(requester).includes(nodeId)) {
      return false;
    }
    const requesterTask = this.taskForVehicle(requester);
    if (requesterTask?.kind === 'outbound' && !requester.loaded && this.isStorageNode(nodeId)) {
      const candidatePosition = this.storageGridPosition(nodeId);
      const pickupPosition = this.storageGridPosition(requesterTask.pickupNodeId);
      if (candidatePosition && pickupPosition && candidatePosition.column === pickupPosition.column) {
        return false;
      }
    }
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(requester);
    if (this.isStorageNode(nodeId) && this.liftPortKindForNodeId(clearanceSegment?.liftNodeId ?? '') !== 'outbound') {
      return true;
    }
    if (!clearanceSegment) {
      return true;
    }
    const fromNode = this.layoutNode(clearanceSegment.fromNodeId);
    const toNode = this.layoutNode(clearanceSegment.toNodeId);
    const pocketNode = this.layoutNode(nodeId);
    if (!fromNode || !toNode || !pocketNode) {
      return true;
    }

    const clearanceM = this.scenario.vehicles.widthM / 2 + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    return this.pointToSegmentDistanceM(
      pocketNode.x,
      pocketNode.z,
      fromNode.x,
      fromNode.z,
      toNode.x,
      toNode.z
    ) > clearanceM;
  }

  private topLiftLoadedInboundServiceAccessConflictNodeIds(requester: MutableVehicle): string[] {
    if (!this.topLiftColumnLayoutEnabled() || !requester.loaded) {
      return [];
    }
    const task = this.taskForVehicle(requester);
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(requester);
    if (
      !clearanceSegment ||
      this.liftPortKindForNodeId(clearanceSegment.liftNodeId) !== 'inbound' ||
      (task !== null && task.kind !== 'inbound')
    ) {
      return [];
    }

    const routeTail = this.vehicleRouteTail(requester, requester.routeNodeIds);
    const accessNodeId =
      routeTail.find((nodeId) => /^column-top-b-c\d+$/.test(nodeId)) ??
      (topLiftQueueEntrySlot(clearanceSegment.toNodeId)
        ? this.topLiftQueueEntryBottomAccessNodeId(clearanceSegment.toNodeId)
        : null) ??
      (/^column-top-b-c\d+$/.test(clearanceSegment.toNodeId) ? clearanceSegment.toNodeId : null);
    const column = accessNodeId ? this.topLiftColumnAccessColumn(accessNodeId) : null;
    if (column === null) {
      return [];
    }
    return [
      accessNodeId!,
      columnAccessNodeId('top-a', column - 1),
      `storage-r01-c${String(column).padStart(2, '0')}`
    ];
  }

  private topLiftActiveServiceClearanceSegment(vehicle: MutableVehicle): {
    liftNodeId: string;
    fromNodeId: string;
    toNodeId: string;
  } | null {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.targetNodeId) {
      return null;
    }

    const currentServiceSlot = topLiftQueueServiceSlot(vehicle.currentNodeId);
    const targetServiceSlot = topLiftQueueServiceSlot(vehicle.targetNodeId);
    if (currentServiceSlot && targetServiceSlot && currentServiceSlot.liftNodeId === targetServiceSlot.liftNodeId) {
      return {
        liftNodeId: currentServiceSlot.liftNodeId,
        fromNodeId: vehicle.currentNodeId,
        toNodeId: vehicle.targetNodeId
      };
    }

    const targetEntrySlot = topLiftQueueEntrySlot(vehicle.targetNodeId);
    if (currentServiceSlot && targetEntrySlot && currentServiceSlot.liftNodeId === targetEntrySlot.liftNodeId) {
      return {
        liftNodeId: currentServiceSlot.liftNodeId,
        fromNodeId: vehicle.currentNodeId,
        toNodeId: vehicle.targetNodeId
      };
    }

    const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    if (
      currentEntrySlot &&
      this.topLiftQueueEntryBottomAccessNodeId(vehicle.currentNodeId) === vehicle.targetNodeId
    ) {
      return {
        liftNodeId: currentEntrySlot.liftNodeId,
        fromNodeId: vehicle.currentNodeId,
        toNodeId: vehicle.targetNodeId
      };
    }

    return null;
  }

  private topLiftOutboundClearanceProtectedRouteNodeIds(vehicle: MutableVehicle): string[] {
    const liftNodeId = this.topLiftOutboundClearanceLiftNodeId(vehicle);
    if (!liftNodeId) {
      return [];
    }
    const exitBottomNodeId = this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId);
    if (!exitBottomNodeId) {
      return [];
    }
    const routeNodeIds = this.vehicleRouteTail(vehicle, vehicle.routeNodeIds);
    const route = routeNodeIds.length > 1
      ? routeNodeIds
      : [vehicle.currentNodeId, vehicle.targetNodeId].filter((nodeId): nodeId is string => nodeId !== null);
    const protectedNodeIds: string[] = [];
    for (let index = 1; index < route.length && index <= 5; index += 1) {
      const nodeId = route[index]!;
      protectedNodeIds.push(nodeId);
      if (nodeId === exitBottomNodeId) {
        break;
      }
    }
    return protectedNodeIds;
  }

  private pointToSegmentDistanceM(
    pointX: number,
    pointZ: number,
    startX: number,
    startZ: number,
    endX: number,
    endZ: number
  ): number {
    const dx = endX - startX;
    const dz = endZ - startZ;
    const lengthSq = dx * dx + dz * dz;
    if (lengthSq <= 1e-9) {
      return Math.hypot(pointX - startX, pointZ - startZ);
    }
    const t = Math.max(0, Math.min(1, ((pointX - startX) * dx + (pointZ - startZ) * dz) / lengthSq));
    const projectionX = startX + t * dx;
    const projectionZ = startZ + t * dz;
    return Math.hypot(pointX - projectionX, pointZ - projectionZ);
  }

  private topLiftLoadedMainLaneBypassesInboundServiceLane(vehicle: MutableVehicle, toNodeId: string, blocker: MutableVehicle): boolean {
    if (
      !/^column-top-a-c\d+$/.test(vehicle.currentNodeId) ||
      !/^column-top-a-c\d+$/.test(toNodeId)
    ) {
      return false;
    }
    const blockerLiftNodeId =
      topLiftQueueServiceSlot(blocker.currentNodeId)?.liftNodeId ??
      topLiftQueueEntrySlot(blocker.currentNodeId)?.liftNodeId ??
      topLiftQueueServiceSlot(blocker.targetNodeId ?? '')?.liftNodeId ??
      topLiftQueueEntrySlot(blocker.targetNodeId ?? '')?.liftNodeId ??
      null;
    if (!blockerLiftNodeId || this.liftPortKindForNodeId(blockerLiftNodeId) !== 'inbound') {
      return false;
    }
    const vehicleNode = this.layoutNode(vehicle.currentNodeId);
    const blockerNode = this.layoutNode(blocker.currentNodeId);
    if (!vehicleNode || !blockerNode) {
      return false;
    }
    return Math.abs(vehicleNode.x - blockerNode.x) <= 2.5;
  }

  private agentRefreshImmediateNodeBlockTakesPrecedence(reason: string): boolean {
    return reason === 'node-occupancy-mismatch' ||
      reason === 'node-occupied' ||
      reason === 'node-local-yield' ||
      reason === 'node-target-near' ||
      reason === 'edge-head-on' ||
      reason.includes('-lift-busy:');
  }

  private topLiftQueueAisleClearThroughBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null
  ): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const entryAccess = topLiftQueueAisleAccess(toNodeId);
    if (!entryAccess) {
      return null;
    }
    const routeNodeIds = candidateRouteNodeIds ?? this.vehicleRouteTailForMove(vehicle, toNodeId);
    const toIndex = routeNodeIds.indexOf(toNodeId);
    if (toIndex < 0) {
      return null;
    }
    const moveIntent = this.topLiftQueueAisleMoveIntent(vehicle, toNodeId);

    for (let index = toIndex; index < routeNodeIds.length && index <= toIndex + 8; index += 1) {
      const nodeId = routeNodeIds[index]!;
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicle.id) {
        return occupantId;
      }
      const claimantId = this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
      if (claimantId) {
        if (
          moveIntent === 'service' &&
          this.topLiftQueueAisleClaimIsQueueEntry(claimantId, entryAccess.liftNodeId)
        ) {
          continue;
        }
        return claimantId;
      }

      if (index === toIndex) {
        continue;
      }
      const access = topLiftQueueAisleAccess(nodeId);
      if (!access || access.liftNodeId !== entryAccess.liftNodeId || topLiftQueueParkingSlot(nodeId)) {
        return null;
      }
    }

    return null;
  }

  private topLiftQueueAisleClaimIsQueueEntry(claimantId: string, liftNodeId: string): boolean {
    const claimant = this.vehicles.find((vehicle) => vehicle.id === claimantId) ?? null;
    if (!claimant || !claimant.targetNodeId) {
      return false;
    }
    if (!this.topLiftNodeBelongsToLiftQueueOrService(claimant.targetNodeId, liftNodeId)) {
      return false;
    }
    return this.topLiftQueueAisleMoveIntent(claimant, claimant.targetNodeId) === 'queue';
  }

  private topLiftQueueAisleMoveIntent(vehicle: MutableVehicle, toNodeId: string): 'queue' | 'service' | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const currentAccess = topLiftQueueAisleAccess(vehicle.currentNodeId);
    const toAccess = topLiftQueueAisleAccess(toNodeId);
    const currentSlot = topLiftQueueParkingSlot(vehicle.currentNodeId);
    const toSlot = topLiftQueueParkingSlot(toNodeId);
    const currentServiceLiftNodeId = this.topLiftQueueServiceLiftNodeId(vehicle.currentNodeId);
    const toServiceLiftNodeId = this.topLiftQueueServiceLiftNodeId(toNodeId);
    const task = this.taskForVehicle(vehicle);
    const taskLiftNodeId = task ? this.taskLiftPortNodeId(task) : null;
    const plannedSlot = vehicle.plannedGoalNodeId ? topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) : null;
    const liftNodeId =
      toAccess?.liftNodeId ??
      currentAccess?.liftNodeId ??
      toSlot?.liftNodeId ??
      currentSlot?.liftNodeId ??
      toServiceLiftNodeId ??
      currentServiceLiftNodeId ??
      taskLiftNodeId ??
      plannedSlot?.liftNodeId ??
      null;
    if (!liftNodeId) {
      return null;
    }

    if (toSlot?.liftNodeId === liftNodeId) {
      return 'queue';
    }
    if (currentAccess?.liftNodeId === liftNodeId && toAccess?.liftNodeId === liftNodeId) {
      if (toAccess.slotIndex > currentAccess.slotIndex) {
        return 'queue';
      }
      if (toAccess.slotIndex < currentAccess.slotIndex) {
        return 'service';
      }
    }
    if (currentSlot?.liftNodeId === liftNodeId && toAccess?.liftNodeId === liftNodeId) {
      return plannedSlot?.liftNodeId === liftNodeId && plannedSlot.slotIndex !== currentSlot.slotIndex
        ? 'queue'
        : 'service';
    }
    if (currentServiceLiftNodeId === liftNodeId && toAccess?.liftNodeId === liftNodeId) {
      return 'queue';
    }
    if (currentAccess?.liftNodeId === liftNodeId && toServiceLiftNodeId === liftNodeId) {
      return 'service';
    }
    if (toServiceLiftNodeId === liftNodeId) {
      return 'service';
    }
    return plannedSlot?.liftNodeId === liftNodeId ? 'queue' : null;
  }

  private topLiftQueueServiceLiftNodeId(nodeId: string): string | null {
    const queueSlot = topLiftQueueParkingSlot(nodeId);
    if (queueSlot) {
      return queueSlot.liftNodeId;
    }
    const queueAccess = topLiftQueueAisleAccess(nodeId);
    if (queueAccess) {
      return queueAccess.liftNodeId;
    }
    const buffer = liftBufferParentNodeId(nodeId);
    if (buffer) {
      return buffer.liftNodeId;
    }
    const suffix = '-buffer-access';
    if (nodeId.endsWith(suffix)) {
      return nodeId.slice(0, -suffix.length);
    }
    return /^(lift-\d{2}-(?:inbound|outbound))-(?:queue-access|queue-\d{2}-(?:entry-access|service-exit))$/.exec(nodeId)?.[1] ?? null;
  }

  private topLiftQueueDeeperClearanceOverlapAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blockerVehicleId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return false;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockerVehicleId) ?? null;
    if (blocker && this.topLiftRearQueueDisplayClearanceAllowedForTarget(vehicle, toNodeId, blocker)) {
      return true;
    }
    if (!blocker?.loaded) {
      return false;
    }
    const currentSlot = topLiftQueueParkingSlot(vehicle.currentNodeId);
    const currentAccess = topLiftQueueAisleAccess(vehicle.currentNodeId);
    const toSlot = topLiftQueueParkingSlot(toNodeId);
    const toAccess = topLiftQueueAisleAccess(toNodeId);
    const liftNodeId = currentSlot?.liftNodeId ?? currentAccess?.liftNodeId ?? null;
    if (!liftNodeId || (toSlot?.liftNodeId ?? toAccess?.liftNodeId) !== liftNodeId) {
      return false;
    }
    const goalSlot = topLiftQueueParkingSlot(vehicle.routeNodeIds.at(-1) ?? '');
    if (!goalSlot || goalSlot.liftNodeId !== liftNodeId) {
      return false;
    }
    const currentIndex = currentSlot?.slotIndex ?? currentAccess?.slotIndex ?? 0;
    const toIndex = toSlot?.slotIndex ?? toAccess?.slotIndex ?? 0;
    const enteringGoalSlotFromAccess =
      !currentSlot &&
      currentAccess !== null &&
      toSlot?.slotIndex === goalSlot.slotIndex &&
      currentAccess.slotIndex === goalSlot.slotIndex;
    if ((goalSlot.slotIndex <= currentIndex && !enteringGoalSlotFromAccess) || toIndex < currentIndex) {
      return false;
    }
    const blockerLiftNodeId =
      this.topLiftQueueServiceLiftNodeId(blocker.currentNodeId) ??
      (blocker.targetNodeId ? this.topLiftQueueServiceLiftNodeId(blocker.targetNodeId) : null);
    return blockerLiftNodeId === liftNodeId;
  }

  private topLiftQueueEntryBlockedByOccupiedFrontSlot(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null
  ): string | null {
    if (!this.topLiftColumnLayoutEnabled() || topLiftQueueParkingSlot(vehicle.currentNodeId)) {
      return null;
    }
    const liftNodeId = this.topLiftQueueEntryLiftNodeId(vehicle, toNodeId, candidateRouteNodeIds);
    if (!liftNodeId) {
      return null;
    }
    const frontSlotNodeId = liftQueueNodeId(liftNodeId, 1);
    const frontSlotOccupantId = this.currentNodeOccupancy.get(frontSlotNodeId);
    if (frontSlotOccupantId && frontSlotOccupantId !== vehicle.id) {
      return frontSlotOccupantId;
    }
    return this.nodeClaimedByOtherVehicle(frontSlotNodeId, vehicle.id);
  }

  private topLiftQueueEntryLiftNodeId(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null
  ): string | null {
    const routeNodeIds = candidateRouteNodeIds ?? this.vehicleRouteTailForMove(vehicle, toNodeId);
    const currentIndex = routeNodeIds.indexOf(vehicle.currentNodeId);
    const startIndex = currentIndex >= 0 ? currentIndex : 0;
    for (let index = Math.max(0, startIndex + 1); index < routeNodeIds.length; index += 1) {
      const nodeId = routeNodeIds[index]!;
      const accessLiftNodeId = this.topLiftQueueAccessLiftNodeId(nodeId);
      if (accessLiftNodeId) {
        return accessLiftNodeId;
      }
      const slot = topLiftQueueParkingSlot(nodeId);
      if (slot) {
        return slot.liftNodeId;
      }
      if (index > startIndex + 4) {
        break;
      }
    }
    return this.topLiftQueueAccessLiftNodeId(toNodeId);
  }

  private topLiftQueueAccessLiftNodeId(nodeId: string): string | null {
    const suffix = '-queue-access';
    return nodeId.endsWith(suffix) ? nodeId.slice(0, -suffix.length) : null;
  }

  private agentRefreshNoStopContinuationBlock(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null = null
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    if (!isTopLiftSpineLevelNodeId(toNodeId, 'middle')) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (!this.mustClearNoStopNode(vehicle, task, toNodeId)) {
      return null;
    }
    const candidateRouteIndex = candidateRouteNodeIds?.indexOf(toNodeId) ?? -1;
    const nextNodeId = candidateRouteNodeIds
      ? candidateRouteIndex >= 0
        ? candidateRouteNodeIds[candidateRouteIndex + 1] ?? null
        : null
      : this.agentRouteNodeAfter(vehicle, toNodeId);
    if (!nextNodeId) {
      return { reason: 'no-stop-continuation-blocked', blockingVehicleId: null };
    }
    const occupantId = this.currentNodeOccupancy.get(nextNodeId);
    if (occupantId && occupantId !== vehicle.id) {
      const blocker = this.vehicles.find((candidate) => candidate.id === occupantId) ?? null;
      if (blocker && this.topLiftSameDirectionNoStopFollowerAllowed(vehicle, toNodeId, nextNodeId, blocker)) {
        return null;
      }
      return { reason: 'no-stop-continuation-blocked', blockingVehicleId: occupantId };
    }
    const targetClaimId = this.movingVehicleTargetingNode(nextNodeId, vehicle.id);
    if (targetClaimId) {
      const blocker = this.vehicles.find((candidate) => candidate.id === targetClaimId) ?? null;
      if (blocker && this.topLiftSameDirectionNoStopFollowerAllowed(vehicle, toNodeId, nextNodeId, blocker)) {
        return null;
      }
      return { reason: 'no-stop-continuation-blocked', blockingVehicleId: targetClaimId };
    }
    return null;
  }

  private topLiftSameDirectionNoStopFollowerAllowed(
    vehicle: MutableVehicle,
    throughNodeId: string,
    nextNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.id === blocker.id) {
      return false;
    }
    const requestedClaim = this.topLiftVerticalSpineClaimFromRoute([
      vehicle.currentNodeId,
      throughNodeId,
      nextNodeId
    ]);
    const blockerClaim = this.topLiftVerticalSpineActiveClaim(blocker);
    if (
      !requestedClaim ||
      !blockerClaim ||
      requestedClaim.spineKey !== blockerClaim.spineKey ||
      requestedClaim.direction !== blockerClaim.direction
    ) {
      return false;
    }
    const headwayM = Math.max(
      this.scenario.vehicles.lengthM * 2 + this.scenario.vehicles.safetyRadiusM,
      this.scenario.vehicles.widthM + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM
    );
    const longitudinalGapM = requestedClaim.direction * (blocker.z - vehicle.z);
    if (longitudinalGapM <= headwayM) {
      return false;
    }

    const blockerAheadOfThroughNodeM = requestedClaim.direction *
      (blocker.z - (this.layoutNode(throughNodeId)?.z ?? vehicle.z));
    return blockerAheadOfThroughNodeM > -headwayM;
  }

  private topLiftSameDirectionMovingFollowerAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.id === blocker.id ||
      blocker.currentEdgeId === null ||
      blocker.targetNodeId === null ||
      blocker.legRemainingM <= 0 ||
      !this.topLiftColumnSpineOrAccessNode(vehicle.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(toNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(blocker.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(blocker.targetNodeId)
    ) {
      return false;
    }
    const from = this.layoutNode(vehicle.currentNodeId);
    const to = this.layoutNode(toNodeId);
    const blockerFrom = this.layoutNode(blocker.currentNodeId);
    const blockerTo = this.layoutNode(blocker.targetNodeId);
    if (!from || !to || !blockerFrom || !blockerTo) {
      return false;
    }
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const length = Math.hypot(dx, dz);
    const blockerDx = blockerTo.x - blockerFrom.x;
    const blockerDz = blockerTo.z - blockerFrom.z;
    const blockerLength = Math.hypot(blockerDx, blockerDz);
    if (length <= 1e-9 || blockerLength <= 1e-9) {
      return false;
    }
    const ux = dx / length;
    const uz = dz / length;
    const blockerUx = blockerDx / blockerLength;
    const blockerUz = blockerDz / blockerLength;
    if (ux * blockerUx + uz * blockerUz < 0.99) {
      return false;
    }

    const relX = blocker.x - vehicle.x;
    const relZ = blocker.z - vehicle.z;
    const projection = relX * ux + relZ * uz;
    const lateral = Math.abs(relX * -uz + relZ * ux);
    const laneToleranceM = Math.max(0.2, this.scenario.vehicles.widthM * 0.65);
    if (lateral > laneToleranceM) {
      return false;
    }
    const requiredHeadwayM = Math.max(
      this.scenario.vehicles.lengthM * 2 + this.scenario.vehicles.safetyRadiusM,
      this.scenario.vehicles.widthM + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM
    );
    return projection > requiredHeadwayM;
  }

  private agentRefreshBlockerIsTrailingCurrentNode(vehicle: MutableVehicle, blocker: MutableVehicle): boolean {
    if (blocker.currentEdgeId !== null || blocker.legRemainingM > 0) {
      return false;
    }
    if (blocker.targetNodeId === vehicle.currentNodeId) {
      return true;
    }
    return blocker.routeNodeIds[blocker.routeIndex + 1] === vehicle.currentNodeId;
  }

  private agentRefreshBlockerIsBehindCurrentMove(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const from = nodePosition(this.scenario, vehicle.currentNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const length = Math.hypot(dx, dz);
    if (length <= 1e-9) {
      return false;
    }

    const ux = dx / length;
    const uz = dz / length;
    const relX = blocker.x - from.x;
    const relZ = blocker.z - from.z;
    const projection = relX * ux + relZ * uz;
    const lateral = Math.abs(relX * -uz + relZ * ux);
    const sameLaneToleranceM = Math.max(0.2, this.scenario.vehicles.widthM * 0.8);
    if (projection >= -0.05 || lateral > sameLaneToleranceM) {
      return false;
    }

    if (
      this.topLiftColumnLayoutEnabled() &&
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      isTopLiftAisleLevelNodeId(toNodeId, 'middle') &&
      (
        isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle') ||
        (blocker.targetNodeId !== null && isTopLiftAisleLevelNodeId(blocker.targetNodeId, 'middle'))
      )
    ) {
      return true;
    }

    const blockerDirection = this.vehicleMovementDirection(blocker);
    return !blockerDirection || blockerDirection.ux * ux + blockerDirection.uz * uz > 0.35;
  }

  private agentRefreshColumnEdgeBlocker(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { reason: string; blockingVehicleId: string | null } | null {
    const inboundQueueEntryBlockerId = this.topLiftInboundQueueEntryLoadedColumnBlocker(vehicle, toNodeId);
    if (inboundQueueEntryBlockerId) {
      return { reason: 'lift-column-near', blockingVehicleId: inboundQueueEntryBlockerId };
    }
    const blockingVehicleId = this.agentRefreshNearColumnSweptFootprintBlocker(vehicle, vehicle.currentNodeId, toNodeId);
    if (
      blockingVehicleId &&
      this.topLiftOutboundClearanceExitPastWaitingLoadedOutboundAllowed(vehicle, toNodeId, blockingVehicleId)
    ) {
      return null;
    }
    if (
      blockingVehicleId &&
      this.topLiftOutboundEntryPastTrailingLoadedFollowerAllowed(vehicle, toNodeId, blockingVehicleId)
    ) {
      return null;
    }
    if (
      blockingVehicleId &&
      this.topLiftQueueDeeperClearanceOverlapAllowed(vehicle, toNodeId, blockingVehicleId)
    ) {
      return null;
    }
    if (
      blockingVehicleId &&
      this.topLiftOutboundBufferContinuationAllowed(vehicle, toNodeId, blockingVehicleId)
    ) {
      return null;
    }
    return blockingVehicleId ? { reason: 'lift-column-near', blockingVehicleId } : null;
  }

  private topLiftOutboundClearanceExitPastWaitingLoadedOutboundAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blockerVehicleId: string
  ): boolean {
    const liftNodeId = this.topLiftOutboundClearanceLiftNodeId(vehicle);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'outbound') {
      return false;
    }
    const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    const exitBottomNodeId = currentEntrySlot ? this.topLiftQueueEntryBottomAccessNodeId(vehicle.currentNodeId) : null;
    if (
      !currentEntrySlot ||
      currentEntrySlot.liftNodeId !== liftNodeId ||
      toNodeId !== exitBottomNodeId ||
      !isTopLiftAisleLevelNodeId(toNodeId, 'top-b')
    ) {
      return false;
    }

    const blocker = this.vehicles.find((candidate) => candidate.id === blockerVehicleId) ?? null;
    if (!blocker?.loaded || !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'top-a')) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind !== 'outbound' || this.taskLiftPortNodeId(blockerTask) !== liftNodeId) {
      return false;
    }
    const blockerColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    const exitColumn = this.topLiftColumnAccessColumn(toNodeId);
    if (blockerColumn === null || blockerColumn !== exitColumn) {
      return false;
    }
    const blockerTargetEntry = topLiftQueueEntrySlot(blocker.targetNodeId ?? '');
    const blockerMeterSlot = blocker.plannedGoalNodeId
      ? this.topLiftOutboundMeterSlot(blocker.plannedGoalNodeId)
      : null;
    return blockerTargetEntry?.liftNodeId === liftNodeId || blockerMeterSlot?.liftNodeId === liftNodeId;
  }

  private topLiftOutboundEntryPastTrailingLoadedFollowerAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blockerVehicleId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded) {
      return false;
    }
    const entrySlot = topLiftQueueEntrySlot(toNodeId);
    if (!entrySlot || this.liftPortKindForNodeId(entrySlot.liftNodeId) !== 'outbound') {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'outbound' || this.taskLiftPortNodeId(task) !== entrySlot.liftNodeId) {
      return false;
    }
    const approachAccessNodeId = this.topLiftQueueEntryTopAccessNodeId(toNodeId);
    const exitAccessNodeId = this.topLiftQueueEntryBottomAccessNodeId(toNodeId);
    if (!approachAccessNodeId || !exitAccessNodeId || vehicle.currentNodeId !== approachAccessNodeId) {
      return false;
    }

    const blocker = this.vehicles.find((candidate) => candidate.id === blockerVehicleId) ?? null;
    if (!blocker?.loaded) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind !== 'outbound' || this.taskLiftPortNodeId(blockerTask) !== entrySlot.liftNodeId) {
      return false;
    }
    if (topLiftQueueEntrySlot(blocker.currentNodeId) || topLiftQueueServiceSlot(blocker.currentNodeId)) {
      return false;
    }
    return blocker.currentNodeId === exitAccessNodeId || blocker.targetNodeId === approachAccessNodeId;
  }

  private topLiftInboundQueueEntryLoadedColumnBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || !isTopLiftAisleLevelNodeId(toNodeId, 'top-b')) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    const queueSlot = topLiftQueueParkingSlot(vehicle.plannedGoalNodeId ?? vehicle.routeNodeIds.at(-1) ?? '');
    if (
      task?.kind !== 'inbound' ||
      !queueSlot ||
      this.liftPortKindForNodeId(queueSlot.liftNodeId) !== 'inbound'
    ) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(toNodeId);
    if (!column) {
      return null;
    }
    const topANodeId = columnAccessNodeId('top-a', column - 1);
    const topBNodeId = columnAccessNodeId('top-b', column - 1);
    const blocker = this.vehicles.find((candidate) =>
      candidate.id !== vehicle.id &&
      candidate.loaded &&
      (
        candidate.currentNodeId === topANodeId ||
        candidate.targetNodeId === topANodeId ||
        candidate.currentNodeId === topBNodeId ||
        candidate.targetNodeId === topBNodeId
      )
    );
    return blocker?.id ?? null;
  }

  private topLiftOutboundBufferContinuationAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blockerVehicleId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded) {
      return false;
    }
    const targetBuffer = liftBufferParentNodeId(toNodeId);
    if (targetBuffer?.kind !== 'outbound') {
      return false;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockerVehicleId) ?? null;
    if (!blocker?.loaded) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    const blockerTask = this.taskForVehicle(blocker);
    if (
      task?.kind !== 'outbound' ||
      blockerTask?.kind !== 'outbound' ||
      this.taskLiftPortNodeId(task) !== targetBuffer.liftNodeId ||
      this.taskLiftPortNodeId(blockerTask) !== targetBuffer.liftNodeId ||
      !this.taskPrecedes(task, blockerTask)
    ) {
      return false;
    }
    const blockerLiftNodeId =
      this.topLiftQueueServiceLiftNodeId(blocker.currentNodeId) ??
      (blocker.targetNodeId ? this.topLiftQueueServiceLiftNodeId(blocker.targetNodeId) : null);
    return blockerLiftNodeId === targetBuffer.liftNodeId;
  }

  private topLiftMiddleAisleOpposingClaimBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null = null
  ): string | null {
    const requestedClaim = this.topLiftMiddleAisleRequestedClaim(vehicle, toNodeId, candidateRouteNodeIds);
    if (!requestedClaim) {
      return null;
    }

    const blocker = this.vehicles.find((other) => {
      if (other.id === vehicle.id) {
        return false;
      }
      if (
        other.waitReason === 'no-stop-continuation-blocked' &&
        other.blockingVehicleId === vehicle.id
      ) {
        return false;
      }
      if (this.topLiftTasklessStorageExitPrecedesLoadedInboundEntry(vehicle, toNodeId, other)) {
        return false;
      }
      const activeClaim = this.topLiftMiddleAisleActiveClaim(other);
      if (
        activeClaim === null ||
        activeClaim.direction === requestedClaim.direction ||
        !this.topLiftMiddleAisleClaimsOverlap(requestedClaim, activeClaim)
      ) {
        return false;
      }
      if (
        isTopLiftAisleLevelNodeId(other.currentNodeId, 'middle') ||
        (
          other.currentEdgeId !== null &&
          other.targetNodeId !== null &&
          isTopLiftAisleLevelNodeId(other.targetNodeId, 'middle')
        )
      ) {
        return true;
      }
      return this.agentRefreshHasHigherPriority(other, vehicle);
    });
    return blocker?.id ?? null;
  }

  private topLiftStorageMiddleExitLookaheadBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null = null
  ): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !this.isStorageNode(toNodeId)
    ) {
      return null;
    }

    const route = candidateRouteNodeIds ?? this.vehicleRouteTailForMove(vehicle, toNodeId);
    if (route[0] !== vehicle.currentNodeId || route[1] !== toNodeId) {
      return null;
    }

    const exitNodeId = route[2] ?? null;
    if (!exitNodeId || !isTopLiftAisleLevelNodeId(exitNodeId, 'middle')) {
      return null;
    }

    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const targetPosition = this.storageGridPosition(toNodeId);
    if (
      !currentPosition ||
      !targetPosition ||
      currentPosition.column !== targetPosition.column
    ) {
      return null;
    }

    const requestedClaim = this.topLiftMiddleAisleClaimFromRoute(route.slice(1, 5));
    if (!requestedClaim) {
      return null;
    }

    const directBlockerId = this.currentNodeOccupancy.get(exitNodeId);
    if (directBlockerId && directBlockerId !== vehicle.id) {
      return directBlockerId;
    }

    const blocker = this.vehicles.find((other) => {
      if (other.id === vehicle.id) {
        return false;
      }
      const activeClaim = this.topLiftMiddleAisleActiveClaim(other);
      if (
        !activeClaim ||
        activeClaim.direction === requestedClaim.direction ||
        !this.topLiftMiddleAisleClaimsOverlap(requestedClaim, activeClaim)
      ) {
        return false;
      }
      if (other.currentNodeId === exitNodeId || other.targetNodeId === exitNodeId) {
        return true;
      }
      const activeRoute = this.vehicleRouteTail(other, other.routeNodeIds);
      const exitIndex = activeRoute.indexOf(exitNodeId);
      return exitIndex >= 0 && exitIndex <= 2;
    });
    return blocker?.id ?? null;
  }

  private topLiftTasklessStorageExitPrecedesLoadedInboundEntry(
    vehicle: MutableVehicle,
    toNodeId: string,
    other: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId !== null ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !isTopLiftColumnAccessNodeId(toNodeId) ||
      !other.loaded
    ) {
      return false;
    }
    const exitColumn = this.storageGridPosition(vehicle.currentNodeId)?.column ?? null;
    if (exitColumn === null || this.topLiftColumnAccessColumn(toNodeId) !== exitColumn) {
      return false;
    }
    const otherTask = this.taskForVehicle(other);
    const otherDropoffColumn = otherTask?.kind === 'inbound'
      ? this.storageGridPosition(otherTask.dropoffNodeId)?.column ?? null
      : null;
    if (otherDropoffColumn !== exitColumn) {
      return false;
    }
    const otherRoute = new Set([
      other.currentNodeId,
      other.targetNodeId,
      other.plannedGoalNodeId,
      ...this.vehicleRouteTail(other, other.routeNodeIds),
      ...this.vehicleRouteTail(other, other.plannedRouteNodeIds),
      ...this.vehicleRouteTail(other, other.localRouteNodeIds)
    ].filter((nodeId): nodeId is string => Boolean(nodeId)));
    return otherRoute.has(vehicle.currentNodeId) || otherRoute.has(toNodeId);
  }

  private topLiftMiddleAisleRequestedClaim(
    vehicle: MutableVehicle,
    toNodeId: string,
    candidateRouteNodeIds: string[] | null = null
  ): { direction: -1 | 1; minX: number; maxX: number } | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(toNodeId, 'middle')
    ) {
      return null;
    }

    return this.topLiftMiddleAisleClaimFromRoute(candidateRouteNodeIds ?? this.vehicleRouteTailForMove(vehicle, toNodeId));
  }

  private topLiftMiddleAisleActiveClaim(vehicle: MutableVehicle): { direction: -1 | 1; minX: number; maxX: number } | null {
    if (
      vehicle.waitReason === 'middle-aisle-opposing-claim' &&
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      !(
        vehicle.currentEdgeId !== null &&
        vehicle.targetNodeId !== null &&
        isTopLiftAisleLevelNodeId(vehicle.targetNodeId, 'middle')
      )
    ) {
      return null;
    }
    if (
      vehicle.waitReason === 'local-yield-hold' &&
      vehicle.currentEdgeId === null &&
      vehicle.targetNodeId === vehicle.currentNodeId
    ) {
      return null;
    }
    if (
      vehicle.waitReason === 'node-local-yield' &&
      vehicle.currentEdgeId === null &&
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      !(vehicle.targetNodeId !== null && isTopLiftAisleLevelNodeId(vehicle.targetNodeId, 'middle'))
    ) {
      return null;
    }

    const routeCandidates = this.activeTrafficClaimRouteCandidates(vehicle);

    for (const routeNodeIds of routeCandidates) {
      const claim = this.topLiftMiddleAisleClaimFromRoute(routeNodeIds);
      if (claim) {
        return claim;
      }
    }
    return null;
  }

  private topLiftMiddleAisleClaimsOverlap(
    left: { minX: number; maxX: number },
    right: { minX: number; maxX: number }
  ): boolean {
    const clearanceM = Math.max(this.scenario.vehicles.lengthM, this.scenario.vehicles.widthM) * 1.5;
    return left.minX <= right.maxX + clearanceM && right.minX <= left.maxX + clearanceM;
  }

  private topLiftMiddleAisleClaimFromRoute(routeNodeIds: string[]): { direction: -1 | 1; minX: number; maxX: number } | null {
    let direction: -1 | 1 | null = null;
    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;

    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromNodeId = routeNodeIds[index - 1]!;
      const toNodeId = routeNodeIds[index]!;
      const moveDirection = this.topLiftMiddleAisleMoveDirection(fromNodeId, toNodeId);
      if (!moveDirection) {
        continue;
      }
      const fromNode = this.layoutNode(fromNodeId);
      const toNode = this.layoutNode(toNodeId);
      if (!fromNode || !toNode) {
        continue;
      }
      direction ??= moveDirection;
      if (moveDirection !== direction) {
        break;
      }
      minX = Math.min(minX, fromNode.x, toNode.x);
      maxX = Math.max(maxX, fromNode.x, toNode.x);
    }

    return direction === null ? null : { direction, minX, maxX };
  }

  private vehicleRouteTailForMove(vehicle: MutableVehicle, toNodeId: string): string[] {
    const routeNodeIds = this.vehicleRouteTail(vehicle, vehicle.routeNodeIds);
    if (routeNodeIds.length === 0) {
      return [vehicle.currentNodeId, toNodeId];
    }
    if (routeNodeIds[0] !== vehicle.currentNodeId) {
      routeNodeIds.unshift(vehicle.currentNodeId);
    }
    if (routeNodeIds[1] !== toNodeId) {
      routeNodeIds.splice(1, 0, toNodeId);
    }
    return routeNodeIds;
  }

  private activeTrafficClaimRouteCandidates(vehicle: MutableVehicle): string[][] {
    const routeCandidates: string[][] = [];
    if (vehicle.currentEdgeId !== null && vehicle.targetNodeId) {
      routeCandidates.push([vehicle.currentNodeId, vehicle.targetNodeId]);
    }
    if (!this.vehicleFutureClaimsEnabled(vehicle)) {
      return routeCandidates;
    }
    if (vehicle.targetNodeId && vehicle.currentEdgeId === null) {
      routeCandidates.push([vehicle.currentNodeId, vehicle.targetNodeId]);
    }
    routeCandidates.push(
      this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.localRouteNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds)
    );
    return routeCandidates;
  }

  private shadowPlannedRouteClaimTail(vehicle: MutableVehicle, maxNodeCount = 6): string[] {
    if (vehicle.plannedRouteNodeIds.length < 2) {
      return [];
    }
    const routeTail = this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds);
    if (routeTail.length < 2) {
      return [];
    }
    return this.topLiftRemoteInboundActiveServiceRouteShouldStageClaims(vehicle, routeTail)
      ? routeTail.slice(0, maxNodeCount)
      : routeTail;
  }

  private topLiftRemoteInboundActiveServiceRouteShouldStageClaims(vehicle: MutableVehicle, routeTail: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (
      task?.kind !== 'inbound' ||
      (task.state !== 'assigned' && task.state !== 'in-progress')
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    const targetSlot = this.topLiftInboundApproachQueueSlot(vehicle.targetNodeId ?? '');
    const plannedSlot = this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId ?? '');
    if (
      plannedSlot?.liftNodeId !== liftNodeId ||
      currentSlot?.liftNodeId === liftNodeId ||
      targetSlot?.liftNodeId === liftNodeId
    ) {
      return false;
    }
    return routeTail.some((nodeId) => {
      if (this.isStorageNode(nodeId)) {
        return true;
      }
      const level = topLiftAisleLevel(nodeId);
      return level === 'middle' || level === 'bottom-a' || level === 'bottom-b';
    });
  }

  private vehicleRouteTail(vehicle: MutableVehicle, routeNodeIds: string[]): string[] {
    if (routeNodeIds.length === 0) {
      return [];
    }
    const currentIndex = routeNodeIds.indexOf(vehicle.currentNodeId);
    if (currentIndex >= 0) {
      return routeNodeIds.slice(currentIndex);
    }
    if (vehicle.targetNodeId) {
      const targetIndex = routeNodeIds.indexOf(vehicle.targetNodeId);
      if (targetIndex >= 0) {
        return [vehicle.currentNodeId, ...routeNodeIds.slice(targetIndex)];
      }
    }
    return [vehicle.currentNodeId, ...routeNodeIds];
  }

  private topLiftMiddleAisleDirectionFromRoute(routeNodeIds: string[]): -1 | 1 | null {
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const direction = this.topLiftMiddleAisleMoveDirection(routeNodeIds[index - 1]!, routeNodeIds[index]!);
      if (direction) {
        return direction;
      }
    }
    return null;
  }

  private topLiftMiddleAisleMoveDirection(fromNodeId: string, toNodeId: string): -1 | 1 | null {
    if (!isTopLiftAisleLevelNodeId(fromNodeId, 'middle') || !isTopLiftAisleLevelNodeId(toNodeId, 'middle')) {
      return null;
    }
    const fromNode = this.layoutNode(fromNodeId);
    const toNode = this.layoutNode(toNodeId);
    if (!fromNode || !toNode) {
      return null;
    }
    const dx = Math.sign(toNode.x - fromNode.x);
    return dx === -1 || dx === 1 ? dx : null;
  }

  private topLiftVerticalSpineOpposingClaimBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    const requestedClaim = this.topLiftVerticalSpineRequestedClaim(vehicle, toNodeId);
    if (!requestedClaim) {
      return null;
    }

    const blocker = this.vehicles.find((other) => {
      if (other.id === vehicle.id) {
        return false;
      }
      if (
        other.waitReason === 'no-stop-continuation-blocked' &&
        other.blockingVehicleId === vehicle.id
      ) {
        return false;
      }
      const activeClaim = this.topLiftVerticalSpineActiveClaim(other);
      if (
        activeClaim === null ||
        activeClaim.spineKey !== requestedClaim.spineKey ||
        activeClaim.direction === requestedClaim.direction ||
        !this.topLiftVerticalSpineClaimsOverlap(requestedClaim, activeClaim)
      ) {
        return false;
      }
      if (
        this.agentRefreshBlockerIsTrailingCurrentNode(vehicle, other) ||
        this.agentRefreshBlockerIsBehindCurrentMove(vehicle, toNodeId, other)
      ) {
        return false;
      }
      if (
        other.currentEdgeId === null &&
        other.speedMps <= 0 &&
        this.topLiftVerticalSpinePrecedenceAllows(vehicle, other)
      ) {
        return false;
      }
      if (
        topLiftSpineKey(other.currentNodeId) === requestedClaim.spineKey ||
        (
          other.targetNodeId !== null &&
          topLiftSpineKey(other.targetNodeId) === requestedClaim.spineKey
        ) ||
        (
          other.currentEdgeId !== null &&
          other.targetNodeId !== null &&
          topLiftSpineKey(other.targetNodeId) === requestedClaim.spineKey
        )
      ) {
        return true;
      }
      return false;
    });
    return blocker?.id ?? null;
  }

  private topLiftVerticalSpinePrecedenceAllows(vehicle: MutableVehicle, other: MutableVehicle): boolean {
    if (vehicle.loaded !== other.loaded) {
      return vehicle.loaded;
    }
    const task = this.taskForVehicle(vehicle);
    const otherTask = this.taskForVehicle(other);
    if (task && otherTask) {
      if (this.taskPrecedes(task, otherTask)) {
        return true;
      }
      if (this.taskPrecedes(otherTask, task)) {
        return false;
      }
    }
    const priority = this.priorityFor(vehicle);
    const otherPriority = this.priorityFor(other);
    return priority > otherPriority ||
      (priority === otherPriority && vehicle.id.localeCompare(other.id) < 0);
  }

  private topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(
    vehicle: MutableVehicle,
    routeNodeIds: string[]
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || routeNodeIds.length < 2) {
      return false;
    }
    const requestedClaim = this.topLiftVerticalSpineClaimFromRoute(routeNodeIds);
    if (!requestedClaim) {
      return false;
    }

    return this.vehicles.some((other) => {
      if (other.id === vehicle.id || !other.loaded) {
        return false;
      }
      const activeClaim = this.topLiftVerticalSpineActiveClaim(other);
      return Boolean(
        activeClaim &&
        activeClaim.spineKey === requestedClaim.spineKey &&
        activeClaim.direction !== requestedClaim.direction &&
        this.topLiftVerticalSpineClaimsOverlap(requestedClaim, activeClaim)
      );
    });
  }

  private topLiftVerticalSpineRequestedClaim(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { spineKey: string; direction: -1 | 1; minZ: number; maxZ: number } | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const routeNodeIds = this.vehicleRouteTailForMove(vehicle, toNodeId);
    const firstVerticalMoveIndex = routeNodeIds.findIndex((nodeId, index) =>
      index > 0 && this.topLiftVerticalSpineMove(routeNodeIds[index - 1]!, nodeId) !== null
    );
    if (firstVerticalMoveIndex < 1) {
      return null;
    }
    const firstVerticalMoveFromIndex = firstVerticalMoveIndex - 1;
    const enteringSpineNow = firstVerticalMoveFromIndex <= 1;
    if (!enteringSpineNow) {
      return null;
    }
    return this.topLiftVerticalSpineClaimFromRoute(routeNodeIds.slice(firstVerticalMoveFromIndex));
  }

  private topLiftVerticalSpineActiveClaim(vehicle: MutableVehicle): { spineKey: string; direction: -1 | 1; minZ: number; maxZ: number } | null {
    if (
      vehicle.waitReason === 'local-yield-hold' &&
      vehicle.currentEdgeId === null &&
      vehicle.targetNodeId === vehicle.currentNodeId
    ) {
      return null;
    }

    const routeCandidates = this.activeTrafficClaimRouteCandidates(vehicle);

    for (const routeNodeIds of routeCandidates) {
      const claim = this.topLiftVerticalSpineClaimFromRoute(routeNodeIds);
      if (claim) {
        return claim;
      }
    }
    return null;
  }

  private topLiftVerticalSpineClaimsOverlap(
    left: { minZ: number; maxZ: number },
    right: { minZ: number; maxZ: number }
  ): boolean {
    const clearanceM = Math.max(this.scenario.vehicles.lengthM, this.scenario.vehicles.widthM) * 1.5;
    return left.minZ <= right.maxZ + clearanceM && right.minZ <= left.maxZ + clearanceM;
  }

  private topLiftVerticalSpineClaimFromRoute(routeNodeIds: string[]): { spineKey: string; direction: -1 | 1; minZ: number; maxZ: number } | null {
    let spineKey: string | null = null;
    let direction: -1 | 1 | null = null;
    let minZ = Number.POSITIVE_INFINITY;
    let maxZ = Number.NEGATIVE_INFINITY;

    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromNodeId = routeNodeIds[index - 1]!;
      const toNodeId = routeNodeIds[index]!;
      const move = this.topLiftVerticalSpineMove(fromNodeId, toNodeId);
      if (!move) {
        if (direction !== null) {
          break;
        }
        continue;
      }
      if (spineKey !== null && move.spineKey !== spineKey) {
        break;
      }
      if (direction !== null && move.direction !== direction) {
        break;
      }
      spineKey = move.spineKey;
      direction = move.direction;
      minZ = Math.min(minZ, move.fromZ, move.toZ);
      maxZ = Math.max(maxZ, move.fromZ, move.toZ);
    }

    return spineKey === null || direction === null ? null : { spineKey, direction, minZ, maxZ };
  }

  private topLiftVerticalSpineMove(fromNodeId: string, toNodeId: string): { spineKey: string; direction: -1 | 1; fromZ: number; toZ: number } | null {
    const spineKey = topLiftSpineKey(fromNodeId);
    if (!spineKey || topLiftSpineKey(toNodeId) !== spineKey) {
      return null;
    }
    const fromNode = this.layoutNode(fromNodeId);
    const toNode = this.layoutNode(toNodeId);
    if (!fromNode || !toNode) {
      return null;
    }
    const dz = Math.sign(toNode.z - fromNode.z);
    return dz === -1 || dz === 1
      ? { spineKey, direction: dz, fromZ: fromNode.z, toZ: toNode.z }
      : null;
  }

  private agentRefreshHandleMoveBlock(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    block: { reason: string; blockingVehicleId: string | null }
  ): boolean {
    const blocker = block.blockingVehicleId
      ? this.vehicles.find((candidate) => candidate.id === block.blockingVehicleId) ?? null
      : null;

    if (this.topLiftFifoHeldVehicle(vehicle)) {
      return false;
    }

    if (block.reason === 'storage-exit-precedence' || block.reason === 'loaded-route-precedence' || block.reason === 'middle-exit-precedence') {
      return false;
    }

    if (block.reason === 'middle-aisle-opposing-claim') {
      const emptyTransferYielder = blocker
        ? this.tryYieldEmptyMiddleBottomTransferFaceoff(vehicle, blocker, blockedTargetNodeId)
        : null;
      if (emptyTransferYielder) {
        return emptyTransferYielder.id === vehicle.id;
      }
      if (blocker && this.tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(vehicle, blocker, blockedTargetNodeId)) {
        return false;
      }
      if (blocker && this.tryYieldEmptyMiddleAisleBlockerAwayFromLoadedInbound(vehicle, blocker, blockedTargetNodeId)) {
        return false;
      }
      if (blocker && this.tryMoveEmptyStorageExitToAdjacentPocketAwayFromLoadedMiddleClaim(vehicle, blockedTargetNodeId, blocker)) {
        return true;
      }
      if (blocker && this.tryRerouteEmptyStorageExitAroundLoadedMiddleClaim(vehicle, blockedTargetNodeId, blocker)) {
        return true;
      }
      if (this.tryMoveAgentRefreshTopLiftTopBEntrantAside(vehicle, blockedTargetNodeId)) {
        return true;
      }
      return blocker
        ? this.tryInstallTopLiftMiddleAisleStorageYield(vehicle, blockedTargetNodeId, blocker)
        : false;
    }

    if (block.reason === 'top-lift-spine-opposing-claim' && blocker) {
      const emptyTransferYielder = this.tryYieldEmptyMiddleBottomTransferFaceoff(vehicle, blocker, blockedTargetNodeId);
      if (emptyTransferYielder) {
        return emptyTransferYielder.id === vehicle.id;
      }
      if (this.tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId)) {
        return true;
      }
      if (this.tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(vehicle, blocker, blockedTargetNodeId)) {
        return false;
      }
      if (this.tryYieldEmptySpineClaimBlockerForLoadedInbound(blocker, vehicle, blockedTargetNodeId)) {
        return false;
      }
      if (this.tryYieldEmptySpineClaimBlockerForLoadedInbound(vehicle, blocker, blocker.targetNodeId ?? blocker.currentNodeId)) {
        return true;
      }
    }

    if (
      block.reason === 'no-stop-continuation-blocked' ||
      this.topLiftLaneTransferShouldWait(vehicle.currentNodeId, blockedTargetNodeId, block.reason)
    ) {
      if (blocker && this.tryClearEmptyNoParkingServiceLaneBlocker(blocker, vehicle, blockedTargetNodeId)) {
        return false;
      }
      if (blocker && this.tryClearEmptyNoParkingSpineBlocker(blocker, vehicle, blockedTargetNodeId)) {
        return false;
      }
      if (blocker && this.tryYieldEmptySpineClaimBlockerForLoadedInbound(blocker, vehicle, blockedTargetNodeId)) {
        return false;
      }
      if (blocker && this.tryYieldLoadedMiddleAccessAwayFromNoStopCycle(vehicle, blocker, blockedTargetNodeId)) {
        return true;
      }
      return false;
    }

    if (!blocker) {
      return false;
    }
    if (this.tryClearEmptyNoParkingServiceLaneBlocker(blocker, vehicle, blockedTargetNodeId)) {
      return false;
    }
    if (
      block.reason === 'outbound-lift-dock-corridor' &&
      this.tryYieldEmptyBottomBDockCorridorBlockerForLoadedOutbound(blocker, vehicle, blockedTargetNodeId)
    ) {
      return false;
    }
    if (this.tryClearTasklessBottomBSpineBlocker(blocker, vehicle, blockedTargetNodeId)) {
      return false;
    }
    if (
      block.reason === 'node-occupied' &&
      this.tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(vehicle, blocker, blockedTargetNodeId)
    ) {
      return false;
    }
    if (this.tryYieldEmptySpineClaimBlockerForLoadedInbound(blocker, vehicle, blockedTargetNodeId)) {
      return false;
    }
    if (this.tryRerouteLoadedInboundAroundOccupiedStorageTransit(vehicle, blockedTargetNodeId, blocker)) {
      return true;
    }
    if (this.tryRetreatOutboundLoadedApproachForQueueExit(vehicle, blocker)) {
      return true;
    }
    if (this.tryRetreatOutboundLoadedApproachForQueueExit(blocker, vehicle)) {
      return false;
    }
    if (this.tryYieldTopLiftAccessBlockerAhead(blocker, vehicle, blockedTargetNodeId)) {
      return false;
    }
    if (this.tryYieldLoadedMiddleColumnBlockerForSpineSwap(vehicle, blocker, blockedTargetNodeId)) {
      return false;
    }
    if (this.tryYieldLoadedMiddleColumnBlockerForSpineSwap(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId)) {
      return true;
    }
    if (
      (block.reason === 'node-occupied' || block.reason === 'node-clearing' || block.reason === 'node-target-near') &&
      this.tryBreakAgentRefreshColumnAccessStorageSwap([vehicle.id, blocker.id])
    ) {
      return vehicle.waitReason === null;
    }
    if (
      (block.reason === 'node-occupied' || block.reason === 'node-clearing' || block.reason === 'node-target-near') &&
      this.tryBreakAgentRefreshStorageColumnQueue([vehicle.id, blocker.id])
    ) {
      return vehicle.waitReason === null;
    }
    const immediateAdjacentSwapYielder = this.tryInstallAgentRefreshTopLiftAdjacentNodeSwapYieldForPair(vehicle, blocker);
    if (immediateAdjacentSwapYielder) {
      return immediateAdjacentSwapYielder.id === vehicle.id;
    }
    if (block.reason === 'top-lift-entry-crossing' && this.tryMoveTopLiftInboundEntryCrossingBlockerAside(vehicle, blocker, blockedTargetNodeId)) {
      return true;
    }
    if (
      (block.reason === 'min-separation' || block.reason === 'avoidance-clearance') &&
      this.tryMoveTopLiftInboundEntryCrossingBlockerAside(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId)
    ) {
      return false;
    }
    if (this.tryFlushTasklessStorageBlockerAhead(blocker, vehicle, blockedTargetNodeId)) {
      return false;
    }
    if (this.tryRetreatLoadedInboundColumnFaceoff(vehicle, blocker)) {
      return true;
    }
    if (this.tryRetreatLoadedInboundColumnFaceoff(blocker, vehicle)) {
      return false;
    }
    if (this.tryYieldStorageAwayFromLoadedInboundDropoffRoute(vehicle, blocker)) {
      return true;
    }
    if (this.tryYieldStorageAwayFromLoadedInboundDropoffRoute(blocker, vehicle)) {
      return false;
    }
    if (this.tryRetreatLoadedInboundColumnEntryForTasklessExit(vehicle, blocker)) {
      return true;
    }
    if (this.tryRetreatLoadedInboundColumnEntryForTasklessExit(blocker, vehicle)) {
      return false;
    }
    if (this.tryYieldStorageAwayFromTopLiftServiceClearance(vehicle, blocker)) {
      return true;
    }
    if (this.tryYieldStorageAwayFromTopLiftServiceClearance(blocker, vehicle)) {
      return false;
    }
    if (this.tryYieldAisleAwayFromTopLiftServiceClearance(vehicle, blocker, blockedTargetNodeId)) {
      return true;
    }
    if (this.tryYieldAisleAwayFromTopLiftServiceClearance(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId)) {
      return false;
    }
    if (this.tryYieldInboundQueueEntrantAwayFromLoadedExit(blocker, vehicle)) {
      return false;
    }
    if (this.tryYieldInboundQueueEntrantAwayFromLoadedExit(vehicle, blocker)) {
      return true;
    }
    const parkedInboundQueueFootprintBlocker =
      this.inboundQueueFootprintBlockerForTopBNode(blockedTargetNodeId, vehicle.id, blocker.id) ?? blocker;
    if (this.tryYieldTopAInboundQueueBlockerForEntryRequester(vehicle, parkedInboundQueueFootprintBlocker, blockedTargetNodeId)) {
      return false;
    }
    if (this.tryRerouteStorageExitAroundParkedInboundQueueBlocker(vehicle, parkedInboundQueueFootprintBlocker, blockedTargetNodeId)) {
      return true;
    }
    if (this.tryBypassParkedInboundQueueBlockerViaTopA(vehicle, parkedInboundQueueFootprintBlocker, blockedTargetNodeId)) {
      return true;
    }
    if (this.tryYieldTopBRequesterAwayFromInboundQueueTail(vehicle, blocker, blockedTargetNodeId)) {
      return true;
    }
    if (this.tryYieldLaterInboundQueueBlockerForEarlierPickup(vehicle, blocker, blockedTargetNodeId)) {
      return false;
    }
    if (this.topLiftInboundRequesterShouldWaitForEarlierPickup(vehicle, blocker)) {
      return this.tryYieldInboundQueueRequesterForEarlierPickup(vehicle, blocker, blockedTargetNodeId);
    }
    if (
      (block.reason === 'node-occupied' || block.reason === 'node-clearing' || block.reason === 'node-target-near') &&
      this.topLiftBlockerHasCommittedContinuationAway(vehicle, blockedTargetNodeId, blocker)
    ) {
      const existingContinuationSession = this.activeConflictSessionForPair(vehicle.id, blocker.id);
      if (existingContinuationSession) {
        this.closeConflictSession(existingContinuationSession, 'blocker-continuing-away');
      }
      return false;
    }
    if (block.reason === 'node-clearing' && blocker.currentEdgeId !== null) {
      return false;
    }
    if (
      (block.reason === 'min-separation' || block.reason === 'avoidance-clearance') &&
      (
        this.agentRefreshSameDirectionFollowerBlock(vehicle, blockedTargetNodeId, blocker) ||
        this.agentRefreshBlockerIsClearingTarget(vehicle, blockedTargetNodeId, blocker)
      )
    ) {
      return false;
    }
    if (this.tryRerouteLoadedInboundTopLaneFaceoff(vehicle, blockedTargetNodeId, blocker)) {
      return true;
    }
    if (this.tryRerouteLoadedTopBFaceoffViaTopA(vehicle, blockedTargetNodeId, blocker)) {
      return true;
    }

    const existingSession = this.activeConflictSessionForPair(vehicle.id, blocker.id);
    if (existingSession) {
      existingSession.updatedAtSec = this.simTimeSec;
      const adjacentSwapYielder = this.tryInstallAgentRefreshTopLiftAdjacentNodeSwapYieldForPair(vehicle, blocker);
      if (adjacentSwapYielder) {
        return adjacentSwapYielder.id === vehicle.id;
      }
      if (vehicle.id === existingSession.winnerVehicleId) {
        if (this.agentRefreshClearProtectedExitYielder(blocker, existingSession, vehicle, blockedTargetNodeId)) {
          return true;
        }
        if (this.agentRefreshMoveQueueYielderDeeper(blocker, existingSession, vehicle, blockedTargetNodeId)) {
          return true;
        }
        return false;
      }
      if (
        vehicle.id === existingSession.yielderVehicleId &&
        !vehicle.currentEdgeId &&
        vehicle.legRemainingM <= 0
      ) {
        existingSession.yielderOriginalNodeId = vehicle.currentNodeId;
        return this.agentRefreshInstallSideYield(vehicle, blockedTargetNodeId, blocker, existingSession);
      }
      return false;
    }

    const adjacentSwapYielder = this.tryInstallAgentRefreshTopLiftAdjacentNodeSwapYieldForPair(vehicle, blocker);
    if (adjacentSwapYielder) {
      return adjacentSwapYielder.id === vehicle.id;
    }

    if (this.isStorageNode(vehicle.currentNodeId) && this.liftStorageTransferTargetLiftId(blockedTargetNodeId) !== null) {
      return false;
    }

    const session = this.createAgentRefreshConflictSession(vehicle, blocker, blockedTargetNodeId, block.reason);
    if (session.yielderVehicleId === blocker.id) {
      if (this.agentRefreshInstallSideYield(blocker, blockedTargetNodeId, vehicle, session)) {
        return false;
      }
      if (vehicle.loaded) {
        return false;
      }
      return this.installSideYieldWithReassignedConflictSession(session, blocker, vehicle, blockedTargetNodeId);
    }

    if (vehicle.loaded) {
      return false;
    }

    return this.agentRefreshInstallSideYield(vehicle, blockedTargetNodeId, blocker, session);
  }

  private tryYieldEmptySpineClaimBlockerForLoadedInbound(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      requester.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      requester.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      !this.topLiftColumnSpineOrAccessNode(blocker.currentNodeId)
    ) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    const requesterTask = this.taskForVehicle(requester);
    if (requesterTask?.kind !== 'inbound' && requesterTask?.kind !== 'outbound') {
      return false;
    }
    if (this.topLiftTaskVehicleMainSpineShouldHoldLine(blocker, blockedTargetNodeId)) {
      return false;
    }

    if (this.emptyTopBSpineBlockerAlreadyClearsLoadedInbound(blocker, requester, blockedTargetNodeId)) {
      return true;
    }

    const protectedNodeIds = new Set<string>([
      requester.currentNodeId,
      blockedTargetNodeId,
      ...this.vehicleRouteTail(requester, requester.routeNodeIds).slice(0, 5)
    ]);
    if (requester.targetNodeId) {
      protectedNodeIds.add(requester.targetNodeId);
    }

    const routeNodeIds = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => !protectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => {
        const node = this.layoutNode(neighbor.nodeId);
        if (!node) {
          return false;
        }
        if (this.isStorageNode(neighbor.nodeId)) {
          return this.topLiftTemporaryYieldStorageHoldAllowed(blocker, neighbor.nodeId);
        }
        if (
          blockerTask?.kind === 'inbound' &&
          isTopLiftSpineLevelNodeId(blocker.currentNodeId, 'top-b') &&
          topLiftAisleLevel(neighbor.nodeId) === 'top-a'
        ) {
          return false;
        }
        return this.topLiftColumnSpineOrAccessNode(neighbor.nodeId) &&
          this.agentRefreshYieldPocketAllowed(blocker, neighbor.nodeId);
      })
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(blocker, neighbor.nodeId, requester))
      .filter((neighbor) =>
        blocker.waitReason === 'route-unavailable' ||
        this.agentRefreshYieldPocketKeepsGoalReachable(blocker, neighbor.nodeId)
      )
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id))
      .map((neighbor) => [blocker.currentNodeId, neighbor.nodeId])
      .filter((route) =>
        this.agentRefreshLocalRouteNodesClear(blocker, route) &&
        !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route)
      )
      .sort((left, right) =>
        Number(!this.isStorageNode(left.at(-1)!)) - Number(!this.isStorageNode(right.at(-1)!)) ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;

    if (!routeNodeIds) {
      if (this.releaseEmptySpineClaimForLoadedRequester(blocker, requester, blockedTargetNodeId)) {
        return true;
      }
      return false;
    }

    const holdRouteNodeIds = this.extendTopLiftTemporaryYieldRouteToHold(blocker, routeNodeIds, protectedNodeIds);
    if (
      !holdRouteNodeIds ||
      holdRouteNodeIds.slice(1).some((nodeId) => protectedNodeIds.has(nodeId)) ||
      !this.agentRefreshLocalRouteNodesClear(blocker, holdRouteNodeIds) ||
      this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, holdRouteNodeIds)
    ) {
      if (this.releaseEmptySpineClaimForLoadedRequester(blocker, requester, blockedTargetNodeId)) {
        return true;
      }
      return false;
    }

    if (!this.installAgentRefreshTopLiftSpineCycleYield(blocker, holdRouteNodeIds, protectedNodeIds)) {
      return false;
    }
    this.logAgentReroute(blocker, blockerTask, blockedTargetNodeId, blocker.routeNodeIds, `empty-spine-claim-yield-for-loaded-${requesterTask.kind}`, { countTaskReplan: false });
    return blocker.waitReason === null && blocker.targetNodeId !== blockedTargetNodeId;
  }

  private releaseEmptySpineClaimForLoadedRequester(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      blocker.loaded ||
      blocker.currentNodeId === blockedTargetNodeId ||
      !this.topLiftColumnSpineOrAccessNode(blocker.currentNodeId)
    ) {
      return false;
    }
    const blockerClaimsBlockedTarget =
      blocker.targetNodeId === blockedTargetNodeId ||
      this.vehicleRouteTail(blocker, blocker.routeNodeIds).slice(0, 4).includes(blockedTargetNodeId) ||
      this.vehicleRouteTail(blocker, blocker.plannedRouteNodeIds).slice(0, 4).includes(blockedTargetNodeId);
    if (!blockerClaimsBlockedTarget) {
      return false;
    }

    const releaseRoute = this.topLiftAccessClearanceRouteForBlocker(blocker, requester, blockedTargetNodeId);
    if (!releaseRoute) {
      return false;
    }

    const targetNodeId = releaseRoute[1]!;
    blocker.routeNodeIds = releaseRoute;
    blocker.routeIndex = 0;
    blocker.targetNodeId = targetNodeId;
    blocker.plannedRouteNodeIds = releaseRoute;
    blocker.localRouteNodeIds = releaseRoute;
    blocker.localRouteReason = 'temporary-yield';
    blocker.state = blocker.taskId ? 'moving-to-pickup' : 'returning';
    blocker.waitReason = null;
    blocker.blockingReservationId = null;
    blocker.blockingVehicleId = null;
    blocker.waitingSinceSec = null;
    blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, releaseRoute) + 2);
    blocker.yieldHoldNodeId = releaseRoute[releaseRoute.length - 1]!;
    this.logAgentReroute(
      blocker,
      this.taskForVehicle(blocker),
      blockedTargetNodeId,
      releaseRoute,
      `empty-spine-claim-released-for-loaded-${this.taskForVehicle(requester)?.kind ?? 'vehicle'}`,
      { countTaskReplan: false }
    );
    return true;
  }

  private tryYieldEmptyMiddleBottomTransferFaceoff(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): MutableVehicle | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || blocker.loaded) {
      return null;
    }

    const middleVehicle = [vehicle, blocker].find((candidate) =>
      candidate.currentEdgeId === null &&
      candidate.legRemainingM <= 0 &&
      candidate.phaseRemainingSec <= 0 &&
      candidate.state !== 'lifting' &&
      candidate.state !== 'lowering' &&
      isTopLiftAisleLevelNodeId(candidate.currentNodeId, 'middle') &&
      candidate.targetNodeId === blockedTargetNodeId
    ) ?? null;
    const bottomVehicle = [vehicle, blocker].find((candidate) =>
      candidate.id !== middleVehicle?.id &&
      candidate.currentEdgeId === null &&
      candidate.legRemainingM <= 0 &&
      candidate.phaseRemainingSec <= 0 &&
      candidate.state !== 'lifting' &&
      candidate.state !== 'lowering' &&
      isTopLiftAisleLevelNodeId(candidate.currentNodeId, 'bottom-a') &&
      candidate.targetNodeId === blockedTargetNodeId
    ) ?? null;
    if (!middleVehicle || !bottomVehicle || !isTopLiftSpineLevelNodeId(blockedTargetNodeId, 'middle')) {
      return null;
    }
    if (this.topLiftFifoHeldVehicle(middleVehicle) || this.topLiftFifoHeldVehicle(bottomVehicle)) {
      return null;
    }

    const protectedNodeIds = new Set<string>([
      bottomVehicle.currentNodeId,
      bottomVehicle.targetNodeId,
      blockedTargetNodeId,
      ...this.vehicleRouteTail(bottomVehicle, bottomVehicle.routeNodeIds).slice(0, 4),
      ...this.vehicleRouteTail(bottomVehicle, bottomVehicle.plannedRouteNodeIds).slice(0, 4)
    ].filter((nodeId): nodeId is string => Boolean(nodeId)));

    const routeNodeIds = this.neighbors(middleVehicle.currentNodeId)
      .filter((neighbor) => this.isStorageNode(neighbor.nodeId))
      .filter((neighbor) => !protectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.topLiftMiddleAisleTemporaryStorageYieldAllowed(middleVehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(middleVehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(middleVehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(middleVehicle, neighbor.nodeId, middleVehicle.currentNodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(middleVehicle, middleVehicle.currentNodeId, neighbor.nodeId))
      .map((neighbor) => [middleVehicle.currentNodeId, neighbor.nodeId])
      .filter((route) =>
        this.agentRefreshLocalRouteNodesClear(middleVehicle, route) &&
        !this.agentRefreshMoveBlocker(middleVehicle, route[1]!, route) &&
        !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(middleVehicle, route)
      )
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;
    if (!routeNodeIds) {
      return this.tryYieldEmptyBottomASpineToBottomBForMiddleFaceoff(bottomVehicle, middleVehicle, blockedTargetNodeId)
        ? bottomVehicle
        : null;
    }

    const session = this.activeConflictSessionForPair(middleVehicle.id, bottomVehicle.id) ??
      this.createAgentRefreshConflictSession(bottomVehicle, middleVehicle, blockedTargetNodeId, 'middle-bottom-empty-transfer-faceoff');
    this.reassignAgentRefreshConflictSession(session, bottomVehicle, middleVehicle, blockedTargetNodeId);
    if (!this.installAgentRefreshSideYieldRoute(middleVehicle, bottomVehicle, blockedTargetNodeId, routeNodeIds, session)) {
      return null;
    }
    this.logAgentReroute(middleVehicle, this.taskForVehicle(middleVehicle), blockedTargetNodeId, routeNodeIds, 'empty-middle-bottom-transfer-faceoff-yield', { countTaskReplan: false });
    return middleVehicle;
  }

  private tryYieldEmptyBottomASpineToBottomBForMiddleFaceoff(
    bottomVehicle: MutableVehicle,
    middleVehicle: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      bottomVehicle.loaded ||
      middleVehicle.loaded ||
      bottomVehicle.currentEdgeId !== null ||
      middleVehicle.currentEdgeId !== null ||
      bottomVehicle.legRemainingM > 0 ||
      middleVehicle.legRemainingM > 0 ||
      bottomVehicle.phaseRemainingSec > 0 ||
      middleVehicle.phaseRemainingSec > 0 ||
      bottomVehicle.state === 'lifting' ||
      bottomVehicle.state === 'lowering' ||
      middleVehicle.state === 'lifting' ||
      middleVehicle.state === 'lowering' ||
      !isTopLiftSpineLevelNodeId(bottomVehicle.currentNodeId, 'bottom-a') ||
      bottomVehicle.targetNodeId !== blockedTargetNodeId ||
      !isTopLiftSpineLevelNodeId(blockedTargetNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(middleVehicle.currentNodeId, 'middle') ||
      middleVehicle.targetNodeId !== blockedTargetNodeId ||
      bottomVehicle.blockingVehicleId !== middleVehicle.id ||
      middleVehicle.blockingVehicleId !== bottomVehicle.id ||
      !this.vehicleRouteTail(middleVehicle, middleVehicle.routeNodeIds).includes(bottomVehicle.currentNodeId)
    ) {
      return false;
    }

    const bottomBNodeId = this.topLiftSpineSiblingNodeId(bottomVehicle.currentNodeId, 'bottom-b');
    if (!bottomBNodeId || !this.layoutNode(bottomBNodeId)) {
      return false;
    }
    const routeNodeIds = [bottomVehicle.currentNodeId, bottomBNodeId];
    if (
      !this.routeEdgesExist(routeNodeIds) ||
      this.currentNodeOccupancy.has(bottomBNodeId) ||
      this.nodeClaimedByOtherVehicle(bottomBNodeId, bottomVehicle.id) ||
      !this.agentMinimalYieldFirstLegSafe(bottomVehicle, bottomVehicle.currentNodeId, bottomBNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(bottomVehicle, routeNodeIds) ||
      this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(bottomVehicle, routeNodeIds) ||
      this.agentRefreshMoveBlocker(bottomVehicle, bottomBNodeId, routeNodeIds)
    ) {
      return false;
    }

    const session = this.activeConflictSessionForPair(bottomVehicle.id, middleVehicle.id) ??
      this.createAgentRefreshConflictSession(middleVehicle, bottomVehicle, blockedTargetNodeId, 'middle-bottom-empty-transfer-faceoff');
    this.reassignAgentRefreshConflictSession(session, middleVehicle, bottomVehicle, blockedTargetNodeId);
    if (!this.installAgentRefreshSideYieldRoute(bottomVehicle, middleVehicle, blockedTargetNodeId, routeNodeIds, session)) {
      return false;
    }
    this.logAgentReroute(
      bottomVehicle,
      this.taskForVehicle(bottomVehicle),
      blockedTargetNodeId,
      routeNodeIds,
      'empty-bottom-a-spine-to-bottom-b-faceoff-yield',
      { countTaskReplan: false }
    );
    return bottomVehicle.targetNodeId !== blockedTargetNodeId && bottomVehicle.waitReason === null;
  }

  private tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string,
    allowEmptyRequester = false
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      (!requester.loaded && !allowEmptyRequester) ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      requester.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      requester.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle') ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'middle'
    ) {
      return false;
    }

    const blockerColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    if (blockerColumn === null) {
      return false;
    }

    const requesterNode = this.layoutNode(requester.currentNodeId);
    const blockerNode = this.layoutNode(blocker.currentNodeId);
    const awayDirection = requesterNode && blockerNode ? Math.sign(blockerNode.x - requesterNode.x) : 0;
    const directions: (-1 | 1)[] = awayDirection === -1 || awayDirection === 1
      ? [awayDirection, awayDirection === 1 ? -1 : 1]
      : [1, -1];
    const protectedNodeIds = new Set<string>([
      requester.currentNodeId,
      requester.targetNodeId,
      blockedTargetNodeId,
      requester.plannedGoalNodeId,
      ...this.agentRefreshRequesterProtectedRouteNodeIds(requester)
    ].filter((nodeId): nodeId is string => Boolean(nodeId)));

    for (const direction of directions) {
      const candidateNodeId = columnAccessNodeId('middle', blockerColumn - 1 + direction);
      const route = [blocker.currentNodeId, candidateNodeId];
      if (
        protectedNodeIds.has(candidateNodeId) ||
        !this.layoutNode(candidateNodeId) ||
        !this.routeEdgesExist(route) ||
        !this.topLiftColumnSpineOrAccessNode(candidateNodeId) ||
        !this.agentRefreshYieldPocketAllowed(blocker, candidateNodeId) ||
        !this.agentRefreshYieldPocketKeepsGoalReachable(blocker, candidateNodeId) ||
        !this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, candidateNodeId) ||
        !this.agentRefreshLocalRouteNodesClear(blocker, route) ||
        this.agentRefreshMoveBlocker(blocker, candidateNodeId, route) ||
        this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route)
      ) {
        continue;
      }

      const installed = this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, route, null);
      if (!installed) {
        continue;
      }
      this.logAgentReroute(blocker, this.taskForVehicle(blocker), blockedTargetNodeId, route, 'empty-middle-access-horizontal-yield-for-loaded-spine', { countTaskReplan: false });
      return blocker.waitReason === null && blocker.targetNodeId !== blockedTargetNodeId;
    }

    const storageRoute = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => this.isStorageNode(neighbor.nodeId))
      .filter((neighbor) => !protectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => !this.storedLoadIdAtNode(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(blocker, neighbor.nodeId, requester))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(blocker, neighbor.nodeId, blockedTargetNodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => {
        const route = [blocker.currentNodeId, neighbor.nodeId];
        return this.agentRefreshLocalRouteNodesClear(blocker, route) &&
          !this.agentRefreshMoveBlocker(blocker, neighbor.nodeId, route) &&
          !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route);
      })
      .sort((left, right) =>
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )
      .map((neighbor) => [blocker.currentNodeId, neighbor.nodeId])
      [0] ?? null;
    if (storageRoute) {
      const installed = this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, storageRoute, null);
      if (!installed) {
        return false;
      }
      this.logAgentReroute(blocker, this.taskForVehicle(blocker), blockedTargetNodeId, storageRoute, 'empty-middle-access-storage-yield-for-loaded-spine', { countTaskReplan: false });
      return blocker.waitReason === null && blocker.targetNodeId !== blockedTargetNodeId;
    }

    const columnEscapeRoute = this.topLiftEmptyMiddleAccessStorageColumnEscapeRoute(
      blocker,
      requester,
      blockedTargetNodeId,
      protectedNodeIds
    );
    if (columnEscapeRoute) {
      const installed = this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, columnEscapeRoute, null);
      if (!installed) {
        return false;
      }
      this.logAgentReroute(blocker, this.taskForVehicle(blocker), blockedTargetNodeId, columnEscapeRoute, 'empty-middle-access-column-storage-escape-for-loaded-spine', { countTaskReplan: false });
      return blocker.waitReason === null && blocker.targetNodeId !== blockedTargetNodeId;
    }

    const extendedStorageRoute = this.topLiftEmptyMiddleAccessExtendedStorageYieldRoute(
      blocker,
      requester,
      blockedTargetNodeId,
      protectedNodeIds,
      directions
    );
    if (extendedStorageRoute) {
      const installed = this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, extendedStorageRoute, null);
      if (!installed) {
        return false;
      }
      this.logAgentReroute(blocker, this.taskForVehicle(blocker), blockedTargetNodeId, extendedStorageRoute, 'empty-middle-access-extended-storage-yield-for-loaded-spine', { countTaskReplan: false });
      return blocker.waitReason === null && blocker.targetNodeId !== blockedTargetNodeId;
    }

    return false;
  }

  private tryYieldEmptyMiddleAccessAwayFromWaitCycle(
    yielder: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      yielder.loaded ||
      this.topLiftFifoHeldVehicle(yielder) ||
      yielder.currentEdgeId !== null ||
      yielder.legRemainingM > 0 ||
      yielder.phaseRemainingSec > 0 ||
      yielder.state === 'lifting' ||
      yielder.state === 'lowering' ||
      !isTopLiftAisleLevelNodeId(yielder.currentNodeId, 'middle')
    ) {
      return false;
    }
    const yielderTargetNodeId = yielder.targetNodeId ?? yielder.plannedGoalNodeId;
    const yielderIsTryingToEnterMiddleSpine =
      yielder.waitReason === 'no-stop-continuation-blocked' ||
      yielder.waitReason === 'top-lift-spine-opposing-claim' ||
      (yielderTargetNodeId !== null && isTopLiftSpineLevelNodeId(yielderTargetNodeId, 'middle'));
    if (!yielderIsTryingToEnterMiddleSpine) {
      return false;
    }
    return this.tryYieldEmptyMiddleAccessHorizontallyForLoadedSpine(
      requester,
      yielder,
      blockedTargetNodeId,
      true
    );
  }

  private tryYieldEmptyBottomASpineAwayFromMiddleAccessCycle(
    yielder: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      yielder.loaded ||
      !requester.loaded ||
      this.topLiftFifoHeldVehicle(yielder) ||
      yielder.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      yielder.legRemainingM > 0 ||
      requester.legRemainingM > 0 ||
      yielder.phaseRemainingSec > 0 ||
      requester.phaseRemainingSec > 0 ||
      yielder.state === 'lifting' ||
      yielder.state === 'lowering' ||
      requester.state === 'lifting' ||
      requester.state === 'lowering' ||
      !isTopLiftSpineLevelNodeId(yielder.currentNodeId, 'bottom-a') ||
      !(
        isTopLiftAisleLevelNodeId(requester.currentNodeId, 'middle') ||
        isTopLiftSpineLevelNodeId(requester.currentNodeId, 'middle')
      ) ||
      !yielder.targetNodeId ||
      !isTopLiftSpineLevelNodeId(yielder.targetNodeId, 'middle') ||
      !(
        yielder.waitReason === 'middle-aisle-opposing-claim' ||
        yielder.waitReason === 'no-stop-continuation-blocked'
      )
    ) {
      return false;
    }

    const protectedNodeIds = new Set(
      [
        requester.currentNodeId,
        requester.targetNodeId,
        blockedTargetNodeId,
        ...this.vehicleRouteTail(requester, requester.routeNodeIds).slice(0, 4),
        ...this.vehicleRouteTail(requester, requester.plannedRouteNodeIds).slice(0, 4)
      ].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    const route = this.neighbors(yielder.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'bottom-a'))
      .filter((neighbor) => !protectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(yielder, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(yielder, yielder.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => {
        const routeNodeIds = [yielder.currentNodeId, neighbor.nodeId];
        return this.routeEdgesExist(routeNodeIds) &&
          this.agentRefreshLocalRouteNodesClear(yielder, routeNodeIds) &&
          !this.agentRefreshMoveBlocker(yielder, neighbor.nodeId, routeNodeIds) &&
          !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(yielder, routeNodeIds);
      })
      .sort((left, right) =>
        this.agentRefreshYieldPocketRank(yielder, left.nodeId) - this.agentRefreshYieldPocketRank(yielder, right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )
      .map((neighbor) => [yielder.currentNodeId, neighbor.nodeId])
      [0] ?? null;
    if (!route) {
      return false;
    }

    return this.installAgentRefreshSideYieldRoute(yielder, requester, blockedTargetNodeId, route, null);
  }

  private topLiftEmptyMiddleAccessStorageColumnEscapeRoute(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    protectedNodeIds: Set<string>
  ): string[] | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle')
    ) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    if (column === null) {
      return null;
    }

    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const routeCandidates: string[][] = [];
    for (const [entryRow, direction, terminalRow] of [
      [rowsPerZone, -1, 1],
      [rowsPerZone + 1, 1, rowsPerZone * 2]
    ] as const) {
      const route = [blocker.currentNodeId];
      for (
        let row = entryRow;
        direction > 0 ? row <= terminalRow : row >= terminalRow;
        row += direction
      ) {
        const nodeId = storageNodeId(row - 1, column - 1);
        route.push(nodeId);
        const isTerminal = !this.storedLoadIdAtNode(nodeId);
        if (!isTerminal) {
          continue;
        }
        if (
          protectedNodeIds.has(nodeId) ||
          !this.agentRefreshYieldPocketAllowed(blocker, nodeId) ||
          !this.agentRefreshYieldPocketCompatibleWithRequester(blocker, nodeId, requester) ||
          !this.agentRefreshYieldPocketKeepsGoalReachable(blocker, nodeId) ||
          !this.agentRefreshYieldPocketCanReturn(blocker, nodeId, blockedTargetNodeId) ||
          !this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, route[1]!) ||
          !this.routeEdgesExist(route) ||
          !this.agentRefreshLocalRouteNodesClear(blocker, route) ||
          this.agentRefreshMoveBlocker(blocker, route[1]!, route) ||
          this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route)
        ) {
          continue;
        }
        routeCandidates.push([...route]);
      }
    }

    return routeCandidates.sort((left, right) =>
      left.length - right.length ||
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    )[0] ?? null;
  }

  private topLiftEmptyMiddleAccessExtendedStorageYieldRoute(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    protectedNodeIds: Set<string>,
    directions: (-1 | 1)[]
  ): string[] | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle')
    ) {
      return null;
    }
    const startColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    if (startColumn === null) {
      return null;
    }

    const candidateRoutes: string[][] = [];
    for (const direction of directions) {
      const middleRoute = [blocker.currentNodeId];
      for (let offset = 1; offset <= 6; offset += 1) {
        const middleNodeId = columnAccessNodeId('middle', startColumn - 1 + direction * offset);
        const previousNodeId = middleRoute[middleRoute.length - 1]!;
        if (
          protectedNodeIds.has(middleNodeId) ||
          !this.layoutNode(middleNodeId) ||
          !this.traffic.findEdge(previousNodeId, middleNodeId) ||
          this.currentNodeOccupancy.has(middleNodeId) ||
          this.nodeClaimedByOtherVehicle(middleNodeId, blocker.id)
        ) {
          break;
        }
        middleRoute.push(middleNodeId);

        for (const storageNeighbor of this.neighbors(middleNodeId)) {
          const storageNodeId = storageNeighbor.nodeId;
          const route = [...middleRoute, storageNodeId];
          if (
            protectedNodeIds.has(storageNodeId) ||
            !this.isStorageNode(storageNodeId) ||
            this.storedLoadIdAtNode(storageNodeId) ||
            !this.agentRefreshYieldPocketAllowed(blocker, storageNodeId) ||
            !this.agentRefreshYieldPocketCompatibleWithRequester(blocker, storageNodeId, requester) ||
            !this.agentRefreshYieldPocketKeepsGoalReachable(blocker, storageNodeId) ||
            !this.agentRefreshYieldPocketCanReturn(blocker, storageNodeId, blockedTargetNodeId) ||
            !this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, route[1]!) ||
            !this.routeEdgesExist(route) ||
            !this.agentRefreshLocalRouteNodesClear(blocker, route) ||
            this.agentRefreshMoveBlocker(blocker, route[1]!, route) ||
            this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route)
          ) {
            continue;
          }
          candidateRoutes.push(route);
        }
      }
    }

    return candidateRoutes.sort((left, right) =>
      left.length - right.length ||
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    )[0] ?? null;
  }

  private tryYieldEmptyMiddleAisleBlockerAwayFromLoadedInbound(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      requesterTask?.kind !== 'inbound' ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      requester.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      requester.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering' ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle') ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'middle'
    ) {
      return false;
    }

    const requesterRouteTail = this.vehicleRouteTail(requester, requester.routeNodeIds);
    const protectedNodeIds = new Set<string>([
      requester.currentNodeId,
      blockedTargetNodeId,
      requester.targetNodeId,
      requester.plannedGoalNodeId,
      ...requesterRouteTail.slice(0, 10)
    ].filter((nodeId): nodeId is string => Boolean(nodeId)));

    const selectedRoute = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => !protectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => {
        const node = this.layoutNode(neighbor.nodeId);
        if (!node || node.type === 'lift-blackbox') {
          return false;
        }
        if (this.isStorageNode(neighbor.nodeId)) {
          if (this.storedLoadIdAtNode(neighbor.nodeId)) {
            return false;
          }
          if (blocker.waitReason === 'route-unavailable') {
            const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
            return (!occupantId || occupantId === blocker.id) &&
              !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id);
          }
          return this.agentRefreshTemporaryStorageNodeAllowed(blocker, neighbor.nodeId);
        }
        return this.topLiftColumnSpineOrAccessNode(neighbor.nodeId) &&
          this.agentRefreshYieldPocketAllowed(blocker, neighbor.nodeId);
      })
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(blocker, neighbor.nodeId, requester))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id))
      .map((neighbor) => [blocker.currentNodeId, neighbor.nodeId])
      .filter((route) =>
        this.agentRefreshLocalRouteNodesClear(blocker, route) &&
        !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, route)
      )
      .sort((left, right) =>
        Number(this.isStorageNode(left.at(-1)!)) - Number(this.isStorageNode(right.at(-1)!)) ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;

    if (!selectedRoute) {
      return false;
    }

    return this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, selectedRoute, null) &&
      blocker.waitReason === null &&
      blocker.targetNodeId !== blockedTargetNodeId;
  }

  private tryMoveEmptyStorageExitToAdjacentPocketAwayFromLoadedMiddleClaim(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const blockerTask = this.taskForVehicle(blocker);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !blocker.loaded ||
      blockerTask?.kind !== 'inbound' ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle') ||
      vehicle.currentEdgeId !== null ||
      blocker.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      blocker.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      blocker.phaseRemainingSec > 0 ||
      vehicle.state === 'lifting' ||
      vehicle.state === 'lowering'
    ) {
      return false;
    }

    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!currentPosition || blockedColumn !== currentPosition.column) {
      return false;
    }

    const blockedTargetPosition = nodePosition(this.scenario, blockedTargetNodeId);
    const blockerPosition = nodePosition(this.scenario, blocker.currentNodeId);
    const awayDirection = Math.sign(blockedTargetPosition.x - blockerPosition.x);
    if (awayDirection !== -1 && awayDirection !== 1) {
      return false;
    }

    const selectedRoute = this.emptyStorageExitAdjacentPocketRoutes(
      vehicle,
      blockedTargetNodeId,
      currentPosition.row,
      currentPosition.column,
      awayDirection
    )[0] ?? null;
    if (!selectedRoute) {
      return false;
    }

    return this.installAgentRefreshSideYieldRoute(vehicle, blocker, blockedTargetNodeId, selectedRoute, null);
  }

  private tryYieldEmptyStorageEntryAwayFromLoadedInbound(
    yielder: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      yielder.loaded ||
      !requester.loaded ||
      requesterTask?.kind !== 'inbound' ||
      !this.isStorageNode(yielder.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(requester.currentNodeId, 'middle') ||
      yielder.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      yielder.legRemainingM > 0 ||
      requester.legRemainingM > 0 ||
      yielder.phaseRemainingSec > 0 ||
      requester.phaseRemainingSec > 0 ||
      yielder.state === 'lifting' ||
      yielder.state === 'lowering' ||
      requester.state === 'lifting' ||
      requester.state === 'lowering' ||
      yielder.waitReason !== 'middle-aisle-opposing-claim'
    ) {
      return false;
    }
    const currentPosition = this.storageGridPosition(yielder.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!currentPosition || blockedColumn !== currentPosition.column) {
      return false;
    }

    const requesterProtectedNodeIds = new Set(
      [
        requester.currentNodeId,
        requester.targetNodeId,
        requester.plannedGoalNodeId,
        ...this.vehicleRouteTail(requester, requester.routeNodeIds).slice(0, 6)
      ].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    const candidateRoutes: string[][] = [];
    const queue: string[][] = [[yielder.currentNodeId]];
    const visited = new Set<string>([yielder.currentNodeId]);
    const maxRouteNodes = 6;
    while (queue.length > 0) {
      const routePrefix = queue.shift()!;
      const tailNodeId = routePrefix[routePrefix.length - 1]!;
      if (routePrefix.length >= maxRouteNodes) {
        continue;
      }
      for (const neighbor of this.neighbors(tailNodeId)) {
        if (routePrefix.includes(neighbor.nodeId) || visited.has(neighbor.nodeId)) {
          continue;
        }
        const position = this.storageGridPosition(neighbor.nodeId);
        if (!position || position.column !== currentPosition.column) {
          continue;
        }
        if (this.storedLoadIdAtNode(neighbor.nodeId)) {
          continue;
        }
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        if ((occupantId && occupantId !== yielder.id) || this.nodeClaimedByOtherVehicle(neighbor.nodeId, yielder.id)) {
          continue;
        }
        const routeNodeIds = [...routePrefix, neighbor.nodeId];
        if (
          !this.routeHasOnlyAdjacentEdges(routeNodeIds) ||
          !this.agentMinimalYieldFirstLegSafe(yielder, yielder.currentNodeId, routeNodeIds[1]!) ||
          !this.agentRefreshLocalRouteNodesClear(yielder, routeNodeIds) ||
          this.agentRefreshMoveBlocker(yielder, routeNodeIds[1]!, routeNodeIds) ||
          this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(yielder, routeNodeIds)
        ) {
          continue;
        }
        const terminalClearsRequester = !requesterProtectedNodeIds.has(neighbor.nodeId);
        if (terminalClearsRequester) {
          candidateRoutes.push(routeNodeIds);
        }
        visited.add(neighbor.nodeId);
        queue.push(routeNodeIds);
      }
    }
    const route = candidateRoutes
      .sort((left, right) =>
        left.length - right.length ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;
    if (!route) {
      return false;
    }

    this.installEmptyStorageEntryRetreatRoute(yielder, requester, blockedTargetNodeId, route);
    return true;
  }

  private tryYieldLoadedInboundMiddleSpineAwayFromStorageExitCycle(
    loadedVehicle: MutableVehicle,
    storageExitVehicle: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const task = this.taskForVehicle(loadedVehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      task?.kind !== 'inbound' ||
      storageExitVehicle.loaded ||
      !this.isStorageNode(storageExitVehicle.currentNodeId) ||
      loadedVehicle.currentEdgeId !== null ||
      storageExitVehicle.currentEdgeId !== null ||
      loadedVehicle.legRemainingM > 0 ||
      storageExitVehicle.legRemainingM > 0 ||
      loadedVehicle.phaseRemainingSec > 0 ||
      storageExitVehicle.phaseRemainingSec > 0 ||
      loadedVehicle.state === 'lifting' ||
      loadedVehicle.state === 'lowering' ||
      storageExitVehicle.state === 'lifting' ||
      storageExitVehicle.state === 'lowering' ||
      loadedVehicle.waitReason !== 'inbound-column-entry-occupied' ||
      loadedVehicle.blockingVehicleId !== storageExitVehicle.id ||
      storageExitVehicle.waitReason !== 'middle-aisle-opposing-claim' ||
      storageExitVehicle.blockingVehicleId !== loadedVehicle.id ||
      loadedVehicle.targetNodeId !== blockedTargetNodeId ||
      storageExitVehicle.targetNodeId !== blockedTargetNodeId ||
      !isTopLiftSpineLevelNodeId(loadedVehicle.currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle')
    ) {
      return false;
    }

    const storagePosition = this.storageGridPosition(storageExitVehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!storagePosition || blockedColumn !== storagePosition.column) {
      return false;
    }

    const storageExitRoute = new Set(this.vehicleRouteTail(storageExitVehicle, storageExitVehicle.routeNodeIds).slice(0, 8));
    const candidateRoute = this.neighbors(loadedVehicle.currentNodeId)
      .map((neighbor) => neighbor.nodeId)
      .filter((nodeId) =>
        nodeId !== blockedTargetNodeId &&
        nodeId !== storageExitVehicle.currentNodeId &&
        nodeId !== storageExitVehicle.targetNodeId &&
        isTopLiftAisleLevelNodeId(nodeId, 'middle') &&
        !isTopLiftSpineLevelNodeId(nodeId, 'middle') &&
        !this.isStorageNode(nodeId) &&
        !storageExitRoute.has(nodeId) &&
        this.agentRefreshYieldPocketAllowed(loadedVehicle, nodeId) &&
        this.agentRefreshYieldPocketCanReturn(loadedVehicle, nodeId, loadedVehicle.currentNodeId) &&
        this.agentMinimalYieldFirstLegSafe(loadedVehicle, loadedVehicle.currentNodeId, nodeId)
      )
      .map((nodeId) => [loadedVehicle.currentNodeId, nodeId])
      .filter((routeNodeIds) =>
        this.routeHasOnlyAdjacentEdges(routeNodeIds) &&
        this.agentRefreshLocalRouteNodesClear(loadedVehicle, routeNodeIds) &&
        !this.agentRefreshMoveBlocker(loadedVehicle, routeNodeIds[1]!, routeNodeIds)
      )
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;

    if (!candidateRoute) {
      return false;
    }

    this.installLoadedInboundSpineRetreatRoute(
      loadedVehicle,
      storageExitVehicle,
      blockedTargetNodeId,
      candidateRoute
    );
    return true;
  }

  private installLoadedInboundSpineRetreatRoute(
    vehicle: MutableVehicle,
    storageExitVehicle: MutableVehicle,
    blockedTargetNodeId: string,
    route: string[]
  ): void {
    const task = this.taskForVehicle(vehicle);
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 2);
    vehicle.yieldHoldNodeId = route.at(-1) ?? null;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'loaded-inbound-spine-retreat';
    const session = this.activeConflictSessionForPair(vehicle.id, storageExitVehicle.id);
    if (session) {
      this.closeConflictSession(session, 'loaded-inbound-spine-retreat');
    }
    this.logAgentReroute(
      vehicle,
      task,
      blockedTargetNodeId,
      route,
      'loaded-inbound-spine-retreat',
      { countTaskReplan: false }
    );
  }

  private installEmptyStorageEntryRetreatRoute(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    route: string[]
  ): void {
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 2);
    vehicle.yieldHoldNodeId = route[route.length - 1] ?? null;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'empty-storage-entry-retreat';
    const session = this.activeConflictSessionForPair(vehicle.id, requester.id);
    if (session) {
      this.closeConflictSession(session, 'empty-storage-entry-retreat');
    }
    this.logAgentReroute(
      vehicle,
      this.taskForVehicle(vehicle),
      blockedTargetNodeId,
      route,
      'empty-storage-entry-retreat',
      { countTaskReplan: false }
    );
  }

  private emptyStorageExitAdjacentPocketRoutes(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    storageRow: number,
    storageColumn: number,
    awayDirection: -1 | 1
  ): string[][] {
    const routes: string[][] = [];
    for (let offset = 1; offset <= 4; offset += 1) {
      const candidateColumn = storageColumn + awayDirection * offset;
      if (candidateColumn < 1) {
        continue;
      }
      const middleNodeId = columnAccessNodeId('middle', candidateColumn - 1);
      if (!this.layoutNode(middleNodeId)) {
        continue;
      }
      const middleRoute = [vehicle.currentNodeId, blockedTargetNodeId];
      for (let column = storageColumn + awayDirection; column !== candidateColumn + awayDirection; column += awayDirection) {
        middleRoute.push(columnAccessNodeId('middle', column - 1));
      }
      if (!this.routeHasOnlyAdjacentEdges(middleRoute)) {
        continue;
      }

      const terminalCandidates = [
        storageNodeId(storageRow - 1, candidateColumn - 1),
        storageNodeId(storageRow - 2, candidateColumn - 1),
        storageNodeId(storageRow, candidateColumn - 1)
      ];
      for (const terminalNodeId of terminalCandidates) {
        const route = [...middleRoute, terminalNodeId];
        if (
          !this.isStorageNode(terminalNodeId) ||
          !this.routeHasOnlyAdjacentEdges(route) ||
          !this.agentRefreshTemporaryStorageNodeAllowed(vehicle, terminalNodeId) ||
          !this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, blockedTargetNodeId) ||
          !this.agentRefreshLocalRouteNodesClear(vehicle, route) ||
          this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, route)
        ) {
          continue;
        }
        routes.push(route);
      }
    }
    return routes.sort((left, right) =>
      this.routeDistanceM(left) - this.routeDistanceM(right) ||
      left.join('>').localeCompare(right.join('>'))
    );
  }

  private emptyTopBSpineBlockerAlreadyClearsLoadedInbound(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      blocker.loaded ||
      !requester.loaded ||
      blocker.currentEdgeId !== null ||
      requester.currentEdgeId !== null ||
      !isTopLiftSpineLevelNodeId(blocker.currentNodeId, 'top-b') ||
      !isTopLiftAisleLevelNodeId(requester.currentNodeId, 'top-b') ||
      blockedTargetNodeId !== blocker.currentNodeId ||
      this.taskForVehicle(requester)?.kind !== 'inbound'
    ) {
      return false;
    }
    const topANodeId = this.topLiftSpineSiblingNodeId(blocker.currentNodeId, 'top-a');
    const routeTail = this.vehicleRouteTail(blocker, blocker.routeNodeIds);
    if (
      !topANodeId ||
      routeTail.length < 2 ||
      routeTail[0] !== blocker.currentNodeId ||
      routeTail[1] !== topANodeId ||
      routeTail.includes(this.topLiftSpineSiblingNodeId(blocker.currentNodeId, 'middle') ?? '')
    ) {
      return false;
    }
    const nextNodeId = routeTail[1]!;
    return this.routeEdgesExist(routeTail.slice(0, Math.min(routeTail.length, 3))) &&
      this.agentRefreshYieldPocketAllowed(blocker, nextNodeId) &&
      this.agentRefreshYieldPocketKeepsGoalReachable(blocker, nextNodeId) &&
      this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, nextNodeId) &&
      this.agentRefreshLocalRouteNodesClear(blocker, routeTail.slice(0, Math.min(routeTail.length, 4))) &&
      !this.currentNodeOccupancy.has(nextNodeId) &&
      !this.nodeClaimedByOtherVehicle(nextNodeId, blocker.id);
  }

  private tryRerouteEmptyStorageExitAroundLoadedMiddleClaim(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    const blockerTask = this.taskForVehicle(blocker);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !blocker.loaded ||
      blockerTask?.kind !== 'inbound' ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle') ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.targetNodeId !== blockedTargetNodeId ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'middle') ||
      !this.traffic.findEdge(vehicle.currentNodeId, blockedTargetNodeId)
    ) {
      return false;
    }

    const currentGoalNodeId = this.agentGoalNodeId(vehicle, task);
    const candidateGoalNodeIds = task
      ? [currentGoalNodeId].filter((nodeId): nodeId is string => Boolean(nodeId))
      : [
        currentGoalNodeId,
        ...this.inboundStandbyNodeCandidates(vehicle.id).map((node) => node.id)
      ].filter((nodeId, index, nodeIds): nodeId is string =>
        Boolean(nodeId) &&
        nodeId !== vehicle.currentNodeId &&
        nodeIds.indexOf(nodeId) === index
      );
    if (candidateGoalNodeIds.length === 0) {
      return false;
    }

    let selectedGoalNodeId: string | null = null;
    let expandedRoute: string[] | null = null;
    for (const goalNodeId of candidateGoalNodeIds) {
      const blockedNodeIds = this.agentRefreshBlockedNodeIds(vehicle, task, goalNodeId);
      blockedNodeIds.add(blocker.currentNodeId);
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(blockedTargetNodeId);
      blockedNodeIds.delete(goalNodeId);
      if (task) {
        blockedNodeIds.delete(task.pickupNodeId);
        blockedNodeIds.delete(task.dropoffNodeId);
      }

      const route = this.tryAgentRefreshShortestPath(
        vehicle.currentNodeId,
        goalNodeId,
        blockedNodeIds,
        vehicle.lastMovementAxis
      );
      if (
        !route ||
        route.length < 3 ||
        route[1] !== blockedTargetNodeId ||
        route.includes(blocker.currentNodeId) ||
        !this.routeHasOnlyAdjacentEdges(route)
      ) {
        continue;
      }
      const candidateExpandedRoute = this.agentRefreshExpandLiftColumnSegments(route);
      if (
        candidateExpandedRoute.includes(blocker.currentNodeId) ||
        !this.agentRefreshLocalRouteNodesClear(vehicle, candidateExpandedRoute)
      ) {
        continue;
      }
      const moveBlock = this.agentRefreshMoveBlocker(vehicle, candidateExpandedRoute[1]!, candidateExpandedRoute);
      if (moveBlock && moveBlock.blockingVehicleId !== blocker.id) {
        continue;
      }
      selectedGoalNodeId = goalNodeId;
      expandedRoute = candidateExpandedRoute;
      break;
    }
    if (
      !selectedGoalNodeId ||
      !expandedRoute ||
      expandedRoute.includes(blocker.currentNodeId)
    ) {
      return false;
    }

    vehicle.routeNodeIds = expandedRoute;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = expandedRoute[1] ?? null;
    vehicle.state = task ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = selectedGoalNodeId;
    vehicle.plannedRouteNodeIds = expandedRoute;
    vehicle.localRouteNodeIds = expandedRoute;
    vehicle.localRouteReason = 'middle-aisle-empty-storage-reroute';
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    const session = this.activeConflictSessionForPair(vehicle.id, blocker.id);
    if (session) {
      this.closeConflictSession(session, 'middle-aisle-empty-storage-reroute');
    }
    this.logAgentReroute(vehicle, task, blockedTargetNodeId, expandedRoute, 'middle-aisle-empty-storage-reroute', { countTaskReplan: false });
    return true;
  }

  private topLiftBlockerHasCommittedContinuationAway(
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || blocker.currentNodeId !== blockedTargetNodeId) {
      return false;
    }
    const movingAway = blocker.currentEdgeId !== null && blocker.legRemainingM > 0;
    const readyToMoveAway = blocker.currentEdgeId === null && blocker.legRemainingM <= 0;
    if (!movingAway && !readyToMoveAway) {
      return false;
    }
    const nextNodeId = blocker.targetNodeId ?? blocker.routeNodeIds[blocker.routeIndex + 1] ?? null;
    if (!nextNodeId || nextNodeId === blocker.currentNodeId || nextNodeId === requester.currentNodeId) {
      return false;
    }
    if (!this.traffic.findEdge(blocker.currentNodeId, nextNodeId)) {
      return false;
    }
    if (blocker.waitReason === 'local-yield-hold' || blocker.waitReason === 'middle-aisle-opposing-claim') {
      return false;
    }
    if (readyToMoveAway) {
      if (
        blocker.state === 'waiting-blocked' ||
        blocker.phaseRemainingSec > 0 ||
        blocker.state === 'lifting' ||
        blocker.state === 'lowering'
      ) {
        return false;
      }
      const occupantId = this.currentNodeOccupancy.get(nextNodeId);
      if (occupantId && occupantId !== blocker.id) {
        return false;
      }
      if (this.nodeClaimedByOtherVehicle(nextNodeId, blocker.id)) {
        return false;
      }
      if (!this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, nextNodeId)) {
        return false;
      }
    }
    const blockedNode = this.layoutNode(blockedTargetNodeId);
    const nextNode = this.layoutNode(nextNodeId);
    if (!blockedNode || !nextNode) {
      return false;
    }
    const leavingAlongAxis =
      Math.abs(blockedNode.x - nextNode.x) <= 1e-6 ||
      Math.abs(blockedNode.z - nextNode.z) <= 1e-6;
    return leavingAlongAxis && (blocker.taskId !== null || blocker.localRouteReason !== null || blocker.plannedGoalNodeId !== null);
  }

  private agentRefreshTemporaryYieldInProgress(vehicle: MutableVehicle): boolean {
    if (
      vehicle.localRouteReason !== 'temporary-yield' ||
      vehicle.localRouteNodeIds.length <= 1 ||
      vehicle.routeNodeIds.length <= 1 ||
      vehicle.waitReason !== null ||
      vehicle.targetNodeId === null ||
      vehicle.targetNodeId === vehicle.currentNodeId ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.state === 'lifting' ||
      vehicle.state === 'lowering'
    ) {
      return false;
    }
    return vehicle.localRouteNodeIds.join('>') === vehicle.routeNodeIds.join('>');
  }

  private tryRetreatOutboundLoadedApproachForQueueExit(
    loadedVehicle: MutableVehicle,
    queueExitVehicle: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      queueExitVehicle.loaded ||
      loadedVehicle.currentEdgeId !== null ||
      queueExitVehicle.currentEdgeId !== null ||
      loadedVehicle.legRemainingM > 0 ||
      queueExitVehicle.legRemainingM > 0 ||
      loadedVehicle.phaseRemainingSec > 0 ||
      queueExitVehicle.phaseRemainingSec > 0
    ) {
      return false;
    }
    const task = this.taskForVehicle(loadedVehicle);
    if (task?.kind !== 'outbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const targetEntrySlot = topLiftQueueEntrySlot(loadedVehicle.targetNodeId ?? '');
    const blockerEntrySlot = topLiftQueueEntrySlot(queueExitVehicle.currentNodeId);
    if (
      !liftNodeId ||
      !targetEntrySlot ||
      !blockerEntrySlot ||
      targetEntrySlot.liftNodeId !== liftNodeId ||
      blockerEntrySlot.liftNodeId !== liftNodeId ||
      targetEntrySlot.slotIndex !== blockerEntrySlot.slotIndex ||
      this.liftPortKindForNodeId(liftNodeId) !== 'outbound'
    ) {
      return false;
    }
    const bottomAccessNodeId = this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId);
    if (
      !bottomAccessNodeId ||
      loadedVehicle.currentNodeId !== bottomAccessNodeId ||
      queueExitVehicle.targetNodeId !== bottomAccessNodeId
    ) {
      return false;
    }

    const sameLaneRetreatCandidate = (nodeId: string) =>
      isTopLiftAisleLevelNodeId(nodeId, 'bottom-b') &&
      this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(nodeId) === liftNodeId &&
      this.topLiftOutboundClearanceDirections(liftNodeId, loadedVehicle.currentNodeId).some((direction) =>
        this.nextTopLiftRailNodeAlongDirection(loadedVehicle.currentNodeId, 'bottom-b', direction, loadedVehicle.id) === nodeId
      );
    const candidate = this.neighbors(loadedVehicle.currentNodeId)
      .filter((neighbor) =>
        neighbor.nodeId !== loadedVehicle.currentNodeId &&
        neighbor.nodeId !== queueExitVehicle.currentNodeId &&
        isTopLiftAisleLevelNodeId(neighbor.nodeId, 'bottom-b')
      )
      .filter((neighbor) =>
        sameLaneRetreatCandidate(neighbor.nodeId) ||
        this.agentRefreshYieldPocketAllowed(loadedVehicle, neighbor.nodeId)
      )
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, loadedVehicle.id))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(loadedVehicle, loadedVehicle.currentNodeId, neighbor.nodeId))
      .sort((left, right) => left.lengthM - right.lengthM || left.nodeId.localeCompare(right.nodeId))[0];
    if (!candidate) {
      return false;
    }

    const route = [loadedVehicle.currentNodeId, candidate.nodeId];
    if (this.agentRefreshTemporaryRouteAlreadyActive(loadedVehicle, route)) {
      return true;
    }
    loadedVehicle.routeNodeIds = route;
    loadedVehicle.routeIndex = 0;
    loadedVehicle.targetNodeId = candidate.nodeId;
    loadedVehicle.state = 'loaded-moving';
    loadedVehicle.waitReason = null;
    loadedVehicle.blockingReservationId = null;
    loadedVehicle.blockingVehicleId = null;
    loadedVehicle.waitingSinceSec = null;
    loadedVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(loadedVehicle, route) + 2);
    loadedVehicle.yieldHoldNodeId = candidate.nodeId;
    loadedVehicle.localRouteNodeIds = route;
    loadedVehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(loadedVehicle, task, queueExitVehicle.currentNodeId, route, 'outbound-loaded-approach-yield-for-queue-exit', { countTaskReplan: false });
    return true;
  }

  private tryFlushTasklessStorageBlockerAhead(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      !this.isStorageNode(blocker.currentNodeId) ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering'
    ) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }

    const requesterRoute = this.vehicleRouteTailForMove(requester, blockedTargetNodeId);
    const blockedIndex = requesterRoute.indexOf(blockedTargetNodeId);
    if (blockedIndex < 0) {
      return false;
    }

    const route = [blocker.currentNodeId];
    for (let index = blockedIndex + 1; index < requesterRoute.length && route.length < 5; index += 1) {
      const nodeId = requesterRoute[index]!;
      const previousNodeId = route[route.length - 1]!;
      if (nodeId === requester.currentNodeId || !this.traffic.findEdge(previousNodeId, nodeId)) {
        break;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== blocker.id) {
        break;
      }
      if (this.nodeClaimedByOtherVehicle(nodeId, blocker.id)) {
        break;
      }
      if (this.isStorageNode(nodeId) && !this.agentRefreshTemporaryStorageNodeAllowed(blocker, nodeId)) {
        break;
      }
      route.push(nodeId);
      if (!this.isStorageNode(nodeId)) {
        break;
      }
    }

    if (route.length < 2) {
      return false;
    }
    const firstTargetNodeId = route[1]!;
    if (!this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, firstTargetNodeId)) {
      return false;
    }
    const firstLegBlock = this.collisionAvoidanceEnabled()
      ? this.agentRefreshEnabled()
        ? this.agentRefreshMoveBlocker(blocker, firstTargetNodeId, route)
        : this.agentMinimalEnabled()
          ? this.agentMinimalMoveBlocker(blocker, firstTargetNodeId)
          : this.agentMoveBlocker(blocker, firstTargetNodeId)
      : null;
    if (firstLegBlock) {
      return false;
    }
    if (this.agentRefreshTemporaryRouteAlreadyActive(blocker, route)) {
      return true;
    }

    blocker.routeNodeIds = route;
    blocker.routeIndex = 0;
    blocker.targetNodeId = firstTargetNodeId;
    blocker.state = blocker.taskId ? 'moving-to-pickup' : 'returning';
    blocker.waitReason = null;
    blocker.blockingReservationId = null;
    blocker.blockingVehicleId = null;
    blocker.waitingSinceSec = null;
    blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, route) + 2);
    blocker.yieldHoldNodeId = route[route.length - 1]!;
    blocker.localRouteNodeIds = route;
    blocker.localRouteReason = 'temporary-yield';
    this.logAgentReroute(blocker, null, blockedTargetNodeId, route, 'taskless-storage-blocker-flush', { countTaskReplan: false });
    return true;
  }

  private tryYieldTopLiftAccessBlockerAhead(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      !isTopLiftColumnAccessNodeId(blocker.currentNodeId) ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      blocker.state === 'lifting' ||
      blocker.state === 'lowering'
    ) {
      return false;
    }

    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }

    const route = this.topLiftAccessClearanceRouteForBlocker(blocker, requester, blockedTargetNodeId);
    if (!route) {
      return false;
    }
    const targetNodeId = route[1]!;
    if (this.agentRefreshTemporaryRouteAlreadyActive(blocker, route)) {
      return true;
    }
    blocker.routeNodeIds = route;
    blocker.routeIndex = 0;
    blocker.targetNodeId = targetNodeId;
    blocker.state = blocker.taskId ? 'moving-to-pickup' : 'returning';
    blocker.waitReason = null;
    blocker.blockingReservationId = null;
    blocker.blockingVehicleId = null;
    blocker.waitingSinceSec = null;
    blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, route) + 2);
    blocker.yieldHoldNodeId = route[route.length - 1]!;
    blocker.localRouteNodeIds = route;
    blocker.localRouteReason = 'access-blocker-clearance';
    this.logAgentReroute(blocker, blockerTask, blockedTargetNodeId, route, 'agent-refresh-access-blocker-clearance', { countTaskReplan: false });
    return true;
  }

  private topLiftAccessClearanceRouteForBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }

    const requesterProtectedNodeIds = new Set<string>([
      requester.currentNodeId,
      requester.targetNodeId ?? '',
      blockedTargetNodeId,
      ...this.agentRefreshRequesterProtectedRouteNodeIds(requester),
      ...this.agentRefreshLoadedRequesterProtectedRouteNodeIds(requester)
    ].filter(Boolean));
    const allowedStorageNodeIds = this.topLiftTaskAllowedTemporaryStorageNodeIds(blocker);
    const candidate = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => !requesterProtectedNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => {
        const node = this.layoutNode(neighbor.nodeId);
        if (!node) {
          return false;
        }
        if (this.isStorageNode(neighbor.nodeId)) {
          return allowedStorageNodeIds.has(neighbor.nodeId) &&
            this.agentRefreshTemporaryStorageNodeAllowed(blocker, neighbor.nodeId);
        }
        return this.topLiftColumnSpineOrAccessNode(neighbor.nodeId) &&
          this.agentRefreshYieldPocketAllowed(blocker, neighbor.nodeId);
      })
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(blocker, neighbor.nodeId, requester))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.topLiftAccessClearanceNodeClaimedByOtherVehicle(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId))
      .map((neighbor) => {
        const route = this.topLiftAccessClearanceExtendedTaskRoute(
          blocker,
          requester,
          blockedTargetNodeId,
          neighbor.nodeId,
          requesterProtectedNodeIds
        ) ?? [blocker.currentNodeId, neighbor.nodeId];
        return {
          ...neighbor,
          route
        };
      })
      .filter((candidateRoute) =>
        candidateRoute.route[1] === candidateRoute.nodeId &&
        candidateRoute.route.slice(1).every((nodeId) =>
          !this.currentNodeOccupancy.has(nodeId) &&
          !this.topLiftAccessClearanceNodeClaimedByOtherVehicle(blocker, nodeId)
        ) &&
        this.agentRefreshLocalRouteNodesClear(blocker, candidateRoute.route) &&
        !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(blocker, candidateRoute.route) &&
        !this.agentRefreshMoveBlocker(blocker, candidateRoute.nodeId, candidateRoute.route)
      )
      .sort((left, right) =>
        Number(this.isStorageNode(left.nodeId)) - Number(this.isStorageNode(right.nodeId)) ||
        Number(right.route.length > 2) - Number(left.route.length > 2) ||
        this.agentRefreshYieldPocketTieBreak(blocker, left.nodeId) - this.agentRefreshYieldPocketTieBreak(blocker, right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0] ?? null;
    return candidate?.route ?? null;
  }

  private topLiftAccessClearanceExtendedTaskRoute(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    firstClearNodeId: string,
    requesterProtectedNodeIds: Set<string>
  ): string[] | null {
    const task = this.taskForVehicle(blocker);
    const goalNodeId = this.agentGoalNodeId(blocker, task);
    if (
      !task ||
      !goalNodeId ||
      goalNodeId === blocker.currentNodeId ||
      goalNodeId === firstClearNodeId ||
      !this.topLiftAccessClearanceSidePocketMove(blocker.currentNodeId, firstClearNodeId)
    ) {
      return null;
    }

    const blockedNodeIds = this.agentRefreshBlockedNodeIds(blocker, task, goalNodeId);
    blockedNodeIds.add(blocker.currentNodeId);
    blockedNodeIds.add(blockedTargetNodeId);
    blockedNodeIds.add(requester.currentNodeId);
    if (requester.targetNodeId) {
      blockedNodeIds.add(requester.targetNodeId);
    }
    for (const nodeId of requesterProtectedNodeIds) {
      blockedNodeIds.add(nodeId);
    }
    blockedNodeIds.delete(firstClearNodeId);
    blockedNodeIds.delete(goalNodeId);
    blockedNodeIds.delete(task.pickupNodeId);
    blockedNodeIds.delete(task.dropoffNodeId);

    const continuation = this.tryAgentRefreshShortestPath(
      firstClearNodeId,
      goalNodeId,
      blockedNodeIds,
      this.routeTerminalAxis([blocker.currentNodeId, firstClearNodeId])
    );
    if (!continuation || continuation.length < 2) {
      return null;
    }

    const route = this.simplifyImmediateTurnbackLoops([blocker.currentNodeId, ...continuation]);
    if (
      route[1] !== firstClearNodeId ||
      route.slice(2).includes(blocker.currentNodeId) ||
      route.slice(1).includes(blockedTargetNodeId) ||
      this.routeHasRepeatedNode(route) ||
      !this.routeHasOnlyAdjacentEdges(route)
    ) {
      return null;
    }
    return route;
  }

  private topLiftAccessClearanceSidePocketMove(fromNodeId: string, toNodeId: string): boolean {
    const fromLevel = topLiftAisleLevel(fromNodeId);
    const toLevel = topLiftAisleLevel(toNodeId);
    const fromColumn = this.topLiftColumnAccessColumn(fromNodeId);
    const toColumn = this.topLiftColumnAccessColumn(toNodeId);
    if (!fromLevel || !toLevel || fromColumn === null || fromColumn !== toColumn) {
      return false;
    }
    return (fromLevel === 'top-b' && toLevel === 'top-a') ||
      (fromLevel === 'bottom-b' && toLevel === 'bottom-a');
  }

  private topLiftTaskAllowedTemporaryStorageNodeIds(vehicle: MutableVehicle): Set<string> {
    const allowedNodeIds = new Set<string>();
    const task = this.taskForVehicle(vehicle);
    if (!task) {
      for (const node of this.scenario.layout.nodes) {
        if (node.type === 'storage') {
          allowedNodeIds.add(node.id);
        }
      }
      return allowedNodeIds;
    }

    for (const route of [
      this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
      [vehicle.currentNodeId, vehicle.targetNodeId].filter((nodeId): nodeId is string => nodeId !== null)
    ]) {
      for (const nodeId of route) {
        if (this.isStorageNode(nodeId)) {
          allowedNodeIds.add(nodeId);
        }
      }
    }
    if (task.kind === 'inbound' && vehicle.loaded) {
      allowedNodeIds.add(task.dropoffNodeId);
    }
    if (task.kind === 'outbound') {
      allowedNodeIds.add(task.pickupNodeId);
    }
    return allowedNodeIds;
  }

  private topLiftAccessClearanceNodeClaimedByOtherVehicle(blocker: MutableVehicle, nodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    return this.vehicles.some((vehicle) => {
      if (
        vehicle.id === blocker.id ||
        vehicle.state === 'idle' ||
        vehicle.state === 'parking'
      ) {
        return false;
      }
      if (
        vehicle.currentNodeId === nodeId ||
        (
          vehicle.state !== 'waiting-blocked' &&
          (
            vehicle.targetNodeId === nodeId ||
            vehicle.plannedGoalNodeId === nodeId
          )
        )
      ) {
        return true;
      }
      if (vehicle.state === 'waiting-blocked') {
        return false;
      }
      const routeTails = [
        this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
        this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
        this.activeLocalRouteClaimTail(vehicle)
      ];
      return routeTails.some((route) => route.slice(0, 8).includes(nodeId));
    });
  }

  private tryRetreatLoadedInboundColumnFaceoff(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      blocker.loaded ||
      loadedVehicle.currentEdgeId !== null ||
      loadedVehicle.legRemainingM > 0 ||
      loadedVehicle.phaseRemainingSec > 0 ||
      loadedVehicle.state === 'lifting' ||
      loadedVehicle.state === 'lowering' ||
      !this.isStorageNode(loadedVehicle.currentNodeId) ||
      !this.isStorageNode(blocker.currentNodeId) ||
      loadedVehicle.targetNodeId !== blocker.currentNodeId ||
      blocker.targetNodeId !== loadedVehicle.currentNodeId
    ) {
      return false;
    }

    const task = this.taskForVehicle(loadedVehicle);
    const loadedPosition = this.storageGridPosition(loadedVehicle.currentNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    const dropoffPosition = task?.kind === 'inbound' ? this.storageGridPosition(task.dropoffNodeId) : null;
    if (
      task?.kind !== 'inbound' ||
      !loadedPosition ||
      !blockerPosition ||
      !dropoffPosition ||
      loadedPosition.column !== blockerPosition.column ||
      loadedPosition.column !== dropoffPosition.column
    ) {
      return false;
    }

    const retreatRoute = this.loadedInboundColumnFaceoffRetreatRoute(loadedVehicle, blocker, dropoffPosition.column);
    if (!retreatRoute) {
      return false;
    }

    loadedVehicle.routeNodeIds = retreatRoute;
    loadedVehicle.routeIndex = 0;
    loadedVehicle.targetNodeId = retreatRoute[1] ?? null;
    loadedVehicle.state = 'loaded-moving';
    loadedVehicle.waitReason = null;
    loadedVehicle.blockingReservationId = null;
    loadedVehicle.blockingVehicleId = null;
    loadedVehicle.waitingSinceSec = null;
    loadedVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(loadedVehicle, retreatRoute) + 1);
    loadedVehicle.yieldHoldNodeId = retreatRoute[retreatRoute.length - 1]!;
    loadedVehicle.localRouteNodeIds = retreatRoute;
    loadedVehicle.localRouteReason = 'inbound-column-faceoff-retreat';
    this.logAgentReroute(loadedVehicle, task, blocker.currentNodeId, retreatRoute, 'agent-refresh-inbound-column-faceoff-retreat', { countTaskReplan: false });
    return true;
  }

  private loadedInboundColumnFaceoffRetreatRoute(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle,
    column: number
  ): string[] | null {
    const position = this.storageGridPosition(loadedVehicle.currentNodeId);
    if (!position) {
      return null;
    }

    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const upperBank = position.row <= rowsPerZone;
    const exitRow = upperBank ? 1 : rowsPerZone * 2;
    const exitAccessNodeId = upperBank
      ? columnAccessNodeId('top-b', column - 1)
      : columnAccessNodeId('bottom-a', column - 1);
    const rowDirection = Math.sign(exitRow - position.row);
    const route = [loadedVehicle.currentNodeId];
    for (let row = position.row + rowDirection; rowDirection === 0 ? false : rowDirection > 0 ? row <= exitRow : row >= exitRow; row += rowDirection) {
      route.push(storageNodeId(row - 1, column - 1));
    }
    if (route[route.length - 1] !== exitAccessNodeId) {
      route.push(exitAccessNodeId);
    }

    const sideCandidates = this.loadedInboundColumnFaceoffSideCandidateNodeIds(exitAccessNodeId, blocker);
    for (const sideNodeId of sideCandidates) {
      const candidateRoute = sideNodeId === exitAccessNodeId ? route : [...route, sideNodeId];
      if (this.loadedInboundColumnFaceoffRetreatRouteClear(candidateRoute, loadedVehicle)) {
        return candidateRoute;
      }
    }
    return this.loadedInboundColumnFaceoffRetreatRouteClear(route, loadedVehicle) ? route : null;
  }

  private loadedInboundColumnFaceoffSideCandidateNodeIds(exitAccessNodeId: string, blocker: MutableVehicle): string[] {
    const column = this.topLiftColumnAccessColumn(exitAccessNodeId);
    const level = topLiftAisleLevel(exitAccessNodeId);
    if (column === null || !level) {
      return [exitAccessNodeId];
    }
    const blockerFutureRoute = new Set([
      ...this.vehicleRouteTail(blocker, blocker.routeNodeIds),
      ...this.vehicleRouteTail(blocker, blocker.plannedRouteNodeIds)
    ]);
    const candidates = [
      column > 1 ? columnAccessNodeId(level, column - 2) : null,
      columnAccessNodeId(level, column)
    ].filter((nodeId): nodeId is string => nodeId !== null && this.layoutNode(nodeId) !== null);
    return [
      ...candidates.filter((nodeId) => !blockerFutureRoute.has(nodeId)),
      ...candidates.filter((nodeId) => blockerFutureRoute.has(nodeId)),
      exitAccessNodeId
    ].filter((nodeId, index, all) => all.indexOf(nodeId) === index);
  }

  private loadedInboundColumnFaceoffRetreatRouteClear(routeNodeIds: string[], loadedVehicle: MutableVehicle): boolean {
    if (routeNodeIds.length < 2 || !this.routeEdgesExist(routeNodeIds)) {
      return false;
    }
    for (const nodeId of routeNodeIds.slice(1)) {
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== loadedVehicle.id) {
        return false;
      }
      if (this.nodeClaimedByOtherVehicle(nodeId, loadedVehicle.id)) {
        return false;
      }
      if (this.isStorageNode(nodeId) && this.storedLoadIdAtNode(nodeId)) {
        return false;
      }
    }
    return this.agentMinimalYieldFirstLegSafe(loadedVehicle, routeNodeIds[0]!, routeNodeIds[1]!);
  }

  private tryYieldStorageAwayFromTopLiftServiceClearance(
    storageVehicle: MutableVehicle,
    serviceVehicle: MutableVehicle
  ): boolean {
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(serviceVehicle);
    if (
      !clearanceSegment ||
      storageVehicle.loaded ||
      !this.isStorageNode(storageVehicle.currentNodeId) ||
      storageVehicle.currentEdgeId !== null ||
      storageVehicle.legRemainingM > 0 ||
      storageVehicle.phaseRemainingSec > 0 ||
      storageVehicle.state === 'lifting' ||
      storageVehicle.state === 'lowering'
    ) {
      return false;
    }

    const fromNode = this.layoutNode(clearanceSegment.fromNodeId);
    const toNode = this.layoutNode(clearanceSegment.toNodeId);
    const storageNode = this.layoutNode(storageVehicle.currentNodeId);
    if (!fromNode || !toNode || !storageNode) {
      return false;
    }

    const targetNode = storageVehicle.targetNodeId ? this.layoutNode(storageVehicle.targetNodeId) : null;
    const clearanceM = this.scenario.vehicles.widthM / 2 + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    const currentDistanceM = this.pointToSegmentDistanceM(
      storageNode.x,
      storageNode.z,
      fromNode.x,
      fromNode.z,
      toNode.x,
      toNode.z
    );
    const targetDistanceM = targetNode
      ? this.pointToSegmentDistanceM(targetNode.x, targetNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z)
      : Number.POSITIVE_INFINITY;
    if (currentDistanceM > clearanceM && targetDistanceM > clearanceM) {
      return false;
    }

    const currentPosition = this.storageGridPosition(storageVehicle.currentNodeId);
    if (!currentPosition) {
      return false;
    }

    const candidate = this.neighbors(storageVehicle.currentNodeId)
      .filter((neighbor) => {
        const position = this.storageGridPosition(neighbor.nodeId);
        return position !== null && position.column === currentPosition.column;
      })
      .filter((neighbor) => this.agentRefreshTemporaryStorageNodeAllowed(storageVehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(storageVehicle, storageVehicle.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.agentRefreshMoveBlocker(storageVehicle, neighbor.nodeId, [
        storageVehicle.currentNodeId,
        neighbor.nodeId
      ]))
      .sort((left, right) => {
        const leftNode = nodePosition(this.scenario, left.nodeId);
        const rightNode = nodePosition(this.scenario, right.nodeId);
        const leftDistanceM = this.pointToSegmentDistanceM(leftNode.x, leftNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z);
        const rightDistanceM = this.pointToSegmentDistanceM(rightNode.x, rightNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z);
        return rightDistanceM - leftDistanceM ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0];
    if (!candidate) {
      return false;
    }

    const route = [storageVehicle.currentNodeId, candidate.nodeId];
    if (this.agentRefreshTemporaryRouteAlreadyActive(storageVehicle, route)) {
      return true;
    }
    storageVehicle.routeNodeIds = route;
    storageVehicle.routeIndex = 0;
    storageVehicle.targetNodeId = candidate.nodeId;
    storageVehicle.state = storageVehicle.taskId ? 'assigned' : 'returning';
    storageVehicle.waitReason = null;
    storageVehicle.blockingReservationId = null;
    storageVehicle.blockingVehicleId = null;
    storageVehicle.waitingSinceSec = null;
    storageVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(storageVehicle, route) + 2);
    storageVehicle.yieldHoldNodeId = candidate.nodeId;
    storageVehicle.localRouteNodeIds = route;
    storageVehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(storageVehicle, this.taskForVehicle(storageVehicle), clearanceSegment.toNodeId, route, 'top-lift-service-clearance-storage-yield', { countTaskReplan: false });
    return true;
  }

  private tryYieldStorageAwayFromLoadedInboundDropoffRoute(
    storageVehicle: MutableVehicle,
    loadedVehicle: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      storageVehicle.loaded ||
      !loadedVehicle.loaded ||
      !this.isStorageNode(storageVehicle.currentNodeId) ||
      storageVehicle.currentEdgeId !== null ||
      storageVehicle.legRemainingM > 0 ||
      storageVehicle.phaseRemainingSec > 0 ||
      storageVehicle.state === 'lifting' ||
      storageVehicle.state === 'lowering'
    ) {
      return false;
    }
    const task = this.taskForVehicle(loadedVehicle);
    if (task?.kind !== 'inbound' || !this.isStorageNode(task.dropoffNodeId)) {
      return false;
    }
    const storagePosition = this.storageGridPosition(storageVehicle.currentNodeId);
    const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!storagePosition || !dropoffPosition || storagePosition.column !== dropoffPosition.column) {
      return false;
    }
    const protectedRouteNodeIds = this.agentRefreshRequesterProtectedRouteNodeIds(loadedVehicle);
    if (!protectedRouteNodeIds.includes(storageVehicle.currentNodeId)) {
      return false;
    }
    const direction = Math.sign(dropoffPosition.row - storagePosition.row);
    if (direction === 0) {
      return false;
    }
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const bankStartRow = storagePosition.row <= rowsPerZone ? 1 : rowsPerZone + 1;
    const bankEndRow = storagePosition.row <= rowsPerZone ? rowsPerZone : rowsPerZone * 2;
    const firstSafeRow = dropoffPosition.row + direction;
    const candidateRows: number[] = [];
    if (direction > 0) {
      for (let row = Math.max(firstSafeRow, storagePosition.row + 1); row <= bankEndRow; row += 1) {
        candidateRows.push(row);
      }
    } else {
      for (let row = Math.min(firstSafeRow, storagePosition.row - 1); row >= bankStartRow; row -= 1) {
        candidateRows.push(row);
      }
    }

    for (const candidateRow of candidateRows) {
      const route = [storageVehicle.currentNodeId];
      for (let row = storagePosition.row + direction; direction > 0 ? row <= candidateRow : row >= candidateRow; row += direction) {
        route.push(storageNodeId(row - 1, storagePosition.column - 1));
      }
      if (
        route.length < 2 ||
        !this.routeEdgesExist(route) ||
        !this.agentMinimalYieldFirstLegSafe(storageVehicle, route[0]!, route[1]!) ||
        route.slice(1).some((nodeId, index) => {
          const occupantId = this.currentNodeOccupancy.get(nodeId);
          if (occupantId && occupantId !== storageVehicle.id) {
            return true;
          }
          if (this.nodeClaimedByOtherVehicle(nodeId, storageVehicle.id)) {
            return true;
          }
          if (this.storedLoadIdAtNode(nodeId)) {
            return true;
          }
          return index === route.length - 2 && protectedRouteNodeIds.includes(nodeId);
        })
      ) {
        continue;
      }
      const firstTargetNodeId = route[1]!;
      const moveBlock = this.agentRefreshMoveBlocker(storageVehicle, firstTargetNodeId, route);
      if (moveBlock) {
        continue;
      }
      if (this.agentRefreshTemporaryRouteAlreadyActive(storageVehicle, route)) {
        return true;
      }
      storageVehicle.routeNodeIds = route;
      storageVehicle.routeIndex = 0;
      storageVehicle.targetNodeId = firstTargetNodeId;
      storageVehicle.state = storageVehicle.taskId ? 'assigned' : 'returning';
      storageVehicle.waitReason = null;
      storageVehicle.blockingReservationId = null;
      storageVehicle.blockingVehicleId = null;
      storageVehicle.waitingSinceSec = null;
      storageVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(storageVehicle, route) + 2);
      storageVehicle.yieldHoldNodeId = route[route.length - 1]!;
      storageVehicle.localRouteNodeIds = route;
      storageVehicle.localRouteReason = 'inbound-dropoff-column-clearance';
      this.logAgentReroute(storageVehicle, this.taskForVehicle(storageVehicle), task.dropoffNodeId, route, 'agent-refresh-inbound-dropoff-column-clearance', { countTaskReplan: false });
      return true;
    }
    return false;
  }

  private tryRetreatLoadedInboundColumnEntryForTasklessExit(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      blocker.loaded ||
      loadedVehicle.currentEdgeId !== null ||
      loadedVehicle.legRemainingM > 0 ||
      loadedVehicle.phaseRemainingSec > 0 ||
      loadedVehicle.state === 'lifting' ||
      loadedVehicle.state === 'lowering' ||
      !isTopLiftColumnAccessNodeId(loadedVehicle.currentNodeId) ||
      !this.isStorageNode(blocker.currentNodeId) ||
      blocker.targetNodeId !== loadedVehicle.currentNodeId ||
      loadedVehicle.targetNodeId !== blocker.currentNodeId
    ) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask && blocker.currentNodeId === blockerTask.pickupNodeId) {
      return false;
    }

    const task = this.taskForVehicle(loadedVehicle);
    const loadedColumn = this.topLiftColumnAccessColumn(loadedVehicle.currentNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    if (
      task?.kind !== 'inbound' ||
      loadedColumn === null ||
      !blockerPosition ||
      blockerPosition.column !== loadedColumn ||
      this.storageGridPosition(task.dropoffNodeId)?.column !== loadedColumn
    ) {
      return false;
    }

    const route = this.topLiftLoadedInboundColumnEntryRetreatRoute(loadedVehicle, blocker.currentNodeId);
    if (!route) {
      return false;
    }

    loadedVehicle.routeNodeIds = route;
    loadedVehicle.routeIndex = 0;
    loadedVehicle.targetNodeId = route[1] ?? null;
    loadedVehicle.state = 'loaded-moving';
    loadedVehicle.waitReason = null;
    loadedVehicle.blockingReservationId = null;
    loadedVehicle.blockingVehicleId = null;
    loadedVehicle.waitingSinceSec = null;
    loadedVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(loadedVehicle, route) + 1);
    loadedVehicle.yieldHoldNodeId = route.at(-1) ?? null;
    loadedVehicle.localRouteNodeIds = route;
    loadedVehicle.localRouteReason = 'inbound-column-entry-retreat';
    this.logAgentReroute(loadedVehicle, task, blocker.currentNodeId, route, 'agent-refresh-inbound-column-entry-retreat', { countTaskReplan: false });
    return true;
  }

  private topLiftLoadedInboundColumnEntryRetreatRoute(
    loadedVehicle: MutableVehicle,
    blockedStorageNodeId: string
  ): string[] | null {
    const startNodeId = loadedVehicle.currentNodeId;
    const routes = this.neighbors(startNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedStorageNodeId)
      .map((neighbor) => this.topLiftLoadedInboundColumnEntryRetreatRouteFromFirstStep(
        loadedVehicle,
        blockedStorageNodeId,
        neighbor.nodeId
      ))
      .filter((route): route is string[] => route !== null)
      .filter((route) => this.agentRefreshLocalRouteNodesClear(loadedVehicle, route))
      .sort((left, right) =>
        this.topLiftColumnEntryRetreatRouteRank(left) - this.topLiftColumnEntryRetreatRouteRank(right) ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      );
    return routes[0] ?? this.topLiftLoadedInboundColumnEntryNoStopRetreatRoute(loadedVehicle, blockedStorageNodeId);
  }

  private topLiftLoadedInboundColumnEntryNoStopRetreatRoute(
    loadedVehicle: MutableVehicle,
    blockedStorageNodeId: string
  ): string[] | null {
    const currentLevel = topLiftAisleLevel(loadedVehicle.currentNodeId);
    const currentColumn = this.topLiftColumnAccessColumn(loadedVehicle.currentNodeId);
    if (currentLevel !== 'top-b' || currentColumn === null) {
      return null;
    }
    const retreatNodeId = columnAccessNodeId('top-a', currentColumn - 1);
    if (
      !this.layoutNode(retreatNodeId) ||
      retreatNodeId === blockedStorageNodeId ||
      !this.traffic.findEdge(loadedVehicle.currentNodeId, retreatNodeId) ||
      !this.topLiftLoadedInboundColumnEntryRetreatStepAllowed(loadedVehicle, loadedVehicle.currentNodeId, retreatNodeId, blockedStorageNodeId)
    ) {
      return null;
    }
    const route = [loadedVehicle.currentNodeId, retreatNodeId];
    return this.agentRefreshLocalRouteNodesClear(loadedVehicle, route) ? route : null;
  }

  private tryRerouteLoadedInboundAroundOccupiedStorageTransit(
    loadedVehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const task = this.taskForVehicle(loadedVehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      blocker.loaded ||
      task?.kind !== 'inbound' ||
      !this.isStorageNode(task.dropoffNodeId) ||
      !this.isStorageNode(blockedTargetNodeId) ||
      blockedTargetNodeId === task.dropoffNodeId ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      loadedVehicle.currentEdgeId !== null ||
      loadedVehicle.legRemainingM > 0 ||
      loadedVehicle.phaseRemainingSec > 0 ||
      loadedVehicle.state === 'lifting' ||
      loadedVehicle.state === 'lowering'
    ) {
      return false;
    }

    const blockedColumn = this.storageGridPosition(blockedTargetNodeId)?.column ?? null;
    const dropoffColumn = this.storageGridPosition(task.dropoffNodeId)?.column ?? null;
    if (blockedColumn === null || dropoffColumn === null || blockedColumn === dropoffColumn) {
      return false;
    }

    const route = this.agentRefreshLoadedInboundRouteToDropoff(loadedVehicle.currentNodeId, task);
    const nextNodeId = route[1] ?? null;
    if (
      route.length < 2 ||
      !nextNodeId ||
      nextNodeId === blockedTargetNodeId ||
      !this.routeEdgesExist(route) ||
      !this.agentRefreshLocalRouteNodesClear(loadedVehicle, route)
    ) {
      return false;
    }

    loadedVehicle.routeNodeIds = route;
    loadedVehicle.routeIndex = 0;
    loadedVehicle.targetNodeId = nextNodeId;
    loadedVehicle.state = 'loaded-moving';
    loadedVehicle.waitReason = null;
    loadedVehicle.blockingReservationId = null;
    loadedVehicle.blockingVehicleId = null;
    loadedVehicle.waitingSinceSec = null;
    loadedVehicle.plannedGoalNodeId = route.at(-1) ?? null;
    loadedVehicle.plannedRouteNodeIds = route;
    loadedVehicle.localRouteNodeIds = route;
    loadedVehicle.localRouteReason = 'loaded-inbound-storage-transit-bypass';
    loadedVehicle.yieldHoldUntilSec = null;
    loadedVehicle.yieldHoldNodeId = null;
    this.logAgentReroute(loadedVehicle, task, blockedTargetNodeId, route, 'loaded-inbound-storage-transit-bypass', { countTaskReplan: false });
    return true;
  }

  private topLiftLoadedInboundColumnEntryRetreatRouteFromFirstStep(
    loadedVehicle: MutableVehicle,
    blockedStorageNodeId: string,
    firstNodeId: string
  ): string[] | null {
    const startNodeId = loadedVehicle.currentNodeId;
    if (!this.topLiftLoadedInboundColumnEntryRetreatStepAllowed(loadedVehicle, startNodeId, firstNodeId, blockedStorageNodeId)) {
      return null;
    }
    const directRoute = [startNodeId, firstNodeId];
    if (this.topLiftLoadedInboundColumnEntryRetreatHoldAllowed(loadedVehicle, firstNodeId, blockedStorageNodeId)) {
      return directRoute;
    }

    const firstNode = this.layoutNode(firstNodeId);
    if (!firstNode?.noStop || !this.topLiftColumnSpineOrAccessNode(firstNodeId)) {
      return null;
    }

    const queue: Array<{ nodeId: string; routeNodeIds: string[]; distanceM: number }> = [{
      nodeId: firstNodeId,
      routeNodeIds: directRoute,
      distanceM: this.routeDistanceM(directRoute)
    }];
    const bestDistanceByNode = new Map<string, number>([
      [startNodeId, 0],
      [firstNodeId, queue[0]!.distanceM]
    ]);
    const maxRouteNodes = 8;

    while (queue.length > 0) {
      queue.sort((left, right) =>
        left.distanceM - right.distanceM ||
        left.routeNodeIds.join('>').localeCompare(right.routeNodeIds.join('>'))
      );
      const current = queue.shift()!;
      if (
        current.nodeId !== firstNodeId &&
        this.topLiftLoadedInboundColumnEntryRetreatHoldAllowed(loadedVehicle, current.nodeId, blockedStorageNodeId)
      ) {
        return current.routeNodeIds;
      }
      if (current.routeNodeIds.length >= maxRouteNodes) {
        continue;
      }

      for (const neighbor of this.neighbors(current.nodeId)) {
        if (
          neighbor.nodeId === startNodeId ||
          neighbor.nodeId === blockedStorageNodeId ||
          current.routeNodeIds.includes(neighbor.nodeId) ||
          !this.topLiftLoadedInboundColumnEntryRetreatStepAllowed(loadedVehicle, current.nodeId, neighbor.nodeId, blockedStorageNodeId)
        ) {
          continue;
        }
        const routeNodeIds = [...current.routeNodeIds, neighbor.nodeId];
        if (!this.routeHasOnlyAdjacentEdges(routeNodeIds)) {
          continue;
        }
        if (this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(loadedVehicle, routeNodeIds)) {
          continue;
        }
        const distanceM = current.distanceM + neighbor.lengthM;
        if (distanceM >= (bestDistanceByNode.get(neighbor.nodeId) ?? Infinity) - 1e-9) {
          continue;
        }
        bestDistanceByNode.set(neighbor.nodeId, distanceM);
        queue.push({ nodeId: neighbor.nodeId, routeNodeIds, distanceM });
      }
    }
    return null;
  }

  private topLiftLoadedInboundColumnEntryRetreatStepAllowed(
    loadedVehicle: MutableVehicle,
    fromNodeId: string,
    nodeId: string,
    blockedStorageNodeId: string | null = null
  ): boolean {
    const node = this.layoutNode(nodeId);
    if (!node || node.type === 'lift-blackbox') {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== loadedVehicle.id) {
      return false;
    }
    if (this.nodeClaimedByOtherVehicle(nodeId, loadedVehicle.id)) {
      return false;
    }
    if (this.isStorageNode(nodeId)) {
      return this.agentRefreshYieldPocketAllowed(loadedVehicle, nodeId) ||
        this.topLiftLoadedInboundColumnEntryEmergencyStorageHoldAllowed(loadedVehicle, nodeId, blockedStorageNodeId);
    }
    if (!node.noStop && !node.noParking) {
      return true;
    }
    return this.topLiftColumnSpineOrAccessNode(nodeId) &&
      this.agentMinimalYieldFirstLegSafe(loadedVehicle, fromNodeId, nodeId);
  }

  private topLiftLoadedInboundColumnEntryRetreatHoldAllowed(
    loadedVehicle: MutableVehicle,
    nodeId: string,
    blockedStorageNodeId: string | null = null
  ): boolean {
    const node = this.layoutNode(nodeId);
    if (!node || node.noStop || node.noParking) {
      return false;
    }
    if (node.type === 'storage') {
      return this.agentRefreshYieldPocketAllowed(loadedVehicle, nodeId) ||
        this.topLiftLoadedInboundColumnEntryEmergencyStorageHoldAllowed(loadedVehicle, nodeId, blockedStorageNodeId);
    }
    return node.type === 'parking' || node.type === 'aisle';
  }

  private topLiftLoadedInboundColumnEntryEmergencyStorageHoldAllowed(
    loadedVehicle: MutableVehicle,
    nodeId: string,
    blockedStorageNodeId: string | null
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !loadedVehicle.loaded ||
      !blockedStorageNodeId ||
      !isTopLiftColumnAccessNodeId(loadedVehicle.currentNodeId) ||
      !this.isStorageNode(nodeId) ||
      !this.isStorageNode(blockedStorageNodeId) ||
      this.storedLoadIdByNodeId.has(nodeId)
    ) {
      return false;
    }
    const task = this.taskForVehicle(loadedVehicle);
    const accessColumn = this.topLiftColumnAccessColumn(loadedVehicle.currentNodeId);
    const holdPosition = this.storageGridPosition(nodeId);
    const blockedPosition = this.storageGridPosition(blockedStorageNodeId);
    const dropoffPosition = this.storageGridPosition(task?.dropoffNodeId ?? '');
    if (
      task?.kind !== 'inbound' ||
      accessColumn === null ||
      !holdPosition ||
      !blockedPosition ||
      !dropoffPosition ||
      holdPosition.column !== accessColumn ||
      blockedPosition.column !== accessColumn ||
      dropoffPosition.column !== accessColumn ||
      holdPosition.row === blockedPosition.row
    ) {
      return false;
    }

    const activeDropoffTask = this.activeTasks().find((candidate) =>
      candidate.id !== task.id &&
      candidate.kind === 'inbound' &&
      candidate.dropoffNodeId === nodeId
    );
    if (!activeDropoffTask) {
      return true;
    }
    const activeVehicle = activeDropoffTask.vehicleId
      ? this.vehicles.find((candidate) => candidate.id === activeDropoffTask.vehicleId) ?? null
      : null;
    if (activeVehicle?.currentNodeId === nodeId || activeVehicle?.targetNodeId === nodeId) {
      return false;
    }
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const blockedLowerBank = blockedPosition.row > rowsPerZone;
    return blockedLowerBank
      ? holdPosition.row <= rowsPerZone && dropoffPosition.row > blockedPosition.row
      : holdPosition.row > rowsPerZone && dropoffPosition.row < blockedPosition.row;
  }

  private topLiftColumnEntryRetreatRouteRank(routeNodeIds: string[]): number {
    const firstNodeId = routeNodeIds[1] ?? routeNodeIds[0] ?? '';
    const holdNodeId = routeNodeIds.at(-1) ?? firstNodeId;
    const holdNode = this.layoutNode(holdNodeId);
    const holdRank = holdNode?.type === 'storage' ? 0 : holdNode?.type === 'parking' ? 1 : 2;
    return holdRank * 10 + this.topLiftColumnEntryRetreatRank(firstNodeId);
  }

  private topLiftColumnEntryRetreatRank(nodeId: string): number {
    if (this.isStorageNode(nodeId)) {
      return 0;
    }
    if (/^(?:module-\d+|module-boundary-\d+)-spine-(?:top-a|top-b|middle|bottom-a|bottom-b)$/.test(nodeId)) {
      return 1;
    }
    if (isTopLiftColumnAccessNodeId(nodeId)) {
      return 2;
    }
    return 3;
  }

  private tryYieldAisleAwayFromTopLiftServiceClearance(
    aisleVehicle: MutableVehicle,
    serviceVehicle: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const aisleTask = this.taskForVehicle(aisleVehicle);
    if (
      aisleTask?.kind === 'inbound' &&
      !aisleVehicle.loaded &&
      aisleVehicle.currentNodeId === aisleTask.pickupNodeId
    ) {
      return false;
    }

    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(serviceVehicle);
    if (
      !clearanceSegment ||
      topLiftAisleLevel(aisleVehicle.currentNodeId) !== 'top-b' ||
      aisleVehicle.currentEdgeId !== null ||
      aisleVehicle.legRemainingM > 0 ||
      aisleVehicle.phaseRemainingSec > 0 ||
      aisleVehicle.state === 'lifting' ||
      aisleVehicle.state === 'lowering'
    ) {
      return false;
    }

    const fromNode = this.layoutNode(clearanceSegment.fromNodeId);
    const toNode = this.layoutNode(clearanceSegment.toNodeId);
    const currentNode = this.layoutNode(aisleVehicle.currentNodeId);
    const blockedNode = this.layoutNode(blockedTargetNodeId);
    if (!fromNode || !toNode || !currentNode) {
      return false;
    }

    const clearanceM = this.scenario.vehicles.widthM / 2 + this.scenario.trafficPolicy.dynamicAvoidanceClearanceM;
    const currentDistanceM = this.pointToSegmentDistanceM(currentNode.x, currentNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z);
    const blockedDistanceM = blockedNode
      ? this.pointToSegmentDistanceM(blockedNode.x, blockedNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z)
      : Number.POSITIVE_INFINITY;
    if (currentDistanceM > clearanceM && blockedDistanceM > clearanceM) {
      return false;
    }

    const column = this.topLiftColumnAccessColumn(aisleVehicle.currentNodeId);
    if (column === null) {
      return false;
    }

    const sameLaneCandidateNodeIds = [
      column > 1 ? columnAccessNodeId('top-b', column - 2) : null,
      columnAccessNodeId('top-b', column)
    ].filter((nodeId): nodeId is string => nodeId !== null);
    const candidateNodeIds = aisleVehicle.loaded
      ? [
          ...sameLaneCandidateNodeIds,
          columnAccessNodeId('top-a', column - 1)
        ]
      : [
          columnAccessNodeId('top-a', column - 1),
          `storage-r01-c${String(column).padStart(2, '0')}`,
          ...sameLaneCandidateNodeIds
        ];
    const sameLaneCandidateNodeIdSet = new Set(sameLaneCandidateNodeIds);
    const requesterProtectedNodeIdSet = new Set([
      ...this.vehicleRouteTail(serviceVehicle, serviceVehicle.routeNodeIds).slice(1, 9),
      ...this.vehicleRouteTail(serviceVehicle, serviceVehicle.plannedRouteNodeIds).slice(1, 9),
      ...this.topLiftLoadedInboundServiceAccessConflictNodeIds(serviceVehicle)
    ]);
    const candidate = candidateNodeIds
      .filter((nodeId) => nodeId !== aisleVehicle.currentNodeId && nodeId !== blockedTargetNodeId)
      .map((nodeId) => this.neighbors(aisleVehicle.currentNodeId).find((neighbor) => neighbor.nodeId === nodeId) ?? null)
      .filter((neighbor): neighbor is { nodeId: string; lengthM: number } => neighbor !== null)
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(aisleVehicle, neighbor.nodeId))
      .filter((neighbor) => sameLaneCandidateNodeIdSet.has(neighbor.nodeId)
        ? !requesterProtectedNodeIdSet.has(neighbor.nodeId)
        : this.agentRefreshYieldPocketCompatibleWithRequester(aisleVehicle, neighbor.nodeId, serviceVehicle))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(aisleVehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(aisleVehicle, neighbor.nodeId, blockedTargetNodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(aisleVehicle, aisleVehicle.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.agentRefreshMoveBlocker(aisleVehicle, neighbor.nodeId, [
        aisleVehicle.currentNodeId,
        neighbor.nodeId
      ]))[0];
    if (!candidate) {
      return false;
    }

    const route = [aisleVehicle.currentNodeId, candidate.nodeId];
    if (this.agentRefreshTemporaryRouteAlreadyActive(aisleVehicle, route)) {
      return true;
    }
    aisleVehicle.routeNodeIds = route;
    aisleVehicle.routeIndex = 0;
    aisleVehicle.targetNodeId = candidate.nodeId;
    aisleVehicle.state = aisleVehicle.loaded ? 'loaded-moving' : aisleVehicle.taskId ? 'assigned' : 'returning';
    aisleVehicle.waitReason = null;
    aisleVehicle.blockingReservationId = null;
    aisleVehicle.blockingVehicleId = null;
    aisleVehicle.waitingSinceSec = null;
    aisleVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(aisleVehicle, route) + 2);
    aisleVehicle.yieldHoldNodeId = candidate.nodeId;
    aisleVehicle.localRouteNodeIds = route;
    aisleVehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(aisleVehicle, this.taskForVehicle(aisleVehicle), clearanceSegment.toNodeId, route, 'top-lift-service-clearance-aisle-yield', { countTaskReplan: false });
    return true;
  }

  private tryInstallTopLiftMiddleAisleStorageYield(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle') ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.state === 'lifting' ||
      vehicle.state === 'lowering' ||
      vehicle.loaded
    ) {
      return false;
    }

    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!currentPosition || blockedColumn !== currentPosition.column) {
      return false;
    }

    const blockedTarget = nodePosition(this.scenario, blockedTargetNodeId);
    const currentNodeId = vehicle.currentNodeId;
    const candidate = this.neighbors(currentNodeId)
      .filter((neighbor) => {
        const position = this.storageGridPosition(neighbor.nodeId);
        return position !== null && position.column === currentPosition.column;
      })
      .filter((neighbor) => neighbor.nodeId !== blockedTargetNodeId && neighbor.nodeId !== blocker.currentNodeId)
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(vehicle, neighbor.nodeId, currentNodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftPosition = nodePosition(this.scenario, left.nodeId);
        const rightPosition = nodePosition(this.scenario, right.nodeId);
        const leftAwayM = Math.abs(leftPosition.x - blockedTarget.x) + Math.abs(leftPosition.z - blockedTarget.z);
        const rightAwayM = Math.abs(rightPosition.x - blockedTarget.x) + Math.abs(rightPosition.z - blockedTarget.z);
        return rightAwayM - leftAwayM ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0];
    if (!candidate) {
      return false;
    }
    if (this.topLiftFifoHeldVehicle(vehicle) || this.topLiftFifoHeldVehicle(blocker)) {
      return false;
    }

    const route = [currentNodeId, candidate.nodeId];
    if (
      this.agentRefreshTemporaryRouteAlreadyActive(vehicle, route) ||
      (
        vehicle.localRouteReason === 'temporary-yield' &&
        vehicle.targetNodeId === candidate.nodeId &&
        vehicle.routeNodeIds.join('>') === route.join('>') &&
        vehicle.localRouteNodeIds.join('>') === route.join('>')
      )
    ) {
      return true;
    }
    const session = this.createAgentRefreshConflictSession(vehicle, blocker, blockedTargetNodeId, 'middle-aisle-opposing-claim');
    this.reassignAgentRefreshConflictSession(session, blocker, vehicle, blockedTargetNodeId);
    session.state = 'yielding';
    session.updatedAtSec = this.simTimeSec;
    session.yielderOriginalNodeId = currentNodeId;
    session.yielderPocketNodeId = candidate.nodeId;
    session.yielderLocalRouteNodeIds = route;
    session.resumeNodeId = blockedTargetNodeId;
    session.clearancePolicy = 'short-horizon';
    session.timeoutAtSec = Math.max(session.timeoutAtSec, round(this.simTimeSec + 20));
    session.expiresAtSec = Math.max(session.expiresAtSec, round(this.simTimeSec + 30));
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = candidate.nodeId;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 1);
    vehicle.yieldHoldNodeId = candidate.nodeId;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'temporary-yield';
    if (!vehicle.taskId && !vehicle.loaded) {
      vehicle.plannedGoalNodeId = candidate.nodeId;
      vehicle.plannedRouteNodeIds = route;
    }
    this.logAgentReroute(vehicle, task, blockedTargetNodeId, route, 'agent-refresh-middle-aisle-storage-yield', { countTaskReplan: false });
    return true;
  }

  private tryYieldLoadedMiddleAccessAwayFromNoStopCycle(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      task?.kind !== 'outbound' ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.state === 'lifting' ||
      vehicle.state === 'lowering' ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'middle')
    ) {
      return false;
    }

    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    if (currentColumn === null) {
      return false;
    }

    const followerBlockedNodeIds = new Set<string>();
    for (const other of this.vehicles) {
      if (other.id === vehicle.id || other.blockingVehicleId !== vehicle.id) {
        continue;
      }
      followerBlockedNodeIds.add(other.currentNodeId);
      if (other.targetNodeId) {
        followerBlockedNodeIds.add(other.targetNodeId);
      }
      for (const nodeId of this.vehicleRouteTail(other, other.routeNodeIds).slice(0, 3)) {
        followerBlockedNodeIds.add(nodeId);
      }
    }
    const activeInboundDropoffNodeIds = this.activeInboundDropoffNodeIds();
    const activeInboundDropoffColumnKeys = this.activeInboundDropoffColumnKeys();

    const route = this.neighbors(vehicle.currentNodeId)
      .map((neighbor) => neighbor.nodeId)
      .filter((nodeId) => {
        const position = this.storageGridPosition(nodeId);
        return position !== null && position.column === currentColumn;
      })
      .filter((nodeId) => {
        const columnKey = this.topLiftColumnKey(nodeId);
        return !activeInboundDropoffNodeIds.has(nodeId) &&
          (!columnKey || !activeInboundDropoffColumnKeys.has(columnKey));
      })
      .filter((nodeId) =>
        nodeId !== requester.currentNodeId &&
        nodeId !== requester.targetNodeId &&
        nodeId !== blockedTargetNodeId &&
        !followerBlockedNodeIds.has(nodeId) &&
        this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId) &&
        this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, nodeId) &&
        this.agentRefreshYieldPocketCanReturn(vehicle, nodeId, blockedTargetNodeId) &&
        this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, nodeId)
      )
      .map((nodeId) => [vehicle.currentNodeId, nodeId])
      .filter((routeNodeIds) =>
        this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) &&
        !this.agentRefreshMoveBlocker(vehicle, routeNodeIds[1]!, routeNodeIds)
      )
      .sort((left, right) => {
        const leftPosition = this.storageGridPosition(left[1]!);
        const rightPosition = this.storageGridPosition(right[1]!);
        return (
          (rightPosition?.row ?? 0) - (leftPosition?.row ?? 0) ||
          this.routeDistanceM(left) - this.routeDistanceM(right) ||
          left.join('>').localeCompare(right.join('>'))
        );
      })[0] ?? null;

    if (!route) {
      return false;
    }

    const session = this.activeConflictSessionForPair(vehicle.id, requester.id);
    if (session) {
      this.closeConflictSession(session, 'loaded-middle-access-storage-yield');
    }
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 2);
    vehicle.yieldHoldNodeId = route.at(-1) ?? null;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'loaded-middle-access-storage-yield';
    this.logAgentReroute(vehicle, task, blockedTargetNodeId, route, 'agent-refresh-loaded-middle-access-storage-yield', { countTaskReplan: false });
    return true;
  }

  private topLiftInboundRequesterShouldWaitForEarlierPickup(requester: MutableVehicle, blocker: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const requesterTask = this.taskForVehicle(requester);
    const blockerTask = this.taskForVehicle(blocker);
    if (
      requesterTask?.kind !== 'inbound' ||
      blockerTask?.kind !== 'inbound' ||
      requesterTask.pickupNodeId !== blockerTask.pickupNodeId
    ) {
      return false;
    }
    if (blockerTask.createdAtSec !== requesterTask.createdAtSec) {
      return blockerTask.createdAtSec < requesterTask.createdAtSec;
    }
    return blockerTask.id.localeCompare(requesterTask.id) < 0;
  }

  private tryYieldLoadedMiddleColumnBlockerForSpineSwap(
    spineVehicle: MutableVehicle,
    columnVehicle: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !spineVehicle.loaded ||
      !columnVehicle.loaded ||
      spineVehicle.currentEdgeId !== null ||
      columnVehicle.currentEdgeId !== null ||
      spineVehicle.legRemainingM > 0 ||
      columnVehicle.legRemainingM > 0 ||
      spineVehicle.phaseRemainingSec > 0 ||
      columnVehicle.phaseRemainingSec > 0 ||
      !isTopLiftSpineLevelNodeId(spineVehicle.currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(columnVehicle.currentNodeId, 'middle') ||
      spineVehicle.targetNodeId !== columnVehicle.currentNodeId ||
      columnVehicle.targetNodeId !== spineVehicle.currentNodeId
    ) {
      return false;
    }
    const spineTask = this.taskForVehicle(spineVehicle);
    const columnTask = this.taskForVehicle(columnVehicle);
    if (spineTask?.kind !== 'inbound' || columnTask?.kind !== 'outbound') {
      return false;
    }
    const protectedNodeIds = new Set<string>([
      blockedTargetNodeId,
      ...this.vehicleRouteTail(spineVehicle, spineVehicle.routeNodeIds).slice(0, 4)
    ]);
    const candidateRoutes = this.neighbors(columnVehicle.currentNodeId)
      .filter((neighbor) =>
        neighbor.nodeId !== spineVehicle.currentNodeId &&
        (
          isTopLiftAisleLevelNodeId(neighbor.nodeId, 'middle') ||
          (this.isStorageNode(neighbor.nodeId) && this.agentRefreshTemporaryStorageNodeAllowed(columnVehicle, neighbor.nodeId))
        ) &&
        !protectedNodeIds.has(neighbor.nodeId) &&
        !this.currentNodeOccupancy.has(neighbor.nodeId) &&
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, columnVehicle.id) &&
        this.agentMinimalYieldFirstLegSafe(columnVehicle, columnVehicle.currentNodeId, neighbor.nodeId)
      )
      .map((neighbor) => this.extendTopLiftTemporaryYieldRouteToHold(columnVehicle, [columnVehicle.currentNodeId, neighbor.nodeId], protectedNodeIds))
      .filter((routeNodeIds): routeNodeIds is string[] =>
        routeNodeIds !== null &&
        routeNodeIds.length > 1 &&
        this.routeHasOnlyAdjacentEdges(routeNodeIds) &&
        this.agentRefreshLocalRouteNodesClear(columnVehicle, routeNodeIds) &&
        !this.agentRefreshMoveBlocker(columnVehicle, routeNodeIds[1]!, routeNodeIds)
      )
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      );
    const routeNodeIds = candidateRoutes[0] ?? null;
    if (!routeNodeIds) {
      return false;
    }
    return this.installAgentRefreshTopLiftSpineCycleYield(columnVehicle, routeNodeIds);
  }

  private tryYieldLaterInboundQueueBlockerForEarlierPickup(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      !this.topLiftInboundRequesterShouldWaitForEarlierPickup(blocker, requester)
    ) {
      return false;
    }

    const route = this.topLiftInboundStagedQueueStoragePocketRoute(blocker);
    if (!route || !this.agentRefreshLocalRouteNodesClear(blocker, route)) {
      return false;
    }
    return this.installAgentRefreshSideYieldRoute(blocker, requester, blockedTargetNodeId, route, null);
  }

  private tryYieldInboundQueueRequesterForEarlierPickup(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      requester.loaded ||
      requester.currentEdgeId !== null ||
      requester.legRemainingM > 0 ||
      requester.phaseRemainingSec > 0 ||
      !this.topLiftInboundRequesterShouldWaitForEarlierPickup(requester, blocker)
    ) {
      return false;
    }

    const route = this.topLiftInboundStagedQueueStoragePocketRoute(requester);
    if (!route || !this.agentRefreshLocalRouteNodesClear(requester, route)) {
      return false;
    }
    return this.installAgentRefreshSideYieldRoute(requester, blocker, blockedTargetNodeId, route, null);
  }

  private tryYieldTopAInboundQueueBlockerForEntryRequester(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    const blockerTask = this.taskForVehicle(blocker);
    const entrySlot = topLiftQueueEntrySlot(blockedTargetNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      requester.loaded ||
      blocker.loaded ||
      requesterTask?.kind !== 'inbound' ||
      blockerTask?.kind !== 'inbound' ||
      !entrySlot ||
      this.liftPortKindForNodeId(entrySlot.liftNodeId) !== 'inbound' ||
      requester.currentEdgeId !== null ||
      blocker.currentEdgeId !== null ||
      requester.legRemainingM > 0 ||
      blocker.legRemainingM > 0 ||
      requester.phaseRemainingSec > 0 ||
      blocker.phaseRemainingSec > 0 ||
      !isTopLiftAisleLevelNodeId(requester.currentNodeId, 'top-b') ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'top-a') ||
      !this.topLiftFifoHeldVehicle(blocker) ||
      !this.topLiftInboundQueueAreaNode(blocker.currentNodeId)
    ) {
      return false;
    }
    if (
      this.taskLiftPortNodeId(requesterTask) !== entrySlot.liftNodeId ||
      this.taskLiftPortNodeId(blockerTask) !== entrySlot.liftNodeId ||
      !this.inboundTaskBlocksLiftPickupOrder(requesterTask, blockerTask)
    ) {
      return false;
    }

    const requesterColumn = this.topLiftColumnAccessColumn(requester.currentNodeId);
    const blockerColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    const currentSlot = this.topLiftInboundApproachQueueSlot(blocker.currentNodeId);
    if (
      requesterColumn === null ||
      blockerColumn === null ||
      requesterColumn !== blockerColumn ||
      currentSlot?.liftNodeId !== entrySlot.liftNodeId
    ) {
      return false;
    }
    const currentSlotIndex = currentSlot.slotIndex;

    const route = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'top-a'))
      .filter((neighbor) => this.topLiftColumnAccessColumn(neighbor.nodeId) !== blockerColumn)
      .filter((neighbor) => {
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        return (!occupantId || occupantId === blocker.id) &&
          !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id) &&
          this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId);
      })
      .sort((left, right) => {
        const leftColumn = this.topLiftColumnAccessColumn(left.nodeId) ?? blockerColumn;
        const rightColumn = this.topLiftColumnAccessColumn(right.nodeId) ?? blockerColumn;
        const leftSlot = this.topLiftInboundApproachQueueSlot(left.nodeId);
        const rightSlot = this.topLiftInboundApproachQueueSlot(right.nodeId);
        const leftStaysInQueue = leftSlot?.liftNodeId === entrySlot.liftNodeId && leftSlot.slotIndex > currentSlotIndex ? 0 : 1;
        const rightStaysInQueue = rightSlot?.liftNodeId === entrySlot.liftNodeId && rightSlot.slotIndex > currentSlotIndex ? 0 : 1;
        return leftStaysInQueue - rightStaysInQueue ||
          Math.abs(leftColumn - blockerColumn) - Math.abs(rightColumn - blockerColumn) ||
          left.nodeId.localeCompare(right.nodeId);
      })
      .map((neighbor) => [blocker.currentNodeId, neighbor.nodeId])
      .find((candidateRoute) =>
        this.routeEdgesExist(candidateRoute) &&
        this.agentRefreshLocalRouteNodesClear(blocker, candidateRoute) &&
        !this.agentRefreshMoveBlocker(blocker, candidateRoute[1]!, candidateRoute)
      );
    if (!route) {
      return false;
    }

    this.installInboundPickupClearanceRoute(blocker, blockerTask, route, 'top-a-inbound-queue-blocker-yield', 2);
    return true;
  }

  private tryYieldTopBRequesterAwayFromInboundQueueTail(
    requester: MutableVehicle,
    queueYielder: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    const blockedTargetEntrySlot = topLiftQueueEntrySlot(blockedTargetNodeId);
    const blockedTargetIsInboundEntryAccess = Boolean(
      blockedTargetEntrySlot &&
      this.liftPortKindForNodeId(blockedTargetEntrySlot.liftNodeId) === 'inbound'
    );
    if (
      !this.topLiftColumnLayoutEnabled() ||
      requester.loaded ||
      requesterTask === null ||
      !this.topLiftInboundQueueTailYieldVehicle(queueYielder) ||
      topLiftAisleLevel(requester.currentNodeId) !== 'top-b' ||
      (topLiftAisleLevel(blockedTargetNodeId) !== 'top-b' && !blockedTargetIsInboundEntryAccess) ||
      requester.currentEdgeId !== null ||
      requester.legRemainingM > 0 ||
      requester.phaseRemainingSec > 0
    ) {
      return false;
    }

    const currentColumn = this.topLiftColumnAccessColumn(requester.currentNodeId);
    if (!currentColumn) {
      return false;
    }
    const topANodeId = columnAccessNodeId('top-a', currentColumn - 1);
    const candidateRoutes = [
      [requester.currentNodeId, topANodeId],
      ...this.neighbors(requester.currentNodeId)
        .filter((neighbor) =>
          this.isStorageNode(neighbor.nodeId) &&
          this.agentRefreshTemporaryStorageNodeAllowed(requester, neighbor.nodeId)
        )
        .sort((left, right) => {
          const leftPosition = this.storageGridPosition(left.nodeId);
          const rightPosition = this.storageGridPosition(right.nodeId);
          return (leftPosition?.row ?? Number.MAX_SAFE_INTEGER) - (rightPosition?.row ?? Number.MAX_SAFE_INTEGER) ||
            left.lengthM - right.lengthM ||
            left.nodeId.localeCompare(right.nodeId);
        })
        .map((neighbor) => [requester.currentNodeId, neighbor.nodeId])
    ];
    const route = candidateRoutes.find((candidateRoute) => {
      const targetNodeId = candidateRoute[1]!;
      return Boolean(
        this.traffic.findEdge(candidateRoute[0]!, targetNodeId) &&
        !this.currentNodeOccupancy.has(targetNodeId) &&
        !this.nodeClaimedByOtherVehicle(targetNodeId, requester.id) &&
        this.agentMinimalYieldFirstLegSafe(requester, candidateRoute[0]!, targetNodeId) &&
        this.agentRefreshLocalRouteNodesClear(requester, candidateRoute) &&
        !this.agentRefreshMoveBlocker(requester, targetNodeId, candidateRoute)
      );
    }) ?? null;
    if (!route) {
      return false;
    }
    const yieldTargetNodeId = route[1]!;
    if (this.agentRefreshTemporaryRouteAlreadyActive(requester, route)) {
      return true;
    }

    requester.routeNodeIds = route;
    requester.routeIndex = 0;
    requester.targetNodeId = yieldTargetNodeId;
    requester.state = requester.taskId ? 'moving-to-pickup' : 'returning';
    requester.waitReason = null;
    requester.blockingReservationId = null;
    requester.blockingVehicleId = null;
    requester.waitingSinceSec = null;
    requester.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(requester, route) + 2);
    requester.yieldHoldNodeId = yieldTargetNodeId;
    requester.localRouteNodeIds = route;
    requester.localRouteReason = 'temporary-yield';
    this.logAgentReroute(requester, requesterTask, blockedTargetNodeId, route, 'inbound-queue-tail-top-b-yield', { countTaskReplan: false });
    return true;
  }

  private tryBypassParkedInboundQueueBlockerViaTopA(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      requester.loaded ||
      requesterTask === null ||
      requesterTask.kind !== 'inbound' ||
      !this.topLiftFifoHeldVehicle(blocker) ||
      !this.topLiftInboundQueueAreaNode(blocker.currentNodeId) ||
      topLiftAisleLevel(requester.currentNodeId) !== 'top-b' ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'top-b' ||
      requester.currentEdgeId !== null ||
      requester.legRemainingM > 0 ||
      requester.phaseRemainingSec > 0
    ) {
      return false;
    }

    const route = this.emptyTopBQueueBlockerTopABypassRoute(requester, blockedTargetNodeId, requesterTask);
    if (!route || route.length < 3 || route[1] === blockedTargetNodeId) {
      return false;
    }
    if (this.agentRefreshTemporaryRouteAlreadyActive(requester, route)) {
      return true;
    }

    requester.routeNodeIds = route;
    requester.routeIndex = 0;
    requester.targetNodeId = route[1] ?? null;
    requester.state = requester.taskId ? 'moving-to-pickup' : 'returning';
    requester.waitReason = null;
    requester.blockingReservationId = null;
    requester.blockingVehicleId = null;
    requester.waitingSinceSec = null;
    requester.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(requester, route) + 2);
    requester.yieldHoldNodeId = route.at(-1) ?? null;
    requester.localRouteNodeIds = route;
    requester.localRouteReason = 'temporary-yield';
    this.logAgentReroute(requester, requesterTask, blockedTargetNodeId, route, 'parked-inbound-queue-top-a-bypass', { countTaskReplan: false });
    return true;
  }

  private tryRerouteStorageExitAroundParkedInboundQueueBlocker(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      requester.loaded ||
      requesterTask === null ||
      !this.topLiftFifoHeldVehicle(blocker) ||
      !this.topLiftInboundQueueAreaNode(blocker.currentNodeId) ||
      !this.isStorageNode(requester.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(blockedTargetNodeId, 'top-b') ||
      requester.currentEdgeId !== null ||
      requester.legRemainingM > 0 ||
      requester.phaseRemainingSec > 0 ||
      !this.traffic.findEdge(requester.currentNodeId, blockedTargetNodeId)
    ) {
      return false;
    }

    const goalNodeId = this.agentGoalNodeId(requester, requesterTask);
    if (!goalNodeId || goalNodeId === requester.currentNodeId) {
      return false;
    }

    const blockedNodeIds = this.agentRefreshBlockedNodeIds(requester, requesterTask, goalNodeId);
    blockedNodeIds.add(blockedTargetNodeId);
    blockedNodeIds.add(blocker.currentNodeId);
    blockedNodeIds.delete(requester.currentNodeId);
    blockedNodeIds.delete(goalNodeId);
    blockedNodeIds.delete(requesterTask.pickupNodeId);
    blockedNodeIds.delete(requesterTask.dropoffNodeId);

    const route = this.tryAgentRefreshShortestPath(
      requester.currentNodeId,
      goalNodeId,
      blockedNodeIds,
      requester.lastMovementAxis
    );
    const expandedRoute = route ? this.agentRefreshExpandLiftColumnSegments(route) : null;
    const candidateRoute = expandedRoute && expandedRoute.length >= 2 && expandedRoute[1] !== blockedTargetNodeId
      ? expandedRoute
      : this.storageExitFallbackPocketRoute(requester, blockedTargetNodeId);
    if (!candidateRoute || candidateRoute.length < 2 || candidateRoute[1] === blockedTargetNodeId) {
      return false;
    }
    const nextNodeId = candidateRoute[1]!;
    if (
      !this.routeEdgesExist(candidateRoute) ||
      this.routeHasRepeatedNode(candidateRoute) ||
      !this.agentRefreshLocalRouteNodesClear(requester, candidateRoute) ||
      this.agentRefreshMoveBlocker(requester, nextNodeId, candidateRoute)
    ) {
      return false;
    }
    if (this.agentRefreshTemporaryRouteAlreadyActive(requester, candidateRoute)) {
      return true;
    }

    requester.routeNodeIds = candidateRoute;
    requester.routeIndex = 0;
    requester.targetNodeId = nextNodeId;
    requester.state = requester.taskId ? 'moving-to-pickup' : 'returning';
    requester.waitReason = null;
    requester.blockingReservationId = null;
    requester.blockingVehicleId = null;
    requester.waitingSinceSec = null;
    requester.plannedGoalNodeId = candidateRoute.at(-1) ?? null;
    requester.plannedRouteNodeIds = candidateRoute;
    requester.localRouteNodeIds = candidateRoute;
    requester.localRouteReason = 'temporary-yield';
    requester.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(requester, candidateRoute) + 2);
    requester.yieldHoldNodeId = candidateRoute.at(-1) ?? null;
    this.logAgentReroute(requester, requesterTask, blockedTargetNodeId, candidateRoute, 'parked-inbound-queue-storage-exit-reroute', { countTaskReplan: false });
    return true;
  }

  private storageExitFallbackPocketRoute(vehicle: MutableVehicle, blockedTargetNodeId: string): string[] | null {
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!currentPosition || blockedColumn !== currentPosition.column) {
      return null;
    }

    const candidates = [
      storageNodeId(currentPosition.row, currentPosition.column - 1),
      storageNodeId(currentPosition.row - 1, currentPosition.column),
      storageNodeId(currentPosition.row - 1, currentPosition.column - 2)
    ];
    for (const candidateNodeId of candidates) {
      if (
        !this.isStorageNode(candidateNodeId) ||
        !this.traffic.findEdge(vehicle.currentNodeId, candidateNodeId) ||
        !this.agentRefreshTemporaryStorageNodeAllowed(vehicle, candidateNodeId) ||
        !this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, candidateNodeId)
      ) {
        continue;
      }
      const route = [vehicle.currentNodeId, candidateNodeId];
      if (this.agentRefreshLocalRouteNodesClear(vehicle, route) && !this.agentRefreshMoveBlocker(vehicle, candidateNodeId, route)) {
        return route;
      }
    }
    return null;
  }

  private emptyTopBQueueBlockerTopABypassRoute(
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    task: TaskStateRecord
  ): string[] | null {
    const currentColumn = this.topLiftColumnAccessColumn(requester.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (currentColumn === null || blockedColumn === null) {
      return null;
    }
    const direction = Math.sign(blockedColumn - currentColumn);
    if (direction !== -1 && direction !== 1) {
      return null;
    }

    const minColumn = Math.min(...this.topLiftStorageColumnNumbers());
    const maxColumn = Math.max(...this.topLiftStorageColumnNumbers());
    const routeTail = this.vehicleRouteTailForMove(requester, blockedTargetNodeId);
    const candidateRoutes: string[][] = [];
    for (
      let exitColumn = currentColumn + direction * 2;
      exitColumn >= minColumn && exitColumn <= maxColumn && candidateRoutes.length < 5;
      exitColumn += direction
    ) {
      const route = [requester.currentNodeId, columnAccessNodeId('top-a', currentColumn - 1)];
      for (let column = currentColumn + direction; direction > 0 ? column <= exitColumn : column >= exitColumn; column += direction) {
        route.push(columnAccessNodeId('top-a', column - 1));
      }
      const exitTopBNodeId = columnAccessNodeId('top-b', exitColumn - 1);
      route.push(exitTopBNodeId);

      const tailIndex = routeTail.indexOf(exitTopBNodeId);
      if (tailIndex >= 0) {
        route.push(...routeTail.slice(tailIndex + 1));
      } else {
        const goalNodeId = this.agentGoalNodeId(requester, task);
        if (!goalNodeId || goalNodeId === exitTopBNodeId) {
          continue;
        }
        const continuation = this.tryAgentRefreshShortestPath(
          exitTopBNodeId,
          goalNodeId,
          this.agentRefreshBlockedNodeIds(requester, task, goalNodeId),
          this.routeTerminalAxis(route)
        );
        if (!continuation || continuation.length < 2) {
          continue;
        }
        route.push(...continuation.slice(1));
      }
      candidateRoutes.push(route);
    }

    return candidateRoutes.find((route) => {
      const nextNodeId = route[1] ?? null;
      return Boolean(
        nextNodeId &&
        this.routeEdgesExist(route) &&
        !this.routeHasRepeatedNode(route) &&
        this.agentRefreshLocalRouteNodesClear(requester, route) &&
        !this.agentRefreshMoveBlocker(requester, nextNodeId, route)
      );
    }) ?? null;
  }

  private topLiftInboundStagedQueueStoragePocketRoute(vehicle: MutableVehicle): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (
      task?.kind !== 'inbound' ||
      (!this.inboundTaskShouldWaitBeforePickup(task) && this.inboundTaskLoadReadyAtPickup(task))
    ) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const pickupColumn = this.topLiftColumnAccessColumn(task.pickupNodeId);
    const currentIsAdjacentTopBPickupEdge =
      topLiftAisleLevel(vehicle.currentNodeId) === 'top-b' &&
      currentColumn !== null &&
      pickupColumn !== null &&
      Math.abs(currentColumn - pickupColumn) <= 1 &&
      this.neighbors(vehicle.currentNodeId).some((neighbor) =>
        this.layoutNode(neighbor.nodeId)?.type === 'storage'
      );
    if (
      !liftNodeId ||
      (
        this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId)?.liftNodeId !== liftNodeId &&
        vehicle.currentNodeId !== task.pickupNodeId &&
        !currentIsAdjacentTopBPickupEdge
      )
    ) {
      return null;
    }

    const sideAislePocketNodeId = this.topLiftInboundStagedQueueSideAislePocketNodeId(vehicle);
    if (
      sideAislePocketNodeId &&
      this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, sideAislePocketNodeId)
    ) {
      return [vehicle.currentNodeId, sideAislePocketNodeId];
    }

    const candidate = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => this.layoutNode(neighbor.nodeId)?.type === 'storage')
      .filter((neighbor) => this.agentRefreshTemporaryStorageNodeAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftPosition = this.storageGridPosition(left.nodeId);
        const rightPosition = this.storageGridPosition(right.nodeId);
        return (leftPosition?.row ?? Number.MAX_SAFE_INTEGER) - (rightPosition?.row ?? Number.MAX_SAFE_INTEGER) ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0];
    return candidate ? [vehicle.currentNodeId, candidate.nodeId] : null;
  }

  private topLiftInboundStagedQueueSideAislePocketNodeId(vehicle: MutableVehicle): string | null {
    const currentNodeId = vehicle.currentNodeId;
    if (!isTopLiftAisleLevelNodeId(currentNodeId, 'top-a')) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(currentNodeId);
    if (column === null) {
      return null;
    }
    const sideNodeId = columnAccessNodeId('top-b', column - 1);
    if (!this.layoutNode(sideNodeId) || !this.traffic.findEdge(currentNodeId, sideNodeId)) {
      return null;
    }
    const occupantId = this.currentNodeOccupancy.get(sideNodeId);
    if (occupantId) {
      return null;
    }
    return this.nodeClaimedByOtherVehicle(sideNodeId, vehicle.id) ? null : sideNodeId;
  }

  private tryYieldInboundQueueEntrantAwayFromLoadedExit(entrant: MutableVehicle, exiting: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || entrant.loaded || !exiting.loaded) {
      return false;
    }
    const entrantTask = this.taskForVehicle(entrant);
    const exitingTask = this.taskForVehicle(exiting);
    if (entrantTask?.kind !== 'inbound' || exitingTask?.kind !== 'inbound') {
      return false;
    }
    const exitingLiftNodeId = this.taskLiftPortNodeId(exitingTask);
    const entrantLiftNodeId = this.taskLiftPortNodeId(entrantTask);
    if (
      !exitingLiftNodeId ||
      exitingLiftNodeId !== entrantLiftNodeId ||
      this.liftPortKindForNodeId(exitingLiftNodeId) !== 'inbound' ||
      !isTopLiftAisleLevelNodeId(entrant.currentNodeId, 'top-b')
    ) {
      return false;
    }

    const exitingEntry = topLiftQueueEntrySlot(exiting.currentNodeId);
    const entrantTargetEntry = topLiftQueueEntrySlot(entrant.targetNodeId ?? '');
    const sameLegacyQueueEntry = Boolean(
      exitingEntry &&
      entrantTargetEntry &&
      exitingEntry.liftNodeId === entrantTargetEntry.liftNodeId
    );
    const entrantProjectedToLift = [entrant.currentNodeId, entrant.targetNodeId, entrant.plannedGoalNodeId].some((nodeId) =>
      this.topLiftProjectedInboundLiftNodeId(nodeId ?? '') === exitingLiftNodeId ||
      this.topLiftInboundApproachQueueSlot(nodeId ?? '')?.liftNodeId === exitingLiftNodeId
    );
    const exitingRouteTail = this.vehicleRouteTail(exiting, exiting.routeNodeIds);
    const exitingNeedsEntrantNode = exiting.targetNodeId === entrant.currentNodeId ||
      exitingRouteTail.slice(1).includes(entrant.currentNodeId);
    if (!sameLegacyQueueEntry && (!entrantProjectedToLift || !exitingNeedsEntrantNode)) {
      return false;
    }
    const exitNodeId = exitingEntry ? this.topLiftQueueEntryBottomAccessNodeId(exiting.currentNodeId) : null;
    if (
      sameLegacyQueueEntry &&
      exitNodeId !== entrant.currentNodeId &&
      exiting.targetNodeId !== entrant.currentNodeId &&
      !exitingRouteTail.slice(1).includes(entrant.currentNodeId)
    ) {
      return false;
    }
    const route = this.topLiftInboundQueueEntrantYieldRoute(entrant, exiting);
    if (!route) {
      return false;
    }
    if (
      entrant.localRouteReason === 'temporary-yield' &&
      entrant.routeNodeIds.join('>') === route.join('>') &&
      entrant.localRouteNodeIds.join('>') === route.join('>')
    ) {
      return true;
    }

    entrant.routeNodeIds = route;
    entrant.routeIndex = 0;
    entrant.targetNodeId = route[1] ?? null;
    entrant.currentEdgeId = null;
    entrant.legRemainingM = 0;
    entrant.phaseRemainingSec = 0;
    entrant.speedMps = 0;
    entrant.state = entrant.taskId ? 'moving-to-pickup' : 'returning';
    entrant.waitReason = null;
    entrant.blockingReservationId = null;
    entrant.blockingVehicleId = null;
    entrant.waitingSinceSec = null;
    entrant.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(entrant, route) + 2);
    entrant.yieldHoldNodeId = route.at(-1) ?? null;
    entrant.localRouteNodeIds = route;
    entrant.localRouteReason = 'temporary-yield';
    this.logAgentReroute(entrant, entrantTask, exiting.currentNodeId, route, 'inbound-lift-entry-yield', { countTaskReplan: false });
    return true;
  }

  private topLiftInboundQueueEntrantYieldRoute(entrant: MutableVehicle, exiting: MutableVehicle): string[] | null {
    const currentColumn = this.topLiftColumnAccessColumn(entrant.currentNodeId);
    if (!currentColumn) {
      return null;
    }

    const candidateRoutes: string[][] = [];
    candidateRoutes.push(...this.topLiftInboundQueueEntrantHorizontalYieldRoutes(entrant.currentNodeId, exiting));
    candidateRoutes.push([entrant.currentNodeId, storageNodeId(0, currentColumn - 1)]);

    for (const route of candidateRoutes) {
      if (this.topLiftInboundQueueEntrantYieldRouteClear(entrant, exiting, route)) {
        return route;
      }
    }
    return null;
  }

  private topLiftInboundQueueEntrantHorizontalYieldRoutes(currentNodeId: string, exiting: MutableVehicle): string[][] {
    const currentNode = this.layoutNode(currentNodeId);
    if (!currentNode || !isTopLiftAisleLevelNodeId(currentNodeId, 'top-b')) {
      return [];
    }
    const topBNodes = this.scenario.layout.nodes
      .filter((node) => isTopLiftAisleLevelNodeId(node.id, 'top-b'))
      .sort((left, right) => left.x - right.x || left.id.localeCompare(right.id));
    const currentIndex = topBNodes.findIndex((node) => node.id === currentNodeId);
    if (currentIndex < 0) {
      return [];
    }

    const exitingRoute = this.vehicleRouteTailForMove(exiting, currentNodeId);
    const currentInExitRoute = exitingRoute.indexOf(currentNodeId);
    const protectedExitNodeIds = new Set(
      currentInExitRoute >= 0
        ? exitingRoute.slice(currentInExitRoute)
        : [currentNodeId, exiting.targetNodeId].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    const nextExitNode = currentInExitRoute >= 0 ? this.layoutNode(exitingRoute[currentInExitRoute + 1] ?? '') : null;
    const preferredDirection = nextExitNode ? Math.sign(currentNode.x - nextExitNode.x) : 1;
    const directions = preferredDirection === 0 ? [1, -1] : [preferredDirection, -preferredDirection];
    const stepPreference = [2, 1, 3, 4];
    const routes: string[][] = [];
    for (const direction of directions) {
      for (const stepCount of stepPreference) {
        const targetIndex = currentIndex + direction * stepCount;
        if (targetIndex < 0 || targetIndex >= topBNodes.length) {
          continue;
        }
        const route = direction > 0
          ? topBNodes.slice(currentIndex, targetIndex + 1).map((node) => node.id)
          : topBNodes.slice(targetIndex, currentIndex + 1).reverse().map((node) => node.id);
        if (route.length < 2 || route.slice(1).some((nodeId) => protectedExitNodeIds.has(nodeId))) {
          continue;
        }
        routes.push(route);
      }
    }
    return routes.filter((route, index, all) =>
      all.findIndex((candidate) => candidate.join('>') === route.join('>')) === index
    );
  }

  private topLiftInboundQueueEntrantYieldRouteClear(
    entrant: MutableVehicle,
    exiting: MutableVehicle,
    route: string[]
  ): boolean {
    if (
      route.length < 2 ||
      route[0] !== entrant.currentNodeId ||
      !this.routeEdgesExist(route) ||
      !this.agentMinimalYieldFirstLegSafe(entrant, route[0], route[1]!)
    ) {
      return false;
    }
    const exitingRoute = this.vehicleRouteTailForMove(exiting, entrant.currentNodeId);
    const entrantIndex = exitingRoute.indexOf(entrant.currentNodeId);
    const protectedExitNodeIds = new Set(
      entrantIndex >= 0
        ? exitingRoute.slice(entrantIndex + 1)
        : [exiting.targetNodeId].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    for (const nodeId of route.slice(1)) {
      if (nodeId === exiting.currentNodeId || protectedExitNodeIds.has(nodeId)) {
        return false;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== entrant.id) {
        return false;
      }
      if (this.nodeClaimedByOtherVehicle(nodeId, entrant.id)) {
        return false;
      }
      if (this.isStorageNode(nodeId)) {
        if (this.storedLoadIdAtNode(nodeId) || !this.agentRefreshTemporaryStorageNodeAllowed(entrant, nodeId)) {
          return false;
        }
      }
    }
    return this.agentRefreshLocalRouteNodesClear(entrant, route);
  }

  private topLiftLaneTransferShouldWait(fromNodeId: string, toNodeId: string, blockReason: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      blockReason !== 'node-local-yield'
    ) {
      return false;
    }

    const fromLevel = topLiftAisleLevel(fromNodeId);
    const toLevel = topLiftAisleLevel(toNodeId);
    const laneTransfer =
      (fromLevel === 'top-a' && toLevel === 'top-b') ||
      (fromLevel === 'top-b' && toLevel === 'top-a') ||
      (fromLevel === 'bottom-a' && toLevel === 'bottom-b') ||
      (fromLevel === 'bottom-b' && toLevel === 'bottom-a');
    if (!laneTransfer) {
      return false;
    }

    const fromNode = this.layoutNode(fromNodeId);
    const toNode = this.layoutNode(toNodeId);
    return Boolean(fromNode && toNode && Math.abs(fromNode.x - toNode.x) <= 1e-6);
  }

  private topLiftMainAisleBlockedVehicleShouldHoldLine(vehicle: MutableVehicle, blockedTargetNodeId: string): boolean {
    return this.topLiftTaskVehicleMainSpineShouldHoldLine(vehicle, blockedTargetNodeId);
  }

  private topLiftTaskVehicleMainSpineShouldHoldLine(vehicle: MutableVehicle, blockedTargetNodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId === null ||
      !this.topLiftAdjacentSwapNetworkNode(vehicle.currentNodeId) ||
      !this.topLiftAdjacentSwapNetworkNode(blockedTargetNodeId)
    ) {
      return false;
    }
    return (
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-b')
    ) && isTopLiftSpineLevelNodeId(blockedTargetNodeId, 'middle');
  }

  private topLiftMiddleAisleTaskYieldSurfaceRank(
    vehicle: MutableVehicle,
    currentNodeId: string,
    blockedTargetNodeId: string,
    candidateNodeId: string
  ): number {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !vehicle.taskId ||
      topLiftAisleLevel(currentNodeId) !== 'middle' ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'middle'
    ) {
      return 0;
    }
    if (this.topLiftColumnSpineOrAccessNode(candidateNodeId)) {
      return 0;
    }
    return this.isStorageNode(candidateNodeId) ? 1 : 2;
  }

  private agentRefreshSameDirectionFollowerBlock(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const from = nodePosition(this.scenario, vehicle.currentNodeId);
    const target = nodePosition(this.scenario, blockedTargetNodeId);
    const dx = target.x - from.x;
    const dz = target.z - from.z;
    const length = Math.hypot(dx, dz);
    if (length <= 1e-9) {
      return false;
    }

    const ux = dx / length;
    const uz = dz / length;
    const relX = blocker.x - from.x;
    const relZ = blocker.z - from.z;
    const projection = relX * ux + relZ * uz;
    const lateral = Math.abs(relX * -uz + relZ * ux);
    const sameLaneToleranceM = Math.max(0.2, this.scenario.vehicles.widthM * 0.65);
    if (projection < -0.05 || lateral > sameLaneToleranceM) {
      return false;
    }

    const blockerDirection = this.vehicleMovementDirection(blocker);
    if (blockerDirection) {
      return blockerDirection.ux * ux + blockerDirection.uz * uz > 0.5;
    }

    return blocker.currentNodeId === blockedTargetNodeId && blocker.targetNodeId === null;
  }

  private agentRefreshBlockerIsClearingTarget(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (blocker.currentNodeId !== blockedTargetNodeId || blocker.currentEdgeId === null || !blocker.targetNodeId) {
      return false;
    }
    return blocker.targetNodeId !== vehicle.currentNodeId;
  }

  private tryRerouteLoadedInboundTopLaneFaceoff(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      !blocker.loaded ||
      task?.kind !== 'inbound' ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b' ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'top-b' ||
      topLiftAisleLevel(blocker.currentNodeId) !== 'top-b' ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0
    ) {
      return false;
    }

    const route = this.agentRefreshLoadedInboundRouteViaTopLane(vehicle.currentNodeId, task, true);
    const nextNodeId = route?.[1] ?? null;
    if (
      !route ||
      !nextNodeId ||
      nextNodeId === blockedTargetNodeId ||
      this.routeHasRepeatedNode(route) ||
      this.agentRefreshMoveBlocker(vehicle, nextNodeId, route)
    ) {
      return false;
    }

    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = nextNodeId;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'loaded-top-b-faceoff-top-a-bypass';
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    this.logAgentReroute(vehicle, task, blockedTargetNodeId, route, 'loaded-inbound-top-lane-faceoff-bypass', { countTaskReplan: false });
    return true;
  }

  private tryRerouteLoadedTopBFaceoffViaTopA(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      !blocker.loaded ||
      task === null ||
      task.kind === 'inbound' ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b' ||
      topLiftAisleLevel(blockedTargetNodeId) !== 'top-b' ||
      topLiftAisleLevel(blocker.currentNodeId) !== 'top-b' ||
      blocker.targetNodeId !== vehicle.currentNodeId ||
      vehicle.currentEdgeId !== null ||
      blocker.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      blocker.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      blocker.phaseRemainingSec > 0
    ) {
      return false;
    }

    const route = this.loadedTopBFaceoffBypassRoute(vehicle, blockedTargetNodeId, task);
    if (!route || route.length <= 1 || route[1] === blockedTargetNodeId) {
      return false;
    }
    if (this.agentRefreshMoveBlocker(vehicle, route[1]!, route)) {
      return false;
    }

    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.plannedGoalNodeId = route.at(-1) ?? null;
    vehicle.plannedRouteNodeIds = route;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'loaded-top-b-faceoff-top-a-bypass';
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    this.logAgentReroute(vehicle, task, blockedTargetNodeId, route, 'loaded-top-b-faceoff-top-a-bypass', { countTaskReplan: false });
    return true;
  }

  private loadedTopBFaceoffBypassRoute(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    task: TaskStateRecord
  ): string[] | null {
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const blockedColumn = this.topLiftColumnAccessColumn(blockedTargetNodeId);
    if (!currentColumn || !blockedColumn) {
      return null;
    }
    const direction = Math.sign(blockedColumn - currentColumn);
    if (direction !== -1 && direction !== 1) {
      return null;
    }

    const routeTail = this.vehicleRouteTailForMove(vehicle, blockedTargetNodeId);
    const minColumn = Math.min(...this.topLiftStorageColumnNumbers());
    const maxColumn = Math.max(...this.topLiftStorageColumnNumbers());
    const candidateExitColumns: number[] = [];
    for (
      let column = currentColumn + direction * 2;
      column >= minColumn && column <= maxColumn && candidateExitColumns.length < 5;
      column += direction
    ) {
      candidateExitColumns.push(column);
    }

    const candidateRoutes: string[][] = [];
    for (const exitColumn of candidateExitColumns) {
      const route = [vehicle.currentNodeId, columnAccessNodeId('top-a', currentColumn - 1)];
      for (let column = currentColumn + direction; direction > 0 ? column <= exitColumn : column >= exitColumn; column += direction) {
        route.push(columnAccessNodeId('top-a', column - 1));
      }
      const exitTopBNodeId = columnAccessNodeId('top-b', exitColumn - 1);
      route.push(exitTopBNodeId);

      const tailIndex = routeTail.indexOf(exitTopBNodeId);
      if (tailIndex >= 0) {
        route.push(...routeTail.slice(tailIndex + 1));
      } else {
        const goalNodeId = this.agentGoalNodeId(vehicle, task);
        if (!goalNodeId || goalNodeId === exitTopBNodeId) {
          continue;
        }
        try {
          const continuation = this.agentRefreshShortestPath(
            exitTopBNodeId,
            goalNodeId,
            this.agentRefreshBlockedNodeIds(vehicle, task, goalNodeId),
            this.routeTerminalAxis(route)
          );
          route.push(...continuation.slice(1));
        } catch {
          continue;
        }
      }

      if (
        !this.routeHasOnlyAdjacentEdges(route) ||
        route.slice(1).some((nodeId) => this.currentNodeOccupancy.get(nodeId) && this.currentNodeOccupancy.get(nodeId) !== vehicle.id) ||
        route.slice(1).some((nodeId) => this.nodeClaimedByOtherVehicle(nodeId, vehicle.id))
      ) {
        continue;
      }
      candidateRoutes.push(route);
    }

    return this.shortestRouteByDistance(candidateRoutes);
  }

  private vehicleMovementDirection(vehicle: MutableVehicle): { ux: number; uz: number } | null {
    const nextNodeId = vehicle.targetNodeId ?? vehicle.routeNodeIds[vehicle.routeIndex + 1] ?? null;
    if (!nextNodeId || nextNodeId === vehicle.currentNodeId) {
      return null;
    }
    const from = nodePosition(this.scenario, vehicle.currentNodeId);
    const to = nodePosition(this.scenario, nextNodeId);
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const length = Math.hypot(dx, dz);
    return length > 1e-9 ? { ux: dx / length, uz: dz / length } : null;
  }

  private installSideYieldWithReassignedConflictSession(
    session: ConflictSessionV1,
    winner: MutableVehicle,
    yielder: MutableVehicle,
    resumeNodeId: string | null
  ): boolean {
    const previousSessionState = {
      winnerVehicleId: session.winnerVehicleId,
      yielderVehicleId: session.yielderVehicleId,
      blockerVehicleId: session.blockerVehicleId,
      yielderOriginalNodeId: session.yielderOriginalNodeId,
      yielderPocketNodeId: session.yielderPocketNodeId,
      yielderLocalRouteNodeIds: [...session.yielderLocalRouteNodeIds],
      resumeNodeId: session.resumeNodeId,
      updatedAtSec: session.updatedAtSec,
      clearancePolicy: session.clearancePolicy
    };
    this.reassignAgentRefreshConflictSession(session, winner, yielder, resumeNodeId);
    if (this.agentRefreshInstallSideYield(yielder, resumeNodeId ?? yielder.targetNodeId ?? yielder.currentNodeId, winner, session, true)) {
      this.logEvent('conflict-session-reassigned', yielder.id, yielder.taskId, null, yielder.currentNodeId, resumeNodeId, 'actual-yielder-side-yield', this.vehiclePosition(yielder), {
        sessionId: session.id,
        winnerVehicleId: session.winnerVehicleId,
        yielderVehicleId: session.yielderVehicleId,
        blockerVehicleId: session.blockerVehicleId,
        resourceKey: session.resourceKey
      });
      return true;
    }

    session.winnerVehicleId = previousSessionState.winnerVehicleId;
    session.yielderVehicleId = previousSessionState.yielderVehicleId;
    session.blockerVehicleId = previousSessionState.blockerVehicleId;
    session.yielderOriginalNodeId = previousSessionState.yielderOriginalNodeId;
    session.yielderPocketNodeId = previousSessionState.yielderPocketNodeId;
    session.yielderLocalRouteNodeIds = previousSessionState.yielderLocalRouteNodeIds;
    session.resumeNodeId = previousSessionState.resumeNodeId;
    session.updatedAtSec = previousSessionState.updatedAtSec;
    session.clearancePolicy = previousSessionState.clearancePolicy;
    return false;
  }

  private reassignAgentRefreshConflictSession(
    session: ConflictSessionV1,
    winner: MutableVehicle,
    yielder: MutableVehicle,
    resumeNodeId: string | null
  ): void {
    session.winnerVehicleId = winner.id;
    session.yielderVehicleId = yielder.id;
    session.blockerVehicleId = winner.id;
    session.yielderOriginalNodeId = yielder.currentNodeId;
    session.yielderPocketNodeId = null;
    session.yielderLocalRouteNodeIds = [];
    session.resumeNodeId = resumeNodeId;
    session.updatedAtSec = this.simTimeSec;
    session.clearancePolicy = 'immediate-next-move';
    this.closeSupersededYieldSessions(yielder.id, session.id);
  }

  private agentRefreshHasHigherPriority(left: MutableVehicle, right: MutableVehicle): boolean {
    const leftPriority = this.agentTurnPriority(left);
    const rightPriority = this.agentTurnPriority(right);
    return leftPriority > rightPriority || (leftPriority === rightPriority && left.id.localeCompare(right.id) < 0);
  }

  private activeConflictSessions(): ConflictSessionV1[] {
    return this.conflictSessions
      .filter((session) => session.state !== 'cleared' && session.state !== 'timed-out')
      .map((session) => structuredClone(session));
  }

  private activeConflictSessionForVehicle(vehicleId: string): ConflictSessionV1 | null {
    for (let index = this.conflictSessions.length - 1; index >= 0; index -= 1) {
      const session = this.conflictSessions[index]!;
      if (
        session.state !== 'cleared' &&
        session.state !== 'timed-out' &&
        session.participantVehicleIds.includes(vehicleId)
      ) {
        return session;
      }
    }
    return null;
  }

  private activeYieldingConflictSessionForVehicle(vehicleId: string): ConflictSessionV1 | null {
    for (let index = this.conflictSessions.length - 1; index >= 0; index -= 1) {
      const session = this.conflictSessions[index]!;
      if (
        session.state !== 'cleared' &&
        session.state !== 'timed-out' &&
        session.yielderVehicleId === vehicleId
      ) {
        return session;
      }
    }
    return null;
  }

  private activeConflictSessionForPair(leftVehicleId: string, rightVehicleId: string): ConflictSessionV1 | null {
    for (let index = this.conflictSessions.length - 1; index >= 0; index -= 1) {
      const session = this.conflictSessions[index]!;
      if (
        session.state !== 'cleared' &&
        session.state !== 'timed-out' &&
        session.participantVehicleIds.includes(leftVehicleId) &&
        session.participantVehicleIds.includes(rightVehicleId)
      ) {
        return session;
      }
    }
    return null;
  }

  private updateConflictSessions(): void {
    for (const session of this.conflictSessions) {
      if (session.state === 'cleared' || session.state === 'timed-out') {
        continue;
      }
      const yielder = this.vehicles.find((vehicle) => vehicle.id === session.yielderVehicleId) ?? null;
      const winner = this.vehicles.find((vehicle) => vehicle.id === session.winnerVehicleId) ?? null;
      if (!yielder || !winner) {
        this.closeConflictSession(session, 'participant-missing');
        continue;
      }
      if (this.simTimeSec >= session.timeoutAtSec) {
        session.state = 'timed-out';
        session.updatedAtSec = this.simTimeSec;
        session.closeReason = 'timeout';
        this.logEvent('conflict-session-timed-out', yielder.id, yielder.taskId, null, yielder.currentNodeId, yielder.targetNodeId, 'timeout', this.vehiclePosition(yielder), {
          sessionId: session.id,
          winnerVehicleId: session.winnerVehicleId,
          yielderVehicleId: session.yielderVehicleId
        });
        continue;
      }
      if (
        session.yielderPocketNodeId &&
        yielder.currentNodeId === session.yielderPocketNodeId &&
        yielder.currentEdgeId === null &&
        yielder.legRemainingM <= 0 &&
        session.state === 'yielding'
      ) {
        session.state = 'holding-pocket';
        session.updatedAtSec = this.simTimeSec;
      }
      if (
        session.state === 'holding-pocket' &&
        yielder.currentNodeId !== session.yielderPocketNodeId
      ) {
        session.state = 'returning';
        session.updatedAtSec = this.simTimeSec;
      }
      if (
        session.state === 'returning' &&
        (yielder.currentEdgeId !== null || yielder.waitReason === null) &&
        this.simTimeSec > session.updatedAtSec + this.scenario.timeStepSec
      ) {
        this.closeConflictSession(session, 'yielder-returning');
      }
      if (this.simTimeSec >= session.expiresAtSec) {
        this.closeConflictSession(session, 'expired');
      }
    }

    if (this.conflictSessions.length > 400) {
      this.conflictSessions = this.conflictSessions.slice(-300);
    }
  }

  private closeConflictSession(session: ConflictSessionV1, reason: string): void {
    if (session.state === 'cleared' || session.state === 'timed-out') {
      return;
    }
    session.state = 'cleared';
    session.updatedAtSec = this.simTimeSec;
    session.closeReason = reason;
    this.logEvent('conflict-session-closed', session.yielderVehicleId, null, null, session.yielderPocketNodeId, session.resumeNodeId, reason, null, {
      sessionId: session.id,
      winnerVehicleId: session.winnerVehicleId,
      yielderVehicleId: session.yielderVehicleId
    });
  }

  private closeSupersededYieldSessions(vehicleId: string, activeSessionId: string): void {
    for (const session of this.conflictSessions) {
      if (
        session.id !== activeSessionId &&
        session.state !== 'cleared' &&
        session.state !== 'timed-out' &&
        session.yielderVehicleId === vehicleId
      ) {
        this.closeConflictSession(session, 'superseded-yield');
      }
    }
  }

  private createAgentRefreshConflictSession(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string,
    reason: string
  ): ConflictSessionV1 {
    const nodeClearingBlockerWins = reason === 'node-clearing' && blocker.currentEdgeId !== null;
    const requesterQueueClearer = this.topLiftInboundQueueClearingVehicle(requester);
    const blockerQueueClearer = this.topLiftInboundQueueClearingVehicle(blocker);
    const winner = nodeClearingBlockerWins
      ? blocker
      : requesterQueueClearer !== blockerQueueClearer
        ? requesterQueueClearer ? requester : blocker
        : this.agentRefreshHasHigherPriority(requester, blocker) ? requester : blocker;
    const yielder = winner.id === requester.id ? blocker : requester;
    const participantVehicleIds = [requester.id, blocker.id].sort((left, right) => left.localeCompare(right));
    const resourceKey = this.agentRefreshConflictResourceKey(requester, blocker, blockedTargetNodeId, reason);
    const existing = this.conflictSessions.find((session) =>
      session.state !== 'cleared' &&
      session.state !== 'timed-out' &&
      session.resourceKey === resourceKey
    );
    if (existing) {
      existing.updatedAtSec = this.simTimeSec;
      return existing;
    }

    const session: ConflictSessionV1 = {
      id: `conflict-${String(this.conflictSessions.length + 1).padStart(5, '0')}`,
      kind: 'pair',
      resourceKey,
      state: 'open',
      participantVehicleIds,
      winnerVehicleId: winner.id,
      yielderVehicleId: yielder.id,
      createdAtSec: this.simTimeSec,
      createdAtTick: this.tickIndex,
      updatedAtSec: this.simTimeSec,
      expiresAtSec: round(this.simTimeSec + 20),
      timeoutAtSec: round(this.simTimeSec + 12),
      trigger: this.agentRefreshConflictTrigger(reason),
      initialBlockerVehicleId: blocker.id,
      blockerVehicleId: winner.id,
      yielderOriginalNodeId: yielder.currentNodeId,
      yielderPocketNodeId: null,
      yielderLocalRouteNodeIds: [],
      resumeNodeId: blockedTargetNodeId,
      clearancePolicy: 'immediate-next-move',
      closeReason: null
    };
    this.conflictSessions.push(session);
    this.closeSupersededYieldSessions(yielder.id, session.id);
    this.logEvent('conflict-session-opened', yielder.id, yielder.taskId, null, yielder.currentNodeId, blockedTargetNodeId, reason, this.vehiclePosition(yielder), {
      sessionId: session.id,
      winnerVehicleId: session.winnerVehicleId,
      yielderVehicleId: session.yielderVehicleId,
      blockerVehicleId: session.blockerVehicleId,
      resourceKey: session.resourceKey
    });
    return session;
  }

  private agentRefreshConflictResourceKey(
    requester: MutableVehicle,
    blocker: MutableVehicle,
    blockedTargetNodeId: string,
    reason: string
  ): string {
    const pairKey = [requester.id, blocker.id].sort((left, right) => left.localeCompare(right)).join('+');
    if (reason === 'node-occupied' || reason === 'node-target-near') {
      return `node:${blockedTargetNodeId}:${pairKey}`;
    }
    const edge = this.traffic.findEdge(requester.currentNodeId, blockedTargetNodeId);
    if (edge) {
      return `edge:${edge.id}:${pairKey}`;
    }
    return `${reason}:${blockedTargetNodeId}:${pairKey}`;
  }

  private agentRefreshConflictTrigger(reason: string): ConflictSessionV1['trigger'] {
    if (reason === 'edge-head-on') return 'head-on';
    if (reason === 'node-occupied' || reason === 'node-target-near') return 'same-node';
    if (reason === 'lift-column-near') return 'column-exit';
    if (reason === 'avoidance-clearance' || reason === 'min-separation') return 'swept-footprint';
    return 'deadlock-break';
  }

  private agentRefreshInstallSideYield(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    requester: MutableVehicle,
    session: ConflictSessionV1 | null = null,
    reassignedYield = false
  ): boolean {
    if (this.topLiftFifoHeldVehicle(vehicle) || this.topLiftFifoHeldVehicle(requester)) {
      return false;
    }
    if (
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.state === 'lifting' ||
      vehicle.state === 'lowering'
    ) {
      return false;
    }
    if (this.topLiftLoadedOutboundQueueShouldHoldLine(vehicle)) {
      return false;
    }
    if (this.topLiftTopBToTopAClearingMove(vehicle)) {
      return false;
    }
    if (this.topLiftMainAisleBlockedVehicleShouldHoldLine(vehicle, blockedTargetNodeId)) {
      return false;
    }

    const currentNodeId = vehicle.currentNodeId;
    const inboundServiceExitRoute = this.topLiftInboundServiceExitSideYieldRoute(currentNodeId);
    if (
      inboundServiceExitRoute &&
      this.agentRefreshSideYieldRouteCompatibleWithRequester(vehicle, inboundServiceExitRoute, requester, blockedTargetNodeId) &&
      this.agentRefreshLocalRouteNodesClear(vehicle, inboundServiceExitRoute)
    ) {
      return this.installAgentRefreshSideYieldRoute(vehicle, requester, blockedTargetNodeId, inboundServiceExitRoute, session);
    }
    if (this.topLiftInboundPickupApproachShouldHoldLine(vehicle)) {
      return false;
    }
    const forbiddenNodeIds = new Set<string>([currentNodeId, blockedTargetNodeId, requester.currentNodeId]);
    const previousNodeId = vehicle.routeNodeIds[vehicle.routeIndex - 1];
    const stagedInboundQueueVehicle =
      !vehicle.loaded &&
      vehicle.plannedGoalNodeId !== null &&
      topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) !== null;
    const allowShortSpineRetreat =
      previousNodeId &&
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      !stagedInboundQueueVehicle &&
      this.topLiftColumnSpineOrAccessNode(currentNodeId) &&
      this.topLiftColumnSpineOrAccessNode(blockedTargetNodeId);
    if (previousNodeId && !allowShortSpineRetreat) {
      forbiddenNodeIds.add(previousNodeId);
    }
    if (requester.targetNodeId) {
      forbiddenNodeIds.add(requester.targetNodeId);
    }
    const requesterContinuationNodeId = this.agentRouteNodeAfter(requester, blockedTargetNodeId);
    if (requesterContinuationNodeId) {
      forbiddenNodeIds.add(requesterContinuationNodeId);
    }
    for (const nodeId of this.agentRefreshRequesterProtectedRouteNodeIds(requester)) {
      forbiddenNodeIds.add(nodeId);
    }
    for (const nodeId of this.topLiftOutboundClearanceProtectedRouteNodeIds(requester)) {
      forbiddenNodeIds.add(nodeId);
    }
    for (const nodeId of this.agentRefreshLoadedRequesterProtectedRouteNodeIds(requester)) {
      forbiddenNodeIds.add(nodeId);
    }
    for (const nodeId of this.agentRefreshLoadedTrafficProtectedRouteNodeIds(vehicle)) {
      forbiddenNodeIds.add(nodeId);
    }

    const bottomBLoadedIngressYieldAllowed = (nodeId: string) =>
      this.topLiftEmptyBottomBLoadedIngressYieldAllowed(vehicle, nodeId, requester, blockedTargetNodeId);
    const outboundClearanceSameLaneYieldPreferred = (nodeId: string) =>
      this.topLiftTasklessOutboundClearanceSameLaneYieldPreferred(vehicle, nodeId);
    const candidate = this.neighbors(currentNodeId)
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) =>
        bottomBLoadedIngressYieldAllowed(neighbor.nodeId) ||
        outboundClearanceSameLaneYieldPreferred(neighbor.nodeId) ||
        !this.topLiftEmptyOutboundFaceSideYieldForbidden(vehicle, currentNodeId, blockedTargetNodeId, neighbor.nodeId)
      )
      .filter((neighbor) =>
        bottomBLoadedIngressYieldAllowed(neighbor.nodeId) ||
        outboundClearanceSameLaneYieldPreferred(neighbor.nodeId) ||
        this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId)
      )
      .filter((neighbor) =>
        this.topLiftEmptyTemporaryYieldNodeAllowed(vehicle, neighbor.nodeId) ||
        bottomBLoadedIngressYieldAllowed(neighbor.nodeId) ||
        outboundClearanceSameLaneYieldPreferred(neighbor.nodeId)
      )
      .filter((neighbor) => !this.topLiftInboundQueueStagingTopAYieldForbidden(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, neighbor.nodeId, requester))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(vehicle, neighbor.nodeId, blockedTargetNodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketMovesAwayFromBlockedTransfer(vehicle, neighbor.nodeId, blockedTargetNodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, [currentNodeId, neighbor.nodeId]))
      .sort((left, right) =>
        this.topLiftMiddleAisleTaskYieldSurfaceRank(vehicle, currentNodeId, blockedTargetNodeId, left.nodeId) -
        this.topLiftMiddleAisleTaskYieldSurfaceRank(vehicle, currentNodeId, blockedTargetNodeId, right.nodeId) ||
        this.agentRefreshYieldPocketRank(vehicle, left.nodeId) - this.agentRefreshYieldPocketRank(vehicle, right.nodeId) ||
        this.agentRefreshYieldPocketDirectionScore(vehicle, left.nodeId, blockedTargetNodeId) - this.agentRefreshYieldPocketDirectionScore(vehicle, right.nodeId, blockedTargetNodeId) ||
        this.agentRefreshYieldPocketTieBreak(vehicle, left.nodeId) - this.agentRefreshYieldPocketTieBreak(vehicle, right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0];

    const selectedCandidate = candidate ?? this.agentRefreshTransferBypassCandidate(
      vehicle,
      currentNodeId,
      forbiddenNodeIds
    ) ?? this.agentRefreshAdjacentTransferBypassCandidate(
      vehicle,
      currentNodeId,
      forbiddenNodeIds
    );
    if (!selectedCandidate) {
      return false;
    }
    const selectedBottomBLoadedIngressYield = bottomBLoadedIngressYieldAllowed(selectedCandidate.nodeId);
    const selectedOutboundClearanceSameLaneYield = outboundClearanceSameLaneYieldPreferred(selectedCandidate.nodeId);
    if (
      !selectedBottomBLoadedIngressYield &&
      !selectedOutboundClearanceSameLaneYield &&
      this.topLiftEmptyOutboundFaceSideYieldForbidden(vehicle, currentNodeId, blockedTargetNodeId, selectedCandidate.nodeId)
    ) {
      return false;
    }
    if (
      !this.topLiftEmptyTemporaryYieldNodeAllowed(vehicle, selectedCandidate.nodeId) &&
      !selectedBottomBLoadedIngressYield &&
      !selectedOutboundClearanceSameLaneYield
    ) {
      return false;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      this.isStorageNode(currentNodeId) &&
      this.isStorageNode(selectedCandidate.nodeId)
    ) {
      return false;
    }

    const queueContinuationNodeId = this.topLiftQueueSideYieldContinuationNodeId(
      vehicle,
      currentNodeId,
      selectedCandidate.nodeId
    );
    const continuationNodeId = queueContinuationNodeId ?? this.topLiftEmptySideYieldContinuationNodeId(
      vehicle,
      currentNodeId,
      selectedCandidate.nodeId,
      blockedTargetNodeId
    );
    const route = continuationNodeId
      ? [currentNodeId, selectedCandidate.nodeId, continuationNodeId]
      : [currentNodeId, selectedCandidate.nodeId];
    const holdRoute = selectedBottomBLoadedIngressYield
      ? route
      : this.extendTopLiftTemporaryYieldRouteToHold(
        vehicle,
        route,
        new Set([blockedTargetNodeId, requester.currentNodeId])
      );
    if (!holdRoute) {
      return false;
    }
    if (this.topLiftTaskVehicleSideYieldRouteUsesDisallowedStorage(vehicle, holdRoute)) {
      return false;
    }
    if (!this.agentRefreshSideYieldRouteCompatibleWithRequester(vehicle, holdRoute, requester, blockedTargetNodeId)) {
      return false;
    }
    if (reassignedYield && !this.agentRefreshReassignedSideYieldRouteAllowed(holdRoute)) {
      return false;
    }
    if (previousNodeId && holdRoute.includes(previousNodeId) && holdRoute.length > 2) {
      return false;
    }
    if (this.topLiftRouteEntersProtectedInboundQueueExit(holdRoute, requester)) {
      return false;
    }
    if (
      !selectedBottomBLoadedIngressYield &&
      !selectedOutboundClearanceSameLaneYield &&
      holdRoute.some((nodeId) =>
        this.topLiftEmptyOutboundFaceSideYieldForbidden(vehicle, currentNodeId, blockedTargetNodeId, nodeId)
      )
    ) {
      return false;
    }
    if (this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, holdRoute)) {
      return false;
    }
    return this.installAgentRefreshSideYieldRoute(vehicle, requester, blockedTargetNodeId, holdRoute, session);
  }

  private agentRefreshSideYieldRouteCompatibleWithRequester(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    if (routeNodeIds.length < 2 || routeNodeIds[0] !== vehicle.currentNodeId) {
      return false;
    }
    const explicitlyProtectedNodeIds = new Set(
      [
        requester.currentNodeId,
        requester.targetNodeId,
        blockedTargetNodeId,
        ...this.agentRefreshRequesterProtectedRouteNodeIds(requester),
        ...this.topLiftOutboundClearanceProtectedRouteNodeIds(requester),
        ...this.agentRefreshLoadedRequesterProtectedRouteNodeIds(requester),
        ...this.topLiftLoadedInboundServiceAccessConflictNodeIds(requester)
      ].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    return routeNodeIds.slice(1).every((nodeId) =>
      !explicitlyProtectedNodeIds.has(nodeId) &&
      this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, nodeId, requester)
    );
  }

  private agentRefreshReassignedSideYieldRouteAllowed(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    if (routeNodeIds.length !== 2) {
      return false;
    }
    const terminalNode = this.layoutNode(routeNodeIds[1]!);
    return Boolean(terminalNode && !terminalNode.noStop && !terminalNode.noParking);
  }

  private topLiftEmptyOutboundFaceSideYieldForbidden(
    vehicle: MutableVehicle,
    currentNodeId: string,
    blockedTargetNodeId: string,
    candidateNodeId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return false;
    }
    if (this.topLiftTasklessOutboundClearanceSameLaneYieldPreferred(vehicle, candidateNodeId)) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task && task.kind !== 'inbound') {
      return false;
    }
    const keepoutNodeIds = this.topLiftOutboundFaceKeepoutNodeIds();
    if (keepoutNodeIds.has(candidateNodeId)) {
      return true;
    }
    return this.isStorageNode(candidateNodeId) &&
      (keepoutNodeIds.has(currentNodeId) || keepoutNodeIds.has(blockedTargetNodeId));
  }

  private topLiftTasklessOutboundClearanceSameLaneYieldPreferred(vehicle: MutableVehicle, candidateNodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.taskId ||
      vehicle.localRouteReason !== 'outbound-lift-clearance' ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-b') ||
      !isTopLiftAisleLevelNodeId(candidateNodeId, 'bottom-b')
    ) {
      return false;
    }
    const liftNodeId = this.outboundLiftNodeIdFromClearanceRoute(vehicle.plannedRouteNodeIds) ??
      this.outboundLiftNodeIdFromClearanceRoute(vehicle.routeNodeIds);
    if (!liftNodeId) {
      return false;
    }
    return this.topLiftOutboundClearanceDirections(liftNodeId, vehicle.currentNodeId).some((direction) =>
      this.nextTopLiftRailNodeAlongDirection(vehicle.currentNodeId, 'bottom-b', direction, vehicle.id) === candidateNodeId
    );
  }

  private extendTopLiftTemporaryYieldRouteToHold(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    forbiddenNodeIds = new Set<string>()
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || routeNodeIds.length < 2) {
      return routeNodeIds;
    }
    const terminalNodeId = routeNodeIds.at(-1)!;
    const terminalNode = this.layoutNode(terminalNodeId);
    if (!terminalNode?.noStop && !terminalNode?.noParking) {
      return routeNodeIds;
    }
    if (vehicle.loaded) {
      return null;
    }
    if (
      !this.topLiftNoStopContinuationRouteEndsOnForbiddenHold(vehicle, routeNodeIds) &&
      this.topLiftTemporaryColumnAccessYieldHoldAllowed(vehicle, routeNodeIds, forbiddenNodeIds)
    ) {
      return routeNodeIds;
    }

    const queue: string[][] = [routeNodeIds];
    const visited = new Set(routeNodeIds);
    const maxRouteNodes = routeNodeIds.length + 8;
    while (queue.length > 0) {
      const route = queue.shift()!;
      const currentNodeId = route.at(-1)!;
      if (route.length >= maxRouteNodes) {
        continue;
      }
      for (const neighbor of this.neighbors(currentNodeId)) {
        if (
          neighbor.nodeId === vehicle.currentNodeId ||
          forbiddenNodeIds.has(neighbor.nodeId) ||
          visited.has(neighbor.nodeId) ||
          route.includes(neighbor.nodeId)
        ) {
          continue;
        }
        const node = this.layoutNode(neighbor.nodeId);
        if (!node || node.type === 'lift-blackbox') {
          continue;
        }
        if (!this.topLiftEmptyTemporaryYieldNodeAllowed(vehicle, neighbor.nodeId)) {
          continue;
        }
        const occupantId = this.currentNodeOccupancy.get(neighbor.nodeId);
        if (occupantId && occupantId !== vehicle.id) {
          continue;
        }
        if (this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id)) {
          continue;
        }
        if (node.type === 'storage' && !this.topLiftTemporaryYieldStorageHoldAllowed(vehicle, neighbor.nodeId)) {
          continue;
        }
        const candidateRoute = [...route, neighbor.nodeId];
        if (!this.routeHasOnlyAdjacentEdges(candidateRoute)) {
          continue;
        }
        if (this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, candidateRoute)) {
          continue;
        }
        if (!node.noStop && !node.noParking && (node.type === 'storage' || node.type === 'aisle')) {
          return candidateRoute;
        }
        if (this.topLiftColumnSpineOrAccessNode(neighbor.nodeId)) {
          visited.add(neighbor.nodeId);
          queue.push(candidateRoute);
        }
      }
    }

    return null;
  }

  private topLiftTemporaryColumnAccessYieldHoldAllowed(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    forbiddenNodeIds = new Set<string>()
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      routeNodeIds.length !== 2
    ) {
      return false;
    }
    const fromNodeId = routeNodeIds[0]!;
    const terminalNodeId = routeNodeIds[1]!;
    if (
      fromNodeId === terminalNodeId ||
      forbiddenNodeIds.has(terminalNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(fromNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(terminalNodeId)
    ) {
      return false;
    }

    const topBSpineSideStep =
      isTopLiftSpineLevelNodeId(fromNodeId, 'top-b') &&
      isTopLiftAisleLevelNodeId(terminalNodeId, 'top-b') &&
      this.traffic.findEdge(fromNodeId, terminalNodeId) !== null;
    if (!topBSpineSideStep && !this.topLiftDoubleAisleOppositeLaneNode(fromNodeId, terminalNodeId)) {
      return false;
    }

    const terminalNode = this.layoutNode(terminalNodeId);
    if (!terminalNode || terminalNode.type === 'lift-blackbox') {
      return false;
    }
    if (!this.topLiftEmptyTemporaryYieldNodeAllowed(vehicle, terminalNodeId)) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(terminalNodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    if (this.nodeClaimedByOtherVehicle(terminalNodeId, vehicle.id)) {
      return false;
    }
    return this.routeHasOnlyAdjacentEdges(routeNodeIds) &&
      !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, routeNodeIds);
  }

  private topLiftDoubleAisleOppositeLaneNode(fromNodeId: string, toNodeId: string): boolean {
    const fromLevel = topLiftAisleLevel(fromNodeId);
    const toLevel = topLiftAisleLevel(toNodeId);
    const sameDoubleLane =
      (fromLevel === 'top-a' && toLevel === 'top-b') ||
      (fromLevel === 'top-b' && toLevel === 'top-a') ||
      (fromLevel === 'bottom-a' && toLevel === 'bottom-b') ||
      (fromLevel === 'bottom-b' && toLevel === 'bottom-a');
    if (!sameDoubleLane || !this.traffic.findEdge(fromNodeId, toNodeId)) {
      return false;
    }
    const fromPosition = nodePosition(this.scenario, fromNodeId);
    const toPosition = nodePosition(this.scenario, toNodeId);
    return Math.abs(fromPosition.x - toPosition.x) <= 0.01;
  }

  private topLiftInboundServiceExitSideYieldRoute(currentNodeId: string): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const serviceSlot = topLiftQueueServiceSlot(currentNodeId);
    if (!serviceSlot || this.liftPortKindForNodeId(serviceSlot.liftNodeId) !== 'inbound') {
      return null;
    }
    const finalSlotIndex = 3;
    const serviceExitTail = Array.from({ length: finalSlotIndex - serviceSlot.slotIndex }, (_, index) =>
      liftQueueServiceExitNodeId(serviceSlot.liftNodeId, serviceSlot.slotIndex + index + 1)
    );
    const finalEntryNodeId = liftQueueTailEntryNodeId(serviceSlot.liftNodeId, finalSlotIndex);
    const exitBottomNodeId = this.topLiftQueueEntryBottomAccessNodeId(finalEntryNodeId);
    const route = [
      currentNodeId,
      ...serviceExitTail,
      finalEntryNodeId,
      exitBottomNodeId
    ].filter((nodeId): nodeId is string => Boolean(nodeId));
    return this.enforceTopLiftWorkcellRouteContract(
      route.length > 1 && this.routeEdgesExist(route) ? route : null,
      'inbound-loaded-departure',
      serviceSlot.liftNodeId,
      'inbound'
    );
  }

  private installAgentRefreshSideYieldRoute(
    vehicle: MutableVehicle,
    _requester: MutableVehicle,
    blockedTargetNodeId: string,
    route: string[],
    session: ConflictSessionV1 | null
  ): boolean {
    const targetNodeId = route[1] ?? null;
    if (!targetNodeId) {
      return false;
    }
    if (this.topLiftNoStopContinuationRouteEndsOnForbiddenHold(vehicle, route)) {
      return false;
    }
    if (this.topLiftTaskVehicleMainSpineStorageYieldForbidden(vehicle, blockedTargetNodeId, route)) {
      return false;
    }
    if (this.topLiftTaskVehicleSideYieldRouteUsesDisallowedStorage(vehicle, route)) {
      return false;
    }
    const yieldHoldNodeId = route[route.length - 1]!;
    if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, route)) {
      this.updateAgentRefreshSideYieldSession(vehicle, blockedTargetNodeId, route, session);
      return false;
    }
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = targetNodeId;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'assigned' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, route) + 2);
    vehicle.yieldHoldNodeId = yieldHoldNodeId;
    vehicle.localRouteNodeIds = route;
    vehicle.localRouteReason = 'temporary-yield';
    this.updateAgentRefreshSideYieldSession(vehicle, blockedTargetNodeId, route, session);
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blockedTargetNodeId, route, 'agent-refresh-side-yield', { countTaskReplan: false });
    return true;
  }

  private topLiftNoStopContinuationRouteEndsOnForbiddenHold(
    vehicle: MutableVehicle,
    routeNodeIds: string[]
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.waitReason !== 'no-stop-continuation-blocked' ||
      routeNodeIds.length < 2
    ) {
      return false;
    }
    const holdNode = this.layoutNode(routeNodeIds.at(-1)!);
    return holdNode?.noStop === true || holdNode?.noParking === true;
  }

  private topLiftTaskVehicleMainSpineStorageYieldForbidden(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    routeNodeIds: string[]
  ): boolean {
    return this.topLiftTaskVehicleMainSpineShouldHoldLine(vehicle, blockedTargetNodeId) &&
      routeNodeIds.slice(1).some((nodeId) =>
        this.isStorageNode(nodeId) &&
        !this.topLiftNoStopBottomASpineTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId)
      );
  }

  private updateAgentRefreshSideYieldSession(
    vehicle: MutableVehicle,
    blockedTargetNodeId: string,
    route: string[],
    session: ConflictSessionV1 | null
  ): void {
    if (!session) {
      return;
    }
    session.state = 'yielding';
    session.updatedAtSec = this.simTimeSec;
    session.yielderPocketNodeId = route[route.length - 1]!;
    session.yielderLocalRouteNodeIds = route;
    session.resumeNodeId = blockedTargetNodeId;
    session.clearancePolicy = 'immediate-next-move';
    this.closeSupersededYieldSessions(vehicle.id, session.id);
  }

  private topLiftLoadedOutboundQueueShouldHoldLine(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.loaded) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'outbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return false;
    }
    return [vehicle.currentNodeId, vehicle.targetNodeId, vehicle.plannedGoalNodeId]
      .some((nodeId) => nodeId !== null && this.topLiftNodeBelongsToLiftQueueOrService(nodeId, liftNodeId));
  }

  private topLiftTopBToTopAClearingMove(vehicle: MutableVehicle, targetNodeId: string | null = vehicle.targetNodeId): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !targetNodeId) {
      return false;
    }
    return topLiftAisleLevel(vehicle.currentNodeId) === 'top-b' &&
      topLiftAisleLevel(targetNodeId) === 'top-a' &&
      this.topLiftColumnAccessColumn(vehicle.currentNodeId) === this.topLiftColumnAccessColumn(targetNodeId) &&
      this.traffic.findEdge(vehicle.currentNodeId, targetNodeId) !== undefined;
  }

  private topLiftTopBToTopAClearingEntryBlockerAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (!this.topLiftTopBToTopAClearingMove(vehicle, toNodeId)) {
      return false;
    }
    if (!blocker.loaded || blocker.targetNodeId !== vehicle.currentNodeId) {
      return false;
    }
    const blockerWaitingAtEntry =
      blocker.currentEdgeId === null &&
      blocker.legRemainingM <= 0 &&
      blocker.phaseRemainingSec <= 0;
    const blockerStoppedOnEntryApproach =
      blocker.currentEdgeId !== null &&
      blocker.state === 'waiting-blocked' &&
      blocker.speedMps <= 0 &&
      blocker.blockingVehicleId === vehicle.id;
    if (!blockerWaitingAtEntry && !blockerStoppedOnEntryApproach) {
      return false;
    }
    const blockerTask = this.taskForVehicle(blocker);
    if (blockerTask?.kind !== 'inbound') {
      return false;
    }
    const entrySlot = topLiftQueueEntrySlot(blocker.currentNodeId);
    return Boolean(entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'inbound');
  }

  private topLiftInboundQueueExitClearingEntryBlockerAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (vehicle.loaded || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const protectedTargetNodeId = this.topLiftProtectedInboundQueueExitTargetNodeId(blocker);
    if (protectedTargetNodeId !== vehicle.currentNodeId) {
      return false;
    }
    if (topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b' || topLiftAisleLevel(toNodeId) !== 'top-b') {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const targetColumn = this.topLiftColumnAccessColumn(toNodeId);
    if (currentColumn === null || targetColumn === null || currentColumn === targetColumn) {
      return false;
    }
    const edge = this.traffic.findEdge(vehicle.currentNodeId, toNodeId);
    if (!edge) {
      return false;
    }
    const blockerStoppedAtEntry =
      blocker.currentEdgeId === null &&
      blocker.legRemainingM <= 0 &&
      blocker.phaseRemainingSec <= 0;
    const blockerStoppedOnEntryApproach =
      blocker.currentEdgeId !== null &&
      blocker.state === 'waiting-blocked' &&
      blocker.speedMps <= 0 &&
      blocker.blockingVehicleId === vehicle.id;
    return blockerStoppedAtEntry || blockerStoppedOnEntryApproach;
  }

  private topLiftNodeBelongsToLiftQueueOrService(nodeId: string, liftNodeId: string): boolean {
    if (
      nodeId === this.topLiftInboundPickupStopNodeId(liftNodeId) ||
      nodeId === this.topLiftOutboundDropoffStopNodeId(liftNodeId)
    ) {
      return true;
    }
    const queueSlot = topLiftQueueParkingSlot(nodeId);
    if (queueSlot?.liftNodeId === liftNodeId) {
      return true;
    }
    const buffer = liftBufferParentNodeId(nodeId);
    if (buffer?.liftNodeId === liftNodeId) {
      return true;
    }
    if (nodeId === liftBufferAccessNodeId(liftNodeId)) {
      return true;
    }
    return nodeId.startsWith(`${liftNodeId}-queue-`);
  }

  private agentRefreshLoadedRequesterProtectedRouteNodeIds(requester: MutableVehicle): string[] {
    if (!this.topLiftColumnLayoutEnabled() || !requester.loaded) {
      return [];
    }
    const task = this.taskForVehicle(requester);
    if (task?.kind !== 'inbound') {
      return [];
    }

    const route = requester.routeNodeIds.length > 1 ? requester.routeNodeIds : requester.plannedRouteNodeIds;
    const currentIndex = route.indexOf(requester.currentNodeId, Math.max(0, requester.routeIndex));
    const startIndex = currentIndex >= 0 ? currentIndex : Math.max(0, requester.routeIndex);
    const dropoffIndex = route.indexOf(task.dropoffNodeId, startIndex);
    const endIndex = dropoffIndex >= 0 ? dropoffIndex : Math.min(route.length - 1, startIndex + 6);
    return route.slice(startIndex + 1, endIndex + 1);
  }

  private agentRefreshRequesterProtectedRouteNodeIds(requester: MutableVehicle): string[] {
    if (!this.topLiftColumnLayoutEnabled()) {
      return [];
    }

    const task = this.taskForVehicle(requester);
    const goalNodeId = task
      ? requester.loaded ? task.dropoffNodeId : task.pickupNodeId
      : requester.plannedGoalNodeId;
    const routeOptions = [
      this.vehicleRouteTail(requester, requester.routeNodeIds),
      this.vehicleRouteTail(requester, requester.plannedRouteNodeIds),
      [requester.currentNodeId, requester.targetNodeId].filter((nodeId): nodeId is string => nodeId !== null)
    ].filter((route) => route.length > 1);
    let route = goalNodeId
      ? routeOptions.find((candidate) => candidate.includes(goalNodeId)) ?? routeOptions[0]
      : routeOptions[0];
    if (!route) {
      return [];
    }
    if (goalNodeId && !route.includes(goalNodeId)) {
      const extensionStartNodeId = route.at(-1) ?? requester.currentNodeId;
      try {
        const extension = this.agentRefreshShortestPath(extensionStartNodeId, goalNodeId);
        route = [...route, ...extension.slice(1)];
      } catch {
        // Keep the visible route tail when the full goal route is not currently reachable.
      }
    }

    const goalIndex = goalNodeId ? route.indexOf(goalNodeId) : -1;
    const endIndex = goalIndex >= 1 ? goalIndex : Math.min(route.length - 1, 8);
    return route.slice(1, endIndex + 1);
  }

  private agentRefreshLoadedTrafficProtectedRouteNodeIds(yielder: MutableVehicle): string[] {
    if (!this.topLiftColumnLayoutEnabled() || yielder.loaded) {
      return [];
    }

    const protectedNodeIds: string[] = [];
    const seen = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (vehicle.id === yielder.id || !vehicle.loaded) {
        continue;
      }
      for (const nodeId of this.agentRefreshLoadedRequesterProtectedRouteNodeIds(vehicle)) {
        if (!seen.has(nodeId)) {
          seen.add(nodeId);
          protectedNodeIds.push(nodeId);
        }
      }
    }
    return protectedNodeIds;
  }

  private agentRefreshMoveQueueYielderDeeper(
    yielder: MutableVehicle,
    session: ConflictSessionV1,
    winner: MutableVehicle,
    resumeNodeId: string
  ): boolean {
    const currentSlot =
      topLiftQueueParkingSlot(yielder.currentNodeId) ??
      topLiftQueueAisleAccess(yielder.currentNodeId);
    const resumeBuffer = liftBufferParentNodeId(resumeNodeId);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      session.winnerVehicleId !== winner.id ||
      session.yielderVehicleId !== yielder.id ||
      (
        !isTopLiftColumnAccessNodeId(resumeNodeId) &&
        (!currentSlot || resumeBuffer?.liftNodeId !== currentSlot.liftNodeId)
      ) ||
      yielder.loaded ||
      yielder.currentEdgeId !== null ||
      yielder.legRemainingM > 0 ||
      yielder.phaseRemainingSec > 0
    ) {
      return false;
    }

    if (!currentSlot) {
      return false;
    }
    const deeperNodeId = liftQueueNodeId(currentSlot.liftNodeId, currentSlot.slotIndex + 1);
    if (!this.layoutNode(deeperNodeId) || !isTopLiftQueueParkingNodeId(deeperNodeId)) {
      return false;
    }
    if (
      this.currentNodeOccupancy.get(deeperNodeId) ||
      this.nodeClaimedByOtherVehicle(deeperNodeId, yielder.id)
    ) {
      return false;
    }

    const blockedNodeIds = new Set<string>();
    for (const [nodeId, occupantId] of this.currentNodeOccupancy) {
      if (occupantId !== yielder.id && nodeId !== deeperNodeId) {
        blockedNodeIds.add(nodeId);
      }
    }
    let route: string[];
    try {
      route = this.agentRefreshShortestPath(yielder.currentNodeId, deeperNodeId, blockedNodeIds);
    } catch {
      return false;
    }
    const nextNodeId = route[1];
    if (
      !nextNodeId ||
      route.at(-1) !== deeperNodeId ||
      !this.agentMinimalYieldFirstLegSafe(yielder, yielder.currentNodeId, nextNodeId) ||
      route.slice(1).some((nodeId) => nodeId !== deeperNodeId && this.nodeClaimedByOtherVehicle(nodeId, yielder.id))
    ) {
      return false;
    }

    yielder.routeNodeIds = route;
    yielder.routeIndex = 0;
    yielder.targetNodeId = nextNodeId;
    yielder.state = yielder.taskId ? 'assigned' : 'returning';
    yielder.waitReason = null;
    yielder.blockingReservationId = null;
    yielder.blockingVehicleId = null;
    yielder.waitingSinceSec = null;
    yielder.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(yielder, route) + 8);
    yielder.yieldHoldNodeId = deeperNodeId;
    yielder.localRouteNodeIds = route;
    yielder.localRouteReason = 'temporary-yield';
    session.state = 'yielding';
    session.updatedAtSec = this.simTimeSec;
    session.yielderPocketNodeId = deeperNodeId;
    session.yielderLocalRouteNodeIds = route;
    session.resumeNodeId = resumeNodeId;
    session.timeoutAtSec = Math.max(session.timeoutAtSec, round(this.simTimeSec + 18));
    session.expiresAtSec = Math.max(session.expiresAtSec, round(this.simTimeSec + 24));
    this.logAgentReroute(yielder, this.taskForVehicle(yielder), resumeNodeId, route, 'agent-refresh-queue-tail-yield', { countTaskReplan: false });
    return true;
  }

  private topLiftTemporaryYieldStorageHoldAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (!this.isStorageNode(nodeId)) {
      return false;
    }
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    if (!this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId)) {
      return false;
    }
    if (vehicle.loaded) {
      return true;
    }
    if (this.topLiftRouteUnavailableTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId)) {
      return true;
    }
    if (this.topLiftNoStopTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId)) {
      return true;
    }
    if (this.topLiftNoStopBottomASpineTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId)) {
      return true;
    }
    if (this.topLiftMiddleSpineClaimTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId)) {
      return true;
    }
    if (this.topLiftInboundStagedQueueStorageYieldAllowed(vehicle, nodeId)) {
      return true;
    }
    const task = this.taskForVehicle(vehicle);
    if (!task) {
      return true;
    }
    if (task.kind === 'outbound') {
      return nodeId === task.pickupNodeId;
    }
    return false;
  }

  private topLiftTaskVehicleSideYieldRouteUsesDisallowedStorage(
    vehicle: MutableVehicle,
    routeNodeIds: string[]
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !vehicle.taskId) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (!task) {
      return false;
    }
    const storageNodeIds = routeNodeIds.slice(1).filter((nodeId) => this.isStorageNode(nodeId));
    if (storageNodeIds.length === 0) {
      return false;
    }
    if (storageNodeIds.every((nodeId) =>
      this.topLiftRouteUnavailableTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId) ||
      this.topLiftNoStopTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId) ||
      this.topLiftNoStopBottomASpineTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId) ||
      this.topLiftMiddleSpineClaimTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId) ||
      this.topLiftInboundStagedQueueStorageYieldAllowed(vehicle, nodeId)
    )) {
      return false;
    }
    const allowedStorageNodeIds = new Set<string>();
    for (const route of [
      this.vehicleRouteTail(vehicle, vehicle.routeNodeIds),
      this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds),
      [vehicle.currentNodeId, vehicle.targetNodeId].filter((nodeId): nodeId is string => nodeId !== null)
    ]) {
      for (const nodeId of route) {
        if (this.isStorageNode(nodeId)) {
          allowedStorageNodeIds.add(nodeId);
        }
      }
    }
    if (task.kind === 'inbound' && vehicle.loaded) {
      allowedStorageNodeIds.add(task.dropoffNodeId);
    }
    if (task.kind === 'outbound') {
      allowedStorageNodeIds.add(task.pickupNodeId);
    }
    return routeNodeIds.some((nodeId) => {
      if (!this.isStorageNode(nodeId)) {
        return false;
      }
      return !allowedStorageNodeIds.has(nodeId);
    });
  }

  private topLiftRouteUnavailableTaskVehicleTemporaryStorageYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !vehicle.taskId ||
      vehicle.waitReason !== 'route-unavailable' ||
      !this.isStorageNode(nodeId)
    ) {
      return false;
    }
    return this.topLiftEmptyVehicleTemporaryStorageYieldAllowed(vehicle, nodeId);
  }

  private topLiftNoStopTaskVehicleTemporaryStorageYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    return (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      vehicle.taskId !== null &&
      vehicle.waitReason === 'no-stop-continuation-blocked' &&
      this.isStorageNode(nodeId) &&
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      this.topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle, nodeId) &&
      this.agentRefreshYieldPocketCanReturn(vehicle, nodeId, vehicle.currentNodeId)
    );
  }

  private topLiftNoStopBottomASpineTaskVehicleTemporaryStorageYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    return (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      vehicle.taskId !== null &&
      vehicle.waitReason === 'no-stop-continuation-blocked' &&
      this.isStorageNode(nodeId) &&
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') &&
      isTopLiftSpineLevelNodeId(vehicle.targetNodeId ?? '', 'middle') &&
      this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId) &&
      this.agentRefreshYieldPocketCanReturn(vehicle, nodeId, vehicle.currentNodeId)
    );
  }

  private topLiftMiddleSpineClaimTaskVehicleTemporaryStorageYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    return (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      vehicle.taskId !== null &&
      vehicle.waitReason === 'top-lift-spine-opposing-claim' &&
      this.isStorageNode(nodeId) &&
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      this.topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle, nodeId) &&
      this.agentRefreshYieldPocketCanReturn(vehicle, nodeId, vehicle.currentNodeId)
    );
  }

  private topLiftInboundStagedQueueStorageYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !this.isStorageNode(nodeId)
    ) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return false;
    }
    const route = this.topLiftInboundStagedQueueStoragePocketRoute(vehicle);
    return route?.at(-1) === nodeId;
  }

  private agentRefreshClearProtectedExitYielder(
    yielder: MutableVehicle,
    session: ConflictSessionV1,
    winner: MutableVehicle,
    resumeNodeId: string
  ): boolean {
    let nextNodeId = yielder.targetNodeId ?? yielder.routeNodeIds[yielder.routeIndex + 1] ?? null;
    if (
      !nextNodeId ||
      session.winnerVehicleId !== winner.id ||
      session.yielderVehicleId !== yielder.id ||
      this.topLiftProtectedInboundQueueExitTargetNodeId(winner) !== yielder.currentNodeId ||
      resumeNodeId !== yielder.currentNodeId ||
      !this.topLiftInboundQueueExitClearingEntryBlockerAllowed(yielder, nextNodeId, winner)
    ) {
      return false;
    }

    let route = yielder.routeNodeIds.length > yielder.routeIndex + 1
      ? this.vehicleRouteTail(yielder, yielder.routeNodeIds)
      : [yielder.currentNodeId, nextNodeId];
    const goalNodeId = yielder.plannedGoalNodeId ?? route.at(-1) ?? nextNodeId;
    const blockedNodeIds = this.agentRefreshBlockedNodeIds(yielder, this.taskForVehicle(yielder), goalNodeId);
    if (route.slice(1).some((nodeId) => blockedNodeIds.has(nodeId))) {
      const alternateRoute = this.tryAgentRefreshShortestPath(
        yielder.currentNodeId,
        goalNodeId,
        blockedNodeIds,
        yielder.lastMovementAxis
      );
      if (!alternateRoute || alternateRoute.length < 2) {
        return false;
      }
      route = this.agentRefreshExpandLiftColumnSegments(alternateRoute);
      nextNodeId = route[1] ?? null;
      if (!nextNodeId) {
        return false;
      }
    }
    if (
      yielder.currentEdgeId !== null &&
      yielder.targetNodeId === nextNodeId &&
      yielder.waitReason === null &&
      yielder.state !== 'waiting-blocked'
    ) {
      session.state = 'yielding';
      session.updatedAtSec = this.simTimeSec;
      session.yielderOriginalNodeId = yielder.currentNodeId;
      session.yielderPocketNodeId = route[1] ?? nextNodeId;
      session.yielderLocalRouteNodeIds = route;
      session.resumeNodeId = resumeNodeId;
      session.timeoutAtSec = Math.max(session.timeoutAtSec, round(this.simTimeSec + 18));
      session.expiresAtSec = Math.max(session.expiresAtSec, round(this.simTimeSec + 24));
      return true;
    }

    const retargetsActiveLeg = yielder.currentEdgeId !== null && yielder.targetNodeId !== nextNodeId;
    yielder.routeNodeIds = route;
    yielder.routeIndex = 0;
    yielder.targetNodeId = nextNodeId;
    if (retargetsActiveLeg) {
      const currentPosition = nodePosition(this.scenario, yielder.currentNodeId);
      yielder.currentEdgeId = null;
      yielder.x = currentPosition.x;
      yielder.y = SHUTTLE_Y_M;
      yielder.z = currentPosition.z;
      yielder.legRemainingM = 0;
      yielder.legElapsedSec = 0;
      yielder.legTravelSec = 0;
    }
    yielder.state = yielder.loaded ? 'loaded-moving' : yielder.taskId ? 'moving-to-pickup' : 'returning';
    yielder.waitReason = null;
    yielder.blockingReservationId = null;
    yielder.blockingVehicleId = null;
    yielder.waitingSinceSec = null;
    yielder.yieldHoldUntilSec = null;
    yielder.yieldHoldNodeId = null;
    yielder.localRouteNodeIds = [];
    yielder.localRouteReason = null;

    session.state = 'yielding';
    session.updatedAtSec = this.simTimeSec;
    session.yielderOriginalNodeId = yielder.currentNodeId;
    session.yielderPocketNodeId = route[1] ?? nextNodeId;
    session.yielderLocalRouteNodeIds = route;
    session.resumeNodeId = resumeNodeId;
    session.timeoutAtSec = Math.max(session.timeoutAtSec, round(this.simTimeSec + 18));
    session.expiresAtSec = Math.max(session.expiresAtSec, round(this.simTimeSec + 24));
    this.logAgentReroute(yielder, this.taskForVehicle(yielder), resumeNodeId, route, 'top-lift-inbound-queue-exit-yielder-clearance', { countTaskReplan: false });
    return true;
  }

  private topLiftQueueSideYieldContinuationNodeId(
    vehicle: MutableVehicle,
    currentNodeId: string,
    pocketNodeId: string
  ): string | null {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return null;
    }
    const currentSlot = topLiftQueueParkingSlot(currentNodeId);
    const pocketSlot = topLiftQueueParkingSlot(pocketNodeId);
    if (
      !currentSlot ||
      !pocketSlot ||
      currentSlot.liftNodeId !== pocketSlot.liftNodeId ||
      pocketSlot.slotIndex !== currentSlot.slotIndex + 1
    ) {
      return null;
    }

    const tailNodeId = liftQueueNodeId(currentSlot.liftNodeId, pocketSlot.slotIndex + 1);
    if (
      !this.layoutNode(tailNodeId) ||
      !this.traffic.findEdge(pocketNodeId, tailNodeId) ||
      this.currentNodeOccupancy.get(tailNodeId) ||
      this.nodeClaimedByOtherVehicle(tailNodeId, vehicle.id)
    ) {
      return null;
    }
    return tailNodeId;
  }

  private topLiftEmptySideYieldContinuationNodeId(
    vehicle: MutableVehicle,
    currentNodeId: string,
    pocketNodeId: string,
    blockedTargetNodeId: string
  ): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      this.isStorageNode(currentNodeId) ||
      !isTopLiftColumnAccessNodeId(currentNodeId) ||
      !isTopLiftColumnAccessNodeId(pocketNodeId)
    ) {
      return null;
    }
    if (this.topLiftDoubleAisleOppositeLaneNode(currentNodeId, pocketNodeId)) {
      return null;
    }
    const blockedTarget = nodePosition(this.scenario, blockedTargetNodeId);
    return this.neighbors(pocketNodeId)
      .filter((neighbor) => this.layoutNode(neighbor.nodeId)?.type === 'storage')
      .filter((neighbor) =>
        this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId) ||
        this.topLiftMiddleAisleTemporaryStorageYieldContinuationAllowed(vehicle, currentNodeId, pocketNodeId, neighbor.nodeId) ||
        this.topLiftColumnAccessTemporaryStorageYieldContinuationAllowed(vehicle, currentNodeId, pocketNodeId, neighbor.nodeId)
      )
      .filter((neighbor) => this.traffic.findEdge(pocketNodeId, neighbor.nodeId) !== null)
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, pocketNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftPosition = nodePosition(this.scenario, left.nodeId);
        const rightPosition = nodePosition(this.scenario, right.nodeId);
        const leftAwayM = Math.abs(leftPosition.x - blockedTarget.x) + Math.abs(leftPosition.z - blockedTarget.z);
        const rightAwayM = Math.abs(rightPosition.x - blockedTarget.x) + Math.abs(rightPosition.z - blockedTarget.z);
        return rightAwayM - leftAwayM ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0]?.nodeId ?? null;
  }

  private agentRefreshTransferBypassCandidate(
    vehicle: MutableVehicle,
    currentNodeId: string,
    forbiddenNodeIds: Set<string>
  ): { nodeId: string; lengthM: number } | null {
    const currentLiftId = this.liftStorageTransferTargetLiftId(currentNodeId);
    if (!currentLiftId || vehicle.loaded) {
      return null;
    }

    const current = nodePosition(this.scenario, currentNodeId);
    return this.neighbors(currentNodeId)
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.liftStorageTransferTargetLiftId(neighbor.nodeId) === currentLiftId)
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(vehicle, neighbor.nodeId, currentNodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftNode = nodePosition(this.scenario, left.nodeId);
        const rightNode = nodePosition(this.scenario, right.nodeId);
        return Math.abs(leftNode.z - current.z) - Math.abs(rightNode.z - current.z) ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0] ?? null;
  }

  private agentRefreshAdjacentTransferBypassCandidate(
    vehicle: MutableVehicle,
    currentNodeId: string,
    forbiddenNodeIds: Set<string>
  ): { nodeId: string; lengthM: number } | null {
    if (!this.isStorageNode(currentNodeId) || vehicle.loaded) {
      return null;
    }

    return this.neighbors(currentNodeId)
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.liftStorageTransferTargetLiftId(neighbor.nodeId) !== null)
      .filter((neighbor) => this.agentRefreshYieldPocketCanReturn(vehicle, neighbor.nodeId, currentNodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .sort((left, right) =>
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0] ?? null;
  }

  private agentRouteNodeAfter(vehicle: MutableVehicle, nodeId: string): string | null {
    const routeIndex = vehicle.routeNodeIds.indexOf(nodeId, Math.max(0, vehicle.routeIndex));
    if (routeIndex >= 0) {
      return vehicle.routeNodeIds[routeIndex + 1] ?? null;
    }
    const plannedIndex = vehicle.plannedRouteNodeIds.indexOf(nodeId);
    return plannedIndex >= 0 ? vehicle.plannedRouteNodeIds[plannedIndex + 1] ?? null : null;
  }

  private routeUnavailableWaitTargetNodeId(vehicle: MutableVehicle, task: TaskStateRecord | null, goalNodeId: string): string {
    if (
      task?.kind === 'inbound' &&
      !vehicle.loaded &&
      this.topLiftInboundEmptyApproachLiftNodeId(task, goalNodeId)
    ) {
      return goalNodeId;
    }
    const routeNextNodeId = this.agentRouteNodeAfter(vehicle, vehicle.currentNodeId);
    if (routeNextNodeId && routeNextNodeId !== vehicle.currentNodeId) {
      return routeNextNodeId;
    }
    if (vehicle.targetNodeId && vehicle.targetNodeId !== vehicle.currentNodeId) {
      return vehicle.targetNodeId;
    }
    return goalNodeId;
  }

  private agentRefreshRouteNodeAfter(
    vehicle: MutableVehicle,
    nodeId: string,
    candidateRouteNodeIds: string[] | null
  ): string | null {
    if (candidateRouteNodeIds) {
      const candidateIndex = candidateRouteNodeIds.indexOf(nodeId);
      return candidateIndex >= 0 ? candidateRouteNodeIds[candidateIndex + 1] ?? null : null;
    }
    return this.agentRouteNodeAfter(vehicle, nodeId);
  }

  private agentRefreshYieldPocketCanReturn(
    vehicle: MutableVehicle,
    pocketNodeId: string,
    resumeNodeId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    if (pocketNodeId === resumeNodeId) {
      return true;
    }
    const blockedNodeIds = new Set<string>();
    if (!this.isStorageNode(pocketNodeId) && !this.isStorageNode(resumeNodeId)) {
      for (const node of this.scenario.layout.nodes) {
        if (node.type === 'storage') {
          blockedNodeIds.add(node.id);
        }
      }
      blockedNodeIds.delete(pocketNodeId);
      blockedNodeIds.delete(resumeNodeId);
    }
    try {
      this.agentRefreshShortestPath(pocketNodeId, resumeNodeId, blockedNodeIds);
      return true;
    } catch {
      const task = this.taskForVehicle(vehicle);
      const goalNodeId = this.agentGoalNodeId(vehicle, task);
      if (!goalNodeId || goalNodeId === resumeNodeId) {
        return false;
      }
      try {
        this.agentRefreshShortestPath(pocketNodeId, goalNodeId, blockedNodeIds);
        return true;
      } catch {
        return false;
      }
    }
  }

  private agentRefreshYieldPocketAllowed(
    vehicle: MutableVehicle,
    nodeId: string
  ): boolean {
    const node = this.layoutNode(nodeId);
    if (!node || node.type === 'lift-blackbox' || this.liftStorageTransferTargetLiftId(nodeId)) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    const claimantId = this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
    if (claimantId) {
      return false;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      (this.taskForVehicle(vehicle)?.kind ?? 'inbound') === 'inbound' &&
      !this.topLiftTasklessOutboundClearanceSameLaneYieldPreferred(vehicle, nodeId) &&
      this.topLiftOutboundFaceKeepoutNodeIds().has(nodeId)
    ) {
      return false;
    }
    if (node.type === 'storage') {
      const task = this.taskForVehicle(vehicle);
      const noStopBottomASpineStorageYieldAllowed =
        this.topLiftNoStopBottomASpineTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId);
      if (
        this.topLiftColumnLayoutEnabled() &&
        !this.isStorageNode(vehicle.currentNodeId) &&
        !isTopLiftColumnAccessNodeId(vehicle.currentNodeId) &&
        !noStopBottomASpineStorageYieldAllowed
      ) {
        return false;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        !vehicle.loaded &&
        task?.kind === 'inbound' &&
        !this.topLiftInboundStagedQueueStorageYieldAllowed(vehicle, nodeId) &&
        !this.topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle, nodeId)
      ) {
        return false;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        !vehicle.loaded &&
        task?.kind === 'outbound' &&
        nodeId !== task.pickupNodeId &&
        !this.topLiftNoStopTaskVehicleTemporaryStorageYieldAllowed(vehicle, nodeId) &&
        !noStopBottomASpineStorageYieldAllowed
      ) {
        return false;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        vehicle.loaded &&
        task?.kind === 'inbound' &&
        nodeId !== task.dropoffNodeId &&
        !this.topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle, nodeId)
      ) {
        return false;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        vehicle.loaded &&
        task?.kind === 'outbound' &&
        nodeId !== task.pickupNodeId
      ) {
        const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
        const candidatePosition = this.storageGridPosition(nodeId);
        if (!currentPosition || !candidatePosition || candidatePosition.column !== currentPosition.column) {
          return false;
        }
      }
      return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      isTopLiftColumnAccessNodeId(node.id)
    ) {
      return true;
    }
    if (this.topLiftColumnLayoutEnabled() && !vehicle.loaded && !this.taskForVehicle(vehicle)) {
      const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
      const candidateEntrySlot = topLiftQueueEntrySlot(node.id);
      if (currentEntrySlot && candidateEntrySlot?.liftNodeId === currentEntrySlot.liftNodeId) {
        return true;
      }
    }
    if (this.topLiftColumnLayoutEnabled() && node.type === 'parking') {
      return false;
    }
    return node.type === 'parking' || node.type === 'aisle' || /^left-row-|^right-row-/.test(node.id);
  }

  private topLiftEmptyTemporaryYieldNodeAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return true;
    }
    return !isTopLiftAisleLevelNodeId(nodeId, 'bottom-b');
  }

  private topLiftEmptyBottomBLoadedIngressYieldAllowed(
    vehicle: MutableVehicle,
    nodeId: string,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !requester.loaded ||
      requester.targetNodeId !== vehicle.currentNodeId ||
      blockedTargetNodeId !== vehicle.currentNodeId ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-b') ||
      !isTopLiftAisleLevelNodeId(requester.currentNodeId, 'bottom-a') ||
      !isTopLiftAisleLevelNodeId(nodeId, 'bottom-b')
    ) {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const requesterColumn = this.topLiftColumnAccessColumn(requester.currentNodeId);
    const candidateColumn = this.topLiftColumnAccessColumn(nodeId);
    if (
      currentColumn === null ||
      requesterColumn === null ||
      candidateColumn === null ||
      requesterColumn !== currentColumn ||
      Math.abs(candidateColumn - currentColumn) !== 1 ||
      !this.traffic.findEdge(vehicle.currentNodeId, nodeId)
    ) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    return !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
  }

  private topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') ||
      !this.isStorageNode(nodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, nodeId)
    ) {
      return false;
    }
    return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
  }

  private topLiftEmptyVehicleTemporaryStorageYieldAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !this.isStorageNode(nodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, nodeId)
    ) {
      return false;
    }
    return this.topLiftMiddleAisleTemporaryStorageYieldAllowed(vehicle, nodeId) ||
      isTopLiftColumnAccessNodeId(vehicle.currentNodeId);
  }

  private topLiftMiddleAisleTemporaryStorageYieldContinuationAllowed(
    vehicle: MutableVehicle,
    currentNodeId: string,
    pocketNodeId: string,
    storageNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !isTopLiftAisleLevelNodeId(currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(pocketNodeId, 'middle') ||
      !this.isStorageNode(storageNodeId) ||
      !this.traffic.findEdge(pocketNodeId, storageNodeId)
    ) {
      return false;
    }
    return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, storageNodeId);
  }

  private topLiftColumnAccessTemporaryStorageYieldContinuationAllowed(
    vehicle: MutableVehicle,
    currentNodeId: string,
    pocketNodeId: string,
    storageNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !isTopLiftColumnAccessNodeId(currentNodeId) ||
      !isTopLiftColumnAccessNodeId(pocketNodeId) ||
      !this.isStorageNode(storageNodeId) ||
      !this.traffic.findEdge(pocketNodeId, storageNodeId)
    ) {
      return false;
    }
    return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, storageNodeId);
  }

  private agentRefreshYieldPocketMovesAwayFromBlockedTransfer(
    vehicle: MutableVehicle,
    nodeId: string,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.isStorageNode(vehicle.currentNodeId) ||
      !this.isStorageNode(nodeId) ||
      this.liftStorageTransferTargetLiftId(blockedTargetNodeId) === null
    ) {
      return true;
    }
    const current = nodePosition(this.scenario, vehicle.currentNodeId);
    const candidate = nodePosition(this.scenario, nodeId);
    const blockedTarget = nodePosition(this.scenario, blockedTargetNodeId);
    const currentDistanceM = Math.abs(current.x - blockedTarget.x) + Math.abs(current.z - blockedTarget.z);
    const candidateDistanceM = Math.abs(candidate.x - blockedTarget.x) + Math.abs(candidate.z - blockedTarget.z);
    return candidateDistanceM > currentDistanceM + 0.1;
  }

  private agentRefreshYieldPocketRank(vehicle: MutableVehicle, nodeId: string): number {
    const node = this.layoutNode(nodeId);
    if (!node) {
      return 99;
    }
    if (this.topLiftTasklessOutboundClearanceSameLaneYieldPreferred(vehicle, nodeId)) {
      return -1;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      isTopLiftColumnAccessNodeId(vehicle.currentNodeId) &&
      isTopLiftColumnAccessNodeId(node.id) &&
      this.topLiftDoubleAisleOppositeLaneNode(vehicle.currentNodeId, node.id)
    ) {
      return 0;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      isTopLiftColumnAccessNodeId(vehicle.currentNodeId) &&
      node.type === 'storage'
    ) {
      const currentLevel = topLiftAisleLevel(vehicle.currentNodeId);
      const doubleAisleLevel = currentLevel === 'bottom-a' ||
        currentLevel === 'bottom-b';
      return doubleAisleLevel ? 1 : 0;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !this.isStorageNode(vehicle.currentNodeId) &&
      !vehicle.loaded &&
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'middle') &&
      isTopLiftAisleLevelNodeId(node.id, 'middle')
    ) {
      return 0;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !this.isStorageNode(vehicle.currentNodeId) &&
      isTopLiftColumnAccessNodeId(node.id)
    ) {
      return vehicle.loaded ? 0 : 1;
    }
    if (node.type === 'storage') {
      if (this.topLiftColumnLayoutEnabled() && !this.isStorageNode(vehicle.currentNodeId)) {
        return vehicle.loaded ? 1 : 0;
      }
      return vehicle.loaded ? 1 : 0;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      isTopLiftColumnAccessNodeId(node.id)
    ) {
      return vehicle.loaded ? 0 : 1;
    }
    if (/^left-row-|^right-row-/.test(node.id)) {
      return 2;
    }
    if (node.type === 'parking') {
      return 3;
    }
    if (node.type === 'aisle') {
      return 4;
    }
    return 10;
  }

  private agentRefreshYieldPocketDirectionScore(
    vehicle: MutableVehicle,
    nodeId: string,
    blockedTargetNodeId: string
  ): number {
    if (
      !this.isStorageNode(vehicle.currentNodeId) ||
      !this.isStorageNode(nodeId) ||
      this.liftStorageTransferTargetLiftId(blockedTargetNodeId) === null
    ) {
      return 0;
    }
    const current = nodePosition(this.scenario, vehicle.currentNodeId);
    const candidate = nodePosition(this.scenario, nodeId);
    const blockedTarget = nodePosition(this.scenario, blockedTargetNodeId);
    const currentDistanceM = Math.abs(current.x - blockedTarget.x) + Math.abs(current.z - blockedTarget.z);
    const candidateDistanceM = Math.abs(candidate.x - blockedTarget.x) + Math.abs(candidate.z - blockedTarget.z);
    if (candidateDistanceM > currentDistanceM + 0.1) {
      return -candidateDistanceM;
    }
    if (candidateDistanceM < currentDistanceM - 0.1) {
      return 100 + candidateDistanceM;
    }
    return 0;
  }

  private agentRefreshYieldPocketTieBreak(vehicle: MutableVehicle, nodeId: string): number {
    if (!this.liftStorageTransferTargetLiftId(vehicle.currentNodeId)) {
      return 0;
    }
    const position = this.storageGridPosition(nodeId);
    return position ? -position.column : 0;
  }

  private taskForVehicle(vehicle: MutableVehicle): TaskStateRecord | null {
    return this.taskById(vehicle.taskId);
  }

  private agentGoalNodeId(vehicle: MutableVehicle, task: TaskStateRecord | null): string | null {
    if (
      task &&
      vehicle.localRouteReason === 'inbound-unready-queue-leader-yield' &&
      vehicle.plannedGoalNodeId &&
      vehicle.plannedGoalNodeId !== vehicle.currentNodeId &&
      vehicle.localRouteNodeIds[0] === vehicle.currentNodeId
    ) {
      return vehicle.plannedGoalNodeId;
    }
    if (task?.kind === 'inbound' && !vehicle.loaded && vehicle.currentNodeId !== task.pickupNodeId) {
      const activeQueueGoalNodeId = this.topLiftInboundActiveQueueRouteTerminalNodeId(task, vehicle);
      if (
        activeQueueGoalNodeId &&
        activeQueueGoalNodeId !== vehicle.currentNodeId &&
        this.topLiftInboundCurrentQueueResourceSlot(vehicle, this.taskLiftPortNodeId(task) ?? '') === null
      ) {
        return activeQueueGoalNodeId;
      }
    }
    if (task) {
      return this.taskDispatchGoalNodeId(task, vehicle);
    }
    if (this.topLiftColumnLayoutEnabled() && vehicle.plannedGoalNodeId && vehicle.plannedGoalNodeId !== vehicle.currentNodeId) {
      return vehicle.plannedGoalNodeId;
    }
    const routeGoal = vehicle.routeNodeIds.at(-1) ?? null;
    return routeGoal && routeGoal !== vehicle.currentNodeId ? routeGoal : null;
  }

  private agentRouteToGoal(vehicle: MutableVehicle, task: TaskStateRecord | null, goalNodeId: string): string[] {
    if (this.agentRefreshEnabled()) {
      const committedLocalRoute = this.agentRefreshCommittedLocalRoute(vehicle, goalNodeId);
      if (committedLocalRoute) {
        return committedLocalRoute;
      }

      const committedRoute = this.agentCommittedRoute(vehicle, goalNodeId);
      if (committedRoute) {
        return committedRoute;
      }

      const existingRouteTail = this.existingRouteTailToGoal(vehicle, task, goalNodeId);
      if (existingRouteTail) {
        return existingRouteTail;
      }

      return this.installAgentRefreshPlannedRoute(vehicle, task, goalNodeId);
    }

    if (this.agentMinimalEnabled()) {
      const committedYieldRoute = this.agentCommittedYieldRoute(vehicle, goalNodeId);
      if (committedYieldRoute) {
        const committedNextNodeId = committedYieldRoute[1] ?? null;
        if (committedNextNodeId && (!this.collisionAvoidanceEnabled() || !this.agentMinimalMoveBlocker(vehicle, committedNextNodeId))) {
          return committedYieldRoute;
        }
      }

      const committedRoute = this.agentCommittedRoute(vehicle, goalNodeId);
      if (committedRoute) {
        const committedNextNodeId = committedRoute[1] ?? null;
        if (
          committedNextNodeId &&
          (!this.collisionAvoidanceEnabled() || !this.agentMinimalMoveBlocker(vehicle, committedNextNodeId))
        ) {
          return committedRoute;
        }
      }

      return this.agentNominalRouteToGoal(vehicle, task, goalNodeId);
    }

    const committedRoute = this.agentCommittedRoute(vehicle, goalNodeId);
    if (committedRoute) {
      const committedNextNodeId = committedRoute[1] ?? null;
      if (committedNextNodeId && (!this.collisionAvoidanceEnabled() || !this.agentMoveBlocker(vehicle, committedNextNodeId))) {
        return committedRoute;
      }
    }

    const committedYieldRoute = this.agentCommittedYieldRoute(vehicle, goalNodeId);
    if (committedYieldRoute) {
      const committedNextNodeId = committedYieldRoute[1] ?? null;
      if (committedNextNodeId && (!this.collisionAvoidanceEnabled() || !this.agentMoveBlocker(vehicle, committedNextNodeId))) {
        return committedYieldRoute;
      }
    }

    const directRoute = this.agentNominalRouteToGoal(vehicle, task, goalNodeId);
    const directNextNodeId = directRoute[1] ?? null;
    if (!this.collisionAvoidanceEnabled() || !directNextNodeId) {
      return directRoute;
    }

    const directBlock = this.agentMoveBlocker(vehicle, directNextNodeId);
    const lookaheadBlock = directBlock ? null : this.agentEmptyStorageExitLookaheadBlocker(vehicle, directRoute);
    if (!directBlock && !lookaheadBlock) {
      return directRoute;
    }
    const blockedNodeId = directBlock ? directNextNodeId : lookaheadBlock!.nodeId;

    if (vehicle.loaded) {
      return directRoute;
    }
    if (this.isStorageNode(vehicle.currentNodeId)) {
      const headOnYieldRoute = directBlock?.blockingVehicleId
        ? this.agentStorageHeadOnYieldRoute(vehicle, task, goalNodeId, directNextNodeId, directBlock.blockingVehicleId)
        : null;
      return headOnYieldRoute ?? directRoute;
    }

    try {
      if (!vehicle.loaded) {
        const storageBypassRoute = this.agentStorageBypassRoute(vehicle, task, goalNodeId, blockedNodeId, directRoute);
        if (storageBypassRoute) {
          return storageBypassRoute;
        }
      }

      const blockedNodeIds = this.agentStaticBlockedNodeIds(vehicle, goalNodeId, { openStorageRows: !vehicle.loaded });
      for (const nodeId of this.agentDynamicBlockedNodeIds(vehicle)) {
        blockedNodeIds.add(nodeId);
      }
      const alternateRoute = this.agentShortestPath(vehicle.currentNodeId, goalNodeId, blockedNodeIds);
      const alternateNextNodeId = alternateRoute[1] ?? null;
      if (
        alternateNextNodeId &&
        !this.agentMoveBlocker(vehicle, alternateNextNodeId) &&
        this.agentLocalRerouteAcceptable(directRoute, alternateRoute)
      ) {
        this.logAgentReroute(vehicle, task, blockedNodeId, alternateRoute, vehicle.loaded ? 'loaded-local-obstacle-reroute' : 'empty-local-obstacle-reroute');
        return alternateRoute;
      }
    } catch {
      // Waiting is better than forcing a strange detour when there is no real local bypass.
    }

    return directRoute;
  }

  private agentRefreshCommittedLocalRoute(vehicle: MutableVehicle, goalNodeId: string): string[] | null {
    if (!vehicle.localRouteReason) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (
      vehicle.localRouteReason === 'inbound-queue-standby' &&
      task?.kind === 'inbound' &&
      !vehicle.loaded &&
      goalNodeId === task.pickupNodeId &&
      !this.inboundTaskShouldWaitBeforePickup(task) &&
        this.inboundTaskLoadReadyAtPickup(task)
      ) {
        return null;
      }
    if (
      vehicle.localRouteReason === 'temporary-yield' &&
      this.isStorageNode(vehicle.currentNodeId) &&
      vehicle.plannedGoalNodeId === goalNodeId
    ) {
      const rejoinRoute = this.agentRefreshYieldPocketExitLookaheadRoute(vehicle);
      if (
        rejoinRoute &&
        rejoinRoute.length >= 2 &&
        rejoinRoute[0] === vehicle.currentNodeId &&
        rejoinRoute.at(-1) === goalNodeId &&
        this.routeStorageClearForTask(vehicle, task, rejoinRoute) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, rejoinRoute)
      ) {
        vehicle.routeNodeIds = rejoinRoute;
        vehicle.routeIndex = 0;
        vehicle.plannedGoalNodeId = goalNodeId;
        vehicle.plannedRouteNodeIds = rejoinRoute;
        vehicle.localRouteNodeIds = [];
        vehicle.localRouteReason = null;
        return rejoinRoute;
      }
    }
    const currentIndex = vehicle.routeNodeIds.indexOf(vehicle.currentNodeId, Math.max(0, vehicle.routeIndex));
    if (currentIndex < 0) {
      return null;
    }
    const route = vehicle.routeNodeIds.slice(currentIndex);
    const routeCanTerminateAtGoal =
      vehicle.localRouteReason === 'temporary-yield' ||
      vehicle.localRouteReason === 'inbound-unready-queue-leader-yield' ||
      vehicle.localRouteReason === 'inbound-queue-standby' ||
      vehicle.localRouteReason === 'top-lift-queue-swap-yield' ||
      vehicle.localRouteReason === 'loaded-top-b-faceoff-top-a-bypass';
    if (route.length < 2 || route[0] !== vehicle.currentNodeId || (!routeCanTerminateAtGoal && route.at(-1) === goalNodeId)) {
      return null;
    }
    const nextNodeId = route[1]!;
    return this.traffic.findEdge(vehicle.currentNodeId, nextNodeId) && this.agentRefreshLocalRouteNodesClear(vehicle, route)
      ? route
      : null;
  }

  private routeStorageClearForTask(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    routeNodeIds: string[]
  ): boolean {
    for (const nodeId of routeNodeIds.slice(1)) {
      if (!this.isStorageNode(nodeId)) {
        continue;
      }
      const storedLoadId = this.storedLoadIdAtNode(nodeId);
      if (!storedLoadId || nodeId === vehicle.currentNodeId) {
        continue;
      }
      if (
        task?.kind === 'outbound' &&
        !vehicle.loaded &&
        nodeId === task.pickupNodeId &&
        storedLoadId === task.loadId
      ) {
        continue;
      }
      return false;
    }
    return true;
  }

  private agentRefreshLocalRouteNodesClear(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    const reservationStartSec = this.simTimeSec;
    const reservationEndSec = round(
      this.simTimeSec +
      this.routeTravelEstimateSec(vehicle, routeNodeIds) +
      this.scenario.trafficPolicy.minimumClearanceSec +
      this.scenario.timeStepSec
    );
    for (const nodeId of routeNodeIds.slice(1)) {
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicle.id) {
        return false;
      }
      if (this.nodeClaimedByOtherVehicle(nodeId, vehicle.id)) {
        return false;
      }
      if (this.nodeReservedByOtherVehicleDuring(nodeId, vehicle.id, reservationStartSec, reservationEndSec)) {
        return false;
      }
    }
    return true;
  }

  private nodeReservedByOtherVehicleDuring(
    nodeId: string,
    vehicleId: string,
    startTimeSec: number,
    endTimeSec: number
  ): string | null {
    const reservation = this.reservations.find((candidate) =>
      candidate.vehicleId !== vehicleId &&
      candidate.resourceType === 'node' &&
      candidate.resourceId === nodeId &&
      startTimeSec <= candidate.endTimeSec + 1e-6 &&
      candidate.startTimeSec <= endTimeSec + 1e-6
    );
    return reservation?.vehicleId ?? null;
  }

  private enforceTopLiftWorkcellRouteContract(
    route: string[] | null,
    flow: LiftWorkcellRouteFlow,
    expectedLiftNodeId: string | null,
    expectedKind: LiftKind | null
  ): string[] | null {
    if (!route || !this.topLiftColumnLayoutEnabled()) {
      return route;
    }
    const violations = topLiftWorkcellRouteContractViolations(route, {
      flow,
      expectedLiftNodeId,
      expectedKind
    });
    if (violations.length === 0) {
      return route;
    }
    const first = violations[0]!;
    throw new Error(
      `Invalid top-lift workcell route (${flow}): ${first.code} at ${first.nodeId}; ${first.message} route=${route.join('>')}`
    );
  }

  private enforceTaskTopLiftWorkcellRouteContract(
    route: string[] | null,
    task: TaskStateRecord,
    flow: LiftWorkcellRouteFlow
  ): string[] | null {
    return this.enforceTopLiftWorkcellRouteContract(
      route,
      flow,
      this.taskLiftPortNodeId(task),
      task.kind as LiftKind
    );
  }

  private agentRefreshNominalRouteToGoal(vehicle: MutableVehicle, task: TaskStateRecord | null, goalNodeId: string): string[] {
    if (vehicle.currentNodeId === goalNodeId) {
      return [vehicle.currentNodeId];
    }
    if (task?.kind === 'inbound' && vehicle.loaded && goalNodeId === task.dropoffNodeId) {
      return this.agentRefreshLoadedInboundRouteToDropoff(vehicle.currentNodeId, task);
    }
    if (task?.kind === 'inbound' && !vehicle.loaded) {
      const pickupRoute = this.agentRefreshEmptyInboundRouteToPickup(vehicle, task, goalNodeId);
      if (pickupRoute) {
        return pickupRoute;
      }
      if (this.topLiftInboundEmptyApproachStrictPathRequired(vehicle.currentNodeId, task, goalNodeId)) {
        throw new Error(`No route between ${vehicle.currentNodeId} and ${goalNodeId}`);
      }
    }
    if (task?.kind === 'outbound' && vehicle.loaded) {
      const dropoffRoute = this.agentRefreshLoadedOutboundRouteToDropoff(vehicle.currentNodeId, task, goalNodeId);
      if (dropoffRoute) {
        return dropoffRoute;
      }
      if (this.topLiftColumnLayoutEnabled() && this.isStorageNode(vehicle.currentNodeId)) {
        return [vehicle.currentNodeId];
      }
    }
    if (task?.kind === 'outbound' && !vehicle.loaded && goalNodeId === task.pickupNodeId) {
      const pickupRoute = this.topLiftEmptyOutboundPickupRoute(vehicle, task);
      if (pickupRoute) {
        return pickupRoute;
      }
      if (this.topLiftColumnLayoutEnabled()) {
        throw new Error(`No route between ${vehicle.currentNodeId} and ${goalNodeId}`);
      }
    }

    const blockedNodeIds = this.agentRefreshBlockedNodeIds(vehicle, task, goalNodeId);
    const fallbackRoute = this.agentRefreshExpandLiftColumnSegments(
      this.agentRefreshShortestPath(vehicle.currentNodeId, goalNodeId, blockedNodeIds, vehicle.lastMovementAxis)
    );
    if (
      task?.kind === 'inbound' &&
      !vehicle.loaded &&
      !this.topLiftInboundEmptyApproachRouteAllowed(fallbackRoute, vehicle.currentNodeId, task, goalNodeId)
    ) {
      throw new Error(`No route between ${vehicle.currentNodeId} and ${goalNodeId}`);
    }
    return fallbackRoute;
  }

  private topLiftEmptyOutboundPickupRoute(vehicle: MutableVehicle, task: TaskStateRecord): string[] | null {
    return this.topLiftEmptyOutboundPickupRouteFromNode(vehicle, task, vehicle.currentNodeId);
  }

  private topLiftEmptyOutboundPickupRouteFromNode(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    fromNodeId: string
  ): string[] | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'outbound' ||
      fromNodeId === task.pickupNodeId
    ) {
      return null;
    }

    const directRoute = this.topLiftDirectStorageColumnStorageRoute(fromNodeId, task.pickupNodeId);
    const allowedStorageNodeIds = new Set([fromNodeId, task.pickupNodeId]);
    if (directRoute && !this.routeHasOtherVehicleStorageOccupancyConflict(vehicle, directRoute, allowedStorageNodeIds)) {
      return directRoute;
    }

    const activeOutboundDockSweepBlocks = this.activeTopLiftOutboundDockSweepBlockedNodeIds(vehicle.id);
    const blockedNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, task.pickupNodeId, { blockStoredLoads: true });
    for (const nodeId of activeOutboundDockSweepBlocks) {
      blockedNodeIds.add(nodeId);
    }
    for (const nodeId of this.activeTopLiftInboundTransitBlockedNodeIds(vehicle, task, task.pickupNodeId)) {
      blockedNodeIds.add(nodeId);
    }
    for (const node of this.scenario.layout.nodes) {
      if (
        isTopLiftAisleLevelNodeId(node.id, 'top-a') ||
        /^lift-\d{2}-(?:inbound|outbound)-throat$/.test(node.id) ||
        /^lift-\d{2}-(?:inbound|outbound)-buffer-access$/.test(node.id) ||
        /^lift-\d{2}-(?:inbound|outbound)-queue-access$/.test(node.id)
      ) {
        blockedNodeIds.add(node.id);
      }
    }
    blockedNodeIds.delete(fromNodeId);
    blockedNodeIds.delete(task.pickupNodeId);
    if (!activeOutboundDockSweepBlocks.has(task.dropoffNodeId)) {
      blockedNodeIds.delete(task.dropoffNodeId);
    }

    const route = this.tryAgentRefreshShortestPath(
      fromNodeId,
      task.pickupNodeId,
      blockedNodeIds,
      vehicle.lastMovementAxis
    );
    if (!route) {
      return null;
    }
    const expandedRoute = this.agentRefreshExpandLiftColumnSegments(route);
    return this.routeHasStoredLoadConflict(expandedRoute, new Set([task.pickupNodeId])) ||
      this.routeHasOtherVehicleStorageOccupancyConflict(vehicle, expandedRoute, allowedStorageNodeIds)
      ? null
      : expandedRoute;
  }

  private tryRecoverRouteUnavailableOutboundStoragePickup(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'outbound' ||
      task.vehicleId !== vehicle.id ||
      goalNodeId !== task.pickupNodeId ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !this.isStorageNode(vehicle.currentNodeId)
    ) {
      return false;
    }

    const recoveryRoute = this.outboundStoragePickupRecoveryRoute(vehicle, task);
    if (recoveryRoute) {
      vehicle.routeNodeIds = recoveryRoute;
      vehicle.routeIndex = 0;
      vehicle.targetNodeId = recoveryRoute[1] ?? null;
      vehicle.state = 'moving-to-pickup';
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      vehicle.waitingSinceSec = null;
      vehicle.plannedGoalNodeId = task.pickupNodeId;
      vehicle.plannedRouteNodeIds = recoveryRoute;
      vehicle.localRouteNodeIds = recoveryRoute;
      vehicle.localRouteReason = 'outbound-route-unavailable-storage-recovery';
      vehicle.yieldHoldUntilSec = null;
      vehicle.yieldHoldNodeId = null;
      this.logAgentReroute(vehicle, task, task.pickupNodeId, recoveryRoute, 'outbound-route-unavailable-storage-recovery');
      return true;
    }

    return false;
  }

  private tryReleaseRouteUnavailableOutboundPickupTaskInStorage(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'outbound' ||
      task.state !== 'assigned' ||
      task.vehicleId !== vehicle.id ||
      task.startedAtSec !== null ||
      goalNodeId !== task.pickupNodeId ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      vehicle.waitReason !== 'route-unavailable' ||
      vehicle.waitingSinceSec === null ||
      this.simTimeSec - vehicle.waitingSinceSec < OUTBOUND_STORAGE_ROUTE_UNAVAILABLE_RELEASE_SEC
    ) {
      return false;
    }

    const previousTaskId = task.id;
    const waitSec = round(this.simTimeSec - vehicle.waitingSinceSec);
    task.vehicleId = null;
    task.waitReason = 'route-unavailable';
    this.setTaskState(task, 'queued');
    vehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(vehicle);
    vehicle.assignmentHoldUntilSec = round(this.simTimeSec + OUTBOUND_STORAGE_ROUTE_UNAVAILABLE_REASSIGN_HOLD_SEC);
    this.logEvent(
      'task-released',
      vehicle.id,
      previousTaskId,
      task.loadId,
      vehicle.currentNodeId,
      task.pickupNodeId,
      'outbound-route-unavailable-storage-release',
      this.vehiclePosition(vehicle),
      {
        pickupNodeId: task.pickupNodeId,
        dropoffNodeId: task.dropoffNodeId,
        waitSec
      }
    );

    if (this.dispatchTasklessTopLiftStorageExit(vehicle, true)) {
      return true;
    }
    this.dispatchTasklessToInboundQueueStandby(vehicle, 'outbound-route-unavailable-storage-release-standby');
    return true;
  }

  private outboundStoragePickupRecoveryRoute(vehicle: MutableVehicle, task: TaskStateRecord): string[] | null {
    const candidates = this.neighbors(vehicle.currentNodeId)
      .map((neighbor) => neighbor.nodeId)
      .filter((nodeId, index, nodeIds) => nodeIds.indexOf(nodeId) === index)
      .filter((nodeId) => nodeId !== vehicle.currentNodeId && this.traffic.findEdge(vehicle.currentNodeId, nodeId))
      .filter((nodeId) => {
        const node = this.layoutNode(nodeId);
        if (!node) {
          return false;
        }
        if (node.type === 'storage') {
          return nodeId === task.pickupNodeId || this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
        }
        const occupantId = this.currentNodeOccupancy.get(nodeId);
        return (!occupantId || occupantId === vehicle.id) && !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
      })
      .filter((nodeId) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, nodeId))
      .map((nodeId) => {
        const routeFromCandidate = nodeId === task.pickupNodeId
          ? [nodeId]
          : this.topLiftEmptyOutboundPickupRouteFromNode(vehicle, task, nodeId);
        if (!routeFromCandidate || routeFromCandidate[0] !== nodeId) {
          return null;
        }
        const routeNodeIds = [vehicle.currentNodeId, ...routeFromCandidate];
        if (
          this.routeHasRepeatedNode(routeNodeIds) ||
          !this.routeHasOnlyAdjacentEdges(routeNodeIds) ||
          !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
          this.routeHasStoredLoadConflict(routeNodeIds, new Set([task.pickupNodeId])) ||
          this.agentRefreshMoveBlocker(vehicle, routeNodeIds[1]!, routeNodeIds)
        ) {
          return null;
        }
        return {
          routeNodeIds,
          score: this.routeDistanceM(routeNodeIds)
        };
      })
      .filter((candidate): candidate is { routeNodeIds: string[]; score: number } => candidate !== null)
      .sort((left, right) =>
        left.score - right.score ||
        left.routeNodeIds.join('>').localeCompare(right.routeNodeIds.join('>'))
      );

    return candidates[0]?.routeNodeIds ?? null;
  }

  private tryReleaseRouteUnavailableOutboundPickupTaskAtAisle(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'outbound' ||
      task.state !== 'assigned' ||
      task.vehicleId !== vehicle.id ||
      task.startedAtSec !== null ||
      goalNodeId !== task.pickupNodeId ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      this.isStorageNode(vehicle.currentNodeId)
    ) {
      return false;
    }

    const previousTaskId = task.id;
    task.vehicleId = null;
    task.waitReason = 'route-unavailable';
    this.setTaskState(task, 'queued');
    vehicle.taskId = null;
    this.resetTasklessVehicleAtCurrentNode(vehicle);
    this.logEvent(
      'task-released',
      vehicle.id,
      previousTaskId,
      task.loadId,
      vehicle.currentNodeId,
      task.pickupNodeId,
      'outbound-route-unavailable-aisle-release',
      this.vehiclePosition(vehicle),
      {
        pickupNodeId: task.pickupNodeId,
        dropoffNodeId: task.dropoffNodeId
      }
    );

    if (this.tryAssignQueuedTaskToVehicle(vehicle)) {
      return true;
    }
    this.dispatchTasklessToInboundQueueStandby(vehicle);
    return true;
  }

  private topLiftQueueServiceTargets(currentNodeId: string, liftNodeId: string, serviceNodeId: string): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const serviceAccessNodeId = liftBufferAccessNodeId(liftNodeId);
    if (!this.layoutNode(serviceNodeId)) {
      return null;
    }
    if (currentNodeId === serviceNodeId) {
      return [];
    }

    if (/-inbound$/.test(liftNodeId)) {
      if (serviceNodeId === this.topLiftInboundPickupStopNodeId(liftNodeId)) {
        return [serviceNodeId];
      }
      const serviceSlot = topLiftQueueServiceSlot(serviceNodeId);
      if (serviceSlot?.liftNodeId === liftNodeId) {
        return [serviceNodeId];
      }
      const pickupServiceNodeId = liftQueueServiceExitNodeId(liftNodeId, 1);
      if (this.layoutNode(pickupServiceNodeId)) {
        return currentNodeId === pickupServiceNodeId
          ? [serviceNodeId]
          : [pickupServiceNodeId, serviceNodeId];
      }
    }

    if (/-outbound$/.test(liftNodeId)) {
      const serviceLaneNodeId = liftQueueServiceExitNodeId(liftNodeId, 1);
      const serviceEntryNodeId = liftQueueTailEntryNodeId(liftNodeId, 1);
      const serviceEntryTopNodeId = this.topLiftQueueEntryTopAccessNodeId(serviceEntryNodeId);
      const serviceEntryBottomNodeId = this.topLiftQueueEntryBottomAccessNodeId(serviceEntryNodeId);
      if (serviceNodeId === this.topLiftOutboundDropoffStopNodeId(liftNodeId) && serviceNodeId !== serviceLaneNodeId) {
        return [serviceNodeId];
      }
      if (this.layoutNode(serviceLaneNodeId)) {
        if (serviceNodeId === serviceLaneNodeId) {
          if (currentNodeId === serviceLaneNodeId) {
            return [];
          }
          if (currentNodeId === serviceEntryNodeId) {
            return [serviceLaneNodeId];
          }
          if (currentNodeId === serviceEntryTopNodeId) {
            return [serviceEntryNodeId, serviceLaneNodeId];
          }
          if (currentNodeId === serviceEntryBottomNodeId) {
            return [serviceEntryTopNodeId, serviceEntryNodeId, serviceLaneNodeId].filter((nodeId): nodeId is string => Boolean(nodeId));
          }
          if (serviceEntryTopNodeId && this.layoutNode(serviceEntryTopNodeId)) {
            return [serviceEntryTopNodeId, serviceEntryNodeId, serviceLaneNodeId];
          }
          return [serviceLaneNodeId];
        }
        if (currentNodeId === serviceAccessNodeId) {
          return [serviceNodeId];
        }
        if (currentNodeId === serviceLaneNodeId) {
          return [serviceAccessNodeId, serviceNodeId];
        }
        if (currentNodeId === serviceEntryNodeId) {
          return [serviceLaneNodeId, serviceAccessNodeId, serviceNodeId];
        }
        if (currentNodeId === serviceEntryTopNodeId) {
          return [serviceEntryNodeId, serviceLaneNodeId, serviceAccessNodeId, serviceNodeId];
        }
        if (currentNodeId === serviceEntryBottomNodeId) {
          return [serviceEntryTopNodeId, serviceEntryNodeId, serviceLaneNodeId, serviceAccessNodeId, serviceNodeId]
            .filter((nodeId): nodeId is string => Boolean(nodeId));
        }
        if (serviceEntryTopNodeId && this.layoutNode(serviceEntryTopNodeId)) {
          return [serviceEntryTopNodeId, serviceEntryNodeId, serviceLaneNodeId, serviceAccessNodeId, serviceNodeId];
        }
        return [serviceLaneNodeId, serviceAccessNodeId, serviceNodeId];
      }
    }

    if (!this.layoutNode(serviceAccessNodeId)) {
      return null;
    }
    return currentNodeId === serviceAccessNodeId
      ? [serviceNodeId]
      : [serviceAccessNodeId, serviceNodeId];
  }

  private agentRefreshEmptyInboundRouteToPickup(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    goalNodeId = task.pickupNodeId
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }

    const route: string[] = [vehicle.currentNodeId];
    const currentExitNodeId = this.isStorageNode(vehicle.currentNodeId)
      ? this.topLiftNearestStorageColumnAccessNodeId(vehicle.currentNodeId)
      : null;
    const liftNodeId = this.taskLiftPortNodeId(task);
    const queueSlot = topLiftQueueParkingSlot(goalNodeId);
    const queueParkingTargets = liftNodeId && queueSlot?.liftNodeId === liftNodeId
      ? [
          liftQueueTailEntryNodeId(liftNodeId, 1),
          ...Array.from({ length: queueSlot.slotIndex }, (_, index) =>
            liftQueueTailAccessNodeId(liftNodeId, index + 1)
          ),
          goalNodeId
        ]
      : [goalNodeId];
    const queueServiceTargets = goalNodeId === task.pickupNodeId && liftNodeId
      ? this.topLiftQueueServiceTargets(vehicle.currentNodeId, liftNodeId, task.pickupNodeId)
      : null;
    const targets = [currentExitNodeId, ...(queueServiceTargets ?? queueParkingTargets)];

    for (const target of targets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      const blockedNodeIds = this.isStorageNode(fromNodeId) || this.isStorageNode(target)
        ? this.blockedStorageTransitNodeIds(fromNodeId, target)
        : this.agentRefreshBlockedNodeIds(vehicle, task, target);
      this.applyTopLiftInboundPickupApproachBlocks(blockedNodeIds, vehicle, task, fromNodeId, target);
      blockedNodeIds.delete(fromNodeId);
      blockedNodeIds.delete(target);
      const segment = this.tryAgentRefreshShortestPath(fromNodeId, target, blockedNodeIds, this.routeTerminalAxis(route));
      if (!segment) {
        const approachPrefix = this.topLiftInboundReachableApproachPrefix(fromNodeId, task, target, blockedNodeIds, this.routeTerminalAxis(route));
        if (approachPrefix) {
          route.push(...approachPrefix.slice(1));
          break;
        }
        return null;
      }
      route.push(...segment.slice(1));
    }

    const expandedRoute = route.length > 1 ? this.agentRefreshExpandLiftColumnSegments(route) : null;
    if (expandedRoute && !this.routeAvoidsActiveTopLiftOutboundDockBlocks(vehicle, expandedRoute)) {
      return null;
    }
    if (!this.topLiftInboundEmptyApproachRouteAllowed(expandedRoute, vehicle.currentNodeId, task, goalNodeId)) {
      return null;
    }
    return this.enforceTaskTopLiftWorkcellRouteContract(expandedRoute, task, 'inbound-empty-approach');
  }

  private topLiftInboundReachableApproachPrefix(
    fromNodeId: string,
    task: TaskStateRecord,
    targetNodeId: string,
    blockedNodeIds: Set<string>,
    initialAxis: MovementAxis
  ): string[] | null {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      targetNodeId !== task.pickupNodeId
    ) {
      return null;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const pickupStopNodeId = liftNodeId ? this.topLiftInboundPickupStopNodeId(liftNodeId) : null;
    const pickupColumn = pickupStopNodeId ? this.topLiftColumnAccessColumn(pickupStopNodeId) : null;
    if (!liftNodeId || !pickupStopNodeId || pickupColumn === null || targetNodeId !== pickupStopNodeId) {
      return null;
    }

    const queueDirection = this.topLiftQueueDisplayDirection(liftNodeId);
    const candidateNodeIds = Array.from({ length: 8 }, (_, index) =>
      columnAccessNodeId('top-b', pickupColumn + queueDirection * (index + 1))
    ).filter((nodeId) => this.layoutNode(nodeId) !== null);

    for (const candidateNodeId of candidateNodeIds) {
      const prefixBlockedNodeIds = new Set(blockedNodeIds);
      prefixBlockedNodeIds.delete(candidateNodeId);
      const route = this.tryAgentRefreshShortestPath(fromNodeId, candidateNodeId, prefixBlockedNodeIds, initialAxis);
      if (route && route.length > 1 && this.topLiftInboundEmptyApproachRouteAllowed(route, fromNodeId, task, targetNodeId)) {
        return route;
      }
    }
    return null;
  }

  private applyTopLiftInboundPickupApproachBlocks(
    blockedNodeIds: Set<string>,
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    fromNodeId: string,
    targetNodeId: string
  ): void {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      task.kind !== 'inbound'
    ) {
      return;
    }

    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return;
    }
    const targetQueueSlot = this.topLiftInboundApproachQueueSlot(targetNodeId);
    if (targetQueueSlot?.liftNodeId === liftNodeId) {
      const pickupStopNodeId = this.topLiftInboundPickupStopNodeId(liftNodeId);
      if (pickupStopNodeId) {
        blockedNodeIds.add(pickupStopNodeId);
      }
      for (const nodeId of this.topLiftInboundApproachQueueNodeIds(liftNodeId)) {
        const slot = this.topLiftInboundApproachQueueSlot(nodeId);
        if (slot && slot.slotIndex < targetQueueSlot.slotIndex) {
          blockedNodeIds.add(nodeId);
        }
      }
      this.applyTopLiftInboundTopLaneCorridorBlocks(blockedNodeIds, fromNodeId, targetNodeId);
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(fromNodeId);
      blockedNodeIds.delete(targetNodeId);
      return;
    }
    const targetLiftNodeId = this.topLiftOperationalLiftNodeId(targetNodeId);
    const targetIsLiftApproach = targetNodeId === task.pickupNodeId ||
      (targetLiftNodeId !== null && targetLiftNodeId === liftNodeId);
    if (!targetIsLiftApproach) {
      return;
    }

    for (const node of this.scenario.layout.nodes) {
      if (isTopLiftAisleLevelNodeId(node.id, 'top-a')) {
        blockedNodeIds.add(node.id);
      }
    }
    for (const nodeId of this.topLiftInboundProjectedQueueCompressionNodeIds(liftNodeId, fromNodeId, targetNodeId)) {
      blockedNodeIds.delete(nodeId);
    }
    for (const nodeId of this.topLiftOutboundFaceKeepoutNodeIds()) {
      blockedNodeIds.add(nodeId);
    }
    for (const nodeId of this.activeTopLiftOutboundDockBlockedNodeIds(vehicle.id)) {
      blockedNodeIds.add(nodeId);
    }
    this.applyTopLiftInboundTopLaneCorridorBlocks(blockedNodeIds, fromNodeId, targetNodeId);
    blockedNodeIds.delete(vehicle.currentNodeId);
    blockedNodeIds.delete(fromNodeId);
    blockedNodeIds.delete(targetNodeId);
    blockedNodeIds.delete(task.pickupNodeId);
  }

  private topLiftInboundProjectedQueueCompressionNodeIds(
    liftNodeId: string,
    fromNodeId: string,
    targetNodeId: string
  ): string[] {
    const currentSlot = this.topLiftInboundApproachQueueSlot(fromNodeId);
    const pickupStopNodeId = this.topLiftInboundPickupStopNodeId(liftNodeId);
    if (
      !currentSlot ||
      currentSlot.liftNodeId !== liftNodeId ||
      !pickupStopNodeId ||
      targetNodeId !== pickupStopNodeId
    ) {
      return [];
    }
    return [
      ...this.topLiftInboundApproachQueueNodeIds(liftNodeId).filter((nodeId) => {
        const slot = this.topLiftInboundApproachQueueSlot(nodeId);
        return Boolean(slot && slot.liftNodeId === liftNodeId && slot.slotIndex < currentSlot.slotIndex);
      }),
      pickupStopNodeId
    ];
  }

  private activeTopLiftOutboundDockBlockedNodeIds(requesterVehicleId: string): Set<string> {
    const activeOutboundLiftNodeIds = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (vehicle.id === requesterVehicleId) {
        continue;
      }
      const task = this.taskForVehicle(vehicle);
      if (
        task?.kind === 'outbound' &&
        task.completedAtSec === null &&
        (vehicle.loaded || vehicle.state === 'lowering' || task.state === 'in-progress')
      ) {
        const liftNodeId = this.taskLiftPortNodeId(task);
        if (liftNodeId && this.liftPortKindForNodeId(liftNodeId) === 'outbound') {
          activeOutboundLiftNodeIds.add(liftNodeId);
        }
      }
    }
    const blockedNodeIds = this.activeTopLiftOutboundDockSweepBlockedNodeIds(requesterVehicleId);
    if (activeOutboundLiftNodeIds.size === 0) {
      return blockedNodeIds;
    }
    for (const node of this.scenario.layout.nodes) {
      const dockLiftNodeId = this.topLiftOutboundDockBottomCorridorNodeLiftNodeId(node.id);
      if (dockLiftNodeId && activeOutboundLiftNodeIds.has(dockLiftNodeId)) {
        blockedNodeIds.add(node.id);
      }
    }
    return blockedNodeIds;
  }

  private applyTopLiftInboundTopLaneCorridorBlocks(
    blockedNodeIds: Set<string>,
    fromNodeId: string,
    targetNodeId: string
  ): void {
    const fromLevel = topLiftAisleLevel(fromNodeId);
    if (fromLevel !== 'top-a' && fromLevel !== 'top-b') {
      return;
    }
    const targetLiftNodeId = this.topLiftProjectedInboundLiftNodeId(targetNodeId);
    if (!targetLiftNodeId) {
      return;
    }
    for (const node of this.scenario.layout.nodes) {
      const level = topLiftAisleLevel(node.id);
      if (level === 'middle' || level === 'bottom-a' || level === 'bottom-b') {
        blockedNodeIds.add(node.id);
      }
    }
  }

  private topLiftInboundEmptyApproachStrictPathRequired(
    fromNodeId: string,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (!this.topLiftInboundEmptyApproachLiftNodeId(task, goalNodeId)) {
      return false;
    }
    const fromLevel = topLiftAisleLevel(fromNodeId);
    return fromLevel === 'top-a' || fromLevel === 'top-b';
  }

  private topLiftInboundEmptyApproachLiftNodeId(task: TaskStateRecord, goalNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound') {
      return null;
    }
    const taskLiftNodeId = this.taskLiftPortNodeId(task);
    if (!taskLiftNodeId || this.liftPortKindForNodeId(taskLiftNodeId) !== 'inbound') {
      return null;
    }
    const targetLiftNodeId =
      this.topLiftProjectedInboundLiftNodeId(goalNodeId) ??
      this.topLiftInboundLiftContextForNode(goalNodeId);
    if (!targetLiftNodeId || targetLiftNodeId !== taskLiftNodeId) {
      return null;
    }
    return targetLiftNodeId;
  }

  private topLiftInboundEmptyApproachRouteAllowed(
    routeNodeIds: string[] | null,
    fromNodeId: string,
    task: TaskStateRecord,
    goalNodeId: string
  ): boolean {
    if (!routeNodeIds || !this.topLiftInboundEmptyApproachLiftNodeId(task, goalNodeId)) {
      return true;
    }
    const strictTopStart = this.topLiftInboundEmptyApproachStrictPathRequired(fromNodeId, task, goalNodeId);
    let sawTopLevel = false;
    let leftTopLevel = false;
    for (const nodeId of routeNodeIds) {
      const level = topLiftAisleLevel(nodeId);
      const isTopLevel = level === 'top-a' || level === 'top-b';
      const isLowerLevel = level === 'middle' || level === 'bottom-a' || level === 'bottom-b';
      if (isTopLevel) {
        if (leftTopLevel) {
          return false;
        }
        sawTopLevel = true;
      }
      if (isLowerLevel) {
        if (strictTopStart || sawTopLevel) {
          leftTopLevel = true;
        }
      }
    }
    return !leftTopLevel;
  }

  private topLiftOutboundFaceKeepoutNodeIds(): Set<string> {
    const nodeIds = new Set<string>();
    if (!this.topLiftColumnLayoutEnabled()) {
      return nodeIds;
    }
    for (const liftNode of this.outboundLiftNodes()) {
      const firstEntryNodeId = liftQueueTailEntryNodeId(liftNode.id, 1);
      const entryApproachNodeId = this.topLiftQueueEntryTopAccessNodeId(firstEntryNodeId);
      const entryExitNodeId = this.topLiftQueueEntryBottomAccessNodeId(firstEntryNodeId);
      const serviceNodeId = liftQueueServiceExitNodeId(liftNode.id, 1);
      const anchors = [
        entryApproachNodeId,
        entryExitNodeId,
        serviceNodeId,
        liftNode.id
      ]
        .map((nodeId) => nodeId ? this.layoutNode(nodeId) : null)
        .filter((node): node is LayoutNode => node !== null);
      if (anchors.length === 0) {
        continue;
      }
      const minX = Math.min(...anchors.map((node) => node.x)) - this.scenario.vehicles.lengthM;
      const maxX = Math.max(...anchors.map((node) => node.x)) + this.scenario.vehicles.lengthM;
      for (const node of this.scenario.layout.nodes) {
        const level = topLiftAisleLevel(node.id);
        if (
          (level === 'bottom-a' || level === 'bottom-b') &&
          node.x >= minX - 1e-6 &&
          node.x <= maxX + 1e-6
        ) {
          nodeIds.add(node.id);
        }
      }
    }
    return nodeIds;
  }

  private topLiftNearestStorageColumnAccessNodeId(storageNodeId: string): string | null {
    const position = this.storageGridPosition(storageNodeId);
    if (!position || !this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    const zoneRow = position.row <= rowsPerZone ? position.row : position.row - rowsPerZone;
    const nearRightEntry = zoneRow <= (rowsPerZone + 1) / 2;
    return this.storageSideNodeId(storageNodeId, nearRightEntry ? 'right' : 'left') ??
      this.storageSideNodeId(storageNodeId, nearRightEntry ? 'left' : 'right');
  }

  private agentRefreshLoadedOutboundRouteToDropoff(currentNodeId: string, task: TaskStateRecord, goalNodeId = task.dropoffNodeId): string[] | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }

    const liftNodeId = goalNodeId === task.dropoffNodeId ? this.taskLiftPortNodeId(task) : null;
    const routePrefixes = this.isStorageNode(currentNodeId)
      ? [this.topLiftLoadedOutboundStorageExitRoute(currentNodeId)].filter((route): route is string[] => route !== null)
      : [[currentNodeId]];
    if (routePrefixes.length === 0) {
      return null;
    }

    const planFromPrefix = (routePrefix: string[]): string[] | null => {
      const route: string[] = [...routePrefix];
      const routeStartNodeId = route[route.length - 1]!;
      const queueServiceTargets = liftNodeId
        ? this.topLiftQueueServiceTargets(routeStartNodeId, liftNodeId, task.dropoffNodeId)
        : null;
      const meterApproachTargets = queueServiceTargets
        ? null
        : this.topLiftOutboundMeterApproachTargets(task, goalNodeId);
      const targets = queueServiceTargets ?? meterApproachTargets ?? [goalNodeId];

      for (const target of targets) {
        if (!target || target === route[route.length - 1]) {
          continue;
        }
        const fromNodeId = route[route.length - 1]!;
        const directColumnExitRoute = this.isStorageNode(fromNodeId)
          ? this.topLiftDirectStorageColumnExitRoute(fromNodeId, target)
          : null;
        if (directColumnExitRoute && !this.routeHasStoredLoadConflict(directColumnExitRoute, new Set([fromNodeId]))) {
          route.push(...directColumnExitRoute.slice(1));
          continue;
        }
        const blockedNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target, { blockStoredLoads: true });
        const vehicleId = task.vehicleId ?? '';
        for (const nodeId of this.activeTopLiftLoadedInboundProtectedNodeIds(vehicleId)) {
          blockedNodeIds.add(nodeId);
        }
        const activeInboundServiceProtectedNodeIds = this.activeTopLiftInboundServiceProtectedNodeIds(vehicleId);
        for (const nodeId of activeInboundServiceProtectedNodeIds) {
          blockedNodeIds.add(nodeId);
        }
        const outboundServiceEntryNodeId = liftNodeId ? liftQueueTailEntryNodeId(liftNodeId, 1) : null;
        const outboundServiceEntryTopNodeId = outboundServiceEntryNodeId
          ? this.topLiftQueueEntryTopAccessNodeId(outboundServiceEntryNodeId)
          : null;
        if (
          liftNodeId &&
          (
            target === this.topLiftOutboundServiceEntryBottomNodeId(liftNodeId) ||
            (activeInboundServiceProtectedNodeIds.size > 0 && target === outboundServiceEntryTopNodeId)
          )
        ) {
          const outboundApproachLevel: TopLiftAisleLevel = this.liftPortKindForNodeId(liftNodeId) === 'outbound'
            ? 'bottom-a'
            : 'top-a';
          for (const node of this.scenario.layout.nodes) {
            const verticalSpineTransferNode = new RegExp(`^.+-spine-${outboundApproachLevel}$`).test(node.id);
            if (isTopLiftAisleLevelNodeId(node.id, outboundApproachLevel) && node.id !== fromNodeId && !verticalSpineTransferNode) {
              blockedNodeIds.add(node.id);
            }
          }
        }
        blockedNodeIds.delete(fromNodeId);
        blockedNodeIds.delete(target);
        const segment = this.tryAgentRefreshShortestPath(fromNodeId, target, blockedNodeIds, this.routeTerminalAxis(route));
        if (!segment) {
          return null;
        }
        route.push(...segment.slice(1));
      }

      const expandedRoute = route.length > 1 ? this.agentRefreshExpandLiftColumnSegments(route) : null;
      const liftQueueMeterSlot = goalNodeId === task.dropoffNodeId ? null : this.topLiftOutboundMeterSlot(goalNodeId);
      if (liftQueueMeterSlot && liftQueueMeterSlot.liftNodeId === this.taskLiftPortNodeId(task)) {
        return expandedRoute;
      }
      return this.enforceTaskTopLiftWorkcellRouteContract(expandedRoute, task, 'outbound-loaded-approach');
    };

    for (const routePrefix of routePrefixes) {
      const route = planFromPrefix(routePrefix);
      if (route && route.length > 1 && route.at(-1) === goalNodeId) {
        return route;
      }
    }
    return null;
  }

  private topLiftOutboundMeterApproachTargets(task: TaskStateRecord, goalNodeId: string): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'outbound') {
      return null;
    }
    const meterSlot = this.topLiftOutboundMeterSlot(goalNodeId);
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!meterSlot || !liftNodeId || meterSlot.liftNodeId !== liftNodeId) {
      return null;
    }
    const meterColumn = this.topLiftColumnAccessColumn(goalNodeId);
    if (!meterColumn) {
      return null;
    }
    const approachNodeId = columnAccessNodeId('bottom-a', meterColumn - 1);
    if (!this.layoutNode(approachNodeId) || !this.traffic.findEdge(approachNodeId, goalNodeId)) {
      return null;
    }
    return [approachNodeId, goalNodeId];
  }

  private agentRefreshLoadedInboundRouteToDropoff(currentNodeId: string, task: TaskStateRecord): string[] {
    const route: string[] = [currentNodeId];
    const serviceExitRoute = this.topLiftInboundLoadedServiceExitRoute(currentNodeId, task);
    if (serviceExitRoute) {
      route.push(...serviceExitRoute.slice(1));
    }
    const topBExitRoute = this.isInboundOnlyFlow() ? this.topLiftInboundTopBExitRoute(route[route.length - 1]!) : null;
    if (topBExitRoute) {
      route.push(...topBExitRoute.slice(1));
    }
    const topLaneTransferRoute = this.topLiftLoadedInboundTopLaneTransferRoute(route[route.length - 1]!, task, true);
    if (topLaneTransferRoute) {
      route.push(...topLaneTransferRoute.slice(1));
    }
    const directColumnDropoffRoute = this.topLiftLoadedInboundDirectStorageColumnDropoffRoute(route[route.length - 1]!, task);
    if (directColumnDropoffRoute) {
      route.push(...directColumnDropoffRoute.slice(1));
      return this.enforceTaskTopLiftWorkcellRouteContract(route, task, 'inbound-loaded-departure')!;
    }
    const lowerBankMiddleEntryRoute = this.agentRefreshLoadedInboundLowerBankMiddleEntryRoute(route, task);
    if (lowerBankMiddleEntryRoute) {
      return this.enforceTaskTopLiftWorkcellRouteContract(lowerBankMiddleEntryRoute, task, 'inbound-loaded-departure')!;
    }
    const dropoffRowLabel = this.nodeStorageRowLabel(task.dropoffNodeId);
    const routeStartNodeId = route[route.length - 1]!;
    const currentRowLabel = this.nodeStorageRowLabel(routeStartNodeId);
    const alreadyInsideDropoffRow = this.isStorageNode(routeStartNodeId) && currentRowLabel !== null && currentRowLabel === dropoffRowLabel;
    const currentStorageExitNodeId = this.isStorageNode(routeStartNodeId) && currentRowLabel !== dropoffRowLabel
      ? this.storageSideNodeId(routeStartNodeId, 'right') ?? this.nearestStorageSideNodeId(routeStartNodeId)
      : null;
    const candidateLiftRowTransferNodeId = alreadyInsideDropoffRow ? null : this.agentRefreshLiftRowTransferNodeId(routeStartNodeId, task.dropoffNodeId);
    const liftRowTransferNodeId = candidateLiftRowTransferNodeId && this.agentRefreshLoadedInboundSegmentAvailable(candidateLiftRowTransferNodeId, task.dropoffNodeId, task)
      ? candidateLiftRowTransferNodeId
      : null;
    const preEntryTargets = alreadyInsideDropoffRow
      ? []
      : [
          currentStorageExitNodeId,
          liftRowTransferNodeId
        ];

    for (const target of preEntryTargets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      try {
        this.appendAgentRefreshLoadedInboundSegment(route, target, task);
      } catch (error) {
        const fallbackRoute = target === task.dropoffNodeId
          ? this.agentRefreshLoadedInboundEntryFallbackRoute(fromNodeId, task)
          : null;
        if (!fallbackRoute) {
          throw error;
        }
        route.push(...fallbackRoute.slice(1));
        return this.enforceTaskTopLiftWorkcellRouteContract(route, task, 'inbound-loaded-departure')!;
      }
    }

    if (!alreadyInsideDropoffRow && !liftRowTransferNodeId) {
      const entryRoute = this.agentRefreshLoadedInboundBestEntryRoute(route, task);
      if (entryRoute) {
        return this.enforceTaskTopLiftWorkcellRouteContract(entryRoute, task, 'inbound-loaded-departure')!;
      }
    }

    if (task.dropoffNodeId !== route[route.length - 1]) {
      const fromNodeId = route[route.length - 1]!;
      try {
        this.appendAgentRefreshLoadedInboundSegment(route, task.dropoffNodeId, task);
      } catch (error) {
        const fallbackRoute = this.agentRefreshLoadedInboundEntryFallbackRoute(fromNodeId, task);
        if (!fallbackRoute) {
          throw error;
        }
        route.push(...fallbackRoute.slice(1));
      }
    }

    return this.enforceTaskTopLiftWorkcellRouteContract(route, task, 'inbound-loaded-departure')!;
  }

  private agentRefreshLoadedInboundRouteViaTopLane(
    currentNodeId: string,
    task: TaskStateRecord,
    includeLowerBank: boolean
  ): string[] | null {
    const route = this.topLiftLoadedInboundTopLaneTransferRoute(currentNodeId, task, includeLowerBank);
    if (!route || route.length <= 1) {
      return null;
    }
    if (route[route.length - 1] !== task.dropoffNodeId) {
      try {
        this.appendAgentRefreshLoadedInboundSegment(route, task.dropoffNodeId, task);
      } catch {
        return null;
      }
    }
    return route.length > 1 ? route : null;
  }

  private agentRefreshLoadedInboundLowerBankMiddleEntryRoute(routePrefix: string[], task: TaskStateRecord): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound' || routePrefix.length === 0) {
      return null;
    }
    const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
    const rowsPerZone = this.topLiftColumnRowsPerZone();
    if (!dropoffPosition || dropoffPosition.row <= rowsPerZone) {
      return null;
    }

    const entryNodeId = this.storageSideNodeId(task.dropoffNodeId, 'right');
    if (!entryNodeId || !this.layoutNode(entryNodeId)) {
      return null;
    }

    const route = [...routePrefix];
    const fromNodeId = route[route.length - 1]!;
    if (fromNodeId !== entryNodeId) {
      const blockedNodeIds = this.agentRefreshLoadedInboundBlockedNodeIds(fromNodeId, entryNodeId, task);
      for (const nodeId of this.topLiftStorageColumnNodeIds(dropoffPosition.column)) {
        if (nodeId !== fromNodeId && nodeId !== task.dropoffNodeId) {
          blockedNodeIds.add(nodeId);
        }
      }
      blockedNodeIds.delete(fromNodeId);
      blockedNodeIds.delete(entryNodeId);
      const segment = this.tryAgentRefreshShortestPath(fromNodeId, entryNodeId, blockedNodeIds, this.routeTerminalAxis(route));
      if (!segment) {
        return null;
      }
      route.push(...segment.slice(1));
    }

    if (route[route.length - 1] !== task.dropoffNodeId) {
      if (!this.traffic.findEdge(route[route.length - 1]!, task.dropoffNodeId)) {
        return null;
      }
      route.push(task.dropoffNodeId);
    }
    return route.length > 1 ? route : null;
  }

  private topLiftLoadedInboundTopLaneTransferRoute(
    currentNodeId: string,
    task: TaskStateRecord,
    includeLowerBank = false
  ): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound') {
      return null;
    }
    const targetPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!targetPosition || (!includeLowerBank && targetPosition.row > this.topLiftColumnRowsPerZone())) {
      return null;
    }
    const currentColumn = this.topLiftColumnAccessColumn(currentNodeId);
    if (!currentColumn || currentColumn === targetPosition.column) {
      return null;
    }
    const currentLevel = topLiftAisleLevel(currentNodeId);
    if (currentLevel !== 'top-b' && currentLevel !== 'top-a') {
      return null;
    }

    const route = [currentNodeId];
    if (currentLevel === 'top-a') {
      route.push(columnAccessNodeId('top-b', currentColumn - 1));
    }
    const direction = Math.sign(targetPosition.column - currentColumn);
    for (let column = currentColumn + direction; column !== targetPosition.column + direction; column += direction) {
      route.push(columnAccessNodeId('top-b', column - 1));
    }

    return route.every((nodeId) => this.layoutNode(nodeId)) &&
      this.routeEdgesExist(route)
      ? route
      : null;
  }

  private topLiftInboundLoadedServiceExitRoute(currentNodeId: string, task: TaskStateRecord): string[] | null {
    if (!this.topLiftColumnLayoutEnabled() || task.kind !== 'inbound' || !task.pickupNodeId) {
      return null;
    }
    const pickupServiceSlot = topLiftQueueServiceSlot(task.pickupNodeId);
    const pickupBuffer = liftBufferParentNodeId(task.pickupNodeId);
    const liftNodeId = pickupServiceSlot?.liftNodeId ?? pickupBuffer?.liftNodeId ?? null;
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return null;
    }
    const serviceSlotIndex = pickupServiceSlot?.slotIndex ?? 1;
    const serviceExitNodeId = pickupServiceSlot ? task.pickupNodeId : liftQueueServiceExitNodeId(liftNodeId, serviceSlotIndex);
    const entryNodeId = liftQueueTailEntryNodeId(liftNodeId, serviceSlotIndex);
    if (!this.layoutNode(serviceExitNodeId) || !this.layoutNode(entryNodeId)) {
      return null;
    }

    const entryExitRoute = this.topLiftInboundQueueExitRoute(entryNodeId, task);
    const bufferAccessNodeId = liftBufferAccessNodeId(liftNodeId);
    const currentAtServiceNode = currentNodeId === serviceExitNodeId ||
      (pickupServiceSlot !== null && currentNodeId === task.pickupNodeId);
    const currentAtPickupBuffer = pickupServiceSlot === null && currentNodeId === task.pickupNodeId;
    const route =
      currentNodeId === entryNodeId ? [currentNodeId] :
      currentAtServiceNode ? [
        currentNodeId,
        entryNodeId
      ] :
      currentAtPickupBuffer && this.traffic.findEdge(currentNodeId, serviceExitNodeId) ? [
        currentNodeId,
        serviceExitNodeId,
        entryNodeId
      ] :
      this.layoutNode(bufferAccessNodeId) && currentAtPickupBuffer ? [
        currentNodeId,
        bufferAccessNodeId,
        serviceExitNodeId,
        entryNodeId
      ] :
      this.layoutNode(bufferAccessNodeId) && currentNodeId === bufferAccessNodeId ? [
        currentNodeId,
        serviceExitNodeId,
        entryNodeId
      ] :
      null;
    if (!route) {
      return null;
    }
    if (entryExitRoute && route.at(-1) === entryNodeId) {
      route.push(...entryExitRoute.slice(1));
    }
    if (route.length < 2) {
      return null;
    }
    for (let index = 1; index < route.length; index += 1) {
      if (!this.traffic.findEdge(route[index - 1]!, route[index]!)) {
        return null;
      }
    }
    return route;
  }

  private topLiftInboundQueueExitRoute(entryNodeId: string, task: TaskStateRecord): string[] | null {
    const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
    if (!dropoffPosition || dropoffPosition.row > this.topLiftColumnRowsPerZone()) {
      return this.topLiftInboundQueueEntryDownRoute(entryNodeId);
    }

    const entryNode = this.layoutNode(entryNodeId);
    if (!entryNode) {
      return null;
    }
    const downRoute = this.isInboundOnlyFlow() ? this.topLiftInboundQueueEntryDownRoute(entryNodeId) : null;
    if (downRoute) {
      return downRoute;
    }
    const topBColumnNode = this.scenario.layout.nodes.find((node) =>
      /^column-top-b-c\d+$/.test(node.id) &&
      Math.abs(node.x - entryNode.x) < 1e-6
    );
    const columnMatch = topBColumnNode ? /^column-top-b-c(\d+)$/.exec(topBColumnNode.id) : null;
    if (!topBColumnNode || !columnMatch) {
      return null;
    }
    const columnIndex = Number(columnMatch[1]!) - 1;
    if (!Number.isInteger(columnIndex) || columnIndex < 0) {
      return null;
    }

    if (this.isInboundOnlyFlow()) {
      const spineTopBNodeId = this.neighbors(topBColumnNode.id).find((neighbor) =>
        /^module-\d{2}-spine-top-b$/.test(neighbor.nodeId)
      )?.nodeId ?? null;
      const spineMiddleNodeId = spineTopBNodeId?.replace('-top-b', '-middle') ?? null;
      const spineExitRoute = [entryNodeId, topBColumnNode.id, spineTopBNodeId, spineMiddleNodeId]
        .filter((nodeId): nodeId is string => Boolean(nodeId));
      if (spineExitRoute.length === 4 && this.routeEdgesExist(spineExitRoute)) {
        return spineExitRoute;
      }
    }

    const route = [
      entryNodeId,
      topBColumnNode.id
    ];
    return route.every((nodeId) => this.layoutNode(nodeId)) &&
      route.slice(1).every((nodeId, index) => this.traffic.findEdge(route[index]!, nodeId))
      ? route
      : null;
  }

  private topLiftInboundQueueEntryDownRoute(entryNodeId: string): string[] | null {
    const entryNode = this.layoutNode(entryNodeId);
    if (!entryNode) {
      return null;
    }
    const topBColumnNode = this.scenario.layout.nodes.find((node) =>
      /^column-top-b-c\d+$/.test(node.id) &&
      Math.abs(node.x - entryNode.x) < 1e-6
    );
    const columnMatch = topBColumnNode ? /^column-top-b-c(\d+)$/.exec(topBColumnNode.id) : null;
    if (!topBColumnNode || !columnMatch) {
      return null;
    }
    const columnIndex = Number(columnMatch[1]!) - 1;
    if (!Number.isInteger(columnIndex) || columnIndex < 0) {
      return null;
    }
    const storageNodeIds = Array.from({ length: this.topLiftColumnRowsPerZone() }, (_, rowIndex) =>
      storageNodeId(rowIndex, columnIndex)
    );
    const storedLoadNodeIds = this.storageNodeLoadOccupancy(false);
    if (storageNodeIds.some((nodeId) => storedLoadNodeIds.has(nodeId))) {
      return null;
    }
    const route = [
      entryNodeId,
      topBColumnNode.id,
      ...storageNodeIds,
      columnAccessNodeId('middle', columnIndex)
    ];
    return route.every((nodeId) => this.layoutNode(nodeId)) ? route : null;
  }

  private topLiftInboundTopBExitRoute(topBNodeId: string): string[] | null {
    const topBMatch = /^column-top-b-c(\d+)$/.exec(topBNodeId);
    if (!topBMatch) {
      return null;
    }
    const columnIndex = Number(topBMatch[1]!) - 1;
    if (!Number.isInteger(columnIndex) || columnIndex < 0) {
      return null;
    }
    const storageNodeIds = Array.from({ length: this.topLiftColumnRowsPerZone() }, (_, rowIndex) =>
      storageNodeId(rowIndex, columnIndex)
    );
    const storedLoadNodeIds = this.storageNodeLoadOccupancy(false);
    if (!storageNodeIds.some((nodeId) => storedLoadNodeIds.has(nodeId))) {
      const downRoute = [
        topBNodeId,
        ...storageNodeIds,
        columnAccessNodeId('middle', columnIndex)
      ];
      if (downRoute.every((nodeId) => this.layoutNode(nodeId))) {
        return downRoute;
      }
    }
    const spineTopBNodeId = this.neighbors(topBNodeId).find((neighbor) =>
      /^module-\d{2}-spine-top-b$/.test(neighbor.nodeId)
    )?.nodeId ?? null;
    const spineMiddleNodeId = spineTopBNodeId?.replace('-top-b', '-middle') ?? null;
    const spineRoute = [topBNodeId, spineTopBNodeId, spineMiddleNodeId]
      .filter((nodeId): nodeId is string => Boolean(nodeId));
    return spineRoute.length === 3 && this.routeEdgesExist(spineRoute) ? spineRoute : null;
  }

  private appendAgentRefreshLoadedInboundSegment(
    route: string[],
    target: string,
    task: TaskStateRecord
  ): void {
    const fromNodeId = route[route.length - 1]!;
    const blockedStorageNodeIds = this.agentRefreshLoadedInboundBlockedNodeIds(fromNodeId, target, task);
    blockedStorageNodeIds.delete(fromNodeId);
    blockedStorageNodeIds.delete(target);
    blockedStorageNodeIds.delete(task.pickupNodeId);
    blockedStorageNodeIds.delete(task.dropoffNodeId);
    const segment = this.agentRefreshShortestPath(fromNodeId, target, blockedStorageNodeIds, this.routeTerminalAxis(route));
    route.push(...segment.slice(1));
  }

  private agentRefreshLoadedInboundBlockedNodeIds(
    fromNodeId: string,
    target: string,
    task: TaskStateRecord
  ): Set<string> {
    const blockedNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target, { blockStoredLoads: true });
    if (!this.topLiftColumnLayoutEnabled()) {
      return blockedNodeIds;
    }

    const inboundSourceBuffer = liftBufferParentNodeId(fromNodeId);
    if (inboundSourceBuffer?.kind === 'inbound') {
      for (const node of this.scenario.layout.nodes) {
        const sameLiftEntryAccess = new RegExp(`^${inboundSourceBuffer.liftNodeId}-queue-\\d{2}-entry-access$`).test(node.id);
        if (sameLiftEntryAccess) {
          continue;
        }
        if (
          isTopLiftQueueParkingNodeId(node.id) ||
          /^(lift-\d{2}-(?:inbound|outbound))-queue(?:-\d{2})?-(?:entry-)?access$/.test(node.id) ||
          /^lift-\d{2}-(?:inbound|outbound)-queue-pickup-access$/.test(node.id)
        ) {
          blockedNodeIds.add(node.id);
        }
      }
    }

    const allowedColumnKeys = new Set<string>();
    for (const nodeId of [fromNodeId, target, task.dropoffNodeId]) {
      const columnKey = this.topLiftColumnKey(nodeId);
      if (columnKey) {
        allowedColumnKeys.add(columnKey);
      }
    }
    const occupiedStorageNodeIds = this.storageNodeLoadOccupancyForTaskReachability(task);
    const routeAllowedStorageNodeIds = new Set([fromNodeId, target, task.dropoffNodeId]);
    for (const nodeId of occupiedStorageNodeIds.keys()) {
      if (!routeAllowedStorageNodeIds.has(nodeId)) {
        blockedNodeIds.add(nodeId);
      }
    }
    for (const [nodeId] of this.currentNodeOccupancy) {
      if (this.isStorageNode(nodeId) && !routeAllowedStorageNodeIds.has(nodeId)) {
        blockedNodeIds.add(nodeId);
      }
    }

    for (const node of this.scenario.layout.nodes) {
      if (node.type !== 'storage') {
        continue;
      }
      const columnKey = this.topLiftColumnKey(node.id);
      if (!columnKey || !allowedColumnKeys.has(columnKey)) {
        blockedNodeIds.add(node.id);
        continue;
      }
      if (
        !occupiedStorageNodeIds.has(node.id) &&
        (!this.currentNodeOccupancy.has(node.id) || node.id === fromNodeId || node.id === target || node.id === task.dropoffNodeId)
      ) {
        blockedNodeIds.delete(node.id);
      }
    }
    return blockedNodeIds;
  }

  private agentRefreshLoadedInboundSegmentAvailable(
    fromNodeId: string,
    target: string,
    task: TaskStateRecord
  ): boolean {
    const route = [fromNodeId];
    try {
      this.appendAgentRefreshLoadedInboundSegment(route, target, task);
      return true;
    } catch {
      return false;
    }
  }

  private agentRefreshLoadedInboundEntryFallbackRoute(
    fromNodeId: string,
    task: TaskStateRecord
  ): string[] | null {
    const entryNodeIds = this.agentRefreshLoadedInboundEntryCandidateNodeIds(task);
    const fromLiftId = this.liftStorageTransferTargetLiftId(fromNodeId);
    const candidateRoutes: string[][] = [];
    for (const entryNodeId of entryNodeIds) {
      const route = [fromNodeId];
      const targets = [
        fromLiftId,
        entryNodeId,
        task.dropoffNodeId
      ];
      try {
        for (const target of targets) {
          if (!target || target === route[route.length - 1]) {
            continue;
          }
          this.appendAgentRefreshLoadedInboundSegment(route, target, task);
        }
        candidateRoutes.push(route);
      } catch {
        continue;
      }
    }
    return this.shortestRouteByDistance(candidateRoutes);
  }

  private agentRefreshLoadedInboundBestEntryRoute(routePrefix: string[], task: TaskStateRecord): string[] | null {
    const candidateRoutes: string[][] = [];
    for (const entryNodeId of this.agentRefreshLoadedInboundEntryCandidateNodeIds(task)) {
      const route = [...routePrefix];
      try {
        if (entryNodeId !== route[route.length - 1]) {
          this.appendAgentRefreshLoadedInboundSegment(route, entryNodeId, task);
        }
        if (task.dropoffNodeId !== route[route.length - 1]) {
          this.appendAgentRefreshLoadedInboundSegment(route, task.dropoffNodeId, task);
        }
        candidateRoutes.push(route);
      } catch {
        continue;
      }
    }
    return this.shortestRouteByDistance(candidateRoutes);
  }

  private shortestRouteByDistance(routes: string[][]): string[] | null {
    return routes
      .filter((route) => route.length > 1)
      .sort((left, right) =>
        this.routePlannerCostM(left) - this.routePlannerCostM(right) ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.length - right.length ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;
  }

  private agentRefreshLoadedInboundEntryCandidateNodeIds(task: TaskStateRecord): string[] {
    return [
      this.topLiftNearestStorageColumnAccessNodeId(task.dropoffNodeId),
      this.storageSideNodeId(task.dropoffNodeId, 'right'),
      this.storageSideNodeId(task.dropoffNodeId, 'left')
    ].filter((nodeId, index, nodeIds): nodeId is string => Boolean(nodeId) && nodeIds.indexOf(nodeId) === index);
  }

  private agentRefreshLiftRowTransferNodeId(currentNodeId: string, storageNodeId: string): string | null {
    const liftId = this.layoutNode(currentNodeId)?.type === 'lift-blackbox'
      ? currentNodeId
      : this.liftStorageTransferTargetLiftId(currentNodeId);
    const storagePosition = this.storageGridPosition(storageNodeId);
    if (!liftId || !storagePosition) {
      return null;
    }
    const transferNodeId = `${liftId}-row-${String(storagePosition.row).padStart(2, '0')}-transfer`;
    return this.layoutNode(transferNodeId) ? transferNodeId : null;
  }

  private agentRefreshExpandLiftColumnSegments(route: string[]): string[] {
    if (route.length < 2) {
      return route;
    }

    const expanded = [route[0]!];
    for (let index = 1; index < route.length; index += 1) {
      const fromNodeId = expanded[expanded.length - 1]!;
      const toNodeId = route[index]!;
      const segment = this.agentRefreshLiftColumnSegment(fromNodeId, toNodeId);
      expanded.push(...(segment ? segment.slice(1) : [toNodeId]));
    }
    return expanded;
  }

  private agentRefreshLiftColumnSegment(fromNodeId: string, toNodeId: string): string[] | null {
    if (
      topLiftQueueParkingSlot(fromNodeId) ||
      topLiftQueueParkingSlot(toNodeId) ||
      /^lift-\d{2}-(?:inbound|outbound)-queue-access$/.test(fromNodeId) ||
      /^lift-\d{2}-(?:inbound|outbound)-queue-access$/.test(toNodeId)
    ) {
      return null;
    }
    const fromInfo = this.liftColumnNodeInfo(fromNodeId);
    const toInfo = this.liftColumnNodeInfo(toNodeId);
    const liftId = fromInfo?.liftId ?? toInfo?.liftId ?? null;
    if (!liftId || fromInfo?.liftId !== liftId || toInfo?.liftId !== liftId) {
      return null;
    }
    if (!this.traffic.findEdge(fromNodeId, toNodeId)) {
      return null;
    }

    const from = nodePosition(this.scenario, fromNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    if (Math.abs(from.x - to.x) > 1e-6 || Math.abs(from.z - to.z) <= 1e-6) {
      return null;
    }

    const minZ = Math.min(from.z, to.z);
    const maxZ = Math.max(from.z, to.z);
    const nodes = this.scenario.layout.nodes
      .filter((node) =>
        this.liftColumnNodeInfo(node.id)?.liftId === liftId &&
        Math.abs(node.x - from.x) <= 1e-6 &&
        node.z >= minZ - 1e-6 &&
        node.z <= maxZ + 1e-6
      )
      .sort((left, right) => from.z <= to.z
        ? left.z - right.z || left.id.localeCompare(right.id)
        : right.z - left.z || left.id.localeCompare(right.id)
      )
      .map((node) => node.id);

    if (nodes[0] !== fromNodeId || nodes.at(-1) !== toNodeId || nodes.length < 2) {
      return null;
    }
    return nodes;
  }

  private liftColumnNodeInfo(nodeId: string): { liftId: string } | null {
    const node = this.layoutNode(nodeId);
    if (node?.type === 'lift-blackbox') {
      return { liftId: nodeId };
    }
    const liftId = this.liftStorageTransferTargetLiftId(nodeId);
    return liftId ? { liftId } : null;
  }

  private agentRefreshBlockedNodeIds(vehicle: MutableVehicle, task: TaskStateRecord | null, goalNodeId: string): Set<string> {
    const applyTopLiftAuxiliaryBlocks = (blocked: Set<string>, keepBlocked = new Set<string>()): Set<string> => {
      if (!this.topLiftColumnLayoutEnabled()) {
        return blocked;
      }
      for (const node of this.scenario.layout.nodes) {
        if (
          /^lift-\d{2}-(?:inbound|outbound)-throat$/.test(node.id) ||
          /^lift-\d{2}-(?:inbound|outbound)-buffer-access$/.test(node.id) ||
          /^lift-\d{2}-(?:inbound|outbound)-queue-access$/.test(node.id)
        ) {
          blocked.add(node.id);
        }
      }
      blocked.delete(vehicle.currentNodeId);
      blocked.delete(goalNodeId);
      if (task) {
        blocked.delete(task.pickupNodeId);
        if (!keepBlocked.has(task.dropoffNodeId)) {
          blocked.delete(task.dropoffNodeId);
        }
      }
      return blocked;
    };

    if (!vehicle.loaded) {
      const blocked = this.activeTopLiftInboundTransitBlockedNodeIds(vehicle, task, goalNodeId);
      const activeOutboundDockSweepBlocks = this.activeTopLiftOutboundDockSweepBlockedNodeIds(vehicle.id);
      for (const nodeId of activeOutboundDockSweepBlocks) {
        blocked.add(nodeId);
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        task?.kind === 'outbound' &&
        goalNodeId === task.pickupNodeId
      ) {
        for (const node of this.scenario.layout.nodes) {
          if (isTopLiftAisleLevelNodeId(node.id, 'top-a')) {
            blocked.add(node.id);
          }
        }
        blocked.delete(vehicle.currentNodeId);
        blocked.delete(goalNodeId);
      }
      return applyTopLiftAuxiliaryBlocks(blocked, activeOutboundDockSweepBlocks);
    }

    if (task?.kind === 'outbound' && goalNodeId === task.dropoffNodeId) {
      return applyTopLiftAuxiliaryBlocks(this.blockedStorageTransitNodeIds(vehicle.currentNodeId, goalNodeId, { blockStoredLoads: false }));
    }

    const blocked = this.blockedStorageTransitNodeIds(vehicle.currentNodeId, goalNodeId, { blockStoredLoads: true });
    blocked.delete(vehicle.currentNodeId);
    blocked.delete(goalNodeId);
    if (task) {
      blocked.delete(task.pickupNodeId);
      blocked.delete(task.dropoffNodeId);
    }
    return applyTopLiftAuxiliaryBlocks(blocked);
  }

  private tryAgentRefreshShortestPath(
    fromNodeId: string,
    toNodeId: string,
    blockedNodeIds = new Set<string>(),
    initialAxis: MovementAxis = null
  ): string[] | null {
    try {
      return this.agentRefreshShortestPath(fromNodeId, toNodeId, blockedNodeIds, initialAxis);
    } catch (error) {
      if (error instanceof Error && error.message.startsWith('No route between ')) {
        return null;
      }
      throw error;
    }
  }

  private agentRefreshShortestPath(
    fromNodeId: string,
    toNodeId: string,
    blockedNodeIds = new Set<string>(),
    initialAxis: MovementAxis = null
  ): string[] {
    if (fromNodeId === toNodeId) {
      return [fromNodeId];
    }

    const stateKey = (nodeId: string, axis: MovementAxis): string => `${nodeId}|${axis ?? '-'}`;
    const stateNode = (key: string): string => key.split('|')[0]!;
    const stateAxis = (key: string): MovementAxis => {
      const axis = key.split('|')[1];
      return axis === 'x' || axis === 'z' ? axis : null;
    };
    const open = new MinPriorityQueue();
    const cameFrom = new Map<string, string>();
    const startKey = stateKey(fromNodeId, initialAxis);
    const gScore = new Map<string, number>([[startKey, 0]]);
    open.push({ nodeId: startKey, priority: 0 });

    while (open.size > 0) {
      const next = open.pop();
      if (!next) {
        break;
      }
      const currentKey = next.nodeId;
      if (next.priority > (gScore.get(currentKey) ?? Infinity) + 1e-9) {
        continue;
      }
      const current = stateNode(currentKey);
      const currentAxis = stateAxis(currentKey);
      if (current === toNodeId) {
        const pathKeys = [currentKey];
        while (cameFrom.has(pathKeys[0]!)) {
          pathKeys.unshift(cameFrom.get(pathKeys[0]!)!);
        }
        return pathKeys.map(stateNode);
      }

      for (const neighbor of this.neighbors(current)) {
        if (blockedNodeIds.has(neighbor.nodeId)) {
          continue;
        }
        if (!this.agentEdgeDirectionAllowed(current, neighbor.nodeId, toNodeId)) {
          continue;
        }
        if (neighbor.nodeId !== toNodeId && this.layoutNode(neighbor.nodeId)?.type === 'lift-blackbox') {
          continue;
        }
        const nextAxis = this.axisBetweenNodes(current, neighbor.nodeId);
        const neighborKey = stateKey(neighbor.nodeId, nextAxis ?? currentAxis);
        const tentative = (gScore.get(currentKey) ?? Infinity) +
          this.agentEdgeCostM(current, neighbor.nodeId, neighbor.lengthM, toNodeId) +
          this.turnPenaltyCostM(currentAxis, nextAxis);
        if (tentative < (gScore.get(neighborKey) ?? Infinity)) {
          cameFrom.set(neighborKey, currentKey);
          gScore.set(neighborKey, tentative);
          open.push({ nodeId: neighborKey, priority: tentative });
        }
      }
    }

    throw new Error(`No route between ${fromNodeId} and ${toNodeId}`);
  }

  private agentNominalRouteToGoal(vehicle: MutableVehicle, task: TaskStateRecord | null, goalNodeId: string): string[] {
    if (vehicle.currentNodeId === goalNodeId) {
      return [vehicle.currentNodeId];
    }
    if (task?.kind === 'inbound' && vehicle.loaded && goalNodeId === task.dropoffNodeId) {
      return this.agentLoadedInboundRouteToDropoff(vehicle.currentNodeId, task);
    }
    return this.agentShortestPath(
      vehicle.currentNodeId,
      goalNodeId,
      this.agentStaticBlockedNodeIds(vehicle, goalNodeId)
    );
  }

  private agentLoadedInboundRouteToDropoff(currentNodeId: string, task: TaskStateRecord): string[] {
    const route: string[] = [currentNodeId];
    const rightSideNodeId = this.storageSideNodeId(task.dropoffNodeId, 'right');
    const dropoffRow = this.nodeStorageRowLabel(task.dropoffNodeId);
    const currentRow = this.nodeStorageRowLabel(currentNodeId);
    const alreadyInRightEntryLane =
      currentNodeId === rightSideNodeId ||
      (this.isStorageNode(currentNodeId) && currentRow !== null && currentRow === dropoffRow);
    const targets: Array<string | null> = alreadyInRightEntryLane
      ? [task.dropoffNodeId]
      : [rightSideNodeId, task.dropoffNodeId];

    for (const target of targets) {
      if (!target || target === route[route.length - 1]) {
        continue;
      }
      const fromNodeId = route[route.length - 1]!;
      const blockedStorageNodeIds = this.blockedStorageTransitNodeIds(fromNodeId, target, { blockStoredLoads: true });
      const segment = this.agentShortestPath(fromNodeId, target, blockedStorageNodeIds);
      route.push(...segment.slice(1));
    }
    return route;
  }

  private agentCommittedRoute(vehicle: MutableVehicle, goalNodeId: string): string[] | null {
    const currentIndex = vehicle.routeNodeIds.indexOf(vehicle.currentNodeId, Math.max(0, vehicle.routeIndex));
    if (currentIndex < 0) {
      return null;
    }
    const route = vehicle.routeNodeIds.slice(currentIndex);
    if (route.length < 2 || route[0] !== vehicle.currentNodeId || route.at(-1) !== goalNodeId) {
      return null;
    }
    const nextNodeId = route[1]!;
    if (!this.traffic.findEdge(vehicle.currentNodeId, nextNodeId)) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (vehicle.loaded) {
      const blockedNodeIds = this.agentStaticBlockedNodeIds(vehicle, goalNodeId);
      const goalLiftNodeId = this.topLiftOperationalLiftNodeId(goalNodeId);
      if (
        this.topLiftColumnLayoutEnabled() &&
        goalLiftNodeId &&
        this.liftPortKindForNodeId(goalLiftNodeId) === 'outbound'
      ) {
        for (const nodeId of this.activeTopLiftLoadedInboundProtectedNodeIds(vehicle.id)) {
          blockedNodeIds.add(nodeId);
        }
        blockedNodeIds.delete(vehicle.currentNodeId);
        blockedNodeIds.delete(goalNodeId);
      }
      if (route.slice(1).some((nodeId) => blockedNodeIds.has(nodeId))) {
        return null;
      }
      if (
        this.topLiftColumnLayoutEnabled() &&
        goalLiftNodeId &&
        this.liftPortKindForNodeId(goalLiftNodeId) === 'outbound' &&
        this.activeTopLiftInboundServiceProtectedNodeIds(vehicle.id).size === 0 &&
        this.routeHasSameLevelAisleMove(route, 'top-b')
      ) {
        return null;
      }
    } else if (task?.kind === 'inbound' && this.topLiftColumnLayoutEnabled()) {
      const blockedNodeIds = this.agentRefreshBlockedNodeIds(vehicle, task, goalNodeId);
      this.applyTopLiftInboundPickupApproachBlocks(blockedNodeIds, vehicle, task, vehicle.currentNodeId, goalNodeId);
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(goalNodeId);
      if (route.slice(1).some((nodeId) => blockedNodeIds.has(nodeId))) {
        return null;
      }
    } else if (task?.kind === 'outbound' && this.topLiftColumnLayoutEnabled()) {
      const blockedNodeIds = this.agentRefreshBlockedNodeIds(vehicle, task, goalNodeId);
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(goalNodeId);
      if (route.slice(1).some((nodeId) => blockedNodeIds.has(nodeId))) {
        return null;
      }
    }
    return route;
  }

  private existingRouteTailToGoal(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    goalNodeId: string
  ): string[] | null {
    const currentIndex = vehicle.routeNodeIds.indexOf(vehicle.currentNodeId, Math.max(0, vehicle.routeIndex));
    if (currentIndex < 0) {
      return null;
    }
    const route = vehicle.routeNodeIds.slice(currentIndex);
    if (
      route.length < 2 ||
      route[0] !== vehicle.currentNodeId ||
      route.at(-1) !== goalNodeId ||
      !this.routeEdgesExist(route)
    ) {
      return null;
    }
    for (const nodeId of route.slice(1)) {
      if (!this.isStorageNode(nodeId)) {
        continue;
      }
      const storedLoadId = this.storedLoadIdAtNode(nodeId);
      const isOutboundPickup = task?.kind === 'outbound' && !vehicle.loaded && nodeId === task.pickupNodeId;
      const isInboundDropoff = task?.kind === 'inbound' && vehicle.loaded && nodeId === task.dropoffNodeId;
      if (isOutboundPickup) {
        if (storedLoadId !== task.loadId) {
          return null;
        }
        continue;
      }
      if (isInboundDropoff) {
        if (storedLoadId) {
          return null;
        }
        continue;
      }
      if (storedLoadId) {
        return null;
      }
    }
    return route;
  }

  private routeHasSameLevelAisleMove(routeNodeIds: string[], level: TopLiftAisleLevel): boolean {
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      if (
        topLiftAisleLevel(routeNodeIds[index - 1]!) === level &&
        topLiftAisleLevel(routeNodeIds[index]!) === level
      ) {
        return true;
      }
    }
    return false;
  }

  private agentCommittedYieldRoute(vehicle: MutableVehicle, goalNodeId: string): string[] | null {
    if (vehicle.loaded) {
      return null;
    }
    const currentIndex = vehicle.routeNodeIds.indexOf(vehicle.currentNodeId, Math.max(0, vehicle.routeIndex));
    if (currentIndex < 0) {
      return null;
    }
    const route = vehicle.routeNodeIds.slice(currentIndex);
    if (route.length < 2 || route[0] !== vehicle.currentNodeId || route.at(-1) === goalNodeId) {
      return null;
    }
    if (this.agentMinimalEnabled() && route.length === 2) {
      const nextNodeId = route[1]!;
      return this.traffic.findEdge(vehicle.currentNodeId, nextNodeId) ? route : null;
    }
    const routeGoal = route.at(-1)!;
    if (!this.isStorageNode(routeGoal) && !routeGoal.startsWith('left-row-') && !routeGoal.startsWith('right-row-')) {
      return null;
    }
    const nextNodeId = route[1]!;
    if (!this.traffic.findEdge(vehicle.currentNodeId, nextNodeId)) {
      return null;
    }
    return route;
  }

  private agentStaticBlockedNodeIds(
    vehicle: MutableVehicle,
    goalNodeId: string,
    options: { openStorageRows?: boolean } = {}
  ): Set<string> {
    if (options.openStorageRows === true && !vehicle.loaded) {
      return new Set();
    }
    const blockedNodeIds = this.blockedStorageTransitNodeIds(vehicle.currentNodeId, goalNodeId, { blockStoredLoads: vehicle.loaded });
    const goalLiftNodeId = this.topLiftOperationalLiftNodeId(goalNodeId);
    if (
      this.topLiftColumnLayoutEnabled() &&
      vehicle.loaded &&
      goalLiftNodeId &&
      this.liftPortKindForNodeId(goalLiftNodeId) === 'outbound'
    ) {
      for (const nodeId of this.activeTopLiftInboundServiceProtectedNodeIds(vehicle.id)) {
        blockedNodeIds.add(nodeId);
      }
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(goalNodeId);
    }
    return blockedNodeIds;
  }

  private agentStorageBypassRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    goalNodeId: string,
    blockedNodeId: string,
    directRoute: string[]
  ): string[] | null {
    const entryNodeId = this.agentStorageEntryNodeId(vehicle.currentNodeId);
    if (!entryNodeId) {
      return null;
    }

    try {
      const blockedNodeIds = this.agentStaticBlockedNodeIds(vehicle, goalNodeId, { openStorageRows: true });
      for (const nodeId of this.agentDynamicBlockedNodeIds(vehicle)) {
        blockedNodeIds.add(nodeId);
      }
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(entryNodeId);

      const entrySegment = this.agentShortestPath(vehicle.currentNodeId, entryNodeId, blockedNodeIds);
      if (entrySegment[1] !== entryNodeId || this.agentMoveBlocker(vehicle, entryNodeId)) {
        return null;
      }
      const exitSegment = this.agentShortestPath(entryNodeId, goalNodeId, blockedNodeIds);
      const route = [...entrySegment, ...exitSegment.slice(1)];
      if (!this.agentLocalRerouteAcceptable(directRoute, route)) {
        return null;
      }
      this.logAgentReroute(vehicle, task, blockedNodeId, route, 'empty-storage-row-bypass');
      return route;
    } catch {
      return null;
    }
  }

  private agentLocalRerouteAcceptable(directRoute: string[], candidateRoute: string[]): boolean {
    const allowedRows = new Set(
      [directRoute[0], directRoute.at(-1)]
        .map((nodeId) => nodeId ? this.nodeStorageRowLabel(nodeId) : null)
        .filter((row): row is string => row !== null)
    );
    const storageRows = new Set(
      candidateRoute
        .filter((nodeId) => this.isStorageNode(nodeId))
        .map((nodeId) => this.nodeStorageRowLabel(nodeId))
        .filter((row): row is string => row !== null)
    );
    for (const row of storageRows) {
      if (!allowedRows.has(row)) {
        return false;
      }
    }
    if (this.routeUsesOuterTransfer(candidateRoute)) {
      return false;
    }
    if (this.topLiftColumnLayoutEnabled() || storageRows.size === 0) {
      const directDistanceM = this.routeDistanceM(directRoute);
      const candidateDistanceM = this.routeDistanceM(candidateRoute);
      const extraDistanceM = candidateDistanceM - directDistanceM;
      if (extraDistanceM > 12 && candidateDistanceM > directDistanceM * 1.5) {
        return false;
      }
    }
    return true;
  }

  private routeUsesOuterTransfer(route: string[]): boolean {
    for (let index = 1; index < route.length; index += 1) {
      const edgeKey = [route[index - 1]!, route[index]!].sort().join('>');
      if (edgeKey === 'left-top>right-top' || edgeKey === 'left-bottom>right-bottom') {
        return true;
      }
    }
    return false;
  }

  private agentStorageHeadOnYieldRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    goalNodeId: string,
    blockedNodeId: string | null,
    blockingVehicleId: string
  ): string[] | null {
    if (vehicle.loaded || !blockedNodeId) {
      return null;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockingVehicleId) ?? null;
    if (!blocker || blocker.currentEdgeId || blocker.legRemainingM > 0) {
      return null;
    }
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockedPosition = this.storageGridPosition(blockedNodeId);
    if (
      !currentPosition ||
      !blockedPosition ||
      currentPosition.row !== blockedPosition.row ||
      Math.abs(currentPosition.column - blockedPosition.column) !== 1 ||
      blocker.currentNodeId !== blockedNodeId ||
      blocker.targetNodeId !== vehicle.currentNodeId
    ) {
      return null;
    }

    const vehiclePriority = this.agentTurnPriority(vehicle);
    const blockerPriority = this.agentTurnPriority(blocker);
    if (vehiclePriority > blockerPriority || (vehiclePriority === blockerPriority && vehicle.id.localeCompare(blocker.id) < 0)) {
      return null;
    }

    const yieldSide: 'left' | 'right' = blockedPosition.column > currentPosition.column ? 'left' : 'right';
    const sideNodeId = this.storageSideNodeId(vehicle.currentNodeId, yieldSide);
    if (!sideNodeId) {
      return null;
    }

    try {
      const blockedNodeIds = this.agentStaticBlockedNodeIds(vehicle, goalNodeId);
      for (const nodeId of this.agentDynamicBlockedNodeIds(vehicle)) {
        blockedNodeIds.add(nodeId);
      }
      blockedNodeIds.delete(vehicle.currentNodeId);
      const exitSegment = this.agentShortestPath(vehicle.currentNodeId, sideNodeId, blockedNodeIds);
      const nextNodeId = exitSegment[1] ?? null;
      if (!nextNodeId || nextNodeId === blockedNodeId || this.agentMoveBlocker(vehicle, nextNodeId)) {
        return null;
      }
      const continuationSegment = this.agentShortestPath(sideNodeId, goalNodeId, blockedNodeIds);
      const route = [...exitSegment, ...continuationSegment.slice(1)];
      this.logAgentReroute(vehicle, task, blockedNodeId, route, 'empty-storage-head-on-yield');
      return route;
    } catch {
      return null;
    }
  }

  private agentStorageEntryNodeId(nodeId: string): string | null {
    const sideMatch = /^(left|right)-row-(\d+)$/.exec(nodeId);
    if (!sideMatch) {
      return null;
    }
    const rowNumber = sideMatch[2]!;
    if (sideMatch[1] === 'left') {
      const entryNodeId = `storage-r${rowNumber}-c01`;
      return this.layoutNode(entryNodeId) ? entryNodeId : null;
    }
    const rowColumns = this.scenario.layout.nodes
      .map((node) => this.storageGridPosition(node.id))
      .filter((position): position is { row: number; column: number } => position !== null && String(position.row).padStart(2, '0') === rowNumber)
      .map((position) => position.column);
    const maxColumn = Math.max(0, ...rowColumns);
    if (maxColumn <= 0) {
      return null;
    }
    const entryNodeId = `storage-r${rowNumber}-c${String(maxColumn).padStart(2, '0')}`;
    return this.layoutNode(entryNodeId) ? entryNodeId : null;
  }

  private agentDynamicBlockedNodeIds(vehicle: MutableVehicle): Set<string> {
    const blocked = new Set<string>();
    for (const other of this.vehicles) {
      if (other.id === vehicle.id) {
        continue;
      }
      blocked.add(other.currentNodeId);
      if (other.targetNodeId && other.currentNodeId !== other.targetNodeId) {
        blocked.add(other.targetNodeId);
      }
    }
    blocked.delete(vehicle.currentNodeId);
    return blocked;
  }

  private agentEmptyStorageExitLookaheadBlocker(
    vehicle: MutableVehicle,
    route: string[]
  ): { nodeId: string; blockingVehicleId: string } | null {
    if (vehicle.loaded || route.length < 3) {
      return null;
    }
    const nextNodeId = route[1]!;
    const afterNextNodeId = route[2]!;
    if (!this.isStorageNode(vehicle.currentNodeId) && !this.isStorageNode(nextNodeId)) {
      return null;
    }
    const afterNextIsSideExit = /^left-row-|^right-row-/.test(afterNextNodeId);
    if (!afterNextIsSideExit) {
      return null;
    }
    const blockerId = this.agentNodeBlocker(vehicle, afterNextNodeId);
    return blockerId ? { nodeId: afterNextNodeId, blockingVehicleId: blockerId } : null;
  }

  private agentMoveBlocker(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { reason: string; blockingVehicleId: string | null } | null {
    const fromNodeId = vehicle.currentNodeId;
    const currentOccupant = this.currentNodeOccupancy.get(fromNodeId);
    if (currentOccupant && currentOccupant !== vehicle.id) {
      return { reason: 'node-occupancy-mismatch', blockingVehicleId: currentOccupant };
    }
    const inboundEntryCrossingBlockerId = this.topLiftInboundEntryCrossingBlocker(vehicle, toNodeId);
    if (inboundEntryCrossingBlockerId) {
      return { reason: 'top-lift-entry-crossing', blockingVehicleId: inboundEntryCrossingBlockerId };
    }
    const clearingCurrentId = this.movingVehicleClearingNode(fromNodeId, vehicle);
    if (clearingCurrentId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingCurrentId };
    }

    const nodeClaim = this.agentNodeBlocker(vehicle, toNodeId);
    if (nodeClaim) {
      return { reason: this.liftPortWaitReason(toNodeId) ?? 'node-occupied', blockingVehicleId: nodeClaim };
    }
    const storageExitBlockerId = this.topLiftStorageExitAccessBlocker(vehicle, toNodeId);
    if (storageExitBlockerId) {
      return { reason: 'storage-exit-precedence', blockingVehicleId: storageExitBlockerId };
    }
    const loadedRoutePrecedenceBlockerId = this.topLiftLoadedRoutePrecedenceBlocker(vehicle, toNodeId);
    if (loadedRoutePrecedenceBlockerId) {
      return { reason: 'loaded-route-precedence', blockingVehicleId: loadedRoutePrecedenceBlockerId };
    }
    const projectedDisplayBlockerId = this.topLiftProjectedDisplayMoveBlocker(vehicle, toNodeId);
    if (projectedDisplayBlockerId) {
      return { reason: 'projected-display-clearance', blockingVehicleId: projectedDisplayBlockerId };
    }
    const clearingTargetId = this.movingVehicleClearingNode(toNodeId, vehicle);
    if (clearingTargetId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingTargetId };
    }

    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (edge) {
      const headOn = this.vehicles.find((other) =>
        other.id !== vehicle.id &&
        other.currentEdgeId === edge.id &&
        other.currentNodeId === toNodeId &&
        other.targetNodeId === fromNodeId
      );
      if (headOn) {
        return { reason: 'edge-head-on', blockingVehicleId: headOn.id };
      }
    }

    const leadingVehicleId = this.leadingVehicleTooClose(vehicle, fromNodeId, toNodeId);
    if (leadingVehicleId) {
      const leadingVehicle = this.vehicles.find((candidate) => candidate.id === leadingVehicleId) ?? null;
      if (
        !leadingVehicle ||
        (
          !this.topLiftRearQueueDisplayClearanceAllowedForTarget(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftTopBToTopAClearingEntryBlockerAllowed(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftInboundServiceAccessAisleClearanceMoveAllowed(vehicle, toNodeId, leadingVehicle)
        )
      ) {
        return { reason: 'min-separation', blockingVehicleId: leadingVehicleId };
      }
    }

    const target = nodePosition(this.scenario, toNodeId);
    const footprintBlockerId = this.predictedFootprintOverlapVehicleId(vehicle, target.x, target.z);
    const footprintBlocker = footprintBlockerId
      ? this.vehicles.find((candidate) => candidate.id === footprintBlockerId) ?? null
      : null;
    if (
      footprintBlockerId &&
      !this.topLiftQueueClearanceOverlapAllowed(vehicle, toNodeId, footprintBlockerId) &&
      (
        !footprintBlocker ||
        (
          !this.topLiftTopBToTopAClearingEntryBlockerAllowed(vehicle, toNodeId, footprintBlocker) &&
          !this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, footprintBlocker) &&
          !this.topLiftInboundServiceAccessAisleClearanceMoveAllowed(vehicle, toNodeId, footprintBlocker)
        )
      )
    ) {
      return { reason: 'min-separation', blockingVehicleId: footprintBlockerId };
    }
    return null;
  }

  private topLiftInboundQueueStagingTopAYieldForbidden(vehicle: MutableVehicle, nodeId: string): boolean {
    return this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      vehicle.plannedGoalNodeId !== null &&
      topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) !== null &&
      isTopLiftAisleLevelNodeId(nodeId, 'top-a');
  }

  private agentMinimalMoveBlocker(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { reason: string; blockingVehicleId: string | null } | null {
    const fromNodeId = vehicle.currentNodeId;
    const currentOccupant = this.currentNodeOccupancy.get(fromNodeId);
    if (currentOccupant && currentOccupant !== vehicle.id) {
      return { reason: 'node-occupancy-mismatch', blockingVehicleId: currentOccupant };
    }
    const inboundEntryCrossingBlockerId = this.topLiftInboundEntryCrossingBlocker(vehicle, toNodeId);
    if (inboundEntryCrossingBlockerId) {
      return { reason: 'top-lift-entry-crossing', blockingVehicleId: inboundEntryCrossingBlockerId };
    }
    const clearingCurrentId = this.movingVehicleClearingNode(fromNodeId, vehicle);
    if (clearingCurrentId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingCurrentId };
    }

    const occupiedTargetId = this.currentNodeOccupancy.get(toNodeId);
    if (occupiedTargetId && occupiedTargetId !== vehicle.id) {
      return { reason: this.liftPortWaitReason(toNodeId) ?? 'node-occupied', blockingVehicleId: occupiedTargetId };
    }
    const storageExitBlockerId = this.topLiftStorageExitAccessBlocker(vehicle, toNodeId);
    if (storageExitBlockerId) {
      return { reason: 'storage-exit-precedence', blockingVehicleId: storageExitBlockerId };
    }
    const loadedRoutePrecedenceBlockerId = this.topLiftLoadedRoutePrecedenceBlocker(vehicle, toNodeId);
    if (loadedRoutePrecedenceBlockerId) {
      return { reason: 'loaded-route-precedence', blockingVehicleId: loadedRoutePrecedenceBlockerId };
    }
    const projectedDisplayBlockerId = this.topLiftProjectedDisplayMoveBlocker(vehicle, toNodeId);
    if (projectedDisplayBlockerId) {
      return { reason: 'projected-display-clearance', blockingVehicleId: projectedDisplayBlockerId };
    }
    const clearingTargetId = this.movingVehicleClearingNode(toNodeId, vehicle);
    if (clearingTargetId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingTargetId };
    }

    const localRouteClaimBlockerId = this.localRouteNodeClaimBlocker(toNodeId, vehicle.id);
    if (localRouteClaimBlockerId) {
      return { reason: 'node-local-yield', blockingVehicleId: localRouteClaimBlockerId };
    }

    const targetClaimBlockerId = this.minimalTargetClaimBlocker(vehicle, toNodeId);
    if (targetClaimBlockerId) {
      return { reason: 'node-target-near', blockingVehicleId: targetClaimBlockerId };
    }

    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (edge) {
      const headOn = this.vehicles.find((other) =>
        other.id !== vehicle.id &&
        other.currentEdgeId === edge.id &&
        other.currentNodeId === toNodeId &&
        other.targetNodeId === fromNodeId
      );
      if (headOn) {
        return { reason: 'edge-head-on', blockingVehicleId: headOn.id };
      }
    }

    const leadingVehicleId = this.leadingVehicleTooClose(vehicle, fromNodeId, toNodeId);
    if (leadingVehicleId) {
      const leadingVehicle = this.vehicles.find((candidate) => candidate.id === leadingVehicleId) ?? null;
      if (
        !leadingVehicle ||
        (
          !this.topLiftRearQueueDisplayClearanceAllowedForTarget(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftTopBToTopAClearingEntryBlockerAllowed(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, leadingVehicle) &&
          !this.topLiftInboundServiceAccessAisleClearanceMoveAllowed(vehicle, toNodeId, leadingVehicle)
        )
      ) {
        return { reason: 'min-separation', blockingVehicleId: leadingVehicleId };
      }
    }

    const target = nodePosition(this.scenario, toNodeId);
    const footprintBlockerId = this.predictedFootprintOverlapVehicleId(vehicle, target.x, target.z);
    const footprintBlocker = footprintBlockerId
      ? this.vehicles.find((candidate) => candidate.id === footprintBlockerId) ?? null
      : null;
    if (
      footprintBlockerId &&
      !this.topLiftQueueClearanceOverlapAllowed(vehicle, toNodeId, footprintBlockerId) &&
      (
        !footprintBlocker ||
        (
          !this.topLiftTopBToTopAClearingEntryBlockerAllowed(vehicle, toNodeId, footprintBlocker) &&
          !this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, footprintBlocker) &&
          !this.topLiftInboundServiceAccessAisleClearanceMoveAllowed(vehicle, toNodeId, footprintBlocker)
        )
      )
    ) {
      return { reason: 'avoidance-clearance', blockingVehicleId: footprintBlockerId };
    }
    return null;
  }

  private topLiftStorageExitAccessBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !isTopLiftColumnAccessNodeId(toNodeId) ||
      this.isStorageNode(vehicle.currentNodeId)
    ) {
      return null;
    }
    if (
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle') &&
      isTopLiftAisleLevelNodeId(toNodeId, 'middle')
    ) {
      return null;
    }

    const blocker = this.vehicles
      .filter((other) =>
        other.id !== vehicle.id &&
        this.isStorageNode(other.currentNodeId) &&
        other.targetNodeId === toNodeId &&
        other.currentEdgeId === null &&
        other.legRemainingM <= 0 &&
        other.phaseRemainingSec <= 0 &&
        this.traffic.findEdge(other.currentNodeId, toNodeId)
      )
      .sort((left, right) =>
        Number(right.loaded) - Number(left.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        left.id.localeCompare(right.id)
      )[0] ?? null;

    return blocker?.id ?? null;
  }

  private topLiftLoadedRoutePrecedenceBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
      !isTopLiftAisleLevelNodeId(toNodeId, 'bottom-a')
    ) {
      return null;
    }

    const fromPosition = nodePosition(this.scenario, vehicle.currentNodeId);
    const toPosition = nodePosition(this.scenario, toNodeId);
    const vehicleDirection = Math.sign(toPosition.x - fromPosition.x);
    if (vehicleDirection === 0) {
      return null;
    }

    const blocker = this.vehicles
      .map((other) => {
        if (other.id === vehicle.id || !other.loaded) {
          return null;
        }
        const route = this.topLiftLoadedRouteTailClaimingOppositeBottomA(other, toNodeId, vehicleDirection);
        return route ? { other, distance: route.indexOf(toNodeId) } : null;
      })
      .filter((entry): entry is { other: MutableVehicle; distance: number } => entry !== null)
      .sort((left, right) =>
        left.distance - right.distance ||
        this.agentTurnPriority(left.other) - this.agentTurnPriority(right.other) ||
        left.other.id.localeCompare(right.other.id)
      )[0] ?? null;

    return blocker?.other.id ?? null;
  }

  private topLiftLoadedRouteTailClaimingOppositeBottomA(
    loadedVehicle: MutableVehicle,
    nodeId: string,
    emptyVehicleDirection: number
  ): string[] | null {
    const targetColumn = this.topLiftColumnAccessColumn(nodeId);
    if (targetColumn === null) {
      return null;
    }
    const candidateRoutes = [
      this.vehicleRouteTail(loadedVehicle, loadedVehicle.routeNodeIds),
      this.vehicleRouteTail(loadedVehicle, loadedVehicle.plannedRouteNodeIds)
    ];

    for (const route of candidateRoutes) {
      if (this.topLiftLoadedRouteTailClaimsBottomAColumn(route, targetColumn, emptyVehicleDirection)) {
        return route;
      }
    }

    return null;
  }

  private topLiftLoadedRouteTailClaimsBottomAColumn(
    route: string[],
    targetColumn: number,
    emptyVehicleDirection: number
  ): boolean {
    const bottomANodes = route
      .slice(0, 13)
      .map((nodeId, index) => ({
        nodeId,
        index,
        column: isTopLiftAisleLevelNodeId(nodeId, 'bottom-a')
          ? this.topLiftColumnAccessColumn(nodeId)
          : null
      }))
      .filter((entry): entry is { nodeId: string; index: number; column: number } => entry.column !== null);
    if (bottomANodes.length === 0) {
      return false;
    }

    let loadedDirection: number | null = null;
    for (let index = 1; index < bottomANodes.length; index += 1) {
      const direction = Math.sign(bottomANodes[index]!.column - bottomANodes[index - 1]!.column);
      if (direction !== 0) {
        loadedDirection = direction;
        break;
      }
    }
    if (loadedDirection === null || loadedDirection === emptyVehicleDirection) {
      return false;
    }

    const columns = bottomANodes.map((entry) => entry.column);
    const minColumn = Math.min(...columns);
    const maxColumn = Math.max(...columns);
    const protectedMinColumn = loadedDirection > 0 ? minColumn : minColumn - 1;
    const protectedMaxColumn = loadedDirection > 0 ? maxColumn + 1 : maxColumn;
    return targetColumn >= protectedMinColumn && targetColumn <= protectedMaxColumn;
  }

  private topLiftQueueClearanceOverlapAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blockerVehicleId: string
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const targetBuffer = liftBufferParentNodeId(toNodeId);
    const targetBufferAccessLiftNodeId = /^(lift-\d{2}-(?:inbound|outbound))-buffer-access$/.exec(toNodeId)?.[1] ?? null;
    const targetLiftNodeId = targetBuffer?.liftNodeId ??
      targetBufferAccessLiftNodeId ??
      this.topLiftQueueServiceLiftNodeId(toNodeId);
    if (!targetLiftNodeId) {
      return false;
    }
    const blocker = this.vehicles.find((vehicle) => vehicle.id === blockerVehicleId);
    if (blocker && this.topLiftRearQueueDisplayClearanceAllowed(vehicle, toNodeId, blocker, targetLiftNodeId)) {
      return true;
    }
    const blockerQueueSlot = blocker ? topLiftQueueParkingSlot(blocker.currentNodeId) : null;
    if (blockerQueueSlot?.liftNodeId === targetLiftNodeId) {
      return true;
    }

    const task = this.taskForVehicle(vehicle);
    const blockerTask = blocker ? this.taskForVehicle(blocker) : null;
    return Boolean(
      blocker &&
      vehicle.loaded &&
      blocker.loaded &&
      task?.kind === 'outbound' &&
      blockerTask?.kind === 'outbound' &&
      this.taskLiftPortNodeId(task) === targetLiftNodeId &&
      this.taskLiftPortNodeId(blockerTask) === targetLiftNodeId &&
      this.taskPrecedes(task, blockerTask)
    );
  }

  private topLiftRearQueueDisplayClearanceAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle,
    liftNodeId: string
  ): boolean {
    if (
      vehicle.loaded ||
      blocker.loaded ||
      this.liftPortKindForNodeId(liftNodeId) !== 'inbound'
    ) {
      return false;
    }
    const targetSlot = this.topLiftQueueSlotForNode(toNodeId);
    const blockerSlot = this.topLiftQueueSlotForNode(blocker.currentNodeId);
    if (
      !targetSlot ||
      !blockerSlot ||
      targetSlot.liftNodeId !== liftNodeId ||
      blockerSlot.liftNodeId !== liftNodeId ||
      targetSlot.slotIndex <= blockerSlot.slotIndex
    ) {
      return false;
    }
    const goalSlot = this.topLiftQueueSlotForNode(vehicle.routeNodeIds.at(-1) ?? vehicle.plannedGoalNodeId ?? '');
    if (!goalSlot || goalSlot.liftNodeId !== liftNodeId || goalSlot.slotIndex < targetSlot.slotIndex) {
      return false;
    }
    const targetNode = this.layoutNode(toNodeId);
    if (!targetNode) {
      return false;
    }
    const targetDisplay = this.topLiftDisplayPointForNode(toNodeId, targetNode);
    const blockerDisplay = this.topLiftDisplayPointForNode(blocker.currentNodeId, blocker);
    return !vehicleFootprintsOverlap(
      { x: targetDisplay.x, z: targetDisplay.z, yaw: vehicle.yaw },
      { x: blockerDisplay.x, z: blockerDisplay.z, yaw: blocker.yaw },
      this.scenario.vehicles
    );
  }

  private topLiftRearQueueDisplayClearanceAllowedForTarget(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const liftNodeId = this.topLiftQueueServiceLiftNodeId(toNodeId);
    return liftNodeId ? this.topLiftRearQueueDisplayClearanceAllowed(vehicle, toNodeId, blocker, liftNodeId) : false;
  }

  private topLiftQueueSlotForNode(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
    return topLiftQueueParkingSlot(nodeId) ??
      topLiftQueueAisleAccess(nodeId) ??
      topLiftQueueEntrySlot(nodeId) ??
      topLiftQueueServiceSlot(nodeId) ??
      this.topLiftInboundApproachQueueSlot(nodeId);
  }

  private topLiftInboundEntryCrossingBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const protectedColumn = this.topLiftInboundEntryProtectedColumnForMove(vehicle.currentNodeId, toNodeId);
    if (protectedColumn === null) {
      return null;
    }

    return this.vehicles.find((other) => {
      if (other.id === vehicle.id) {
        return false;
      }
      const crossingColumn = this.topLiftInboundEntryCrossingColumnForVehicle(other);
      if (
        crossingColumn === protectedColumn &&
        this.topLiftInboundEntryWaitsForVehicleToClearProtectedNode(vehicle, toNodeId, other)
      ) {
        return false;
      }
      return crossingColumn === protectedColumn;
    })?.id ?? null;
  }

  private topLiftInboundEntryWaitsForVehicleToClearProtectedNode(
    vehicle: MutableVehicle,
    toNodeId: string,
    inboundEntryVehicle: MutableVehicle
  ): boolean {
    if (
      inboundEntryVehicle.phaseRemainingSec > 0 ||
      inboundEntryVehicle.targetNodeId !== vehicle.currentNodeId ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-b' ||
      topLiftAisleLevel(toNodeId) !== 'top-a'
    ) {
      return false;
    }
    const inboundWaitingAtEntry =
      inboundEntryVehicle.currentEdgeId === null &&
      inboundEntryVehicle.legRemainingM <= 0;
    const inboundStoppedOnEntryApproach =
      inboundEntryVehicle.currentEdgeId !== null &&
      inboundEntryVehicle.state === 'waiting-blocked' &&
      inboundEntryVehicle.speedMps <= 0 &&
      inboundEntryVehicle.blockingVehicleId === vehicle.id;
    if (!inboundWaitingAtEntry && !inboundStoppedOnEntryApproach) {
      return false;
    }
    const entrySlot = topLiftQueueEntrySlot(inboundEntryVehicle.currentNodeId);
    return Boolean(entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'inbound');
  }

  private topLiftInboundEntryProtectedColumnForMove(fromNodeId: string, toNodeId: string): number | null {
    const toColumn = this.topLiftColumnAccessColumn(toNodeId);
    if (toColumn !== null && topLiftAisleLevel(toNodeId) === 'top-a') {
      return toColumn;
    }
    const fromColumn = this.topLiftColumnAccessColumn(fromNodeId);
    if (fromColumn !== null && topLiftAisleLevel(fromNodeId) === 'top-a' && topLiftAisleLevel(toNodeId) === 'top-b') {
      return fromColumn;
    }
    return null;
  }

  private topLiftInboundEntryCrossingColumnForVehicle(vehicle: MutableVehicle): number | null {
    if (!vehicle.targetNodeId) {
      return null;
    }
    return this.topLiftInboundEntryCrossingColumnForLeg(vehicle.currentNodeId, vehicle.targetNodeId);
  }

  private topLiftInboundEntryCrossingColumnForLeg(fromNodeId: string, toNodeId: string): number | null {
    const fromEntry = topLiftQueueEntrySlot(fromNodeId);
    const toEntry = topLiftQueueEntrySlot(toNodeId);
    if (toEntry && this.liftPortKindForNodeId(toEntry.liftNodeId) === 'inbound' && topLiftAisleLevel(fromNodeId) === 'top-b') {
      return this.topLiftColumnAccessColumn(fromNodeId);
    }
    if (fromEntry && this.liftPortKindForNodeId(fromEntry.liftNodeId) === 'inbound' && topLiftAisleLevel(toNodeId) === 'top-b') {
      return this.topLiftColumnAccessColumn(toNodeId);
    }
    return null;
  }

  private tryMoveTopLiftInboundEntryCrossingBlockerAside(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      topLiftAisleLevel(vehicle.currentNodeId) !== 'top-a'
    ) {
      return false;
    }
    const crossingColumn = this.topLiftInboundEntryCrossingColumnForVehicle(requester);
    const vehicleColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    if (crossingColumn === null || vehicleColumn !== crossingColumn) {
      return false;
    }

    const vehiclePosition = this.vehiclePosition(vehicle);
    const requesterPosition = this.vehiclePosition(requester);
    const route = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedTargetNodeId)
      .filter((neighbor) => neighbor.nodeId !== requester.currentNodeId && neighbor.nodeId !== requester.targetNodeId)
      .filter((neighbor) => topLiftAisleLevel(neighbor.nodeId) === 'top-a')
      .filter((neighbor) => this.topLiftColumnSpineOrAccessNode(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .map((neighbor) => {
        const node = this.layoutNode(neighbor.nodeId)!;
        const requesterDistance = Math.hypot(node.x - requesterPosition.x, node.z - requesterPosition.z);
        const currentDistance = Math.hypot(node.x - vehiclePosition.x, node.z - vehiclePosition.z);
        return { nodeId: neighbor.nodeId, requesterDistance, currentDistance };
      })
      .sort((left, right) =>
        right.requesterDistance - left.requesterDistance ||
        left.currentDistance - right.currentDistance ||
        left.nodeId.localeCompare(right.nodeId)
      )[0];

    if (!route) {
      return false;
    }

    const routeNodeIds = [vehicle.currentNodeId, route.nodeId];
    if (!this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
      return false;
    }

    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route.nodeId;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.phaseRemainingSec = 0;
    vehicle.speedMps = 0;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, routeNodeIds) + 2);
    vehicle.yieldHoldNodeId = route.nodeId;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blockedTargetNodeId, routeNodeIds, 'top-lift-entry-crossing-yield', { countTaskReplan: false });
    return true;
  }

  private topLiftQueueFifoBlocker(vehicle: MutableVehicle, toNodeId: string): string | null {
    if (!this.topLiftColumnLayoutEnabled()) {
      return null;
    }
    const targetSlot = topLiftQueueParkingSlot(toNodeId);
    if (!targetSlot) {
      return null;
    }
    const currentAccessSlot = topLiftQueueAisleAccess(vehicle.currentNodeId);
    if (
      currentAccessSlot?.liftNodeId === targetSlot.liftNodeId &&
      currentAccessSlot.slotIndex === targetSlot.slotIndex
    ) {
      return null;
    }
    const plannedSlot = topLiftQueueParkingSlot(vehicle.plannedGoalNodeId ?? vehicle.routeNodeIds.at(-1) ?? '');
    if (
      plannedSlot?.liftNodeId === targetSlot.liftNodeId &&
      plannedSlot.slotIndex > targetSlot.slotIndex
    ) {
      return null;
    }
    const task = this.taskForVehicle(vehicle);
    if (!task || this.taskLiftPortNodeId(task) !== targetSlot.liftNodeId) {
      return null;
    }
    if (task.kind === 'outbound' && !vehicle.loaded) {
      return null;
    }
    if (task.kind === 'inbound' && vehicle.loaded) {
      return null;
    }

    for (const candidate of this.activeTasks()) {
      if (
        candidate.id === task.id ||
        candidate.kind !== task.kind ||
        this.taskLiftPortNodeId(candidate) !== targetSlot.liftNodeId ||
        !this.taskPrecedes(candidate, task)
      ) {
        continue;
      }
      if (task.kind === 'inbound' && this.inboundTaskPickupReleased(candidate)) {
        continue;
      }
      if (task.kind === 'outbound' && this.outboundTaskDropoffReleased(candidate)) {
        continue;
      }
      const candidateVehicle = candidate.vehicleId
        ? this.vehicles.find((entry) => entry.id === candidate.vehicleId) ?? null
        : null;
      if (!candidateVehicle) {
        return candidate.vehicleId;
      }
      for (const nodeId of [candidateVehicle.currentNodeId, candidateVehicle.targetNodeId, candidateVehicle.plannedGoalNodeId]) {
        const candidateSlot = nodeId ? topLiftQueueParkingSlot(nodeId) : null;
        if (
          candidateSlot?.liftNodeId === targetSlot.liftNodeId &&
          candidateSlot.slotIndex > targetSlot.slotIndex
        ) {
          return candidateVehicle.id;
        }
      }
    }
    return null;
  }

  private loadedStorageLoadBlock(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (!vehicle.loaded || !this.isStorageNode(toNodeId)) {
      return null;
    }
    return this.storedLoadIdAtNode(toNodeId) ? { reason: 'stored-load-occupied', blockingVehicleId: null } : null;
  }

  private agentMinimalStorageExitLookaheadBlocker(
    vehicle: MutableVehicle,
    route: string[]
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (!this.agentMinimalEnabled() || !this.collisionAvoidanceEnabled() || vehicle.loaded || route.length < 3) {
      return null;
    }
    const fromNodeId = route[0]!;
    const sideExitNodeId = route[1]!;
    const afterExitNodeId = route[2]!;
    if (!this.isStorageNode(fromNodeId) || !/^(left|right)-row-\d+$/.test(sideExitNodeId)) {
      return null;
    }
    const block = this.agentMinimalMoveBlocker(vehicle, afterExitNodeId);
    return block
      ? { reason: `storage-exit-${block.reason}`, blockingVehicleId: block.blockingVehicleId }
      : null;
  }

  private agentRefreshNearColumnSweptFootprintBlocker(
    vehicle: MutableVehicle,
    fromNodeId: string,
    toNodeId: string
  ): string | null {
    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (!edge || this.axisForEdge(edge) !== 'z') {
      return null;
    }
    const from = nodePosition(this.scenario, fromNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    const distanceM = Math.hypot(to.x - from.x, to.z - from.z);
    if (distanceM <= 1e-9) {
      return null;
    }
    const horizonM = Math.min(distanceM, this.agentRefreshNearAvoidanceHorizonM());
    const ratio = horizonM / distanceM;
    const horizonX = from.x + (to.x - from.x) * ratio;
    const horizonZ = from.z + (to.z - from.z) * ratio;
    return this.predictedSweptFootprintOverlapVehicleId(vehicle, from.x, from.z, horizonX, horizonZ);
  }

  private agentRefreshNearAvoidanceHorizonM(): number {
    return Math.max(
      this.scenario.trafficPolicy.dynamicAvoidanceClearanceM,
      this.scenario.vehicles.lengthM + this.scenario.vehicles.safetyRadiusM
    );
  }

  private agentRefreshYieldHoldBlocker(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (!this.agentRefreshEnabled()) {
      return null;
    }
    const conflictSession = this.activeYieldingConflictSessionForVehicle(vehicle.id);
    if (
      conflictSession &&
      conflictSession.clearancePolicy === 'short-horizon' &&
      (conflictSession.state === 'yielding' || conflictSession.state === 'holding-pocket') &&
      conflictSession.yielderVehicleId === vehicle.id
    ) {
      const winner = this.vehicles.find((candidate) => candidate.id === conflictSession.winnerVehicleId) ?? null;
      if (winner && this.tryUnwindTopLiftStoragePocketYieldHold(vehicle, winner, conflictSession)) {
        return null;
      }
      const blockerId = this.topLiftMiddleAisleStorageYieldHoldBlocker(vehicle, conflictSession);
      if (blockerId) {
        return { reason: 'local-yield-hold', blockingVehicleId: blockerId };
      }
    }
    if (
      conflictSession &&
      conflictSession.state === 'yielding' &&
      conflictSession.yielderVehicleId === vehicle.id &&
      conflictSession.resumeNodeId
    ) {
      const winner = this.vehicles.find((candidate) => candidate.id === conflictSession.winnerVehicleId) ?? null;
      if (winner) {
        if (this.agentRefreshYieldHoldVehicleCanLeaveCurrentForWinner(vehicle, winner, task)) {
          this.closeConflictSession(conflictSession, 'yielder-current-needed-by-winner');
          vehicle.yieldHoldUntilSec = null;
          vehicle.yieldHoldNodeId = null;
          return null;
        }
        if (this.tryUnwindTopLiftStoragePocketYieldHold(vehicle, winner, conflictSession)) {
          return null;
        }
        const winnerCurrentIndex = winner.routeNodeIds.indexOf(
          winner.currentNodeId,
          Math.max(0, winner.routeIndex)
        );
        const searchFromIndex = winnerCurrentIndex >= 0 ? winnerCurrentIndex : Math.max(0, winner.routeIndex);
        const resumeIndex = winner.routeNodeIds.indexOf(conflictSession.resumeNodeId, searchFromIndex);
        if (winner.targetNodeId === conflictSession.resumeNodeId || resumeIndex > searchFromIndex) {
          return { reason: 'local-yield-hold', blockingVehicleId: winner.id };
        }
      }
    }
    const pocketExitBlock = this.agentRefreshYieldPocketExitLookaheadBlocker(vehicle);
    if (pocketExitBlock) {
      vehicle.yieldHoldUntilSec = round(Math.max(vehicle.yieldHoldUntilSec ?? 0, this.simTimeSec + 1));
      return pocketExitBlock;
    }
    if (
      vehicle.yieldHoldUntilSec !== null &&
      this.simTimeSec < vehicle.yieldHoldUntilSec
    ) {
      return {
        reason: 'local-yield-hold',
        blockingVehicleId: conflictSession?.winnerVehicleId ?? null
      };
    }
    return null;
  }

  private agentRefreshYieldHoldVehicleCanLeaveCurrentForWinner(
    vehicle: MutableVehicle,
    winner: MutableVehicle,
    task: TaskStateRecord | null
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !this.isStorageNode(vehicle.currentNodeId)
    ) {
      return false;
    }
    const winnerNeedsCurrentNode =
      winner.targetNodeId === vehicle.currentNodeId ||
      this.vehicleRouteTail(winner, winner.routeNodeIds).includes(vehicle.currentNodeId) ||
      this.vehicleRouteTail(winner, winner.plannedRouteNodeIds).includes(vehicle.currentNodeId);
    if (!winnerNeedsCurrentNode) {
      return false;
    }

    const goalNodeId = this.agentGoalNodeId(vehicle, task);
    if (!goalNodeId || goalNodeId === vehicle.currentNodeId) {
      return false;
    }

    let routeNodeIds: string[];
    try {
      routeNodeIds = this.agentRefreshNominalRouteToGoal(vehicle, task, goalNodeId);
    } catch {
      return false;
    }
    const nextNodeId = routeNodeIds[1] ?? null;
    if (
      !nextNodeId ||
      nextNodeId === winner.currentNodeId ||
      !this.routeHasOnlyAdjacentEdges(routeNodeIds) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
      this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeNodeIds)
    ) {
      return false;
    }
    return true;
  }

  private tryUnwindTopLiftStoragePocketYieldHold(
    yielder: MutableVehicle,
    winner: MutableVehicle,
    conflictSession: ConflictSessionV1 | null
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      yielder.loaded ||
      winner.loaded ||
      yielder.currentEdgeId !== null ||
      winner.currentEdgeId !== null ||
      yielder.legRemainingM > 0 ||
      winner.legRemainingM > 0 ||
      yielder.phaseRemainingSec > 0 ||
      winner.phaseRemainingSec > 0 ||
      !this.isStorageNode(yielder.currentNodeId) ||
      !isTopLiftAisleLevelNodeId(winner.currentNodeId, 'bottom-a') ||
      winner.state !== 'waiting-blocked' ||
      winner.waitReason !== 'node-occupied' ||
      winner.blockingVehicleId !== yielder.id ||
      winner.targetNodeId !== yielder.currentNodeId ||
      !this.traffic.findEdge(winner.currentNodeId, yielder.currentNodeId)
    ) {
      return false;
    }

    const winnerTask = this.taskForVehicle(winner);
    if (winnerTask?.kind !== 'outbound') {
      return false;
    }

    const winnerStillNeedsYielderNode =
      this.vehicleRouteTail(winner, winner.routeNodeIds).includes(yielder.currentNodeId) ||
      this.vehicleRouteTail(winner, winner.plannedRouteNodeIds).includes(yielder.currentNodeId);
    if (!winnerStillNeedsYielderNode) {
      return false;
    }

    if (
      !this.agentRefreshInstallSideYield(winner, yielder.currentNodeId, yielder, null) &&
      !this.tryInstallTopLiftStoragePocketBottomBUnwind(winner, yielder.currentNodeId)
    ) {
      return false;
    }

    if (conflictSession) {
      this.closeConflictSession(conflictSession, 'storage-pocket-yield-unwind');
    }
    yielder.yieldHoldUntilSec = null;
    yielder.yieldHoldNodeId = null;
    yielder.waitReason = null;
    yielder.blockingVehicleId = null;
    yielder.blockingReservationId = null;
    yielder.waitingSinceSec = null;
    this.logEvent(
      'route-replanned',
      yielder.id,
      yielder.taskId,
      null,
      yielder.currentNodeId,
      yielder.currentNodeId,
      'storage-pocket-yield-unwind-released',
      this.vehiclePosition(yielder),
      { winnerVehicleId: winner.id }
    );
    return true;
  }

  private tryInstallTopLiftStoragePocketBottomBUnwind(
    vehicle: MutableVehicle,
    blockedStorageNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      !this.isStorageNode(blockedStorageNodeId)
    ) {
      return false;
    }
    const currentMatch = /^column-bottom-a-c(\d+)$/.exec(vehicle.currentNodeId);
    if (!currentMatch) {
      return false;
    }

    const bottomBNodeId = `column-bottom-b-c${currentMatch[1]}`;
    const routeNodeIds = [vehicle.currentNodeId, bottomBNodeId];
    if (
      !this.layoutNode(bottomBNodeId) ||
      !this.routeHasOnlyAdjacentEdges(routeNodeIds) ||
      this.currentNodeOccupancy.get(bottomBNodeId) ||
      this.nodeClaimedByOtherVehicle(bottomBNodeId, vehicle.id) ||
      !this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, bottomBNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
      this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, routeNodeIds)
    ) {
      return false;
    }

    const moveBlock = this.agentRefreshMoveBlocker(vehicle, bottomBNodeId, routeNodeIds);
    if (moveBlock) {
      return false;
    }

    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = bottomBNodeId;
    vehicle.state = vehicle.taskId ? 'assigned' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, routeNodeIds) + 6);
    vehicle.yieldHoldNodeId = bottomBNodeId;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'storage-pocket-unwind';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blockedStorageNodeId, routeNodeIds, 'storage-pocket-bottom-b-unwind', { countTaskReplan: false });
    return true;
  }

  private agentRefreshYieldPocketExitLookaheadBlocker(
    vehicle: MutableVehicle
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.yieldHoldNodeId !== vehicle.currentNodeId ||
      !this.isStorageNode(vehicle.currentNodeId)
    ) {
      return null;
    }

    const route = this.agentRefreshYieldPocketExitLookaheadRoute(vehicle);
    if (!route || route.length < 3) {
      return null;
    }
    const exitNodeId = route[1]!;
    const afterExitNodeId = route[2]!;
    if (
      !this.topLiftColumnSpineOrAccessNode(exitNodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, exitNodeId) ||
      !this.traffic.findEdge(exitNodeId, afterExitNodeId)
    ) {
      return null;
    }

    const exitBlock = this.agentRefreshMoveBlocker(vehicle, exitNodeId, route);
    if (exitBlock) {
      const blocker = exitBlock.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === exitBlock.blockingVehicleId) ?? null
        : null;
      if (
        blocker &&
        this.tryUnwindTopLiftStoragePocketYieldHold(
          vehicle,
          blocker,
          this.activeConflictSessionForPair(vehicle.id, blocker.id)
        )
      ) {
        return null;
      }
      return { reason: 'local-yield-hold', blockingVehicleId: exitBlock.blockingVehicleId };
    }

    const proxyVehicle: MutableVehicle = {
      ...vehicle,
      currentNodeId: exitNodeId,
      targetNodeId: null,
      currentEdgeId: null,
      legRemainingM: 0,
      legElapsedSec: 0,
      legTravelSec: 0,
      speedMps: 0,
      targetSpeedMps: 0
    };
    const afterExitRoute = route.slice(1);
    const afterExitBlock = this.agentRefreshMoveBlocker(proxyVehicle, afterExitNodeId, afterExitRoute);
    if (!afterExitBlock || afterExitBlock.blockingVehicleId === vehicle.id) {
      const loadedRouteBlockerId = this.agentRefreshYieldPocketLoadedRouteReservationBlocker(
        vehicle,
        afterExitNodeId
      );
      return loadedRouteBlockerId
        ? { reason: 'local-yield-hold', blockingVehicleId: loadedRouteBlockerId }
        : null;
    }
    return { reason: 'local-yield-hold', blockingVehicleId: afterExitBlock.blockingVehicleId };
  }

  private agentRefreshYieldPocketLoadedRouteReservationBlocker(
    vehicle: MutableVehicle,
    afterExitNodeId: string
  ): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !this.topLiftColumnSpineOrAccessNode(afterExitNodeId)
    ) {
      return null;
    }

    const blockers = this.vehicles
      .filter((other) =>
        other.id !== vehicle.id &&
        other.loaded &&
        (other.currentEdgeId !== null || other.phaseRemainingSec <= 0)
      )
      .map((other) => {
        const route = this.agentRefreshLoadedRouteReservationTail(other, afterExitNodeId);
        const afterExitIndex = route ? route.indexOf(afterExitNodeId) : -1;
        return { other, afterExitIndex };
      })
      .filter(({ afterExitIndex }) => afterExitIndex >= 0 && afterExitIndex <= 8)
      .sort((left, right) =>
        left.afterExitIndex - right.afterExitIndex ||
        left.other.id.localeCompare(right.other.id)
      );
    return blockers[0]?.other.id ?? null;
  }

  private agentRefreshLoadedRouteReservationTail(vehicle: MutableVehicle, nodeId: string): string[] | null {
    const candidateRoutes = [
      vehicle.routeNodeIds,
      vehicle.plannedRouteNodeIds
    ];
    for (const candidateRoute of candidateRoutes) {
      const route = this.vehicleRouteTail(vehicle, candidateRoute);
      if (route.includes(nodeId)) {
        return route;
      }
    }
    return null;
  }

  private agentRefreshYieldPocketExitLookaheadRoute(vehicle: MutableVehicle): string[] | null {
    const candidateRoutes = [
      vehicle.plannedRouteNodeIds,
      vehicle.routeNodeIds
    ];
    for (const candidateRoute of candidateRoutes) {
      if (candidateRoute.length < 2) {
        continue;
      }
      const currentIndex = candidateRoute.indexOf(vehicle.currentNodeId);
      const route = currentIndex >= 0
        ? candidateRoute.slice(currentIndex)
        : this.agentRefreshYieldPocketRouteRejoinTail(vehicle.currentNodeId, candidateRoute);
      if (
        route &&
        route.length >= 3 &&
        route[0] === vehicle.currentNodeId &&
        route[1] !== vehicle.currentNodeId &&
        route[2] !== vehicle.currentNodeId &&
        this.traffic.findEdge(route[0]!, route[1]!)
      ) {
        return route;
      }
    }
    return null;
  }

  private agentRefreshYieldPocketRouteRejoinTail(
    currentNodeId: string,
    candidateRoute: string[]
  ): string[] | null {
    const rejoinIndex = candidateRoute.findIndex((nodeId) =>
      nodeId !== currentNodeId && this.traffic.findEdge(currentNodeId, nodeId) !== null
    );
    if (rejoinIndex < 0) {
      return null;
    }
    return [currentNodeId, ...candidateRoute.slice(rejoinIndex)];
  }

  private topLiftMiddleAisleStorageYieldHoldBlocker(
    vehicle: MutableVehicle,
    session: ConflictSessionV1
  ): string | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !this.isStorageNode(vehicle.currentNodeId) ||
      !this.isStorageNode(session.yielderOriginalNodeId) ||
      !session.resumeNodeId ||
      !isTopLiftAisleLevelNodeId(session.resumeNodeId, 'middle')
    ) {
      return null;
    }
    const resumeNode = this.layoutNode(session.resumeNodeId);
    if (!resumeNode) {
      return null;
    }
    const entryClaim = { minX: resumeNode.x, maxX: resumeNode.x };
    return this.vehicles
      .filter((candidate) => candidate.id !== vehicle.id)
      .sort((left, right) =>
        Number(right.id === session.winnerVehicleId) - Number(left.id === session.winnerVehicleId) ||
        left.id.localeCompare(right.id)
      )
      .find((candidate) => {
        const activeClaim = this.topLiftMiddleAisleActiveClaim(candidate);
        return Boolean(activeClaim && this.topLiftMiddleAisleClaimsOverlap(entryClaim, activeClaim));
      })?.id ?? null;
  }

  private agentRefreshWinnerShouldStayCourse(
    session: ConflictSessionV1 | null,
    vehicle: MutableVehicle,
    blocker: MutableVehicle | null
  ): boolean {
    if (
      !session ||
      !blocker ||
      session.winnerVehicleId !== vehicle.id ||
      session.yielderVehicleId !== blocker.id ||
      !session.resumeNodeId ||
      !isTopLiftColumnAccessNodeId(session.resumeNodeId)
    ) {
      return false;
    }

    return [
      blocker.currentNodeId,
      blocker.targetNodeId,
      session.yielderPocketNodeId,
      ...session.yielderLocalRouteNodeIds
    ].some((nodeId) => nodeId !== null && isTopLiftQueueParkingNodeId(nodeId));
  }

  private agentNodeBlocker(vehicle: MutableVehicle, nodeId: string): string | null {
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return occupantId;
    }

    const claimant = this.vehicles.find((other) =>
      other.id !== vehicle.id &&
      other.targetNodeId === nodeId &&
      other.currentNodeId !== nodeId &&
      other.state !== 'idle' &&
      other.state !== 'parking' &&
      !this.vehicleCurrentlyWaitsFor(other, vehicle.id)
    );
    if (!claimant) {
      return null;
    }

    if (claimant.currentEdgeId !== null || claimant.legRemainingM > 0) {
      return claimant.id;
    }

    const claimantPriority = this.agentTurnPriority(claimant);
    const vehiclePriority = this.agentTurnPriority(vehicle);
    if (claimantPriority > vehiclePriority) {
      return claimant.id;
    }
    if (claimantPriority === vehiclePriority && claimant.id.localeCompare(vehicle.id) < 0) {
      return claimant.id;
    }
    return null;
  }

  private agentSetWaiting(
    vehicle: MutableVehicle,
    targetNodeId: string,
    block: { reason: string; blockingVehicleId: string | null },
    dtSec: number
  ): void {
    const conflictSession = this.agentRefreshEnabled()
      ? block.blockingVehicleId
        ? this.activeConflictSessionForPair(vehicle.id, block.blockingVehicleId)
        : this.activeYieldingConflictSessionForVehicle(vehicle.id)
      : null;
    const shouldUseSessionBlocker = block.reason !== 'no-stop-continuation-blocked';
    const stableBlockingVehicleId =
      shouldUseSessionBlocker && conflictSession && conflictSession.yielderVehicleId === vehicle.id
        ? conflictSession.blockerVehicleId
        : block.blockingVehicleId;
    if (conflictSession && conflictSession.yielderVehicleId === vehicle.id) {
      conflictSession.updatedAtSec = this.simTimeSec;
    }
    const shouldLogWait = this.shouldLogVehicleWait(vehicle, targetNodeId, block.reason, null, stableBlockingVehicleId);
    this.reservationConflictCount += 1;
    vehicle.state = 'waiting-blocked';
    vehicle.speedMps = 0;
    vehicle.targetNodeId = targetNodeId;
    vehicle.waitReason = block.reason;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = stableBlockingVehicleId;
    vehicle.waitingSinceSec ??= this.simTimeSec;
    vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
    this.blockedTimeByReasonSec.set(block.reason, round((this.blockedTimeByReasonSec.get(block.reason) ?? 0) + dtSec));
    if (shouldLogWait) {
      this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, vehicle.currentNodeId, targetNodeId, block.reason, this.vehiclePosition(vehicle), {
        blockingVehicleId: stableBlockingVehicleId,
        conflictSessionId: conflictSession?.id ?? null
      });
    }
  }

  private beginAgentSimpleLeg(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    toNodeId: string,
    task: TaskStateRecord | null,
    dtSec: number
  ): void {
    const motionMode = this.routeLegMotionMode(vehicle, edge, toNodeId, vehicle.routeIndex, task);
    const speedMps = this.speedForEdge(vehicle, edge);
    const travelSec = this.routeLegTravelSec(vehicle, edge, toNodeId, vehicle.routeIndex, motionMode);

    this.releaseNodeOccupancy(vehicle, vehicle.currentNodeId);
    vehicle.directionSwitchReadyNodeId = null;
    vehicle.waitingSinceSec = null;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    if (vehicle.yieldHoldNodeId === vehicle.currentNodeId) {
      vehicle.yieldHoldUntilSec = null;
      vehicle.yieldHoldNodeId = null;
    }
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.targetNodeId = toNodeId;
    vehicle.legRemainingM = this.routeLegDistanceM(edge);
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = travelSec;
    vehicle.currentEdgeId = edge.id;
    vehicle.targetSpeedMps = speedMps;
    vehicle.legStartYaw = vehicle.yaw;
    vehicle.legMotionMode = motionMode;
    this.advanceMovement(vehicle, dtSec);
  }

  private agentTryDisplaceEmptyBlocker(blockingVehicleId: string, requester: MutableVehicle, blockedTargetNodeId: string): boolean {
    const blocker = this.vehicles.find((candidate) => candidate.id === blockingVehicleId) ?? null;
    if (
      !blocker ||
      blocker.loaded ||
      blocker.currentEdgeId ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0
    ) {
      return false;
    }
    if (this.agentRefreshTemporaryYieldInProgress(blocker)) {
      return true;
    }

    if (this.tryYieldInboundQueueEntrantAwayFromLoadedExit(blocker, requester)) {
      return true;
    }

    if (this.tryMoveTopLiftQueueBlockerDeeper(blocker, requester, blockedTargetNodeId)) {
      return true;
    }

    if (this.tryDisplaceAgentRefreshTopLiftSpineBlocker(blocker, requester, blockedTargetNodeId)) {
      return true;
    }

    if (this.tryYieldStorageAwayFromLoadedInboundDropoffRoute(blocker, requester)) {
      return true;
    }
    if (this.agentRefreshClearanceRouteInProgressAwayFrom(blocker, blockedTargetNodeId)) {
      return true;
    }
    if (
      blocker.waitReason === 'route-unavailable' &&
      this.agentRefreshInstallSideYield(blocker, blockedTargetNodeId, requester, null)
    ) {
      return true;
    }

    const task = this.taskForVehicle(blocker);
    const goals = this.agentEmptyEscapeGoalCandidates(blocker, requester, blockedTargetNodeId)
      .filter((goal) => this.agentEmptyEscapeGoalAllowed(blocker, goal));
    const taskGoal = blocker.waitReason === 'route-unavailable'
      ? null
      : this.agentGoalNodeId(blocker, task);
    if (taskGoal && this.agentEmptyEscapeGoalAllowed(blocker, taskGoal)) {
      goals.push(taskGoal);
    }

    const seen = new Set<string>();
    for (const goal of goals) {
      if (!goal || goal === blocker.currentNodeId || seen.has(goal)) {
        continue;
      }
      seen.add(goal);
      try {
        const blockedNodeIds = this.agentStaticBlockedNodeIds(blocker, goal);
        for (const nodeId of this.agentDynamicBlockedNodeIds(blocker)) {
          blockedNodeIds.add(nodeId);
        }
        blockedNodeIds.add(requester.currentNodeId);
        if (requester.targetNodeId) {
          blockedNodeIds.add(requester.targetNodeId);
        }
        blockedNodeIds.delete(blocker.currentNodeId);
        const route = this.agentShortestPath(blocker.currentNodeId, goal, blockedNodeIds);
        const isTaskGoal = taskGoal !== null && goal === taskGoal;
        if (this.agentEmptyEscapeRouteCrossesStoredLoad(route, isTaskGoal ? goal : null)) {
          continue;
        }
        if (!isTaskGoal && this.agentEmptyEscapeRouteRepeatsLastStorageStep(blocker, route)) {
          continue;
        }
        if (!this.agentEmptyEscapeRouteClearsRequester(blocker, requester, route)) {
          continue;
        }
        if (!isTaskGoal && !this.agentYieldEscapeRouteAcceptable(route)) {
          continue;
        }
        if (isTaskGoal) {
          const directRoute = this.agentNominalRouteToGoal(blocker, task, goal);
          if (!this.agentLocalRerouteAcceptable(directRoute, route)) {
            continue;
          }
        }
        if (this.agentMinimalEnabled() && isTaskGoal && route.length > 8) {
          continue;
        }
        const nextNodeId = route[1] ?? null;
        const nextBlock = nextNodeId
          ? this.agentMinimalEnabled()
            ? this.agentMinimalMoveBlocker(blocker, nextNodeId)
            : this.agentMoveBlocker(blocker, nextNodeId)
          : { reason: 'route-unavailable', blockingVehicleId: null };
        const effectiveNextBlock = nextBlock && this.emptyStorageEscapeMovesAwayFromLoadedRequester(
          blocker,
          requester,
          blockedTargetNodeId,
          nextNodeId,
          nextBlock
        )
          ? null
          : nextBlock;
        if (!nextNodeId || effectiveNextBlock) {
          continue;
        }
        const alreadyFollowingRoute =
          blocker.routeNodeIds.length === route.length &&
          blocker.routeNodeIds.every((nodeId, index) => nodeId === route[index]) &&
          blocker.targetNodeId === nextNodeId;
        blocker.routeNodeIds = route;
        blocker.routeIndex = 0;
        blocker.targetNodeId = nextNodeId;
        blocker.state = blocker.taskId ? 'assigned' : 'returning';
        blocker.waitReason = null;
        blocker.blockingReservationId = null;
        blocker.blockingVehicleId = null;
        if (isTaskGoal) {
          blocker.yieldHoldUntilSec = null;
          blocker.yieldHoldNodeId = null;
          blocker.localRouteNodeIds = [];
          blocker.localRouteReason = null;
        } else {
          blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, route) + 8);
          blocker.yieldHoldNodeId = route.at(-1) ?? null;
          blocker.localRouteNodeIds = route;
          blocker.localRouteReason = 'temporary-yield';
        }
        if (!alreadyFollowingRoute) {
          this.logAgentReroute(
            blocker,
            task,
            blockedTargetNodeId,
            route,
            isTaskGoal ? 'empty-task-route-clears-loaded' : 'empty-yields-to-loaded',
            { countTaskReplan: false }
          );
        }
        const session = this.agentRefreshEnabled() ? this.activeConflictSessionForPair(requester.id, blocker.id) : null;
        if (session && session.yielderVehicleId === blocker.id) {
          session.state = 'yielding';
          session.updatedAtSec = this.simTimeSec;
          session.yielderOriginalNodeId = blocker.currentNodeId;
          session.yielderPocketNodeId = route.at(-1) ?? null;
          session.yielderLocalRouteNodeIds = route;
          session.resumeNodeId = blockedTargetNodeId;
          session.clearancePolicy = 'immediate-next-move';
        }
        return true;
      } catch {
        continue;
      }
    }

    return false;
  }

  private agentEmptyEscapeRouteCrossesStoredLoad(routeNodeIds: string[], allowedTerminalNodeId: string | null): boolean {
    return routeNodeIds.slice(1).some((nodeId) =>
      nodeId !== allowedTerminalNodeId &&
      this.isStorageNode(nodeId) &&
      this.storedLoadIdAtNode(nodeId) !== null
    );
  }

  private tryMoveTopLiftQueueBlockerDeeper(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.agentRefreshEnabled() ||
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0
    ) {
      return false;
    }
    const currentSlot = topLiftQueueParkingSlot(blocker.currentNodeId);
    const currentAccess = topLiftQueueAisleAccess(blocker.currentNodeId);
    const currentLiftNodeId = currentSlot?.liftNodeId ?? currentAccess?.liftNodeId ?? null;
    const currentSlotIndex = currentSlot?.slotIndex ?? currentAccess?.slotIndex ?? 0;
    if (!currentLiftNodeId || currentSlotIndex <= 0) {
      return false;
    }
    const requesterLiftNodeId =
      this.topLiftQueueServiceLiftNodeId(blockedTargetNodeId) ??
      this.topLiftQueueServiceLiftNodeId(requester.currentNodeId) ??
      (requester.targetNodeId ? this.topLiftQueueServiceLiftNodeId(requester.targetNodeId) : null);
    if (requesterLiftNodeId && requesterLiftNodeId !== currentLiftNodeId) {
      return false;
    }

    for (let slotIndex = currentSlotIndex + 1; slotIndex <= 3; slotIndex += 1) {
      const deeperNodeId = liftQueueNodeId(currentLiftNodeId, slotIndex);
      if (
        !this.layoutNode(deeperNodeId) ||
        this.currentNodeOccupancy.has(deeperNodeId) ||
        this.nodeClaimedByOtherVehicle(deeperNodeId, blocker.id)
      ) {
        continue;
      }
      let routeNodeIds: string[];
      try {
        routeNodeIds = this.agentRefreshShortestPath(blocker.currentNodeId, deeperNodeId, new Set([requester.currentNodeId]));
      } catch {
        continue;
      }
      const nextNodeId = routeNodeIds[1] ?? null;
      if (
        !nextNodeId ||
        routeNodeIds.at(-1) !== deeperNodeId ||
        !this.agentRefreshLocalRouteNodesClear(blocker, routeNodeIds)
      ) {
        continue;
      }

      blocker.routeNodeIds = routeNodeIds;
      blocker.routeIndex = 0;
      blocker.targetNodeId = nextNodeId;
      blocker.state = blocker.taskId ? 'assigned' : 'returning';
      blocker.waitReason = null;
      blocker.blockingReservationId = null;
      blocker.blockingVehicleId = null;
      blocker.waitingSinceSec = null;
      blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, routeNodeIds) + 8);
      blocker.yieldHoldNodeId = deeperNodeId;
      blocker.localRouteNodeIds = routeNodeIds;
      blocker.localRouteReason = 'temporary-yield';
      this.logAgentReroute(blocker, this.taskForVehicle(blocker), blockedTargetNodeId, routeNodeIds, 'agent-refresh-queue-blocker-deeper', { countTaskReplan: false });
      return true;
    }
    return false;
  }

  private tryDisplaceAgentRefreshTopLiftSpineBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): boolean {
    if (
      !this.agentRefreshEnabled() ||
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      blocker.loaded ||
      blocker.currentNodeId !== blockedTargetNodeId ||
      !this.topLiftColumnSpineOrAccessNode(blocker.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(requester.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(blockedTargetNodeId)
    ) {
      return false;
    }

    const forbiddenNodeIds = new Set<string>([
      requester.currentNodeId,
      blockedTargetNodeId
    ]);
    if (requester.targetNodeId) {
      forbiddenNodeIds.add(requester.targetNodeId);
    }
    const requesterContinuationNodeId = this.agentRouteNodeAfter(requester, blockedTargetNodeId);
    if (requesterContinuationNodeId) {
      forbiddenNodeIds.add(requesterContinuationNodeId);
    }

    const escapeNodeId = this.neighbors(blocker.currentNodeId)
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => {
        const node = this.layoutNode(neighbor.nodeId);
        if (!node) {
          return false;
        }
        if (!blocker.loaded && this.isStorageNode(neighbor.nodeId)) {
          return this.traffic.findEdge(blocker.currentNodeId, neighbor.nodeId) !== null &&
            this.agentRefreshTemporaryStorageNodeAllowed(blocker, neighbor.nodeId);
        }
        return this.topLiftColumnSpineOrAccessNode(neighbor.nodeId) &&
          !node.noStop &&
          this.agentRefreshYieldPocketAllowed(blocker, neighbor.nodeId);
      })
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(blocker, neighbor.nodeId, requester))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(blocker, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => !this.nodeClaimedByOtherVehicle(neighbor.nodeId, blocker.id))
      .sort((left, right) =>
        this.topLiftAdjacentSwapEscapeRank(left.nodeId) - this.topLiftAdjacentSwapEscapeRank(right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0]?.nodeId ?? null;
    if (!escapeNodeId) {
      return false;
    }

    const routeNodeIds = [blocker.currentNodeId, escapeNodeId];
    if (!this.agentRefreshLocalRouteNodesClear(blocker, routeNodeIds)) {
      return false;
    }

    if (!this.installAgentRefreshTopLiftSpineCycleYield(blocker, routeNodeIds, forbiddenNodeIds)) {
      return false;
    }
    const session = this.activeConflictSessionForPair(requester.id, blocker.id);
    if (session && session.yielderVehicleId === blocker.id) {
      session.state = 'yielding';
      session.updatedAtSec = this.simTimeSec;
      session.yielderOriginalNodeId = blocker.currentNodeId;
      session.yielderPocketNodeId = escapeNodeId;
      session.yielderLocalRouteNodeIds = routeNodeIds;
      session.resumeNodeId = blockedTargetNodeId;
      session.clearancePolicy = 'immediate-next-move';
    }
    return true;
  }

  private emptyStorageEscapeMovesAwayFromLoadedRequester(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string,
    nextNodeId: string | null,
    block: { reason: string; blockingVehicleId: string | null }
  ): boolean {
    if (
      !nextNodeId ||
      !requester.loaded ||
      block.blockingVehicleId !== requester.id ||
      (block.reason !== 'min-separation' && block.reason !== 'avoidance-clearance') ||
      !this.isStorageNode(blocker.currentNodeId) ||
      !this.isStorageNode(nextNodeId) ||
      this.topLiftColumnKey(blocker.currentNodeId) !== this.topLiftColumnKey(nextNodeId)
    ) {
      return false;
    }
    const current = nodePosition(this.scenario, blocker.currentNodeId);
    const next = nodePosition(this.scenario, nextNodeId);
    const blockedTarget = nodePosition(this.scenario, blockedTargetNodeId);
    const currentDistance = Math.hypot(current.x - blockedTarget.x, current.z - blockedTarget.z);
    const nextDistance = Math.hypot(next.x - blockedTarget.x, next.z - blockedTarget.z);
    return nextDistance > currentDistance + 1e-6;
  }

  private agentEmptyEscapeRouteClearsRequester(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    route: string[]
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !requester.loaded || route.length < 2) {
      return true;
    }
    return route.slice(1).every((nodeId) =>
      this.agentRefreshYieldPocketCompatibleWithRequester(blocker, nodeId, requester)
    );
  }

  private emptyMoveIncreasesClearanceFromLoadedBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded || !blocker.loaded) {
      return false;
    }
    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    const currentDistanceM = Math.hypot(vehicle.x - blocker.x, vehicle.z - blocker.z);
    const targetDistanceM = Math.hypot(target.x - blocker.x, target.z - blocker.z);
    return targetDistanceM > currentDistanceM + 0.1;
  }

  private clearanceMoveEndpointFootprintsClear(vehicle: MutableVehicle, toNodeId: string, blocker: MutableVehicle): boolean {
    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    return this.clearanceMovePoseFootprintsClear(vehicle, target.x, target.z, blocker);
  }

  private clearanceMovePoseFootprintsClear(vehicle: MutableVehicle, targetX: number, targetZ: number, blocker: MutableVehicle): boolean {
    return this.predictedFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z) !== blocker.id &&
      this.predictedFootprintOverlapVehicleId(vehicle, targetX, targetZ) !== blocker.id;
  }

  private loadedMoveIncreasesClearanceFromLoadedBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      !blocker.loaded ||
      !this.topLiftColumnSpineOrAccessNode(vehicle.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(toNodeId)
    ) {
      return false;
    }
    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    const dx = target.x - vehicle.x;
    const dz = target.z - vehicle.z;
    const lengthM = Math.hypot(dx, dz);
    if (lengthM <= 1e-9) {
      return false;
    }
    const blockerProjection = ((blocker.x - vehicle.x) * dx + (blocker.z - vehicle.z) * dz) / lengthM;
    if (blockerProjection > 0.05) {
      return false;
    }
    const currentDistanceM = Math.hypot(vehicle.x - blocker.x, vehicle.z - blocker.z);
    const targetDistanceM = Math.hypot(target.x - blocker.x, target.z - blocker.z);
    return targetDistanceM > currentDistanceM + 0.1;
  }

  private topLiftMoveIncreasesClearanceFromBlocker(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !this.topLiftColumnSpineOrAccessNode(vehicle.currentNodeId) ||
      !this.topLiftColumnSpineOrAccessNode(toNodeId)
    ) {
      return false;
    }
    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    const dx = target.x - vehicle.x;
    const dz = target.z - vehicle.z;
    const lengthM = Math.hypot(dx, dz);
    if (lengthM <= 1e-9) {
      return false;
    }
    const blockerProjection = ((blocker.x - vehicle.x) * dx + (blocker.z - vehicle.z) * dz) / lengthM;
    if (blockerProjection > 0.05) {
      return false;
    }
    const currentDistanceM = Math.hypot(vehicle.x - blocker.x, vehicle.z - blocker.z);
    const targetDistanceM = Math.hypot(target.x - blocker.x, target.z - blocker.z);
    return targetDistanceM > currentDistanceM + 0.1;
  }

  private topLiftSeparatingMoveFromFootprintBlockerAllowed(
    vehicle: MutableVehicle,
    toNodeId: string,
    blocker: MutableVehicle,
    nextPose?: { x: number; z: number }
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !this.topLiftConflictRecoveryNode(vehicle.currentNodeId) ||
      !this.topLiftConflictRecoveryNode(toNodeId) ||
      vehicle.id === blocker.id
    ) {
      return false;
    }
    const target = this.layoutNode(toNodeId);
    if (!target) {
      return false;
    }
    if (this.predictedFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z) !== blocker.id) {
      return false;
    }
    const currentDistanceM = Math.hypot(vehicle.x - blocker.x, vehicle.z - blocker.z);
    const endDistanceM = Math.hypot(target.x - blocker.x, target.z - blocker.z);
    const nextDistanceM = nextPose
      ? Math.hypot(nextPose.x - blocker.x, nextPose.z - blocker.z)
      : endDistanceM;
    return endDistanceM > currentDistanceM + 0.05 && nextDistanceM >= currentDistanceM - 1e-6;
  }

  private topLiftConflictRecoveryNode(nodeId: string): boolean {
    return isTopLiftColumnAccessNodeId(nodeId) ||
      topLiftQueueAisleAccess(nodeId) !== null ||
      topLiftQueueParkingSlot(nodeId) !== null ||
      topLiftQueueEntrySlot(nodeId) !== null ||
      topLiftQueueServiceSlot(nodeId) !== null;
  }

  private agentEmptyEscapeRouteRepeatsLastStorageStep(vehicle: MutableVehicle, route: string[]): boolean {
    if (route.length !== 2 || !this.isStorageNode(route[0]!) || !this.isStorageNode(route[1]!)) {
      return false;
    }

    const previousNodeId = vehicle.routeIndex > 0 ? vehicle.routeNodeIds[vehicle.routeIndex - 1] : null;
    return previousNodeId === route[1];
  }

  private agentYieldEscapeRouteAcceptable(route: string[]): boolean {
    const goalNodeId = route.at(-1);
    if (!goalNodeId) {
      return false;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      this.isStorageNode(route[0]!) &&
      isTopLiftColumnAccessNodeId(goalNodeId)
    ) {
      const directColumnExit = this.topLiftDirectStorageColumnExitRoute(route[0]!, goalNodeId);
      if (directColumnExit && directColumnExit.join('>') === route.join('>')) {
        return true;
      }
    }
    const maxNodes = this.isStorageNode(goalNodeId) ? 5 : 4;
    const maxDistanceM = this.isStorageNode(goalNodeId) ? 18 : 12;
    return route.length <= maxNodes && this.routeDistanceM(route) <= maxDistanceM;
  }

  private agentEmptyEscapeGoalAllowed(vehicle: MutableVehicle, goalNodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled() || !this.isStorageNode(goalNodeId)) {
      return true;
    }
    const task = this.taskForVehicle(vehicle);
    if (
      task?.kind === 'inbound' &&
      vehicle.plannedGoalNodeId !== null &&
      topLiftQueueParkingSlot(vehicle.plannedGoalNodeId) !== null
    ) {
      return false;
    }
    if (task?.kind === 'outbound' && goalNodeId !== task.pickupNodeId) {
      return false;
    }
    return true;
  }

  private agentEmptyEscapeGoalCandidates(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): string[] {
    const rowLabel = this.nodeStorageRowLabel(vehicle.currentNodeId) ?? this.nodeStorageRowLabel(blockedTargetNodeId);
    if (!rowLabel) {
      return this.agentMainLaneEscapeGoalCandidates(vehicle, requester, blockedTargetNodeId);
    }
    if (this.topLiftColumnLayoutEnabled()) {
      const storageNodeId = this.isStorageNode(vehicle.currentNodeId)
        ? vehicle.currentNodeId
        : this.isStorageNode(blockedTargetNodeId)
          ? blockedTargetNodeId
          : null;
      if (storageNodeId) {
        const storagePosition = nodePosition(this.scenario, storageNodeId);
        const storageGoals = this.scenario.layout.nodes
          .filter((node) => node.type === 'storage' && this.nodeStorageRowLabel(node.id) === rowLabel)
          .sort((left, right) => {
            const leftDistance = Math.abs(left.x - storagePosition.x) + Math.abs(left.z - storagePosition.z);
            const rightDistance = Math.abs(right.x - storagePosition.x) + Math.abs(right.z - storagePosition.z);
            return leftDistance - rightDistance || left.id.localeCompare(right.id);
          })
          .map((node) => node.id);
        return [...this.inboundStorageExitNodeCandidates(storageNodeId), ...storageGoals];
      }
    }
    const rowNumber = rowLabel.replace(/^r/, '');
    const leftSide = `left-row-${rowNumber}`;
    const rightSide = `right-row-${rowNumber}`;
    const requesterNodeId = requester.targetNodeId ?? requester.currentNodeId;
    const requesterComesFromLeft = requester.currentNodeId.startsWith('left-row-') || requesterNodeId.startsWith('left-row-');
    const sideGoals = requesterComesFromLeft ? [rightSide, leftSide] : [leftSide, rightSide];
    const immediatePocket = this.agentStorageEntryNodeId(vehicle.currentNodeId);
    const storageGoals = this.scenario.layout.nodes
      .filter((node) => node.type === 'storage' && this.nodeStorageRowLabel(node.id) === rowLabel)
      .sort((left, right) =>
        Math.abs(right.x - nodePosition(this.scenario, requester.currentNodeId).x) -
        Math.abs(left.x - nodePosition(this.scenario, requester.currentNodeId).x) ||
        left.id.localeCompare(right.id)
      )
      .map((node) => node.id);
    return [immediatePocket, ...sideGoals, ...storageGoals].filter((nodeId): nodeId is string => nodeId !== null);
  }

  private agentMainLaneEscapeGoalCandidates(
    vehicle: MutableVehicle,
    requester: MutableVehicle,
    blockedTargetNodeId: string
  ): string[] {
    const vehiclePosition = nodePosition(this.scenario, vehicle.currentNodeId);
    const requesterPosition = nodePosition(this.scenario, requester.currentNodeId);
    const forbidden = new Set<string>([
      vehicle.currentNodeId,
      requester.currentNodeId,
      blockedTargetNodeId
    ]);
    if (requester.targetNodeId) {
      forbidden.add(requester.targetNodeId);
    }

    const candidates = this.scenario.layout.nodes
      .filter((node) =>
        !forbidden.has(node.id) &&
        (
          node.type === 'storage' ||
          (node.type === 'intersection' && /^left-row-|^right-row-/.test(node.id))
        )
      )
      .map((node) => {
        const distanceM = Math.abs(node.x - vehiclePosition.x) + Math.abs(node.z - vehiclePosition.z);
        const requesterDistanceM = Math.abs(node.x - requesterPosition.x) + Math.abs(node.z - requesterPosition.z);
        return { node, distanceM, requesterDistanceM };
      })
      .sort((left, right) =>
        (left.node.type === 'storage' ? -1 : 1) - (right.node.type === 'storage' ? -1 : 1) ||
        left.distanceM - right.distanceM ||
        right.requesterDistanceM - left.requesterDistanceM ||
        left.node.id.localeCompare(right.node.id)
      )
      .slice(0, 16)
      .map((candidate) => candidate.node.id);

    return [...new Set(candidates)];
  }

  private logAgentReroute(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    blockedNodeId: string,
    route: string[],
    reason: string,
    options: { countTaskReplan?: boolean } = {}
  ): void {
    this.replanCount += 1;
    if (task && options.countTaskReplan !== false) {
      task.replanCount += 1;
    }
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, task?.loadId ?? null, vehicle.currentNodeId, route.at(-1) ?? null, reason, this.vehiclePosition(vehicle), {
      blockedNodeId,
      route: route.join('>')
    });
  }

  private agentTurnPriority(vehicle: MutableVehicle): number {
    const task = this.taskForVehicle(vehicle);
    const ageSec = task ? Math.max(0, this.simTimeSec - task.createdAtSec) : 0;
    const liftServiceDeparturePriority = this.topLiftLoadedInboundServiceDeparturePriority(vehicle, task);
    const loadPriority = vehicle.loaded ? 1_000_000 : 0;
    const taskPriority = vehicle.taskId ? 100_000 : 0;
    const waitPriority = vehicle.state === 'waiting-blocked' ? 10_000 : 0;
    const stagedSameLiftPickupPenalty =
      task && !vehicle.loaded && this.inboundTaskShouldWaitBeforePickup(task) ? 90_000 : 0;
    return liftServiceDeparturePriority + loadPriority + taskPriority + waitPriority + ageSec - stagedSameLiftPickupPenalty - this.vehicleOrdinal(vehicle.id) / 1000;
  }

  private topLiftLoadedInboundServiceDeparturePriority(vehicle: MutableVehicle, task: TaskStateRecord | null): number {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      task?.kind !== 'inbound' ||
      !vehicle.targetNodeId
    ) {
      return 0;
    }

    const segment = this.topLiftActiveServiceClearanceSegment(vehicle);
    if (segment && this.liftPortKindForNodeId(segment.liftNodeId) === 'inbound') {
      return 10_000_000;
    }

    const currentServiceSlot = topLiftQueueServiceSlot(vehicle.currentNodeId);
    const currentEntrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    const targetServiceSlot = topLiftQueueServiceSlot(vehicle.targetNodeId);
    const targetEntrySlot = topLiftQueueEntrySlot(vehicle.targetNodeId);
    const liftNodeId =
      currentServiceSlot?.liftNodeId ??
      currentEntrySlot?.liftNodeId ??
      targetServiceSlot?.liftNodeId ??
      targetEntrySlot?.liftNodeId ??
      null;
    if (liftNodeId && this.liftPortKindForNodeId(liftNodeId) === 'inbound') {
      return 5_000_000;
    }

    return 0;
  }

  private startNextLeg(vehicle: MutableVehicle, dtSec: number): void {
    const fromNodeId = vehicle.currentNodeId;
    const task = this.taskById(vehicle.taskId);

    if (this.redirectTopLiftQueueAccessToParking(vehicle)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }

    if (this.redirectTopLiftQueueEntryRetreat(vehicle)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }

    if (task && fromNodeId === task.pickupNodeId && !vehicle.loaded) {
      if (!this.inboundTaskLoadReadyAtPickup(task)) {
        if (!this.inboundPickupClearanceRouteActive(vehicle, task)) {
          if (this.rerouteInboundPickupVehicleBehindEarlierTask(vehicle, task)) {
            return;
          }
          this.waitForInboundPickupLoad(vehicle, task, dtSec);
          return;
        }
        this.syncActiveInboundPickupClearanceRoute(vehicle, task);
      } else {
        this.setTaskState(task, 'in-progress');
        task.startedAtSec ??= this.simTimeSec;
        vehicle.state = 'lifting';
        vehicle.speedMps = 0;
        vehicle.phaseRemainingSec = this.scenario.physicsParams.liftTimeSec;
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
        this.ensureZoneHoldReservation(vehicle, fromNodeId);
        this.logEvent('lift-started', vehicle.id, task.id, task.loadId, fromNodeId, fromNodeId, 'pickup-aligned', this.vehiclePosition(vehicle), {});
        return;
      }
    }

    if (task && fromNodeId === task.dropoffNodeId && vehicle.loaded) {
      vehicle.state = 'lowering';
      vehicle.speedMps = 0;
      vehicle.phaseRemainingSec = this.scenario.physicsParams.lowerTimeSec;
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.logEvent('lower-started', vehicle.id, task.id, task.loadId, fromNodeId, fromNodeId, 'dropoff-aligned', this.vehiclePosition(vehicle), {});
      return;
    }

    if (task && this.tryYieldUnreadyInboundQueueLeader(vehicle, task)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }

    if (task && this.tryAdvanceInboundPickupTopAHoldAway(vehicle, task)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }

    const toNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 1];

    if (!toNodeId) {
      if (task) {
        const recoveredRoute = this.restoreMissingTaskRouteAtCurrentNode(vehicle, task, 'task-route-missing-recovered');
        if (recoveredRoute) {
          this.startNextLeg(vehicle, dtSec);
          return;
        }
      }
      if (!vehicle.taskId) {
        vehicle.state = 'parking';
        vehicle.phaseRemainingSec = 0;
      } else {
        vehicle.state = 'idle';
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
      }
      return;
    }

    const currentOccupant = this.currentNodeOccupancy.get(fromNodeId);
    if (this.collisionAvoidanceEnabled() && currentOccupant && currentOccupant !== vehicle.id) {
      const waitReason = 'node-occupancy-mismatch';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, currentOccupant);
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = currentOccupant;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: currentOccupant
        });
      }
      return;
    }

    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (!edge) {
      vehicle.state = 'faulted';
      vehicle.waitReason = 'route-edge-missing';
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      this.error = `Missing route edge ${fromNodeId} -> ${toNodeId}`;
      this.logEvent('vehicle-faulted', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, 'route-edge-missing', this.vehiclePosition(vehicle), {});
      return;
    }

    const strictBlock = this.strictMoveSafetyBlocker(vehicle, toNodeId);
    if (strictBlock) {
      if (this.tryMoveDeeperIntoStorageRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = strictBlock.reason;
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, strictBlock.blockingVehicleId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = strictBlock.blockingVehicleId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: strictBlock.blockingVehicleId
        });
      }
      return;
    }

    const refugeExitBlock = this.storageRefugeExitBlock(vehicle, task, fromNodeId, toNodeId, edge);
    if (refugeExitBlock) {
      if (this.tryMoveDeeperIntoStorageRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const shouldLogWait = this.shouldLogVehicleWait(
        vehicle,
        toNodeId,
        refugeExitBlock.reason,
        refugeExitBlock.blockingReservationId,
        refugeExitBlock.blockingVehicleId
      );
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = refugeExitBlock.reason;
      vehicle.blockingReservationId = refugeExitBlock.blockingReservationId;
      vehicle.blockingVehicleId = refugeExitBlock.blockingVehicleId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(refugeExitBlock.reason, round((this.blockedTimeByReasonSec.get(refugeExitBlock.reason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, refugeExitBlock.reason, this.vehiclePosition(vehicle), {
          blockingReservationId: refugeExitBlock.blockingReservationId,
          blockingVehicleId: refugeExitBlock.blockingVehicleId
        });
      }
      return;
    }

    const liftIngressBlock = this.liftIngressStagingBlock(vehicle, toNodeId, task);
    if (liftIngressBlock) {
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, liftIngressBlock.reason, null, liftIngressBlock.blockingVehicleId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = liftIngressBlock.reason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = liftIngressBlock.blockingVehicleId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(liftIngressBlock.reason, round((this.blockedTimeByReasonSec.get(liftIngressBlock.reason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, liftIngressBlock.reason, this.vehiclePosition(vehicle), {
          blockingVehicleId: liftIngressBlock.blockingVehicleId
        });
      }
      return;
    }

    const inboundQueueEntryBlockerId = this.collisionAvoidanceEnabled()
      ? this.topLiftInboundQueueEntryLoadedColumnBlocker(vehicle, toNodeId)
      : null;
    if (inboundQueueEntryBlockerId) {
      const waitReason = 'lift-column-near';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, inboundQueueEntryBlockerId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = inboundQueueEntryBlockerId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: inboundQueueEntryBlockerId
        });
      }
      return;
    }

    let closeNextOccupantId = this.closeOccupiedNextNode(vehicle, toNodeId);
    if (
      closeNextOccupantId &&
      this.topLiftQueueDeeperClearanceOverlapAllowed(vehicle, toNodeId, closeNextOccupantId)
    ) {
      closeNextOccupantId = null;
    }
    if (closeNextOccupantId) {
      const closeNextOccupant = this.vehicles.find((candidate) => candidate.id === closeNextOccupantId) ?? null;
      if (closeNextOccupant && this.topLiftServiceExitOverlapAllowed(vehicle, toNodeId, closeNextOccupant)) {
        closeNextOccupantId = null;
      }
      if (
        closeNextOccupantId &&
        this.topLiftOutboundClearanceExitPastWaitingLoadedOutboundAllowed(vehicle, toNodeId, closeNextOccupantId)
      ) {
        closeNextOccupantId = null;
      }
      if (
        closeNextOccupantId &&
        this.topLiftOutboundEntryPastTrailingLoadedFollowerAllowed(vehicle, toNodeId, closeNextOccupantId)
      ) {
        closeNextOccupantId = null;
      }
      if (
        closeNextOccupantId &&
        closeNextOccupant &&
        this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, closeNextOccupant)
      ) {
        closeNextOccupantId = null;
      }
    }
    if (closeNextOccupantId) {
      if (this.tryMoveDeeperIntoStorageRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      if (vehicle.loaded && this.agentRefreshEnabled()) {
        this.agentTryDisplaceEmptyBlocker(closeNextOccupantId, vehicle, toNodeId);
      }
      const waitReason = 'min-separation';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, closeNextOccupantId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = closeNextOccupantId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: closeNextOccupantId
        });
      }
      return;
    }

    const clearingTargetId = this.movingVehicleClearingNode(toNodeId, vehicle);
    if (clearingTargetId) {
      const waitReason = 'node-clearing';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, clearingTargetId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = clearingTargetId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: clearingTargetId
        });
      }
      return;
    }

    const movingTargetClaimId = this.collisionAvoidanceEnabled() ? this.movingVehicleTargetingNode(toNodeId, vehicle.id) : null;
    if (movingTargetClaimId) {
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = 'node-reserved';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, movingTargetClaimId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = movingTargetClaimId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: movingTargetClaimId
        });
      }
      return;
    }

    const occupiedTargetId = this.collisionAvoidanceEnabled() ? this.currentNodeOccupancy.get(toNodeId) : null;
    if (occupiedTargetId && occupiedTargetId !== vehicle.id) {
      if (this.tryMoveDeeperIntoStorageRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = this.liftPortWaitReason(toNodeId) ?? 'node-occupied';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, occupiedTargetId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = occupiedTargetId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: occupiedTargetId
        });
      }
      return;
    }

    const portalHoldBlock = this.collisionAvoidanceEnabled() ? this.portalNodeHoldBlock(vehicle, toNodeId) : null;
    if (portalHoldBlock) {
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = 'zone-reserved';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, portalHoldBlock.id, null);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = portalHoldBlock.id;
      vehicle.blockingVehicleId = null;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingReservationId: portalHoldBlock.id
        });
      }
      return;
    }

    let leadingVehicleId = this.leadingVehicleTooClose(vehicle, fromNodeId, toNodeId);
    if (leadingVehicleId) {
      const leadingVehicle = this.vehicles.find((candidate) => candidate.id === leadingVehicleId) ?? null;
      if (leadingVehicle && this.topLiftServiceExitOverlapAllowed(vehicle, toNodeId, leadingVehicle)) {
        leadingVehicleId = null;
      }
      if (
        leadingVehicleId &&
        leadingVehicle &&
        this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, toNodeId, leadingVehicle)
      ) {
        leadingVehicleId = null;
      }
    }
    if (leadingVehicleId) {
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = 'min-separation';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, leadingVehicleId);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = leadingVehicleId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: leadingVehicleId
        });
      }
      return;
    }

    const authorization = this.authorizeRouteHorizon(vehicle, task);

    if (!authorization.ok) {
      if (
        authorization.reasonCode === 'no-stop-continuation-blocked' &&
        toNodeId &&
        this.tryExtendAgentRefreshNoStopContinuation(vehicle, toNodeId)
      ) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      if (this.tryInsertEmptySideAisleRefuge(vehicle, toNodeId)) {
        this.startNextLeg(vehicle, dtSec);
        return;
      }
      const waitReason = this.liftPortWaitReason(toNodeId) ?? authorization.reasonCode;
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, authorization.blockingReservationId, null);
      this.reservationConflictCount += 1;
      vehicle.state = 'waiting-blocked';
      vehicle.speedMps = 0;
      vehicle.targetNodeId = toNodeId;
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = authorization.blockingReservationId;
      vehicle.blockingVehicleId = null;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.ensureZoneHoldReservation(vehicle, fromNodeId);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingReservationId: authorization.blockingReservationId
        });
      }
      return;
    }

    this.installMoveReservationsReplacingSelfOverlap(vehicle, authorization.reservations);
    this.releaseNodeOccupancy(vehicle, fromNodeId);
    vehicle.directionSwitchReadyNodeId = null;
    vehicle.waitingSinceSec = null;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.targetNodeId = toNodeId;
    vehicle.legRemainingM = this.routeLegDistanceM(authorization.edge);
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = authorization.travelSec;
    vehicle.currentEdgeId = authorization.edge.id;
    vehicle.targetSpeedMps = authorization.speedMps;
    vehicle.legStartYaw = vehicle.yaw;
    vehicle.legMotionMode = authorization.motionMode;
    if (!authorization.reusedExisting) {
      this.logEvent('reservation-created', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, 'route-horizon', this.vehiclePosition(vehicle), {
        edgeId: authorization.edge.id,
        reservationIds: authorization.reservations.map((reservation) => reservation.id).join(','),
        motionMode: vehicle.legMotionMode,
        horizonLegCount: authorization.horizonLegCount
      });
    }
    this.advanceMovement(vehicle, dtSec);
  }

  private redirectTopLiftQueueAccessToParking(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return false;
    }
    const accessSlot = topLiftQueueAisleAccess(vehicle.currentNodeId);
    const plannedSlot = topLiftQueueParkingSlot(vehicle.plannedGoalNodeId ?? '');
    if (
      !accessSlot ||
      !plannedSlot ||
      accessSlot.liftNodeId !== plannedSlot.liftNodeId ||
      accessSlot.slotIndex !== plannedSlot.slotIndex ||
      this.liftPortKindForNodeId(accessSlot.liftNodeId) !== 'inbound'
    ) {
      return false;
    }
    const parkingNodeId = liftQueueNodeId(accessSlot.liftNodeId, accessSlot.slotIndex);
    if (vehicle.currentNodeId === parkingNodeId || vehicle.targetNodeId === parkingNodeId) {
      return false;
    }
    const route = [vehicle.currentNodeId, parkingNodeId];
    if (!this.routeEdgesExist(route)) {
      return false;
    }
    const previousTargetNodeId = vehicle.targetNodeId;
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = parkingNodeId;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.localRouteNodeIds = this.localClaimPrefixForRoute(vehicle.id, route);
    vehicle.localRouteReason = 'top-lift-queue-access-correction';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), previousTargetNodeId ?? parkingNodeId, route, 'agent-refresh-top-lift-queue-access-correction', { countTaskReplan: false });
    return true;
  }

  private redirectTopLiftQueueEntryRetreat(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return false;
    }
    const entrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
    const plannedSlot = topLiftQueueParkingSlot(vehicle.plannedGoalNodeId ?? '');
    if (
      !entrySlot ||
      !plannedSlot ||
      entrySlot.liftNodeId !== plannedSlot.liftNodeId ||
      entrySlot.slotIndex !== plannedSlot.slotIndex
    ) {
      return false;
    }
    const nextNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 1] ?? vehicle.targetNodeId;
    if (!nextNodeId || !/^column-top-a-c\d+$/.test(nextNodeId)) {
      return false;
    }
    const accessNodeId = liftQueueTailAccessNodeId(entrySlot.liftNodeId, entrySlot.slotIndex);
    const parkingNodeId = liftQueueNodeId(entrySlot.liftNodeId, entrySlot.slotIndex);
    const route = [vehicle.currentNodeId, accessNodeId, parkingNodeId];
    if (!this.routeEdgesExist(route)) {
      return false;
    }
    vehicle.routeNodeIds = route;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = route[1] ?? null;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.localRouteNodeIds = this.localClaimPrefixForRoute(vehicle.id, route);
    vehicle.localRouteReason = 'top-lift-queue-entry-correction';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), nextNodeId, route, 'agent-refresh-top-lift-queue-entry-correction', { countTaskReplan: false });
    return true;
  }

  private mustStopAtNode(vehicle: MutableVehicle, task: TaskStateRecord | null, nodeId: string): boolean {
    if (task && nodeId === task.pickupNodeId && !vehicle.loaded) {
      return true;
    }
    if (task && nodeId === task.dropoffNodeId && vehicle.loaded) {
      return true;
    }
    if (nodeId === vehicle.plannedGoalNodeId && topLiftQueueParkingSlot(nodeId)) {
      return true;
    }
    if (nodeId === vehicle.plannedGoalNodeId && this.topLiftInboundApproachQueueSlot(nodeId)) {
      return true;
    }
    if (
      (vehicle.localRouteReason === 'temporary-yield' || vehicle.localRouteReason === 'inbound-unready-queue-leader-yield') &&
      vehicle.yieldHoldNodeId === nodeId &&
      nodeId === vehicle.routeNodeIds.at(-1) &&
      this.topLiftTemporaryColumnAccessYieldHoldAllowed(vehicle, vehicle.routeNodeIds)
    ) {
      return true;
    }
    if (
      vehicle.localRouteReason === 'bottom-lane-meter-clearance' &&
      vehicle.yieldHoldNodeId === nodeId &&
      nodeId === vehicle.routeNodeIds.at(-1) &&
      topLiftAisleLevel(nodeId) === 'bottom-b' &&
      this.topLiftDoubleAisleOppositeLaneNode(vehicle.routeNodeIds[0] ?? '', nodeId)
    ) {
      return true;
    }
    return !task && nodeId === this.parkingNodeFor(vehicle.id);
  }

  private layoutNode(nodeId: string): LayoutNode | null {
    return this.layoutNodesById.get(nodeId) ?? null;
  }

  private targetNodeCanServeAsExitBuffer(vehicle: MutableVehicle, task: TaskStateRecord | null, nodeId: string): boolean {
    if (!this.layoutNode(nodeId)) {
      return false;
    }
    return !this.mustClearNoStopNode(vehicle, task, nodeId);
  }

  private mustClearNoStopNode(vehicle: MutableVehicle, task: TaskStateRecord | null, nodeId: string): boolean {
    if (!this.collisionAvoidanceEnabled()) {
      return false;
    }
    const nodeRequiresClearThrough = this.layoutNode(nodeId)?.noStop === true;
    const zoneRequiresClearThrough = this.zonesForNode(nodeId).some(
      (zone) => zone.noStop && (zone.edgeIds.length === 0 || zone.id.startsWith('zone-main-portal-node'))
    );
    return (nodeRequiresClearThrough || zoneRequiresClearThrough) && !this.mustStopAtNode(vehicle, task, nodeId);
  }

  private movementRequiresClearThrough(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    fromNodeId: string,
    toNodeId: string
  ): boolean {
    if (!this.collisionAvoidanceEnabled()) {
      return false;
    }
    if (this.targetNodeCanServeAsExitBuffer(vehicle, task, toNodeId)) {
      return false;
    }
    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (!edge) {
      return false;
    }
    const targetNodeRequiresClearThrough = this.layoutNode(toNodeId)?.noStop === true;
    const movementZoneRequiresClearThrough = this.traffic
      .zonesForMovement(fromNodeId, toNodeId, edge.id)
      .some((zone) => zone.noStop);
    return targetNodeRequiresClearThrough || movementZoneRequiresClearThrough;
  }

  private noStopArrivalBlock(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    fromNodeId: string,
    nodeId: string
  ): { reason: string; blockingReservationId: string | null; blockingVehicleId: string | null } | null {
    if (!this.movementRequiresClearThrough(vehicle, task, fromNodeId, nodeId)) {
      return null;
    }
    const nextNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 2];
    if (!nextNodeId) {
      return { reason: 'no-stop-continuation-blocked', blockingReservationId: null, blockingVehicleId: null };
    }

    const occupiedTargetId = this.currentNodeOccupancy.get(nextNodeId);
    if (occupiedTargetId && occupiedTargetId !== vehicle.id) {
      const blocker = this.vehicles.find((candidate) => candidate.id === occupiedTargetId) ?? null;
      if (blocker && this.agentRefreshEnabled() && this.agentRefreshBlockerIsBehindCurrentMove(vehicle, nodeId, blocker)) {
        return null;
      }
      if (blocker && this.topLiftSameDirectionNoStopFollowerAllowed(vehicle, nodeId, nextNodeId, blocker)) {
        return null;
      }
      return { reason: 'node-occupied', blockingReservationId: null, blockingVehicleId: occupiedTargetId };
    }

    const movingTargetClaimId = this.movingVehicleTargetingNode(nextNodeId, vehicle.id);
    if (movingTargetClaimId) {
      const blocker = this.vehicles.find((candidate) => candidate.id === movingTargetClaimId) ?? null;
      if (blocker && this.agentRefreshEnabled() && this.agentRefreshBlockerIsBehindCurrentMove(vehicle, nodeId, blocker)) {
        return null;
      }
      if (blocker && this.topLiftSameDirectionNoStopFollowerAllowed(vehicle, nodeId, nextNodeId, blocker)) {
        return null;
      }
      return { reason: 'node-reserved', blockingReservationId: null, blockingVehicleId: movingTargetClaimId };
    }

    const nextEdge = this.traffic.findEdge(nodeId, nextNodeId);
    if (!nextEdge) {
      return { reason: 'route-edge-missing', blockingReservationId: null, blockingVehicleId: null };
    }

    const motionMode = this.routeLegMotionMode(vehicle, nextEdge, nextNodeId, vehicle.routeIndex + 1, task);
    const travelSec = this.routeLegTravelSec(vehicle, nextEdge, nextNodeId, vehicle.routeIndex + 1, motionMode);
    const continuationStartTimeSec = this.simTimeSec + Math.max(0, vehicle.legTravelSec - vehicle.legElapsedSec);
    const requiredEndTimeSec = continuationStartTimeSec + travelSec + this.scenario.trafficPolicy.minimumClearanceSec;
    const tickEndToleranceSec = Math.max(this.scenario.timeStepSec, 1e-6);
    if (!this.hasSelfMoveAuthorizationAt(vehicle, nextEdge.id, nextNodeId, continuationStartTimeSec, requiredEndTimeSec, tickEndToleranceSec)) {
      return { reason: 'no-stop-continuation-blocked', blockingReservationId: null, blockingVehicleId: null };
    }

    return null;
  }

  private speedForEdge(vehicle: MutableVehicle, edge: ShuttleScenario['layout']['edges'][number]): number {
    const speedLimit = vehicle.loaded ? edge.speedLimitLoadedMps ?? this.scenario.physicsParams.loadedSpeedMps : edge.speedLimitEmptyMps ?? this.scenario.physicsParams.emptySpeedMps;
    return Math.min(speedLimit, vehicle.loaded ? this.scenario.physicsParams.loadedSpeedMps : this.scenario.physicsParams.emptySpeedMps);
  }

  private routeLegMotionMode(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    toNodeId: string,
    routeIndex: number,
    task: TaskStateRecord | null
  ): MutableVehicle['legMotionMode'] {
    const axis = this.axisForEdge(edge);
    if (!axis || this.mustStopAtNode(vehicle, task, toNodeId)) {
      return 'profile';
    }
    if (routeIndex === vehicle.routeIndex && vehicle.state === 'waiting-blocked' && vehicle.currentEdgeId !== null) {
      return 'profile';
    }
    const nextNodeId = vehicle.routeNodeIds[routeIndex + 2];
    if (!nextNodeId) {
      return 'profile';
    }
    const nextEdge = this.traffic.findEdge(toNodeId, nextNodeId);
    return nextEdge && this.axisForEdge(nextEdge) === axis ? 'cruise' : 'profile';
  }

  private previousAxisForRouteLeg(vehicle: MutableVehicle, routeIndex: number): MovementAxis {
    if (routeIndex <= vehicle.routeIndex) {
      return vehicle.lastMovementAxis;
    }
    const previousFromNodeId = vehicle.routeNodeIds[routeIndex - 1];
    const previousToNodeId = vehicle.routeNodeIds[routeIndex];
    if (!previousFromNodeId || !previousToNodeId) {
      return vehicle.lastMovementAxis;
    }
    return this.axisBetweenNodes(previousFromNodeId, previousToNodeId) ?? vehicle.lastMovementAxis;
  }

  private routeLegTurnDelaySec(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    routeIndex: number
  ): number {
    const previousAxis = this.previousAxisForRouteLeg(vehicle, routeIndex);
    const nextAxis = this.axisForEdge(edge);
    return previousAxis !== null && nextAxis !== null && previousAxis !== nextAxis
      ? this.scenario.physicsParams.switchDirectionSec
      : 0;
  }

  private routeLegTravelSec(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    toNodeId: string,
    routeIndex: number,
    motionMode: MutableVehicle['legMotionMode']
  ): number {
    const fullTravelSec = this.routeLegBaseTravelSec(vehicle, edge, motionMode);
    const turnDelaySec = this.routeLegTurnDelaySec(vehicle, edge, routeIndex);
    const isActiveCurrentLeg =
      vehicle.currentEdgeId === edge.id &&
      vehicle.targetNodeId === toNodeId &&
      vehicle.routeIndex === routeIndex;
    return isActiveCurrentLeg ? Math.max(0, vehicle.legTravelSec - vehicle.legElapsedSec) : fullTravelSec + turnDelaySec;
  }

  private routeLegBaseTravelSec(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    motionMode: MutableVehicle['legMotionMode']
  ): number {
    const speed = this.speedForEdge(vehicle, edge);
    const lengthM = this.routeLegDistanceM(edge);
    return motionMode === 'cruise'
      ? lengthM / Math.max(0.001, speed)
      : calculateTravelTimeSec(lengthM, speed, this.scenario.physicsParams.accelerationMps2);
  }

  private routeLegDistanceM(edge: ShuttleScenario['layout']['edges'][number]): number {
    const from = this.layoutNode(edge.from);
    const to = this.layoutNode(edge.to);
    if (!from || !to || (!this.topLiftDisplayProjectedNode(from.id) && !this.topLiftDisplayProjectedNode(to.id))) {
      return edge.lengthM;
    }
    const displayFrom = this.topLiftDisplayPointForNode(from.id, from);
    const displayTo = this.topLiftDisplayPointForNode(to.id, to);
    if (Math.abs(displayFrom.x - displayTo.x) <= 1e-6 && Math.abs(displayFrom.z - displayTo.z) <= 1e-6) {
      return edge.lengthM;
    }
    return this.topLiftOrthogonalDisplayPathLength(
      displayFrom,
      displayTo,
      Math.abs(to.x - from.x) >= Math.abs(to.z - from.z) ? 'x' : 'z'
    );
  }

  private topLiftOrthogonalDisplayPathLength(
    from: { x: number; z: number },
    to: { x: number; z: number },
    preferredAxis: 'x' | 'z'
  ): number {
    const midpoint = preferredAxis === 'x' ? { x: to.x, z: from.z } : { x: from.x, z: to.z };
    const segments = Math.abs(from.x - to.x) <= 1e-6 || Math.abs(from.z - to.z) <= 1e-6
      ? [{ from, to }]
      : [{ from, to: midpoint }, { from: midpoint, to }];
    return segments.reduce((sum, segment) =>
      sum + Math.hypot(segment.to.x - segment.from.x, segment.to.z - segment.from.z), 0
    );
  }

  private routeHorizonEligible(
    vehicle: MutableVehicle,
    task: TaskStateRecord | null,
    fromNodeId: string,
    toNodeId: string
  ): boolean {
    return this.mustClearNoStopNode(vehicle, task, fromNodeId) || this.movementRequiresClearThrough(vehicle, task, fromNodeId, toNodeId);
  }

  private collisionAvoidanceEnabled(): boolean {
    return this.scenario.trafficPolicy.collisionAvoidanceEnabled !== false;
  }

  private strictMoveSafetyBlocker(
    vehicle: MutableVehicle,
    toNodeId: string
  ): { reason: string; blockingVehicleId: string | null } | null {
    if (!this.collisionAvoidanceEnabled()) {
      return null;
    }

    const fromNodeId = vehicle.currentNodeId;
    const currentOccupant = this.currentNodeOccupancy.get(fromNodeId);
    if (currentOccupant && currentOccupant !== vehicle.id) {
      return { reason: 'node-occupancy-mismatch', blockingVehicleId: currentOccupant };
    }

    const targetOccupant = this.currentNodeOccupancy.get(toNodeId);
    if (targetOccupant && targetOccupant !== vehicle.id) {
      return { reason: this.liftPortWaitReason(toNodeId) ?? 'node-occupied', blockingVehicleId: targetOccupant };
    }

    const clearingCurrentId = this.movingVehicleClearingNode(fromNodeId, vehicle);
    if (clearingCurrentId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingCurrentId };
    }

    const clearingTargetId = this.movingVehicleClearingNode(toNodeId, vehicle);
    if (clearingTargetId) {
      return { reason: 'node-clearing', blockingVehicleId: clearingTargetId };
    }

    const movingTargetClaimId = this.movingVehicleTargetingNode(toNodeId, vehicle.id);
    if (movingTargetClaimId) {
      return { reason: 'node-reserved', blockingVehicleId: movingTargetClaimId };
    }

    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    if (edge) {
      const headOn = this.vehicles.find((other) =>
        other.id !== vehicle.id &&
        other.currentEdgeId === edge.id &&
        other.currentNodeId === toNodeId &&
        other.targetNodeId === fromNodeId
      );
      if (headOn) {
        return { reason: 'edge-head-on', blockingVehicleId: headOn.id };
      }
    }

    const leadingVehicleId = this.leadingVehicleTooClose(vehicle, fromNodeId, toNodeId);
    if (leadingVehicleId) {
      return { reason: 'min-separation', blockingVehicleId: leadingVehicleId };
    }

    const target = nodePosition(this.scenario, toNodeId);
    const targetFootprintBlockerId = this.predictedFootprintOverlapVehicleId(vehicle, target.x, target.z);
    if (targetFootprintBlockerId) {
      return { reason: 'min-separation', blockingVehicleId: targetFootprintBlockerId };
    }
    return null;
  }

  private agentMinimalEmptyStorageEscapeMove(
    vehicle: MutableVehicle,
    blockingVehicleId: string,
    nextX: number,
    nextZ: number
  ): boolean {
    if (
      (!this.agentMinimalEnabled() && !this.agentRefreshEnabled()) ||
      vehicle.loaded ||
      !vehicle.targetNodeId ||
      !this.isStorageNode(vehicle.targetNodeId)
    ) {
      return false;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockingVehicleId);
    if (!blocker) {
      return false;
    }
    const ignoredBlockerIds = new Set([blockingVehicleId]);
    if (this.predictedSweptFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z, nextX, nextZ, ignoredBlockerIds)) {
      return false;
    }
    const currentClearanceM = vehicleFootprintClearanceM(vehicle, blocker, this.scenario.vehicles);
    const nextClearanceM = vehicleFootprintClearanceM({ x: nextX, z: nextZ, yaw: vehicle.yaw }, blocker, this.scenario.vehicles);
    const target = nodePosition(this.scenario, vehicle.targetNodeId);
    const targetClearanceM = vehicleFootprintClearanceM({ x: target.x, z: target.z, yaw: vehicle.yaw }, blocker, this.scenario.vehicles);
    const nextOverlapsBlocker = vehicleFootprintsOverlap({ x: nextX, z: nextZ, yaw: vehicle.yaw }, blocker, this.scenario.vehicles);
    const targetOverlapsBlocker = vehicleFootprintsOverlap({ x: target.x, z: target.z, yaw: vehicle.yaw }, blocker, this.scenario.vehicles);
    return !nextOverlapsBlocker && !targetOverlapsBlocker && (nextClearanceM > currentClearanceM + 0.001 || targetClearanceM > currentClearanceM + 0.01);
  }

  private agentSimpleEnabled(): boolean {
    return this.scenario.trafficPolicy.controllerMode === 'agent-simple' || this.agentMinimalEnabled() || this.agentRefreshEnabled();
  }

  private agentSimpleModeEnabled(): boolean {
    return this.scenario.trafficPolicy.controllerMode === 'agent-simple';
  }

  private agentMinimalEnabled(): boolean {
    return this.scenario.trafficPolicy.controllerMode === 'agent-minimal';
  }

  private agentRefreshEnabled(): boolean {
    return this.scenario.trafficPolicy.controllerMode === 'agent-refresh';
  }

  private leadingVehicleTooClose(vehicle: MutableVehicle, fromNodeId: string, toNodeId: string): string | null {
    if (!this.collisionAvoidanceEnabled()) {
      return null;
    }
    const from = nodePosition(this.scenario, fromNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    const length = Math.hypot(dx, dz);
    if (length <= 1e-9) {
      return null;
    }

    const ux = dx / length;
    const uz = dz / length;
    const lateralToleranceM = Math.max(0.15, this.scenario.vehicles.widthM * 0.55);
    const headwayM = Math.max(
      this.scenario.vehicles.lengthM + this.scenario.vehicles.safetyRadiusM + 0.15,
      this.scenario.vehicles.lengthM * 2 + this.scenario.vehicles.safetyRadiusM
    );

    for (const other of this.vehicles) {
      if (other.id === vehicle.id) {
        continue;
      }
      const relX = other.x - from.x;
      const relZ = other.z - from.z;
      const projection = relX * ux + relZ * uz;
      if (projection <= 0 || projection > headwayM) {
        continue;
      }

      const lateral = Math.abs(relX * -uz + relZ * ux);
      if (lateral > lateralToleranceM) {
        continue;
      }

      const otherAheadOnSameLane =
        other.currentNodeId === toNodeId ||
        other.targetNodeId === toNodeId ||
        (other.currentEdgeId !== null && this.edgeIsCollinearWithVector(other.currentEdgeId, ux, uz, from));
      if (otherAheadOnSameLane) {
        return other.id;
      }
    }
    return null;
  }

  private edgeIsCollinearWithVector(edgeId: string, ux: number, uz: number, origin: { x: number; z: number }): boolean {
    const edge = this.scenario.layout.edges.find((candidate) => candidate.id === edgeId);
    if (!edge) {
      return false;
    }
    const from = nodePosition(this.scenario, edge.from);
    const to = nodePosition(this.scenario, edge.to);
    const edgeDx = to.x - from.x;
    const edgeDz = to.z - from.z;
    const edgeLength = Math.hypot(edgeDx, edgeDz);
    if (edgeLength <= 1e-9) {
      return false;
    }

    const edgeUx = edgeDx / edgeLength;
    const edgeUz = edgeDz / edgeLength;
    const parallel = Math.abs(edgeUx * ux + edgeUz * uz) >= 0.99;
    const lateral = Math.abs((from.x - origin.x) * -uz + (from.z - origin.z) * ux);
    return parallel && lateral <= Math.max(0.15, this.scenario.vehicles.widthM * 0.55);
  }

  private authorizeRouteHorizon(vehicle: MutableVehicle, task: TaskStateRecord | null): RouteLegAuthorization {
    const firstFromNodeId = vehicle.currentNodeId;
    const firstToNodeId = vehicle.routeNodeIds[vehicle.routeIndex + 1];
    if (!firstToNodeId) {
      return { ok: false, reasonCode: 'route-complete', blockingReservationId: null };
    }

    const firstEdge = this.traffic.findEdge(firstFromNodeId, firstToNodeId);
    if (!firstEdge) {
      return { ok: false, reasonCode: 'route-edge-missing', blockingReservationId: null };
    }

    const firstSpeed = this.speedForEdge(vehicle, firstEdge);
    const firstMotionMode = this.routeLegMotionMode(vehicle, firstEdge, firstToNodeId, vehicle.routeIndex, task);
    const firstTravelSec = this.routeLegTravelSec(vehicle, firstEdge, firstToNodeId, vehicle.routeIndex, firstMotionMode);
    const firstMovementMustClear = this.movementRequiresClearThrough(vehicle, task, firstFromNodeId, firstToNodeId);

    const requiredSelfAuthorizationEndSec = this.simTimeSec + firstTravelSec + this.scenario.trafficPolicy.minimumClearanceSec;
    if (
      !firstMovementMustClear &&
      this.hasActiveSelfMoveAuthorization(vehicle, firstEdge.id, firstToNodeId, requiredSelfAuthorizationEndSec)
    ) {
      return {
        ok: true,
        edge: firstEdge,
        speedMps: firstSpeed,
        travelSec: firstTravelSec,
        motionMode: firstMotionMode,
        reservations: [],
        horizonLegCount: 1,
        reusedExisting: true
      };
    }

    const priority = this.priorityFor(vehicle);
    const stagedReservations: Reservation[] = [];
    let horizonLegCount = 0;
    let cumulativeTravelSec = 0;
    let horizonAxis: 'x' | 'z' | null = null;
    let lastHorizonTargetNodeId = firstFromNodeId;

    for (
      let routeIndex = vehicle.routeIndex;
      routeIndex < vehicle.routeNodeIds.length - 1 && horizonLegCount < MAX_CLEAR_THROUGH_HORIZON_LEGS;
      routeIndex += 1
    ) {
      const fromNodeId = vehicle.routeNodeIds[routeIndex]!;
      const toNodeId = vehicle.routeNodeIds[routeIndex + 1]!;
      const edge = this.traffic.findEdge(fromNodeId, toNodeId);
      if (!edge) {
        return horizonLegCount === 0
          ? { ok: false, reasonCode: 'route-edge-missing', blockingReservationId: null }
          : {
              ok: true,
              edge: firstEdge,
              speedMps: firstSpeed,
              travelSec: firstTravelSec,
              motionMode: firstMotionMode,
              reservations: stagedReservations,
              horizonLegCount,
              reusedExisting: false
            };
      }

      const movementMustClear = this.movementRequiresClearThrough(vehicle, task, fromNodeId, toNodeId);
      const horizonEligible = this.routeHorizonEligible(vehicle, task, fromNodeId, toNodeId);
      if (horizonLegCount > 0 && !horizonEligible) {
        break;
      }

      const axis = this.axisForEdge(edge);
      const clearingNoStopTurn =
        movementMustClear ||
        this.mustClearNoStopNode(vehicle, task, fromNodeId) ||
        this.mustClearNoStopNode(vehicle, task, toNodeId);
      if (horizonLegCount > 0 && horizonAxis !== null && axis !== horizonAxis && !clearingNoStopTurn) {
        break;
      }

      const occupiedTargetId = this.collisionAvoidanceEnabled() ? this.currentNodeOccupancy.get(toNodeId) : null;
      if (occupiedTargetId && occupiedTargetId !== vehicle.id) {
        break;
      }

      const motionMode = this.routeLegMotionMode(vehicle, edge, toNodeId, routeIndex, task);
      const travelSec = this.routeLegTravelSec(vehicle, edge, toNodeId, routeIndex, motionMode);
      const nextCumulativeTravelSec = cumulativeTravelSec + travelSec;
      if (
        horizonLegCount > 0 &&
        nextCumulativeTravelSec > MAX_CLEAR_THROUGH_HORIZON_SEC &&
        this.targetNodeCanServeAsExitBuffer(vehicle, task, lastHorizonTargetNodeId)
      ) {
        break;
      }
      const legStartTimeSec = this.simTimeSec + cumulativeTravelSec;
      cumulativeTravelSec = nextCumulativeTravelSec;
      const attempt = this.traffic.reserveMove({
        vehicleId: vehicle.id,
        taskId: vehicle.taskId,
        fromNodeId,
        toNodeId,
        startTimeSec: legStartTimeSec,
        travelSec,
        priority,
        existing: [...this.reservations, ...stagedReservations],
        ignoreConflicts: !this.collisionAvoidanceEnabled()
      });

      if (!attempt.ok) {
        if (
          firstMovementMustClear &&
          (horizonLegCount < 2 || !this.targetNodeCanServeAsExitBuffer(vehicle, task, lastHorizonTargetNodeId))
        ) {
          return attempt;
        }
        return horizonLegCount === 0
          ? attempt
          : {
              ok: true,
              edge: firstEdge,
              speedMps: firstSpeed,
              travelSec: firstTravelSec,
              motionMode: firstMotionMode,
              reservations: stagedReservations,
              horizonLegCount,
              reusedExisting: false
            };
      }

      stagedReservations.push(...attempt.reservations);
      horizonLegCount += 1;
      horizonAxis = axis ?? horizonAxis;
      lastHorizonTargetNodeId = toNodeId;

      if (this.mustStopAtNode(vehicle, task, toNodeId)) {
        break;
      }
      if (!horizonEligible && !this.mustClearNoStopNode(vehicle, task, toNodeId)) {
        break;
      }
    }

    if (firstMovementMustClear && horizonLegCount < 2) {
      return { ok: false, reasonCode: 'no-stop-continuation-blocked', blockingReservationId: null };
    }
    if (firstMovementMustClear && !this.targetNodeCanServeAsExitBuffer(vehicle, task, lastHorizonTargetNodeId)) {
      return { ok: false, reasonCode: 'no-stop-clearance-incomplete', blockingReservationId: null };
    }

    return {
      ok: true,
      edge: firstEdge,
      speedMps: firstSpeed,
      travelSec: firstTravelSec,
      motionMode: firstMotionMode,
      reservations: stagedReservations,
      horizonLegCount,
      reusedExisting: false
    };
  }

  private advanceMovement(vehicle: MutableVehicle, dtSec: number): void {
    const fromNodeId = vehicle.currentNodeId;
    const toNodeId = vehicle.targetNodeId;
    if (!toNodeId) {
      return;
    }
    const task = this.taskById(vehicle.taskId);
    if (task && vehicle.loaded && fromNodeId === task.dropoffNodeId) {
      const dropoffPosition = nodePosition(this.scenario, fromNodeId);
      vehicle.x = dropoffPosition.x;
      vehicle.y = SHUTTLE_Y_M;
      vehicle.z = dropoffPosition.z;
      vehicle.speedMps = 0;
      vehicle.targetNodeId = null;
      vehicle.currentEdgeId = null;
      vehicle.legRemainingM = 0;
      vehicle.legElapsedSec = 0;
      vehicle.legTravelSec = 0;
      vehicle.state = 'lowering';
      vehicle.phaseRemainingSec = this.scenario.physicsParams.lowerTimeSec;
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      this.logEvent('lower-started', vehicle.id, task.id, task.loadId, fromNodeId, fromNodeId, 'dropoff-aligned', this.vehiclePosition(vehicle), {});
      return;
    }
    if (vehicle.state === 'waiting-blocked' && this.redirectTopLiftQueueEntryRetreat(vehicle)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }
    if (vehicle.state === 'waiting-blocked' && this.redirectTopLiftQueueAccessToParking(vehicle)) {
      this.startNextLeg(vehicle, dtSec);
      return;
    }
    const from = nodePosition(this.scenario, fromNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    const usesTopLiftDisplayMotion = this.topLiftDisplayProjectedNode(fromNodeId) || this.topLiftDisplayProjectedNode(toNodeId);
    const displayFrom = usesTopLiftDisplayMotion ? this.topLiftDisplayPointForNode(fromNodeId, from) : from;
    const displayTo = usesTopLiftDisplayMotion ? this.topLiftDisplayPointForNode(toNodeId, to) : to;
    const edge = this.traffic.findEdge(fromNodeId, toNodeId);
    const lengthM = edge?.lengthM
      ? this.routeLegDistanceM(edge)
      : Math.hypot(displayTo.x - displayFrom.x, displayTo.z - displayFrom.z);
    const targetYaw = yawForSegment(displayFrom, displayTo);
    const remainingLegSec = Math.max(0, vehicle.legTravelSec - vehicle.legElapsedSec);
    const previousLegElapsedSec = vehicle.legElapsedSec;
    const previousLegRemainingM = vehicle.legRemainingM;
    const previousYaw = vehicle.yaw;
    const usedSec = Math.min(dtSec, remainingLegSec);
    vehicle.legElapsedSec = round(Math.min(vehicle.legTravelSec, vehicle.legElapsedSec + usedSec));
    const configuredTurnDelaySec = edge ? this.routeLegTurnDelaySec(vehicle, edge, vehicle.routeIndex) : 0;
    const baseTravelSec = edge ? this.routeLegBaseTravelSec(vehicle, edge, vehicle.legMotionMode) : vehicle.legTravelSec;
    const turnDelaySec = Math.max(0, Math.min(configuredTurnDelaySec, vehicle.legTravelSec - baseTravelSec));
    const motionElapsedSec = Math.max(0, vehicle.legElapsedSec - turnDelaySec);
    const legYaw = turnDelaySec > 0
      ? interpolateYaw(vehicle.legStartYaw, targetYaw, vehicle.legElapsedSec / turnDelaySec)
      : targetYaw;
    vehicle.yaw = round(legYaw);
    const profile = vehicle.legMotionMode === 'cruise'
      ? {
          distanceM: motionElapsedSec * vehicle.targetSpeedMps,
          speedMps: motionElapsedSec > 0 ? vehicle.targetSpeedMps : 0
        }
      : motionProfileAt(
          motionElapsedSec,
          lengthM,
          vehicle.targetSpeedMps,
          this.scenario.physicsParams.accelerationMps2
    );
    const legCompleteByTime = vehicle.legElapsedSec >= vehicle.legTravelSec - 1e-6;
    const traveledM = legCompleteByTime ? lengthM : Math.min(lengthM, profile.distanceM);
    const progress = lengthM <= 0 ? 1 : traveledM / lengthM;
    const rawNextX = from.x + (to.x - from.x) * progress;
    const rawNextZ = from.z + (to.z - from.z) * progress;
    const displayNext = usesTopLiftDisplayMotion
      ? this.topLiftPointOnOrthogonalDisplayPath(
          displayFrom,
          displayTo,
          progress,
          Math.abs(to.x - from.x) >= Math.abs(to.z - from.z) ? 'x' : 'z'
        )
      : { x: rawNextX, z: rawNextZ };
    const nextX = round(displayNext.x);
    const nextZ = round(displayNext.z);

    const outboundDockCorridorBlockerId = this.collisionAvoidanceEnabled() && this.agentRefreshEnabled()
      ? this.topLiftOutboundDockCorridorActiveBottomMoveBlocker(vehicle, nextX, nextZ)
      : null;
    if (outboundDockCorridorBlockerId) {
      const waitReason = 'outbound-lift-dock-corridor';
      const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, outboundDockCorridorBlockerId);
      vehicle.legElapsedSec = previousLegElapsedSec;
      vehicle.legRemainingM = previousLegRemainingM;
      vehicle.yaw = previousYaw;
      vehicle.speedMps = 0;
      vehicle.state = 'waiting-blocked';
      vehicle.waitReason = waitReason;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = outboundDockCorridorBlockerId;
      vehicle.waitingSinceSec ??= this.simTimeSec;
      vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
      this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
      if (shouldLogWait) {
        this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
          blockingVehicleId: outboundDockCorridorBlockerId
        });
      }
      return;
    }

    if (legCompleteByTime && !this.agentSimpleEnabled()) {
      let noStopBlock = this.noStopArrivalBlock(vehicle, task, fromNodeId, toNodeId);
      if (
        noStopBlock &&
        (noStopBlock.reason === 'no-stop-continuation-blocked' || noStopBlock.reason === 'no-stop-clearance-incomplete')
      ) {
        const authorization = this.authorizeRouteHorizon(vehicle, task);
        if (authorization.ok) {
          const installedReservations = this.installMoveReservationsReplacingSelfOverlap(vehicle, authorization.reservations);
          noStopBlock = this.noStopArrivalBlock(vehicle, task, fromNodeId, toNodeId);
          if (noStopBlock) {
            this.rollbackMoveReservationInstall(installedReservations.installed, installedReservations.removed);
          }
        }
      }

      if (noStopBlock) {
        const holdDistanceM = Math.min(0.15, Math.max(0.01, lengthM * 0.05));
        const holdProgress = lengthM <= 1e-9 ? 0 : Math.max(0, (lengthM - holdDistanceM) / lengthM);
        const shouldLogWait = this.shouldLogVehicleWait(
          vehicle,
          toNodeId,
          noStopBlock.reason,
          noStopBlock.blockingReservationId,
          noStopBlock.blockingVehicleId
        );
        vehicle.legElapsedSec = round(Math.max(0, vehicle.legTravelSec - 0.001));
        vehicle.legRemainingM = round(holdDistanceM);
        vehicle.speedMps = 0;
        vehicle.x = round(from.x + (to.x - from.x) * holdProgress);
        vehicle.y = SHUTTLE_Y_M;
        vehicle.z = round(from.z + (to.z - from.z) * holdProgress);
        vehicle.state = 'waiting-blocked';
        vehicle.waitReason = noStopBlock.reason;
        vehicle.blockingReservationId = noStopBlock.blockingReservationId;
        vehicle.blockingVehicleId = noStopBlock.blockingVehicleId;
        vehicle.waitingSinceSec ??= this.simTimeSec;
        vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
        this.blockedTimeByReasonSec.set(noStopBlock.reason, round((this.blockedTimeByReasonSec.get(noStopBlock.reason) ?? 0) + dtSec));
        if (shouldLogWait) {
          this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, noStopBlock.reason, this.vehiclePosition(vehicle), {
            blockingReservationId: noStopBlock.blockingReservationId,
            blockingVehicleId: noStopBlock.blockingVehicleId
          });
        }
        return;
      }
    }

    let footprintBlockerId = this.collisionAvoidanceEnabled()
      ? this.predictedSweptFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z, nextX, nextZ)
      : null;
    if (footprintBlockerId) {
      if (this.agentMinimalEmptyStorageEscapeMove(vehicle, footprintBlockerId, nextX, nextZ)) {
        vehicle.waitReason = null;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = null;
      } else {
        if (vehicle.loaded && this.agentRefreshEnabled()) {
          this.agentTryDisplaceEmptyBlocker(footprintBlockerId, vehicle, toNodeId);
        }
        const waitReason = this.agentMinimalEnabled() ? 'avoidance-clearance' : 'min-separation';
        const shouldLogWait = this.shouldLogVehicleWait(vehicle, toNodeId, waitReason, null, footprintBlockerId);
        vehicle.legElapsedSec = previousLegElapsedSec;
        vehicle.legRemainingM = previousLegRemainingM;
        vehicle.yaw = previousYaw;
        vehicle.speedMps = 0;
        vehicle.state = 'waiting-blocked';
        vehicle.waitReason = waitReason;
        vehicle.blockingReservationId = null;
        vehicle.blockingVehicleId = footprintBlockerId;
        vehicle.waitingSinceSec ??= this.simTimeSec;
        vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
        this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
        if (shouldLogWait) {
          this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, fromNodeId, toNodeId, waitReason, this.vehiclePosition(vehicle), {
            blockingVehicleId: footprintBlockerId
          });
        }
        if (this.agentRefreshEnabled()) {
          this.tryRetreatAgentRefreshNearFaceoff([vehicle.id, footprintBlockerId]);
        }
        return;
      }
    }

    if (vehicle.state === 'waiting-blocked') {
      vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
      vehicle.waitReason = null;
      vehicle.blockingReservationId = null;
      vehicle.blockingVehicleId = null;
      vehicle.waitingSinceSec = null;
    }

    vehicle.legRemainingM = round(Math.max(0, lengthM - traveledM));
    vehicle.speedMps = round(vehicle.legRemainingM <= 0 ? 0 : profile.speedMps);
    vehicle.x = nextX;
    vehicle.y = SHUTTLE_Y_M;
    vehicle.z = nextZ;
    vehicle.yaw = round(legYaw);

    if (vehicle.legRemainingM > 0) {
      return;
    }

    const previousNode = vehicle.currentNodeId;
    vehicle.currentNodeId = toNodeId;
    this.occupyNode(vehicle, toNodeId);
    vehicle.routeIndex += 1;
    vehicle.lastMovementAxis = edge ? this.axisForEdge(edge) : vehicle.lastMovementAxis;
    vehicle.targetNodeId = null;
    vehicle.currentEdgeId = null;
    vehicle.targetSpeedMps = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.legMotionMode = 'profile';
    vehicle.speedMps = 0;
    this.logEvent('vehicle-arrived', vehicle.id, task?.id ?? null, task?.loadId ?? null, previousNode, toNodeId, 'route-arrival', this.vehiclePosition(vehicle), {});

    if (task && toNodeId === task.pickupNodeId && !vehicle.loaded) {
      if (this.holdInboundPickupBeforePredecessor(vehicle, task, dtSec)) {
        return;
      }
      if (!this.inboundTaskLoadReadyAtPickup(task)) {
        if (!this.inboundPickupClearanceRouteActive(vehicle, task) && this.rerouteInboundPickupVehicleBehindEarlierTask(vehicle, task)) {
          return;
        }
        this.waitForInboundPickupLoad(vehicle, task, dtSec);
        return;
      }
      this.startInboundPickupLift(vehicle, task, toNodeId);
      return;
    }

    if (task && toNodeId === task.dropoffNodeId && vehicle.loaded) {
      vehicle.state = 'lowering';
      vehicle.phaseRemainingSec = this.scenario.physicsParams.lowerTimeSec;
      this.logEvent('lower-started', vehicle.id, task.id, task.loadId, previousNode, toNodeId, 'dropoff-aligned', this.vehiclePosition(vehicle), {});
      return;
    }

    if (!task && toNodeId === this.parkingNodeFor(vehicle.id)) {
      vehicle.state = 'parking';
      vehicle.phaseRemainingSec = 0;
      return;
    }

    vehicle.state = 'assigned';
    const remainingStepSec = round(Math.max(0, dtSec - usedSec));
    if (remainingStepSec > 1e-6 && this.movementContinuationDepth < 8) {
      this.movementContinuationDepth += 1;
      try {
        if (this.agentSimpleEnabled()) {
          this.startNextLegAgentSimple(vehicle, remainingStepSec);
        } else {
          this.startNextLeg(vehicle, remainingStepSec);
        }
      } finally {
        this.movementContinuationDepth -= 1;
      }
    }
  }

  private topLiftInboundQueueHoldActive(task: TaskStateRecord, vehicle: MutableVehicle): boolean {
    if (
      task.kind !== 'inbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.currentNodeId === task.pickupNodeId
    ) {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    const approachSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
    return Boolean(
      liftNodeId &&
      approachSlot?.liftNodeId === liftNodeId &&
      (
        this.inboundTaskShouldWaitBeforePickup(task) ||
        this.inboundTaskHasEarlierPickupTask(task) ||
        !this.inboundTaskLoadReadyAtPickup(task)
      )
    );
  }

  private topLiftInboundQueueHoldReason(task: TaskStateRecord): string {
    if (this.inboundTaskHasEarlierPickupTask(task)) {
      return 'inbound-lift-fifo-wait';
    }
    if (this.topLiftInboundColumnPredecessorPending(task)) {
      return 'inbound-column-predecessor-wait';
    }
    if (!this.inboundTaskLoadReadyAtPickup(task)) {
      return this.inboundSourceUnavailableReason();
    }
    return 'inbound-lift-fifo-wait';
  }

  private topLiftFifoHeldVehicle(vehicle: MutableVehicle): boolean {
    if (vehicle.waitReason === 'inbound-lift-fifo-wait' || vehicle.waitReason === 'outbound-lift-fifo-wait') {
      return true;
    }
    const task = this.taskForVehicle(vehicle);
    return Boolean(
      task &&
      (
        this.topLiftInboundQueueHoldActive(task, vehicle) ||
        this.topLiftOutboundMeterHoldActive(task, vehicle)
      )
    );
  }

  private topLiftInboundQueueClearingVehicle(vehicle: MutableVehicle): boolean {
    if (this.topLiftInboundQueueCompressingVehicle(vehicle)) {
      return true;
    }
    if (vehicle.loaded || this.topLiftFifoHeldVehicle(vehicle)) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    const slot = this.topLiftQueueSlotForNode(vehicle.currentNodeId);
    if (!slot || slot.liftNodeId !== liftNodeId || vehicle.currentNodeId === task.pickupNodeId) {
      return false;
    }
    return vehicle.routeNodeIds.includes(task.pickupNodeId) ||
      vehicle.plannedGoalNodeId === task.pickupNodeId ||
      vehicle.targetNodeId === task.pickupNodeId;
  }

  private topLiftInboundQueueCompressingVehicle(vehicle: MutableVehicle): boolean {
    if (vehicle.loaded || !vehicle.targetNodeId || !this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return false;
    }
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId || this.liftPortKindForNodeId(liftNodeId) !== 'inbound') {
      return false;
    }
    const currentSlot = this.topLiftQueueSlotForNode(vehicle.currentNodeId);
    const targetSlot = this.topLiftQueueSlotForNode(vehicle.targetNodeId);
    const finalSlot = this.topLiftQueueSlotForNode(vehicle.routeNodeIds.at(-1) ?? '');
    return Boolean(
      currentSlot &&
      targetSlot &&
      finalSlot &&
      currentSlot.liftNodeId === liftNodeId &&
      targetSlot.liftNodeId === liftNodeId &&
      finalSlot.liftNodeId === liftNodeId &&
      this.liftPortKindForNodeId(currentSlot.liftNodeId) === 'inbound' &&
      isTopLiftQueueParkingNodeId(vehicle.currentNodeId) &&
      isTopLiftQueueParkingNodeId(vehicle.targetNodeId) &&
      targetSlot.slotIndex > currentSlot.slotIndex &&
      finalSlot.slotIndex >= targetSlot.slotIndex
    );
  }

  private topLiftOutboundMeterHoldActive(task: TaskStateRecord, vehicle: MutableVehicle): boolean {
    if (
      task.kind !== 'outbound' ||
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      vehicle.currentEdgeId !== null
    ) {
      return false;
    }
    const meterSlot = this.topLiftOutboundMeterSlot(vehicle.currentNodeId);
    const liftNodeId = this.taskLiftPortNodeId(task);
    return Boolean(
      liftNodeId &&
      meterSlot?.liftNodeId === liftNodeId &&
      this.outboundTaskHasEarlierDropoffTask(task)
    );
  }

  private holdAtTopLiftQueueNode(vehicle: MutableVehicle, holdNodeId: string, waitReason: string, dtSec: number): void {
    const shouldLogWait = this.shouldLogVehicleWait(vehicle, holdNodeId, waitReason, null, null);
    vehicle.state = 'waiting-blocked';
    vehicle.speedMps = 0;
    vehicle.routeNodeIds = [holdNodeId];
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = holdNodeId;
    vehicle.currentEdgeId = null;
    vehicle.legRemainingM = 0;
    vehicle.legElapsedSec = 0;
    vehicle.legTravelSec = 0;
    vehicle.targetSpeedMps = 0;
    vehicle.waitReason = waitReason;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec ??= this.simTimeSec;
    vehicle.blockedTimeSec = round(vehicle.blockedTimeSec + dtSec);
    this.blockedTimeByReasonSec.set(waitReason, round((this.blockedTimeByReasonSec.get(waitReason) ?? 0) + dtSec));
    if (shouldLogWait) {
      this.logEvent('vehicle-waiting', vehicle.id, vehicle.taskId, null, vehicle.currentNodeId, holdNodeId, waitReason, this.vehiclePosition(vehicle), {});
    }
  }

  private priorityFor(vehicle: MutableVehicle): number {
    const task = this.taskById(vehicle.taskId);
    const base = task?.createdAtSec ?? this.simTimeSec;
    const age = Math.floor((this.simTimeSec - base) / Math.max(1, this.scenario.trafficPolicy.priorityAgingSec));
    return age * 1000 - Number(vehicle.id.replace(/\D+/g, '') || 0);
  }

  private updateDeadlockSmokeCounters(): void {
    if (this.agentRefreshEnabled() && this.tryYieldInboundQueueEntrantsBlockingLoadedExits()) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshReciprocalEdgeFaceoff()) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    const loadedStorageSwapCandidateVehicleIds = this.agentRefreshLoadedStorageSwapCandidateVehicleIds();
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshLoadedStorageSwap(loadedStorageSwapCandidateVehicleIds)) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshStorageColumnQueue(this.agentRefreshLoadedStorageSwapPairVehicleIds(loadedStorageSwapCandidateVehicleIds))) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryClearTopLiftLoadedOutboundStorageExitBlockers(loadedStorageSwapCandidateVehicleIds)) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryClearTopLiftBottomLaneMeterBlockers(loadedStorageSwapCandidateVehicleIds)) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshColumnAccessStorageSwap(loadedStorageSwapCandidateVehicleIds)) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshColumnAccessStorageSwap(this.agentRefreshWaitingBlockedVehicleIds())) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftAdjacentNodeSwap(this.agentRefreshWaitingBlockedVehicleIds())) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshWaitCycle(this.agentRefreshNoStopContinuationWaitCandidateVehicleIds())) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftSpineCycle(this.agentRefreshTopLiftSpineCycleWaitCandidateVehicleIds())) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    const deadlockCandidateVehicleIds = this.deadlockCandidateVehicleIds();
    if (deadlockCandidateVehicleIds.length < 2) {
      this.deadlockCandidateSignature = null;
      this.deadlockCandidateSinceSec = null;
      return;
    }
    const signature = deadlockCandidateVehicleIds.join(',');
    if (signature !== this.deadlockCandidateSignature) {
      this.deadlockCandidateSignature = signature;
      this.deadlockCandidateSinceSec = this.simTimeSec;
      return;
    }
    if (this.deadlockCandidateSinceSec !== null && this.simTimeSec - this.deadlockCandidateSinceSec >= this.scenario.trafficPolicy.deadlockDetectSec) {
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshLoadedStorageSwap(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryClearTopLiftLoadedOutboundStorageExitBlockers(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryClearTopLiftBottomLaneMeterBlockers(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshColumnAccessStorageSwap(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshStorageColumnQueue(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftAdjacentNodeSwap(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftQueueAccessParkingSwap(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftSpineCycle(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshTopLiftServiceClearanceCycle(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryRetreatAgentRefreshNearFaceoff(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.tryBreakAgentRefreshWaitCycle(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentMinimalEnabled() && this.tryRetreatAgentMinimalLoadedFaceoff(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentMinimalEnabled() && this.tryRetreatAgentMinimalEdgeBlocker(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentMinimalEnabled() && this.tryBreakAgentMinimalWaitCycle(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.tryBreakPortalHoldCycle(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      if (this.agentRefreshEnabled() && this.deadlockCandidateHasActiveRecovery(deadlockCandidateVehicleIds)) {
        this.deadlockCandidateSignature = null;
        this.deadlockCandidateSinceSec = null;
        return;
      }
      this.deadlockCount += 1;
      this.deadlockCandidateSinceSec = this.simTimeSec;
      this.logEvent('deadlock-detected', null, null, null, null, null, 'phase0-smoke-detector', null, {
        waitingVehicles: signature
      });
    }
  }

  private deadlockCandidateVehicleIds(): string[] {
    const waitingVehicles = this.vehicles.filter((vehicle) => vehicle.state === 'waiting-blocked');
    const waitFor = new Map<string, string>();
    for (const vehicle of waitingVehicles) {
      const blockingVehicleId = vehicle.blockingVehicleId ?? this.blockingVehicleForReservation(vehicle.blockingReservationId);
      if (blockingVehicleId && blockingVehicleId !== vehicle.id) {
        if (this.agentRefreshEnabled() && !this.agentRefreshDeadlockBlockerStillApplies(vehicle, blockingVehicleId)) {
          continue;
        }
        waitFor.set(vehicle.id, blockingVehicleId);
      }
    }

    const cycleVehicleIds = new Set<string>();
    for (const vehicleId of waitFor.keys()) {
      const seen = new Set<string>();
      let cursor: string | undefined = vehicleId;
      while (cursor) {
        if (seen.has(cursor)) {
          for (const id of seen) {
            cycleVehicleIds.add(id);
          }
          break;
        }
        seen.add(cursor);
        cursor = waitFor.get(cursor);
      }
    }
    return [...cycleVehicleIds].sort((left, right) => left.localeCompare(right));
  }

  private agentRefreshWaitingBlockedVehicleIds(): string[] {
    return this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.blockingVehicleId !== null &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0
      )
      .map((vehicle) => vehicle.id)
      .sort((left, right) => left.localeCompare(right));
  }

  private agentRefreshTopLiftSpineCycleWaitCandidateVehicleIds(): string[] {
    const reasons = new Set([
      'middle-aisle-opposing-claim',
      'top-lift-spine-opposing-claim',
      'no-stop-continuation-blocked',
      'node-occupied'
    ]);
    const minWaitSec = Math.max(2, this.scenario.trafficPolicy.deadlockDetectSec);
    const ids = this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.waitReason !== null &&
        reasons.has(vehicle.waitReason) &&
        (vehicle.waitingSinceSec === null || this.simTimeSec - vehicle.waitingSinceSec >= minWaitSec) &&
        (
          isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-b') ||
          isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
          isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'middle') ||
          isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'top-b') ||
          isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
          isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'middle')
        )
      )
      .map((vehicle) => vehicle.id)
      .sort((left, right) => left.localeCompare(right));
    return ids.length >= 2 ? ids : [];
  }

  private deadlockCandidateHasActiveRecovery(candidateVehicleIds: string[]): boolean {
    const shortRecoveryWindowSec = Math.max(6, this.scenario.trafficPolicy.deadlockDetectSec * 3);
    for (const vehicleId of candidateVehicleIds) {
      const vehicle = this.vehicles.find((candidate) => candidate.id === vehicleId);
      if (!vehicle) {
        continue;
      }
      if (vehicle.currentEdgeId !== null || vehicle.legRemainingM > 1e-6) {
        return true;
      }
      const hasPendingLocalRoute =
        vehicle.localRouteReason === 'temporary-yield' &&
        vehicle.routeNodeIds.length > vehicle.routeIndex + 1 &&
        (vehicle.targetNodeId === null || vehicle.targetNodeId !== vehicle.currentNodeId);
      const localWaitAgeSec = vehicle.waitingSinceSec === null ? 0 : this.simTimeSec - vehicle.waitingSinceSec;
      if (hasPendingLocalRoute && localWaitAgeSec < shortRecoveryWindowSec) {
        return true;
      }
      if (
        vehicle.waitReason === 'local-yield-hold' &&
        vehicle.yieldHoldUntilSec !== null &&
        this.simTimeSec < vehicle.yieldHoldUntilSec
      ) {
        return true;
      }
    }
    return false;
  }

  private agentRefreshDeadlockBlockerStillApplies(vehicle: MutableVehicle, blockingVehicleId: string): boolean {
    if (vehicle.waitReason === 'local-yield-hold') {
      const task = this.taskForVehicle(vehicle);
      const block = this.agentRefreshYieldHoldBlocker(vehicle, task);
      return block?.blockingVehicleId === blockingVehicleId;
    }

    if (vehicle.waitReason === 'min-separation' || vehicle.waitReason === 'avoidance-clearance') {
      return this.agentRefreshFootprintBlockerStillApplies(vehicle, blockingVehicleId);
    }

    if (vehicle.waitReason === 'node-occupied' || vehicle.waitReason === 'node-target-near') {
      return this.agentRefreshNodeBlockerStillApplies(vehicle, blockingVehicleId);
    }

    return true;
  }

  private agentRefreshNodeBlockerStillApplies(vehicle: MutableVehicle, blockingVehicleId: string): boolean {
    if (!vehicle.targetNodeId) {
      return false;
    }
    const blocker = this.vehicles.find((candidate) => candidate.id === blockingVehicleId) ?? null;
    if (!blocker) {
      return false;
    }
    return blocker.currentNodeId === vehicle.targetNodeId || blocker.targetNodeId === vehicle.targetNodeId;
  }

  private agentRefreshFootprintBlockerStillApplies(vehicle: MutableVehicle, blockingVehicleId: string): boolean {
    const ignoredVehicleIds = new Set<string>();
    const blocker = this.vehicles.find((candidate) => candidate.id === blockingVehicleId) ?? null;
    if (
      blocker &&
      vehicle.targetNodeId &&
      this.topLiftInboundQueueExitClearingEntryBlockerAllowed(vehicle, vehicle.targetNodeId, blocker)
    ) {
      return false;
    }
    const currentBlockerId = this.predictedFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z, ignoredVehicleIds);
    if (currentBlockerId === blockingVehicleId) {
      return true;
    }

    if (!vehicle.targetNodeId) {
      return false;
    }

    if (vehicle.currentEdgeId && vehicle.legRemainingM > 0) {
      const target = nodePosition(this.scenario, vehicle.targetNodeId);
      const dx = target.x - vehicle.x;
      const dz = target.z - vehicle.z;
      const distanceM = Math.hypot(dx, dz);
      if (distanceM <= 1e-6) {
        return false;
      }
      const lookaheadM = Math.min(vehicle.legRemainingM, Math.max(0.25, this.scenario.trafficPolicy.dynamicAvoidanceClearanceM));
      const ratio = Math.min(1, lookaheadM / distanceM);
      const nextX = round(vehicle.x + dx * ratio);
      const nextZ = round(vehicle.z + dz * ratio);
      return this.predictedSweptFootprintOverlapVehicleId(vehicle, vehicle.x, vehicle.z, nextX, nextZ, ignoredVehicleIds) === blockingVehicleId;
    }

    const target = nodePosition(this.scenario, vehicle.targetNodeId);
    return this.predictedFootprintOverlapVehicleId(vehicle, target.x, target.z, ignoredVehicleIds) === blockingVehicleId;
  }

  private tryYieldInboundQueueEntrantsBlockingLoadedExits(): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }

    const loadedExits = this.vehicles
      .filter((vehicle) => {
        if (
          !vehicle.loaded ||
          vehicle.state !== 'waiting-blocked' ||
          vehicle.blockingVehicleId === null ||
          (vehicle.waitReason !== 'min-separation' && vehicle.waitReason !== 'avoidance-clearance')
        ) {
          return false;
        }
        const entrySlot = topLiftQueueEntrySlot(vehicle.currentNodeId);
        return Boolean(entrySlot && this.liftPortKindForNodeId(entrySlot.liftNodeId) === 'inbound');
      })
      .sort((left, right) =>
        (left.waitingSinceSec ?? this.simTimeSec) - (right.waitingSinceSec ?? this.simTimeSec) ||
        left.id.localeCompare(right.id)
      );

    for (const exiting of loadedExits) {
      const entrant = this.vehicles.find((vehicle) => vehicle.id === exiting.blockingVehicleId) ?? null;
      if (entrant && this.tryYieldInboundQueueEntrantAwayFromLoadedExit(entrant, exiting)) {
        return true;
      }
    }
    return false;
  }

  private tryBreakAgentRefreshTopLiftAdjacentNodeSwap(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const swaps = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null &&
        this.topLiftAdjacentSwapNetworkNode(vehicle.currentNodeId) &&
        this.topLiftAdjacentSwapNetworkNode(vehicle.targetNodeId)
      )
      .map((vehicle) => {
        const blocker = vehicle.blockingVehicleId
          ? this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null
          : null;
        return { vehicle, blocker };
      })
      .filter((entry): entry is { vehicle: MutableVehicle; blocker: MutableVehicle } =>
        Boolean(
          entry.blocker &&
          candidateIds.has(entry.blocker.id) &&
          entry.blocker.state === 'waiting-blocked' &&
          entry.blocker.targetNodeId === entry.vehicle.currentNodeId &&
          entry.vehicle.targetNodeId === entry.blocker.currentNodeId &&
          entry.blocker.currentEdgeId === null &&
          entry.blocker.legRemainingM <= 0 &&
          this.topLiftAdjacentSwapNetworkNode(entry.blocker.currentNodeId)
        )
      )
      .sort((left, right) => left.vehicle.id.localeCompare(right.vehicle.id));

    const seenPairs = new Set<string>();
    for (const { vehicle, blocker } of swaps) {
      const pairKey = [vehicle.id, blocker.id].sort().join(':');
      if (seenPairs.has(pairKey)) {
        continue;
      }
      seenPairs.add(pairKey);
      if (this.tryInstallAgentRefreshTopLiftAdjacentNodeSwapYieldForPair(vehicle, blocker)) {
        return true;
      }
    }
    return false;
  }

  private tryInstallAgentRefreshTopLiftAdjacentNodeSwapYieldForPair(
    first: MutableVehicle,
    second: MutableVehicle
  ): MutableVehicle | null {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      first.state !== 'waiting-blocked' ||
      second.state !== 'waiting-blocked' ||
      first.currentEdgeId !== null ||
      second.currentEdgeId !== null ||
      first.legRemainingM > 0 ||
      second.legRemainingM > 0 ||
      !first.targetNodeId ||
      !second.targetNodeId ||
      first.targetNodeId !== second.currentNodeId ||
      second.targetNodeId !== first.currentNodeId ||
      !this.topLiftAdjacentSwapNetworkNode(first.currentNodeId) ||
      !this.topLiftAdjacentSwapNetworkNode(first.targetNodeId) ||
      !this.topLiftAdjacentSwapNetworkNode(second.currentNodeId) ||
      !this.topLiftAdjacentSwapNetworkNode(second.targetNodeId) ||
      !this.traffic.findEdge(first.currentNodeId, first.targetNodeId) ||
      !this.traffic.findEdge(second.currentNodeId, second.targetNodeId)
    ) {
      return null;
    }

    const loadedMiddleRetreatYielder = this.tryInstallTopLiftLoadedMiddleAdjacentFaceoffRetreat(first, second);
    if (loadedMiddleRetreatYielder) {
      return loadedMiddleRetreatYielder;
    }

    const loadedMiddleSpineRerouteYielder = this.tryInstallTopLiftLoadedMiddleSpineColumnSwapReroute(first, second);
    if (loadedMiddleSpineRerouteYielder) {
      return loadedMiddleSpineRerouteYielder;
    }

    const firstAtSpineMiddle = isTopLiftSpineLevelNodeId(first.currentNodeId, 'middle');
    const secondAtSpineMiddle = isTopLiftSpineLevelNodeId(second.currentNodeId, 'middle');
    const preferredYielder = first.loaded !== second.loaded
      ? (first.loaded ? second : first)
      : firstAtSpineMiddle && !secondAtSpineMiddle
        ? first
        : secondAtSpineMiddle && !firstAtSpineMiddle
          ? second
          : [first, second].sort((left, right) =>
              this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
              right.id.localeCompare(left.id)
            )[0]!;
    const fallbackYielder = preferredYielder.id === first.id ? second : first;

    for (const candidateYielder of [preferredYielder, fallbackYielder]) {
      const blockerNodeId = candidateYielder.id === first.id ? second.currentNodeId : first.currentNodeId;
      const routeNodeIds = this.topLiftAdjacentSwapEscapeRoute(candidateYielder, blockerNodeId);
      if (!routeNodeIds || !this.agentRefreshAdjacentSwapRouteClear(candidateYielder, routeNodeIds)) {
        continue;
      }
      this.installAgentRefreshAdjacentNodeSwapYield(candidateYielder, routeNodeIds);
      return candidateYielder;
    }
    return null;
  }

  private tryInstallTopLiftLoadedMiddleSpineColumnSwapReroute(
    first: MutableVehicle,
    second: MutableVehicle
  ): MutableVehicle | null {
    if (
      !first.loaded ||
      !second.loaded ||
      first.currentEdgeId !== null ||
      second.currentEdgeId !== null ||
      first.legRemainingM > 0 ||
      second.legRemainingM > 0
    ) {
      return null;
    }
    const firstAtSpineMiddle = isTopLiftSpineLevelNodeId(first.currentNodeId, 'middle');
    const secondAtSpineMiddle = isTopLiftSpineLevelNodeId(second.currentNodeId, 'middle');
    if (firstAtSpineMiddle === secondAtSpineMiddle) {
      return null;
    }
    const spineVehicle = firstAtSpineMiddle ? first : second;
    const columnVehicle = firstAtSpineMiddle ? second : first;
    if (
      !isTopLiftAisleLevelNodeId(columnVehicle.currentNodeId, 'middle') ||
      spineVehicle.targetNodeId !== columnVehicle.currentNodeId ||
      columnVehicle.targetNodeId !== spineVehicle.currentNodeId
    ) {
      return null;
    }
    const routeNodeIds = this.topLiftLoadedMiddleSpineColumnSwapReroute(spineVehicle, columnVehicle);
    if (routeNodeIds) {
      this.installTopLiftLoadedMiddleSpineColumnSwapReroute(spineVehicle, columnVehicle, routeNodeIds);
      return spineVehicle;
    }
    const task = this.taskForVehicle(spineVehicle);
    if (task?.kind === 'inbound' && this.tryRetargetLoadedInboundToReachableDropoff(spineVehicle, task, task.dropoffNodeId)) {
      return spineVehicle;
    }
    return null;
  }

  private topLiftLoadedMiddleSpineColumnSwapReroute(
    spineVehicle: MutableVehicle,
    columnVehicle: MutableVehicle
  ): string[] | null {
    const task = this.taskForVehicle(spineVehicle);
    if (!task || (task.kind !== 'inbound' && task.kind !== 'outbound')) {
      return null;
    }

    const protectedNodeIds = new Set<string>([
      columnVehicle.currentNodeId,
      ...(columnVehicle.targetNodeId ? [columnVehicle.targetNodeId] : []),
      ...this.vehicleRouteTail(columnVehicle, columnVehicle.routeNodeIds).slice(0, 5)
    ]);
    protectedNodeIds.delete(spineVehicle.currentNodeId);

    const candidateRoutes = this.neighbors(spineVehicle.currentNodeId)
      .filter((neighbor) =>
        neighbor.nodeId !== columnVehicle.currentNodeId &&
        this.topLiftAdjacentSwapNetworkNode(neighbor.nodeId) &&
        !protectedNodeIds.has(neighbor.nodeId) &&
        !this.currentNodeOccupancy.has(neighbor.nodeId) &&
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, spineVehicle.id) &&
        this.agentMinimalYieldFirstLegSafe(spineVehicle, spineVehicle.currentNodeId, neighbor.nodeId)
      )
      .map((neighbor) => this.topLiftLoadedMiddleSpineColumnSwapProductiveRoute(spineVehicle, task, neighbor.nodeId))
      .filter((routeNodeIds): routeNodeIds is string[] =>
        routeNodeIds !== null &&
        routeNodeIds.length > 1 &&
        this.routeHasOnlyAdjacentEdges(routeNodeIds) &&
        !this.routeHasRepeatedNode(routeNodeIds) &&
        !routeNodeIds.slice(1, Math.min(routeNodeIds.length, 6)).some((nodeId) => protectedNodeIds.has(nodeId)) &&
        this.agentRefreshLocalRouteNodesClear(spineVehicle, routeNodeIds) &&
        !this.agentRefreshMoveBlocker(spineVehicle, routeNodeIds[1]!, routeNodeIds)
      )
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      );

    return candidateRoutes[0] ?? null;
  }

  private topLiftLoadedMiddleSpineColumnSwapProductiveRoute(
    vehicle: MutableVehicle,
    task: TaskStateRecord,
    firstNodeId: string
  ): string[] | null {
    try {
      const continuationRoute = task.kind === 'inbound'
        ? this.agentRefreshLoadedInboundRouteToDropoff(firstNodeId, task)
        : this.agentRefreshLoadedOutboundRouteToDropoff(firstNodeId, task, this.taskDispatchGoalNodeId(task, vehicle));
      if (!continuationRoute || continuationRoute.length <= 1 || continuationRoute[0] !== firstNodeId) {
        return null;
      }
      return [vehicle.currentNodeId, ...continuationRoute];
    } catch {
      return null;
    }
  }

  private installTopLiftLoadedMiddleSpineColumnSwapReroute(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = 'loaded-moving';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.plannedGoalNodeId = routeNodeIds.at(-1) ?? vehicle.plannedGoalNodeId;
    vehicle.plannedRouteNodeIds = routeNodeIds;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'loaded-middle-spine-swap-reroute';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blocker.currentNodeId, routeNodeIds, 'loaded-middle-spine-swap-reroute', { countTaskReplan: false });
  }

  private tryInstallTopLiftLoadedMiddleAdjacentFaceoffRetreat(
    first: MutableVehicle,
    second: MutableVehicle
  ): MutableVehicle | null {
    if (
      !first.loaded ||
      !second.loaded ||
      !isTopLiftAisleLevelNodeId(first.currentNodeId, 'middle') ||
      !isTopLiftAisleLevelNodeId(second.currentNodeId, 'middle')
    ) {
      return null;
    }

    const firstTask = this.taskForVehicle(first);
    const secondTask = this.taskForVehicle(second);
    const preferredYielder = firstTask?.kind === 'inbound' && secondTask?.kind === 'outbound'
      ? first
      : secondTask?.kind === 'inbound' && firstTask?.kind === 'outbound'
        ? second
        : [first, second].sort((left, right) =>
            this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
            right.id.localeCompare(left.id)
          )[0]!;
    const fallbackYielder = preferredYielder.id === first.id ? second : first;

    for (const candidateYielder of [preferredYielder, fallbackYielder]) {
      const blocker = candidateYielder.id === first.id ? second : first;
      const routeNodeIds = this.topLiftLoadedMiddleAdjacentFaceoffRetreatRoute(candidateYielder, blocker);
      if (!routeNodeIds) {
        continue;
      }
      this.installTopLiftLoadedMiddleAdjacentFaceoffRetreat(candidateYielder, blocker, routeNodeIds);
      return candidateYielder;
    }
    return null;
  }

  private topLiftLoadedMiddleAdjacentFaceoffRetreatRoute(
    yielder: MutableVehicle,
    blocker: MutableVehicle
  ): string[] | null {
    const yielderColumn = this.topLiftColumnAccessColumn(yielder.currentNodeId);
    const blockerColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    if (
      yielderColumn === null ||
      blockerColumn === null ||
      Math.abs(yielderColumn - blockerColumn) !== 1
    ) {
      return null;
    }

    const yielderNode = this.layoutNode(yielder.currentNodeId);
    const blockerNode = this.layoutNode(blocker.currentNodeId);
    const direction = yielderNode && blockerNode ? Math.sign(yielderNode.x - blockerNode.x) : 0;
    if (direction !== -1 && direction !== 1 || !yielderNode || !blockerNode) {
      return null;
    }

    const blockerFutureNodeIds = new Set(blocker.routeNodeIds.slice(Math.max(0, blocker.routeIndex + 1), blocker.routeIndex + 8));
    const queue: Array<{ nodeId: string; routeNodeIds: string[] }> = [{
      nodeId: yielder.currentNodeId,
      routeNodeIds: [yielder.currentNodeId]
    }];
    const visited = new Set<string>([yielder.currentNodeId]);
    const maxRouteNodes = 7;

    while (queue.length > 0) {
      queue.sort((left, right) =>
        left.routeNodeIds.length - right.routeNodeIds.length ||
        left.routeNodeIds.join('>').localeCompare(right.routeNodeIds.join('>'))
      );
      const current = queue.shift()!;
      const currentNode = this.layoutNode(current.nodeId);
      if (!currentNode) {
        continue;
      }

      if (
        current.routeNodeIds.length >= 3 &&
        current.nodeId !== yielder.currentNodeId &&
        !blockerFutureNodeIds.has(current.nodeId) &&
        Math.sign(currentNode.x - blockerNode.x) === direction &&
        Math.abs(currentNode.x - blockerNode.x) > Math.abs(yielderNode.x - blockerNode.x) + 0.1 &&
        this.topLiftLoadedMiddleFaceoffRetreatRouteClear(yielder, blocker, current.routeNodeIds)
      ) {
        return current.routeNodeIds;
      }

      if (current.routeNodeIds.length >= maxRouteNodes) {
        continue;
      }

      const neighbors = this.neighbors(current.nodeId)
        .filter((neighbor) =>
          neighbor.nodeId !== blocker.currentNodeId &&
          neighbor.nodeId !== blocker.targetNodeId &&
          !current.routeNodeIds.includes(neighbor.nodeId) &&
          this.layoutNode(neighbor.nodeId) &&
          isTopLiftAisleLevelNodeId(neighbor.nodeId, 'middle') &&
          this.topLiftColumnSpineOrAccessNode(neighbor.nodeId)
        )
        .sort((left, right) => {
          const leftNode = this.layoutNode(left.nodeId)!;
          const rightNode = this.layoutNode(right.nodeId)!;
          return (
            Math.abs(rightNode.x - blockerNode.x) - Math.abs(leftNode.x - blockerNode.x) ||
            left.nodeId.localeCompare(right.nodeId)
          );
        });

      for (const neighbor of neighbors) {
        const routeNodeIds = [...current.routeNodeIds, neighbor.nodeId];
        if (
          visited.has(neighbor.nodeId) ||
          !this.routeEdgesExist(routeNodeIds) ||
          !this.topLiftLoadedMiddleFaceoffRetreatRouteClear(yielder, blocker, routeNodeIds) ||
          this.agentRefreshMoveBlocker(yielder, routeNodeIds[1]!, routeNodeIds) ||
          this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(yielder, routeNodeIds)
      ) {
          continue;
        }
        visited.add(neighbor.nodeId);
        queue.push({ nodeId: neighbor.nodeId, routeNodeIds });
      }
    }
    return null;
  }

  private topLiftLoadedMiddleFaceoffRetreatRouteClear(
    yielder: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): boolean {
    if (!this.agentMinimalYieldFirstLegSafe(yielder, routeNodeIds[0]!, routeNodeIds[1]!)) {
      return false;
    }
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const nodeId = routeNodeIds[index]!;
      if (nodeId === blocker.currentNodeId || nodeId === blocker.targetNodeId) {
        return false;
      }
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== yielder.id) {
        return false;
      }
      const claimantId = this.nodeClaimedByOtherVehicle(nodeId, yielder.id);
      if (claimantId && claimantId !== blocker.id) {
        return false;
      }
      if (index === routeNodeIds.length - 1 && claimantId === blocker.id) {
        return false;
      }
      if (
        this.movingVehicleTargetingNode(nodeId, yielder.id) ||
        this.movingVehicleClearingNode(nodeId, yielder)
      ) {
        return false;
      }
    }
    return true;
  }

  private installTopLiftLoadedMiddleAdjacentFaceoffRetreat(
    yielder: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    yielder.routeNodeIds = routeNodeIds;
    yielder.routeIndex = 0;
    yielder.targetNodeId = routeNodeIds[1] ?? null;
    yielder.state = 'loaded-moving';
    yielder.waitReason = null;
    yielder.blockingReservationId = null;
    yielder.blockingVehicleId = null;
    yielder.waitingSinceSec = null;
    yielder.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(yielder, routeNodeIds) + 2);
    yielder.yieldHoldNodeId = routeNodeIds.at(-1) ?? null;
    yielder.localRouteNodeIds = routeNodeIds;
    yielder.localRouteReason = 'loaded-middle-faceoff-retreat';
    this.logAgentReroute(yielder, this.taskForVehicle(yielder), blocker.currentNodeId, routeNodeIds, 'agent-refresh-loaded-middle-faceoff-retreat', { countTaskReplan: false });
  }

  private topLiftAdjacentSwapEscapeRoute(vehicle: MutableVehicle, blockedNodeId: string): string[] | null {
    const routes = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedNodeId)
      .filter((neighbor) => this.topLiftAdjacentSwapEscapeAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) =>
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id) ||
        this.topLiftAdjacentSwapNetworkNode(neighbor.nodeId)
      )
      .map((neighbor) => this.topLiftAdjacentSwapEscapeRouteFromFirstStep(vehicle, blockedNodeId, neighbor.nodeId))
      .filter((route): route is string[] => route !== null)
      .filter((route) => this.agentRefreshAdjacentSwapRouteClear(vehicle, route))
      .sort((left, right) =>
        this.topLiftAdjacentSwapEscapeRouteRank(vehicle, left) - this.topLiftAdjacentSwapEscapeRouteRank(vehicle, right) ||
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      );
    return routes[0] ?? null;
  }

  private topLiftAdjacentSwapEscapeRouteFromFirstStep(
    vehicle: MutableVehicle,
    blockedNodeId: string,
    firstNodeId: string
  ): string[] | null {
    const directRoute = [vehicle.currentNodeId, firstNodeId];
    if (this.topLiftLoadedAdjacentSwapSideHoldAllowed(vehicle, firstNodeId)) {
      return directRoute;
    }
    if (this.topLiftAdjacentSwapHoldNodeAllowed(vehicle, firstNodeId)) {
      return directRoute;
    }
    if (this.topLiftAdjacentSwapTemporaryStorageHoldAllowed(vehicle, firstNodeId)) {
      return directRoute;
    }
    const storageEscapeRoute = this.topLiftAdjacentSwapStorageEscapeRoute(vehicle, blockedNodeId, firstNodeId);
    if (storageEscapeRoute) {
      return storageEscapeRoute;
    }
    if (this.topLiftAdjacentSwapTemporaryNoStopHoldAllowed(vehicle, directRoute)) {
      return directRoute;
    }
    if (!this.topLiftAdjacentSwapNetworkNode(firstNodeId)) {
      return null;
    }

    const task = this.taskForVehicle(vehicle);
    const queue: Array<{ nodeId: string; routeNodeIds: string[]; distanceM: number }> = [{
      nodeId: firstNodeId,
      routeNodeIds: directRoute,
      distanceM: this.routeDistanceM(directRoute)
    }];
    const bestDistanceByNode = new Map<string, number>([[vehicle.currentNodeId, 0], [firstNodeId, queue[0]!.distanceM]]);
    const maxRouteNodes = 18;

    while (queue.length > 0) {
      queue.sort((left, right) =>
        left.distanceM - right.distanceM ||
        left.routeNodeIds.join('>').localeCompare(right.routeNodeIds.join('>'))
      );
      const current = queue.shift()!;
      if (
        current.nodeId !== firstNodeId &&
        !this.mustClearNoStopNode(vehicle, task, current.nodeId) &&
        (
          this.topLiftAdjacentSwapHoldNodeAllowed(vehicle, current.nodeId) ||
          this.topLiftAdjacentSwapStorageContinuationHoldAllowed(vehicle, current.routeNodeIds)
        )
      ) {
        return current.routeNodeIds;
      }
      if (current.routeNodeIds.length >= maxRouteNodes) {
        continue;
      }

      for (const neighbor of this.neighbors(current.nodeId)) {
        const claimedByOtherId = this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id);
        if (
          neighbor.nodeId === vehicle.currentNodeId ||
          neighbor.nodeId === blockedNodeId ||
          current.routeNodeIds.includes(neighbor.nodeId) ||
          (
            !this.topLiftAdjacentSwapClearThroughStepAllowed(vehicle, neighbor.nodeId) &&
            !this.topLiftAdjacentSwapStorageContinuationStepAllowed(vehicle, current.nodeId, neighbor.nodeId)
          ) ||
          this.topLiftDoubleLaneDirectionAllowed(current.nodeId, neighbor.nodeId) === false ||
          this.currentNodeOccupancy.has(neighbor.nodeId) ||
          (claimedByOtherId && !this.topLiftAdjacentSwapNetworkNode(neighbor.nodeId))
        ) {
          continue;
        }
        const routeNodeIds = [...current.routeNodeIds, neighbor.nodeId];
        const distanceM = current.distanceM + neighbor.lengthM;
        if (distanceM >= (bestDistanceByNode.get(neighbor.nodeId) ?? Infinity) - 1e-9) {
          continue;
        }
        bestDistanceByNode.set(neighbor.nodeId, distanceM);
        queue.push({ nodeId: neighbor.nodeId, routeNodeIds, distanceM });
      }
    }
    return null;
  }

  private agentRefreshAdjacentSwapRouteClear(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const nodeId = routeNodeIds[index]!;
      const occupantId = this.currentNodeOccupancy.get(nodeId);
      if (occupantId && occupantId !== vehicle.id) {
        return false;
      }
      const clearThroughNode = index < routeNodeIds.length - 1 && this.topLiftAdjacentSwapNetworkNode(nodeId);
      if (
        !clearThroughNode &&
        this.nodeClaimedByOtherVehicle(nodeId, vehicle.id) &&
        !this.topLiftLoadedAdjacentSwapSideHoldAllowed(vehicle, nodeId)
      ) {
        return false;
      }
      if (this.isStorageNode(nodeId) && this.storedLoadIdAtNode(nodeId)) {
        return false;
      }
      if (nodeId !== routeNodeIds.at(-1) && this.storedLoadIdAtNode(nodeId)) {
        return false;
      }
    }
    return true;
  }

  private topLiftAdjacentSwapStorageContinuationHoldAllowed(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    const storageNodeId = routeNodeIds.at(-1);
    const pocketNodeId = routeNodeIds.at(-2);
    return Boolean(
      storageNodeId &&
      pocketNodeId &&
      (
        this.topLiftMiddleAisleTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, pocketNodeId, storageNodeId) ||
        this.topLiftColumnAccessTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, pocketNodeId, storageNodeId)
      )
    );
  }

  private topLiftAdjacentSwapStorageContinuationStepAllowed(
    vehicle: MutableVehicle,
    pocketNodeId: string,
    storageNodeId: string
  ): boolean {
    return this.topLiftMiddleAisleTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, pocketNodeId, storageNodeId) ||
      this.topLiftColumnAccessTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, pocketNodeId, storageNodeId);
  }

  private topLiftAdjacentSwapTemporaryNoStopHoldAllowed(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    if (
      routeNodeIds.length !== 2 ||
      vehicle.loaded ||
      !this.topLiftColumnLayoutEnabled() ||
      !isTopLiftColumnAccessNodeId(vehicle.currentNodeId)
    ) {
      return false;
    }
    const terminalNodeId = routeNodeIds[1]!;
    const terminalNode = this.layoutNode(terminalNodeId);
    if (!terminalNode?.noStop || !isTopLiftColumnAccessNodeId(terminalNodeId)) {
      return false;
    }
    const currentColumn = this.topLiftColumnAccessColumn(vehicle.currentNodeId);
    const terminalColumn = this.topLiftColumnAccessColumn(terminalNodeId);
    const currentLevel = topLiftAisleLevel(vehicle.currentNodeId);
    const terminalLevel = topLiftAisleLevel(terminalNodeId);
    return currentColumn !== null &&
      currentColumn === terminalColumn &&
      ((currentLevel === 'top-a' && terminalLevel === 'top-b') ||
        (currentLevel === 'top-b' && terminalLevel === 'top-a') ||
        (currentLevel === 'bottom-a' && terminalLevel === 'bottom-b') ||
        (currentLevel === 'bottom-b' && terminalLevel === 'bottom-a'));
  }

  private topLiftLoadedAdjacentSwapSideHoldAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !vehicle.loaded ||
      this.topLiftColumnAccessColumn(vehicle.currentNodeId) !== this.topLiftColumnAccessColumn(nodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, nodeId)
    ) {
      return false;
    }
    const currentLevel = topLiftAisleLevel(vehicle.currentNodeId);
    const holdLevel = topLiftAisleLevel(nodeId);
    const loadedSideHold =
      (currentLevel === 'bottom-a' && holdLevel === 'bottom-b') ||
      (currentLevel === 'top-b' && holdLevel === 'top-a');
    if (!loadedSideHold) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    const claimantId = this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
    const claimant = claimantId
      ? this.vehicles.find((candidate) => candidate.id === claimantId) ?? null
      : null;
    return !claimant || this.vehicleCurrentlyWaitsFor(claimant, vehicle.id);
  }

  private topLiftAdjacentSwapTemporaryStorageHoldAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      !this.topLiftColumnSpineOrAccessNode(vehicle.currentNodeId) ||
      !this.isStorageNode(nodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, nodeId) ||
      this.storedLoadIdAtNode(nodeId) ||
      !this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId)
    ) {
      return false;
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    return !this.nodeClaimedByOtherVehicle(nodeId, vehicle.id);
  }

  private topLiftAdjacentSwapStorageEscapeRoute(
    vehicle: MutableVehicle,
    blockedNodeId: string,
    firstNodeId: string
  ): string[] | null {
    if (
      vehicle.loaded ||
      !this.topLiftAdjacentSwapNetworkNode(vehicle.currentNodeId) ||
      !this.topLiftAdjacentSwapNetworkNode(firstNodeId)
    ) {
      return null;
    }
    return this.neighbors(firstNodeId)
      .filter((neighbor) =>
        neighbor.nodeId !== vehicle.currentNodeId &&
        neighbor.nodeId !== blockedNodeId &&
        this.isStorageNode(neighbor.nodeId) &&
        (
          this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId) ||
          this.topLiftMiddleAisleTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, firstNodeId, neighbor.nodeId) ||
          this.topLiftColumnAccessTemporaryStorageYieldContinuationAllowed(vehicle, vehicle.currentNodeId, firstNodeId, neighbor.nodeId)
        ) &&
        !this.currentNodeOccupancy.has(neighbor.nodeId) &&
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, vehicle.id)
      )
      .map((neighbor) => [vehicle.currentNodeId, firstNodeId, neighbor.nodeId])
      .filter((route) => this.agentRefreshLocalRouteNodesClear(vehicle, route))
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      )[0] ?? null;
  }

  private topLiftAdjacentSwapHoldNodeAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    const task = this.taskForVehicle(vehicle);
    if (this.mustClearNoStopNode(vehicle, task, nodeId)) {
      return false;
    }
    return this.agentRefreshYieldPocketAllowed(vehicle, nodeId) &&
      this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, nodeId);
  }

  private topLiftAdjacentSwapClearThroughStepAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (this.topLiftAdjacentSwapNetworkNode(nodeId)) {
      return true;
    }
    return this.topLiftAdjacentSwapHoldNodeAllowed(vehicle, nodeId);
  }

  private topLiftAdjacentSwapEscapeRouteRank(vehicle: MutableVehicle, routeNodeIds: string[]): number {
    const firstStepNodeId = routeNodeIds[1] ?? routeNodeIds[0] ?? '';
    const holdNodeId = routeNodeIds.at(-1) ?? firstStepNodeId;
    const task = this.taskForVehicle(vehicle);
    const clearThroughPenalty = this.mustClearNoStopNode(vehicle, task, firstStepNodeId) ? 10 : 0;
    const parkingPenalty = this.layoutNode(holdNodeId)?.type === 'parking' ? 4 : 0;
    return clearThroughPenalty + parkingPenalty + this.topLiftAdjacentSwapEscapeRank(firstStepNodeId);
  }

  private topLiftAdjacentSwapEscapeAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (this.topLiftAdjacentSwapNetworkNode(nodeId)) {
      return true;
    }
    return this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      isTopLiftColumnAccessNodeId(vehicle.currentNodeId) &&
      this.isStorageNode(nodeId) &&
      this.traffic.findEdge(vehicle.currentNodeId, nodeId) !== null &&
      this.topLiftTemporaryYieldStorageHoldAllowed(vehicle, nodeId);
  }

  private topLiftAdjacentSwapEscapeRank(nodeId: string): number {
    if (this.isStorageNode(nodeId)) {
      return 0;
    }
    if (isTopLiftAisleLevelNodeId(nodeId, 'top-b') || isTopLiftAisleLevelNodeId(nodeId, 'bottom-a')) {
      return 1;
    }
    if (isTopLiftAisleLevelNodeId(nodeId, 'top-a') || isTopLiftAisleLevelNodeId(nodeId, 'bottom-b')) {
      return 2;
    }
    if (isTopLiftAisleLevelNodeId(nodeId, 'middle')) {
      return 3;
    }
    return 4;
  }

  private installAgentRefreshAdjacentNodeSwapYield(vehicle: MutableVehicle, routeNodeIds: string[]): void {
    const holdNodeId = routeNodeIds.at(-1) ?? vehicle.currentNodeId;
    const temporaryNoStopHold = this.topLiftAdjacentSwapTemporaryNoStopHoldAllowed(vehicle, routeNodeIds);
    const loadedSideHold = this.topLiftLoadedAdjacentSwapSideHoldAllowed(vehicle, holdNodeId);
    if (!temporaryNoStopHold && !loadedSideHold && this.mustClearNoStopNode(vehicle, this.taskForVehicle(vehicle), holdNodeId)) {
      return;
    }
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, routeNodeIds) + 2);
    vehicle.yieldHoldNodeId = routeNodeIds.at(-1) ?? null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), routeNodeIds.at(-1) ?? vehicle.currentNodeId, routeNodeIds, 'agent-refresh-top-lift-adjacent-swap-yield', { countTaskReplan: false });
  }

  private tryBreakAgentRefreshTopLiftQueueAccessParkingSwap(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const accessVehicles = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null
      )
      .map((vehicle) => ({
        vehicle,
        accessSlot: topLiftQueueAisleAccess(vehicle.currentNodeId),
        targetSlot: topLiftQueueParkingSlot(vehicle.targetNodeId!)
      }))
      .filter((entry): entry is { vehicle: MutableVehicle; accessSlot: { liftNodeId: string; slotIndex: number }; targetSlot: { liftNodeId: string; slotIndex: number } } =>
        Boolean(
          entry.accessSlot &&
          entry.targetSlot &&
          entry.accessSlot.slotIndex > 0 &&
          entry.accessSlot.liftNodeId === entry.targetSlot.liftNodeId &&
          entry.accessSlot.slotIndex === entry.targetSlot.slotIndex
        )
      )
      .sort((left, right) => left.vehicle.id.localeCompare(right.vehicle.id));

    for (const { vehicle, accessSlot } of accessVehicles) {
      const blocker = vehicle.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null
        : null;
      const blockerSlot = blocker ? topLiftQueueParkingSlot(blocker.currentNodeId) : null;
      const blockerTargetAccess = blocker?.targetNodeId ? topLiftQueueAisleAccess(blocker.targetNodeId) : null;
      if (
        !blocker ||
        !candidateIds.has(blocker.id) ||
        !blockerSlot ||
        !blockerTargetAccess ||
        blockerSlot.liftNodeId !== accessSlot.liftNodeId ||
        blockerSlot.slotIndex !== accessSlot.slotIndex ||
        blockerTargetAccess.liftNodeId !== accessSlot.liftNodeId ||
        blockerTargetAccess.slotIndex !== accessSlot.slotIndex
      ) {
        continue;
      }

      const candidateSlots = [accessSlot.slotIndex - 1, accessSlot.slotIndex + 1, accessSlot.slotIndex - 2, accessSlot.slotIndex + 2]
        .filter((slotIndex, index, slots) => slotIndex >= 1 && slotIndex <= 3 && slots.indexOf(slotIndex) === index);
      for (const slotIndex of candidateSlots) {
        const parkingNodeId = liftQueueNodeId(accessSlot.liftNodeId, slotIndex);
        const accessNodeId = liftQueueTailAccessNodeId(accessSlot.liftNodeId, slotIndex);
        if (!this.layoutNode(parkingNodeId) || !this.layoutNode(accessNodeId)) {
          continue;
        }
        if (this.currentNodeOccupancy.has(parkingNodeId) || this.nodeClaimedByOtherVehicle(parkingNodeId, vehicle.id)) {
          continue;
        }
        const routeNodeIds = [vehicle.currentNodeId];
        const direction = Math.sign(slotIndex - accessSlot.slotIndex);
        for (let cursor = accessSlot.slotIndex + direction; direction !== 0 && (direction > 0 ? cursor <= slotIndex : cursor >= slotIndex); cursor += direction) {
          routeNodeIds.push(liftQueueTailAccessNodeId(accessSlot.liftNodeId, cursor));
        }
        routeNodeIds.push(parkingNodeId);
        if (!this.routeHasOnlyAdjacentEdges(routeNodeIds) || !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
          continue;
        }
        this.installAgentRefreshTopLiftQueueSwapYield(vehicle, routeNodeIds);
        return true;
      }
    }
    return false;
  }

  private installAgentRefreshTopLiftQueueSwapYield(vehicle: MutableVehicle, routeNodeIds: string[]): void {
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, routeNodeIds) + 2);
    vehicle.yieldHoldNodeId = routeNodeIds[routeNodeIds.length - 1] ?? null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'top-lift-queue-swap-yield';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), routeNodeIds.at(-1) ?? vehicle.currentNodeId, routeNodeIds, 'agent-refresh-top-lift-queue-swap-yield', { countTaskReplan: false });
  }

  private tryBreakAgentRefreshTopLiftSpineCycle(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const loadedTopBEntrant = this.vehicles.find((vehicle) =>
      candidateIds.has(vehicle.id) &&
      vehicle.loaded &&
      vehicle.state === 'waiting-blocked' &&
      (
        vehicle.waitReason === 'top-lift-spine-opposing-claim' ||
        vehicle.waitReason === 'node-occupied' ||
        vehicle.waitReason === 'no-stop-continuation-blocked'
      ) &&
      vehicle.currentEdgeId === null &&
      isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'top-b') &&
      isTopLiftSpineLevelNodeId(vehicle.targetNodeId ?? '', 'top-b')
    );
    if (loadedTopBEntrant?.targetNodeId) {
      const middleNodeId = this.topLiftSpineSiblingNodeId(loadedTopBEntrant.targetNodeId, 'middle');
      const blocker = this.vehicles.find((vehicle) =>
        middleNodeId !== null &&
        candidateIds.has(vehicle.id) &&
        !vehicle.loaded &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.currentNodeId === middleNodeId &&
        vehicle.targetNodeId === loadedTopBEntrant.targetNodeId
      );
      if (blocker && this.tryMoveAgentRefreshTopLiftLoadedTopBAisleAside(loadedTopBEntrant, loadedTopBEntrant.targetNodeId)) {
        return true;
      }
    }

    const loadedBottomAEntrant = this.vehicles.find((vehicle) =>
      candidateIds.has(vehicle.id) &&
      vehicle.loaded &&
      vehicle.state === 'waiting-blocked' &&
      (
        vehicle.waitReason === 'middle-aisle-opposing-claim' ||
        vehicle.waitReason === 'top-lift-spine-opposing-claim' ||
        vehicle.waitReason === 'node-occupied' ||
        vehicle.waitReason === 'no-stop-continuation-blocked'
      ) &&
      vehicle.currentEdgeId === null &&
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') &&
      isTopLiftSpineLevelNodeId(vehicle.targetNodeId ?? '', 'middle')
    );
    if (
      loadedBottomAEntrant?.targetNodeId &&
      this.tryMoveAgentRefreshTopLiftLoadedBottomAAside(
        loadedBottomAEntrant,
        loadedBottomAEntrant.currentNodeId,
        loadedBottomAEntrant.targetNodeId
      )
    ) {
      return true;
    }

    const loadedDown = this.vehicles.find((vehicle) =>
      candidateIds.has(vehicle.id) &&
      vehicle.loaded &&
      vehicle.state === 'waiting-blocked' &&
      (
        vehicle.waitReason === 'edge-head-on' ||
        vehicle.waitReason === 'middle-aisle-opposing-claim' ||
        vehicle.waitReason === 'top-lift-spine-opposing-claim' ||
        vehicle.waitReason === 'no-stop-continuation-blocked'
      ) &&
      vehicle.currentEdgeId === null &&
      isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-b') &&
      isTopLiftSpineLevelNodeId(vehicle.targetNodeId ?? '', 'middle')
    );
    if (!loadedDown || !loadedDown.targetNodeId) {
      return false;
    }
    const topBNodeId = loadedDown.currentNodeId;
    const middleNodeId = loadedDown.targetNodeId;
    if (this.tryMoveAgentRefreshTopLiftLoadedDownAside(loadedDown, topBNodeId, middleNodeId)) {
      return true;
    }
    const emptyCandidates = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        !vehicle.loaded &&
        vehicle.state === 'waiting-blocked' &&
        (vehicle.waitReason === 'min-separation' || vehicle.waitReason === 'avoidance-clearance') &&
        vehicle.currentNodeId === middleNodeId &&
        vehicle.targetNodeId === topBNodeId
      )
      .sort((left, right) =>
        Number(Boolean(left.taskId)) - Number(Boolean(right.taskId)) ||
        (left.waitingSinceSec ?? this.simTimeSec) - (right.waitingSinceSec ?? this.simTimeSec) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of emptyCandidates) {
      if (this.agentRefreshTemporaryYieldShouldContinue(vehicle, topBNodeId)) {
        return true;
      }
      const continuationNodeId = this.agentRefreshTopLiftSpineEscapeNodeId(vehicle, middleNodeId, topBNodeId);
      if (!continuationNodeId) {
        continue;
      }
      if (vehicle.currentEdgeId !== null) {
        const edge = this.traffic.findEdge(middleNodeId, topBNodeId);
        if (!edge) {
          continue;
        }
        this.startAgentMinimalReverseLeg(
          vehicle,
          edge,
          topBNodeId,
          middleNodeId,
          [topBNodeId, middleNodeId, continuationNodeId],
          'agent-refresh-top-lift-spine-cycle-yield'
        );
        return true;
      }
      const routeNodeIds = [middleNodeId, continuationNodeId];
      if (!this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
        continue;
      }
      if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
        return true;
      }
      return this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds);
    }
    return false;
  }

  private tryBreakAgentRefreshTopLiftServiceClearanceCycle(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const waitingVehicles = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.blockingVehicleId !== null
      )
      .sort((left, right) =>
        Number(left.loaded) - Number(right.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of waitingVehicles) {
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (!blocker || !candidateIds.has(blocker.id) || blocker.state !== 'waiting-blocked') {
        continue;
      }
      if (this.tryYieldAisleAwayFromTopLiftServiceClearance(vehicle, blocker, vehicle.targetNodeId ?? vehicle.currentNodeId)) {
        return true;
      }
      if (this.tryYieldAisleAwayFromTopLiftServiceClearance(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId)) {
        return true;
      }
      if (this.topLiftServiceClearanceYieldPocketPending(vehicle, blocker, vehicle.targetNodeId ?? vehicle.currentNodeId, candidateIds)) {
        return true;
      }
      if (this.topLiftServiceClearanceYieldPocketPending(blocker, vehicle, blocker.targetNodeId ?? blocker.currentNodeId, candidateIds)) {
        return true;
      }
      if (this.tryYieldStorageAwayFromLoadedInboundDropoffRoute(vehicle, blocker)) {
        return true;
      }
      if (this.tryYieldStorageAwayFromLoadedInboundDropoffRoute(blocker, vehicle)) {
        return true;
      }
      if (this.tryYieldStorageAwayFromTopLiftServiceClearance(vehicle, blocker)) {
        return true;
      }
      if (this.tryYieldStorageAwayFromTopLiftServiceClearance(blocker, vehicle)) {
        return true;
      }
    }
    return false;
  }

  private topLiftServiceClearanceYieldPocketPending(
    aisleVehicle: MutableVehicle,
    serviceVehicle: MutableVehicle,
    blockedTargetNodeId: string,
    deadlockCandidateIds: Set<string>
  ): boolean {
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(serviceVehicle);
    if (
      !clearanceSegment ||
      topLiftAisleLevel(aisleVehicle.currentNodeId) !== 'top-b' ||
      aisleVehicle.currentEdgeId !== null ||
      aisleVehicle.legRemainingM > 0 ||
      aisleVehicle.phaseRemainingSec > 0
    ) {
      return false;
    }

    const column = this.topLiftColumnAccessColumn(aisleVehicle.currentNodeId);
    if (column === null) {
      return false;
    }
    const candidateNodeIds = aisleVehicle.loaded
      ? [columnAccessNodeId('top-a', column - 1)]
      : [
          columnAccessNodeId('top-a', column - 1),
          `storage-r01-c${String(column).padStart(2, '0')}`
        ];

    return candidateNodeIds.some((nodeId) => {
      if (nodeId === aisleVehicle.currentNodeId || nodeId === blockedTargetNodeId) {
        return false;
      }
      if (!this.neighbors(aisleVehicle.currentNodeId).some((neighbor) => neighbor.nodeId === nodeId)) {
        return false;
      }
      const occupiedOrClaimedBlockerId =
        this.currentNodeOccupancy.get(nodeId) ??
        this.nodeClaimedByOtherVehicle(nodeId, aisleVehicle.id);
      if (
        (!this.agentRefreshYieldPocketAllowed(aisleVehicle, nodeId) && !occupiedOrClaimedBlockerId) ||
        !this.agentRefreshYieldPocketCompatibleWithRequester(aisleVehicle, nodeId, serviceVehicle) ||
        !this.agentRefreshYieldPocketKeepsGoalReachable(aisleVehicle, nodeId) ||
        !this.agentRefreshYieldPocketCanReturn(aisleVehicle, nodeId, blockedTargetNodeId)
      ) {
        return false;
      }
      const block = this.agentRefreshMoveBlocker(aisleVehicle, nodeId, [aisleVehicle.currentNodeId, nodeId]);
      const blockerId =
        block?.blockingVehicleId ??
        occupiedOrClaimedBlockerId ??
        this.movingVehicleTargetingNode(nodeId, aisleVehicle.id);
      if (!blockerId || deadlockCandidateIds.has(blockerId)) {
        return false;
      }
      const blocker = this.vehicles.find((vehicle) => vehicle.id === blockerId) ?? null;
      return Boolean(
        blocker &&
        (
          blocker.state !== 'waiting-blocked' ||
          blocker.currentEdgeId !== null ||
          blocker.speedMps > 0.02
        )
      );
    });
  }

  private topLiftSpineSiblingNodeId(nodeId: string, level: TopLiftAisleLevel): string | null {
    const spineKey = topLiftSpineKey(nodeId);
    return spineKey ? `${spineKey}-spine-${level}` : null;
  }

  private tryMoveAgentRefreshTopLiftLoadedTopBAisleAside(
    vehicle: MutableVehicle,
    blockedNodeId: string
  ): boolean {
    const escapeNodeId = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedNodeId)
      .filter((neighbor) => this.topLiftColumnSpineOrAccessNode(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .sort((left, right) =>
        this.agentRefreshTopLiftLoadedTopBAisleEscapeRank(left.nodeId) - this.agentRefreshTopLiftLoadedTopBAisleEscapeRank(right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0]?.nodeId ?? null;
    if (!escapeNodeId) {
      return false;
    }
    const routeNodeIds = [vehicle.currentNodeId, escapeNodeId];
    if (!this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
      return false;
    }
    return this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds);
  }

  private agentRefreshTopLiftLoadedTopBAisleEscapeRank(nodeId: string): number {
    if (/^column-top-a-c\d+$/.test(nodeId)) {
      return 0;
    }
    if (isTopLiftSpineLevelNodeId(nodeId, 'top-a')) {
      return 1;
    }
    if (isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
      return 2;
    }
    return 3;
  }

  private tryMoveAgentRefreshTopLiftTopBEntrantAside(
    vehicle: MutableVehicle,
    middleNodeId: string
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      !isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-b') ||
      !isTopLiftSpineLevelNodeId(middleNodeId, 'middle')
    ) {
      return false;
    }
    const topANodeId = this.topLiftSpineSiblingNodeId(vehicle.currentNodeId, 'top-a');
    if (!topANodeId || !this.layoutNode(topANodeId)) {
      return false;
    }
    const routeNodeIds = [vehicle.currentNodeId, topANodeId];
    if (
      !this.routeEdgesExist(routeNodeIds) ||
      !this.agentRefreshYieldPocketAllowed(vehicle, topANodeId) ||
      !this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, topANodeId) ||
      !this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, topANodeId) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
      this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, routeNodeIds)
    ) {
      return false;
    }
    if (!this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds)) {
      return false;
    }
    return vehicle.targetNodeId !== middleNodeId;
  }

  private tryMoveAgentRefreshTopLiftLoadedBottomAAside(
    vehicle: MutableVehicle,
    bottomANodeId: string,
    middleNodeId: string
  ): boolean {
    const bottomBNodeId = this.topLiftSpineSiblingNodeId(bottomANodeId, 'bottom-b');
    if (!bottomBNodeId || !this.layoutNode(bottomBNodeId)) {
      return false;
    }
    const routeNodeIds = [bottomANodeId, bottomBNodeId];
    if (
      !this.routeEdgesExist(routeNodeIds) ||
      !this.agentRefreshYieldPocketAllowed(vehicle, bottomBNodeId) ||
      !this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, bottomBNodeId) ||
      !this.agentMinimalYieldFirstLegSafe(vehicle, bottomANodeId, bottomBNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
      this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, routeNodeIds)
    ) {
      return false;
    }
    if (!this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds)) {
      return false;
    }
    return vehicle.targetNodeId !== middleNodeId;
  }

  private tryMoveAgentRefreshTopLiftLoadedDownAside(
    vehicle: MutableVehicle,
    topBNodeId: string,
    middleNodeId: string
  ): boolean {
    const escapeNodeId = this.neighbors(topBNodeId)
      .filter((neighbor) => neighbor.nodeId !== middleNodeId)
      .filter((neighbor) => this.topLiftColumnSpineOrAccessNode(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, topBNodeId, neighbor.nodeId))
      .sort((left, right) =>
        this.agentRefreshTopLiftLoadedDownEscapeRank(left.nodeId) - this.agentRefreshTopLiftLoadedDownEscapeRank(right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0]?.nodeId ?? null;
    if (!escapeNodeId) {
      return false;
    }
    const routeNodeIds = [topBNodeId, escapeNodeId];
    if (!this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
      return false;
    }
    return this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds);
  }

  private agentRefreshTopLiftLoadedDownEscapeRank(nodeId: string): number {
    if (isTopLiftAisleLevelNodeId(nodeId, 'top-b')) {
      return 0;
    }
    if (isTopLiftSpineLevelNodeId(nodeId, 'top-a')) {
      return 1;
    }
    if (isTopLiftAisleLevelNodeId(nodeId, 'top-a')) {
      return 2;
    }
    return 3;
  }

  private agentRefreshTopLiftSpineEscapeNodeId(
    vehicle: MutableVehicle,
    middleNodeId: string,
    blockedTopBNodeId: string
  ): string | null {
    return this.neighbors(middleNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedTopBNodeId)
      .filter((neighbor) => this.topLiftColumnSpineOrAccessNode(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, middleNodeId, neighbor.nodeId))
      .sort((left, right) =>
        this.agentRefreshTopLiftSpineEscapeRank(left.nodeId) - this.agentRefreshTopLiftSpineEscapeRank(right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0]?.nodeId ?? null;
  }

  private tryExtendAgentRefreshNoStopContinuation(vehicle: MutableVehicle, middleNodeId: string): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      !isTopLiftSpineLevelNodeId(middleNodeId, 'middle') ||
      !isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'top-b')
    ) {
      return false;
    }
    const continuationNodeId = this.agentRefreshTopLiftSpineEscapeNodeId(vehicle, middleNodeId, vehicle.currentNodeId);
    if (!continuationNodeId) {
      return false;
    }
    const continuationOccupantId = this.currentNodeOccupancy.get(continuationNodeId);
    if (
      (continuationOccupantId && continuationOccupantId !== vehicle.id) ||
      this.nodeClaimedByOtherVehicle(continuationNodeId, vehicle.id)
    ) {
      return false;
    }
    const routeNodeIds = [vehicle.currentNodeId, middleNodeId, continuationNodeId];
    if (!this.routeEdgesExist(routeNodeIds) || !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
      return false;
    }
    return this.installAgentRefreshTopLiftSpineCycleYield(vehicle, routeNodeIds);
  }

  private agentRefreshTopLiftSpineEscapeRank(nodeId: string): number {
    if (/^column-middle-c\d+$/.test(nodeId)) {
      return 0;
    }
    if (isTopLiftSpineLevelNodeId(nodeId, 'bottom-a')) {
      return 1;
    }
    if (isTopLiftSpineLevelNodeId(nodeId, 'top-a')) {
      return 2;
    }
    return 3;
  }

  private installAgentRefreshTopLiftSpineCycleYield(
    vehicle: MutableVehicle,
    routeNodeIds: string[],
    forbiddenNodeIds = new Set<string>()
  ): boolean {
    const holdRouteNodeIds = this.extendTopLiftTemporaryYieldRouteToHold(vehicle, routeNodeIds, forbiddenNodeIds) ??
      (vehicle.loaded && routeNodeIds.length === 2 && this.topLiftColumnSpineOrAccessNode(routeNodeIds[1]!)
        ? routeNodeIds
        : null);
    if (!holdRouteNodeIds) {
      return false;
    }
    if (this.topLiftNoStopContinuationRouteEndsOnForbiddenHold(vehicle, holdRouteNodeIds)) {
      return false;
    }
    if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, holdRouteNodeIds)) {
      return true;
    }
    vehicle.routeNodeIds = holdRouteNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = holdRouteNodeIds[1] ?? null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, holdRouteNodeIds) + 2);
    vehicle.yieldHoldNodeId = holdRouteNodeIds[holdRouteNodeIds.length - 1] ?? null;
    vehicle.localRouteNodeIds = holdRouteNodeIds;
    vehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), holdRouteNodeIds.at(-1) ?? vehicle.currentNodeId, holdRouteNodeIds, 'agent-refresh-top-lift-spine-cycle-yield', { countTaskReplan: false });
    return true;
  }

  private tryClearTopLiftTaskStopApproachBlocker(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    blockedStopNodeId: string
  ): boolean {
    const requesterTask = this.taskForVehicle(requester);
    if (
      !this.topLiftColumnLayoutEnabled() ||
      !requester.loaded ||
      requesterTask?.kind !== 'outbound' ||
      blockedStopNodeId !== requesterTask.dropoffNodeId ||
      blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0
    ) {
      return false;
    }

    const serviceSlot = topLiftQueueServiceSlot(blockedStopNodeId);
    if (!serviceSlot || this.liftPortKindForNodeId(serviceSlot.liftNodeId) !== 'outbound') {
      return false;
    }
    const currentColumnMatch = /^column-top-a-c(\d+)$/.exec(blocker.currentNodeId);
    if (!currentColumnMatch) {
      return false;
    }

    const serviceNode = this.layoutNode(blockedStopNodeId);
    const currentNode = this.layoutNode(blocker.currentNodeId);
    if (!serviceNode || !currentNode || currentNode.x < serviceNode.x - this.scenario.vehicles.lengthM) {
      return false;
    }

    const safeX = serviceNode.x + this.scenario.vehicles.lengthM + this.scenario.vehicles.safetyRadiusM + 0.05;
    const candidates = this.scenario.layout.nodes
      .filter((node) => /^column-top-a-c\d+$/.test(node.id) && node.x >= safeX)
      .sort((left, right) => left.x - right.x || left.id.localeCompare(right.id));

    const currentColumn = Number(currentColumnMatch[1]);
    for (const candidate of candidates) {
      const targetColumn = Number(/^column-top-a-c(\d+)$/.exec(candidate.id)?.[1] ?? NaN);
      if (!Number.isFinite(targetColumn) || targetColumn <= currentColumn) {
        continue;
      }
      const routeNodeIds = Array.from({ length: targetColumn - currentColumn + 1 }, (_, index) =>
        `column-top-a-c${String(currentColumn + index).padStart(2, '0')}`
      );
      if (!this.routeEdgesExist(routeNodeIds) || !this.agentRefreshLocalRouteNodesClear(blocker, routeNodeIds)) {
        continue;
      }
      blocker.routeNodeIds = routeNodeIds;
      blocker.routeIndex = 0;
      blocker.targetNodeId = routeNodeIds[1] ?? null;
      blocker.state = blocker.taskId ? 'moving-to-pickup' : 'returning';
      blocker.waitReason = null;
      blocker.blockingReservationId = null;
      blocker.blockingVehicleId = null;
      blocker.waitingSinceSec = null;
      blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, routeNodeIds) + 2);
      blocker.yieldHoldNodeId = routeNodeIds[routeNodeIds.length - 1] ?? null;
      blocker.localRouteNodeIds = routeNodeIds;
      blocker.localRouteReason = 'temporary-yield';
      this.logAgentReroute(
        blocker,
        this.taskForVehicle(blocker),
        blockedStopNodeId,
        routeNodeIds,
        'top-lift-service-stop-clearance-yield',
        { countTaskReplan: false }
      );
      return true;
    }

    return false;
  }

  private tryRetreatAgentRefreshNearFaceoff(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidates = this.vehicles
      .filter((vehicle) => {
        if (
          !candidateIds.has(vehicle.id) ||
          vehicle.state !== 'waiting-blocked' ||
          (vehicle.waitReason !== 'min-separation' && vehicle.waitReason !== 'avoidance-clearance' && vehicle.waitReason !== 'edge-head-on' && vehicle.waitReason !== 'lift-column-near' && vehicle.waitReason !== 'top-lift-spine-opposing-claim') ||
          vehicle.targetNodeId === null ||
          !vehicle.blockingVehicleId
        ) {
          return false;
        }
        const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId);
        return Boolean(
          blocker &&
          candidateIds.has(blocker.id) &&
          blocker.state === 'waiting-blocked' &&
          blocker.blockingVehicleId === vehicle.id
        );
      })
      .sort((left, right) =>
        Number(left.loaded) - Number(right.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      if (this.topLiftTopBToTopAClearingMove(vehicle)) {
        continue;
      }
      if (this.topLiftOutboundClearanceLiftNodeId(vehicle)) {
        continue;
      }
      if (this.topLiftInboundPickupApproachShouldHoldLine(vehicle)) {
        continue;
      }
      const retreatNodeId = vehicle.currentNodeId;
      const fromBlockedNodeId = vehicle.targetNodeId;
      if (!fromBlockedNodeId) {
        continue;
      }
      const edge = this.traffic.findEdge(retreatNodeId, fromBlockedNodeId);
      if (!edge) {
        continue;
      }
      const blocker = vehicle.blockingVehicleId
        ? this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null
        : null;
      const task = this.taskForVehicle(vehicle);
      if (this.mustStopAtNode(vehicle, task, fromBlockedNodeId)) {
        if (blocker && this.tryClearTopLiftTaskStopApproachBlocker(blocker, vehicle, fromBlockedNodeId)) {
          return true;
        }
        continue;
      }
      if (blocker?.waitReason === 'local-yield-hold') {
        continue;
      }
      if (vehicle.currentEdgeId === null) {
        const currentLiftId = this.liftStorageTransferTargetLiftId(retreatNodeId);
        const targetLiftId = this.liftStorageTransferTargetLiftId(fromBlockedNodeId);
        const oldLiftTransferFaceoff = Boolean(currentLiftId && currentLiftId === targetLiftId);
        const topLiftSpineFaceoff = this.topLiftColumnLayoutEnabled() &&
          this.topLiftColumnSpineOrAccessNode(retreatNodeId) &&
          this.topLiftColumnSpineOrAccessNode(fromBlockedNodeId);
        if (!oldLiftTransferFaceoff && !topLiftSpineFaceoff) {
          continue;
        }
        const session = blocker ? this.activeConflictSessionForPair(vehicle.id, blocker.id) : null;
        if (this.agentRefreshWinnerShouldStayCourse(session, vehicle, blocker)) {
          continue;
        }
        if (blocker && this.agentRefreshInstallSideYield(vehicle, fromBlockedNodeId, blocker, session)) {
          return true;
        }
        continue;
	      }
	      const serviceClearanceRetreatNodeId = blocker
	        ? this.topLiftStorageServiceClearanceRetreatNodeId(vehicle, blocker)
	        : null;
	      if (serviceClearanceRetreatNodeId) {
	        const routeNodeIds = [fromBlockedNodeId, retreatNodeId, serviceClearanceRetreatNodeId];
	        if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
	          return true;
	        }
	        this.startAgentMinimalReverseLeg(
	          vehicle,
	          edge,
	          fromBlockedNodeId,
	          retreatNodeId,
	          routeNodeIds,
	          'top-lift-service-clearance-storage-retreat',
	          0
	        );
	        return true;
	      }
      const inboundQueueExitContinuationNodeId = blocker
        ? this.topLiftInboundQueueExitAwayContinuationNodeId(vehicle, retreatNodeId, fromBlockedNodeId, blocker)
        : null;
      if (inboundQueueExitContinuationNodeId) {
        const routeNodeIds = [fromBlockedNodeId, retreatNodeId, inboundQueueExitContinuationNodeId];
        if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
          return true;
        }
        this.startAgentMinimalReverseLeg(
          vehicle,
          edge,
          fromBlockedNodeId,
          retreatNodeId,
          routeNodeIds,
          'top-lift-inbound-queue-exit-clearance-yield',
          0
        );
        return true;
      }
      const forwardPocketNodeId = this.agentRefreshForwardYieldPocketNodeId(vehicle, retreatNodeId, fromBlockedNodeId, blocker);
      if (forwardPocketNodeId) {
        const routeNodeIds = [retreatNodeId, fromBlockedNodeId, forwardPocketNodeId];
        if (blocker && this.topLiftRouteEntersProtectedInboundQueueExit(routeNodeIds, blocker)) {
          continue;
        }
        if (this.topLiftInboundServiceEntryRetreatRoute(routeNodeIds)) {
          continue;
        }
        if (!this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
          continue;
        }
        if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
          return true;
        }
        this.startAgentRefreshForwardPocketYield(
          vehicle,
          edge,
          retreatNodeId,
          fromBlockedNodeId,
          forwardPocketNodeId
        );
        return true;
      }
      const continuationNodeId = this.agentRefreshYieldPocketNodeId(vehicle, retreatNodeId, fromBlockedNodeId, blocker);
      const retreatNode = this.layoutNode(retreatNodeId);
      const canShortRetreatOnly = !continuationNodeId && Boolean(retreatNode && (retreatNode.type === 'lift-blackbox' || retreatNode.type === 'parking'));
      if (!continuationNodeId && !canShortRetreatOnly) {
        continue;
      }
      const routeNodeIds = continuationNodeId ? [fromBlockedNodeId, retreatNodeId, continuationNodeId] : [fromBlockedNodeId, retreatNodeId];
      if (blocker && this.topLiftRouteEntersProtectedInboundQueueExit(routeNodeIds, blocker)) {
        continue;
      }
      if (this.topLiftInboundServiceEntryRetreatRoute(routeNodeIds)) {
        continue;
      }
      if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
        return true;
      }
      this.startAgentMinimalReverseLeg(
        vehicle,
        edge,
        fromBlockedNodeId,
        retreatNodeId,
        routeNodeIds,
        'agent-refresh-near-faceoff-yield',
        continuationNodeId ? 0 : 4
      );
      return true;
    }
    return false;
  }

  private tryBreakAgentRefreshReciprocalEdgeFaceoff(): boolean {
    const consideredPairs = new Set<string>();
    const candidates = this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.blockingVehicleId !== null &&
        vehicle.targetNodeId !== null &&
        (
          vehicle.waitReason === 'min-separation' ||
          vehicle.waitReason === 'avoidance-clearance' ||
          vehicle.waitReason === 'edge-head-on' ||
          vehicle.waitReason === 'top-lift-spine-opposing-claim' ||
          vehicle.waitReason === 'middle-aisle-opposing-claim'
        )
      )
      .sort((left, right) =>
        Number(left.loaded) - Number(right.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (
        !blocker ||
        blocker.state !== 'waiting-blocked' ||
        blocker.blockingVehicleId !== vehicle.id ||
        (blocker.waitReason === 'local-yield-hold' &&
          !this.mustStopAtNode(vehicle, this.taskForVehicle(vehicle), vehicle.targetNodeId!)) ||
        (vehicle.currentEdgeId === null && blocker.currentEdgeId === null)
      ) {
        continue;
      }
      const pairKey = [vehicle.id, blocker.id].sort((left, right) => left.localeCompare(right)).join('+');
      if (consideredPairs.has(pairKey)) {
        continue;
      }
      consideredPairs.add(pairKey);
      if (this.tryRetreatAgentRefreshNearFaceoff([vehicle.id, blocker.id])) {
        return true;
      }
    }
    return false;
  }

  private topLiftInboundServiceEntryRetreatRoute(routeNodeIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const fromServiceSlot = topLiftQueueServiceSlot(routeNodeIds[index - 1]!);
      const toEntrySlot = topLiftQueueEntrySlot(routeNodeIds[index]!);
      if (
        fromServiceSlot &&
        toEntrySlot &&
        fromServiceSlot.liftNodeId === toEntrySlot.liftNodeId &&
        fromServiceSlot.slotIndex === toEntrySlot.slotIndex &&
        this.liftPortKindForNodeId(fromServiceSlot.liftNodeId) === 'inbound'
      ) {
        return true;
      }
    }
    return false;
  }

  private topLiftProtectedInboundQueueExitTargetNodeId(requester: MutableVehicle): string | null {
    if (!this.topLiftColumnLayoutEnabled() || !requester.targetNodeId) {
      return null;
    }
    const currentEntrySlot = topLiftQueueEntrySlot(requester.currentNodeId);
    if (
      !currentEntrySlot ||
      this.liftPortKindForNodeId(currentEntrySlot.liftNodeId) !== 'inbound' ||
      topLiftAisleLevel(requester.targetNodeId) !== 'top-b'
    ) {
      return null;
    }
    return requester.targetNodeId;
  }

  private topLiftRouteEntersProtectedInboundQueueExit(
    routeNodeIds: string[],
    requester: MutableVehicle
  ): boolean {
    const protectedTargetNodeId = this.topLiftProtectedInboundQueueExitTargetNodeId(requester);
    if (!protectedTargetNodeId) {
      return false;
    }
    return routeNodeIds.some((nodeId, index) => index > 0 && nodeId === protectedTargetNodeId);
  }

  private topLiftInboundQueueExitAwayContinuationNodeId(
    vehicle: MutableVehicle,
    retreatNodeId: string,
    protectedTargetNodeId: string,
    requester: MutableVehicle
  ): string | null {
    if (
      vehicle.loaded ||
      this.topLiftProtectedInboundQueueExitTargetNodeId(requester) !== protectedTargetNodeId ||
      topLiftAisleLevel(retreatNodeId) !== 'top-b' ||
      topLiftAisleLevel(protectedTargetNodeId) !== 'top-b'
    ) {
      return null;
    }
    const retreatColumn = this.topLiftColumnAccessColumn(retreatNodeId);
    const protectedColumn = this.topLiftColumnAccessColumn(protectedTargetNodeId);
    if (retreatColumn === null || protectedColumn === null || retreatColumn === protectedColumn) {
      return null;
    }
    const awayDirection = Math.sign(retreatColumn - protectedColumn);
    const candidateNodeIds = [
      columnAccessNodeId('top-b', retreatColumn - 1 + awayDirection),
      columnAccessNodeId('top-a', retreatColumn - 1),
      `storage-r01-c${String(retreatColumn).padStart(2, '0')}`
    ];

    for (const candidateNodeId of candidateNodeIds) {
      if (
        candidateNodeId === protectedTargetNodeId ||
        candidateNodeId === requester.currentNodeId ||
        candidateNodeId === requester.targetNodeId ||
        !this.layoutNode(candidateNodeId) ||
        !this.traffic.findEdge(retreatNodeId, candidateNodeId) ||
        !this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, candidateNodeId, requester) ||
        !this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, candidateNodeId) ||
        !this.agentMinimalYieldFirstLegSafe(vehicle, retreatNodeId, candidateNodeId) ||
        !this.agentRefreshLocalRouteNodesClear(vehicle, [retreatNodeId, candidateNodeId]) ||
        this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, [
          protectedTargetNodeId,
          retreatNodeId,
          candidateNodeId
        ])
      ) {
        continue;
      }
      return candidateNodeId;
    }

    return null;
  }

  private topLiftInboundPickupApproachShouldHoldLine(vehicle: MutableVehicle): boolean {
    if (!this.topLiftColumnLayoutEnabled() || vehicle.loaded) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    if (task?.kind !== 'inbound') {
      return false;
    }
    const pickupServiceSlot = topLiftQueueServiceSlot(task.pickupNodeId);
    if (!pickupServiceSlot || this.liftPortKindForNodeId(pickupServiceSlot.liftNodeId) !== 'inbound') {
      return false;
    }
    const sameLift = (slot: { liftNodeId: string } | null): boolean =>
      slot?.liftNodeId === pickupServiceSlot.liftNodeId;
    return (
      sameLift(topLiftQueueEntrySlot(vehicle.currentNodeId)) ||
      sameLift(topLiftQueueServiceSlot(vehicle.currentNodeId)) ||
      sameLift(topLiftQueueAisleAccess(vehicle.currentNodeId)) ||
      sameLift(topLiftQueueParkingSlot(vehicle.currentNodeId)) ||
      sameLift(this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId)) ||
      sameLift(topLiftQueueEntrySlot(vehicle.targetNodeId ?? '')) ||
      sameLift(topLiftQueueServiceSlot(vehicle.targetNodeId ?? '')) ||
      sameLift(topLiftQueueAisleAccess(vehicle.targetNodeId ?? '')) ||
      sameLift(topLiftQueueParkingSlot(vehicle.targetNodeId ?? '')) ||
      sameLift(this.topLiftInboundApproachQueueSlot(vehicle.targetNodeId ?? ''))
    );
  }

  private topLiftStorageServiceClearanceRetreatNodeId(vehicle: MutableVehicle, serviceVehicle: MutableVehicle): string | null {
    const clearanceSegment = this.topLiftActiveServiceClearanceSegment(serviceVehicle);
    if (
      !clearanceSegment ||
      vehicle.loaded ||
      !this.isStorageNode(vehicle.currentNodeId)
    ) {
      return null;
    }

    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    if (!currentPosition) {
      return null;
    }

    const fromNode = this.layoutNode(clearanceSegment.fromNodeId);
    const toNode = this.layoutNode(clearanceSegment.toNodeId);
    if (!fromNode || !toNode) {
      return null;
    }

    const candidate = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => {
        const position = this.storageGridPosition(neighbor.nodeId);
        return position !== null &&
          position.column === currentPosition.column &&
          position.row > currentPosition.row;
      })
      .filter((neighbor) => this.agentRefreshTemporaryStorageNodeAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, neighbor.nodeId))
      .sort((left, right) => {
        const leftNode = nodePosition(this.scenario, left.nodeId);
        const rightNode = nodePosition(this.scenario, right.nodeId);
        const leftDistanceM = this.pointToSegmentDistanceM(leftNode.x, leftNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z);
        const rightDistanceM = this.pointToSegmentDistanceM(rightNode.x, rightNode.z, fromNode.x, fromNode.z, toNode.x, toNode.z);
        return rightDistanceM - leftDistanceM ||
          left.lengthM - right.lengthM ||
          left.nodeId.localeCompare(right.nodeId);
      })[0];
    return candidate?.nodeId ?? null;
  }

  private topLiftColumnSpineOrAccessNode(nodeId: string): boolean {
    return isTopLiftColumnAccessNodeId(nodeId);
  }

  private topLiftAdjacentSwapNetworkNode(nodeId: string): boolean {
    return this.topLiftColumnSpineOrAccessNode(nodeId) || topLiftSpineKey(nodeId) !== null;
  }

  private agentRefreshTemporaryRouteAlreadyActive(vehicle: MutableVehicle, routeNodeIds: string[]): boolean {
    if (
      vehicle.state === 'waiting-blocked' &&
      vehicle.waitReason !== 'local-yield-hold' &&
      vehicle.currentEdgeId === null &&
      vehicle.legRemainingM <= 0
    ) {
      return false;
    }
    return vehicle.localRouteReason === 'temporary-yield' &&
      vehicle.routeNodeIds.join('>') === routeNodeIds.join('>') &&
      vehicle.localRouteNodeIds.join('>') === routeNodeIds.join('>') &&
      this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds);
  }

  private agentRefreshClearanceRouteInProgressAwayFrom(vehicle: MutableVehicle, blockedNodeId: string): boolean {
    if (
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.waitReason !== null ||
      vehicle.targetNodeId === null ||
      vehicle.targetNodeId === blockedNodeId ||
      vehicle.routeNodeIds.length <= 1 ||
      vehicle.routeNodeIds[0] !== vehicle.currentNodeId ||
      vehicle.routeNodeIds[1] !== vehicle.targetNodeId
    ) {
      return false;
    }
    return vehicle.localRouteReason === 'temporary-yield' ||
      vehicle.localRouteReason === 'inbound-unready-queue-leader-yield' ||
      vehicle.localRouteReason === 'column-access-storage-swap-clearance';
  }

  private agentRefreshTemporaryYieldShouldContinue(vehicle: MutableVehicle, blockedNodeId: string): boolean {
    if (
      (vehicle.localRouteReason !== 'temporary-yield' && vehicle.localRouteReason !== 'inbound-unready-queue-leader-yield') ||
      vehicle.routeNodeIds.length < 2
    ) {
      return false;
    }
    if (vehicle.currentEdgeId !== null || vehicle.legRemainingM > 0) {
      return true;
    }
    const currentIndex = vehicle.routeNodeIds.indexOf(vehicle.currentNodeId, Math.max(0, vehicle.routeIndex));
    if (currentIndex < 0) {
      return false;
    }
    const routeTail = vehicle.routeNodeIds.slice(currentIndex);
    const nextNodeId = routeTail[1] ?? null;
    if (!nextNodeId || nextNodeId === blockedNodeId || !this.traffic.findEdge(vehicle.currentNodeId, nextNodeId)) {
      return false;
    }
    return this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeTail) === null;
  }

  private tryBreakAgentRefreshStorageColumnQueue(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidateOrDependent = this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null &&
        (candidateIds.has(vehicle.id) || candidateIds.has(vehicle.blockingVehicleId))
      )
      .sort((left, right) =>
        Number(left.loaded) - Number(right.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidateOrDependent) {
      const routeNodeIds = this.agentRefreshStorageColumnQueueYieldRoute(vehicle);
      if (!routeNodeIds) {
        continue;
      }
      if (this.agentRefreshTemporaryRouteAlreadyActive(vehicle, routeNodeIds)) {
        return true;
      }
      this.installAgentRefreshStorageColumnQueueYield(vehicle, routeNodeIds);
      return true;
    }
    return false;
  }

  private tryClearTopLiftLoadedOutboundStorageExitBlockers(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const loadedOutboundVehicles = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.loaded &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null &&
        this.isStorageNode(vehicle.currentNodeId) &&
        this.isStorageNode(vehicle.targetNodeId) &&
        this.taskForVehicle(vehicle)?.kind === 'outbound'
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const loadedVehicle of loadedOutboundVehicles) {
      const blocker = this.vehicles.find((candidate) => candidate.id === loadedVehicle.blockingVehicleId) ?? null;
      if (!blocker || !this.topLiftLoadedOutboundStorageExitBlockerPair(loadedVehicle, blocker)) {
        continue;
      }
      const routeNodeIds = this.topLiftLoadedOutboundStorageExitBlockerClearanceRoute(loadedVehicle, blocker);
      if (routeNodeIds) {
        this.installTopLiftLoadedOutboundStorageExitBlockerClearance(blocker, loadedVehicle, routeNodeIds);
        return true;
      }
      const retreatRouteNodeIds = this.topLiftLoadedOutboundStorageExitRetreatRoute(loadedVehicle, blocker);
      if (retreatRouteNodeIds) {
        this.installTopLiftLoadedOutboundStorageExitRetreat(loadedVehicle, blocker, retreatRouteNodeIds);
        return true;
      }
    }
    return false;
  }

  private topLiftLoadedOutboundStorageExitBlockerPair(loadedVehicle: MutableVehicle, blocker: MutableVehicle): boolean {
    if (
      !loadedVehicle.targetNodeId ||
      !loadedVehicle.blockingVehicleId ||
      blocker.id !== loadedVehicle.blockingVehicleId ||
      blocker.loaded ||
      blocker.currentNodeId !== loadedVehicle.targetNodeId ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      !this.isStorageNode(blocker.currentNodeId)
    ) {
      return false;
    }
    const loadedCurrentPosition = this.storageGridPosition(loadedVehicle.currentNodeId);
    const loadedTargetPosition = this.storageGridPosition(loadedVehicle.targetNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    return Boolean(
      loadedCurrentPosition &&
      loadedTargetPosition &&
      blockerPosition &&
      loadedCurrentPosition.column === loadedTargetPosition.column &&
      blockerPosition.column === loadedTargetPosition.column &&
      Math.abs(loadedCurrentPosition.row - loadedTargetPosition.row) === 1
    );
  }

  private topLiftLoadedOutboundStorageExitBlockerClearanceRoute(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle
  ): string[] | null {
    const loadedCurrentPosition = this.storageGridPosition(loadedVehicle.currentNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    if (!loadedCurrentPosition || !blockerPosition) {
      return null;
    }
    const awayRowDirection = Math.sign(blockerPosition.row - loadedCurrentPosition.row);
    const candidateNodeIds = [
      `storage-r${String(blockerPosition.row).padStart(2, '0')}-c${String(blockerPosition.column - 1).padStart(2, '0')}`,
      `storage-r${String(blockerPosition.row).padStart(2, '0')}-c${String(blockerPosition.column + 1).padStart(2, '0')}`,
      awayRowDirection === 0
        ? null
        : `storage-r${String(blockerPosition.row + awayRowDirection).padStart(2, '0')}-c${String(blockerPosition.column).padStart(2, '0')}`
    ].filter((nodeId): nodeId is string => nodeId !== null);

    for (const nodeId of candidateNodeIds.filter((candidate, index, all) => all.indexOf(candidate) === index)) {
      if (
        nodeId === loadedVehicle.currentNodeId ||
        nodeId === loadedVehicle.targetNodeId ||
        !this.layoutNode(nodeId) ||
        !this.isStorageNode(nodeId) ||
        !this.traffic.findEdge(blocker.currentNodeId, nodeId) ||
        !this.agentRefreshTemporaryStorageNodeAllowed(blocker, nodeId) ||
        !this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, nodeId)
      ) {
        continue;
      }
      const routeNodeIds = [blocker.currentNodeId, nodeId];
      if (
        !this.agentRefreshLocalRouteNodesClear(blocker, routeNodeIds) ||
        this.agentRefreshMoveBlocker(blocker, nodeId, routeNodeIds)
      ) {
        continue;
      }
      return routeNodeIds;
    }
    return null;
  }

  private topLiftLoadedOutboundStorageExitRetreatRoute(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle
  ): string[] | null {
    const loadedCurrentPosition = this.storageGridPosition(loadedVehicle.currentNodeId);
    const loadedTargetPosition = this.storageGridPosition(loadedVehicle.targetNodeId ?? '');
    if (!loadedCurrentPosition || !loadedTargetPosition) {
      return null;
    }
    const awayRowDirection = Math.sign(loadedCurrentPosition.row - loadedTargetPosition.row);
    if (awayRowDirection === 0) {
      return null;
    }
    const retreatNodeId = `storage-r${String(loadedCurrentPosition.row + awayRowDirection).padStart(2, '0')}-c${String(loadedCurrentPosition.column).padStart(2, '0')}`;
    if (
      retreatNodeId === blocker.currentNodeId ||
      !this.layoutNode(retreatNodeId) ||
      !this.isStorageNode(retreatNodeId) ||
      !this.traffic.findEdge(loadedVehicle.currentNodeId, retreatNodeId) ||
      !this.agentRefreshTemporaryStorageNodeAllowed(loadedVehicle, retreatNodeId) ||
      !this.agentMinimalYieldFirstLegSafe(loadedVehicle, loadedVehicle.currentNodeId, retreatNodeId)
    ) {
      return null;
    }
    const routeNodeIds = [loadedVehicle.currentNodeId, retreatNodeId];
    if (
      !this.agentRefreshLocalRouteNodesClear(loadedVehicle, routeNodeIds) ||
      this.agentRefreshMoveBlocker(loadedVehicle, retreatNodeId, routeNodeIds)
    ) {
      return null;
    }
    return routeNodeIds;
  }

  private installTopLiftLoadedOutboundStorageExitBlockerClearance(
    blocker: MutableVehicle,
    loadedVehicle: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    const session = this.activeConflictSessionForPair(blocker.id, loadedVehicle.id);
    if (session) {
      this.closeConflictSession(session, 'loaded-outbound-storage-exit-clearance');
    }
    blocker.routeNodeIds = routeNodeIds;
    blocker.routeIndex = 0;
    blocker.targetNodeId = routeNodeIds[1] ?? null;
    blocker.state = blocker.taskId ? 'moving-to-pickup' : 'returning';
    blocker.waitReason = null;
    blocker.blockingReservationId = null;
    blocker.blockingVehicleId = null;
    blocker.waitingSinceSec = null;
    blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, routeNodeIds) + 2);
    blocker.yieldHoldNodeId = routeNodeIds.at(-1) ?? null;
    blocker.localRouteNodeIds = routeNodeIds;
    blocker.localRouteReason = 'loaded-outbound-storage-exit-clearance';
    this.logAgentReroute(blocker, this.taskForVehicle(blocker), loadedVehicle.targetNodeId ?? blocker.currentNodeId, routeNodeIds, 'agent-refresh-loaded-outbound-storage-exit-clearance', { countTaskReplan: false });
  }

  private installTopLiftLoadedOutboundStorageExitRetreat(
    loadedVehicle: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    const session = this.activeConflictSessionForPair(blocker.id, loadedVehicle.id);
    if (session) {
      this.closeConflictSession(session, 'loaded-outbound-storage-exit-retreat');
    }
    loadedVehicle.routeNodeIds = routeNodeIds;
    loadedVehicle.routeIndex = 0;
    loadedVehicle.targetNodeId = routeNodeIds[1] ?? null;
    loadedVehicle.state = 'loaded-moving';
    loadedVehicle.waitReason = null;
    loadedVehicle.blockingReservationId = null;
    loadedVehicle.blockingVehicleId = null;
    loadedVehicle.waitingSinceSec = null;
    loadedVehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(loadedVehicle, routeNodeIds) + 2);
    loadedVehicle.yieldHoldNodeId = routeNodeIds.at(-1) ?? null;
    loadedVehicle.localRouteNodeIds = routeNodeIds;
    loadedVehicle.localRouteReason = 'loaded-outbound-storage-exit-retreat';
    this.logAgentReroute(loadedVehicle, this.taskForVehicle(loadedVehicle), blocker.currentNodeId, routeNodeIds, 'agent-refresh-loaded-outbound-storage-exit-retreat', { countTaskReplan: false });
  }

  private tryClearTopLiftBottomLaneMeterBlockers(candidateVehicleIds: string[]): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return false;
    }
    const candidateIds = new Set(candidateVehicleIds);
    const waitingLoadedInbound = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.loaded &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null &&
        this.taskForVehicle(vehicle)?.kind === 'inbound' &&
        isTopLiftAisleLevelNodeId(vehicle.currentNodeId, 'bottom-a') &&
        isTopLiftAisleLevelNodeId(vehicle.targetNodeId, 'bottom-a')
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const requester of waitingLoadedInbound) {
      const blocker = this.vehicles.find((candidate) => candidate.id === requester.blockingVehicleId) ?? null;
      if (!blocker || !this.topLiftBottomLaneMeterBlockerPair(requester, blocker)) {
        continue;
      }
      const routeNodeIds = this.topLiftBottomLaneMeterBlockerClearanceRoute(requester, blocker);
      if (!routeNodeIds) {
        continue;
      }
      this.installTopLiftBottomLaneMeterBlockerClearance(blocker, requester, routeNodeIds);
      return true;
    }
    return false;
  }

  private topLiftBottomLaneMeterBlockerPair(requester: MutableVehicle, blocker: MutableVehicle): boolean {
    if (
      !requester.targetNodeId ||
      blocker.currentNodeId !== requester.targetNodeId ||
      !blocker.loaded ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.phaseRemainingSec > 0 ||
      this.taskForVehicle(blocker)?.kind !== 'outbound' ||
      !isTopLiftAisleLevelNodeId(blocker.currentNodeId, 'bottom-a') ||
      !this.topLiftBottomLaneMeterBlockerSlot(blocker.currentNodeId)
    ) {
      return false;
    }
    const requesterTask = this.taskForVehicle(requester);
    const blockerTask = this.taskForVehicle(blocker);
    return Boolean(
      requesterTask?.kind === 'inbound' &&
      blockerTask?.kind === 'outbound' &&
      requesterTask.id !== blockerTask.id
    );
  }

  private topLiftBottomLaneMeterBlockerSlot(nodeId: string): { liftNodeId: string; slotIndex: number } | null {
    const directSlot = this.topLiftOutboundMeterSlot(nodeId);
    if (directSlot) {
      return directSlot;
    }
    if (!isTopLiftAisleLevelNodeId(nodeId, 'bottom-a')) {
      return null;
    }
    const column = this.topLiftColumnAccessColumn(nodeId);
    if (column === null) {
      return null;
    }
    return this.topLiftOutboundMeterSlot(columnAccessNodeId('bottom-b', column - 1));
  }

  private topLiftBottomLaneMeterBlockerClearanceRoute(
    requester: MutableVehicle,
    blocker: MutableVehicle
  ): string[] | null {
    const blockerColumn = this.topLiftColumnAccessColumn(blocker.currentNodeId);
    if (!blockerColumn) {
      return null;
    }
    const clearanceNodeId = columnAccessNodeId('bottom-b', blockerColumn - 1);
    if (
      clearanceNodeId === requester.currentNodeId ||
      clearanceNodeId === requester.targetNodeId ||
      !this.layoutNode(clearanceNodeId) ||
      !this.topLiftDoubleAisleOppositeLaneNode(blocker.currentNodeId, clearanceNodeId) ||
      this.currentNodeOccupancy.has(clearanceNodeId) ||
      this.topLiftBottomLaneMeterClearanceTargetClaimed(blocker, clearanceNodeId) ||
      this.nodeClaimedByOtherVehicle(clearanceNodeId, blocker.id) ||
      !this.agentMinimalYieldFirstLegSafe(blocker, blocker.currentNodeId, clearanceNodeId)
    ) {
      return null;
    }
    const routeNodeIds = [blocker.currentNodeId, clearanceNodeId];
    if (
      !this.agentRefreshLocalRouteNodesClear(blocker, routeNodeIds) ||
      this.agentRefreshMoveBlocker(blocker, clearanceNodeId, routeNodeIds)
    ) {
      return null;
    }
    return routeNodeIds;
  }

  private topLiftBottomLaneMeterClearanceTargetClaimed(blocker: MutableVehicle, clearanceNodeId: string): boolean {
    return this.vehicles.some((vehicle) =>
      vehicle.id !== blocker.id &&
      vehicle.targetNodeId === clearanceNodeId &&
      vehicle.currentNodeId !== clearanceNodeId &&
      vehicle.state !== 'idle' &&
      vehicle.state !== 'parking'
    );
  }

  private installTopLiftBottomLaneMeterBlockerClearance(
    blocker: MutableVehicle,
    requester: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    const terminalNodeId = routeNodeIds.at(-1) ?? blocker.currentNodeId;
    const session = this.activeConflictSessionForPair(blocker.id, requester.id);
    if (session) {
      this.closeConflictSession(session, 'bottom-lane-meter-clearance');
    }
    blocker.routeNodeIds = routeNodeIds;
    blocker.routeIndex = 0;
    blocker.targetNodeId = routeNodeIds[1] ?? null;
    blocker.state = 'loaded-moving';
    blocker.waitReason = null;
    blocker.blockingReservationId = null;
    blocker.blockingVehicleId = null;
    blocker.waitingSinceSec = null;
    blocker.plannedGoalNodeId = terminalNodeId;
    blocker.plannedRouteNodeIds = routeNodeIds;
    blocker.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(blocker, routeNodeIds) + 2);
    blocker.yieldHoldNodeId = terminalNodeId;
    blocker.localRouteNodeIds = routeNodeIds;
    blocker.localRouteReason = 'bottom-lane-meter-clearance';
    this.logAgentReroute(blocker, this.taskForVehicle(blocker), requester.targetNodeId ?? blocker.currentNodeId, routeNodeIds, 'agent-refresh-bottom-lane-meter-clearance', { countTaskReplan: false });
  }

  private agentRefreshStorageColumnQueueYieldRoute(vehicle: MutableVehicle): string[] | null {
    if (!vehicle.targetNodeId) {
      return null;
    }
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const targetPosition = this.storageGridPosition(vehicle.targetNodeId);
    if (!currentPosition || !targetPosition || currentPosition.column !== targetPosition.column) {
      return null;
    }

    const awayDirection = Math.sign(currentPosition.row - targetPosition.row);
    const candidates: string[] = [];
    if (awayDirection !== 0) {
      candidates.push(`storage-r${String(currentPosition.row + awayDirection).padStart(2, '0')}-c${String(currentPosition.column).padStart(2, '0')}`);
    }
    candidates.push(
      ...this.neighbors(vehicle.currentNodeId)
        .map((neighbor) => neighbor.nodeId)
        .filter((nodeId) => isTopLiftColumnAccessNodeId(nodeId))
    );

    for (const nodeId of candidates.filter((candidate, index, all) => all.indexOf(candidate) === index)) {
      const node = this.layoutNode(nodeId);
      if (!node || nodeId === vehicle.targetNodeId || !this.traffic.findEdge(vehicle.currentNodeId, nodeId)) {
        continue;
      }
      if (node.type === 'storage' && !this.agentRefreshStorageColumnQueueEscapeNodeAllowed(vehicle, nodeId)) {
        continue;
      }
      if (
        node.type !== 'storage' &&
        (
          this.currentNodeOccupancy.has(nodeId) ||
          this.nodeClaimedByOtherVehicle(nodeId, vehicle.id)
        )
      ) {
        continue;
      }
      const directRoute = [vehicle.currentNodeId, nodeId];
      const routeNodeIds = node.noStop || node.noParking
        ? this.extendTopLiftTemporaryYieldRouteToHold(vehicle, directRoute, new Set([vehicle.targetNodeId].filter((id): id is string => Boolean(id))))
        : directRoute;
      const nextNodeId = routeNodeIds?.[1] ?? null;
      if (!routeNodeIds || !nextNodeId || !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds)) {
        continue;
      }
      if (this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeNodeIds)) {
        continue;
      }
      return routeNodeIds;
    }
    return null;
  }

  private installAgentRefreshStorageColumnQueueYield(vehicle: MutableVehicle, routeNodeIds: string[]): void {
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = round(this.simTimeSec + this.routeTravelEstimateSec(vehicle, routeNodeIds) + 2);
    vehicle.yieldHoldNodeId = routeNodeIds.at(-1) ?? null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'temporary-yield';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), routeNodeIds.at(-1) ?? vehicle.currentNodeId, routeNodeIds, 'agent-refresh-storage-column-queue-yield', { countTaskReplan: false });
  }

  private agentRefreshStorageColumnQueueEscapeNodeAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    if (vehicle.loaded || !this.isStorageNode(nodeId)) {
      return this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId);
    }
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    if (this.nodeClaimedByOtherVehicle(nodeId, vehicle.id)) {
      return false;
    }
    return !this.activeInboundDropoffNodeIds().has(nodeId);
  }

  private tryBreakAgentRefreshLoadedStorageSwap(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const consideredPairs = new Set<string>();
    const candidates = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (
        !blocker ||
        !candidateIds.has(blocker.id) ||
        !this.agentRefreshLoadedStorageSwapPair(vehicle, blocker)
      ) {
        continue;
      }
      const pairKey = [vehicle.id, blocker.id].sort((left, right) => left.localeCompare(right)).join('+');
      if (consideredPairs.has(pairKey)) {
        continue;
      }
      consideredPairs.add(pairKey);

      const plans = [
        this.agentRefreshLoadedStorageSwapClearancePlan(vehicle, blocker),
        this.agentRefreshLoadedStorageSwapClearancePlan(blocker, vehicle)
      ]
        .filter((plan): plan is { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } => plan !== null)
        .filter((plan) => this.agentRefreshLocalRouteNodesClear(plan.vehicle, plan.routeNodeIds))
        .sort((left, right) =>
          left.score - right.score ||
          this.agentTurnPriority(left.vehicle) - this.agentTurnPriority(right.vehicle) ||
          right.vehicle.id.localeCompare(left.vehicle.id)
        );
      const plan = plans[0];
      if (!plan) {
        continue;
      }
      if (this.agentRefreshClearanceRouteInProgressAwayFrom(plan.vehicle, plan.blocker.currentNodeId)) {
        continue;
      }

      const session = this.activeConflictSessionForPair(plan.vehicle.id, plan.blocker.id);
      if (session) {
        this.closeConflictSession(session, 'loaded-storage-swap-clearance');
      }
      this.installAgentRefreshLoadedStorageSwapClearance(plan.vehicle, plan.blocker, plan.routeNodeIds);
      return true;
    }
    return false;
  }

  private agentRefreshLoadedStorageSwapCandidateVehicleIds(): string[] {
    return this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null
      )
      .map((vehicle) => vehicle.id);
  }

  private agentRefreshLoadedStorageSwapPairVehicleIds(candidateVehicleIds: string[]): string[] {
    const candidateIds = new Set(candidateVehicleIds);
    const pairVehicleIds = new Set<string>();
    for (const vehicle of this.vehicles) {
      if (!candidateIds.has(vehicle.id) || !vehicle.blockingVehicleId) {
        continue;
      }
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (blocker && candidateIds.has(blocker.id) && this.agentRefreshLoadedStorageSwapPair(vehicle, blocker)) {
        pairVehicleIds.add(vehicle.id);
        pairVehicleIds.add(blocker.id);
      }
    }
    return [...pairVehicleIds];
  }

  private agentRefreshNoStopContinuationWaitCandidateVehicleIds(): string[] {
    return this.vehicles
      .filter((vehicle) =>
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'no-stop-continuation-blocked' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null &&
        (this.layoutNode(vehicle.currentNodeId)?.noStop === true || this.layoutNode(vehicle.targetNodeId)?.noStop === true)
      )
      .map((vehicle) => vehicle.id);
  }

  private tryBreakAgentRefreshColumnAccessStorageSwap(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const consideredPairs = new Set<string>();
    const candidates = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'node-occupied' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (!blocker || !candidateIds.has(blocker.id)) {
        continue;
      }
      const pairKey = [vehicle.id, blocker.id].sort((left, right) => left.localeCompare(right)).join('+');
      if (consideredPairs.has(pairKey)) {
        continue;
      }
      consideredPairs.add(pairKey);

      const plans = [
        this.agentRefreshColumnAccessStorageSwapClearancePlan(vehicle, blocker),
        this.agentRefreshColumnAccessStorageSwapClearancePlan(blocker, vehicle),
        this.agentRefreshStorageColumnAccessSwapClearancePlan(vehicle, blocker),
        this.agentRefreshStorageColumnAccessSwapClearancePlan(blocker, vehicle),
        this.agentRefreshColumnAccessStorageSwapAccessYieldPlan(vehicle, blocker),
        this.agentRefreshColumnAccessStorageSwapAccessYieldPlan(blocker, vehicle)
      ]
        .filter((plan): plan is { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } => plan !== null)
        .filter((plan) => this.agentRefreshLocalRouteNodesClear(plan.vehicle, plan.routeNodeIds))
        .sort((left, right) =>
          left.score - right.score ||
          this.agentTurnPriority(left.vehicle) - this.agentTurnPriority(right.vehicle) ||
          right.vehicle.id.localeCompare(left.vehicle.id)
        );
      const plan = plans[0];
      if (!plan) {
        continue;
      }

      const session = this.activeConflictSessionForPair(plan.vehicle.id, plan.blocker.id);
      if (session) {
        this.closeConflictSession(session, 'column-access-storage-swap-clearance');
      }
      this.installAgentRefreshColumnAccessStorageSwapClearance(plan.vehicle, plan.blocker, plan.routeNodeIds);
      return true;
    }
    return false;
  }

  private agentRefreshColumnAccessStorageSwapClearancePlan(
    accessVehicle: MutableVehicle,
    storageVehicle: MutableVehicle
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    if (
      accessVehicle.loaded ||
      !isTopLiftColumnAccessNodeId(accessVehicle.currentNodeId) ||
      !this.isStorageNode(storageVehicle.currentNodeId) ||
      accessVehicle.targetNodeId !== storageVehicle.currentNodeId ||
      storageVehicle.targetNodeId !== accessVehicle.currentNodeId ||
      storageVehicle.currentEdgeId !== null ||
      storageVehicle.legRemainingM > 0 ||
      storageVehicle.state !== 'waiting-blocked' ||
      storageVehicle.waitReason !== 'node-occupied'
    ) {
      return null;
    }
    const accessColumn = this.topLiftColumnAccessColumn(accessVehicle.currentNodeId);
    const storagePosition = this.storageGridPosition(storageVehicle.currentNodeId);
    if (!accessColumn || !storagePosition || accessColumn !== storagePosition.column) {
      return null;
    }

    const forbiddenNodeIds = new Set<string>([
      storageVehicle.currentNodeId,
      accessVehicle.targetNodeId
    ]);
    const candidates = this.neighbors(accessVehicle.currentNodeId)
      .filter((neighbor) =>
        isTopLiftColumnAccessNodeId(neighbor.nodeId) &&
        neighbor.nodeId !== storageVehicle.currentNodeId &&
        !this.currentNodeOccupancy.has(neighbor.nodeId) &&
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, accessVehicle.id)
      )
      .sort((left, right) =>
        Math.abs((this.topLiftColumnAccessColumn(left.nodeId) ?? accessColumn) - accessColumn) -
          Math.abs((this.topLiftColumnAccessColumn(right.nodeId) ?? accessColumn) - accessColumn) ||
        left.nodeId.localeCompare(right.nodeId)
      );

    for (const candidate of candidates) {
      const routeNodeIds = this.extendTopLiftTemporaryYieldRouteToHold(
        accessVehicle,
        [accessVehicle.currentNodeId, candidate.nodeId],
        forbiddenNodeIds
      );
      const terminalNode = this.layoutNode(routeNodeIds?.at(-1) ?? '');
      const nextNodeId = routeNodeIds?.[1] ?? null;
      if (
        !routeNodeIds ||
        !nextNodeId ||
        routeNodeIds.includes(storageVehicle.currentNodeId) ||
        !terminalNode ||
        terminalNode.noStop ||
        terminalNode.noParking ||
        !this.agentRefreshLocalRouteNodesClear(accessVehicle, routeNodeIds) ||
        this.agentRefreshMoveBlocker(accessVehicle, nextNodeId, routeNodeIds)
      ) {
        continue;
      }
      return {
        vehicle: accessVehicle,
        blocker: storageVehicle,
        routeNodeIds,
        score: this.routeDistanceM(routeNodeIds)
      };
    }
    return null;
  }

  private agentRefreshStorageColumnAccessSwapClearancePlan(
    storageVehicle: MutableVehicle,
    accessVehicle: MutableVehicle
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    if (
      storageVehicle.loaded ||
      !this.isStorageNode(storageVehicle.currentNodeId) ||
      !isTopLiftColumnAccessNodeId(accessVehicle.currentNodeId) ||
      storageVehicle.targetNodeId !== accessVehicle.currentNodeId ||
      accessVehicle.targetNodeId !== storageVehicle.currentNodeId ||
      storageVehicle.currentEdgeId !== null ||
      accessVehicle.currentEdgeId !== null ||
      storageVehicle.legRemainingM > 0 ||
      accessVehicle.legRemainingM > 0 ||
      storageVehicle.state !== 'waiting-blocked' ||
      accessVehicle.state !== 'waiting-blocked' ||
      storageVehicle.waitReason !== 'node-occupied' ||
      accessVehicle.waitReason !== 'node-occupied'
    ) {
      return null;
    }

    const accessColumn = this.topLiftColumnAccessColumn(accessVehicle.currentNodeId);
    const storagePosition = this.storageGridPosition(storageVehicle.currentNodeId);
    if (
      !accessColumn ||
      !storagePosition ||
      accessColumn !== storagePosition.column ||
      !this.traffic.findEdge(storageVehicle.currentNodeId, accessVehicle.currentNodeId)
    ) {
      return null;
    }

    const preferredHoldPosition = this.storageGridPosition(
      storageVehicle.plannedGoalNodeId ?? storageVehicle.routeNodeIds.at(-1) ?? ''
    );
    const sideStorageNodeIds = [storagePosition.column + 1, storagePosition.column - 1]
      .map((column) => `storage-r${String(storagePosition.row).padStart(2, '0')}-c${String(column).padStart(2, '0')}`)
      .filter((nodeId, index, nodeIds) => nodeIds.indexOf(nodeId) === index)
      .filter((nodeId) =>
        nodeId !== accessVehicle.currentNodeId &&
        nodeId !== accessVehicle.targetNodeId &&
        this.layoutNode(nodeId) &&
        this.traffic.findEdge(storageVehicle.currentNodeId, nodeId) &&
        this.agentRefreshTemporaryStorageNodeAllowed(storageVehicle, nodeId) &&
        !this.agentRefreshMoveBlocker(storageVehicle, nodeId, [storageVehicle.currentNodeId, nodeId])
      )
      .sort((left, right) =>
        (
          preferredHoldPosition
            ? Math.abs((this.storageGridPosition(left)?.column ?? storagePosition.column) - preferredHoldPosition.column) -
              Math.abs((this.storageGridPosition(right)?.column ?? storagePosition.column) - preferredHoldPosition.column)
            : 0
        ) ||
        Math.abs((this.storageGridPosition(left)?.column ?? storagePosition.column) - storagePosition.column) -
          Math.abs((this.storageGridPosition(right)?.column ?? storagePosition.column) - storagePosition.column) ||
        left.localeCompare(right)
      );

    for (const sideStorageNodeId of sideStorageNodeIds) {
      const routeNodeIds = [storageVehicle.currentNodeId, sideStorageNodeId];
      const terminalNode = this.layoutNode(sideStorageNodeId);
      if (
        !terminalNode ||
        terminalNode.noStop ||
        terminalNode.noParking ||
        !this.agentRefreshLocalRouteNodesClear(storageVehicle, routeNodeIds)
      ) {
        continue;
      }
      return {
        vehicle: storageVehicle,
        blocker: accessVehicle,
        routeNodeIds,
        score: this.routeDistanceM(routeNodeIds) - 0.25
      };
    }
    return null;
  }

  private agentRefreshColumnAccessStorageSwapAccessYieldPlan(
    accessVehicle: MutableVehicle,
    storageVehicle: MutableVehicle
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    if (
      !isTopLiftColumnAccessNodeId(accessVehicle.currentNodeId) ||
      !this.isStorageNode(storageVehicle.currentNodeId) ||
      accessVehicle.targetNodeId !== storageVehicle.currentNodeId ||
      storageVehicle.targetNodeId !== accessVehicle.currentNodeId ||
      accessVehicle.currentEdgeId !== null ||
      storageVehicle.currentEdgeId !== null ||
      accessVehicle.legRemainingM > 0 ||
      storageVehicle.legRemainingM > 0 ||
      accessVehicle.state !== 'waiting-blocked' ||
      storageVehicle.state !== 'waiting-blocked' ||
      accessVehicle.waitReason !== 'node-occupied' ||
      storageVehicle.waitReason !== 'node-occupied'
    ) {
      return null;
    }

    const accessColumn = this.topLiftColumnAccessColumn(accessVehicle.currentNodeId);
    const storagePosition = this.storageGridPosition(storageVehicle.currentNodeId);
    if (
      !accessColumn ||
      !storagePosition ||
      accessColumn !== storagePosition.column ||
      !this.traffic.findEdge(accessVehicle.currentNodeId, storageVehicle.currentNodeId)
    ) {
      return null;
    }

    const routeCandidates = this.neighbors(accessVehicle.currentNodeId)
      .filter((neighbor) =>
        neighbor.nodeId !== storageVehicle.currentNodeId &&
        isTopLiftColumnAccessNodeId(neighbor.nodeId) &&
        !this.currentNodeOccupancy.has(neighbor.nodeId) &&
        !this.nodeClaimedByOtherVehicle(neighbor.nodeId, accessVehicle.id) &&
        this.agentMinimalYieldFirstLegSafe(accessVehicle, accessVehicle.currentNodeId, neighbor.nodeId)
      )
      .flatMap((neighbor) =>
        this.neighbors(neighbor.nodeId)
          .filter((storageNeighbor) =>
            storageNeighbor.nodeId !== accessVehicle.currentNodeId &&
            storageNeighbor.nodeId !== storageVehicle.currentNodeId &&
            this.isStorageNode(storageNeighbor.nodeId) &&
            this.agentRefreshTemporaryStorageNodeAllowed(accessVehicle, storageNeighbor.nodeId) &&
            !this.currentNodeOccupancy.has(storageNeighbor.nodeId) &&
            !this.nodeClaimedByOtherVehicle(storageNeighbor.nodeId, accessVehicle.id)
          )
          .map((storageNeighbor) => [accessVehicle.currentNodeId, neighbor.nodeId, storageNeighbor.nodeId])
      )
      .filter((routeNodeIds) =>
        this.routeHasOnlyAdjacentEdges(routeNodeIds) &&
        this.agentRefreshLocalRouteNodesClear(accessVehicle, routeNodeIds) &&
        !this.agentRefreshMoveBlocker(accessVehicle, routeNodeIds[1]!, routeNodeIds)
      )
      .sort((left, right) =>
        this.routeDistanceM(left) - this.routeDistanceM(right) ||
        left.join('>').localeCompare(right.join('>'))
      );

    const routeNodeIds = routeCandidates[0] ?? null;
    if (!routeNodeIds) {
      return null;
    }
    return {
      vehicle: accessVehicle,
      blocker: storageVehicle,
      routeNodeIds,
      score: this.routeDistanceM(routeNodeIds) + (accessVehicle.loaded ? 0.5 : 0)
    };
  }

  private installAgentRefreshColumnAccessStorageSwapClearance(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'column-access-storage-swap-clearance';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blocker.currentNodeId, routeNodeIds, 'agent-refresh-column-access-storage-swap-clearance', { countTaskReplan: false });
  }

  private agentRefreshLoadedStorageSwapPair(vehicle: MutableVehicle, blocker: MutableVehicle): boolean {
    if (
      blocker.state !== 'waiting-blocked' ||
      blocker.waitReason !== 'node-occupied' ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.targetNodeId !== vehicle.currentNodeId ||
      vehicle.targetNodeId !== blocker.currentNodeId
    ) {
      return false;
    }
    const vehiclePosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    return Boolean(
      vehiclePosition &&
      blockerPosition &&
      (
        (vehiclePosition.row === blockerPosition.row && Math.abs(vehiclePosition.column - blockerPosition.column) === 1) ||
        (
          this.topLiftColumnLayoutEnabled() &&
          vehiclePosition.column === blockerPosition.column &&
          Math.abs(vehiclePosition.row - blockerPosition.row) === 1
        )
      )
    );
  }

  private agentRefreshLoadedStorageSwapClearancePlan(
    vehicle: MutableVehicle,
    blocker: MutableVehicle
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    const currentPosition = this.storageGridPosition(vehicle.currentNodeId);
    const blockerPosition = this.storageGridPosition(blocker.currentNodeId);
    if (!currentPosition || !blockerPosition) {
      return null;
    }

    if (
      this.topLiftColumnLayoutEnabled() &&
      currentPosition.column === blockerPosition.column &&
      Math.abs(currentPosition.row - blockerPosition.row) === 1
    ) {
      return this.agentRefreshLoadedStorageColumnSwapSidePocketPlan(vehicle, blocker, currentPosition) ??
        this.agentRefreshLoadedStorageColumnSwapClearancePlan(vehicle, blocker, currentPosition, blockerPosition) ??
        this.agentRefreshEmptyStorageColumnSwapInlineClearancePlan(vehicle, blocker);
    }

    if (currentPosition.row !== blockerPosition.row) {
      return null;
    }

    const escapeSide: 'left' | 'right' = currentPosition.column > blockerPosition.column ? 'right' : 'left';
    const sideNodeId = this.storageSideNodeId(vehicle.currentNodeId, escapeSide);
    if (!sideNodeId) {
      return null;
    }

    try {
      const blockedNodeIds = this.blockedStorageTransitNodeIds(vehicle.currentNodeId, sideNodeId, { blockStoredLoads: true });
      blockedNodeIds.delete(vehicle.currentNodeId);
      blockedNodeIds.delete(sideNodeId);
      blockedNodeIds.add(blocker.currentNodeId);
      const sideRoute = this.agentRefreshShortestPath(vehicle.currentNodeId, sideNodeId, blockedNodeIds);
      if (
        sideRoute.length < 2 ||
        sideRoute.includes(blocker.currentNodeId) ||
        sideRoute.slice(1, -1).some((nodeId) => this.storedLoadIdAtNode(nodeId))
      ) {
        return null;
      }

      const routeNodeIds = [...sideRoute];
      const aisleEscapeNodeId = this.agentRefreshLoadedStorageSwapAisleEscapeNodeId(sideNodeId, vehicle, blocker);
      if (aisleEscapeNodeId) {
        routeNodeIds.push(aisleEscapeNodeId);
      }

      const nextNodeId = routeNodeIds[1] ?? null;
      if (!nextNodeId || this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeNodeIds)) {
        return null;
      }

      return {
        vehicle,
        blocker,
        routeNodeIds,
        score: this.routeDistanceM(routeNodeIds)
      };
    } catch {
      return null;
    }
  }

  private agentRefreshLoadedStorageColumnSwapSidePocketPlan(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    currentPosition: { row: number; column: number }
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    const candidates = [currentPosition.column - 1, currentPosition.column + 1]
      .map((column) => `storage-r${String(currentPosition.row).padStart(2, '0')}-c${String(column).padStart(2, '0')}`)
      .filter((nodeId) =>
        nodeId !== blocker.currentNodeId &&
        this.layoutNode(nodeId) &&
        this.traffic.findEdge(vehicle.currentNodeId, nodeId) &&
        this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId) &&
        !this.agentRefreshMoveBlocker(vehicle, nodeId)
      )
      .map((nodeId) => ({
        vehicle,
        blocker,
        routeNodeIds: [vehicle.currentNodeId, nodeId],
        score: this.routeDistanceM([vehicle.currentNodeId, nodeId])
      }))
      .sort((left, right) =>
        left.score - right.score ||
        left.routeNodeIds[1]!.localeCompare(right.routeNodeIds[1]!)
      );
    return candidates[0] ?? null;
  }

  private agentRefreshLoadedStorageColumnSwapClearancePlan(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    currentPosition: { row: number; column: number },
    _blockerPosition: { row: number; column: number }
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    const blockedNodeIds = this.agentRefreshTemporaryStorageBlockedNodeIds(vehicle);
    blockedNodeIds.delete(vehicle.currentNodeId);
    blockedNodeIds.add(blocker.currentNodeId);

    const current = nodePosition(this.scenario, vehicle.currentNodeId);
    const accessNodeIds = this.scenario.layout.nodes
      .filter((node) =>
        isTopLiftColumnAccessNodeId(node.id) &&
        this.topLiftColumnAccessColumn(node.id) === currentPosition.column &&
        !this.currentNodeOccupancy.has(node.id) &&
        !this.nodeClaimedByOtherVehicle(node.id, vehicle.id)
      )
      .sort((left, right) =>
        Math.abs(left.z - current.z) - Math.abs(right.z - current.z) ||
        left.id.localeCompare(right.id)
      )
      .map((node) => node.id);

    for (const accessNodeId of accessNodeIds) {
      try {
        const routeNodeIds = this.agentRefreshShortestPath(vehicle.currentNodeId, accessNodeId, blockedNodeIds);
        if (
          routeNodeIds.length < 2 ||
          routeNodeIds.length > 6 ||
          routeNodeIds.includes(blocker.currentNodeId) ||
          !this.routeHasOnlyAdjacentEdges(routeNodeIds) ||
          routeNodeIds.slice(1, -1).some((nodeId) =>
            this.isStorageNode(nodeId) && !this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId)
          )
        ) {
          continue;
        }
        const clearanceRouteNodeIds = this.agentRefreshLoadedStorageSwapLegalHoldPrefix(vehicle, routeNodeIds) ?? routeNodeIds;
        const nextNodeId = clearanceRouteNodeIds[1] ?? null;
        if (!nextNodeId || this.agentRefreshMoveBlocker(vehicle, nextNodeId, clearanceRouteNodeIds)) {
          continue;
        }
        return {
          vehicle,
          blocker,
          routeNodeIds: clearanceRouteNodeIds,
          score: this.routeDistanceM(clearanceRouteNodeIds)
        };
      } catch {
        continue;
      }
    }
    return null;
  }

  private agentRefreshEmptyStorageColumnSwapInlineClearancePlan(
    vehicle: MutableVehicle,
    blocker: MutableVehicle
  ): { vehicle: MutableVehicle; blocker: MutableVehicle; routeNodeIds: string[]; score: number } | null {
    if (vehicle.loaded || !this.isStorageNode(vehicle.currentNodeId) || !this.isStorageNode(blocker.currentNodeId)) {
      return null;
    }
    const routeNodeIds = this.agentRefreshStorageColumnQueueYieldRoute(vehicle);
    const nextNodeId = routeNodeIds?.[1] ?? null;
    if (
      !routeNodeIds ||
      !nextNodeId ||
      routeNodeIds.includes(blocker.currentNodeId) ||
      !this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) ||
      this.agentRefreshMoveBlocker(vehicle, nextNodeId, routeNodeIds)
    ) {
      return null;
    }
    return {
      vehicle,
      blocker,
      routeNodeIds,
      score: this.routeDistanceM(routeNodeIds) + 0.25
    };
  }

  private agentRefreshLoadedStorageSwapLegalHoldPrefix(vehicle: MutableVehicle, routeNodeIds: string[]): string[] | null {
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      const nodeId = routeNodeIds[index]!;
      const node = this.layoutNode(nodeId);
      if (!node || node.noStop || node.noParking || !this.isStorageNode(nodeId)) {
        continue;
      }
      if (!this.agentRefreshYieldPocketAllowed(vehicle, nodeId)) {
        continue;
      }
      const prefix = routeNodeIds.slice(0, index + 1);
      if (
        prefix.length > 1 &&
        this.routeHasOnlyAdjacentEdges(prefix) &&
        this.agentRefreshLocalRouteNodesClear(vehicle, prefix)
      ) {
        return prefix;
      }
    }
    return null;
  }

  private agentRefreshTemporaryStorageBlockedNodeIds(vehicle: MutableVehicle): Set<string> {
    return new Set(
      this.scenario.layout.nodes
        .filter((node) => node.type === 'storage')
        .map((node) => node.id)
        .filter((nodeId) => !this.agentRefreshTemporaryStorageNodeAllowed(vehicle, nodeId))
    );
  }

  private topLiftColumnAccessColumn(nodeId: string): number | null {
    const match = /^column-(?:top-a|top-b|middle|bottom-a|bottom-b)-c(\d+)$/.exec(nodeId);
    return match ? Number(match[1]) : null;
  }

  private routeHasOnlyAdjacentEdges(routeNodeIds: string[]): boolean {
    for (let index = 1; index < routeNodeIds.length; index += 1) {
      if (!this.traffic.findEdge(routeNodeIds[index - 1]!, routeNodeIds[index]!)) {
        return false;
      }
    }
    return true;
  }

  private routeHasRepeatedNode(routeNodeIds: string[]): boolean {
    return new Set(routeNodeIds).size !== routeNodeIds.length;
  }

  private agentRefreshTemporaryStorageNodeAllowed(vehicle: MutableVehicle, nodeId: string): boolean {
    const occupantId = this.currentNodeOccupancy.get(nodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return false;
    }
    if (this.nodeClaimedByOtherVehicle(nodeId, vehicle.id)) {
      return false;
    }
    if (this.storedLoadIdAtNode(nodeId)) {
      return false;
    }
    if (
      this.topLiftColumnLayoutEnabled() &&
      !vehicle.loaded &&
      (
        this.topLiftStorageNodeInActiveInboundPath(nodeId) ||
        this.topLiftStorageNodeInOtherActiveOutboundPickupPath(nodeId, vehicle.id)
      )
    ) {
      return false;
    }
    const task = this.taskForVehicle(vehicle);
    const activeInboundDropoffs = this.activeInboundDropoffNodeIds();
    return !activeInboundDropoffs.has(nodeId) || (vehicle.loaded && task?.dropoffNodeId === nodeId);
  }

  private topLiftStorageNodeInOtherActiveOutboundPickupPath(nodeId: string, vehicleId: string): boolean {
    for (const other of this.vehicles) {
      if (other.id === vehicleId || other.loaded) {
        continue;
      }
      if (!this.vehicleFutureClaimsEnabled(other)) {
        continue;
      }
      const task = this.taskForVehicle(other);
      if (
        task?.kind !== 'outbound' ||
        task.vehicleId !== other.id ||
        task.completedAtSec !== null ||
        !this.isStorageNode(task.pickupNodeId)
      ) {
        continue;
      }
      const routeNodeIds = [
        ...this.vehicleRouteTail(other, other.routeNodeIds),
        ...this.vehicleRouteTail(other, other.plannedRouteNodeIds),
        ...this.vehicleRouteTail(other, other.localRouteNodeIds)
      ];
      const nodeIndex = routeNodeIds.indexOf(nodeId);
      const pickupIndex = routeNodeIds.indexOf(task.pickupNodeId);
      if (nodeIndex >= 0 && (pickupIndex < 0 || nodeIndex <= pickupIndex)) {
        return true;
      }
    }
    return false;
  }

  private topLiftStorageNodeInActiveInboundPath(nodeId: string): boolean {
    const position = this.storageGridPosition(nodeId);
    if (!position) {
      return false;
    }
    for (const task of this.activeTasks()) {
      if (task.kind !== 'inbound') {
        continue;
      }
      const dropoffPosition = this.storageGridPosition(task.dropoffNodeId);
      if (
        dropoffPosition &&
        dropoffPosition.column === position.column &&
        position.row <= dropoffPosition.row
      ) {
        return true;
      }
    }
    return false;
  }

  private agentRefreshLoadedStorageSwapAisleEscapeNodeId(sideNodeId: string, vehicle: MutableVehicle, blocker: MutableVehicle): string | null {
    const sideMatch = /^(left|right)-row-(\d+)$/.exec(sideNodeId);
    if (!sideMatch) {
      return null;
    }
    const side = sideMatch[1] as 'left' | 'right';
    const row = Number(sideMatch[2]);
    const blockerTask = this.taskForVehicle(blocker);
    const blockerGoalNodeId = this.agentGoalNodeId(blocker, blockerTask);
    const blockerGoalRow = blockerGoalNodeId ? this.storageGridPosition(blockerGoalNodeId)?.row ?? null : null;
    const preferredDirection = blockerGoalRow !== null && blockerGoalRow !== row
      ? -Math.sign(blockerGoalRow - row)
      : -1;
    const directions = [preferredDirection, -preferredDirection].filter((direction, index, self) =>
      direction !== 0 && self.indexOf(direction) === index
    );

    for (const direction of directions) {
      const candidateNodeId = `${side}-row-${String(row + direction).padStart(2, '0')}`;
      if (
        this.layoutNode(candidateNodeId) &&
        this.traffic.findEdge(sideNodeId, candidateNodeId) &&
        !this.currentNodeOccupancy.has(candidateNodeId) &&
        !this.nodeClaimedByOtherVehicle(candidateNodeId, vehicle.id)
      ) {
        return candidateNodeId;
      }
    }
    return null;
  }

  private installAgentRefreshLoadedStorageSwapClearance(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    routeNodeIds: string[]
  ): void {
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = routeNodeIds[1] ?? null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'loaded-storage-swap-clearance';
    this.logAgentReroute(vehicle, this.taskForVehicle(vehicle), blocker.currentNodeId, routeNodeIds, 'agent-refresh-loaded-storage-swap-clearance', { countTaskReplan: false });
  }

  private agentRefreshForwardYieldPocketNodeId(
    vehicle: MutableVehicle,
    currentNodeId: string,
    forwardNodeId: string,
    blocker: MutableVehicle | null = null
  ): string | null {
    const occupantId = this.currentNodeOccupancy.get(forwardNodeId);
    if (occupantId && occupantId !== vehicle.id) {
      return null;
    }
    if (
      this.nodeClaimedByOtherVehicle(forwardNodeId, vehicle.id) ||
      this.movingVehicleTargetingNode(forwardNodeId, vehicle.id) ||
      this.movingVehicleClearingNode(forwardNodeId, vehicle)
    ) {
      return null;
    }

    const pocketNodeId = this.agentRefreshYieldPocketNodeId(vehicle, forwardNodeId, currentNodeId, blocker);
    if (!pocketNodeId) {
      return null;
    }
    if (
      this.movingVehicleTargetingNode(pocketNodeId, vehicle.id) ||
      this.movingVehicleClearingNode(pocketNodeId, vehicle)
    ) {
      return null;
    }
    if (!this.agentRefreshForwardYieldPocketAllowed(vehicle, currentNodeId, pocketNodeId)) {
      return null;
    }
    if (blocker && !this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, pocketNodeId, blocker)) {
      return null;
    }
    if (blocker && this.agentRefreshForwardPocketWouldPassBlocker(currentNodeId, forwardNodeId, blocker)) {
      if (vehicle.loaded) {
        return null;
      }
      const currentPocketNodeId = this.agentRefreshYieldPocketNodeId(vehicle, currentNodeId, forwardNodeId, blocker);
      if (currentPocketNodeId) {
        return null;
      }
    }

    const current = nodePosition(this.scenario, currentNodeId);
    const forward = nodePosition(this.scenario, forwardNodeId);
    const distanceToCurrentM = Math.hypot(vehicle.x - current.x, vehicle.z - current.z);
    const distanceToForwardM = Math.hypot(vehicle.x - forward.x, vehicle.z - forward.z);
    const nearForwardThresholdM = Math.max(
      this.scenario.trafficPolicy.dynamicAvoidanceClearanceM + this.scenario.vehicles.lengthM,
      1.8
    );
    const forwardIsTransfer = this.liftStorageTransferTargetLiftId(forwardNodeId) !== null;
    const alreadyCommittedForward = distanceToForwardM <= distanceToCurrentM + 0.25;
    const nearEnoughToTurnIn = distanceToForwardM <= nearForwardThresholdM;
    if (!forwardIsTransfer && !alreadyCommittedForward && !nearEnoughToTurnIn) {
      return null;
    }

    return pocketNodeId;
  }

  private agentRefreshForwardPocketWouldPassBlocker(
    currentNodeId: string,
    forwardNodeId: string,
    blocker: MutableVehicle
  ): boolean {
    const current = nodePosition(this.scenario, currentNodeId);
    const forward = nodePosition(this.scenario, forwardNodeId);
    const sameVerticalLine = Math.abs(current.x - forward.x) <= 1e-6 &&
      Math.abs(blocker.x - current.x) <= this.scenario.vehicles.widthM;
    if (sameVerticalLine) {
      const minZ = Math.min(current.z, forward.z);
      const maxZ = Math.max(current.z, forward.z);
      return blocker.z > minZ + 0.05 && blocker.z < maxZ - 0.05;
    }
    const sameHorizontalLine = Math.abs(current.z - forward.z) <= 1e-6 &&
      Math.abs(blocker.z - current.z) <= this.scenario.vehicles.widthM;
    if (sameHorizontalLine) {
      const minX = Math.min(current.x, forward.x);
      const maxX = Math.max(current.x, forward.x);
      return blocker.x > minX + 0.05 && blocker.x < maxX - 0.05;
    }
    return false;
  }

  private agentRefreshForwardYieldPocketAllowed(
    vehicle: MutableVehicle,
    currentNodeId: string,
    pocketNodeId: string
  ): boolean {
    const task = this.taskForVehicle(vehicle);
    if (
      !vehicle.loaded ||
      !task ||
      task.kind !== 'inbound' ||
      this.layoutNode(currentNodeId)?.type !== 'lift-blackbox' ||
      !this.isStorageNode(pocketNodeId)
    ) {
      return true;
    }
    if (this.topLiftColumnLayoutEnabled()) {
      const pocketColumnKey = this.topLiftColumnKey(pocketNodeId);
      const dropoffColumnKey = this.topLiftColumnKey(task.dropoffNodeId);
      return pocketColumnKey !== null && pocketColumnKey === dropoffColumnKey;
    }
    return this.nodeStorageRowLabel(pocketNodeId) === this.nodeStorageRowLabel(task.dropoffNodeId);
  }

  private tryBreakAgentRefreshWaitCycle(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidates = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.currentEdgeId === null &&
        vehicle.legRemainingM <= 0 &&
        vehicle.targetNodeId !== null &&
        vehicle.blockingVehicleId !== null
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) ?? null;
      if (!blocker) {
        continue;
      }
      const session = this.activeConflictSessionForPair(vehicle.id, blocker.id);
      if (this.tryYieldEmptyMiddleAccessAwayFromWaitCycle(vehicle, blocker, vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldEmptyMiddleAccessAwayFromWaitCycle(blocker, vehicle, blocker.targetNodeId ?? vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldEmptyBottomASpineAwayFromMiddleAccessCycle(vehicle, blocker, vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldEmptyBottomASpineAwayFromMiddleAccessCycle(blocker, vehicle, blocker.targetNodeId ?? vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldLoadedInboundMiddleSpineAwayFromStorageExitCycle(blocker, vehicle, vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldLoadedInboundMiddleSpineAwayFromStorageExitCycle(vehicle, blocker, blocker.targetNodeId ?? vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldEmptyStorageEntryAwayFromLoadedInbound(vehicle, blocker, vehicle.targetNodeId!)) {
        return true;
      }
      if (this.tryYieldEmptyStorageEntryAwayFromLoadedInbound(blocker, vehicle, blocker.targetNodeId ?? vehicle.targetNodeId!)) {
        return true;
      }
      if (this.agentRefreshWinnerShouldStayCourse(session, vehicle, blocker)) {
        continue;
      }
      if (vehicle.loaded) {
        if (this.tryYieldLoadedMiddleAccessAwayFromNoStopCycle(vehicle, blocker, vehicle.targetNodeId!)) {
          return true;
        }
        continue;
      }
      if (this.tryYieldEmptyBottomASpineAwayFromNoStopCycle(vehicle, blocker, session)) {
        return true;
      }
      if (this.agentRefreshInstallSideYield(vehicle, vehicle.targetNodeId!, blocker, session)) {
        return true;
      }
    }
    return false;
  }

  private tryYieldEmptyBottomASpineAwayFromNoStopCycle(
    vehicle: MutableVehicle,
    blocker: MutableVehicle,
    session: ConflictSessionV1 | null
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.waitReason !== 'no-stop-continuation-blocked' ||
      !vehicle.targetNodeId ||
      !isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
      !isTopLiftSpineLevelNodeId(vehicle.targetNodeId, 'middle') ||
      !this.topLiftNoStopBottomASpineRequesterHasPriority(vehicle, blocker) ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.waitReason !== 'no-stop-continuation-blocked' ||
      blocker.blockingVehicleId !== vehicle.id ||
      blocker.targetNodeId !== vehicle.targetNodeId
    ) {
      return false;
    }

    const forbiddenNodeIds = new Set(
      [
        vehicle.targetNodeId,
        blocker.currentNodeId,
        blocker.targetNodeId,
        ...this.agentRefreshRequesterProtectedRouteNodeIds(blocker),
        ...this.agentRefreshLoadedRequesterProtectedRouteNodeIds(blocker)
      ].filter((nodeId): nodeId is string => Boolean(nodeId))
    );
    const candidates = this.neighbors(vehicle.currentNodeId)
      .filter((neighbor) => isTopLiftAisleLevelNodeId(neighbor.nodeId, 'bottom-a'))
      .filter((neighbor) => !forbiddenNodeIds.has(neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, neighbor.nodeId, blocker))
      .filter((neighbor) => this.agentRefreshLocalRouteNodesClear(vehicle, [vehicle.currentNodeId, neighbor.nodeId]))
      .sort((left, right) =>
        Math.abs((this.layoutNode(left.nodeId)?.x ?? 0) - (this.layoutNode(blocker.currentNodeId)?.x ?? 0)) -
        Math.abs((this.layoutNode(right.nodeId)?.x ?? 0) - (this.layoutNode(blocker.currentNodeId)?.x ?? 0)) ||
        left.nodeId.localeCompare(right.nodeId)
      );

    for (const candidate of candidates) {
      const route = [vehicle.currentNodeId, candidate.nodeId];
      const holdRoute =
        this.extendTopLiftTemporaryYieldRouteToHold(vehicle, route, forbiddenNodeIds) ??
        (
          this.topLiftNoStopBottomASpineCycleLateralHoldAllowed(vehicle, candidate.nodeId, blocker, forbiddenNodeIds)
            ? route
            : null
        );
      if (
        !holdRoute ||
        holdRoute.length < 2 ||
        !this.routeEdgesExist(holdRoute) ||
        !this.agentRefreshSideYieldRouteCompatibleWithRequester(vehicle, holdRoute, blocker, vehicle.targetNodeId) ||
        !this.agentRefreshLocalRouteNodesClear(vehicle, holdRoute)
      ) {
        continue;
      }
      return this.installAgentRefreshSideYieldRoute(vehicle, blocker, vehicle.targetNodeId, holdRoute, session);
    }

    return false;
  }

  private topLiftNoStopBottomASpineCycleLateralHoldAllowed(
    vehicle: MutableVehicle,
    candidateNodeId: string,
    blocker: MutableVehicle,
    forbiddenNodeIds: Set<string>
  ): boolean {
    if (
      !this.topLiftColumnLayoutEnabled() ||
      vehicle.loaded ||
      vehicle.currentEdgeId !== null ||
      vehicle.legRemainingM > 0 ||
      vehicle.phaseRemainingSec > 0 ||
      vehicle.waitReason !== 'no-stop-continuation-blocked' ||
      !isTopLiftSpineLevelNodeId(vehicle.currentNodeId, 'bottom-a') ||
      !isTopLiftSpineLevelNodeId(vehicle.targetNodeId ?? '', 'middle') ||
      !this.topLiftNoStopBottomASpineRequesterHasPriority(vehicle, blocker) ||
      blocker.currentEdgeId !== null ||
      blocker.legRemainingM > 0 ||
      blocker.waitReason !== 'no-stop-continuation-blocked' ||
      blocker.blockingVehicleId !== vehicle.id ||
      blocker.targetNodeId !== vehicle.targetNodeId ||
      forbiddenNodeIds.has(candidateNodeId) ||
      !isTopLiftAisleLevelNodeId(candidateNodeId, 'bottom-a') ||
      !this.topLiftColumnSpineOrAccessNode(candidateNodeId) ||
      !this.traffic.findEdge(vehicle.currentNodeId, candidateNodeId)
    ) {
      return false;
    }

    const routeNodeIds = [vehicle.currentNodeId, candidateNodeId];
    const occupantId = this.currentNodeOccupancy.get(candidateNodeId);
    return (
      (!occupantId || occupantId === vehicle.id) &&
      !this.nodeClaimedByOtherVehicle(candidateNodeId, vehicle.id) &&
      this.agentRefreshYieldPocketAllowed(vehicle, candidateNodeId) &&
      this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, candidateNodeId, blocker) &&
      this.agentMinimalYieldFirstLegSafe(vehicle, vehicle.currentNodeId, candidateNodeId) &&
      this.agentRefreshLocalRouteNodesClear(vehicle, routeNodeIds) &&
      !this.topLiftTemporaryYieldRouteConflictsWithLoadedVerticalSpine(vehicle, routeNodeIds) &&
      !this.agentRefreshMoveBlocker(vehicle, candidateNodeId, routeNodeIds)
    );
  }

  private topLiftNoStopBottomASpineRequesterHasPriority(
    yielder: MutableVehicle,
    requester: MutableVehicle
  ): boolean {
    if (requester.loaded) {
      return true;
    }
    return (
      !requester.loaded &&
      !yielder.loaded &&
      yielder.waitReason === 'no-stop-continuation-blocked' &&
      requester.waitReason === 'no-stop-continuation-blocked' &&
      requester.blockingVehicleId === yielder.id &&
      requester.targetNodeId === yielder.targetNodeId &&
      isTopLiftSpineLevelNodeId(yielder.currentNodeId, 'bottom-a') &&
      isTopLiftSpineLevelNodeId(yielder.targetNodeId ?? '', 'middle') &&
      isTopLiftAisleLevelNodeId(requester.currentNodeId, 'middle') &&
      isTopLiftSpineLevelNodeId(requester.targetNodeId ?? '', 'middle') &&
      this.vehicleRouteTail(requester, requester.routeNodeIds).includes(yielder.currentNodeId) &&
      this.vehicleRouteTail(yielder, yielder.routeNodeIds).includes(requester.currentNodeId)
    );
  }

  private startAgentRefreshForwardPocketYield(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    currentNodeId: string,
    forwardNodeId: string,
    pocketNodeId: string
  ): void {
    const from = nodePosition(this.scenario, currentNodeId);
    const edgeLengthM = Math.max(0.001, edge.lengthM);
    const distanceFromCurrentM = Math.min(
      edgeLengthM,
      Math.max(0, Math.hypot(vehicle.x - from.x, vehicle.z - from.z))
    );
    const speedMps = Math.max(0.001, this.speedForEdge(vehicle, edge));
    const routeNodeIds = [currentNodeId, forwardNodeId, pocketNodeId];
    vehicle.currentNodeId = currentNodeId;
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = forwardNodeId;
    vehicle.currentEdgeId = edge.id;
    vehicle.legMotionMode = 'cruise';
    vehicle.legTravelSec = round(edgeLengthM / speedMps);
    vehicle.legElapsedSec = round(distanceFromCurrentM / speedMps);
    vehicle.legRemainingM = round(edgeLengthM - distanceFromCurrentM);
    vehicle.targetSpeedMps = speedMps;
    vehicle.legStartYaw = vehicle.yaw;
    vehicle.speedMps = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.yieldHoldUntilSec = null;
    vehicle.yieldHoldNodeId = null;
    vehicle.localRouteNodeIds = routeNodeIds;
    vehicle.localRouteReason = 'temporary-yield';
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    const task = this.taskForVehicle(vehicle);
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, task?.loadId ?? null, currentNodeId, pocketNodeId, 'agent-refresh-forward-pocket-yield', this.vehiclePosition(vehicle), {
      route: routeNodeIds.join('>')
    });
  }

  private agentRefreshYieldPocketNodeId(
    vehicle: MutableVehicle,
    currentNodeId: string,
    blockedNodeId: string | null = vehicle.targetNodeId,
    requester: MutableVehicle | null = null
  ): string | null {
    const candidate = this.neighbors(currentNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedNodeId)
      .filter((neighbor) => this.agentRefreshYieldPocketAllowed(vehicle, neighbor.nodeId))
      .filter((neighbor) => !requester || this.agentRefreshYieldPocketCompatibleWithRequester(vehicle, neighbor.nodeId, requester))
      .filter((neighbor) => this.agentRefreshYieldPocketKeepsGoalReachable(vehicle, neighbor.nodeId))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .sort((left, right) =>
        this.agentRefreshYieldPocketRank(vehicle, left.nodeId) - this.agentRefreshYieldPocketRank(vehicle, right.nodeId) ||
        this.agentRefreshYieldPocketTieBreak(vehicle, left.nodeId) - this.agentRefreshYieldPocketTieBreak(vehicle, right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0];
    return candidate?.nodeId ?? null;
  }

  private agentRefreshYieldPocketKeepsGoalReachable(vehicle: MutableVehicle, pocketNodeId: string): boolean {
    if (!this.topLiftColumnLayoutEnabled()) {
      return true;
    }
    const task = this.taskForVehicle(vehicle);
    if (vehicle.loaded && task?.kind === 'outbound') {
      const goalNodeId = this.taskDispatchGoalNodeId(task, vehicle);
      try {
        return (this.agentRefreshLoadedOutboundRouteToDropoff(pocketNodeId, task, goalNodeId)?.length ?? 0) > 1;
      } catch {
        return false;
      }
    }
    if (!vehicle.loaded || task?.kind !== 'inbound') {
      return true;
    }
    try {
      return this.agentRefreshLoadedInboundRouteToDropoff(pocketNodeId, task).length > 1;
    } catch {
      return false;
    }
  }

  private tryRetreatAgentMinimalLoadedFaceoff(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidates = this.vehicles
      .filter((vehicle) => {
        if (
          !candidateIds.has(vehicle.id) ||
          vehicle.state !== 'waiting-blocked' ||
          vehicle.waitReason !== 'avoidance-clearance' ||
          vehicle.currentEdgeId === null ||
          vehicle.targetNodeId === null ||
          !vehicle.loaded ||
          !vehicle.blockingVehicleId
        ) {
          return false;
        }
        const blocker = this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId);
        return Boolean(
          blocker &&
          blocker.loaded &&
          blocker.state === 'waiting-blocked' &&
          blocker.waitReason === 'avoidance-clearance' &&
          blocker.blockingVehicleId === vehicle.id &&
          blocker.currentEdgeId !== null &&
          blocker.targetNodeId === vehicle.targetNodeId
        );
      })
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const retreatNodeId = vehicle.currentNodeId;
      const fromBlockedNodeId = vehicle.targetNodeId;
      if (!fromBlockedNodeId) {
        continue;
      }
      const retreatNode = this.layoutNode(retreatNodeId);
      if (!retreatNode || (retreatNode.type !== 'lift-blackbox' && retreatNode.type !== 'parking')) {
        continue;
      }
      const edge = this.traffic.findEdge(retreatNodeId, fromBlockedNodeId);
      if (!edge) {
        continue;
      }
      this.startAgentMinimalReverseLeg(
        vehicle,
        edge,
        fromBlockedNodeId,
        retreatNodeId,
        [fromBlockedNodeId, retreatNodeId],
        'loaded-retreats-from-faceoff',
        5
      );
      return true;
    }
    return false;
  }

  private tryRetreatAgentMinimalEdgeBlocker(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidates = this.vehicles
      .filter((vehicle) =>
        candidateIds.has(vehicle.id) &&
        vehicle.state === 'waiting-blocked' &&
        vehicle.waitReason === 'avoidance-clearance' &&
        vehicle.currentEdgeId !== null &&
        vehicle.targetNodeId !== null &&
        !vehicle.loaded
      )
      .sort((left, right) =>
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );

    for (const vehicle of candidates) {
      const retreatNodeId = vehicle.currentNodeId;
      const fromBlockedNodeId = vehicle.targetNodeId;
      if (!fromBlockedNodeId) {
        continue;
      }
      const edge = this.traffic.findEdge(retreatNodeId, fromBlockedNodeId);
      if (!edge) {
        continue;
      }
      const blocker = vehicle.blockingVehicleId ? this.vehicles.find((candidate) => candidate.id === vehicle.blockingVehicleId) : null;
      if (blocker && !blocker.loaded) {
        continue;
      }
      const occupantId = this.currentNodeOccupancy.get(retreatNodeId);
      if (occupantId && occupantId !== vehicle.id) {
        continue;
      }
      const continuationNodeId = this.agentMinimalYieldPocketNodeId(vehicle, retreatNodeId, fromBlockedNodeId);
      if (!continuationNodeId) {
        continue;
      }

      this.startAgentMinimalReverseLeg(
        vehicle,
        edge,
        fromBlockedNodeId,
        retreatNodeId,
        [fromBlockedNodeId, retreatNodeId, continuationNodeId],
        'empty-retreats-to-local-yield'
      );
      return true;
    }
    return false;
  }

  private startAgentMinimalReverseLeg(
    vehicle: MutableVehicle,
    edge: ShuttleScenario['layout']['edges'][number],
    fromBlockedNodeId: string,
    retreatNodeId: string,
    routeNodeIds: string[],
    reason: string,
    holdAfterArrivalSec = 0
  ): void {
    const reverseFrom = nodePosition(this.scenario, fromBlockedNodeId);
    const edgeLengthM = Math.max(0.001, edge.lengthM);
    const distanceFromReverseStartM = Math.min(
      edgeLengthM,
      Math.max(0, Math.hypot(vehicle.x - reverseFrom.x, vehicle.z - reverseFrom.z))
    );
    const speedMps = Math.max(0.001, this.speedForEdge(vehicle, edge));
    const remainingReverseTravelSec = (edgeLengthM - distanceFromReverseStartM) / speedMps;
    vehicle.currentNodeId = fromBlockedNodeId;
    if ((this.currentNodeOccupancy.get(fromBlockedNodeId) ?? vehicle.id) === vehicle.id) {
      this.occupyNode(vehicle, fromBlockedNodeId);
    }
    vehicle.routeNodeIds = routeNodeIds;
    vehicle.routeIndex = 0;
    vehicle.targetNodeId = retreatNodeId;
    vehicle.currentEdgeId = edge.id;
    vehicle.legMotionMode = 'cruise';
    vehicle.legTravelSec = round(edgeLengthM / speedMps);
    vehicle.legElapsedSec = round(distanceFromReverseStartM / speedMps);
    vehicle.legRemainingM = round(edgeLengthM - distanceFromReverseStartM);
    vehicle.targetSpeedMps = speedMps;
    vehicle.legStartYaw = vehicle.yaw;
    vehicle.speedMps = 0;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.localRouteNodeIds = [];
    vehicle.localRouteReason = null;
    vehicle.yieldHoldUntilSec = holdAfterArrivalSec > 0
      ? round(this.simTimeSec + remainingReverseTravelSec + holdAfterArrivalSec)
      : null;
    vehicle.yieldHoldNodeId = holdAfterArrivalSec > 0 ? retreatNodeId : null;
    vehicle.state = vehicle.loaded ? 'loaded-moving' : vehicle.taskId ? 'moving-to-pickup' : 'returning';
    const task = this.taskForVehicle(vehicle);
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, task?.loadId ?? null, fromBlockedNodeId, routeNodeIds.at(-1) ?? retreatNodeId, reason, this.vehiclePosition(vehicle), {
      route: vehicle.routeNodeIds.join('>')
    });
  }

  private tryBreakAgentMinimalWaitCycle(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    const candidates = this.vehicles
      .filter((vehicle) => candidateIds.has(vehicle.id) && vehicle.state === 'waiting-blocked')
      .sort((left, right) =>
        Number(left.loaded) - Number(right.loaded) ||
        this.agentTurnPriority(left) - this.agentTurnPriority(right) ||
        right.id.localeCompare(left.id)
      );
    for (const vehicle of candidates) {
      if (this.insertPortalYieldPocket(vehicle)) {
        return true;
      }
    }
    return false;
  }

  private tryBreakPortalHoldCycle(candidateVehicleIds: string[]): boolean {
    const candidateIds = new Set(candidateVehicleIds);
    for (const vehicle of this.vehicles.filter((candidate) => candidateIds.has(candidate.id) && candidate.state === 'waiting-blocked')) {
      const reservation = this.blockingZoneHoldReservation(vehicle);
      if (!reservation) {
        continue;
      }
      const holder = this.vehicles.find((candidate) => candidate.id === reservation.vehicleId);
      if (!holder || !candidateIds.has(holder.id) || holder.state !== 'waiting-blocked') {
        continue;
      }
      const holderReservation = this.blockingZoneHoldReservation(holder);
      if (!holderReservation || holderReservation.vehicleId !== vehicle.id) {
        continue;
      }
      const yieldVehicle = vehicle.id.localeCompare(holder.id) > 0 ? vehicle : holder;
      if (this.insertPortalYieldPocket(yieldVehicle)) {
        return true;
      }
    }
    return false;
  }

  private blockingZoneHoldReservation(vehicle: MutableVehicle): Reservation | null {
    if (!vehicle.blockingReservationId) {
      return null;
    }
    const reservation = this.reservations.find((candidate) => candidate.id === vehicle.blockingReservationId) ?? null;
    return reservation?.reasonCode === 'zone-hold' ? reservation : null;
  }

  private agentMinimalYieldPocketNodeId(
    vehicle: MutableVehicle,
    currentNodeId: string,
    blockedNodeId: string | null = vehicle.targetNodeId
  ): string | null {
    const currentZones = new Set(this.zonesForNode(currentNodeId).map((zone) => zone.id));
    const candidate = this.neighbors(currentNodeId)
      .filter((neighbor) => neighbor.nodeId !== blockedNodeId)
      .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
      .filter((neighbor) => {
        const node = this.scenario.layout.nodes.find((candidate) => candidate.id === neighbor.nodeId);
        return node?.type !== 'lift-blackbox';
      })
      .filter((neighbor) => !this.liftStorageTransferTargetLiftId(neighbor.nodeId))
      .filter((neighbor) => this.zonesForNode(neighbor.nodeId).every((zone) => !currentZones.has(zone.id)))
      .filter((neighbor) => !(vehicle.loaded && this.layoutNode(neighbor.nodeId)?.type === 'storage'))
      .filter((neighbor) => this.agentMinimalYieldFirstLegSafe(vehicle, currentNodeId, neighbor.nodeId))
      .sort((left, right) =>
        this.yieldPocketRank(vehicle, left.nodeId) - this.yieldPocketRank(vehicle, right.nodeId) ||
        left.lengthM - right.lengthM ||
        left.nodeId.localeCompare(right.nodeId)
      )[0];
    return candidate?.nodeId ?? null;
  }

  private agentMinimalYieldFirstLegSafe(vehicle: MutableVehicle, fromNodeId: string, toNodeId: string): boolean {
    const from = nodePosition(this.scenario, fromNodeId);
    const to = nodePosition(this.scenario, toNodeId);
    return this.predictedSweptFootprintOverlapVehicleId(vehicle, from.x, from.z, to.x, to.z) === null;
  }

  private insertPortalYieldPocket(vehicle: MutableVehicle): boolean {
    if (this.agentMinimalEnabled() && (vehicle.currentEdgeId !== null || vehicle.legRemainingM > 0)) {
      return false;
    }
    const currentNodeId = vehicle.currentNodeId;
    const candidateNodeId = this.agentMinimalEnabled()
      ? this.agentMinimalYieldPocketNodeId(vehicle, currentNodeId)
      : null;
    const candidate = candidateNodeId
      ? this.neighbors(currentNodeId).find((neighbor) => neighbor.nodeId === candidateNodeId) ?? null
      : this.neighbors(currentNodeId)
          .filter((neighbor) => neighbor.nodeId !== vehicle.targetNodeId)
          .filter((neighbor) => !this.currentNodeOccupancy.has(neighbor.nodeId))
          .filter((neighbor) => {
            const node = this.scenario.layout.nodes.find((candidateNode) => candidateNode.id === neighbor.nodeId);
            return node?.type !== 'lift-blackbox';
          })
          .filter((neighbor) => !this.liftStorageTransferTargetLiftId(neighbor.nodeId))
          .filter((neighbor) => this.zonesForNode(neighbor.nodeId).every((zone) => !this.zonesForNode(currentNodeId).some((currentZone) => currentZone.id === zone.id)))
          .filter((neighbor) => !(vehicle.loaded && this.layoutNode(neighbor.nodeId)?.type === 'storage'))
          .sort((left, right) =>
            this.yieldPocketRank(vehicle, left.nodeId) - this.yieldPocketRank(vehicle, right.nodeId) ||
            left.lengthM - right.lengthM ||
            left.nodeId.localeCompare(right.nodeId)
          )[0] ?? null;
    if (!candidate || !this.traffic.findEdge(candidate.nodeId, currentNodeId)) {
      return false;
    }

    const route = this.agentMinimalEnabled()
      ? [currentNodeId, candidate.nodeId]
      : [
          ...vehicle.routeNodeIds.slice(0, vehicle.routeIndex + 1),
          candidate.nodeId,
          currentNodeId,
          ...vehicle.routeNodeIds.slice(vehicle.routeIndex + 1)
        ];
    vehicle.routeNodeIds = route;
    if (this.agentMinimalEnabled()) {
      vehicle.routeIndex = 0;
      vehicle.yieldHoldUntilSec = round(this.simTimeSec + 5);
      vehicle.yieldHoldNodeId = null;
    }
    vehicle.targetNodeId = route[vehicle.routeIndex + 1] ?? null;
    vehicle.waitReason = null;
    vehicle.blockingReservationId = null;
    vehicle.blockingVehicleId = null;
    vehicle.waitingSinceSec = null;
    vehicle.state = 'assigned';
    const task = this.taskById(vehicle.taskId);
    if (task && !this.agentMinimalEnabled()) {
      task.replanCount += 1;
    }
    this.replanCount += 1;
    const reason = this.agentMinimalEnabled() ? 'local-yield-pocket' : 'portal-hold-yield-pocket';
    this.logEvent('route-replanned', vehicle.id, vehicle.taskId, null, currentNodeId, vehicle.targetNodeId, reason, this.vehiclePosition(vehicle), {
      route: route.join('>')
    });
    return true;
  }

  private blockingVehicleForReservation(reservationId: string | null): string | null {
    if (!reservationId) {
      return null;
    }
    return this.reservations.find((reservation) => reservation.id === reservationId)?.vehicleId ?? null;
  }

  private liftPortNodes(): Array<{ nodeId: string; kind: 'inbound' | 'outbound' }> {
    return this.scenario.layout.nodes
      .map((node) => ({ nodeId: node.id, kind: liftKindForNode(node) }))
      .filter((port): port is { nodeId: string; kind: LiftKind } => port.kind !== null)
      .sort((left, right) => left.nodeId.localeCompare(right.nodeId));
  }

  private updateLiftPortUtilization(dtSec: number): void {
    for (const port of this.liftPortNodes()) {
      if (this.isLiftPortCycleActive(port.kind, port.nodeId)) {
        this.liftPortBusyTimeSec.set(port.nodeId, round((this.liftPortBusyTimeSec.get(port.nodeId) ?? 0) + dtSec));
      }
    }
  }

  private recordLiftPortCompletion(task: TaskStateRecord): void {
    const liftNodeId = this.taskLiftPortNodeId(task);
    if (!liftNodeId) {
      return;
    }
    const previous = this.completedByLiftPort.get(liftNodeId);
    this.completedByLiftPort.set(liftNodeId, {
      kind: task.kind,
      completed: (previous?.completed ?? 0) + 1
    });
  }

  private liftPortPphByNodeId(): Record<string, { kind: LiftKind; completed: number; pph: number }> {
    const elapsedHours = Math.max(this.simTimeSec / 3600, 1e-9);
    return Object.fromEntries(this.liftPortNodes().map((port) => {
      const completion = this.completedByLiftPort.get(port.nodeId);
      const completed = completion?.completed ?? 0;
      return [port.nodeId, {
        kind: port.kind,
        completed,
        pph: round(completed / elapsedHours, 3)
      }];
    }));
  }

  private liftPortDiagnostics(): ShuttleSimState['traffic']['liftPorts'] {
    const liftPphByNodeId = this.liftPortPphByNodeId();
    return this.liftPortNodes().map((port) => {
      const liftPph = liftPphByNodeId[port.nodeId] ?? { kind: port.kind, completed: 0, pph: 0 };
      const waitingTaskIds = this.queuedTasks()
        .filter((task) => task.kind === port.kind && this.taskLiftPortNodeId(task) === port.nodeId)
        .map((task) => task.id)
        .sort();
      const activeVehicle = this.vehicles
        .filter((vehicle) =>
          ((port.kind === 'inbound' && vehicle.state === 'lifting') || (port.kind === 'outbound' && vehicle.state === 'lowering')) &&
          this.vehicleTaskLiftPortNodeId(vehicle) === port.nodeId
        )
        .sort((left, right) => left.id.localeCompare(right.id))[0];
      return {
        nodeId: port.nodeId,
        kind: port.kind,
        queueLength: waitingTaskIds.length,
        waitingTaskIds,
        activeTaskId: activeVehicle?.taskId ?? null,
        approachOccupancy: this.liftPortApproachCount(port.kind, port.nodeId),
        approachCapacity: this.liftPortApproachCapacity(),
        sourceBufferOccupancy: port.kind === 'inbound' ? this.inboundLiftWaitingSourceLoads(port.nodeId).length : 0,
        sourceBufferCapacity: port.kind === 'inbound' ? this.inboundSourceBufferCapacity(port.nodeId) : 1,
        completedTasks: liftPph.completed,
        pph: liftPph.pph,
        utilization: round((this.liftPortBusyTimeSec.get(port.nodeId) ?? 0) / Math.max(this.simTimeSec, 1), 4)
      };
    });
  }

  private vehiclePosition(vehicle: MutableVehicle): { x: number; y: number; z: number } {
    return { x: vehicle.x, y: vehicle.y, z: vehicle.z };
  }

  private vehicleRouteDiagnostics(vehicle: MutableVehicle): Pick<VehicleState, 'plannedGoalNodeId' | 'plannedRouteNodeIds' | 'localRouteNodeIds' | 'localRouteReason'> {
    const activeRoute = vehicle.routeNodeIds.slice(Math.max(0, vehicle.routeIndex));
    if (!this.agentSimpleEnabled()) {
      return {
        plannedGoalNodeId: activeRoute.at(-1) ?? null,
        plannedRouteNodeIds: activeRoute,
        localRouteNodeIds: [],
        localRouteReason: null
      };
    }

    const task = this.taskForVehicle(vehicle);
    const goalNodeId = this.agentGoalNodeId(vehicle, task);
    if (
      vehicle.localRouteReason === 'inbound-queue-standby' &&
      vehicle.plannedGoalNodeId === vehicle.currentNodeId &&
      this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId)
    ) {
      return {
        plannedGoalNodeId: vehicle.currentNodeId,
        plannedRouteNodeIds: [vehicle.currentNodeId],
        localRouteNodeIds: [],
        localRouteReason: vehicle.localRouteReason
      };
    }
    if (!goalNodeId || (goalNodeId === vehicle.currentNodeId && vehicle.currentEdgeId === null && activeRoute.length < 2)) {
      return {
        plannedGoalNodeId: goalNodeId,
        plannedRouteNodeIds: goalNodeId ? [vehicle.currentNodeId] : [],
        localRouteNodeIds: [],
        localRouteReason: null
      };
    }

    if (this.agentRefreshEnabled()) {
      const plannedFromState = vehicle.plannedGoalNodeId === goalNodeId && vehicle.plannedRouteNodeIds.length >= 1
        ? vehicle.plannedRouteNodeIds
        : [];
      let plannedRouteNodeIds = this.remainingRefreshPlannedRoute(vehicle, plannedFromState);
      if (plannedRouteNodeIds.length < 2 && vehicle.currentNodeId !== goalNodeId) {
        try {
          plannedRouteNodeIds = this.agentRefreshNominalRouteToGoal(vehicle, task, goalNodeId);
        } catch {
          plannedRouteNodeIds = activeRoute.length >= 2 ? activeRoute : [vehicle.currentNodeId];
        }
      }
      const activeRouteDiffers = activeRoute.length >= 2 && activeRoute.join('>') !== plannedRouteNodeIds.join('>');
      const localRouteIndex = vehicle.localRouteNodeIds.indexOf(vehicle.currentNodeId);
      const explicitLocalRouteNodeIds = localRouteIndex >= 0
        ? vehicle.localRouteNodeIds.slice(localRouteIndex)
        : [];
      const localRouteNodeIds = explicitLocalRouteNodeIds.length >= 2 ? explicitLocalRouteNodeIds : [];
      const localRouteTerminalNodeId = localRouteNodeIds.at(-1) ?? null;
      if (
        vehicle.localRouteReason === 'outbound-lift-clearance' &&
        vehicle.plannedGoalNodeId &&
        vehicle.plannedRouteNodeIds.length >= 1
      ) {
        const outboundClearanceRouteNodeIds = this.remainingRefreshPlannedRoute(vehicle, vehicle.plannedRouteNodeIds);
        return {
          plannedGoalNodeId: vehicle.plannedGoalNodeId,
          plannedRouteNodeIds: outboundClearanceRouteNodeIds.length >= 1 ? outboundClearanceRouteNodeIds : activeRoute,
          localRouteNodeIds,
          localRouteReason: vehicle.localRouteReason
        };
      }
      if (
        vehicle.localRouteReason === 'inbound-queue-standby' &&
        vehicle.plannedGoalNodeId === goalNodeId &&
        plannedRouteNodeIds.length >= 2
      ) {
        return {
          plannedGoalNodeId: goalNodeId,
          plannedRouteNodeIds,
          localRouteNodeIds,
          localRouteReason: vehicle.localRouteReason
        };
      }
      if (localRouteTerminalNodeId && localRouteTerminalNodeId !== goalNodeId) {
        return {
          plannedGoalNodeId: localRouteTerminalNodeId,
          plannedRouteNodeIds: localRouteNodeIds,
          localRouteNodeIds,
          localRouteReason: vehicle.localRouteReason ?? 'temporary-yield'
        };
      }
      const activeRouteTerminalNodeId = activeRoute.at(-1) ?? null;
      const activeRouteTerminalSlot = activeRouteTerminalNodeId
        ? this.topLiftInboundApproachQueueSlot(activeRouteTerminalNodeId)
        : null;
      const taskLiftNodeId = task ? this.taskLiftPortNodeId(task) : null;
      if (
        task?.kind === 'inbound' &&
        !vehicle.loaded &&
        activeRoute.length >= 2 &&
        activeRouteTerminalSlot &&
        activeRouteTerminalSlot.liftNodeId === taskLiftNodeId &&
        activeRouteTerminalNodeId !== goalNodeId
      ) {
        return {
          plannedGoalNodeId: activeRouteTerminalNodeId,
          plannedRouteNodeIds: activeRoute,
          localRouteNodeIds,
          localRouteReason: localRouteNodeIds.length === 0 ? null : vehicle.localRouteReason ?? 'temporary-yield'
        };
      }
      const visiblePlannedRouteNodeIds = activeRouteDiffers && activeRoute.at(-1) === goalNodeId
        ? activeRoute
        : plannedRouteNodeIds;
      return {
        plannedGoalNodeId: goalNodeId,
        plannedRouteNodeIds: visiblePlannedRouteNodeIds,
        localRouteNodeIds,
        localRouteReason: localRouteNodeIds.length === 0 ? null : vehicle.localRouteReason ?? 'temporary-yield'
      };
    }

    if (this.agentMinimalEnabled() && activeRoute.length >= 2 && activeRoute.at(-1) === goalNodeId) {
      return {
        plannedGoalNodeId: goalNodeId,
        plannedRouteNodeIds: activeRoute,
        localRouteNodeIds: [],
        localRouteReason: null
      };
    }

    let plannedRouteNodeIds: string[] = [];
    try {
      plannedRouteNodeIds = this.agentNominalRouteToGoal(vehicle, task, goalNodeId);
    } catch {
      plannedRouteNodeIds = [vehicle.currentNodeId, goalNodeId];
    }

    const activeRouteKey = activeRoute.join('>');
    const plannedRouteKey = plannedRouteNodeIds.join('>');
    const localRouteNodeIds = activeRoute.length >= 2 && activeRouteKey !== plannedRouteKey
      ? activeRoute
      : [];
    const localRouteReason = localRouteNodeIds.length === 0
      ? null
      : localRouteNodeIds.at(-1) === goalNodeId
        ? 'temporary-reroute'
        : 'temporary-yield';

    return {
      plannedGoalNodeId: goalNodeId,
      plannedRouteNodeIds,
      localRouteNodeIds,
      localRouteReason
    };
  }

  private remainingRefreshPlannedRoute(vehicle: MutableVehicle, routeNodeIds: string[]): string[] {
    if (routeNodeIds.length === 0) {
      return [];
    }
    const currentIndex = routeNodeIds.indexOf(vehicle.currentNodeId);
    if (currentIndex >= 0) {
      return routeNodeIds.slice(currentIndex);
    }
    return [];
  }

  private publicVehicle(vehicle: MutableVehicle): VehicleState {
    const routeDiagnostics = this.vehicleRouteDiagnostics(vehicle);
    return {
      id: vehicle.id,
      state: vehicle.state,
      x: round(vehicle.x),
      y: round(vehicle.y),
      z: round(vehicle.z),
      yaw: round(vehicle.yaw),
      speedMps: round(vehicle.speedMps),
      loaded: vehicle.loaded,
      taskId: vehicle.taskId,
      targetNodeId: vehicle.targetNodeId,
      currentNodeId: vehicle.currentNodeId,
      currentEdgeId: vehicle.currentEdgeId,
      routeNodeIds: [...vehicle.routeNodeIds],
      ...routeDiagnostics,
      routeIndex: vehicle.routeIndex,
      legRemainingM: round(vehicle.legRemainingM),
      legElapsedSec: round(vehicle.legElapsedSec),
      legTravelSec: round(vehicle.legTravelSec),
      phaseRemainingSec: round(vehicle.phaseRemainingSec),
      waitReason: vehicle.waitReason,
      blockingReservationId: vehicle.blockingReservationId,
      blockingVehicleId: vehicle.blockingVehicleId,
      blockedTimeSec: round(vehicle.blockedTimeSec),
      idleTimeSec: round(vehicle.idleTimeSec),
      busyTimeSec: round(vehicle.busyTimeSec)
    };
  }

  private emptyShadowInboundDemandStatusCounts(): ShadowInboundDemandLedger['statusCounts'] {
    return {
      announced: 0,
      ready: 0,
      claimed: 0,
      completed: 0
    };
  }

  private emptyShadowInboundDemandLedger(): ShadowInboundDemandLedger {
    return {
      schemaVersion: 'shadow-inbound-demand-ledger.v1',
      entryCount: 0,
      statusCounts: this.emptyShadowInboundDemandStatusCounts(),
      stationSummaries: [],
      entries: []
    };
  }

  private shadowInboundDemandStatusForTask(
    task: TaskStateRecord,
    load: LoadStateRecord | null
  ): ShadowInboundDemandLedgerEntry['status'] | null {
    if (task.kind !== 'inbound' || task.state === 'failed' || task.state === 'completed') {
      return null;
    }
    if (
      load?.state === 'carried' ||
      load?.vehicleId !== null
    ) {
      return 'completed';
    }
    return task.state === 'queued' ? 'ready' : 'claimed';
  }

  private shadowInboundDemandLedgerEntries(): ShadowInboundDemandLedgerEntry[] {
    if (!this.topLiftColumnLayoutEnabled()) {
      return [];
    }

    const activeInboundTasks = this.tasks.filter((task) =>
      task.kind === 'inbound' &&
      (task.state === 'queued' || task.state === 'assigned' || task.state === 'in-progress')
    );
    const tasksByLoadId = new Map(activeInboundTasks.map((task) => [task.loadId, task]));
    const loadsById = new Map(this.loads.map((load) => [load.id, load]));
    const entries: ShadowInboundDemandLedgerEntry[] = [];
    const coveredLoadIds = new Set<string>();

    for (const liftNode of this.inboundLiftNodes()) {
      const stationId = liftNode.id;
      const frontSourceNodeId = this.inboundSourceFrontBufferNodeId(stationId);
      for (const load of this.inboundLiftWaitingSourceLoads(stationId)) {
        const task = tasksByLoadId.get(load.id) ?? null;
        const taskStatus = task ? this.shadowInboundDemandStatusForTask(task, load) : null;
        const status: ShadowInboundDemandLedgerEntry['status'] = taskStatus ??
          (load.nodeId === frontSourceNodeId ? 'ready' : 'announced');
        coveredLoadIds.add(load.id);
        entries.push({
          id: `load:${load.id}`,
          stationId,
          status,
          source: task ? 'source-and-task' : 'source-buffer',
          loadId: load.id,
          taskId: task?.id ?? null,
          nodeId: load.nodeId,
          loadState: load.state,
          taskState: task?.state ?? null,
          vehicleId: task?.vehicleId ?? load.vehicleId
        });
      }
    }

    for (const task of activeInboundTasks) {
      if (coveredLoadIds.has(task.loadId)) {
        continue;
      }
      const stationId = this.taskLiftPortNodeId(task);
      if (!stationId) {
        continue;
      }
      const load = loadsById.get(task.loadId) ?? null;
      const status = this.shadowInboundDemandStatusForTask(task, load);
      if (!status) {
        continue;
      }
      entries.push({
        id: `task:${task.id}`,
        stationId,
        status,
        source: 'task',
        loadId: task.loadId,
        taskId: task.id,
        nodeId: task.pickupNodeId,
        loadState: load?.state ?? null,
        taskState: task.state,
        vehicleId: task.vehicleId
      });
    }

    return entries.sort((left, right) =>
      left.stationId.localeCompare(right.stationId) ||
      this.shadowInboundDemandStatusRank(left.status) - this.shadowInboundDemandStatusRank(right.status) ||
      (left.taskId ?? '').localeCompare(right.taskId ?? '') ||
      (left.loadId ?? '').localeCompare(right.loadId ?? '') ||
      left.id.localeCompare(right.id)
    );
  }

  private shadowInboundDemandStatusRank(status: ShadowInboundDemandLedgerEntry['status']): number {
    return status === 'announced' ? 0 :
      status === 'ready' ? 1 :
      status === 'claimed' ? 2 :
      3;
  }

  private calculateShadowInboundDemandLedger(entries: ShadowInboundDemandLedgerEntry[]): ShadowInboundDemandLedger {
    const statusCounts = this.emptyShadowInboundDemandStatusCounts();
    const stationCounts = new Map<string, ShadowInboundDemandLedger['stationSummaries'][number]>();

    for (const entry of entries) {
      statusCounts[entry.status] += 1;
      const stationSummary = stationCounts.get(entry.stationId) ?? {
        stationId: entry.stationId,
        total: 0,
        statusCounts: this.emptyShadowInboundDemandStatusCounts()
      };
      stationSummary.total += 1;
      stationSummary.statusCounts[entry.status] += 1;
      stationCounts.set(entry.stationId, stationSummary);
    }

    return {
      schemaVersion: 'shadow-inbound-demand-ledger.v1',
      entryCount: entries.length,
      statusCounts,
      stationSummaries: [...stationCounts.values()].sort((left, right) => left.stationId.localeCompare(right.stationId)),
      entries: entries.slice(0, 160)
    };
  }

  private calculateShadowStationServiceTransition(
    demands: ShadowStationContractDemand[],
    vehicleCommitments: ShadowStationVehicleCommitment[]
  ): ShadowStationServiceTransition {
    const activeService = vehicleCommitments
      .filter((commitment) => commitment.kind === 'activeInboundService')
      .sort((left, right) =>
        (left.currentQueueSlot ?? 99) - (right.currentQueueSlot ?? 99) ||
        left.vehicleId.localeCompare(right.vehicleId)
      )[0] ?? null;
    const headReservation = vehicleCommitments
      .filter((commitment) => commitment.kind === 'queueReservation' && commitment.currentQueueSlot !== null)
      .sort((left, right) =>
        (left.currentQueueSlot ?? 99) - (right.currentQueueSlot ?? 99) ||
        left.vehicleId.localeCompare(right.vehicleId)
      )[0] ?? null;
    const headDemand = demands
      .filter((demand) => demand.status === 'ready' || demand.status === 'claimed')
      .sort((left, right) =>
        this.shadowInboundDemandStatusRank(left.status) - this.shadowInboundDemandStatusRank(right.status) ||
        (left.taskId ?? '').localeCompare(right.taskId ?? '') ||
        (left.loadId ?? '').localeCompare(right.loadId ?? '') ||
        left.id.localeCompare(right.id)
      )[0] ?? null;
    const readyToStartService = activeService === null && headReservation !== null && headDemand !== null;
    const gap: ShadowStationServiceTransition['gap'] = activeService
      ? 'none'
      : headReservation && headDemand
        ? 'ready-reservation-not-bound'
        : headDemand
          ? 'waiting-for-head-reservation'
          : headReservation
            ? 'waiting-for-demand'
            : 'no-ready-demand';

    return {
      mode: 'shadow',
      headReservationVehicleId: headReservation?.vehicleId ?? null,
      headReservationSlot: headReservation?.currentQueueSlot ?? null,
      headDemandId: headDemand?.id ?? null,
      headDemandStatus: headDemand?.status === 'ready' || headDemand?.status === 'claimed' ? headDemand.status : null,
      activeServiceVehicleId: activeService?.vehicleId ?? null,
      activeServiceTaskId: activeService?.taskId ?? null,
      readyToStartService,
      gap
    };
  }

  private calculateShadowStationHeadReservationSupply(
    demands: ShadowStationContractDemand[],
    vehicleCommitments: ShadowStationVehicleCommitment[],
    targetReserveDepth: number,
    nearCoveredDepth: number,
    candidateReasonCounts: Record<string, number>
  ): ShadowStationHeadReservationSupply {
    const readyDemandCount = demands.filter((demand) => demand.status === 'ready').length;
    const claimedDemandCount = demands.filter((demand) => demand.status === 'claimed').length;
    const activeServiceDepth = vehicleCommitments.filter((commitment) => commitment.kind === 'activeInboundService').length;
    const queueReservations = vehicleCommitments.filter((commitment) => commitment.kind === 'queueReservation');
    const physicalReservations = queueReservations.filter((commitment) => commitment.currentQueueSlot !== null);
    const approachingReservations = queueReservations.filter((commitment) =>
      commitment.currentQueueSlot === null && commitment.targetQueueSlot !== null
    );
    const forecastReservations = queueReservations.filter((commitment) =>
      commitment.currentQueueSlot === null &&
      commitment.targetQueueSlot === null &&
      commitment.plannedQueueSlot !== null
    );
    const physicalHeadReservation = [...physicalReservations].sort((left, right) =>
      (left.currentQueueSlot ?? 99) - (right.currentQueueSlot ?? 99) ||
      left.vehicleId.localeCompare(right.vehicleId)
    )[0] ?? null;
    const candidateBucketCounts = this.shadowStationHeadReservationCandidateBucketCounts(candidateReasonCounts);
    const dominantCandidateReason = this.shadowDominantReason(candidateReasonCounts);
    const dominantCandidateBucket = this.shadowDominantReason(candidateBucketCounts);
    const dispatchableReserveCandidateCount = candidateReasonCounts['dispatchable-reserve'] ?? 0;
    const hasReadyOrClaimedDemand = readyDemandCount + claimedDemandCount > 0;
    const gap: ShadowStationHeadReservationSupply['gap'] = !hasReadyOrClaimedDemand
      ? 'no-ready-demand'
      : activeServiceDepth > 0
        ? 'active-service-present'
        : physicalHeadReservation
          ? 'head-reservation-present'
          : approachingReservations.length + forecastReservations.length > 0
            ? 'reserve-in-transit'
            : dispatchableReserveCandidateCount > 0
              ? 'dispatchable-candidate-available'
              : dominantCandidateBucket === 'busy'
                ? 'fleet-busy'
                : dominantCandidateBucket === 'routeInfeasible'
                  ? 'route-infeasible'
                  : dominantCandidateBucket === 'held'
                    ? 'held-by-assignment'
                    : dominantCandidateBucket === 'noTarget'
                      ? 'no-open-station-target'
                      : 'unknown';

    return {
      mode: 'shadow',
      gap,
      readyDemandCount,
      claimedDemandCount,
      targetReserveDepth,
      nearCoveredDepth,
      physicalHeadReservationVehicleId: physicalHeadReservation?.vehicleId ?? null,
      physicalHeadReservationSlot: physicalHeadReservation?.currentQueueSlot ?? null,
      physicalReservationCount: physicalReservations.length,
      approachingReservationCount: approachingReservations.length,
      forecastReservationCount: forecastReservations.length,
      dispatchableReserveCandidateCount,
      dominantCandidateReason,
      candidateBucketCounts,
      candidateReasonCounts
    };
  }

  private shadowStationHeadReservationCandidateBucketCounts(
    candidateReasonCounts: Record<string, number>
  ): ShadowStationHeadReservationSupply['candidateBucketCounts'] {
    const knownReasons = new Set([
      'dispatchable-reserve',
      'busy-task',
      'busy-loaded',
      'busy-moving',
      'no-station-route',
      'route-origin-disallowed',
      'assignment-hold',
      'inbound-dropoff-standby-hold',
      'standby-reroute-not-allowed',
      'no-open-station-target'
    ]);
    const sum = (...reasons: string[]): number =>
      reasons.reduce((total, reason) => total + (candidateReasonCounts[reason] ?? 0), 0);
    const knownCount = [...knownReasons].reduce((total, reason) => total + (candidateReasonCounts[reason] ?? 0), 0);
    const totalCount = Object.values(candidateReasonCounts).reduce((total, count) => total + count, 0);
    return {
      dispatchable: candidateReasonCounts['dispatchable-reserve'] ?? 0,
      busy: sum('busy-task', 'busy-loaded', 'busy-moving'),
      routeInfeasible: sum('no-station-route', 'route-origin-disallowed'),
      held: sum('assignment-hold', 'inbound-dropoff-standby-hold', 'standby-reroute-not-allowed'),
      noTarget: candidateReasonCounts['no-open-station-target'] ?? 0,
      unavailable: Math.max(0, totalCount - knownCount)
    };
  }

  private shadowDominantReason<T extends string>(counts: Record<T, number>): T | null {
    return Object.entries(counts)
      .filter((entry): entry is [T, number] => typeof entry[0] === 'string' && Number(entry[1]) > 0)
      .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))[0]?.[0] ?? null;
  }

  private calculateShadowStationContractDiagnostics(): ShadowStationContracts {
    type CountKey = Exclude<keyof ShadowStationContractInvariantCounts, 'total'>;

    const invariantCounts: ShadowStationContractInvariantCounts = {
      demandWithoutCoverage: 0,
      queueReservationOverTarget: 0,
      physicalDepthOverTarget: 0,
      activeServiceWithoutDemand: 0,
      duplicateVehicleCommitment: 0,
      duplicateRouteLease: 0,
      total: 0
    };
    const violations: ShadowStationContractViolation[] = [];
    const addViolation = (
      countKey: CountKey,
      violation: ShadowStationContractViolation
    ): void => {
      invariantCounts[countKey] += 1;
      if (violations.length < 50) {
        violations.push(violation);
      }
    };

    if (!this.topLiftColumnLayoutEnabled()) {
      return {
        schemaVersion: 'shadow-station-contracts.v1',
        enabled: false,
        stationCount: 0,
        invariantCounts,
        stations: [],
        inboundDemandLedger: this.emptyShadowInboundDemandLedger(),
        violations: []
      };
    }

    const inboundDemandLedgerEntries = this.shadowInboundDemandLedgerEntries();
    const inboundDemandLedger = this.calculateShadowInboundDemandLedger(inboundDemandLedgerEntries);
    const commitmentStationIdsByVehicle = new Map<string, Set<string>>();
    const stationSnapshots: ShadowStationContractSnapshot[] = this.inboundLiftNodes().map((liftNode) => {
      const stationId = liftNode.id;
      const sourceLoads = this.inboundLiftWaitingSourceLoads(stationId);
      const demands = inboundDemandLedgerEntries
        .filter((entry) => entry.stationId === stationId && entry.status !== 'completed')
        .map((entry): ShadowStationContractDemand => ({
          id: entry.id,
          kind: entry.source === 'task' ? 'inbound-task' : 'source-load',
          status: entry.status,
          stationId,
          loadId: entry.loadId,
          taskId: entry.taskId,
          nodeId: entry.nodeId
        }))
        .sort((left, right) =>
          this.shadowInboundDemandStatusRank(left.status) - this.shadowInboundDemandStatusRank(right.status) ||
          (left.taskId ?? '').localeCompare(right.taskId ?? '') ||
          (left.loadId ?? '').localeCompare(right.loadId ?? '') ||
          left.id.localeCompare(right.id)
        );

      const vehicleCommitments: ShadowStationVehicleCommitment[] = [];
      const routeLeases: ShadowStationRouteLease[] = [];
      const physicalQueueOccupants = new Set<string>();
      for (const vehicle of this.vehicles) {
        const currentSlot = this.topLiftInboundApproachQueueSlot(vehicle.currentNodeId);
        const targetSlot = this.topLiftInboundApproachQueueSlot(vehicle.targetNodeId ?? '');
        const plannedSlot = this.topLiftInboundApproachQueueSlot(vehicle.plannedGoalNodeId ?? '');
        const currentQueueSlot = currentSlot?.liftNodeId === stationId ? currentSlot.slotIndex : null;
        const targetQueueSlot = targetSlot?.liftNodeId === stationId ? targetSlot.slotIndex : null;
        const plannedQueueSlot = plannedSlot?.liftNodeId === stationId ? plannedSlot.slotIndex : null;
        if (currentQueueSlot !== null) {
          physicalQueueOccupants.add(vehicle.id);
        }

        const task = this.taskForVehicle(vehicle);
        const inboundTaskAtStation =
          task?.kind === 'inbound' &&
          this.taskLiftPortNodeId(task) === stationId &&
          (task.state === 'assigned' || task.state === 'in-progress') &&
          !vehicle.loaded &&
          (
            this.topLiftInboundVehicleContributesQueueCoverage(vehicle, stationId) ||
            vehicle.currentNodeId === task.pickupNodeId ||
            vehicle.targetNodeId === task.pickupNodeId ||
            vehicle.plannedGoalNodeId === task.pickupNodeId
          );
        const activeInboundService =
          inboundTaskAtStation;
        const queueReservation =
          !activeInboundService &&
          !vehicle.loaded &&
          vehicle.taskId === null &&
          vehicle.localRouteReason === 'inbound-queue-standby' &&
          (currentQueueSlot !== null || targetQueueSlot !== null || plannedQueueSlot !== null);
        if (!activeInboundService && !queueReservation) {
          continue;
        }

        const routeNodeIds = [
          vehicle.currentNodeId,
          vehicle.targetNodeId,
          vehicle.plannedGoalNodeId,
          ...vehicle.routeNodeIds,
          ...vehicle.plannedRouteNodeIds,
          ...vehicle.localRouteNodeIds
        ].filter((nodeId): nodeId is string => Boolean(nodeId));
        const routeLeavesTopLevel = routeNodeIds.some((nodeId) => {
          if (this.isStorageNode(nodeId)) {
            return true;
          }
          const level = topLiftAisleLevel(nodeId);
          return level === 'middle' || level === 'bottom-a' || level === 'bottom-b';
        });
        const phase: ShadowStationVehicleCommitment['phase'] = activeInboundService
          ? 'service'
          : currentQueueSlot !== null
            ? 'parked'
            : 'approaching';
        vehicleCommitments.push({
          vehicleId: vehicle.id,
          kind: activeInboundService ? 'activeInboundService' : 'queueReservation',
          stationId,
          phase,
          taskId: task?.id ?? null,
          loadId: task?.loadId ?? null,
          currentNodeId: vehicle.currentNodeId,
          targetNodeId: vehicle.targetNodeId,
          plannedGoalNodeId: vehicle.plannedGoalNodeId,
          currentQueueSlot,
          targetQueueSlot,
          plannedQueueSlot,
          routeLeavesTopLevel
        });

        const leaseBase = {
          stationId,
          vehicleId: vehicle.id,
          taskId: task?.id ?? null,
          loadId: task?.loadId ?? null
        };
        if (currentQueueSlot !== null) {
          routeLeases.push({
            ...leaseBase,
            kind: 'physicalQueueSlot',
            phase: 'occupied',
            resourceKey: `station:${stationId}:queue-slot:${currentQueueSlot}`,
            nodeId: vehicle.currentNodeId,
            slotIndex: currentQueueSlot,
            routeNodeIds: []
          });
        } else if (targetQueueSlot !== null) {
          routeLeases.push({
            ...leaseBase,
            kind: 'queueSlotLease',
            phase: 'targeted',
            resourceKey: `station:${stationId}:queue-slot:${targetQueueSlot}`,
            nodeId: vehicle.targetNodeId,
            slotIndex: targetQueueSlot,
            routeNodeIds: []
          });
        } else if (plannedQueueSlot !== null) {
          routeLeases.push({
            ...leaseBase,
            kind: 'queueSlotLease',
            phase: 'planned',
            resourceKey: `station:${stationId}:queue-slot:${plannedQueueSlot}`,
            nodeId: vehicle.plannedGoalNodeId,
            slotIndex: plannedQueueSlot,
            routeNodeIds: []
          });
        }

        if (activeInboundService) {
          const approachNodeIds = this.shadowStationApproachSegmentRouteNodeIds(vehicle, stationId);
          for (const nodeId of approachNodeIds.slice(1)) {
            routeLeases.push({
              ...leaseBase,
              kind: 'approachSegmentLease',
              phase: 'approaching',
              resourceKey: `node:${nodeId}`,
              nodeId,
              slotIndex: null,
              routeNodeIds: approachNodeIds
            });
          }
        }

        const stations = commitmentStationIdsByVehicle.get(vehicle.id) ?? new Set<string>();
        stations.add(stationId);
        commitmentStationIdsByVehicle.set(vehicle.id, stations);
      }

      vehicleCommitments.sort((left, right) =>
        left.kind.localeCompare(right.kind) ||
        (left.currentQueueSlot ?? 99) - (right.currentQueueSlot ?? 99) ||
        (left.plannedQueueSlot ?? 99) - (right.plannedQueueSlot ?? 99) ||
        left.vehicleId.localeCompare(right.vehicleId)
      );
      routeLeases.sort((left, right) =>
        left.resourceKey.localeCompare(right.resourceKey) ||
        left.kind.localeCompare(right.kind) ||
        left.vehicleId.localeCompare(right.vehicleId)
      );

      const targetDepth = this.topLiftInboundQueueReplenishTargetDepth(stationId);
      const nearCoveredDepth = this.topLiftInboundQueueCoveredDepth(stationId);
      const queueReservationCount = vehicleCommitments.filter((commitment) => commitment.kind === 'queueReservation').length;
      const activeServiceDepth = vehicleCommitments.filter((commitment) => commitment.kind === 'activeInboundService').length;
      const activeAssignmentQueueLeaseCount = vehicleCommitments.filter((commitment) =>
        commitment.kind === 'activeInboundService' &&
        (
          commitment.currentQueueSlot !== null ||
          commitment.targetQueueSlot !== null ||
          commitment.plannedQueueSlot !== null
        )
      ).length;
      const tasklessStandbySoftReserveCount = queueReservationCount;
      const physicalQueueSlotLeaseCount = routeLeases.filter((lease) => lease.kind === 'physicalQueueSlot').length;
      const farForecastDepth = vehicleCommitments.filter((commitment) =>
        commitment.plannedQueueSlot !== null &&
        commitment.currentQueueSlot === null &&
        commitment.targetQueueSlot === null &&
        commitment.routeLeavesTopLevel
      ).length;
      const readyDemandCount = demands.filter((demand) => demand.status === 'ready').length;
      const claimedDemandCount = demands.filter((demand) => demand.status === 'claimed').length;
      const physicalDepth = physicalQueueOccupants.size;
      const targetReserveDepth = Math.min(targetDepth, readyDemandCount);
      const queueCoverageGap = Math.max(0, targetReserveDepth - nearCoveredDepth);
      const activeServiceGap = Math.max(0, readyDemandCount - activeServiceDepth);
      const candidateReasonCounts = readyDemandCount + claimedDemandCount > 0
        ? this.shadowStationCoordinatorCandidateReasonCounts(stationId)
        : {};
      const dispatchableReserveCandidateCount = candidateReasonCounts['dispatchable-reserve'] ?? 0;
      const eligibleTasklessVehicleCount = Object.entries(candidateReasonCounts)
        .filter(([reason]) =>
          reason === 'dispatchable-reserve' ||
          reason === 'no-open-station-target' ||
          reason === 'no-station-route' ||
          reason === 'route-origin-disallowed'
        )
        .reduce((sum, [, count]) => sum + count, 0);
      const coordinatorDecision = readyDemandCount === 0
        ? 'no-ready-demand'
        : queueCoverageGap > 0
          ? dispatchableReserveCandidateCount > 0
            ? 'pull-queue-reserve'
            : 'wait-for-reserve-candidate'
          : activeServiceDepth > 0
            ? 'hold-active-service'
            : 'match-head-reservation';
      const serviceTransition = this.calculateShadowStationServiceTransition(demands, vehicleCommitments);
      const headReservationSupply = this.calculateShadowStationHeadReservationSupply(
        demands,
        vehicleCommitments,
        targetReserveDepth,
        nearCoveredDepth,
        candidateReasonCounts
      );

      if (readyDemandCount > 0 && nearCoveredDepth === 0) {
        addViolation('demandWithoutCoverage', {
          code: 'station-demand-without-near-coverage',
          severity: 'watch',
          stationId,
          vehicleId: null,
          detail: `${stationId} has ${readyDemandCount} ready inbound demand(s) but nearCoveredDepth=0.`
        });
      }
      if (queueReservationCount > targetDepth) {
        addViolation('queueReservationOverTarget', {
          code: 'station-queue-reservation-over-target',
          severity: 'watch',
          stationId,
          vehicleId: null,
          detail: `${stationId} has ${queueReservationCount} queue reservations for targetDepth=${targetDepth}.`
        });
      }
      if (targetDepth > 0 && physicalDepth > targetDepth) {
        addViolation('physicalDepthOverTarget', {
          code: 'station-physical-depth-over-target',
          severity: 'warn',
          stationId,
          vehicleId: null,
          detail: `${stationId} has ${physicalDepth} physical queue occupants for targetDepth=${targetDepth}.`
        });
      }
      if (activeServiceDepth > 0 && demands.length === 0) {
        addViolation('activeServiceWithoutDemand', {
          code: 'station-active-service-without-demand',
          severity: 'warn',
          stationId,
          vehicleId: vehicleCommitments.find((commitment) => commitment.kind === 'activeInboundService')?.vehicleId ?? null,
          detail: `${stationId} has ${activeServiceDepth} active inbound service vehicle(s), but no matching demand entry.`
        });
      }

      return {
        stationId,
        kind: 'inbound',
        demandCount: demands.length,
        readyDemandCount,
        claimedDemandCount,
        sourceBufferOccupancy: sourceLoads.length,
        sourceBufferCapacity: this.inboundSourceBufferCapacity(stationId),
        targetDepth,
        physicalDepth,
        nearCoveredDepth,
        farForecastDepth,
        queueReservationCount,
        activeServiceDepth,
        activeAssignmentQueueLeaseCount,
        tasklessStandbySoftReserveCount,
        physicalQueueSlotLeaseCount,
        routeLeaseCount: routeLeases.length,
        coordinator: {
          mode: 'shadow',
          decision: coordinatorDecision,
          targetReserveDepth,
          queueCoverageGap,
          activeServiceGap,
          stationNeedsReservation: queueCoverageGap > 0,
          eligibleTasklessVehicleCount,
          dispatchableReserveCandidateCount,
          candidateReasonCounts
        },
        serviceTransition,
        headReservationSupply,
        demands: demands.slice(0, 12),
        vehicleCommitments: vehicleCommitments.slice(0, 12),
        routeLeases
      };
    });

    for (const station of stationSnapshots) {
      const leasesByResource = new Map<string, ShadowStationRouteLease[]>();
      for (const lease of station.routeLeases) {
        const resourceLeases = leasesByResource.get(lease.resourceKey) ?? [];
        resourceLeases.push(lease);
        leasesByResource.set(lease.resourceKey, resourceLeases);
      }
      for (const [resourceKey, resourceLeases] of leasesByResource.entries()) {
        const owners = [...new Set(resourceLeases.map((lease) => lease.vehicleId))];
        if (owners.length <= 1) {
          continue;
        }
        addViolation('duplicateRouteLease', {
          code: 'station-duplicate-route-lease',
          severity: 'watch',
          stationId: station.stationId,
          vehicleId: owners[0] ?? null,
          detail: `${station.stationId} has ${owners.length} station route lease owners on ${resourceKey}: ${owners.join(', ')}.`
        });
      }
    }

    for (const [vehicleId, stationIds] of commitmentStationIdsByVehicle.entries()) {
      if (stationIds.size <= 1) {
        continue;
      }
      addViolation('duplicateVehicleCommitment', {
        code: 'station-duplicate-vehicle-commitment',
        severity: 'critical',
        stationId: null,
        vehicleId,
        detail: `${vehicleId} has shadow station commitments for ${[...stationIds].sort().join(', ')}.`
      });
    }

    invariantCounts.total =
      invariantCounts.demandWithoutCoverage +
      invariantCounts.queueReservationOverTarget +
      invariantCounts.physicalDepthOverTarget +
      invariantCounts.activeServiceWithoutDemand +
      invariantCounts.duplicateVehicleCommitment +
      invariantCounts.duplicateRouteLease;

    return {
      schemaVersion: 'shadow-station-contracts.v1',
      enabled: true,
      stationCount: stationSnapshots.length,
      invariantCounts,
      stations: stationSnapshots,
      inboundDemandLedger,
      violations
    };
  }

  private shadowStationApproachSegmentRouteNodeIds(vehicle: MutableVehicle, stationId: string): string[] {
    if (vehicle.plannedRouteNodeIds.length < 2) {
      return [];
    }
    const routeTail = this.vehicleRouteTail(vehicle, vehicle.plannedRouteNodeIds);
    if (!this.topLiftRemoteInboundActiveServiceRouteShouldStageClaims(vehicle, routeTail)) {
      return [];
    }
    const claimTail = this.shadowPlannedRouteClaimTail(vehicle);
    if (claimTail.length < 2) {
      return [];
    }
    const stationEntryIndex = claimTail.findIndex((nodeId, index) =>
      index > 0 && this.topLiftInboundApproachQueueSlot(nodeId)?.liftNodeId === stationId
    );
    return stationEntryIndex >= 1 ? claimTail.slice(0, stationEntryIndex + 1) : claimTail;
  }

  private calculateShadowResourceLedgerDiagnostics(): ShuttleSimState['traffic']['shadowLedger'] {
    type CountKey = Exclude<keyof ShadowLedgerInvariantCounts, 'total'>;

    const leases: ShadowResourceLease[] = [];
    const violations: ShadowLedgerViolation[] = [];
    const invariantCounts: ShadowLedgerInvariantCounts = {
      staleLocalRouteClaim: 0,
      blockedWaiterFutureClaim: 0,
      orphanedYieldHold: 0,
      reservationOwnerMismatch: 0,
      duplicateResourceOwner: 0,
      conflictSessionMismatch: 0,
      liftFifoInversion: 0,
      columnModeConflict: 0,
      total: 0
    };
    const addViolation = (
      countKey: CountKey,
      violation: Omit<ShadowLedgerViolation, 'otherVehicleId'> & { otherVehicleId?: string | null }
    ): void => {
      invariantCounts[countKey] += 1;
      if (violations.length < 50) {
        violations.push({
          otherVehicleId: null,
          ...violation
        });
      }
    };
    const addLease = (lease: ShadowResourceLease): void => {
      leases.push(lease);
    };
    const vehiclesById = new Map(this.vehicles.map((vehicle) => [vehicle.id, vehicle]));
    const activeSessions = this.conflictSessions.filter((session) => session.state !== 'cleared' && session.state !== 'timed-out');

    for (const [nodeId, vehicleId] of this.currentNodeOccupancy.entries()) {
      const vehicle = vehiclesById.get(vehicleId) ?? null;
      addLease({
        resourceKey: `node:${nodeId}`,
        kind: 'current-occupancy',
        vehicleId,
        taskId: vehicle?.taskId ?? null,
        source: 'currentNodeOccupancy'
      });
      if (!vehicle || vehicle.currentNodeId !== nodeId) {
        addViolation('reservationOwnerMismatch', {
          code: 'current-occupancy-mismatch',
          severity: 'warn',
          resourceKey: `node:${nodeId}`,
          vehicleId,
          detail: vehicle
            ? `Occupancy says ${vehicleId} is at ${nodeId}, but vehicle.currentNodeId=${vehicle.currentNodeId}.`
            : `Occupancy references missing vehicle ${vehicleId}.`
        });
      }
    }

    for (const reservation of this.reservations) {
      if (reservation.endTimeSec < this.simTimeSec - 1e-6) {
        continue;
      }
      const vehicle = vehiclesById.get(reservation.vehicleId) ?? null;
      addLease({
        resourceKey: `${reservation.resourceType}:${reservation.resourceId}`,
        kind: 'reservation',
        vehicleId: reservation.vehicleId,
        taskId: reservation.taskId,
        source: reservation.reasonCode
      });
      if (!vehicle || (reservation.taskId !== null && reservation.taskId !== vehicle.taskId)) {
        addViolation('reservationOwnerMismatch', {
          code: 'reservation-owner-mismatch',
          severity: 'warn',
          resourceKey: `${reservation.resourceType}:${reservation.resourceId}`,
          vehicleId: reservation.vehicleId,
          detail: vehicle
            ? `Reservation ${reservation.id} taskId=${reservation.taskId} but vehicle.taskId=${vehicle.taskId}.`
            : `Reservation ${reservation.id} references missing vehicle ${reservation.vehicleId}.`
        });
      }
    }

    for (const vehicle of this.vehicles) {
      const claimAllowed = this.vehicleFutureClaimsEnabled(vehicle);
      if (claimAllowed && vehicle.targetNodeId && vehicle.targetNodeId !== vehicle.currentNodeId) {
        addLease({
          resourceKey: `node:${vehicle.targetNodeId}`,
          kind: 'target-claim',
          vehicleId: vehicle.id,
          taskId: vehicle.taskId,
          source: 'targetNodeId'
        });
      }

      if (claimAllowed && vehicle.state !== 'waiting-blocked') {
        for (const nodeId of this.shadowPlannedRouteClaimTail(vehicle).slice(1, 9)) {
          addLease({
            resourceKey: `node:${nodeId}`,
            kind: 'planned-route-claim',
            vehicleId: vehicle.id,
            taskId: vehicle.taskId,
            source: 'plannedRouteNodeIds'
          });
        }
        for (const nodeId of this.activeLocalRouteClaimTail(vehicle).slice(1, 9)) {
          addLease({
            resourceKey: `node:${nodeId}`,
            kind: 'local-route-claim',
            vehicleId: vehicle.id,
            taskId: vehicle.taskId,
            source: vehicle.localRouteReason ?? 'localRouteNodeIds'
          });
        }
      }

      if (
        vehicle.localRouteReason &&
        vehicle.localRouteNodeIds.length >= 2 &&
        this.activeLocalRouteClaimTail(vehicle).length < 2
      ) {
        addViolation('staleLocalRouteClaim', {
          code: 'stale-local-route-claim',
          severity: 'warn',
          resourceKey: vehicle.localRouteNodeIds.at(-1) ? `node:${vehicle.localRouteNodeIds.at(-1)}` : null,
          vehicleId: vehicle.id,
          detail: `${vehicle.id} keeps localRouteReason=${vehicle.localRouteReason}, but the local route is no longer aligned with its active route or hold.`
        });
      }

      if (vehicle.state === 'waiting-blocked') {
        const leakedFutureLeases = leases.filter((lease) =>
          lease.vehicleId === vehicle.id &&
          lease.kind !== 'current-occupancy' &&
          lease.resourceKey !== `node:${vehicle.currentNodeId}`
        );
        if (leakedFutureLeases.length > 0) {
          addViolation('blockedWaiterFutureClaim', {
            code: 'blocked-waiter-future-claim',
            severity: 'warn',
            resourceKey: leakedFutureLeases.slice(0, 3).map((lease) => lease.resourceKey).join(','),
            vehicleId: vehicle.id,
            otherVehicleId: vehicle.blockingVehicleId,
            detail: `${vehicle.id} is waiting-blocked but still owns future leases: ${leakedFutureLeases.slice(0, 6).map((lease) => `${lease.kind}:${lease.resourceKey}`).join('>')}.`
          });
        }
      }

      const activeYieldHold =
        vehicle.yieldHoldUntilSec !== null &&
        this.simTimeSec < vehicle.yieldHoldUntilSec;
      if (activeYieldHold && !this.activeYieldingConflictSessionForVehicle(vehicle.id)) {
        addViolation('orphanedYieldHold', {
          code: 'orphaned-yield-hold',
          severity: 'watch',
          resourceKey: vehicle.yieldHoldNodeId ? `node:${vehicle.yieldHoldNodeId}` : null,
          vehicleId: vehicle.id,
          detail: `${vehicle.id} has yieldHoldUntilSec=${round(vehicle.yieldHoldUntilSec ?? 0)} without an active yielding conflict session.`
        });
      }
    }

    const leasesByResource = new Map<string, ShadowResourceLease[]>();
    for (const lease of leases) {
      const group = leasesByResource.get(lease.resourceKey) ?? [];
      group.push(lease);
      leasesByResource.set(lease.resourceKey, group);
    }
    for (const [resourceKey, resourceLeases] of leasesByResource.entries()) {
      const owners = [...new Set(resourceLeases.map((lease) => lease.vehicleId))];
      if (owners.length > 1) {
        addViolation('duplicateResourceOwner', {
          code: 'duplicate-resource-owner',
          severity: 'watch',
          resourceKey,
          vehicleId: owners[0] ?? null,
          otherVehicleId: owners[1] ?? null,
          detail: `${resourceKey} has ${owners.length} shadow owners: ${owners.join(', ')} via ${resourceLeases.map((lease) => lease.source).join(', ')}.`
        });
      }
    }

    for (const session of activeSessions) {
      const winner = vehiclesById.get(session.winnerVehicleId) ?? null;
      const yielder = vehiclesById.get(session.yielderVehicleId) ?? null;
      if (!winner || !yielder) {
        addViolation('conflictSessionMismatch', {
          code: 'conflict-session-missing-participant',
          severity: 'critical',
          resourceKey: session.resourceKey,
          vehicleId: session.yielderVehicleId,
          otherVehicleId: session.winnerVehicleId,
          detail: `Conflict session ${session.id} references a missing winner or yielder.`
        });
        continue;
      }
      const yielderHasActiveRouteOrHold =
        this.activeLocalRouteClaimTail(yielder).length >= 2 ||
        (yielder.yieldHoldUntilSec !== null && this.simTimeSec < yielder.yieldHoldUntilSec);
      if ((session.state === 'yielding' || session.state === 'holding-pocket') && !yielderHasActiveRouteOrHold) {
        addViolation('conflictSessionMismatch', {
          code: 'conflict-session-without-yield-hold',
          severity: 'watch',
          resourceKey: session.resourceKey,
          vehicleId: yielder.id,
          otherVehicleId: winner.id,
          detail: `Conflict session ${session.id} is ${session.state}, but ${yielder.id} has no active local route or yield hold.`
        });
      }
    }

    const tasksByLift = new Map<string, TaskStateRecord[]>();
    for (const task of this.tasks.filter((candidate) => candidate.state === 'queued' || candidate.state === 'assigned' || candidate.state === 'in-progress')) {
      const liftNodeId = this.taskLiftPortNodeId(task);
      if (!liftNodeId) {
        continue;
      }
      const key = `${task.kind}:${liftNodeId}`;
      const group = tasksByLift.get(key) ?? [];
      group.push(task);
      tasksByLift.set(key, group);
    }
    for (const [key, tasks] of tasksByLift.entries()) {
      const ordered = [...tasks].sort((left, right) => left.createdAtSec - right.createdAtSec || left.id.localeCompare(right.id));
      for (let leftIndex = 0; leftIndex < ordered.length; leftIndex += 1) {
        const older = ordered[leftIndex]!;
        if (older.state !== 'queued') {
          continue;
        }
        const youngerActive = ordered.slice(leftIndex + 1).find((task) => task.state === 'assigned' || task.state === 'in-progress');
        if (youngerActive) {
          addViolation('liftFifoInversion', {
            code: 'lift-fifo-inversion',
            severity: 'watch',
            resourceKey: `lift:${key}`,
            vehicleId: youngerActive.vehicleId,
            detail: `${youngerActive.id} is active while older eligible-looking task ${older.id} remains queued.`
          });
          break;
        }
      }
    }

    const columnModes = new Map<number, Set<'inbound' | 'outbound'>>();
    for (const task of this.tasks.filter((candidate) => candidate.state === 'assigned' || candidate.state === 'in-progress')) {
      const storagePosition = task.kind === 'inbound'
        ? this.storageGridPosition(task.dropoffNodeId)
        : this.storageGridPosition(task.pickupNodeId);
      if (!storagePosition) {
        continue;
      }
      const modes = columnModes.get(storagePosition.column) ?? new Set<'inbound' | 'outbound'>();
      modes.add(task.kind);
      columnModes.set(storagePosition.column, modes);
    }
    for (const [column, modes] of columnModes.entries()) {
      if (modes.size > 1) {
        addViolation('columnModeConflict', {
          code: 'column-mode-conflict',
          severity: 'warn',
          resourceKey: `column:${column}`,
          vehicleId: null,
          detail: `Column ${column} has simultaneous active inbound and outbound task ownership.`
        });
      }
    }

    invariantCounts.total =
      invariantCounts.staleLocalRouteClaim +
      invariantCounts.blockedWaiterFutureClaim +
      invariantCounts.orphanedYieldHold +
      invariantCounts.reservationOwnerMismatch +
      invariantCounts.duplicateResourceOwner +
      invariantCounts.conflictSessionMismatch +
      invariantCounts.liftFifoInversion +
      invariantCounts.columnModeConflict;

    return {
      schemaVersion: 'shadow-resource-ledger.v1',
      enabled: true,
      leaseCount: leases.length,
      currentOccupancyLeaseCount: leases.filter((lease) => lease.kind === 'current-occupancy').length,
      reservationLeaseCount: leases.filter((lease) => lease.kind === 'reservation').length,
      futureClaimLeaseCount: leases.filter((lease) =>
        lease.kind === 'target-claim' ||
        lease.kind === 'planned-route-claim' ||
        lease.kind === 'local-route-claim'
      ).length,
      invariantCounts,
      violations,
      stationContracts: this.calculateShadowStationContractDiagnostics()
    };
  }

  private calculateTrafficDiagnostics(): ShuttleSimState['traffic'] {
    const waitingVehicles = this.vehicles
      .filter((vehicle) => vehicle.state === 'waiting-blocked')
      .map((vehicle) => ({
        vehicleId: vehicle.id,
        currentNodeId: vehicle.currentNodeId,
        targetNodeId: vehicle.targetNodeId,
        waitReason: vehicle.waitReason,
        blockedTimeSec: round(vehicle.blockedTimeSec),
        waitingSinceSec: vehicle.waitingSinceSec,
        blockingReservationId: vehicle.blockingReservationId,
        blockingVehicleId: vehicle.blockingVehicleId
      }));
    const deadlockCandidateVehicleIds = this.deadlockCandidateVehicleIds();
    let minVehicleSeparationM: number | null = null;
    let physicalViolationCount = 0;
    for (const vehicle of this.vehicles) {
      if (![vehicle.x, vehicle.y, vehicle.z, vehicle.yaw, vehicle.speedMps].every(Number.isFinite)) {
        physicalViolationCount += 1;
      }
      const edge = vehicle.currentEdgeId ? this.scenario.layout.edges.find((candidate) => candidate.id === vehicle.currentEdgeId) : null;
      const speedLimitMps = edge
        ? this.speedForEdge(vehicle, edge)
        : vehicle.loaded
          ? this.scenario.physicsParams.loadedSpeedMps
          : this.scenario.physicsParams.emptySpeedMps;
      if (vehicle.speedMps > speedLimitMps + 1e-6) {
        physicalViolationCount += 1;
      }
    }

    for (let leftIndex = 0; leftIndex < this.vehicles.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < this.vehicles.length; rightIndex += 1) {
        const left = this.vehicles[leftIndex]!;
        const right = this.vehicles[rightIndex]!;
        const separationM = Math.hypot(left.x - right.x, left.z - right.z);
        minVehicleSeparationM = minVehicleSeparationM === null ? separationM : Math.min(minVehicleSeparationM, separationM);
        if (vehicleFootprintsOverlap(left, right, this.scenario.vehicles)) {
          physicalViolationCount += 1;
        }
      }
    }

    return {
      trafficMode: this.agentRefreshEnabled() ? 'agent-refresh' : this.agentMinimalEnabled() ? 'agent-minimal' : this.agentSimpleEnabled() ? 'agent-simple' : 'flow-debug',
      safetyValidated: false,
      collisionAvoidanceEnabled: this.collisionAvoidanceEnabled(),
      longHorizonReservationEnabled: false,
      clearThroughLookaheadEnabled: !this.agentSimpleEnabled(),
      clearThroughMaxLookaheadLegs: this.agentSimpleEnabled() ? 0 : MAX_CLEAR_THROUGH_HORIZON_LEGS,
      activeFutureGrantCount: this.reservations.filter((reservation) => reservation.startTimeSec > this.simTimeSec + 1e-6).length,
      legacyZoneHoldEnabled: false,
      activeReservationCount: this.reservations.length,
      waitingVehicles,
      conflictSessions: this.activeConflictSessions(),
      liftPorts: this.liftPortDiagnostics(),
      deadlockCandidateVehicleIds,
      shadowLedger: this.calculateShadowResourceLedgerDiagnostics(),
      minVehicleSeparationM: minVehicleSeparationM === null ? null : round(minVehicleSeparationM),
      maxObservedSpeedMps: round(Math.max(0, ...this.vehicles.map((vehicle) => vehicle.speedMps))),
      physicalViolationCount
    };
  }

  private calculateKpis(): KpiSnapshot {
    const elapsedHours = Math.max(this.simTimeSec / 3600, 1e-9);
    const completedSeededOutbound = this.completedSeededOutboundTasks();
    const completedDemandOutbound = Math.max(0, this.completedOutbound - completedSeededOutbound);
    const pphWindowSec = Math.min(300, Math.max(this.simTimeSec, this.scenario.timeStepSec));
    const windowStartSec = Math.max(0, this.simTimeSec - pphWindowSec);
    const windowCompletedInbound = this.completedTaskCountInWindow('inbound', windowStartSec);
    const windowCompletedOutbound = this.completedTaskCountInWindow('outbound', windowStartSec);
    const windowHours = Math.max((this.simTimeSec - windowStartSec) / 3600, 1e-9);
    const inboundPph = round(this.completedInbound / elapsedHours, 3);
    const outboundPph = round(this.completedOutbound / elapsedHours, 3);
    const demandOutboundPph = round(completedDemandOutbound / elapsedHours, 3);
    const activeTasks = this.activeTasks().filter((task) => task.state === 'assigned' || task.state === 'in-progress').length;
    const queuedTasks = this.queuedTasks().length;
    const vehicleUtilization = Object.fromEntries(
      this.vehicles.map((vehicle) => [vehicle.id, round(vehicle.busyTimeSec / Math.max(this.simTimeSec, 1), 4)])
    );
    const vehicleUtilizationBreakdown = Object.fromEntries(
      this.vehicles.map((vehicle) => {
        const elapsedSec = Math.max(this.simTimeSec, 1);
        const tasklessTravelSec = Math.min(vehicle.tasklessTravelTimeSec, vehicle.movingTimeSec);
        const queueReserveTravelSec = Math.min(vehicle.queueReserveTravelTimeSec, tasklessTravelSec);
        const wasteRepositionSec = Math.max(0, tasklessTravelSec - queueReserveTravelSec);
        const productiveSec = Math.max(0, vehicle.movingTimeSec - tasklessTravelSec) + vehicle.handlingTimeSec;
        return [vehicle.id, {
          busy: round(vehicle.busyTimeSec / elapsedSec, 4),
          productive: round(productiveSec / elapsedSec, 4),
          moving: round(vehicle.movingTimeSec / elapsedSec, 4),
          handling: round(vehicle.handlingTimeSec / elapsedSec, 4),
          waiting: round(vehicle.blockedTimeSec / elapsedSec, 4),
          idle: round(vehicle.idleTimeSec / elapsedSec, 4),
          tasklessTravel: round(tasklessTravelSec / elapsedSec, 4),
          queueReserveTravel: round(queueReserveTravelSec / elapsedSec, 4),
          wasteReposition: round(wasteRepositionSec / elapsedSec, 4)
        }];
      })
    );
    const blockedTimeByReasonSec = Object.fromEntries([...this.blockedTimeByReasonSec.entries()].sort(([left], [right]) => left.localeCompare(right)));

    return {
      inboundPph,
      outboundPph,
      totalPph: round((this.completedInbound + this.completedOutbound) / elapsedHours, 3),
      windowInboundPph: round(windowCompletedInbound / windowHours, 3),
      windowOutboundPph: round(windowCompletedOutbound / windowHours, 3),
      windowTotalPph: round((windowCompletedInbound + windowCompletedOutbound) / windowHours, 3),
      pphWindowSec: round(this.simTimeSec - windowStartSec),
      demandOutboundPph,
      demandTotalPph: round((this.completedInbound + completedDemandOutbound) / elapsedHours, 3),
      completedInbound: this.completedInbound,
      completedOutbound: this.completedOutbound,
      completedSeededOutbound,
      completedDemandOutbound,
      activeTasks,
      queuedTasks,
      averageTaskCycleSec: round(this.completedTaskCycleTimes.reduce((sum, value) => sum + value, 0) / Math.max(1, this.completedTaskCycleTimes.length)),
      p95TaskCycleSec: round(percentile(this.completedTaskCycleTimes, 95)),
      averageTaskWaitSec: round(this.completedTaskWaitTimes.reduce((sum, value) => sum + value, 0) / Math.max(1, this.completedTaskWaitTimes.length)),
      vehicleUtilization,
      vehicleUtilizationBreakdown,
      liftPph: this.liftPortPphByNodeId(),
      blockedTimeByReasonSec,
      reservationConflictCount: this.reservationConflictCount,
      replanCount: this.replanCount,
      deadlockCount: this.deadlockCount,
      livelockCount: this.livelockCount,
      eventLogHash: hashEventLog(this.eventLog),
      theoreticalCapacity: this.calculateTheoreticalCapacity(inboundPph, outboundPph, vehicleUtilization)
    };
  }

  private completedSeededOutboundTasks(): number {
    if (!this.topLiftColumnLayoutEnabled()) {
      return 0;
    }
    return this.tasks.filter((task) =>
      task.kind === 'outbound' &&
      task.state === 'completed' &&
      task.loadId.startsWith(OUTBOUND_SEED_LOAD_PREFIX)
    ).length;
  }

  private completedTaskCountInWindow(kind: 'inbound' | 'outbound', windowStartSec: number): number {
    return this.tasks.filter((task) =>
      task.kind === kind &&
      task.state === 'completed' &&
      task.completedAtSec !== null &&
      task.completedAtSec >= windowStartSec
    ).length;
  }

  private logEvent(
    eventType: string,
    vehicleId: string | null,
    taskId: string | null,
    loadId: string | null,
    fromNodeId: string | null,
    toNodeId: string | null,
    reason: string | null,
    position: { x: number; y: number; z: number } | null,
    details: Record<string, string | number | boolean | null>
  ): void {
    const sanitizedDetails: Record<string, string | number | boolean | null> = {};
    for (const [key, value] of Object.entries(details)) {
      sanitizedDetails[key] =
        typeof value === 'string' ||
        typeof value === 'number' ||
        typeof value === 'boolean' ||
        value === null
          ? value
          : String(value);
    }
    const entry: EventLogEntry = {
      sequence: this.eventSequence,
      timeSec: round(this.simTimeSec),
      eventType,
      vehicleId,
      taskId,
      loadId,
      fromNodeId,
      toNodeId,
      reason,
      position,
      details: sanitizedDetails
    };
    this.eventSequence += 1;
    this.eventLog.push(entry);
    this.recentEvents.push(entry);
    if (this.recentEvents.length > DEFAULT_RECENT_EVENTS) {
      this.recentEvents = this.recentEvents.slice(-DEFAULT_RECENT_EVENTS);
    }
  }
}

export type FixedStepRunManifestV1 = {
  schemaVersion: 'shuttle.fixedStepRunManifest.v1';
  scenarioId: string;
  scenarioHash: string;
  seed: number;
  commitSha: string;
  stepSec: number;
  durationSec: number;
  finalSimTimeSec: number;
  finalTickIndex: number;
  status: RuntimeStatus;
  eventLogHash: string;
  stateHash: string;
  completedInbound: number;
  completedOutbound: number;
  totalPph: number;
  inboundPph: number;
  deadlocks: number;
  livelocks: number;
  physicalViolations: number;
};

export type FixedStepRunResult = {
  manifest: FixedStepRunManifestV1;
  state: ShuttleSimState;
  snapshot: ShuttleEngineSnapshotV1;
  eventLog: EventLogEntry[];
};

export function runFixedStep(options: {
  scenario?: ShuttleScenario;
  durationSec?: number;
  stepSec?: number;
  commitSha?: string;
} = {}): FixedStepRunResult {
  const inputScenario = options.scenario ?? createDefaultShuttleScenario();
  const stepSec = Math.max(0.001, options.stepSec ?? inputScenario.timeStepSec);
  const durationSec = Math.max(0, options.durationSec ?? inputScenario.durationSec);
  const scenario = ShuttleScenarioSchema.parse({
    ...inputScenario,
    durationSec,
    timeStepSec: stepSec
  });
  const sim = new ShuttleSimCore(scenario);
  sim.start();
  while (sim.getClock().simTimeSec < durationSec - 1e-9 && sim.getClock().status === 'running') {
    sim.step(Math.min(stepSec, durationSec - sim.getClock().simTimeSec));
  }
  const state = sim.getState();
  const snapshot = sim.createSnapshot();
  const eventLog = sim.getEventLog();
  return {
    manifest: {
      schemaVersion: 'shuttle.fixedStepRunManifest.v1',
      scenarioId: scenario.id,
      scenarioHash: hashScenario(scenario),
      seed: scenario.seed,
      commitSha: options.commitSha ?? 'unknown',
      stepSec,
      durationSec,
      finalSimTimeSec: state.simTimeSec,
      finalTickIndex: snapshot.tickIndex,
      status: state.status,
      eventLogHash: snapshot.eventLogHash,
      stateHash: hashDeterministicReplayState(snapshot),
      completedInbound: state.kpis.completedInbound,
      completedOutbound: state.kpis.completedOutbound,
      totalPph: state.kpis.totalPph,
      inboundPph: state.kpis.inboundPph,
      deadlocks: state.kpis.deadlockCount,
      livelocks: state.kpis.livelockCount,
      physicalViolations: state.traffic.physicalViolationCount
    },
    state,
    snapshot,
    eventLog
  };
}

function getByPointer(root: Record<string, unknown>, pointer: string): unknown {
  const parts = pointer.split('/').slice(1).map((part) => part.replace(/~1/g, '/').replace(/~0/g, '~'));
  let cursor: unknown = root;
  for (const part of parts) {
    if (!cursor || typeof cursor !== 'object') {
      return undefined;
    }
    cursor = (cursor as Record<string, unknown>)[part];
  }
  return cursor;
}

function setByPointer(root: Record<string, unknown>, pointer: string, value: unknown): { accepted: boolean; previousValue?: unknown; reason?: string } {
  const parts = pointer.split('/').slice(1).map((part) => part.replace(/~1/g, '/').replace(/~0/g, '~'));
  if (parts.length === 0) {
    return { accepted: false, reason: 'Root replacement is not supported' };
  }

  let cursor: unknown = root;
  for (const part of parts.slice(0, -1)) {
    if (!cursor || typeof cursor !== 'object') {
      return { accepted: false, reason: `Path segment ${part} is not an object` };
    }
    cursor = (cursor as Record<string, unknown>)[part];
  }

  if (!cursor || typeof cursor !== 'object') {
    return { accepted: false, reason: 'Target parent is not an object' };
  }

  const key = parts[parts.length - 1]!;
  const parent = cursor as Record<string, unknown>;
  const previousValue = parent[key];
  parent[key] = value;
  return { accepted: true, previousValue };
}
